const DEFAULT_MODULE_KEYS = ALL_SYSTEM_MODULES.flatMap((m) => [
  m.key,
  ...(Array.isArray(m.submodules) ? m.submodules.map((s) => s.key) : [])
]);

function normalizeErpUserRole(role, username = '') {
  const uKey = String(username || '').toLowerCase();
  if (uKey === PRIMARY_ADMIN_USER || uKey === 'danielg') return 'Administrador General';
  const r = String(role || '').trim().toLowerCase();
  if (r === 'administrador general' || r === 'admin_general' || r === 'superadmin') return 'Administrador General';
  return r === 'administrador' ? 'Administrador' : 'Usuario';
}

function isErpGeneralAdminUser(userOrUsername) {
  if (!userOrUsername) return false;
  const uKey = typeof userOrUsername === 'string'
    ? userOrUsername.toLowerCase()
    : String(userOrUsername.username || '').toLowerCase();
  if (uKey === 'danielg') return true;
  const dir = ADMIN_DIRECTORY[uKey] || {};
  const role = typeof userOrUsername === 'object' && userOrUsername.role
    ? userOrUsername.role
    : dir.role;
  return normalizeErpUserRole(role, uKey) === 'Administrador General';
}

function isErpAdminUser(userOrUsername) {
  if (!userOrUsername) return false;
  const uKey = typeof userOrUsername === 'string'
    ? userOrUsername.toLowerCase()
    : String(userOrUsername.username || '').toLowerCase();
  if (uKey === PRIMARY_ADMIN_USER || uKey === 'danielg') return true;
  const dir = ADMIN_DIRECTORY[uKey] || {};
  const role = typeof userOrUsername === 'object' && userOrUsername.role
    ? userOrUsername.role
    : dir.role;
  const norm = normalizeErpUserRole(role, uKey);
  return norm === 'Administrador General' || norm === 'Administrador';
}

const LEGACY_MODULE_KEY_ALIASES = {
  'facturacion:sub_facturador': 'facturacion:facturador',
  'facturacion:sub_recibo': 'facturacion:recibo',
  'facturacion:sub_apertura': 'facturacion:apertura',
  'facturacion:sub_retiro': 'facturacion:retiro',
  'facturacion:sub_cierre': 'facturacion:cierre',
  'facturacion:sub_movil': 'facturacion:movil',
  'facturacion:emitidos': 'facturacion:comprobantes',
  'facturacion:arca_admin': 'facturacion:admin_arca',
  'articulos:padron': 'articulos:listado',
  'articulos:marcas': 'articulos:abm_marcas',
  'articulos:rubros': 'articulos:abm_rubros',
  'articulos:gondola': 'articulos:precios_gondola',
  'proveedores:gondola': 'proveedores:precios_gondola',
  'fondos:caja_tesoreria': 'fondos:caja',
  'fondos:stock_val': 'fondos:stock_valorizado',
  'carrito:registro_online': 'carrito:reg_online',
  'atajos': 'ayuda:atajos',
  'manual_usuario': 'ayuda:manual_usuario'
};

function expandUserModulesWithDefaults(rawModules) {
  if (!Array.isArray(rawModules) || rawModules.length === 0) {
    return [...DEFAULT_MODULE_KEYS];
  }
  const normalized = rawModules.map((k) => {
    const clean = String(k || '').trim();
    return LEGACY_MODULE_KEY_ALIASES[clean] || clean;
  });
  const set = new Set(normalized);
  set.add('perfil');
  set.add('ayuda');
  set.add('ayuda:manual_usuario');
  set.add('ayuda:reporte_mejoras');
  set.add('manual_usuario');
  if (set.has('ayuda:atajos')) {
    set.add('atajos');
  }
  if (set.has('carrito:banners') || set.has('carrito')) {
    set.add('carrito:ventana_emergente');
  }
  if (set.has('estadisticas') || set.has('estadisticas:facturacion')) {
    set.add('estadisticas:dashboard');
  }
  ALL_SYSTEM_MODULES.forEach((mod) => {
    if (Array.isArray(mod.submodules) && mod.submodules.length > 0) {
      const anySubChecked = mod.submodules.some((sub) => set.has(sub.key));
      if (anySubChecked) {
        set.add(mod.key);
      } else if (set.has(mod.key)) {
        mod.submodules.forEach((sub) => set.add(sub.key));
      }
    }
  });
  return Array.from(set);
}

