function getPersistedAdminSessionRaw() {
  try {
    return sessionStorage.getItem(SESSION_STORAGE_KEY) || localStorage.getItem(SESSION_STORAGE_KEY) || null;
  } catch {
    return null;
  }
}

function savePersistedAdminSession(userObj) {
  if (!userObj) return;
  try {
    const raw = JSON.stringify(userObj);
    sessionStorage.setItem(SESSION_STORAGE_KEY, raw);
    localStorage.setItem(SESSION_STORAGE_KEY, raw);
  } catch {}
}

function clearPersistedAdminSession() {
  try {
    sessionStorage.removeItem(SESSION_STORAGE_KEY);
    localStorage.removeItem(SESSION_STORAGE_KEY);
    sessionStorage.removeItem(NAV_STATE_STORAGE_KEY);
    localStorage.removeItem(NAV_STATE_STORAGE_KEY);
  } catch {}
}

function savePersistedNavState(sectionId, cajaId) {
  if (!sectionId) return;
  try {
    const payload = JSON.stringify({
      sectionId: String(sectionId),
      activeCajaId: String(cajaId || STATE.activeCajaId || 'caja1'),
      username: String(STATE.currentUser?.username || '').toLowerCase(),
      ts: Date.now()
    });
    sessionStorage.setItem(NAV_STATE_STORAGE_KEY, payload);
    localStorage.setItem(NAV_STATE_STORAGE_KEY, payload);
  } catch {}
}

function getPersistedNavState() {
  try {
    const raw = sessionStorage.getItem(NAV_STATE_STORAGE_KEY) || localStorage.getItem(NAV_STATE_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

function getUserThemePreference(username) {
  try {
    const cleanUser = String(username || '').trim().toLowerCase();
    if (cleanUser) {
      const byUser = JSON.parse(localStorage.getItem(THEME_BY_USER_STORAGE_KEY) || '{}');
      if (byUser && (byUser[cleanUser] === 'dark' || byUser[cleanUser] === 'light')) {
        return byUser[cleanUser];
      }
    }
    const def = localStorage.getItem(THEME_DEFAULT_STORAGE_KEY);
    if (def === 'dark' || def === 'light') return def;
  } catch {}
  return 'light';
}

function applyThemeMode(theme, saveForCurrentUser = true) {
  const mode = theme === 'dark' ? 'dark' : 'light';
  document.documentElement.setAttribute('data-theme', mode);

  const metaTheme = document.querySelector('meta[name="theme-color"]');
  if (metaTheme) {
    metaTheme.setAttribute('content', mode === 'dark' ? '#07080a' : '#f8f9fa');
  }

  const sunIcon = document.getElementById('theme-card-icon-sun');
  const moonIcon = document.getElementById('theme-card-icon-moon');
  if (sunIcon && moonIcon) {
    sunIcon.hidden = mode === 'dark';
    moonIcon.hidden = mode !== 'dark';
  }

  try {
    localStorage.setItem(THEME_DEFAULT_STORAGE_KEY, mode);
    if (saveForCurrentUser && STATE.currentUser && STATE.currentUser.username) {
      const cleanUser = String(STATE.currentUser.username).trim().toLowerCase();
      const byUser = JSON.parse(localStorage.getItem(THEME_BY_USER_STORAGE_KEY) || '{}');
      byUser[cleanUser] = mode;
      localStorage.setItem(THEME_BY_USER_STORAGE_KEY, JSON.stringify(byUser));
    }
  } catch {}
}

function toggleThemeMode() {
  const current = document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
  const next = current === 'dark' ? 'light' : 'dark';
  applyThemeMode(next, true);
}

/**
 * Muestra un cuadro de confirmación con la imagen corporativa de Casa Nueva / Paseo Alberdi
 * en reemplazo del diálogo nativo del navegador ("cn.com.ar dice").
 */
function showBrandConfirmDialog(rawMessage, opts = {}) {
  return new Promise((resolve) => {
    let dlg = document.getElementById('erp-brand-confirm-dialog');
    if (!dlg) {
      dlg = document.createElement('dialog');
      dlg.id = 'erp-brand-confirm-dialog';
      dlg.className = 'erp-dialog brand-confirm-dialog';
      document.body.appendChild(dlg);
    }

    const esc = (str) =>
      String(str ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');

    const logoSrc = ACTIVE_BRAND?.isMiniSistema
      ? ACTIVE_BRAND.assets?.logo1x1 || '/sistema/assets/img/minisistema/logo-1x1.png'
      : ACTIVE_BRAND?.isPaseoAlberdi
      ? ACTIVE_BRAND.assets?.logo1x1 || 'assets/img/paseo-alberdi/logo-1x1-original.jpg'
      : 'assets/img/brand-mark.jpg';
    const fallbackLogoSrc = ACTIVE_BRAND?.isMiniSistema
      ? '/sistema/assets/img/minisistema/icon-192.png'
      : 'assets/img/icon-192.png';
    const brandEyebrow = `${ACTIVE_BRAND?.upperFullName || 'CASA NUEVA SUPERMERCADO'} · SISTEMA ERP`;
    const titleText = opts.title || 'Confirmación del Sistema';
    const acceptLabel = opts.acceptLabel || '✅ Aceptar';
    const cancelLabel = opts.cancelLabel || 'Cancelar';

    const lines = String(rawMessage || '')
      .split(/\r?\n/)
      .map((l) => l.trim())
      .filter(Boolean);

    const topLines = [];
    const bulletItems = [];
    const bottomLines = [];

    lines.forEach((line) => {
      if (/^[•\-*]\s*/.test(line)) {
        const cleanBullet = line.replace(/^[•\-*]\s*/, '').trim();
        const colonIdx = cleanBullet.indexOf(':');
        if (colonIdx > 0) {
          bulletItems.push({
            label: cleanBullet.slice(0, colonIdx).trim(),
            value: cleanBullet.slice(colonIdx + 1).trim()
          });
        } else {
          bulletItems.push({ label: '', value: cleanBullet });
        }
      } else if (bulletItems.length === 0) {
        topLines.push(line);
      } else {
        bottomLines.push(line);
      }
    });

    const topHtml = topLines
      .map((l) => `<p class="brand-confirm-question">${esc(l)}</p>`)
      .join('');

    const bulletsHtml =
      bulletItems.length > 0
        ? `<div class="brand-confirm-summary-card">${bulletItems
            .map((b) =>
              b.label
                ? `<div class="brand-confirm-row">
                     <span class="brand-confirm-row-label"><span class="brand-confirm-dot">●</span> ${esc(b.label)}:</span>
                     <span class="brand-confirm-row-val">${esc(b.value)}</span>
                   </div>`
                : `<div class="brand-confirm-row">
                     <span class="brand-confirm-row-val" style="text-align:left;"><span class="brand-confirm-dot">●</span> ${esc(b.value)}</span>
                   </div>`
            )
            .join('')}</div>`
        : '';

    const bottomHtml = bottomLines
      .map((l) => `<p class="brand-confirm-note">${esc(l)}</p>`)
      .join('');

    dlg.innerHTML = `
      <header class="brand-confirm-header">
        <div class="brand-confirm-identity">
          <div class="brand-confirm-logo-box">
            <img src="${esc(logoSrc)}" alt="${esc(ACTIVE_BRAND?.fullName || 'Casa Nueva Supermercado')}" onerror="this.src='${esc(fallbackLogoSrc)}'" />
          </div>
          <div class="brand-confirm-titles">
            <span class="brand-confirm-eyebrow">${esc(brandEyebrow)}</span>
            <h3 class="brand-confirm-title">${esc(titleText)}</h3>
          </div>
        </div>
        <button type="button" class="brand-confirm-close-x" data-brand-confirm-action="cancel" aria-label="Cerrar">✕</button>
      </header>
      <div class="brand-confirm-body">
        ${topHtml}
        ${bulletsHtml}
        ${bottomHtml}
      </div>
      <footer class="brand-confirm-footer">
        ${opts.hideCancel ? '' : `<button type="button" class="btn-secondary brand-confirm-btn-cancel" data-brand-confirm-action="cancel">${esc(cancelLabel)}</button>`}
        <button type="button" class="btn-primary brand-confirm-btn-accept" data-brand-confirm-action="accept">${esc(acceptLabel)}</button>
      </footer>
    `;

    let settled = false;
    const finish = (accepted) => {
      if (settled) return;
      settled = true;
      dlg.removeEventListener('cancel', onNativeCancel);
      dlg.removeEventListener('keydown', onKeyDown);
      try {
        if (dlg.open) dlg.close();
      } catch {}
      resolve(Boolean(accepted));
    };

    const onNativeCancel = (ev) => {
      ev.preventDefault();
      finish(false);
    };

    const onKeyDown = (ev) => {
      if (ev.key === 'Escape') {
        ev.preventDefault();
        finish(false);
      } else if (ev.key === 'Enter' && document.activeElement?.getAttribute('data-brand-confirm-action') !== 'cancel') {
        ev.preventDefault();
        finish(true);
      }
    };

    dlg.addEventListener('cancel', onNativeCancel);
    dlg.addEventListener('keydown', onKeyDown);

    dlg.querySelectorAll('[data-brand-confirm-action="cancel"]').forEach((btn) => {
      btn.addEventListener('click', () => finish(false));
    });
    dlg.querySelector('[data-brand-confirm-action="accept"]')?.addEventListener('click', () => finish(true));

    try {
      if (!dlg.open) dlg.showModal();
    } catch {
      dlg.setAttribute('open', 'open');
    }
    setTimeout(() => {
      dlg.querySelector('[data-brand-confirm-action="accept"]')?.focus();
    }, 30);
  });
}
window.showBrandConfirmDialog = showBrandConfirmDialog;

function showBrandAlertDialog(rawMessage, opts = {}) {
  return showBrandConfirmDialog(rawMessage, {
    title: 'Aviso del Sistema',
    acceptLabel: '✅ Aceptar',
    hideCancel: true,
    ...opts
  });
}
window.showBrandAlertDialog = showBrandAlertDialog;
window.alert = function (msg) {
  showBrandAlertDialog(msg);
};

