const USERS_CUSTOM_STORAGE_KEY = ACTIVE_BRAND.storagePrefix + 'erp_users_custom_v1';

function loadCustomUsersIntoDirectory() {
  try {
    const raw = localStorage.getItem(USERS_CUSTOM_STORAGE_KEY);
    if (!raw) return;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return;
    Object.keys(parsed).forEach((uKey) => {
      if (!parsed[uKey] || typeof parsed[uKey] !== 'object') return;
      const p = parsed[uKey];
      if (p._deleted && uKey !== PRIMARY_ADMIN_USER) {
        delete ADMIN_DIRECTORY[uKey];
        return;
      }
      if (!ADMIN_DIRECTORY[uKey]) {
        ADMIN_DIRECTORY[uKey] = {
          username: uKey,
          pass: p.pass || '',
          name: p.name || uKey,
          vendedor: p.vendedor || uKey.toUpperCase(),
          role: normalizeErpUserRole(p.role, uKey),
          branch: p.branch || ACTIVE_BRAND.defaultBranch || 'Casa Central',
          whatsapp: p.whatsapp || '',
          avatar: p.avatar || '',
          modules: expandUserModulesWithDefaults(p.modules),
          cajaAbierta: p.cajaAbierta ?? null,
          hash: p.hash || ''
        };
        return;
      }
      if (p.name) ADMIN_DIRECTORY[uKey].name = p.name;
      if (p.vendedor) ADMIN_DIRECTORY[uKey].vendedor = p.vendedor;
      if (p.branch) ADMIN_DIRECTORY[uKey].branch = p.branch;
      if (p.role) ADMIN_DIRECTORY[uKey].role = normalizeErpUserRole(p.role, uKey);
      if (p.pass) ADMIN_DIRECTORY[uKey].pass = p.pass;
      if (p.hash) ADMIN_DIRECTORY[uKey].hash = p.hash;
      if (typeof p.whatsapp === 'string') ADMIN_DIRECTORY[uKey].whatsapp = p.whatsapp;
      if (typeof p.avatar === 'string') ADMIN_DIRECTORY[uKey].avatar = p.avatar;
      if (Array.isArray(p.modules) && uKey !== PRIMARY_ADMIN_USER) {
        ADMIN_DIRECTORY[uKey].modules = expandUserModulesWithDefaults(p.modules);
      }
      if ('cajaAbierta' in p) ADMIN_DIRECTORY[uKey].cajaAbierta = p.cajaAbierta;
    });
    if (ADMIN_DIRECTORY[PRIMARY_ADMIN_USER]) {
      ADMIN_DIRECTORY[PRIMARY_ADMIN_USER].role = 'Administrador';
      ADMIN_DIRECTORY[PRIMARY_ADMIN_USER].modules = [...DEFAULT_MODULE_KEYS];
    }
  } catch {}
}

function saveCustomUserOverride(username, patch) {
  try {
    const raw = localStorage.getItem(USERS_CUSTOM_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    const uKey = String(username || '').toLowerCase();
    if (!uKey) return;
    if (!ADMIN_DIRECTORY[uKey]) {
      ADMIN_DIRECTORY[uKey] = {
        username: uKey,
        pass: patch.pass || '',
        name: patch.name || uKey,
        vendedor: patch.vendedor || uKey.toUpperCase(),
        role: normalizeErpUserRole(patch.role, uKey),
        branch: patch.branch || ACTIVE_BRAND.defaultBranch || 'Casa Central',
        whatsapp: patch.whatsapp || '',
        avatar: patch.avatar || '',
        modules: expandUserModulesWithDefaults(patch.modules),
        cajaAbierta: null,
        hash: patch.hash || ''
      };
    }
    if (patch.role !== undefined) {
      patch.role = normalizeErpUserRole(patch.role, uKey);
    }
    if (uKey === PRIMARY_ADMIN_USER) {
      patch.role = 'Administrador';
      patch.modules = [...DEFAULT_MODULE_KEYS];
    } else if (Array.isArray(patch.modules)) {
      patch.modules = expandUserModulesWithDefaults(patch.modules);
    }
    parsed[uKey] = Object.assign({}, parsed[uKey] || {}, patch);
    delete parsed[uKey]._deleted;
    localStorage.setItem(USERS_CUSTOM_STORAGE_KEY, JSON.stringify(parsed));
    Object.assign(ADMIN_DIRECTORY[uKey], patch);
  } catch {}
}

function removeOrRenameCustomUserKey(oldKey, newKey = '') {
  try {
    const cleanOld = String(oldKey || '').toLowerCase();
    if (!cleanOld || cleanOld === PRIMARY_ADMIN_USER) return;
    delete ADMIN_DIRECTORY[cleanOld];
    const raw = localStorage.getItem(USERS_CUSTOM_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    parsed[cleanOld] = { _deleted: true, renamedTo: newKey || null };
    localStorage.setItem(USERS_CUSTOM_STORAGE_KEY, JSON.stringify(parsed));
  } catch {}
}

loadCustomUsersIntoDirectory();

async function sha256Hex(text) {
  const data = new TextEncoder().encode(text);
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  return Array.from(new Uint8Array(hashBuffer))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

async function syncUsersFromServer() {
  try {
    const res = await fetch(`api/auth.php?action=list_users&t=${Date.now()}`, { cache: 'no-store' });
    if (!res.ok) return;
    const json = await res.json();
    if (!json || !json.ok || !json.users || typeof json.users !== 'object') return;
    Object.keys(ADMIN_DIRECTORY).forEach((localKey) => {
      if (localKey !== PRIMARY_ADMIN_USER && !json.users[localKey]) {
        delete ADMIN_DIRECTORY[localKey];
      }
    });
    for (const [uKey, srv] of Object.entries(json.users)) {
      if (!srv) continue;
      if (!ADMIN_DIRECTORY[uKey]) {
        ADMIN_DIRECTORY[uKey] = {
          username: uKey,
          pass: srv.pass || '',
          name: srv.name || uKey,
          vendedor: srv.vendedor || uKey.toUpperCase(),
          role: normalizeErpUserRole(srv.role, uKey),
          branch: srv.branch || ACTIVE_BRAND.defaultBranch,
          whatsapp: srv.whatsapp || '',
          avatar: srv.avatar || '',
          modules: expandUserModulesWithDefaults(srv.modules),
          cajaAbierta: srv.cajaAbierta ?? null,
          hash: ''
        };
      }
      const newHash = srv.pass ? await sha256Hex(`cn-erp-2026:${uKey}:${srv.pass}`) : ADMIN_DIRECTORY[uKey].hash;
      saveCustomUserOverride(uKey, {
        name: srv.name || ADMIN_DIRECTORY[uKey].name,
        vendedor: srv.vendedor || ADMIN_DIRECTORY[uKey].vendedor,
        role: normalizeErpUserRole(srv.role || ADMIN_DIRECTORY[uKey].role, uKey),
        branch: srv.branch || ADMIN_DIRECTORY[uKey].branch,
        pass: srv.pass || ADMIN_DIRECTORY[uKey].pass,
        hash: newHash,
        whatsapp: srv.whatsapp ?? ADMIN_DIRECTORY[uKey].whatsapp ?? '',
        avatar: srv.avatar ?? ADMIN_DIRECTORY[uKey].avatar ?? '',
        modules: uKey === PRIMARY_ADMIN_USER
          ? [...DEFAULT_MODULE_KEYS]
          : expandUserModulesWithDefaults(Array.isArray(srv.modules) ? srv.modules : ADMIN_DIRECTORY[uKey].modules),
        cajaAbierta: srv.cajaAbierta ?? null,
        cajaAbiertaAt: srv.cajaAbiertaAt ?? null
      });
    }
    if (STATE.currentUser && STATE.currentUser.username) {
      const currKey = String(STATE.currentUser.username).toLowerCase();
      if (ADMIN_DIRECTORY[currKey]) {
        const rec = ADMIN_DIRECTORY[currKey];
        STATE.currentUser = Object.assign({}, STATE.currentUser, {
          name: rec.name,
          vendedor: rec.vendedor,
          role: normalizeErpUserRole(rec.role, currKey),
          branch: rec.branch,
          whatsapp: rec.whatsapp || '',
          avatar: rec.avatar || '',
          modules: rec.modules || [...DEFAULT_MODULE_KEYS]
        });
        savePersistedAdminSession(STATE.currentUser);
        updateTopbarUserDisplay(STATE.currentUser);
        applyUserAllowedModules(STATE.currentUser);
      }
    }
  } catch {}
}

function renderUserAvatarElement(el, nameStr, avatarUrl) {
  if (!el) return;
  const cleanAvatar = String(avatarUrl || '').trim();
  const initial = String(nameStr || 'U').trim().charAt(0).toUpperCase() || 'U';
  el.textContent = '';
  if (cleanAvatar) {
    const img = document.createElement('img');
    img.className = 'avatar-img-fill';
    img.src = cleanAvatar;
    img.alt = nameStr || 'Avatar';
    img.onerror = () => {
      el.textContent = initial;
    };
    el.appendChild(img);
  } else {
    el.textContent = initial;
  }
}

function updateTopbarUserDisplay(user) {
  if (!user) return;
  const uKey = String(user.username || '').toLowerCase();
  const dir = ADMIN_DIRECTORY[uKey] || {};
  const displayName = user.name || dir.name || 'Administrador';
  const displayRole = normalizeErpUserRole(user.role || dir.role, uKey);
  const displayAvatar = user.avatar !== undefined ? user.avatar : (dir.avatar || '');

  const nameEl = document.getElementById('user-display-name');
  const roleEl = document.getElementById('user-display-role');
  const avatarEl = document.getElementById('user-avatar-initial');
  if (nameEl) nameEl.textContent = displayName;
  const topbarRoleLabel = displayRole === 'Administrador General' ? 'Admin. Gral.' : displayRole;
  if (roleEl) roleEl.textContent = `${topbarRoleLabel} (@${uKey || user.username})`;
  renderUserAvatarElement(avatarEl, displayName, displayAvatar);
}

function getUserAllowedModules(username) {
  const uKey = String(username || STATE.currentUser?.username || '').toLowerCase();
  if (!uKey || uKey === PRIMARY_ADMIN_USER) return [...DEFAULT_MODULE_KEYS];
  const dir = ADMIN_DIRECTORY[uKey];
  if (dir && Array.isArray(dir.modules) && dir.modules.length > 0) {
    const expanded = expandUserModulesWithDefaults(dir.modules);
    const mods = new Set([...expanded, 'perfil', 'ayuda', 'ayuda:manual_usuario', 'ayuda:reporte_mejoras', 'manual_usuario']);
    return Array.from(mods);
  }
  return [...DEFAULT_MODULE_KEYS];
}

function applyUserAllowedModules(user) {
  const uKey = String(user?.username || STATE.currentUser?.username || '').toLowerCase();
  const isPrimary = uKey === PRIMARY_ADMIN_USER;
  const isGenAdmin = isPrimary || isErpGeneralAdminUser(user || STATE.currentUser || uKey);
  const allowed = new Set(getUserAllowedModules(uKey));
  document.querySelectorAll('#sec-inicio [data-module-key]').forEach((card) => {
    const modKey = card.getAttribute('data-module-key');
    if (!modKey) return;
    if (modKey === 'crm') {
      card.hidden = !isGenAdmin;
      return;
    }
    card.hidden = !isPrimary && !allowed.has(modKey);
  });
  ALL_SYSTEM_MODULES.forEach((mod) => {
    if (!Array.isArray(mod.submodules)) return;
    mod.submodules.forEach((sub) => {
      if (!sub.selector) return;
      document.querySelectorAll(sub.selector).forEach((el) => {
        el.hidden = !isPrimary && (!allowed.has(mod.key) || !allowed.has(sub.key));
      });
    });
  });
  const btnGoCrm = document.getElementById('btn-reporte-go-crm');
  if (btnGoCrm) {
    btnGoCrm.hidden = !isGenAdmin;
  }
  if (typeof window.refreshCrmPendingBadge === 'function') {
    window.refreshCrmPendingBadge();
  }
  if (typeof window.refreshManualUsuarioViewIfOpen === 'function') {
    window.refreshManualUsuarioViewIfOpen();
  }
}

function isSectionAllowedForCurrentUser(sectionId) {
  if (
    !sectionId ||
    sectionId === 'sec-inicio' ||
    sectionId === 'sec-perfil-usuario' ||
    sectionId === 'sec-menu-ayuda' ||
    sectionId === 'sec-manual-usuario' ||
    sectionId === 'sec-reporte-mejoras'
  ) {
    return true;
  }
  const uKey = String(STATE.currentUser?.username || '').toLowerCase();
  if (sectionId === 'sec-crm') {
    return uKey === PRIMARY_ADMIN_USER || isErpGeneralAdminUser(STATE.currentUser || uKey);
  }
  if (!uKey || uKey === PRIMARY_ADMIN_USER) return true;
  const allowed = new Set(getUserAllowedModules(uKey));
  for (const mod of ALL_SYSTEM_MODULES) {
    if (Array.isArray(mod.submodules)) {
      for (const sub of mod.submodules) {
        if (Array.isArray(sub.sections) && sub.sections.includes(sectionId)) {
          return allowed.has(mod.key) && allowed.has(sub.key);
        }
      }
    }
    if (mod.sections.includes(sectionId)) {
      return allowed.has(mod.key);
    }
  }
  return true;
}

function resizeUserAvatarImageFile(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        const size = 220;
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, size, size);
        const scale = Math.max(size / img.width, size / img.height);
        const w = img.width * scale;
        const h = img.height * scale;
        const x = (size - w) / 2;
        const y = (size - h) / 2;
        ctx.drawImage(img, x, y, w, h);
        resolve(canvas.toDataURL('image/jpeg', 0.86));
      };
      img.onerror = reject;
      img.src = reader.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

async function authenticateCredentials(rawUsername, rawPassword) {
  const username = rawUsername.trim().toLowerCase();
  const password = rawPassword;

  try {
    const response = await fetch('api/auth.php', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ username, password })
    });
    const contentType = response.headers.get('content-type') || '';
    if (contentType.includes('application/json')) {
      const result = await response.json();
      if (response.ok && result.ok && result.user) {
        saveCustomUserOverride(username, {
          name: result.user.name,
          vendedor: result.user.vendedor,
          role: username === PRIMARY_ADMIN_USER ? 'Administrador' : result.user.role,
          branch: result.user.branch,
          whatsapp: result.user.whatsapp || '',
          avatar: result.user.avatar || '',
          modules: Array.isArray(result.user.modules) ? result.user.modules : [...DEFAULT_MODULE_KEYS],
          pass: password
        });
        return { ok: true, user: result.user };
      }
      return { ok: false, message: result.message || 'Usuario o contraseña incorrectos.' };
    }
  } catch {
    // Fallback to Web Crypto verification
  }

  const record = ADMIN_DIRECTORY[username];
  if (!record) {
    return { ok: false, message: 'Usuario o contraseña incorrectos.' };
  }
  const computed = await sha256Hex(`cn-erp-2026:${username}:${password}`);
  if (computed !== record.hash && password !== record.pass) {
    return { ok: false, message: 'Usuario o contraseña incorrectos. Verificá mayúsculas y números.' };
  }
  return {
    ok: true,
    user: {
      username: record.username,
      name: record.name,
      vendedor: record.vendedor,
      role: username === PRIMARY_ADMIN_USER ? 'Administrador' : record.role,
      branch: record.branch,
      whatsapp: record.whatsapp || '',
      avatar: record.avatar || '',
      modules: record.modules || [...DEFAULT_MODULE_KEYS],
      loginAt: new Date().toISOString()
    }
  };
}

function round2(val) {
  const n = Number(val);
  if (!isFinite(n)) return 0;
  return Math.round(n * 100) / 100;
}

function parseNumber(val) {
  if (typeof val === 'number') return isFinite(val) ? val : 0;
  const str = String(val ?? '')
    .replace(/^\$?\s*/, '')
    .trim();
  if (!str) return 0;
  if (str.includes(',') && str.includes('.')) {
    const lastComma = str.lastIndexOf(',');
    const lastDot = str.lastIndexOf('.');
    if (lastComma > lastDot) {
      const n = parseFloat(str.replace(/\./g, '').replace(',', '.'));
      return isFinite(n) ? n : 0;
    }
    const n = parseFloat(str.replace(/,/g, ''));
    return isFinite(n) ? n : 0;
  }
  if (str.includes(',')) {
    const n = parseFloat(str.replace(',', '.'));
    return isFinite(n) ? n : 0;
  }
  const n = parseFloat(str);
  return isFinite(n) ? n : 0;
}

function formatArs(val) {
  return new Intl.NumberFormat('es-AR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(Number(val) || 0);
}

function formatMoney(val) {
  return formatArs(val);
}

function formatARS(val) {
  return `$ ${formatArs(val)}`;
}

function todayFormatted() {
  const now = new Date();
  const dd = String(now.getDate()).padStart(2, '0');
  const mm = String(now.getMonth() + 1).padStart(2, '0');
  const yyyy = now.getFullYear();
  return `${dd}/${mm}/${yyyy}`;
}

function getLocalTodayIsoStr() {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  const d = String(now.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}
window.getLocalTodayIsoStr = getLocalTodayIsoStr;

function getTurnoComprobanteUniqueKey(c) {
  if (!c || typeof c !== 'object') return '';
  const tBase = c.tipoBase || (/cr[eé]dito|\bnc\b/i.test(String(c.tipo || '')) ? 'Nota de Crédito' : /d[eé]bito|\bnd\b/i.test(String(c.tipo || '')) ? 'Nota de Débito' : 'Factura');
  return `${c.pv || ''}-${tBase}-${c.letra || 'B'}-${String(c.nro || '').padStart(8, '0')}-${c.entryType || 'venta'}`;
}
window.getTurnoComprobanteUniqueKey = getTurnoComprobanteUniqueKey;

function syncTurnosCajasFromServerMap(comprobantesPorCaja) {
  if (!comprobantesPorCaja || typeof comprobantesPorCaja !== 'object') return false;
  let updatedAny = false;
  const todayIsoStr = getLocalTodayIsoStr();
  ['caja1', 'caja2', 'caja3'].forEach((cajaKey) => {
    const fromServer = Array.isArray(comprobantesPorCaja[cajaKey]) ? comprobantesPorCaja[cajaKey] : [];
    if (fromServer.length === 0) return;
    const closedServerKeySet = new Set(
      fromServer.filter((c) => c && c.cerradoEnTurno).map(getTurnoComprobanteUniqueKey)
    );
    const openSlice = fromServer
      .filter((c) => c && !c.cerradoEnTurno)
      .map((c) => Object.assign({}, c, { _inServerDailyRecords: true }));
    const openServerKeySet = new Set(openSlice.map(getTurnoComprobanteUniqueKey));
    const unsyncedLocal = (STATE.turnosCajas[cajaKey] || []).filter((c) => {
      if (!c || c.origenOliver || c.cerradoEnTurno) return false;
      const k = getTurnoComprobanteUniqueKey(c);
      if (closedServerKeySet.has(k) || openServerKeySet.has(k)) return false;
      if (c._inServerDailyRecords) return false;
      return c.fechaIso === todayIsoStr;
    });
    STATE.turnosCajas[cajaKey] = [...openSlice, ...unsyncedLocal];
    updatedAny = true;
  });
  return updatedAny;
}
window.syncTurnosCajasFromServerMap = syncTurnosCajasFromServerMap;

/**
 * Normaliza cadenas quitando acentos/diacríticos y convirtiendo a minúsculas
 * para búsquedas insensibles a tildes y mayúsculas.
 */
function normalizeStr(str) {
  return String(str ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

function normalizeSearchText(str) {
  return normalizeStr(str);
}

function matchesSearchQueryTokens(haystackRaw, queryRaw) {
  const q = normalizeSearchText(queryRaw);
  if (!q) return false;
  const hay = normalizeSearchText(haystackRaw);
  if (hay.includes(q)) return true;
  const tokens = q.split(/\s+/).filter(Boolean);
  if (tokens.length === 0) return false;
  return tokens.every((tok) => hay.includes(tok));
}

function escapeHtml(str) {
  return String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Encuentra los primeros N códigos libres alternados entre 00001 y 99999
 * que aún no están en uso en el padrón de artículos.
 */
function findNextUnusedCodes(count = 5, excludeArticleId = null) {
  const used = new Set();
  for (const art of STATE.articulos) {
    if (excludeArticleId !== null && art.id === excludeArticleId) continue;
    const num = parseInt(String(art.c).trim(), 10);
    if (!isNaN(num) && num >= 1 && num <= 99999) {
      used.add(num);
    }
  }
  const free = [];
  for (let i = 1; i <= 99999; i++) {
    if (!used.has(i)) {
      free.push(String(i).padStart(5, '0'));
      if (free.length >= count) break;
    }
  }
  return free;
}

/**
 * Resuelve la URL de imagen del artículo:
 * - Si tiene imagen en Sinergial (ej. 0000001761.jpg), usa el servidor oficial de imágenes.
 * - Si tiene URL propia subida o seleccionada, la usa directamente.
 * - Si aún no tiene fotografía en el sistema, genera la búsqueda inteligente web con fondo blanco.
 */
function resolveArticleImageUrl(art) {
  if (art.im) {
    if (
      art.im.startsWith('http://') ||
      art.im.startsWith('https://') ||
      art.im.startsWith('assets/') ||
      art.im.startsWith('data:image/')
    ) {
      return { url: art.im, isSystem: art.ims !== 'web' };
    }
    return { url: SINERGIAL_IMG_BASE + encodeURIComponent(art.im), isSystem: true };
  }
  const mainBc = art.bc && art.bc.length > 0 ? art.bc[0].c : '';
  const query = `${mainBc ? mainBc + ' ' : ''}${art.n || ''} supermercado producto fondo blanco`.trim();
  const hostIdx = (art.id || 1) % 4 + 1;
  return {
    url: `https://tse${hostIdx}.mm.bing.net/th?q=${encodeURIComponent(query)}&w=400&h=400&c=7&rs=1&p=0`,
    isSystem: false
  };
}

/**
 * Normaliza cualquier archivo de imagen subido a un cuadrado 400x400 con fondo blanco puro (#ffffff)
 */
function normalizeImageFileToWhiteBg(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        const size = 400;
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, size, size);

        const pad = 16;
        const maxDim = size - pad * 2;
        const scale = Math.min(maxDim / img.width, maxDim / img.height);
        const w = img.width * scale;
        const h = img.height * scale;
        const x = (size - w) / 2;
        const y = (size - h) / 2;

        ctx.drawImage(img, x, y, w, h);
        resolve(canvas.toDataURL('image/jpeg', 0.9));
      };
      img.onerror = reject;
      img.src = reader.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

function normalizeGondolaQueueMap(raw) {
  const out = {};
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return out;
  Object.entries(raw).forEach(([key, entry]) => {
    if (!entry || typeof entry !== 'object') return;
    const artId = Number(entry.artId || key) || 0;
    if (artId <= 0) return;
    out[String(artId)] = {
      artId,
      enGondolaMin: round2(entry.enGondolaMin ?? 0),
      enGondolaMay: round2(entry.enGondolaMay ?? 0),
      copias: Math.max(1, Math.min(999, parseInt(entry.copias, 10) || 1)),
      fechaActualizacion: String(entry.fechaActualizacion || todayFormatted()),
      updatedAtIso: String(entry.updatedAtIso || new Date().toISOString()),
      origen: String(entry.origen || 'Actualización'),
      manual: Boolean(entry.manual)
    };
  });
  return out;
}

