function ensureSeededGondolaPrintHistory() {
  if (!Array.isArray(STATE.gondolaPrintHistory)) {
    STATE.gondolaPrintHistory = [];
  }
  if (STATE.gondolaPrintHistory.length > 0 || !Array.isArray(STATE.articulos) || STATE.articulos.length === 0) {
    updatePgHistoryCountBadge();
    return;
  }
  const seedCodes = [
    '00023', '00039', '00047', '00072', '00096', '00165', '00166', '00167', '00168',
    '00170', '00171', '00172', '00173', '00174', '00175', '01482', '02447', '03543',
    '04454', '06121', '08403', '09397', '10008', '10348', '21625', '22853', '23030',
    '24299', '90878', '90885', '90886', '90888', '90892', '90894', '90895', '90896',
    '90901', '90905', '90907', '90908', '90909', '90912', '90913', '90915'
  ];
  const byCode5 = new Map();
  STATE.articulos.forEach((a) => {
    if (Number(a.bl) === 1) return;
    const c5 = String(a.c || '').trim().padStart(5, '0');
    if (!byCode5.has(c5)) byCode5.set(c5, a);
  });
  const seedItems = [];
  seedCodes.forEach((code5) => {
    const art = byCode5.get(code5);
    if (!art) return;
    const ean = Array.isArray(art.bc) && art.bc.length > 0 ? String(art.bc[0].c || '').trim() : '';
    const actual = round2(art.p1f || 0);
    seedItems.push({
      artId: Number(art.id),
      c: String(art.c || code5),
      n: String(art.n || ''),
      ean,
      actual,
      enGondolaMin: actual,
      enGondolaMay: round2(art.p2f || 0),
      copias: 1,
      fechaAct: '11/11/2026',
      origen: 'Impresión A4',
      manual: false
    });
  });
  if (seedItems.length > 0) {
    STATE.gondolaPrintHistory.push({
      id: 'IMP-SEED-20261111-44',
      fechaHora: '11/11/2026 20:00',
      tipo: 'Impresión Reporte A4 (PDF)',
      usuario: 'Administrador',
      articlesCount: seedItems.length,
      totalLabels: seedItems.length,
      totalSheets: Math.ceil(seedItems.length / 27),
      items: seedItems
    });
    saveLocalGondolaPrintHistory();
  }
}

