function registerGondolaPriceUpdate(newArt, oldArt, origen = 'Actualización de Precio') {
  if (!newArt || !newArt.id) return false;
  if (!STATE.gondolaQueue || typeof STATE.gondolaQueue !== 'object') {
    STATE.gondolaQueue = {};
  }
  const key = String(newArt.id);
  const newP1f = round2(newArt.p1f || 0);
  const newP2f = round2(newArt.p2f || 0);
  const today = todayFormatted();
  const nowIso = new Date().toISOString();

  if (!oldArt) {
    if (newP1f <= 0 && newP2f <= 0) return false;
    newArt.fup = today;
    STATE.gondolaQueue[key] = {
      artId: Number(newArt.id),
      enGondolaMin: 0,
      enGondolaMay: 0,
      copias: 1,
      fechaActualizacion: today,
      updatedAtIso: nowIso,
      origen,
      manual: false
    };
    if (window.PG_SELECT_NEW_ID) window.PG_SELECT_NEW_ID(Number(newArt.id));
    updateGondolaMenuBadges();
    return true;
  }

  const oldP1f = round2(oldArt.p1f || 0);
  const oldP2f = round2(oldArt.p2f || 0);
  if (Math.abs(newP1f - oldP1f) < 0.01 && Math.abs(newP2f - oldP2f) < 0.01) {
    return false;
  }

  const prevEntry = STATE.gondolaQueue[key] || null;
  const enGondolaMin = prevEntry ? round2(prevEntry.enGondolaMin) : oldP1f;
  const enGondolaMay = prevEntry ? round2(prevEntry.enGondolaMay) : oldP2f;
  const copias = prevEntry ? Math.max(1, Number(prevEntry.copias) || 1) : 1;

  if (Math.abs(newP1f - enGondolaMin) < 0.01 && Math.abs(newP2f - enGondolaMay) < 0.01 && !prevEntry?.manual) {
    delete STATE.gondolaQueue[key];
    updateGondolaMenuBadges();
    return false;
  }

  newArt.fup = today;
  STATE.gondolaQueue[key] = {
    artId: Number(newArt.id),
    enGondolaMin,
    enGondolaMay,
    copias,
    fechaActualizacion: today,
    updatedAtIso: nowIso,
    origen,
    manual: Boolean(prevEntry?.manual)
  };
  if (window.PG_SELECT_NEW_ID) window.PG_SELECT_NEW_ID(Number(newArt.id));
  updateGondolaMenuBadges();
  return true;
}

