async function promptAddNewRubro() {
  const raw = window.prompt('Ingresá el nombre del nuevo Rubro (se guardará en MAYÚSCULAS):');
  if (!raw) return;
  const nombre = raw.trim().toUpperCase();
  if (!nombre) return;

  const prevMarcaVal = document.getElementById('art-marca')?.value || '0';
  const prevAlicVal = document.getElementById('art-alicuota')?.value || '5';
  const prevCfgVal = document.getElementById('art-config-precio')?.value || '0';

  let existing = STATE.rubros.find((r) => String(r.nombre || '').trim().toUpperCase() === nombre);
  if (!existing || Number(existing.bl) === 1) {
    let newRubroObj = existing
      ? Object.assign({}, existing, { bl: 0, fb: null })
      : {
          id: STATE.rubros.reduce((m, r) => Math.max(m, Number(r.id) || 0), 0) + 1,
          nombre,
          bl: 0
        };
    try {
      const res = await fetch('api/catalog.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'create_rubro',
          nombre
        })
      });
      if (res.ok) {
        const json = await res.json();
        if (json && json.ok && json.rubro) {
          newRubroObj = json.rubro;
        }
      }
    } catch {}

    existing = STATE.rubros.find((r) => Number(r.id) === Number(newRubroObj.id));
    if (!existing) {
      if (!newRubroObj.codigo) newRubroObj.codigo = Number(findNextFreeRubroCode()) || newRubroObj.id;
      newRubroObj.bl = 0;
      STATE.rubros.push(newRubroObj);
      STATE.rubros.sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es-AR'));
      STATE.rubrosMap.set(Number(newRubroObj.id), newRubroObj);
      existing = newRubroObj;
    } else {
      existing.bl = 0;
      delete existing.fb;
    }
  }

  saveLocalAbmCatalogOverrides();
  populateMasterSelects();
  updateKpis();
  renderAbmRubrosSection();

  const artRubroSel = document.getElementById('art-rubro');
  if (artRubroSel && existing) artRubroSel.value = String(existing.id);
  const artMarcaSel = document.getElementById('art-marca');
  if (artMarcaSel) artMarcaSel.value = prevMarcaVal;
  const artAlicSel = document.getElementById('art-alicuota');
  if (artAlicSel) artAlicSel.value = prevAlicVal;
  const artCfgSel = document.getElementById('art-config-precio');
  if (artCfgSel) artCfgSel.value = prevCfgVal;
  syncArticleModalIvaLockUI();
}

async function promptAddNewMarca() {
  const raw = window.prompt('Ingresá el nombre de la nueva Marca (se guardará en MAYÚSCULAS):');
  if (!raw) return;
  const nombre = raw.trim().toUpperCase();
  if (!nombre) return;

  const prevRubroVal = document.getElementById('art-rubro')?.value || '0';
  const prevAlicVal = document.getElementById('art-alicuota')?.value || '5';
  const prevCfgVal = document.getElementById('art-config-precio')?.value || '0';

  let existing = STATE.marcas.find((m) => String(m.nombre || '').trim().toUpperCase() === nombre);
  if (!existing || Number(existing.bl) === 1) {
    let newMarcaObj = existing
      ? Object.assign({}, existing, { bl: 0, fb: null })
      : {
          id: STATE.marcas.reduce((m, x) => Math.max(m, Number(x.id) || 0), 0) + 1,
          nombre,
          bl: 0
        };
    try {
      const res = await fetch('api/catalog.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'create_marca',
          nombre
        })
      });
      if (res.ok) {
        const json = await res.json();
        if (json && json.ok && json.marca) {
          newMarcaObj = json.marca;
        }
      }
    } catch {}

    existing = STATE.marcas.find((m) => Number(m.id) === Number(newMarcaObj.id));
    if (!existing) {
      if (!newMarcaObj.codigo) newMarcaObj.codigo = findNextFreeMarcaCode();
      newMarcaObj.bl = 0;
      STATE.marcas.push(newMarcaObj);
      STATE.marcas.sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es-AR'));
      STATE.marcasMap.set(Number(newMarcaObj.id), newMarcaObj);
      existing = newMarcaObj;
    } else {
      existing.bl = 0;
      delete existing.fb;
    }
  }

  saveLocalAbmCatalogOverrides();
  populateMasterSelects();
  updateKpis();
  applyAbmMarcasFilters(STATE.abmMarcasPage || 1);

  const artRubroSel = document.getElementById('art-rubro');
  if (artRubroSel) artRubroSel.value = prevRubroVal;
  const artMarcaSel = document.getElementById('art-marca');
  if (artMarcaSel && existing) artMarcaSel.value = String(existing.id);
  const artAlicSel = document.getElementById('art-alicuota');
  if (artAlicSel) artAlicSel.value = prevAlicVal;
  const artCfgSel = document.getElementById('art-config-precio');
  if (artCfgSel) artCfgSel.value = prevCfgVal;
  syncArticleModalIvaLockUI();
}

function updateKpis() {
  let activeCount = 0;
  let cwCount = 0;
  let bajaCount = 0;
  let envCount = 0;
  let sysImgCount = 0;
  let webImgCount = 0;
  for (const a of STATE.articulos) {
    if (Number(a.bl) === 1) {
      bajaCount++;
    } else {
      activeCount++;
      if (isArticlePublishedInCarritoWeb(a)) cwCount++;
      if (Number(a.env) === 1) envCount++;
    }
    if (a.ims === 'web') webImgCount++;
    else if (a.im) sysImgCount++;
  }
  const optEnv = document.querySelector('#filter-estado option[value="envase_retornable"]');
  if (optEnv) {
    optEnv.textContent = `🍾 Con Envase Retornable (${envCount})`;
  }
  document.getElementById('kpi-active-count').textContent = activeCount.toLocaleString('es-AR');
  document.getElementById('kpi-baja-count').textContent = `${cwCount.toLocaleString('es-AR')} tildados Carrito Web · ${bajaCount.toLocaleString('es-AR')} discontinuados`;

  const freeCodes = findNextUnusedCodes(4);
  document.getElementById('kpi-next-code').textContent = freeCodes[0] || '-----';
  document.getElementById('kpi-next-gaps').textContent = `Siguientes libres: ${freeCodes.slice(1).join(', ')}`;
  document.getElementById('kpi-rubros-prov').textContent = `${STATE.rubros.length} Rubros / ${STATE.proveedores.length} Prov.`;

  const imgTotalEl = document.getElementById('kpi-img-total');
  const imgBreakEl = document.getElementById('kpi-img-breakdown');
  if (imgTotalEl) {
    imgTotalEl.textContent = `${(sysImgCount + webImgCount).toLocaleString('es-AR')} (100%)`;
  }
  if (imgBreakEl) {
    imgBreakEl.textContent = `${sysImgCount.toLocaleString('es-AR')} Sistema + ${webImgCount.toLocaleString('es-AR')} Web Asignadas`;
  }
}

function calcEan13CheckDigit(digits12) {
  const clean = String(digits12 || '').replace(/\D/g, '').slice(0, 12).padStart(12, '0');
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    const d = parseInt(clean.charAt(i), 10) || 0;
    sum += i % 2 === 0 ? d : d * 3;
  }
  return String((10 - (sum % 10)) % 10);
}

function buildScaleBarcodeExample(artCode, weightKg = 1, prefix = '21') {
  const cod5 = String(artCode || '00001').replace(/\D/g, '').slice(-5).padStart(5, '0');
  const configs =
    Array.isArray(STATE.scaleBarcodeConfigs) && STATE.scaleBarcodeConfigs.length > 0
      ? STATE.scaleBarcodeConfigs
      : DEFAULT_SCALE_BARCODE_CONFIGS;
  const cfg = configs.find((c) => String(c.prefijo) === String(prefix)) || configs[0];
  const div = Number(cfg?.divisorCantidad) || 1000;
  const val5 = String(Math.max(1, Math.round((Number(weightKg) || 1) * div)))
    .slice(-5)
    .padStart(5, '0');
  const body12 =
    cfg?.primerosCinco === 'CODIGO'
      ? `${prefix}${cod5}${val5}`
      : `${prefix}${val5}${cod5}`;
  return `${body12}${calcEan13CheckDigit(body12)}`;
}

function sanitizeScannerBarcode(rawCode) {
  let s = String(rawCode || '').trim();
  if (!s) return '';
  // Quitar identificadores de simbología AIM enviados por algunos lectores (ej: ]E0, ]C1, ]A0)
  s = s.replace(/^\][A-Za-z]\d/, '').trim();
  // Compactar espacios o caracteres de control si es una lectura numérica de lector/balanza (ej: "2 300240 001200")
  if (/^[\d\s\r\n\t-]+$/.test(s) && s.replace(/\D/g, '').length >= 12) {
    s = s.replace(/\D/g, '');
  }
  return s;
}

/**
 * Decodifica el código de barras emitido por la balanza (PLU) según CONFIG_COD_BARRAS de Oliver
 * (Procedure GET_CODIGOBARRA_ARTICULO en GestionDB):
 * - Prefijos: '21' y '23' (admite 13 dígitos EAN-13, 14 dígitos GTIN-14 con 0 inicial, o 12 dígitos sin dígito verificador)
 * - Posiciones 3..7 (PRIMEROS_CINCO = 'CODIGO'): PLU / Código interno del artículo de 5 dígitos (ej: '00240')
 * - Posiciones 8..12 (ULTIMOS_CINCO = 'CANTIDAD'): Peso en gramos dividido por DIVISOR_CANTIDAD (1000 -> kg, ej: '00120' -> 0.120 kg)
 * - Posición 13: Dígito verificador EAN-13
 */
function parseScaleBarcode(rawCode) {
  let clean = sanitizeScannerBarcode(rawCode);
  if (!clean) return null;

  if (/^0(21|23)\d{11}$/.test(clean)) {
    clean = clean.slice(1);
  } else if (/^(21|23)\d{10}$/.test(clean)) {
    clean = clean + calcEan13CheckDigit(clean);
  }

  if (!/^\d{13}$/.test(clean)) return null;

  const configs =
    Array.isArray(STATE.scaleBarcodeConfigs) && STATE.scaleBarcodeConfigs.length > 0
      ? STATE.scaleBarcodeConfigs
      : DEFAULT_SCALE_BARCODE_CONFIGS;

  const prefix = clean.slice(0, 2);
  const cfg = configs.find((c) => String(c.prefijo) === prefix);
  if (!cfg) return null;

  const first5 = clean.slice(2, 7);
  const last5 = clean.slice(7, 12);
  const checkDigit = clean.slice(12, 13);
  const divisor = Number(cfg.divisorCantidad) > 0 ? Number(cfg.divisorCantidad) : 1000;

  let artCode5 = first5;
  let rawAmountDigits = last5;
  let mode = cfg.ultimosCinco || 'CANTIDAD';

  if (cfg.primerosCinco === 'CANTIDAD' || cfg.primerosCinco === 'PRECIO') {
    rawAmountDigits = first5;
    artCode5 = last5;
    mode = cfg.primerosCinco;
  }

  const rawInt = parseInt(rawAmountDigits, 10);
  const valueDecoded = isFinite(rawInt) && rawInt > 0 ? Math.round((rawInt / divisor) * 1000) / 1000 : 0;

  // Buscar el artículo correspondiente al PLU de 5 dígitos extraído de la balanza
  let matchedArt =
    STATE.articulos.find((a) => a.bl !== 1 && String(a.c || '').padStart(5, '0') === artCode5) || null;
  if (!matchedArt && artCode5.endsWith('00')) {
    const shiftedCode = '00' + artCode5.slice(0, 3);
    matchedArt =
      STATE.articulos.find((a) => a.bl !== 1 && String(a.c || '').padStart(5, '0') === shiftedCode) || null;
  }
  if (!matchedArt) {
    matchedArt =
      STATE.articulos.find((a) => String(a.c || '').padStart(5, '0') === artCode5) || null;
  }

  // Verificar si este EAN-13 completo pertenece como código de barras fijo de fábrica a OTRO artículo no fraccionable
  const fixedBarcodeOwner = STATE.articulos.find(
    (a) =>
      a.bl !== 1 &&
      (!matchedArt || a.id !== matchedArt.id) &&
      Array.isArray(a.bc) &&
      a.bc.some((b) => String(b.c || '').trim() === clean)
  );

  // Si es un EAN fijo de fábrica de otro artículo y el PLU no está marcado fraccionable, priorizar el EAN fijo
  if (fixedBarcodeOwner && !(matchedArt && Number(matchedArt.fr) === 1)) {
    return null;
  }

  // Igual que GET_CODIGOBARRA_ARTICULO en Oliver: cualquier PLU válido de balanza se lee (salvo que haya sido deshabilitado explícitamente)
  const isPluEnabled = Boolean(matchedArt && Number(matchedArt.frDisabled) !== 1);

  return {
    rawBarcode: clean,
    prefix,
    artCode5: matchedArt ? String(matchedArt.c).padStart(5, '0') : artCode5,
    rawAmountDigits,
    divisor,
    mode,
    valueDecoded,
    checkDigit,
    art: matchedArt,
    isFractionableArt: isPluEnabled,
    fixedBarcodeOwner: fixedBarcodeOwner || null
  };
}

function doesArticleAllowFraction(art) {
  return Boolean(art && Number(art.fr) === 1);
}

function normalizeArticleQtyByFrac(val, art, minPositive = false) {
  const n = Number(String(val ?? '').replace(',', '.'));
  const allowFrac = doesArticleAllowFraction(art);
  if (!Number.isFinite(n)) return minPositive ? 1 : 0;
  if (allowFrac) {
    const r = Math.round(n * 1000) / 1000;
    return minPositive ? (r > 0 ? r : 1) : r;
  }
  const intVal = Math.round(n);
  return minPositive ? Math.max(1, intVal) : intVal;
}

function preventDecimalKeyIfNotFrac(event, allowFrac) {
  if (!allowFrac && (event.key === '.' || event.key === ',' || event.key === 'Decimal')) {
    event.preventDefault();
  }
}

function stripDecimalInputIfNotFrac(inpEl, allowFrac) {
  if (allowFrac || !inpEl) return;
  const raw = String(inpEl.value ?? '');
  if (raw.includes('.') || raw.includes(',')) {
    inpEl.value = raw.replace(/[.,].*$/, '');
  }
}

function syncModalFraccionarPreview() {
  const allowFrac = Boolean(document.getElementById('art-fraccionar')?.checked);
  const stepVal = allowFrac ? '0.01' : '1';
  ['art-stock-inicial', 'art-stock-compras', 'art-stock-minimo'].forEach((id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.step = stepVal;
    if (!allowFrac && el.value !== '' && !Number.isNaN(Number(el.value))) {
      el.value = String(Math.round(Number(el.value)));
    }
  });
  const finEl = document.getElementById('art-stock-final');
  if (finEl) {
    const si = Number(document.getElementById('art-stock-inicial')?.value) || 0;
    const sc = Number(document.getElementById('art-stock-compras')?.value) || 0;
    finEl.value = String(allowFrac ? round2(si + sc) : Math.round(si + sc));
  }
  document.querySelectorAll('#barcodes-rows-container .bc-qty-input').forEach((inp) => {
    inp.step = stepVal;
    inp.min = allowFrac ? '0.01' : '1';
    if (!allowFrac && inp.value !== '' && !Number.isNaN(Number(inp.value))) {
      inp.value = String(Math.max(1, Math.round(Number(inp.value) || 1)));
    }
  });
}

function getDefaultStockMinimoByRubro(rubroId) {
  const rid = Number(rubroId) || 0;
  if (rid === 30) return 1;
  const rObj = STATE.rubrosMap ? STATE.rubrosMap.get(rid) : null;
  if (rObj && String(rObj.nombre || '').trim().toUpperCase() === 'PERFUMES') {
    return 1;
  }
  return 6;
}

function getArticleStockMinimo(art) {
  if (!art) return 6;
  if (art.sm !== undefined && art.sm !== null && art.sm !== '' && !Number.isNaN(Number(art.sm))) {
    return Math.max(0, round2(Number(art.sm)));
  }
  return getDefaultStockMinimoByRubro(art.r);
}

function isArticleBelowStockMinimo(art) {
  if (!art) return false;
  return Number(art.sf ?? 0) < getArticleStockMinimo(art);
}

function applyCatalogFilters(page = 1) {
  const q = document.getElementById('filter-q').value.trim().toLowerCase();
  const rubroId = Number(document.getElementById('filter-rubro').value) || 0;
  const provId = Number(document.getElementById('filter-proveedor').value) || 0;
  const marcaId = Number(document.getElementById('filter-marca')?.value) || 0;
  const rawCfgVal = document.getElementById('filter-config').value;
  const isSinConfig = rawCfgVal === 'SIN_CONFIG' || rawCfgVal === '0';
  const cfgId = isSinConfig ? 0 : (Number(rawCfgVal) || 0);
  const estado = document.getElementById('filter-estado').value;

  document.getElementById('btn-clear-search').hidden = q.length === 0;

  const tokens = q ? q.split(/\s+/).filter(Boolean) : [];
  const scaleQueryInfo = tokens.length === 1 ? parseScaleBarcode(tokens[0]) : null;

  STATE.filtered = STATE.articulos.filter((art) => {
    if (estado === 'activos' && art.bl === 1) return false;
    if (estado === 'bajo_stock_minimo' && (art.bl === 1 || !isArticleBelowStockMinimo(art))) return false;
    if (estado === 'envase_retornable' && (art.bl === 1 || Number(art.env) !== 1)) return false;
    if (estado === 'carrito_web' && (Number(art.bl) === 1 || !isArticlePublishedInCarritoWeb(art))) return false;
    if (estado === 'canje_fidelizacion' && (art.bl === 1 || Number(art.cfid) !== 1)) return false;
    if (estado === 'baja' && art.bl !== 1) return false;
    if (rubroId > 0 && Number(art.r) !== rubroId) return false;
    if (marcaId > 0 && Number(art.mk) !== marcaId) return false;
    if (isSinConfig) {
      if (Number(art.ucp) === 1 && Number(art.cp) > 0 && STATE.configPreciosMap.has(Number(art.cp))) return false;
    } else if (cfgId > 0) {
      if (!(Number(art.ucp) === 1 && Number(art.cp) === cfgId)) return false;
    }

    if (provId > 0) {
      const matchMainProv = Number(art.p) === provId;
      const matchMultiProv = Array.isArray(art.pr) && art.pr.some((x) => Number(x.p) === provId);
      if (!matchMainProv && !matchMultiProv) return false;
    }

    if (tokens.length > 0) {
      if (scaleQueryInfo && scaleQueryInfo.art && scaleQueryInfo.art.id === art.id) {
        return true;
      }
      const codeStr = String(art.c || '').toLowerCase();
      const nameStr = String(art.n || '').toLowerCase();
      const cfStr = String(art.cf || '').toLowerCase();
      const marcaObj = STATE.marcasMap.get(Number(art.mk));
      const marcaStr = marcaObj ? String(marcaObj.nombre).toLowerCase() : '';
      const bcJoined = Array.isArray(art.bc)
        ? art.bc.map((b) => String(b.c).toLowerCase()).join(' ')
        : '';
      const prCfJoined = Array.isArray(art.pr)
        ? art.pr.map((p) => String(p.cf || '').toLowerCase()).join(' ')
        : '';
      const scalePrefixesStr = art.fr === 1 ? `21${codeStr} 23${codeStr} balanza fraccionable` : '';

      const haystack = `${codeStr} ${nameStr} ${cfStr} ${marcaStr} ${bcJoined} ${prCfJoined} ${scalePrefixesStr}`;
      for (const tk of tokens) {
        if (!haystack.includes(tk)) return false;
      }
    }

    return true;
  });

  const totalPages = Math.max(1, Math.ceil(STATE.filtered.length / PAGE_SIZE));
  STATE.currentPage = Math.min(Math.max(1, page), totalPages);
  renderCatalogTable();
}

function resolveArticleSupplierCodeForProv(art, provId) {
  if (!art || !provId) return '';
  const codes = [];
  if (Array.isArray(art.pr)) {
    art.pr.forEach((entry) => {
      if (Number(entry.p) === Number(provId)) {
        const c = String(entry.cf || '').trim();
        if (c && !codes.includes(c)) codes.push(c);
      }
    });
  }
  if (codes.length === 0 && Number(art.p) === Number(provId)) {
    const mainCf = String(art.cf || '').trim();
    if (mainCf) codes.push(mainCf);
  }
  if (codes.length === 0 && String(art.cf || '').trim()) {
    codes.push(String(art.cf).trim());
  }
  return codes.join(' / ');
}

function renderCatalogTable() {
  const tbody = document.getElementById('catalog-tbody');
  const statusEl = document.getElementById('catalog-status-msg');
  const prevBtn = document.getElementById('btn-prev-page');
  const nextBtn = document.getElementById('btn-next-page');
  const pageInd = document.getElementById('page-indicator');

  const activeProvId = Number(document.getElementById('filter-proveedor')?.value) || 0;
  const showCodProvCol = activeProvId > 0;
  const thCodProv = document.getElementById('th-catalog-cod-prov');
  if (thCodProv) {
    thCodProv.hidden = !showCodProvCol;
  }

  const total = STATE.filtered.length;
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const startIdx = (STATE.currentPage - 1) * PAGE_SIZE;
  const pageItems = STATE.filtered.slice(startIdx, startIdx + PAGE_SIZE);

  statusEl.textContent = `Mostrando ${pageItems.length} de ${total.toLocaleString('es-AR')} artículos encontrados`;
  syncUnifiedPaginationControls(pageInd, prevBtn, nextBtn, STATE.currentPage, totalPages, (nextPage) => {
    STATE.currentPage = nextPage;
    renderCatalogTable();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  tbody.textContent = '';

  if (pageItems.length === 0) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = showCodProvCol ? 8 : 7;
    td.className = 'table-loading-cell';
    td.textContent = 'No se encontraron artículos con los filtros aplicados.';
    tr.appendChild(td);
    tbody.appendChild(tr);
    return;
  }

  const fragment = document.createDocumentFragment();

  pageItems.forEach((art) => {
    const tr = document.createElement('tr');

    // 1. Sticky Row Header: Foto Fondo Blanco + Código + Nombre
    const th = document.createElement('th');
    th.scope = 'row';
    const headWrap = document.createElement('div');
    headWrap.className = 'art-row-head';

    const thumbBox = document.createElement('div');
    thumbBox.className = 'thumb-white-box';
    const img = document.createElement('img');
    const resolvedImg = resolveArticleImageUrl(art);
    img.src = resolvedImg.url;
    img.alt = art.n;
    img.loading = 'lazy';
    img.onerror = () => {
      img.onerror = null;
      img.src = 'assets/img/icon-192.png';
    };
    thumbBox.appendChild(img);

    const meta = document.createElement('div');
    meta.className = 'art-head-meta';

    const codePill = document.createElement('div');
    codePill.className = 'art-code-pill';
    codePill.textContent = `#${art.c}`;

    if (art.fr === 1) {
      const tagFrac = document.createElement('span');
      tagFrac.className = 'mini-tag mini-tag--frac';
      tagFrac.textContent = 'Fraccionable';
      codePill.appendChild(tagFrac);
    }
    if (Number(art.env) === 1) {
      const tagEnv = document.createElement('span');
      tagEnv.className = 'mini-tag';
      tagEnv.style.background = 'rgba(16, 185, 129, 0.16)';
      tagEnv.style.color = '#10b981';
      tagEnv.style.border = '1px solid rgba(16, 185, 129, 0.45)';
      tagEnv.textContent = '🍾 Envase Retornable (Cód. 03000)';
      codePill.appendChild(tagEnv);
    }
    if (art.bl === 1) {
      const tagBaja = document.createElement('span');
      tagBaja.className = 'mini-tag mini-tag--baja';
      tagBaja.textContent = `Baja ${art.fb || ''}`;
      codePill.appendChild(tagBaja);
    }

    const titleSpan = document.createElement('span');
    titleSpan.className = 'art-title-text';
    titleSpan.textContent = art.n;

    meta.appendChild(codePill);
    meta.appendChild(titleSpan);
    headWrap.appendChild(thumbBox);
    headWrap.appendChild(meta);
    th.appendChild(headWrap);
    tr.appendChild(th);

    // 1b. Código Proveedor (solo visible cuando se filtra por Proveedor)
    if (showCodProvCol) {
      const tdCodProv = document.createElement('td');
      tdCodProv.dataset.label = 'Código Proveedor';
      const codProvStr = resolveArticleSupplierCodeForProv(art, activeProvId);
      if (codProvStr) {
        const codeProvEl = document.createElement('code');
        codeProvEl.style.fontWeight = '700';
        codeProvEl.style.color = 'var(--gold-main)';
        codeProvEl.style.fontSize = '0.86rem';
        codeProvEl.textContent = codProvStr;
        tdCodProv.appendChild(codeProvEl);
      } else {
        tdCodProv.style.color = 'var(--silver-muted)';
        tdCodProv.textContent = '—';
      }
      tr.appendChild(tdCodProv);
    }

    // 2. Costo Neto de IVA
    const tdCostoNeto = document.createElement('td');
    tdCostoNeto.className = 'num-col';
    tdCostoNeto.dataset.label = 'Costo Neto de IVA';
    const cNeto = document.createElement('span');
    cNeto.style.fontWeight = '700';
    cNeto.textContent = `$ ${formatArs(art.cn)}`;
    tdCostoNeto.appendChild(cNeto);
    tr.appendChild(tdCostoNeto);

    // 3. Costo Final
    const tdCosto = document.createElement('td');
    tdCosto.className = 'num-col';
    tdCosto.dataset.label = 'Costo Final';
    const cFinal = document.createElement('span');
    cFinal.style.fontWeight = '700';
    cFinal.textContent = `$ ${formatArs(art.cfn)}`;
    tdCosto.appendChild(cFinal);
    tr.appendChild(tdCosto);

    // 4. Lista Minorista
    const tdMin = document.createElement('td');
    tdMin.className = 'num-col';
    tdMin.dataset.label = 'Lista Minorista';
    const minFinal = document.createElement('span');
    minFinal.className = 'price-final-val';
    minFinal.textContent = `$ ${formatArs(art.p1f)}`;
    tdMin.appendChild(minFinal);
    tr.appendChild(tdMin);

    // 5. Lista Mayorista
    const tdMay = document.createElement('td');
    tdMay.className = 'num-col';
    tdMay.dataset.label = 'Lista Mayorista';
    const mayFinal = document.createElement('span');
    mayFinal.style.fontWeight = '800';
    mayFinal.style.color = 'var(--success)';
    mayFinal.textContent = `$ ${formatArs(art.p2f)}`;
    tdMay.appendChild(mayFinal);
    tr.appendChild(tdMay);

    // 6. Inventario (Stock + Stock Mínimo Sugerido)
    const tdStock = document.createElement('td');
    tdStock.className = 'num-col';
    tdStock.dataset.label = 'Inventario';
    const stStack = document.createElement('div');
    stStack.className = 'price-cell-stack';
    const stBadge = document.createElement('span');
    const sfNumBadge = round2(Number(art.sf) || 0);
    stBadge.className = 'stock-badge' + (sfNumBadge <= 0 ? ' stock-badge--zero' : '');
    stBadge.textContent = sfNumBadge < 0
      ? `STOCK NEG. (${sfNumBadge.toLocaleString('es-AR')})`
      : sfNumBadge === 0
        ? 'SIN STOCK (0)'
        : `Stock: ${sfNumBadge.toLocaleString('es-AR')}`;
    stStack.appendChild(stBadge);
    const smVal = getArticleStockMinimo(art);
    const smSub = document.createElement('span');
    const belowMin = Number(art.sf ?? 0) < smVal;
    smSub.style.fontSize = '0.73rem';
    smSub.style.fontWeight = belowMin ? '700' : '500';
    smSub.style.color = belowMin ? '#dc2626' : 'var(--silver-muted)';
    smSub.textContent = belowMin ? `⚠️ Mín. sug.: ${smVal}` : `Mín. sug.: ${smVal}`;
    stStack.appendChild(smSub);
    tdStock.appendChild(stStack);
    tr.appendChild(tdStock);

    // 7. Botones Editar y Duplicar
    const tdAct = document.createElement('td');
    tdAct.dataset.label = 'Acciones';
    const actWrap = document.createElement('div');
    actWrap.style.display = 'flex';
    actWrap.style.gap = '0.4rem';
    actWrap.style.flexWrap = 'wrap';

    const btnEdit = document.createElement('button');
    btnEdit.type = 'button';
    btnEdit.className = 'btn-secondary btn-sm';
    btnEdit.textContent = '✏️ Editar';
    btnEdit.addEventListener('click', () => openArticleModal(art));

    const btnDup = document.createElement('button');
    btnDup.type = 'button';
    btnDup.className = 'btn-secondary btn-sm';
    btnDup.title = 'Duplicar configuración de este artículo (excepto código interno, cód. proveedor, cód. de barras y foto)';
    btnDup.textContent = '📋 Duplicar';
    btnDup.addEventListener('click', () => openDuplicateArticleModal(art));

    actWrap.appendChild(btnEdit);
    actWrap.appendChild(btnDup);
    tdAct.appendChild(actWrap);
    tr.appendChild(tdAct);

    fragment.appendChild(tr);
  });

  tbody.appendChild(fragment);
}

/* ==========================================================================
   MODAL FICHA DEL ARTÍCULO: CÁLCULOS AUTOMÁTICOS Y MULTICAMPOS
   ========================================================================== */
function createSupplierRowElement(provId = 0, codFabricante = '') {
  const row = document.createElement('div');
  row.className = 'dyn-row supplier-dyn-row';

  const select = document.createElement('select');
  select.className = 'form-select form-input--compact sup-select';
  const optEmpty = document.createElement('option');
  optEmpty.value = '0';
  optEmpty.textContent = '— Seleccionar Proveedor —';
  select.appendChild(optEmpty);

  STATE.proveedores.forEach((p) => {
    const opt = document.createElement('option');
    opt.value = String(p.id);
    opt.textContent = `${p.nombre}${p.cuit ? ' (' + p.cuit + ')' : ''}`;
    if (Number(p.id) === Number(provId)) opt.selected = true;
    select.appendChild(opt);
  });

  const inputCf = document.createElement('input');
  inputCf.type = 'text';
  inputCf.className = 'form-input form-input--compact sup-cf-input';
  inputCf.placeholder = 'Cód. Fabricante de este proveedor';
  inputCf.value = codFabricante || '';
  inputCf.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      e.stopPropagation();
    }
  });

  const btnDel = document.createElement('button');
  btnDel.type = 'button';
  btnDel.className = 'btn-remove-row';
  btnDel.title = 'Quitar proveedor';
  btnDel.textContent = '✕';
  btnDel.addEventListener('click', () => {
    row.remove();
  });

  row.appendChild(select);
  row.appendChild(inputCf);
  row.appendChild(btnDel);
  return row;
}

function findArticleWithDuplicateBarcode(barcodeStr, excludeArticleId = null) {
  const cleanBc = String(barcodeStr || '').trim().toUpperCase();
  if (!cleanBc) return null;
  const list = Array.isArray(STATE.articulos) ? STATE.articulos : [];
  return (
    list.find((a) => {
      if (!a) return false;
      if (excludeArticleId !== null && excludeArticleId !== undefined && Number(a.id) === Number(excludeArticleId)) {
        return false;
      }
      if (!Array.isArray(a.bc)) return false;
      return a.bc.some((b) => String(b?.c || '').trim().toUpperCase() === cleanBc);
    }) || null
  );
}

function createBarcodeRowElement(codigo = '', cantidad = 1) {
  const row = document.createElement('div');
  row.className = 'dyn-row barcode-dyn-row';

  const inputCode = document.createElement('input');
  inputCode.type = 'text';
  inputCode.className = 'form-input form-input--compact bc-code-input';
  inputCode.placeholder = 'Código de barras (EAN / Interno)';
  inputCode.value = codigo || '';

  const validateBarcodeRowLive = () => {
    const cleanVal = inputCode.value.trim();
    const alertEl = document.getElementById('article-form-alert');
    if (!cleanVal) {
      inputCode.style.borderColor = '';
      inputCode.style.backgroundColor = '';
      return;
    }
    const dupArt = findArticleWithDuplicateBarcode(cleanVal, STATE.editingArticleId);
    if (dupArt) {
      inputCode.style.borderColor = '#dc2626';
      inputCode.style.backgroundColor = '#fef2f2';
      if (alertEl) {
        alertEl.textContent = `⚠️ CÓDIGO DE BARRAS DUPLICADO: El código "${cleanVal}" ya pertenece al producto #${dupArt.c} — "${dupArt.n}". No se permite crear un artículo con un código de barras existente.`;
        alertEl.hidden = false;
      }
    } else {
      inputCode.style.borderColor = '';
      inputCode.style.backgroundColor = '';
      if (alertEl && alertEl.textContent.includes('CÓDIGO DE BARRAS DUPLICADO')) {
        alertEl.hidden = true;
      }
    }
  };

  inputCode.addEventListener('input', validateBarcodeRowLive);
  inputCode.addEventListener('blur', validateBarcodeRowLive);
  inputCode.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      e.stopPropagation();
      const cleaned = sanitizeScannerBarcode(inputCode.value);
      if (cleaned) inputCode.value = cleaned;
      validateBarcodeRowLive();
    }
  });

  const modalAllowFrac = Boolean(document.getElementById('art-fraccionar')?.checked);
  const inputQty = document.createElement('input');
  inputQty.type = 'number';
  inputQty.step = modalAllowFrac ? '0.01' : '1';
  inputQty.min = modalAllowFrac ? '0.01' : '1';
  inputQty.className = 'form-input form-input--compact bc-qty-input';
  inputQty.placeholder = 'Cantidad (ej: 1)';
  inputQty.value = String(modalAllowFrac ? (cantidad || 1) : Math.max(1, Math.round(Number(cantidad) || 1)));
  inputQty.addEventListener('keydown', (e) => {
    preventDecimalKeyIfNotFrac(e, Boolean(document.getElementById('art-fraccionar')?.checked));
    if (e.key === 'Enter') {
      e.preventDefault();
      e.stopPropagation();
    }
  });
  inputQty.addEventListener('input', () => {
    stripDecimalInputIfNotFrac(inputQty, Boolean(document.getElementById('art-fraccionar')?.checked));
  });

  const btnScanRow = document.createElement('button');
  btnScanRow.type = 'button';
  btnScanRow.className = 'btn-secondary btn-sm bc-scan-btn';
  btnScanRow.title = 'Escanear código de barras o QR con la cámara (Android / iOS)';
  btnScanRow.textContent = '📷';
  btnScanRow.addEventListener('click', () => {
    if (typeof window.openUniversalBarcodeScanner === 'function') {
      window.openUniversalBarcodeScanner({
        title: '📷 Escanear Código de Barras del Artículo',
        continuous: false,
        onDetect: (rawCode) => {
          const cleaned = sanitizeScannerBarcode(rawCode) || String(rawCode || '').trim();
          if (cleaned) {
            inputCode.value = cleaned;
            validateBarcodeRowLive();
          }
        }
      });
    }
  });

  const btnDel = document.createElement('button');
  btnDel.type = 'button';
  btnDel.className = 'btn-remove-row';
  btnDel.title = 'Quitar código de barras';
  btnDel.textContent = '✕';
  btnDel.addEventListener('click', () => {
    row.remove();
  });

  row.appendChild(inputCode);
  row.appendChild(btnScanRow);
  row.appendChild(inputQty);
  row.appendChild(btnDel);
  return row;
}

function getSelectedIvaFraction() {
  const chkUsaCfg = document.getElementById('art-usa-config-precio');
  const selCfg = document.getElementById('art-config-precio');
  const cfgId = Number(selCfg?.value) || 0;
  if (chkUsaCfg?.checked && cfgId > 0 && STATE.configPreciosMap.has(cfgId)) {
    const alic = resolveAlicuotaForConfig(STATE.configPreciosMap.get(cfgId));
    return Number(alic.porcentaje ?? 21) / 100;
  }
  const sel = document.getElementById('art-alicuota');
  const opt = sel.options[sel.selectedIndex];
  const pct = opt && opt.dataset.porcentaje !== undefined ? Number(opt.dataset.porcentaje) : 21;
  return pct / 100;
}

function openArticleModal(art = null, options = {}) {
  const isDuplicate = Boolean(options.isDuplicate && art);
  const dialog = document.getElementById('article-dialog');
  const alertEl = document.getElementById('article-form-alert');
  const dupBanner = document.getElementById('duplicate-source-banner');
  const dupText = document.getElementById('duplicate-source-text');

  if (Array.isArray(STATE.clientes) && STATE.clientes.length > 0) {
    syncProveedoresCatalogFromEntities();
  } else if (!STATE.clientesLoaded && !STATE.clientesLoadingPromise) {
    loadClientesDatabase();
  }

  populateMasterSelects();

  alertEl.hidden = true;
  document.getElementById('smart-candidates-panel').hidden = true;

  const isNew = !art;
  // When duplicating, we create a brand-new article (editingArticleId = null)
  STATE.editingArticleId = (isNew || isDuplicate) ? null : art.id;

  if (dupBanner && dupText) {
    if (isDuplicate) {
      const preBcTxt = options.prefillBarcode
        ? ` Se pre-cargó el código de barras "${options.prefillBarcode}".`
        : ' Completá el nuevo nombre, código proveedor, código de barras y fotografía.';
      dupText.textContent = `📋 Duplicando configuración desde #${art.c} (${art.n}). Se copiaron rubro, proveedor, IVA, costos, márgenes y precios.${preBcTxt}`;
      dupBanner.hidden = false;
    } else {
      dupBanner.hidden = true;
    }
  }

  const freeCodes = findNextUnusedCodes(4, STATE.editingArticleId);
  document.getElementById('art-code-hint').textContent = `Próximos libres: ${freeCodes.join(', ')}`;

  if (isDuplicate) {
    document.getElementById('dialog-mode-badge').textContent = 'DUPLICAR ARTÍCULO';
    document.getElementById('article-dialog-title').textContent = `Duplicando: ${art.n}`;
  } else {
    document.getElementById('dialog-mode-badge').textContent = isNew
      ? 'NUEVO ARTÍCULO'
      : `EDITANDO #${art.c}`;
    document.getElementById('article-dialog-title').textContent = isNew
      ? 'Alta de Nuevo Producto'
      : art.n;
  }

  // 1. Código interno: nuevo código libre si es alta o duplicación
  document.getElementById('art-codigo').value = (isNew || isDuplicate)
    ? (options.prefillScaleCode5 || freeCodes[0] || '00001')
    : art.c;

  // Nombre: en duplicación conserva el nombre base para facilitar editar solo la variante/sabor
  document.getElementById('art-nombre').value = isNew ? '' : art.n;
  document.getElementById('art-rubro').value = isNew ? '0' : String(art.r || 0);
  const artMarcaSel = document.getElementById('art-marca');
  if (artMarcaSel) {
    artMarcaSel.value = isNew ? '0' : String(art.mk || 0);
  }
  const artCwChk = document.getElementById('art-carrito-web');
  if (artCwChk) {
    artCwChk.checked = isNew ? true : isArticlePublishedInCarritoWeb(art);
  }
  const artCfidChk = document.getElementById('art-canje-fidelizacion');
  const artCanjeBox = document.getElementById('art-canje-config-box');
  if (artCfidChk) {
    artCfidChk.checked = isNew ? false : Number(art.cfid) === 1;
  }
  if (artCanjeBox) {
    artCanjeBox.hidden = !(artCfidChk && artCfidChk.checked);
  }
  const artPtsManualChk = document.getElementById('art-puntos-canje-manual');
  const artPtsInput = document.getElementById('art-puntos-canje');
  const artFactorLbl = document.getElementById('art-factor-canje-label');
  const factorCanje = Number(STATE.fidelizacionConfig.factorCanje) || 1.12;
  if (artFactorLbl) {
    artFactorLbl.textContent = factorCanje.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  if (artPtsManualChk) {
    artPtsManualChk.checked = isNew ? false : Number(art.pfidManual) === 1;
  }
  if (artPtsInput) {
    const autoPts = Math.max(1, Math.round((isNew ? 0 : Number(art.p1f) || 0) * factorCanje));
    artPtsInput.value = String(
      !isNew && Number(art.pfidManual) === 1 && Number(art.pfid) > 0
        ? Math.round(Number(art.pfid))
        : autoPts
    );
  }
  document.getElementById('art-fraccionar').checked = options.prefillScaleCode5
    ? true
    : (isNew ? false : art.fr === 1);
  syncModalFraccionarPreview();

  const usesEnvRet = !isNew && doesArticleUseEnvaseRetornable(art);
  const chkEnvRet = document.getElementById('art-envase-retornable');
  const chkEnvRetTop = document.getElementById('art-envase-retornable-top');
  const inpEnvAsoc = document.getElementById('art-envase-asociado');
  if (chkEnvRet) chkEnvRet.checked = usesEnvRet;
  if (chkEnvRetTop) chkEnvRetTop.checked = usesEnvRet;
  if (inpEnvAsoc) {
    const envArt = findEnvaseRetornableArticle();
    inpEnvAsoc.value = `ENVASE RETORNABLE (Cód. ${envArt.c || '03000'} · $ ${formatArs(envArt.p1f || 3000)})`;
  }

  const bajaChk = document.getElementById('art-baja-logica');
  const bajaWrap = document.getElementById('baja-fecha-wrap');
  const bajaInput = document.getElementById('art-fecha-baja');
  bajaChk.checked = (isNew || isDuplicate) ? false : art.bl === 1;
  bajaWrap.hidden = !bajaChk.checked;
  bajaInput.value = (isNew || isDuplicate) ? '' : (art.fb || (bajaChk.checked ? todayFormatted() : ''));

  // Suppliers rows: en duplicación mantiene el/los proveedor(es) pero limpia el código de proveedor (cf = '')
  const supContainer = document.getElementById('suppliers-rows-container');
  supContainer.textContent = '';
  const supList = !isNew && Array.isArray(art.pr) && art.pr.length > 0
    ? art.pr
    : (!isNew && art.p > 0 ? [{ p: art.p, cf: art.cf || '' }] : [{ p: 0, cf: '' }]);
  supList.forEach((s) => {
    const cfToUse = isDuplicate ? '' : s.cf;
    supContainer.appendChild(createSupplierRowElement(s.p, cfToUse));
  });

  // Barcodes rows: en duplicación NO se copia el código de barras original (salvo prefillBarcode)
  const bcContainer = document.getElementById('barcodes-rows-container');
  bcContainer.textContent = '';
  const prefillBc = options.prefillBarcode ? String(options.prefillBarcode).trim() : '';
  const appendBc = options.appendBarcode ? String(options.appendBarcode).trim() : '';
  let bcList;
  if (!isNew && !isDuplicate && Array.isArray(art.bc) && art.bc.length > 0) {
    bcList = [...art.bc];
    if (appendBc && !bcList.some((b) => String(b.c || '').trim().toUpperCase() === appendBc.toUpperCase())) {
      bcList.push({ c: appendBc, q: 1 });
    }
  } else if (!isNew && !isDuplicate && appendBc) {
    bcList = [{ c: appendBc, q: 1 }];
  } else {
    bcList = [{ c: prefillBc || '', q: 1 }];
  }
  bcList.forEach((b) => {
    bcContainer.appendChild(createBarcodeRowElement(b.c, b.q));
  });

  // Prices: en duplicación se duplica toda la configuración de IVA, costos, márgenes y precios
  const defaultFirstCfg = STATE.configuracionesPrecios?.[0] || null;
  const defaultFirstCfgId = defaultFirstCfg ? String(defaultFirstCfg.id) : '3';
  const defaultMinMargin = defaultFirstCfg ? String(defaultFirstCfg.margenMinorista) : '49';
  const defaultMayMargin = defaultFirstCfg ? String(defaultFirstCfg.margenMayorista) : '18';

  const usaConfigChecked = isNew ? true : Number(art.ucp) === 1;
  document.getElementById('art-usa-config-precio').checked = usaConfigChecked;
  const resolvedCfgVal = isNew
    ? defaultFirstCfgId
    : (usaConfigChecked
        ? (art.cp && STATE.configPreciosMap?.has(Number(art.cp)) ? String(art.cp) : defaultFirstCfgId)
        : '0');
  document.getElementById('art-config-precio').value = resolvedCfgVal;

  const activeModalCfg = usaConfigChecked && Number(resolvedCfgVal) > 0
    ? STATE.configPreciosMap.get(Number(resolvedCfgVal)) || null
    : null;
  const effAlicModal = activeModalCfg
    ? resolveAlicuotaForConfig(activeModalCfg)
    : (isNew ? resolveAlicuotaForConfig(defaultFirstCfg) : resolveArticleEffectiveIva(art));

  document.getElementById('art-alicuota').value = String(effAlicModal.id);
  syncArticleModalIvaLockUI();

  const modalCn = isNew ? 0 : Number(art.cn ?? 0);
  const ivaFracModal = Number(effAlicModal.porcentaje ?? 21) / 100;
  const storedArtIva = (!isNew && art.iva !== undefined && art.iva !== null && art.iva !== '' && !Number.isNaN(Number(art.iva)))
    ? Number(art.iva)
    : effAlicModal.porcentaje;
  const needRecalcByCfgIva = !isNew && activeModalCfg && modalCn > 0 && Math.abs(storedArtIva - effAlicModal.porcentaje) > 0.001;

  const modalM1 = isNew
    ? Number(defaultMinMargin)
    : (activeModalCfg && needRecalcByCfgIva ? Number(activeModalCfg.margenMinorista) : Number(art.m1 ?? 0));
  const modalM2 = isNew
    ? Number(defaultMayMargin)
    : (activeModalCfg && needRecalcByCfgIva ? Number(activeModalCfg.margenMayorista) : Number(art.m2 ?? 0));

  const modalCfn = isNew
    ? 0
    : (needRecalcByCfgIva ? round2(modalCn * (1 + ivaFracModal)) : Number(art.cfn ?? 0));
  const modalP1n = isNew
    ? 0
    : (needRecalcByCfgIva ? round2(modalCn * (1 + modalM1 / 100)) : Number(art.p1n ?? 0));
  const modalP1f = isNew
    ? 0
    : (needRecalcByCfgIva ? round2(modalP1n * (1 + ivaFracModal)) : Number(art.p1f ?? 0));
  const modalP2n = isNew
    ? 0
    : (needRecalcByCfgIva ? round2(modalCn * (1 + modalM2 / 100)) : Number(art.p2n ?? 0));
  const modalP2f = isNew
    ? 0
    : (needRecalcByCfgIva ? round2(modalP2n * (1 + ivaFracModal)) : Number(art.p2f ?? 0));

  document.getElementById('art-costo-neto').value = String(modalCn);
  document.getElementById('art-costo-final').value = String(modalCfn);

  document.getElementById('art-margen-min').value = String(modalM1);
  document.getElementById('art-min-neto').value = String(modalP1n);
  document.getElementById('art-min-final').value = String(modalP1f);

  document.getElementById('art-margen-may').value = String(modalM2);
  document.getElementById('art-may-neto').value = String(modalP2n);
  document.getElementById('art-may-final').value = String(modalP2f);

  // Inventory
  document.getElementById('art-stock-inicial').value = (isNew || isDuplicate) ? '0' : String(art.si ?? 0);
  document.getElementById('art-stock-compras').value = (isNew || isDuplicate) ? '0' : String(art.sc ?? 0);
  document.getElementById('art-stock-final').value = (isNew || isDuplicate) ? '0' : String(art.sf ?? 0);
  const inpStockMinModal = document.getElementById('art-stock-minimo');
  if (inpStockMinModal) {
    if (isNew) {
      inpStockMinModal.value = String(getDefaultStockMinimoByRubro(0));
      inpStockMinModal.dataset.manualEdited = '0';
    } else {
      const currentSm = getArticleStockMinimo(art);
      const defSm = getDefaultStockMinimoByRubro(art.r);
      inpStockMinModal.value = String(currentSm);
      inpStockMinModal.dataset.manualEdited = currentSm !== defSm ? '1' : '0';
    }
    if (!inpStockMinModal.dataset.listenerBound) {
      inpStockMinModal.dataset.listenerBound = '1';
      inpStockMinModal.addEventListener('keydown', (e) => {
        preventDecimalKeyIfNotFrac(e, Boolean(document.getElementById('art-fraccionar')?.checked));
      });
      inpStockMinModal.addEventListener('input', () => {
        stripDecimalInputIfNotFrac(inpStockMinModal, Boolean(document.getElementById('art-fraccionar')?.checked));
        inpStockMinModal.dataset.manualEdited = '1';
      });
      const selRubroModal = document.getElementById('art-rubro');
      selRubroModal?.addEventListener('change', () => {
        if (inpStockMinModal.dataset.manualEdited !== '1') {
          inpStockMinModal.value = String(getDefaultStockMinimoByRubro(Number(selRubroModal.value) || 0));
        }
      });
    }
  }
  syncModalFraccionarPreview();

  // Image: en duplicación NO se copia la fotografía
  STATE.currentEditImage = (isNew || isDuplicate) ? null : art.im;
  if (isNew || isDuplicate) {
    updateModalImagePreview(null);
  } else {
    updateModalImagePreview(art);
  }

  if (!dialog.open) {
    dialog.showModal();
  }

  const nameInput = document.getElementById('art-nombre');
  if (nameInput) {
    nameInput.focus();
    if (isDuplicate) {
      nameInput.select();
    }
  }
}

function openDuplicateArticleModal(sourceArt, extraOptions = {}) {
  if (!sourceArt) return;
  const dupDialog = document.getElementById('duplicate-search-dialog');
  if (dupDialog && dupDialog.open) {
    dupDialog.close();
  }
  const pendingFactCtx = STATE.pendingFactMissingBarcodeContext || null;
  const mergedOptions = {
    isDuplicate: true,
    ...extraOptions
  };
  if (pendingFactCtx && !mergedOptions.prefillBarcode && !mergedOptions.prefillScaleCode5) {
    if (pendingFactCtx.scaleInfo && !pendingFactCtx.scaleInfo.art && pendingFactCtx.scaleInfo.artCode5) {
      mergedOptions.prefillScaleCode5 = pendingFactCtx.scaleInfo.artCode5;
    } else if (pendingFactCtx.code) {
      mergedOptions.prefillBarcode = pendingFactCtx.code;
    }
  }
  openArticleModal(sourceArt, mergedOptions);
  if (typeof window.__fcrApplyPendingSupplierToArticleModal === 'function') {
    window.__fcrApplyPendingSupplierToArticleModal();
  }
}

function openDuplicateSearchDialog() {
  const dupDialog = document.getElementById('duplicate-search-dialog');
  if (!dupDialog) return;
  const searchInput = document.getElementById('dup-search-input');
  if (searchInput) {
    searchInput.value = '';
  }
  renderDuplicateSearchResults('');
  if (!dupDialog.open) {
    dupDialog.showModal();
  }
  if (searchInput) {
    searchInput.focus();
  }
}

function renderDuplicateSearchResults(rawQuery = '') {
  const tbody = document.getElementById('dup-search-tbody');
  const statusEl = document.getElementById('dup-search-status');
  if (!tbody) return;

  const q = rawQuery.trim().toLowerCase();
  const tokens = q ? q.split(/\s+/).filter(Boolean) : [];

  const matches = [];
  for (const art of STATE.articulos) {
    if (art.bl === 1) continue;
    if (tokens.length > 0) {
      const codeStr = String(art.c || '').toLowerCase();
      const nameStr = String(art.n || '').toLowerCase();
      const bcJoined = Array.isArray(art.bc) ? art.bc.map((b) => String(b.c).toLowerCase()).join(' ') : '';
      const rubroObj = STATE.rubrosMap.get(Number(art.r));
      const provObj = STATE.proveedoresMap.get(Number(art.p));
      const rubName = rubroObj ? rubroObj.nombre.toLowerCase() : '';
      const provName = provObj ? provObj.nombre.toLowerCase() : '';
      const haystack = `${codeStr} ${nameStr} ${bcJoined} ${rubName} ${provName}`;
      let allMatch = true;
      for (const tk of tokens) {
        if (!haystack.includes(tk)) {
          allMatch = false;
          break;
        }
      }
      if (!allMatch) continue;
    }
    matches.push(art);
    if (matches.length >= 40) break;
  }

  if (statusEl) {
    statusEl.textContent = q
      ? `Mostrando primeros ${matches.length} resultados para "${rawQuery.trim()}"`
      : `Mostrando primeros ${matches.length} artículos activos (escribí arriba para buscar por código o nombre):`;
  }

  tbody.textContent = '';
  if (matches.length === 0) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = 5;
    td.className = 'table-loading-cell';
    td.textContent = 'No se encontraron artículos que coincidan con la búsqueda.';
    tr.appendChild(td);
    tbody.appendChild(tr);
    return;
  }

  const fragment = document.createDocumentFragment();
  matches.forEach((art) => {
    const tr = document.createElement('tr');

    const th = document.createElement('th');
    th.scope = 'row';
    th.innerHTML = `<div class="price-cell-stack"><span class="art-code-pill">#${art.c}</span><span class="art-title-text">${art.n}</span></div>`;
    tr.appendChild(th);

    const tdRubProv = document.createElement('td');
    const rubroObj = STATE.rubrosMap.get(Number(art.r));
    const provObj = STATE.proveedoresMap.get(Number(art.p));
    tdRubProv.innerHTML = `<div class="price-cell-stack"><strong style="font-size:0.8rem;">${rubroObj ? rubroObj.nombre : 'Sin rubro'}</strong><span class="price-neto-val">${provObj ? provObj.nombre : 'Sin proveedor'}</span></div>`;
    tr.appendChild(tdRubProv);

    const tdCosto = document.createElement('td');
    tdCosto.innerHTML = `<div class="price-cell-stack"><strong>$ ${formatArs(art.cfn)}</strong><span class="price-neto-val">Neto: $ ${formatArs(art.cn)} (${art.iva}%)</span></div>`;
    tr.appendChild(tdCosto);

    const tdPrecios = document.createElement('td');
    tdPrecios.innerHTML = `<div class="price-cell-stack"><span class="price-final-val">Min: $ ${formatArs(art.p1f)} (${art.m1}%)</span><span class="price-neto-val" style="color:var(--success); font-weight:700;">May: $ ${formatArs(art.p2f)} (${art.m2}%)</span></div>`;
    tr.appendChild(tdPrecios);

    const tdAct = document.createElement('td');
    const btnSelectDup = document.createElement('button');
    btnSelectDup.type = 'button';
    btnSelectDup.className = 'btn-primary btn-sm';
    btnSelectDup.style.width = 'auto';
    btnSelectDup.textContent = 'Duplicar';
    btnSelectDup.addEventListener('click', () => {
      openDuplicateArticleModal(art);
    });
    tdAct.appendChild(btnSelectDup);
    tr.appendChild(tdAct);

    fragment.appendChild(tr);
  });

  tbody.appendChild(fragment);
}

function updateModalImagePreview(artLike) {
  const previewImg = document.getElementById('art-preview-img');
  const badge = document.getElementById('art-img-source-badge');
  if (!artLike && !STATE.currentEditImage) {
    previewImg.src = 'assets/img/icon-192.png';
    badge.textContent = 'Sin fotografía asignada (Usá Búsqueda Inteligente o Subir Foto)';
    return;
  }
  const resolved = resolveArticleImageUrl({
    ...(artLike || { id: 1, n: '', bc: [] }),
    im: STATE.currentEditImage
  });
  previewImg.src = resolved.url;
  previewImg.onerror = () => {
    previewImg.onerror = null;
    previewImg.src = 'assets/img/icon-192.png';
  };
  badge.textContent = resolved.isSystem
    ? '✓ Fotografía Oficial en Sistema'
    : '✨ Fotografía Web Inteligente';
}

async function persistPriceConfigsToServer() {
  try {
    const resCfg = await fetch('api/catalog.php', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'save_price_configs',
        configuracionesPrecios: STATE.configuracionesPrecios
      })
    });
    if (resCfg.ok) {
      const jsonCfg = await resCfg.json();
      if (jsonCfg && Array.isArray(jsonCfg.configuracionesPrecios)) {
        STATE.configuracionesPrecios = jsonCfg.configuracionesPrecios;
        STATE.configPreciosMap.clear();
        STATE.configuracionesPrecios.forEach((c) => STATE.configPreciosMap.set(Number(c.id), c));
      }
      if (jsonCfg && jsonCfg.gondolaQueue) {
        STATE.gondolaQueue = normalizeGondolaQueueMap(jsonCfg.gondolaQueue);
        saveLocalGondolaQueue();
        updateGondolaMenuBadges();
      }
    }
  } catch {
    // Offline tolerance
  }
}

function openNewPriceConfigModal(existingCfg = null) {
  const dlg = document.getElementById('price-config-dialog');
  if (!dlg) return;
  const alertEl = document.getElementById('price-config-form-alert');
  if (alertEl) alertEl.hidden = true;
  const editIdInp = document.getElementById('new-cfg-edit-id');
  const badgeEl = document.getElementById('price-config-dialog-badge');
  const titleEl = document.getElementById('price-config-dialog-title');
  const linkedInfoEl = document.getElementById('price-config-linked-info');
  const inpNom = document.getElementById('new-cfg-nombre');
  const selAlic = document.getElementById('new-cfg-alicuota');
  const inpMin = document.getElementById('new-cfg-margen-min');
  const inpMay = document.getElementById('new-cfg-margen-may');
  const btnSub = document.getElementById('btn-submit-price-config');

  if (existingCfg && Number(existingCfg.id) > 0) {
    const alicInit = resolveAlicuotaForConfig(existingCfg);
    const linkedCount = STATE.articulos.filter(
      (a) => Number(a.ucp) === 1 && Number(a.cp) === Number(existingCfg.id)
    ).length;
    if (editIdInp) editIdInp.value = String(existingCfg.id);
    if (badgeEl) badgeEl.textContent = `MODIFICANDO CONFIGURACIÓN #${existingCfg.id}`;
    if (titleEl) titleEl.textContent = existingCfg.nombre || 'Editar Configuración de Precios';
    if (linkedInfoEl) {
      linkedInfoEl.textContent = `🔗 ${linkedCount.toLocaleString('es-AR')} artículo(s) vinculado(s) a esta configuración.`;
      linkedInfoEl.hidden = false;
    }
    if (inpNom) inpNom.value = String(existingCfg.nombre || '').toUpperCase();
    if (selAlic) selAlic.value = String(alicInit.id);
    if (inpMin) inpMin.value = String(existingCfg.margenMinorista ?? 0);
    if (inpMay) inpMay.value = String(existingCfg.margenMayorista ?? 0);
    if (btnSub) {
      btnSub.disabled = false;
      btnSub.textContent = '💾 Guardar Cambios';
    }
  } else {
    if (editIdInp) editIdInp.value = '';
    if (badgeEl) badgeEl.textContent = 'CONFIGURACIÓN DE PRECIOS';
    if (titleEl) titleEl.textContent = 'Nueva Configuración de Precios';
    if (linkedInfoEl) {
      linkedInfoEl.textContent = '';
      linkedInfoEl.hidden = true;
    }
    if (inpNom) inpNom.value = '';
    if (selAlic && STATE.alicuotasMap.has(5)) selAlic.value = '5';
    if (inpMin) inpMin.value = '49';
    if (inpMay) inpMay.value = '18';
    if (btnSub) {
      btnSub.disabled = false;
      btnSub.textContent = '💾 Crear Configuración';
    }
  }

  if (!dlg.open) dlg.showModal();
  requestAnimationFrame(() => {
    if (inpNom) {
      inpNom.focus();
      if (existingCfg) inpNom.select();
    }
  });
}
window.openPriceConfigModal = openNewPriceConfigModal;

