// ============================================================================
// MÓDULO: ABM MARCA Y ABM RUBRO (ALTA, BAJA Y MODIFICACIÓN)
// ============================================================================

function rebuildRubrosAndMarcasMaps() {
  STATE.rubros.sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es-AR'));
  STATE.marcas.sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es-AR'));

  STATE.rubrosMap.clear();
  STATE.rubros.forEach((r) => STATE.rubrosMap.set(Number(r.id), r));

  STATE.marcasMap.clear();
  STATE.marcas.forEach((m) => STATE.marcasMap.set(Number(m.id), m));
}

function saveLocalAbmCatalogOverrides() {
  try {
    localStorage.setItem(
      ABM_CATALOG_STORAGE_KEY,
      JSON.stringify({
        rubros: STATE.rubros,
        marcas: STATE.marcas
      })
    );
  } catch {}
}

function applyLocalAbmCatalogOverrides() {
  try {
    const raw = localStorage.getItem(ABM_CATALOG_STORAGE_KEY);
    if (!raw) return;
    const parsed = JSON.parse(raw);
    if (parsed && Array.isArray(parsed.rubros) && parsed.rubros.length > 0) {
      STATE.rubros = parsed.rubros;
    }
    if (parsed && Array.isArray(parsed.marcas) && parsed.marcas.length > 0) {
      STATE.marcas = parsed.marcas;
    }
  } catch {}
}

function findNextFreeRubroCode(excludeId = null) {
  let maxCode = 44;
  for (const r of STATE.rubros) {
    if (excludeId !== null && Number(r.id) === Number(excludeId)) continue;
    const c = parseInt(String(r.codigo ?? r.id ?? '').trim(), 10);
    if (!isNaN(c) && c > maxCode) maxCode = c;
  }
  return String(maxCode + 1);
}

function findNextFreeMarcaCode(excludeId = null) {
  let maxCode = 2594;
  for (const m of STATE.marcas) {
    if (excludeId !== null && Number(m.id) === Number(excludeId)) continue;
    const c = parseInt(String(m.codigo ?? m.id ?? '').trim(), 10);
    if (!isNaN(c) && c > maxCode) maxCode = c;
  }
  return String(maxCode + 1);
}

function countArticlesByRubroMap() {
  const counts = new Map();
  let totalWithRubro = 0;
  for (const art of STATE.articulos) {
    const rId = Number(art.r) || 0;
    if (rId > 0) {
      counts.set(rId, (counts.get(rId) || 0) + 1);
      totalWithRubro++;
    }
  }
  return { counts, totalWithRubro };
}

function countArticlesByMarcaMap() {
  const counts = new Map();
  let totalWithMarca = 0;
  for (const art of STATE.articulos) {
    const mId = Number(art.mk) || 0;
    if (mId > 0) {
      counts.set(mId, (counts.get(mId) || 0) + 1);
      totalWithMarca++;
    }
  }
  return { counts, totalWithMarca };
}

function resetAbmRubroForm() {
  STATE.editingRubroId = null;
  const idInp = document.getElementById('abm-rubro-id');
  const codInp = document.getElementById('abm-rubro-codigo');
  const nomInp = document.getElementById('abm-rubro-nombre');
  const bajaChk = document.getElementById('abm-rubro-baja');
  const badgeEl = document.getElementById('abm-rubro-form-mode-badge');
  const saveBtn = document.getElementById('btn-abm-rubro-save');
  const cancelBtn = document.getElementById('btn-abm-rubro-cancel');
  const alertEl = document.getElementById('abm-rubro-alert');

  if (idInp) idInp.value = '';
  if (codInp) codInp.value = findNextFreeRubroCode();
  if (nomInp) nomInp.value = '';
  if (bajaChk) bajaChk.checked = false;
  if (badgeEl) badgeEl.textContent = 'ALTA DE NUEVO RUBRO';
  if (saveBtn) saveBtn.textContent = '💾 Guardar Nuevo Rubro';
  if (cancelBtn) cancelBtn.hidden = true;
  if (alertEl) alertEl.hidden = true;
}

function editRubroInAbm(rubro) {
  if (!rubro) return;
  const dialog = document.getElementById('abm-rubro-edit-dialog');
  if (!dialog) return;

  const idInp = document.getElementById('abm-rubro-modal-id');
  const codInp = document.getElementById('abm-rubro-modal-codigo');
  const nomInp = document.getElementById('abm-rubro-modal-nombre');
  const bajaChk = document.getElementById('abm-rubro-modal-baja');
  const bajaHint = document.getElementById('abm-rubro-modal-baja-hint');
  const badgeEl = document.getElementById('abm-rubro-modal-badge');
  const titleEl = document.getElementById('abm-rubro-edit-dialog-title');
  const metaEl = document.getElementById('abm-rubro-modal-meta');
  const linkedEl = document.getElementById('abm-rubro-modal-linked');
  const saveBtn = document.getElementById('btn-save-abm-rubro-modal');
  const alertEl = document.getElementById('abm-rubro-modal-alert');
  const linkedCount = countArticlesByRubroMap().counts.get(Number(rubro.id)) || 0;

  if (alertEl) alertEl.hidden = true;
  if (saveBtn) saveBtn.disabled = false;
  if (idInp) idInp.value = String(rubro.id);
  if (codInp) codInp.value = String(rubro.codigo ?? rubro.id);
  if (nomInp) nomInp.value = String(rubro.nombre || '').toUpperCase();
  if (badgeEl) badgeEl.textContent = `MODIFICANDO RUBRO #${rubro.codigo ?? rubro.id}`;
  if (titleEl) titleEl.textContent = String(rubro.nombre || 'Modificar Rubro').toUpperCase();
  if (metaEl) metaEl.textContent = `ID interno: ${rubro.id}`;
  if (linkedEl) {
    linkedEl.className = linkedCount > 0 ? 'badge badge--gold' : 'price-neto-val';
    linkedEl.textContent = `${linkedCount.toLocaleString('es-AR')} artículo(s) vinculado(s)`;
  }

  if (bajaChk) {
    bajaChk.checked = Number(rubro.bl) === 1;
    bajaChk.disabled = false;
    bajaChk.title = '';
  }
  if (bajaHint) {
    if (linkedCount > 0) {
      bajaHint.textContent = `ℹ️ Este rubro tiene ${linkedCount.toLocaleString('es-AR')} artículo(s) vinculado(s).`;
      bajaHint.hidden = false;
    } else {
      bajaHint.textContent = '';
      bajaHint.hidden = true;
    }
  }

  if (!dialog.open) {
    dialog.showModal();
  }
  requestAnimationFrame(() => {
    if (nomInp) {
      nomInp.focus();
      nomInp.select();
    }
  });
}

function renderAbmRubrosSection() {
  const tbody = document.getElementById('abm-rubros-tbody');
  if (!tbody) return;

  const { counts, totalWithRubro } = countArticlesByRubroMap();
  const nextFree = findNextFreeRubroCode(STATE.editingRubroId);

  let activeCount = 0;
  let bajaCount = 0;
  let withArtsCount = 0;
  for (const r of STATE.rubros) {
    if (Number(r.bl) === 1) bajaCount++;
    else activeCount++;
    if ((counts.get(Number(r.id)) || 0) > 0) withArtsCount++;
  }

  const kpiActive = document.getElementById('kpi-rubros-active');
  const kpiSub = document.getElementById('kpi-rubros-total-sub');
  const kpiNext = document.getElementById('kpi-rubros-next-code');
  const kpiWithArts = document.getElementById('kpi-rubros-with-arts');
  const kpiLinked = document.getElementById('kpi-rubros-linked-arts');

  if (kpiActive) kpiActive.textContent = activeCount.toLocaleString('es-AR');
  if (kpiSub) {
    kpiSub.textContent = bajaCount > 0
      ? `${STATE.rubros.length} totales (${bajaCount} en baja lógica)`
      : `${STATE.rubros.length} rubros en el padrón`;
  }
  if (kpiNext) kpiNext.textContent = `#${nextFree}`;
  if (kpiWithArts) kpiWithArts.textContent = `${withArtsCount.toLocaleString('es-AR')} de ${STATE.rubros.length}`;
  if (kpiLinked) kpiLinked.textContent = totalWithRubro.toLocaleString('es-AR');

  if (!STATE.editingRubroId) {
    const codInp = document.getElementById('abm-rubro-codigo');
    if (codInp && !codInp.value.trim()) codInp.value = nextFree;
  }

  const q = normalizeStr(document.getElementById('abm-rubro-q')?.value || '');
  const estado = document.getElementById('abm-rubro-filter-estado')?.value || 'activos';
  const orden = document.getElementById('abm-rubro-orden')?.value || 'nombre';

  const filtered = STATE.rubros.filter((r) => {
    const isBaja = Number(r.bl) === 1;
    const artCount = counts.get(Number(r.id)) || 0;
    if (estado === 'activos' && isBaja) return false;
    if (estado === 'baja' && !isBaja) return false;
    if (estado === 'con_articulos' && artCount <= 0) return false;
    if (estado === 'sin_articulos' && artCount > 0) return false;

    if (q) {
      const hay = normalizeStr(`${r.codigo ?? ''} ${r.id} ${r.nombre || ''}`);
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  filtered.sort((a, b) => {
    if (orden === 'codigo') {
      return (Number(a.codigo ?? a.id) || 0) - (Number(b.codigo ?? b.id) || 0);
    }
    if (orden === 'articulos') {
      const diff = (counts.get(Number(b.id)) || 0) - (counts.get(Number(a.id)) || 0);
      if (diff !== 0) return diff;
    }
    return String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es-AR');
  });

  const statusEl = document.getElementById('abm-rubro-status-msg');
  if (statusEl) {
    statusEl.textContent = `Mostrando ${filtered.length} de ${STATE.rubros.length} rubros registrados`;
  }

  tbody.textContent = '';
  if (filtered.length === 0) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = 5;
    td.className = 'table-loading-cell';
    td.textContent = 'No se encontraron rubros con los filtros seleccionados.';
    tr.appendChild(td);
    tbody.appendChild(tr);
    return;
  }

  const frag = document.createDocumentFragment();
  filtered.forEach((r) => {
    const tr = document.createElement('tr');
    if (STATE.lastSavedRubroId && Number(STATE.lastSavedRubroId) === Number(r.id)) {
      tr.style.background = 'rgba(212, 160, 23, 0.14)';
      tr.style.transition = 'background 1.2s ease';
      setTimeout(() => {
        tr.style.background = '';
      }, 2200);
    }
    const isBaja = Number(r.bl) === 1;
    const artCount = counts.get(Number(r.id)) || 0;

    // 1. Código / ID
    const th = document.createElement('th');
    th.scope = 'row';
    th.innerHTML = `<div class="price-cell-stack"><span class="art-code-pill">#${r.codigo ?? r.id}</span><span class="price-neto-val">ID interno: ${r.id}</span></div>`;
    tr.appendChild(th);

    // 2. Nombre del Rubro
    const tdNom = document.createElement('td');
    const nomStrong = document.createElement('strong');
    nomStrong.style.fontSize = '0.92rem';
    nomStrong.textContent = r.nombre;
    tdNom.appendChild(nomStrong);
    tr.appendChild(tdNom);

    // 3. Artículos Vinculados + botón rápido para filtrar catálogo
    const tdArts = document.createElement('td');
    const artsStack = document.createElement('div');
    artsStack.style.display = 'flex';
    artsStack.style.alignItems = 'center';
    artsStack.style.gap = '0.5rem';
    artsStack.style.flexWrap = 'wrap';

    const badgeArts = document.createElement('span');
    badgeArts.className = artCount > 0 ? 'badge badge--gold' : 'price-neto-val';
    badgeArts.textContent = `${artCount.toLocaleString('es-AR')} artículo(s)`;
    artsStack.appendChild(badgeArts);

    if (artCount > 0) {
      const btnVerArts = document.createElement('button');
      btnVerArts.type = 'button';
      btnVerArts.className = 'btn-secondary btn-sm';
      btnVerArts.style.fontSize = '0.72rem';
      btnVerArts.style.padding = '0.2rem 0.5rem';
      btnVerArts.textContent = '🔎 Ver productos';
      btnVerArts.addEventListener('click', () => {
        const filterRubro = document.getElementById('filter-rubro');
        const filterMarca = document.getElementById('filter-marca');
        const filterQ = document.getElementById('filter-q');
        if (filterRubro) filterRubro.value = String(r.id);
        if (filterMarca) filterMarca.value = '';
        if (filterQ) filterQ.value = '';
        applyCatalogFilters(1);
        document.querySelectorAll('.erp-section').forEach((sec) => {
          sec.hidden = sec.id !== 'sec-articulos';
        });
        updateTopbarModuleState('sec-articulos');
      });
      artsStack.appendChild(btnVerArts);
    }
    tdArts.appendChild(artsStack);
    tr.appendChild(tdArts);

    // 4. Estado
    const tdEst = document.createElement('td');
    tdEst.innerHTML = isBaja
      ? `<span class="mini-tag mini-tag--baja">BAJA ${r.fb || ''}</span>`
      : `<span class="badge badge--green">ACTIVO</span>`;
    tr.appendChild(tdEst);

    // 5. Acciones (Modificar / Baja o Eliminar)
    const tdAct = document.createElement('td');
    const actWrap = document.createElement('div');
    actWrap.style.display = 'flex';
    actWrap.style.gap = '0.4rem';
    actWrap.style.flexWrap = 'wrap';

    const uniformAbmBtnStyle = 'width:158px; min-height:32px; display:inline-flex; align-items:center; justify-content:center; box-sizing:border-box; white-space:nowrap;';

    const btnEdit = document.createElement('button');
    btnEdit.type = 'button';
    btnEdit.className = 'btn-secondary btn-sm';
    btnEdit.style.cssText = uniformAbmBtnStyle;
    btnEdit.textContent = '✏️ Modificar';
    btnEdit.addEventListener('click', () => editRubroInAbm(r));
    actWrap.appendChild(btnEdit);

    const btnBaja = document.createElement('button');
    btnBaja.type = 'button';
    btnBaja.className = 'btn-secondary btn-sm';
    btnBaja.style.cssText = uniformAbmBtnStyle;
    if (isBaja) {
      btnBaja.textContent = '♻️ Reactivar';
      btnBaja.style.borderColor = 'rgba(49, 196, 141, 0.45)';
      btnBaja.style.color = 'var(--success)';
    } else if (artCount === 0) {
      btnBaja.textContent = '🗑️ Eliminar / Baja';
      btnBaja.style.borderColor = 'rgba(240, 82, 82, 0.45)';
      btnBaja.style.color = 'var(--danger)';
    } else {
      btnBaja.textContent = '⛔ Dar de Baja';
      btnBaja.style.borderColor = 'rgba(240, 82, 82, 0.45)';
      btnBaja.style.color = 'var(--danger)';
    }
    btnBaja.addEventListener('click', () => toggleOrDeleteRubro(r, artCount));
    actWrap.appendChild(btnBaja);

    tdAct.appendChild(actWrap);
    tr.appendChild(tdAct);

    frag.appendChild(tr);
  });

  tbody.appendChild(frag);
}

async function toggleOrDeleteRubro(rubro, linkedCount) {
  if (!rubro) return;
  const isBaja = Number(rubro.bl) === 1;
  const alertEl = document.getElementById('abm-rubro-alert');
  const okEl = document.getElementById('abm-rubro-success');
  if (alertEl) alertEl.hidden = true;
  if (okEl) okEl.hidden = true;

  let mode = 'baja';
  if (!isBaja && linkedCount === 0) {
    const confirmDelete = await showBrandConfirmDialog(
      `El rubro "${rubro.nombre}" (#${rubro.codigo ?? rubro.id}) no tiene artículos vinculados.\n\n¿Querés ELIMINARLO definitivamente del padrón?\n(Si presionás Cancelar, se aplicará solo Baja Lógica).`
    );
    mode = confirmDelete ? 'delete' : 'baja';
  } else if (!isBaja && linkedCount > 0) {
    const confirmBaja = await showBrandConfirmDialog(
      `El rubro "${rubro.nombre}" tiene ${linkedCount} artículo(s) vinculado(s).\n¿Confirmás pasarlo a BAJA LÓGICA (inactivo)?`
    );
    if (!confirmBaja) return;
    mode = 'baja';
  }

  try {
    await fetch('api/catalog.php', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'delete_rubro',
        id: rubro.id,
        mode
      })
    });
  } catch {}

  if (mode === 'delete' && linkedCount === 0) {
    STATE.rubros = STATE.rubros.filter((r) => Number(r.id) !== Number(rubro.id));
    if (okEl) {
      okEl.innerHTML = `<strong>Rubro eliminado:</strong> Se eliminó el rubro <strong>#${rubro.codigo ?? rubro.id} — ${rubro.nombre}</strong>.`;
      okEl.hidden = false;
    }
  } else {
    rubro.bl = isBaja ? 0 : 1;
    rubro.fb = rubro.bl === 1 ? todayFormatted() : null;
    if (okEl) {
      okEl.innerHTML = rubro.bl === 1
        ? `<strong>Baja lógica aplicada:</strong> El rubro <strong>#${rubro.codigo ?? rubro.id} — ${rubro.nombre}</strong> quedó marcado como inactivo.`
        : `<strong>Rubro reactivado:</strong> El rubro <strong>#${rubro.codigo ?? rubro.id} — ${rubro.nombre}</strong> volvió a estar activo.`;
      okEl.hidden = false;
    }
  }

  if (STATE.editingRubroId === Number(rubro.id)) {
    resetAbmRubroForm();
  }
  rebuildRubrosAndMarcasMaps();
  saveLocalAbmCatalogOverrides();
  populateMasterSelects();
  updateKpis();
  renderAbmRubrosSection();
  applyCatalogFilters(STATE.currentPage);
}

function resetAbmMarcaForm() {
  STATE.editingMarcaId = null;
  const idInp = document.getElementById('abm-marca-id');
  const codInp = document.getElementById('abm-marca-codigo');
  const nomInp = document.getElementById('abm-marca-nombre');
  const bajaChk = document.getElementById('abm-marca-baja');
  const badgeEl = document.getElementById('abm-marca-form-mode-badge');
  const saveBtn = document.getElementById('btn-abm-marca-save');
  const cancelBtn = document.getElementById('btn-abm-marca-cancel');
  const alertEl = document.getElementById('abm-marca-alert');

  if (idInp) idInp.value = '';
  if (codInp) codInp.value = findNextFreeMarcaCode();
  if (nomInp) nomInp.value = '';
  if (bajaChk) {
    bajaChk.checked = false;
    bajaChk.disabled = false;
    bajaChk.title = '';
  }
  if (badgeEl) badgeEl.textContent = 'ALTA DE NUEVA MARCA';
  if (saveBtn) saveBtn.textContent = '💾 Guardar Nueva Marca';
  if (cancelBtn) cancelBtn.hidden = true;
  if (alertEl) alertEl.hidden = true;
}

function editMarcaInAbm(marca) {
  if (!marca) return;
  const dialog = document.getElementById('abm-marca-edit-dialog');
  if (!dialog) return;

  const idInp = document.getElementById('abm-marca-modal-id');
  const codInp = document.getElementById('abm-marca-modal-codigo');
  const nomInp = document.getElementById('abm-marca-modal-nombre');
  const bajaChk = document.getElementById('abm-marca-modal-baja');
  const bajaHint = document.getElementById('abm-marca-modal-baja-hint');
  const badgeEl = document.getElementById('abm-marca-modal-badge');
  const titleEl = document.getElementById('abm-marca-edit-dialog-title');
  const metaEl = document.getElementById('abm-marca-modal-meta');
  const linkedEl = document.getElementById('abm-marca-modal-linked');
  const saveBtn = document.getElementById('btn-save-abm-marca-modal');
  const alertEl = document.getElementById('abm-marca-modal-alert');
  const linkedCount = countArticlesByMarcaMap().counts.get(Number(marca.id)) || 0;

  if (alertEl) alertEl.hidden = true;
  if (saveBtn) saveBtn.disabled = false;
  if (idInp) idInp.value = String(marca.id);
  if (codInp) codInp.value = String(marca.codigo ?? marca.id);
  if (nomInp) nomInp.value = String(marca.nombre || '').toUpperCase();
  if (badgeEl) badgeEl.textContent = `MODIFICANDO MARCA #${marca.codigo ?? marca.id}`;
  if (titleEl) titleEl.textContent = String(marca.nombre || 'Modificar Marca').toUpperCase();
  if (metaEl) metaEl.textContent = `ID interno: ${marca.id}`;
  if (linkedEl) {
    linkedEl.className = linkedCount > 0 ? 'badge badge--gold' : 'price-neto-val';
    linkedEl.textContent = `${linkedCount.toLocaleString('es-AR')} artículo(s) vinculado(s)`;
  }

  if (bajaChk) {
    if (linkedCount > 0) {
      bajaChk.checked = false;
      bajaChk.disabled = true;
      bajaChk.title = `No se puede dar de baja: tiene ${linkedCount} producto(s) asociado(s)`;
      if (bajaHint) {
        bajaHint.textContent = `🔒 No se puede dar de baja porque tiene ${linkedCount.toLocaleString('es-AR')} artículo(s) vinculado(s).`;
        bajaHint.hidden = false;
      }
    } else {
      bajaChk.checked = Number(marca.bl) === 1;
      bajaChk.disabled = false;
      bajaChk.title = '';
      if (bajaHint) {
        bajaHint.textContent = '';
        bajaHint.hidden = true;
      }
    }
  }

  if (!dialog.open) {
    dialog.showModal();
  }
  requestAnimationFrame(() => {
    if (nomInp) {
      nomInp.focus();
      nomInp.select();
    }
  });
}

function applyAbmMarcasFilters(page = 1) {
  const { counts, totalWithMarca } = countArticlesByMarcaMap();
  const nextFree = findNextFreeMarcaCode(STATE.editingMarcaId);

  let activeCount = 0;
  let bajaCount = 0;
  let withArtsCount = 0;
  for (const m of STATE.marcas) {
    if (Number(m.bl) === 1) bajaCount++;
    else activeCount++;
    if ((counts.get(Number(m.id)) || 0) > 0) withArtsCount++;
  }

  const kpiActive = document.getElementById('kpi-marcas-active');
  const kpiSub = document.getElementById('kpi-marcas-total-sub');
  const kpiNext = document.getElementById('kpi-marcas-next-code');
  const kpiWithArts = document.getElementById('kpi-marcas-with-arts');
  const kpiLinked = document.getElementById('kpi-marcas-linked-arts');

  if (kpiActive) kpiActive.textContent = activeCount.toLocaleString('es-AR');
  if (kpiSub) {
    kpiSub.textContent = bajaCount > 0
      ? `${STATE.marcas.length.toLocaleString('es-AR')} totales (${bajaCount} en baja)`
      : `${STATE.marcas.length.toLocaleString('es-AR')} marcas en el padrón`;
  }
  if (kpiNext) kpiNext.textContent = `#${nextFree}`;
  if (kpiWithArts) kpiWithArts.textContent = `${withArtsCount.toLocaleString('es-AR')} de ${STATE.marcas.length.toLocaleString('es-AR')}`;
  if (kpiLinked) kpiLinked.textContent = totalWithMarca.toLocaleString('es-AR');

  if (!STATE.editingMarcaId) {
    const codInp = document.getElementById('abm-marca-codigo');
    if (codInp && !codInp.value.trim()) codInp.value = nextFree;
  }

  const q = normalizeStr(document.getElementById('abm-marca-q')?.value || '');
  const estado = document.getElementById('abm-marca-filter-estado')?.value || 'activas';
  const orden = document.getElementById('abm-marca-orden')?.value || 'nombre';

  STATE.abmMarcasFiltered = STATE.marcas.filter((m) => {
    const isBaja = Number(m.bl) === 1;
    const artCount = counts.get(Number(m.id)) || 0;
    if (estado === 'activas' && isBaja && q.length < 2) return false;
    if (estado === 'baja' && !isBaja) return false;
    if (estado === 'con_articulos' && artCount <= 0) return false;
    if (estado === 'sin_articulos' && artCount > 0) return false;

    if (q) {
      const hay = normalizeStr(`${m.codigo ?? ''} ${m.id} ${m.nombre || ''}`);
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  STATE.abmMarcasFiltered.sort((a, b) => {
    if (orden === 'codigo') {
      const ca = parseInt(String(a.codigo ?? a.id), 10) || 0;
      const cb = parseInt(String(b.codigo ?? b.id), 10) || 0;
      if (ca !== cb) return ca - cb;
    } else if (orden === 'articulos') {
      const diff = (counts.get(Number(b.id)) || 0) - (counts.get(Number(a.id)) || 0);
      if (diff !== 0) return diff;
    }
    return String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es-AR');
  });

  const totalPages = Math.max(1, Math.ceil(STATE.abmMarcasFiltered.length / PAGE_SIZE));
  STATE.abmMarcasPage = Math.min(Math.max(1, page), totalPages);
  renderAbmMarcasTable(counts);
}

function renderAbmMarcasTable(countsMap = null) {
  const tbody = document.getElementById('abm-marcas-tbody');
  if (!tbody) return;
  const counts = countsMap || countArticlesByMarcaMap().counts;

  const total = STATE.abmMarcasFiltered.length;
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const startIdx = (STATE.abmMarcasPage - 1) * PAGE_SIZE;
  const pageItems = STATE.abmMarcasFiltered.slice(startIdx, startIdx + PAGE_SIZE);

  const statusEl = document.getElementById('abm-marca-status-msg');
  const prevBtn = document.getElementById('btn-abm-marca-prev');
  const nextBtn = document.getElementById('btn-abm-marca-next');
  const pageInd = document.getElementById('abm-marca-page-ind');

  if (statusEl) {
    statusEl.textContent = `Mostrando ${pageItems.length} de ${total.toLocaleString('es-AR')} marcas encontradas`;
  }
  syncUnifiedPaginationControls(pageInd, prevBtn, nextBtn, STATE.abmMarcasPage, totalPages, (nextPage) => {
    STATE.abmMarcasPage = nextPage;
    renderAbmMarcasTable();
  });

  tbody.textContent = '';
  if (pageItems.length === 0) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = 5;
    td.className = 'table-loading-cell';
    td.textContent = 'No se encontraron marcas con los filtros seleccionados.';
    tr.appendChild(td);
    tbody.appendChild(tr);
    return;
  }

  const frag = document.createDocumentFragment();
  pageItems.forEach((m) => {
    const tr = document.createElement('tr');
    if (STATE.lastSavedMarcaId && Number(STATE.lastSavedMarcaId) === Number(m.id)) {
      tr.style.background = 'rgba(212, 160, 23, 0.14)';
      tr.style.transition = 'background 1.2s ease';
      setTimeout(() => {
        tr.style.background = '';
      }, 2200);
    }
    const isBaja = Number(m.bl) === 1;
    const artCount = counts.get(Number(m.id)) || 0;

    // 1. Código / ID
    const th = document.createElement('th');
    th.scope = 'row';
    th.innerHTML = `<div class="price-cell-stack"><span class="art-code-pill">#${m.codigo ?? m.id}</span><span class="price-neto-val">ID interno: ${m.id}</span></div>`;
    tr.appendChild(th);

    // 2. Nombre de la Marca
    const tdNom = document.createElement('td');
    const nomStrong = document.createElement('strong');
    nomStrong.style.fontSize = '0.92rem';
    nomStrong.textContent = m.nombre;
    tdNom.appendChild(nomStrong);
    tr.appendChild(tdNom);

    // 3. Artículos Vinculados
    const tdArts = document.createElement('td');
    const artsStack = document.createElement('div');
    artsStack.style.display = 'flex';
    artsStack.style.alignItems = 'center';
    artsStack.style.gap = '0.5rem';
    artsStack.style.flexWrap = 'wrap';

    const badgeArts = document.createElement('span');
    badgeArts.className = artCount > 0 ? 'badge badge--gold' : 'price-neto-val';
    badgeArts.textContent = `${artCount.toLocaleString('es-AR')} artículo(s)`;
    artsStack.appendChild(badgeArts);

    if (artCount > 0) {
      const btnVerArts = document.createElement('button');
      btnVerArts.type = 'button';
      btnVerArts.className = 'btn-secondary btn-sm';
      btnVerArts.style.fontSize = '0.72rem';
      btnVerArts.style.padding = '0.2rem 0.5rem';
      btnVerArts.textContent = '🔎 Ver productos';
      btnVerArts.addEventListener('click', () => {
        const filterRubro = document.getElementById('filter-rubro');
        const filterMarca = document.getElementById('filter-marca');
        const filterQ = document.getElementById('filter-q');
        if (filterMarca) filterMarca.value = String(m.id);
        if (filterRubro) filterRubro.value = '';
        if (filterQ) filterQ.value = '';
        applyCatalogFilters(1);
        document.querySelectorAll('.erp-section').forEach((sec) => {
          sec.hidden = sec.id !== 'sec-articulos';
        });
        updateTopbarModuleState('sec-articulos');
      });
      artsStack.appendChild(btnVerArts);
    }
    tdArts.appendChild(artsStack);
    tr.appendChild(tdArts);

    // 4. Estado
    const tdEst = document.createElement('td');
    tdEst.innerHTML = isBaja
      ? `<span class="mini-tag mini-tag--baja">BAJA ${m.fb || ''}</span>`
      : `<span class="badge badge--green">ACTIVA</span>`;
    tr.appendChild(tdEst);

    // 5. Acciones (Modificar / Baja o Eliminar)
    const tdAct = document.createElement('td');
    const actWrap = document.createElement('div');
    actWrap.style.display = 'flex';
    actWrap.style.gap = '0.4rem';
    actWrap.style.flexWrap = 'wrap';

    const uniformAbmBtnStyle = 'width:158px; min-height:32px; display:inline-flex; align-items:center; justify-content:center; box-sizing:border-box; white-space:nowrap;';

    const btnEdit = document.createElement('button');
    btnEdit.type = 'button';
    btnEdit.className = 'btn-secondary btn-sm';
    btnEdit.style.cssText = uniformAbmBtnStyle;
    btnEdit.textContent = '✏️ Modificar';
    btnEdit.addEventListener('click', () => editMarcaInAbm(m));
    actWrap.appendChild(btnEdit);

    const btnBaja = document.createElement('button');
    btnBaja.type = 'button';
    btnBaja.className = 'btn-secondary btn-sm';
    btnBaja.style.cssText = uniformAbmBtnStyle;
    if (isBaja) {
      btnBaja.textContent = '♻️ Reactivar';
      btnBaja.style.borderColor = 'rgba(49, 196, 141, 0.45)';
      btnBaja.style.color = 'var(--success)';
      btnBaja.addEventListener('click', () => toggleOrDeleteMarca(m, artCount));
    } else if (artCount === 0) {
      btnBaja.textContent = '⛔ Dar de Baja';
      btnBaja.style.borderColor = 'rgba(240, 82, 82, 0.45)';
      btnBaja.style.color = 'var(--danger)';
      btnBaja.addEventListener('click', () => toggleOrDeleteMarca(m, artCount));
    } else {
      btnBaja.textContent = '🔒 Baja bloqueada';
      btnBaja.disabled = true;
      btnBaja.title = `No se puede dar de baja una marca con ${artCount} producto(s) asociado(s)`;
      btnBaja.style.opacity = '0.5';
      btnBaja.style.cursor = 'not-allowed';
    }
    actWrap.appendChild(btnBaja);

    tdAct.appendChild(actWrap);
    tr.appendChild(tdAct);

    frag.appendChild(tr);
  });

  tbody.appendChild(frag);
}

async function toggleOrDeleteMarca(marca, linkedCount) {
  if (!marca) return;
  const isBaja = Number(marca.bl) === 1;
  const alertEl = document.getElementById('abm-marca-alert');
  const okEl = document.getElementById('abm-marca-success');
  if (alertEl) alertEl.hidden = true;
  if (okEl) okEl.hidden = true;

  if (!isBaja && linkedCount > 0) {
    if (alertEl) {
      alertEl.textContent = `NO SE PUEDE DAR DE BAJA LA MARCA "${marca.nombre}" PORQUE TIENE ${linkedCount} PRODUCTO(S) ASOCIADO(S).`;
      alertEl.hidden = false;
    }
    return;
  }

  let mode = 'baja';
  if (!isBaja && linkedCount === 0) {
    const confirmDelete = await showBrandConfirmDialog(
      `La marca "${marca.nombre}" (#${marca.codigo ?? marca.id}) no tiene artículos vinculados.\n\n¿Querés ELIMINARLA definitivamente del padrón?\n(Si presionás Cancelar, se aplicará solo Baja Lógica).`
    );
    mode = confirmDelete ? 'delete' : 'baja';
  }

  try {
    await fetch('api/catalog.php', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'delete_marca',
        id: marca.id,
        mode
      })
    });
  } catch {}

  if (mode === 'delete' && linkedCount === 0) {
    STATE.marcas = STATE.marcas.filter((m) => Number(m.id) !== Number(marca.id));
    if (okEl) {
      okEl.innerHTML = `<strong>Marca eliminada:</strong> Se eliminó la marca <strong>#${marca.codigo ?? marca.id} — ${marca.nombre}</strong>.`;
      okEl.hidden = false;
    }
  } else {
    marca.bl = isBaja ? 0 : 1;
    marca.fb = marca.bl === 1 ? todayFormatted() : null;
    if (okEl) {
      okEl.innerHTML = marca.bl === 1
        ? `<strong>Baja lógica aplicada:</strong> La marca <strong>#${marca.codigo ?? marca.id} — ${marca.nombre}</strong> quedó marcada como inactiva.`
        : `<strong>Marca reactivada:</strong> La marca <strong>#${marca.codigo ?? marca.id} — ${marca.nombre}</strong> volvió a estar activa.`;
      okEl.hidden = false;
    }
  }

  if (STATE.editingMarcaId === Number(marca.id)) {
    resetAbmMarcaForm();
  }
  rebuildRubrosAndMarcasMaps();
  saveLocalAbmCatalogOverrides();
  populateMasterSelects();
  updateKpis();
  applyAbmMarcasFilters(STATE.abmMarcasPage || 1);
  applyCatalogFilters(STATE.currentPage);
}

// ============================================================================
// MÓDULO: CLIENTES Y CUENTAS CORRIENTES + REGISTRACIÓN EN LÍNEA (CARRITO WEB)
// ============================================================================

/**
 * Validación oficial de CUIT/CUIL ARCA/AFIP por Módulo 11 (igual a campodirecto.ar)
 */
function validateCuitMod11(rawCuit) {
  const digits = String(rawCuit || '').replace(/\D/g, '');
  if (digits.length !== 11) return false;
  const weights = [5, 4, 3, 2, 7, 6, 5, 4, 3, 2];
  let sum = 0;
  for (let i = 0; i < 10; i++) {
    sum += parseInt(digits[i], 10) * weights[i];
  }
  const mod = 11 - (sum % 11);
  const checkDigit = mod === 11 ? 0 : mod === 10 ? 9 : mod;
  return checkDigit === parseInt(digits[10], 10);
}

function formatCuitString(rawVal) {
  const digits = String(rawVal || '').replace(/\D/g, '');
  if (digits.length === 11) {
    return `${digits.slice(0, 2)}-${digits.slice(2, 10)}-${digits.slice(10)}`;
  }
  return String(rawVal || '').trim().toUpperCase();
}

/**
 * Extrae las claves numéricas normalizadas de un DNI, CUIT o CUIL
 * (tanto el número completo sin guiones/puntos como los 8 dígitos del DNI
 * cuando se trata de un CUIT/CUIL de persona física con prefijo 20, 23, 24 o 27).
 * Devuelve un arreglo vacío si el documento está en blanco o es genérico en ceros (00-00000000-0 / 00.000.000).
 */
function extractClientDocKeys(rawDoc) {
  const digits = String(rawDoc || '').replace(/\D/g, '');
  if (!digits || /^0+$/.test(digits)) return [];
  const cleanFull = digits.replace(/^0+/, '');
  if (!cleanFull) return [];
  const keys = [cleanFull];
  if (digits.length === 11 && /^(20|23|24|27)/.test(digits)) {
    const dniPart = digits.slice(2, 10).replace(/^0+/, '');
    if (dniPart.length >= 6 && !/^0+$/.test(dniPart) && !keys.includes(dniPart)) {
      keys.push(dniPart);
    }
  }
  return keys;
}

/**
 * Busca si ya existe en el padrón otro cliente con el mismo N° de Documento, DNI, CUIT o CUIL.
 */
function findDuplicateClientByDoc(rawDoc, excludeClientId = null) {
  const targetKeys = extractClientDocKeys(rawDoc);
  if (targetKeys.length === 0) return null;
  for (const c of STATE.clientes) {
    if (excludeClientId !== null && Number(c.id) === Number(excludeClientId)) continue;
    const cKeys = extractClientDocKeys(c.nroDoc);
    if (cKeys.length > 0 && targetKeys.some((k) => cKeys.includes(k))) {
      return c;
    }
  }
  return null;
}

function findNextFreeUnifiedCode(excludeEntityId = null) {
  let maxNum = 234;
  for (const c of STATE.clientes) {
    if (excludeEntityId !== null && Number(c.id) === Number(excludeEntityId)) continue;
    const n1 = parseInt(String(c.codigo || '').trim(), 10);
    const n2 = parseInt(String(c.codigoProveedor || '').trim(), 10);
    if (!isNaN(n1) && n1 > maxNum) maxNum = n1;
    if (!isNaN(n2) && n2 > maxNum) maxNum = n2;
  }
  return String(maxNum + 1);
}

function findNextFreeClientCode(excludeClientId = null) {
  return findNextFreeUnifiedCode(excludeClientId);
}

function findNextFreeProveedorCode(excludeEntityId = null) {
  return findNextFreeUnifiedCode(excludeEntityId);
}

function syncProveedoresCatalogFromEntities() {
  if (!Array.isArray(STATE.clientes)) return;
  const provEntities = STATE.clientes.filter((c) => c.esProveedor === true && !c.bajaLogica);
  if (provEntities.length === 0) return;

  const byId = new Map();
  if (Array.isArray(STATE.proveedores)) {
    STATE.proveedores.forEach((p) => {
      byId.set(Number(p.id), p);
    });
  }

  provEntities.forEach((ent) => {
    const pId = Number(ent.idProveedor) || (1000 + Number(ent.codigo || ent.codigoProveedor || ent.id));
    ent.idProveedor = pId;
    const prev = byId.get(pId) || {};
    const unifiedCode = Number(ent.codigo || ent.codigoProveedor) || 0;
    const modoIvaVal = ent.fpModoIva === 'neto' || ent.fpModoIva === 'final' ? ent.fpModoIva : prev.fpModoIva;
    byId.set(pId, {
      ...prev,
      id: pId,
      codigo: unifiedCode,
      nombre: ent.nombre,
      cuit: ent.nroDoc || '',
      entityId: ent.id,
      esCliente: ent.esCliente !== false,
      ...(modoIvaVal ? { fpModoIva: modoIvaVal } : {})
    });
  });

  STATE.proveedores = Array.from(byId.values()).sort((a, b) =>
    String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es')
  );
  if (STATE.proveedoresMap instanceof Map) {
    STATE.proveedoresMap.clear();
    STATE.proveedores.forEach((p) => STATE.proveedoresMap.set(Number(p.id), p));
  }
  if (STATE.loaded || STATE.catalogLoaded) {
    populateMasterSelects();
  }
  document.querySelectorAll('#suppliers-rows-container .sup-select').forEach((sel) => {
    const prevVal = Number(sel.value) || 0;
    sel.textContent = '';
    const optEmpty = document.createElement('option');
    optEmpty.value = '0';
    optEmpty.textContent = '— Seleccionar Proveedor —';
    sel.appendChild(optEmpty);
    STATE.proveedores.forEach((p) => {
      const opt = document.createElement('option');
      opt.value = String(p.id);
      opt.textContent = `${p.nombre}${p.cuit ? ' (' + p.cuit + ')' : ''}`;
      if (Number(p.id) === prevVal) opt.selected = true;
      sel.appendChild(opt);
    });
  });
}

function lookupCatalogLabel(items, idValue, propName = 'nombre', fallback = '') {
  if (!Array.isArray(items) || idValue === undefined || idValue === null) return fallback;
  const found = items.find((item) => item && typeof item === 'object' && Number(item.id) === Number(idValue));
  if (!found) return fallback;
  return String(found[propName] ?? found.nombre ?? found.descripcion ?? fallback);
}

function getGenericSystemClientRule(c) {
  if (!c) return null;
  const cod = Number(c.codigo ?? c.id ?? 0);
  const nom = String(c.nombre || '').trim().toUpperCase();
  if (cod === 1 || nom === 'CONSUMIDOR FINAL') {
    return { isGeneric: true, code: 1, listaId: 1, listaPrecio: 'MINORISTA' };
  }
  if (cod === 2 || nom === 'CLIENTE OCASIONAL') {
    return { isGeneric: true, code: 2, listaId: 1, listaPrecio: 'MINORISTA' };
  }
  if (cod === 3 || nom === 'CLIENTE MAYORISTA') {
    return { isGeneric: true, code: 3, listaId: 2, listaPrecio: 'MAYORISTA' };
  }
  return null;
}

function sanitizeStreetNumberValue(raw) {
  let s = String(raw ?? '').trim().toUpperCase();
  if (!s) return '';
  // Si quedó pegado el ejemplo "S/N" o "S/D" junto con el número escrito por el usuario (ej: "S/N210" o "210S/N")
  const mPrefix = s.match(/^(?:S\/N|S\/D)\s*(.+)$/i);
  if (mPrefix && mPrefix[1].trim() && mPrefix[1].trim().toUpperCase() !== 'S/N') {
    s = mPrefix[1].trim().toUpperCase();
  }
  const mSuffix = s.match(/^(.+?)\s*(?:S\/N|S\/D)$/i);
  if (mSuffix && mSuffix[1].trim() && mSuffix[1].trim().toUpperCase() !== 'S/N') {
    s = mSuffix[1].trim().toUpperCase();
  }
  return s;
}

function inputStreetNumberValue(raw) {
  const clean = sanitizeStreetNumberValue(raw);
  if (!clean || clean === 'S/N' || clean === 'S/D' || clean === '...') return '';
  return clean;
}

function normalizeClientRecord(raw, catalogs = {}) {
  const c = Object.assign({}, raw);
  if (c.numero !== undefined) c.numero = sanitizeStreetNumberValue(c.numero) || 'S/N';
  if (c.numeroFiscal !== undefined) c.numeroFiscal = sanitizeStreetNumberValue(c.numeroFiscal) || c.numero || 'S/N';
  if (typeof c.calle === 'string' && /^S\/D\s+(.+)$/i.test(c.calle.trim())) {
    c.calle = c.calle.trim().replace(/^S\/D\s+/i, '').trim().toUpperCase();
  }
  if (typeof c.calleFiscal === 'string' && /^S\/D\s+(.+)$/i.test(c.calleFiscal.trim())) {
    c.calleFiscal = c.calleFiscal.trim().replace(/^S\/D\s+/i, '').trim().toUpperCase();
  }
  c.esCliente = c.esCliente !== undefined ? Boolean(c.esCliente) : true;
  c.esProveedor = Boolean(c.esProveedor);
  const unifiedCode = Number(c.codigo) || Number(c.codigoProveedor) || 0;
  c.codigo = unifiedCode;
  c.codigoProveedor = unifiedCode;
  c.idProveedor = Number(c.idProveedor) || 0;
  c.tipoProveedor = String(c.tipoProveedor || 'MERCADERÍA').toUpperCase();
  c.nombreFantasia = String(c.nombreFantasia || c.razonSocial || c.nombre || '').toUpperCase();
  c.contactoViajante = String(c.contactoViajante || c.contacto || '').toUpperCase();
  c.tel0800 = String(c.tel0800 || '').toUpperCase();
  c.plazoDiasCtaCteProv = Number(c.plazoDiasCtaCteProv ?? c.plazoDiasCtaCte) || 0;
  c.descuentoProntoPago = Number(c.descuentoProntoPago) || 0;
  if (raw.fpModoIva === 'neto' || raw.fpModoIva === 'final') {
    c.fpModoIva = raw.fpModoIva;
  } else if (
    c.esProveedor &&
    (unifiedCode === 242 || Number(c.idProveedor) === 242 || String(c.nombre || '').toUpperCase().includes('MANSILLA'))
  ) {
    c.fpModoIva = 'neto';
  }
  if (raw.fpTipoComprobante) {
    c.fpTipoComprobante = String(raw.fpTipoComprobante).trim().toUpperCase();
  }

  const genericRule = getGenericSystemClientRule(c);
  const listaId = genericRule
    ? genericRule.listaId
    : (Number(c.listaPrecioId ?? c.listaPrecios ?? 1) === 2 ? 2 : 1);
  const listaSecId = genericRule
    ? genericRule.listaId
    : (Number(c.listaPrecioSecId ?? c.listaPreciosSecundaria ?? listaId) === 2 ? 2 : 1);
  const ctaCteHabilitada = genericRule
    ? false
    : (c.habilitarCtaCte !== undefined ? Boolean(c.habilitarCtaCte) : Boolean(Number(c.habilitaCtaCte)));

  c.listaPrecioId = listaId;
  c.listaPrecios = listaId;
  c.listaPrecio = listaId === 2 ? 'MAYORISTA' : 'MINORISTA';
  c.listaPrecioSecId = listaSecId;
  c.listaPreciosSecundaria = listaSecId;
  c.listaPrecioSec = listaSecId === 2 ? 'MAYORISTA' : 'MINORISTA';

  c.habilitarCtaCte = ctaCteHabilitada;
  c.habilitaCtaCte = ctaCteHabilitada ? 1 : 0;
  if (genericRule) {
    c.idFormaPago = 1;
    c.formaPagoPredeterminada = 'CONTADO';
    c.creditoIlimitado = false;
    c.creditoMaximo = 0;
    c.boletaContraBoleta = false;
  }

  c.respIva =
    c.respIva ||
    lookupCatalogLabel(catalogs.respIva, c.idRespIva, 'nombre', 'CONSUMIDOR FINAL');
  c.tipoDoc =
    c.tipoDoc ||
    lookupCatalogLabel(catalogs.tiposDoc, c.idTipoDoc, 'nombre', 'DNI');
  c.condicionPagoContado =
    c.condicionPagoContado ||
    lookupCatalogLabel(catalogs.condicionesPagoContado, c.idCondicionContado, 'nombre', 'EFECTIVO');
  c.formaPagoPredeterminada =
    c.formaPagoPredeterminada ||
    lookupCatalogLabel(
      catalogs.formasPago,
      c.idFormaPago,
      'nombre',
      ctaCteHabilitada ? 'CTA. CTE.' : 'CONTADO'
    );
  c.vencimientoCtaCte =
    c.vencimientoCtaCte ||
    lookupCatalogLabel(
      catalogs.vencimientosCtaCte,
      c.idVencimientoCtaCte,
      'descripcion',
      'VENCIMIENTO: CERO DÍAS DE PLAZO'
    );
  c.referencia =
    c.referencia ||
    lookupCatalogLabel(catalogs.referencias, c.idReferencia, 'nombre', 'BUENO');
  c.categoria =
    c.categoria ||
    lookupCatalogLabel(catalogs.categorias, c.idCategoria, 'nombre', 'DESCONOCIDO');
  c.regimenIibb =
    c.regimenIibb ||
    lookupCatalogLabel(catalogs.regimenesIibb, c.idRegimenIibb, 'nombre', 'NO INSCRIPTO');
  c.regimenConvenio =
    c.regimenConvenio ||
    lookupCatalogLabel(
      catalogs.regimenesConvenio,
      c.idRegimenConvenio,
      'descripcion',
      'NO INSCRIPTO POR CONVENIO MULTILATERAL'
    );
  c.motivoExencionIibb =
    c.motivoExencionIibb ||
    lookupCatalogLabel(catalogs.exencionesIibb, c.idMotivoExencionIibb, 'nombre', '');

  c.solicitarDatosIibb =
    c.solicitarDatosIibb !== undefined ? Boolean(c.solicitarDatosIibb) : Boolean(c.solicitarIibb);
  c.exencionIibb = Boolean(c.exencionIibb);
  c.creditoIlimitado = Boolean(c.creditoIlimitado);
  c.boletaContraBoleta = Boolean(c.boletaContraBoleta);
  c.controlChequesTerceros =
    c.controlChequesTerceros !== undefined
      ? Boolean(c.controlChequesTerceros)
      : Boolean(c.controlValoresPendientes);
  c.dpto = c.dpto ?? c.depto ?? '';
  c.dptoFiscal = c.dptoFiscal ?? c.deptoFiscal ?? '';
  c.fechaNacimiento = String(c.fechaNacimiento || c.fn || '').trim();
  c.fechaAlta = String(c.fechaAlta || raw.fechaAlta || '').trim();
  c.fechaAltaClub = String(c.fechaAltaClub || raw.fechaAltaClub || c.fechaAlta || '').trim();
  const parsedAltaIso = parseClubDateToIso(c.fechaAlta || c.fechaAltaClub || '');
  c.fechaAltaIso = parsedAltaIso;
  c.fechaAltaFmt = parsedAltaIso ? formatIsoToDdMmYyyy(parsedAltaIso) : (c.fechaAlta || '');
  c.bajaLogica =
    c.bajaLogica !== undefined ? Number(c.bajaLogica) : c.estado && c.estado !== 'A' ? 1 : 0;

  c.puntosFidelizacion = Math.max(0, Math.round(Number(c.puntosFidelizacion) || 0));
  c.puntosAcumuladosHist = Math.max(0, Math.round(Number(c.puntosAcumuladosHist) || 0));
  c.puntosCanjeadosHist = Math.max(0, Math.round(Number(c.puntosCanjeadosHist) || 0));
  c.canalFidelizacion = c.canalFidelizacion || '';
  c.aliasCodigos = Array.isArray(raw.aliasCodigos)
    ? raw.aliasCodigos.map((x) => Number(x)).filter(Boolean)
    : [];
  c.aliasIds = Array.isArray(raw.aliasIds)
    ? raw.aliasIds.map((x) => Number(x)).filter(Boolean)
    : [];
  c.emailSecundario = String(raw.emailSecundario || '').trim().toUpperCase();
  if (
    (Number(c.id) === 108 || Number(c.codigo) === 106) &&
    String(c.nombre || '').toUpperCase().includes('GHIGLIONE')
  ) {
    if (!c.aliasCodigos.includes(209)) c.aliasCodigos.push(209);
    if (!c.aliasIds.includes(10076)) c.aliasIds.push(10076);
    if (!c.emailSecundario) c.emailSecundario = 'DANIGHIGLIONESL@GMAIL.COM';
  }

  return c;
}

function sanitizeCtaCteComprobanteParts(m) {
  let tca = String(m.tca || '').trim().toUpperCase();
  let letra = String(m.letra || m.l || '').trim().toUpperCase();
  let rawN = String(m.n || m.num || '').trim();

  const prefixLoopRe = /^(FA|FC|FB|NC|ND|CI|TI|OP|RE|RC)\s+(?:([ABCX])\s+)?/i;
  let guard = 0;
  while (guard < 5 && prefixLoopRe.test(rawN)) {
    const match = rawN.match(prefixLoopRe);
    if (!match) break;
    tca = match[1].toUpperCase();
    if (match[2]) letra = match[2].toUpperCase();
    rawN = rawN.slice(match[0].length).trim();
    guard++;
  }
  const bareLetterRe = /^([ABCX])\s+(\d{4}-\d{6,8}\b.*)$/i;
  const bareMatch = rawN.match(bareLetterRe);
  if (bareMatch) {
    letra = bareMatch[1].toUpperCase();
    rawN = bareMatch[2].trim();
  }

  let comp = String(m.comprobante || '').trim();
  if (comp) {
    let cleanComp = comp;
    let lastTca = '';
    let lastLetra = '';
    let cGuard = 0;
    while (cGuard < 5 && prefixLoopRe.test(cleanComp)) {
      const match = cleanComp.match(prefixLoopRe);
      if (!match) break;
      lastTca = match[1].toUpperCase();
      if (match[2]) lastLetra = match[2].toUpperCase();
      cleanComp = cleanComp.slice(match[0].length).trim();
      cGuard++;
    }
    if (lastTca) {
      tca = lastTca;
      if (lastLetra) letra = lastLetra;
      comp = [lastTca, lastLetra, cleanComp].filter(Boolean).join(' ');
    }
  } else {
    comp = [tca, letra, rawN].filter(Boolean).join(' ') || '-';
  }

  return { comprobante: comp || '-', letra };
}

function normalizeMovimientoRecord(m) {
  const dh = Number(m.dh) || 1;
  const imp = Number(m.importe ?? m.imp) || 0;
  const tipoComp = String(m.tipoComp || m.tcn || 'COMPROBANTE').toUpperCase();
  const esCompensacion = Boolean(m.esCompensacion || /COMPENSACI[ÓO]N/i.test(tipoComp));
  const origen = m.origen
    ? String(m.origen).toUpperCase()
    : (tipoComp.includes('COMPRA') || tipoComp.includes('ORDEN DE PAGO') ? 'COMPRA' : 'VENTA');
  const cleanedComp = sanitizeCtaCteComprobanteParts(m);
  return {
    id: m.id,
    idVenta: m.idVenta ?? m.vId ?? 0,
    vId: m.vId ?? m.idVenta ?? 0,
    cId: m.cId,
    fecha: m.fecha || m.f || '',
    hora: m.hora || m.h_str || '',
    vencimiento: m.vencimiento || m.v || m.f || '',
    tipoComp,
    comprobante: cleanedComp.comprobante,
    dh,
    debe: esCompensacion ? 0 : (Number(m.debe ?? m.d ?? (dh === 1 ? imp : 0)) || 0),
    haber: esCompensacion ? 0 : (Number(m.haber ?? m.h ?? (dh === -1 ? imp : 0)) || 0),
    importe: imp,
    cancelado: Number(m.cancelado ?? m.canc) || 0,
    pendiente: Number(m.pendiente ?? m.pend ?? m.sal) || 0,
    saldo: Number(m.saldo ?? m.s) || 0,
    obs: m.obs || '',
    origen,
    letra: cleanedComp.letra,
    uid: m.uid || '',
    medioPago: m.medioPago || '',
    cae: m.cae || '',
    caeVto: m.caeVto || '',
    qrImgSrc: m.qrImgSrc || '',
    items: Array.isArray(m.items) ? m.items : [],
    fcrItems: Array.isArray(m.fcrItems) ? m.fcrItems : [],
    fcrModoIva: m.fcrModoIva === 'neto' || m.fcrModoIva === 'final' ? m.fcrModoIva : '',
    esCompensacion,
    imputacionesCompensadas: Array.isArray(m.imputacionesCompensadas) ? m.imputacionesCompensadas : []
  };
}

async function loadClientesDatabase(forceReload = false) {
  if (STATE.clientesLoaded && !forceReload) return;
  if (STATE.clientesLoadingPromise && !forceReload) return STATE.clientesLoadingPromise;

  STATE.clientesLoadingPromise = (async () => {
    const statusEl = document.getElementById('clientes-status-msg');
    if (statusEl && !STATE.clientesLoaded) {
      statusEl.textContent = 'Descargando padrón unificado de clientes, proveedores y cuentas corrientes...';
    }

    let data = null;
    try {
      const res = await fetch(`api/clientes.php?action=all&_t=${Date.now()}`, { cache: 'no-store' });
      if (res.ok) {
        data = await res.json();
      }
    } catch {
      // Fallback to static JSON
    }

    if (!data || !Array.isArray(data.clientes)) {
      try {
        const resFallback = await fetch(`data/clientes_db.json?_t=${Date.now()}`, { cache: 'no-store' });
        if (resFallback.ok) {
          data = await resFallback.json();
        }
      } catch {}
    }

    if (!data) return;

    if (data.catalogs && typeof data.catalogs === 'object') {
      STATE.clientesCatalogs = Object.assign(STATE.clientesCatalogs, data.catalogs);
    }

    STATE.clientes = Array.isArray(data.clientes)
      ? data.clientes.map((c) => normalizeClientRecord(c, STATE.clientesCatalogs))
      : [];

    const movsMap = {};
    if (Array.isArray(data.movimientosCtaCte)) {
      for (const rawMov of data.movimientosCtaCte) {
        const key = String(rawMov.cId);
        if (!movsMap[key]) movsMap[key] = [];
        movsMap[key].push(normalizeMovimientoRecord(rawMov));
      }
    } else if (data.movimientosPorCliente && typeof data.movimientosPorCliente === 'object') {
      for (const [k, arr] of Object.entries(data.movimientosPorCliente)) {
        movsMap[k] = (arr || []).map((m) => normalizeMovimientoRecord(m));
      }
    }
    // Conciliación preventiva para clientes con ajustes por crédito históricos ya imputados (ej. #194 TALANO, cId=196)
    if (Array.isArray(movsMap['196'])) {
      movsMap['196'] = movsMap['196'].filter(
        (m) => !(Number(m.id) === 900049 || (String(m.comprobante || '').includes('0101-00000128') && Math.abs((Number(m.haber) || 0) - 8457063.6) < 1))
      );
      movsMap['196'].forEach((m) => {
        if ((Number(m.haber) || 0) > 0 && String(m.tipoComp || '').includes('AJUSTE')) {
          m.pendiente = 0;
          m.cancelado = round2(Number(m.haber) || 0);
        }
      });
      const talanoCli = STATE.clientes.find((c) => Number(c.id) === 196);
      if (talanoCli) {
        let sD = 0;
        let sH = 0;
        movsMap['196'].forEach((m) => {
          sD = round2(sD + (Number(m.debe) || 0));
          sH = round2(sH + (Number(m.haber) || 0));
        });
        talanoCli.totalDebe = sD;
        talanoCli.totalHaber = sH;
        talanoCli.saldoActual = round2(sD - sH);
        talanoCli.cantMovs = movsMap['196'].length;
      }
    }
    STATE.movimientosPorCliente = movsMap;
    if (data.fidelizacionConfig && typeof data.fidelizacionConfig === 'object') {
      STATE.fidelizacionConfig = Object.assign({}, STATE.fidelizacionConfig, data.fidelizacionConfig);
      const srvPct = Number(data.fidelizacionConfig.porcentajeCompra ?? data.fidelizacionConfig.porcentajeSuma);
      if (isFinite(srvPct) && srvPct > 0) {
        const cleanSrvPct = Math.min(5.00, Math.max(0.25, round2(srvPct)));
        STATE.fidelizacionConfig.porcentajeSuma = cleanSrvPct;
        STATE.fidelizacionConfig.porcentajeCompra = cleanSrvPct;
      }
      const srvDias = Number(data.fidelizacionConfig.diasVigencia ?? data.fidelizacionConfig.diasVencimiento);
      if (isFinite(srvDias) && srvDias > 0) {
        const cleanDias = Math.max(1, Math.round(srvDias));
        STATE.fidelizacionConfig.diasVencimiento = cleanDias;
        STATE.fidelizacionConfig.diasVigencia = cleanDias;
      }
      STATE.fidelizacionConfig.reglasRubros = normalizeFidRubroRules(data.fidelizacionConfig.reglasRubros);
    }
    if (Array.isArray(data.movimientosFidelizacion)) {
      STATE.movimientosFidelizacion = data.movimientosFidelizacion;
    }
    // BLINDAJE MULTI-USUARIO: No pisar datos del servidor con caches viejos de localStorage
    recalcAllClientsFidelizacionPoints();
    syncProveedoresCatalogFromEntities();
    STATE.clientesLoaded = true;

    populateClientesMasterSelects();
    updateClientesKpis();
    applyClientesFilters(1);
    applyProveedoresFilters(1);
    renderCuentasCorrientesSection();
    updateFidelizacionKpisAndSummary();
    if (typeof window.refreshPedidosProveedoresAfterArticleSave === 'function') {
      window.refreshPedidosProveedoresAfterArticleSave();
    }
  })().finally(() => {
    STATE.clientesLoadingPromise = null;
  });

  return STATE.clientesLoadingPromise;
}

async function loadVentasDatabase(forceReload = false) {
  if (STATE.ventasLoaded && STATE.ventasDb && !forceReload) return STATE.ventasDb;
  if (STATE.ventasLoadingPromise && !forceReload) return STATE.ventasLoadingPromise;

  STATE.ventasLoadingPromise = (async () => {
    let data = null;
    try {
      const res = await fetch(`api/ventas.php?t=${Date.now()}`, { cache: 'no-store' });
      if (res.ok) {
        data = await res.json();
      }
    } catch {}

    if (!data || !Array.isArray(data.dailyRecords)) {
      try {
        const resFallback = await fetch(`data/ventas_db.json?t=${Date.now()}`, { cache: 'no-store' });
        if (resFallback.ok) {
          data = await resFallback.json();
        }
      } catch {}
    }

    if (!data || !Array.isArray(data.dailyRecords)) return null;

    STATE.ventasDb = data;
    STATE.ventasLoaded = true;
    STATE.estDatasetCache = null;

    // 1. Actualizar números correlativos siguientes de cada Caja según el Servidor + Oliver Informática
    if (data.nextCorrelativos && typeof data.nextCorrelativos === 'object') {
      Object.entries(data.nextCorrelativos).forEach(([k, val]) => {
        const num = Number(val) || 0;
        if (num > 0) {
          OLIVER_NEXT_CORRELATIVOS[k] = Math.max(Number(OLIVER_NEXT_CORRELATIVOS[k]) || 0, num);
          STATE.factCorrelativos[k] = Math.max(Number(STATE.factCorrelativos[k]) || 0, num);
        }
      });
    }

    // 2. Incorporar los comprobantes reales del turno abierto de cada Caja (sin perder ventas al cruzar las 00:00 hs y purgando comprobantes ya cerrados en el servidor)
    if (data.comprobantesPorCaja && typeof data.comprobantesPorCaja === 'object') {
      syncTurnosCajasFromServerMap(data.comprobantesPorCaja);
    }

    if (Array.isArray(data.aperturasCajaCentral) && data.aperturasCajaCentral.length > 0) {
      STATE.aperturasCajaCentral = data.aperturasCajaCentral;
      if (typeof normalizeClientAperturasState === 'function') {
        normalizeClientAperturasState();
      }
    }

    if (data.efectivoInicialPorCaja && typeof data.efectivoInicialPorCaja === 'object') {
      STATE.efectivoInicialPorCaja = {
        caja1: round2(Number(data.efectivoInicialPorCaja.caja1) || 0),
        caja2: round2(Number(data.efectivoInicialPorCaja.caja2) || 0),
        caja3: round2(Number(data.efectivoInicialPorCaja.caja3) || 0)
      };
    }

    if (Array.isArray(data.cierresCajaCentral) && data.cierresCajaCentral.length > 0) {
      const localById = new Map();
      (STATE.cierresCajaCentral || []).forEach((lc) => {
        if (!lc) return;
        if (typeof window.normalizeCierreBilletesTransferidos === 'function') {
          window.normalizeCierreBilletesTransferidos(lc);
        }
        const k = lc.uid || (lc.numeroPlanilla ? `NP-${Number(lc.numeroPlanilla)}` : `ID-${lc.id}`);
        localById.set(k, lc);
      });
      const seenIds = new Set();
      const mergedCierres = [];
      for (const rawC of [...data.cierresCajaCentral, ...(STATE.cierresCajaCentral || [])]) {
        if (!rawC) continue;
        if (typeof window.normalizeCierreBilletesTransferidos === 'function') {
          window.normalizeCierreBilletesTransferidos(rawC);
        }
        const k = rawC.uid || (rawC.numeroPlanilla ? `NP-${Number(rawC.numeroPlanilla)}` : `ID-${rawC.id}`);
        if (!k || seenIds.has(k)) continue;
        seenIds.add(k);
        const localMatch = localById.get(k);
        let mergedItem = rawC;
        if (localMatch) {
          if (localMatch.editadoAt && (!rawC.editadoAt || localMatch.editadoAt >= rawC.editadoAt)) {
            mergedItem = { ...rawC, ...localMatch };
            if (typeof window.normalizeCierreBilletesTransferidos === 'function') {
              window.normalizeCierreBilletesTransferidos(mergedItem);
            }
          }
          if (localMatch.confirmadoCajaCentral && !mergedItem.confirmadoCajaCentral) {
            mergedItem = {
              ...mergedItem,
              confirmadoCajaCentral: true,
              estadoRecepcion: 'CONFIRMADA',
              confirmadoAt: localMatch.confirmadoAt || mergedItem.confirmadoAt,
              confirmadoPor: localMatch.confirmadoPor || mergedItem.confirmadoPor
            };
          }
        }
        mergedCierres.push(mergedItem);
      }
      STATE.cierresCajaCentral = mergedCierres;
    }

    if (typeof window.saveCajasState === 'function') {
      window.saveCajasState();
    }
    if (typeof window.__onVentasDbLoaded === 'function') {
      window.__onVentasDbLoaded();
    }
    return data;
  })().finally(() => {
    STATE.ventasLoadingPromise = null;
  });

  return STATE.ventasLoadingPromise;
}

function populateSelectOptions(selectEl, items, valueKey = null, labelKey = null, placeholder = null) {
  if (!selectEl) return;
  selectEl.textContent = '';
  if (placeholder !== null) {
    const opt0 = document.createElement('option');
    opt0.value = '';
    opt0.textContent = placeholder;
    selectEl.appendChild(opt0);
  }
  (items || []).forEach((item) => {
    const opt = document.createElement('option');
    if (typeof item === 'string' || typeof item === 'number') {
      opt.value = String(item);
      opt.textContent = String(item);
    } else if (item && typeof item === 'object') {
      const val = valueKey ? item[valueKey] : (item.nombre ?? item.codigo ?? item.descripcion ?? item.id ?? '');
      const lbl = labelKey ? item[labelKey] : (item.nombre ?? item.descripcion ?? item.codigo ?? item.id ?? '');
      opt.value = String(val);
      opt.textContent = String(lbl);
    }
    selectEl.appendChild(opt);
  });
}

/**
 * Configura los desplegables en cascada País -> Provincia -> Localidad -> C.P.
 * tal como en campodirecto.ar, todo en MAYÚSCULAS.
 */
function updateGeoCascade(prefix, desiredPais, desiredProvincia, desiredLocalidad, desiredCp) {
  const paisSel = document.getElementById(`${prefix}-pais`);
  const provSel = document.getElementById(`${prefix}-provincia`);
  const locSel = document.getElementById(`${prefix}-localidad`);
  const cpInp = document.getElementById(`${prefix}-cp`);
  if (!paisSel || !provSel || !locSel) return;

  const paises = STATE.clientesCatalogs.paises || ['ARGENTINA'];
  populateSelectOptions(paisSel, paises);
  const targetPais = (desiredPais || 'ARGENTINA').toUpperCase();
  if (!Array.from(paisSel.options).some((o) => o.value === targetPais)) {
    const opt = document.createElement('option');
    opt.value = targetPais;
    opt.textContent = targetPais;
    paisSel.appendChild(opt);
  }
  paisSel.value = targetPais;

  const provincias = STATE.clientesCatalogs.provincias || ['CÓRDOBA'];
  populateSelectOptions(provSel, provincias);
  const targetProv = (desiredProvincia || 'CÓRDOBA').toUpperCase();
  if (targetProv && !Array.from(provSel.options).some((o) => o.value === targetProv)) {
    const opt = document.createElement('option');
    opt.value = targetProv;
    opt.textContent = targetProv;
    provSel.appendChild(opt);
  }
  provSel.value = targetProv || 'CÓRDOBA';

  populateLocalidadesForProvinceSelect(locSel, cpInp, provSel.value, desiredLocalidad, desiredCp);
}

function populateLocalidadesForProvinceSelect(locSel, cpInp, provinciaName, desiredLocalidad = '', desiredCp = '') {
  if (!locSel) return;
  const provKey = String(provinciaName || 'CÓRDOBA').toUpperCase();
  const locsMap = STATE.clientesCatalogs.localidadesPorProvincia || {};
  const list = Array.isArray(locsMap[provKey]) ? [...locsMap[provKey]] : [];

  locSel.textContent = '';
  const targetLoc = String(desiredLocalidad || '').trim().toUpperCase();

  // Ensure desiredLocalidad exists in list if provided
  if (targetLoc && !list.some((x) => x.nombre === targetLoc)) {
    list.unshift({ nombre: targetLoc, cp: String(desiredCp || '').trim().toUpperCase() });
  }

  if (list.length === 0) {
    list.push({ nombre: 'ALCIRA GIGENA', cp: '5813' });
  }

  list.forEach((locObj) => {
    const opt = document.createElement('option');
    opt.value = locObj.nombre;
    opt.dataset.cp = locObj.cp || '';
    opt.textContent = locObj.cp ? `${locObj.nombre} (CP ${locObj.cp})` : locObj.nombre;
    locSel.appendChild(opt);
  });

  if (targetLoc && Array.from(locSel.options).some((o) => o.value === targetLoc)) {
    locSel.value = targetLoc;
  } else if (Array.from(locSel.options).some((o) => o.value === 'ALCIRA GIGENA')) {
    locSel.value = 'ALCIRA GIGENA';
  } else if (locSel.options.length > 0) {
    locSel.selectedIndex = 0;
  }

  if (cpInp) {
    if (desiredCp !== undefined && desiredCp !== null && String(desiredCp).trim() !== '') {
      cpInp.value = String(desiredCp).trim().toUpperCase();
    } else {
      const selOpt = locSel.options[locSel.selectedIndex];
      cpInp.value = (selOpt && selOpt.dataset.cp) ? selOpt.dataset.cp : '';
    }
  }
}

function promptAddCustomLocality(provSelId, locSelId, cpInpId) {
  const provSel = document.getElementById(provSelId);
  const locSel = document.getElementById(locSelId);
  const cpInp = document.getElementById(cpInpId);
  if (!provSel || !locSel) return;

  const provName = (provSel.value || 'CÓRDOBA').toUpperCase();
  const rawLoc = prompt(`Ingresá el nombre de la nueva Localidad para la provincia ${provName}:`);
  if (!rawLoc || !rawLoc.trim()) return;
  const newLoc = rawLoc.trim().toUpperCase();

  const rawCp = prompt(`Ingresá el Código Postal (C.P.) para ${newLoc}:`, (cpInp && cpInp.value) || '5813');
  const newCp = rawCp ? rawCp.trim().toUpperCase() : '';

  if (!STATE.clientesCatalogs.localidadesPorProvincia[provName]) {
    STATE.clientesCatalogs.localidadesPorProvincia[provName] = [];
  }
  const arr = STATE.clientesCatalogs.localidadesPorProvincia[provName];
  const existing = arr.find((x) => x.nombre === newLoc);
  if (!existing) {
    arr.push({ nombre: newLoc, cp: newCp });
    arr.sort((a, b) => a.nombre.localeCompare(b.nombre, 'es'));
  } else if (newCp) {
    existing.cp = newCp;
  }

  populateLocalidadesForProvinceSelect(locSel, cpInp, provName, newLoc, newCp);
}

function promptAddCustomProvince(provSelId, locSelId, cpInpId) {
  const provSel = document.getElementById(provSelId);
  const locSel = document.getElementById(locSelId);
  const cpInp = document.getElementById(cpInpId);
  if (!provSel) return;

  const rawProv = prompt('Ingresá el nombre de la Provincia / Estado:');
  if (!rawProv || !rawProv.trim()) return;
  const newProv = rawProv.trim().toUpperCase();

  if (!STATE.clientesCatalogs.provincias.includes(newProv)) {
    STATE.clientesCatalogs.provincias.push(newProv);
  }
  populateSelectOptions(provSel, STATE.clientesCatalogs.provincias);
  provSel.value = newProv;
  populateLocalidadesForProvinceSelect(locSel, cpInp, newProv, '', '');
}

