const PHONE_CODES_BY_LEN = PHONE_COUNTRY_CODES
  .filter((x) => x.code)
  .slice()
  .sort((a, b) => b.code.length - a.code.length);

function sanitizeLocalArSubscriber(rawDigits) {
  let d = String(rawDigits || '').replace(/\D/g, '');
  if (!d) return '';
  d = d.replace(/^0+/, '');
  if (d.length === 12) {
    if (d.startsWith('1115')) {
      d = '11' + d.slice(4);
    } else if (/^[23]\d{2}15\d{7}$/.test(d)) {
      d = d.slice(0, 3) + d.slice(5);
    } else if (/^[23]\d{3}15\d{6}$/.test(d)) {
      d = d.slice(0, 4) + d.slice(6);
    }
  }
  return d;
}

function ensurePhoneCountrySelectPopulated(sel) {
  if (!sel || sel.options.length > 0) return;
  for (const item of PHONE_COUNTRY_CODES) {
    const opt = document.createElement('option');
    opt.value = item.code;
    opt.textContent = item.label;
    sel.appendChild(opt);
  }
  sel.value = '+549';
}

function syncPhoneInputPlaceholder(sel, inp) {
  if (!sel || !inp) return;
  const found = PHONE_COUNTRY_CODES.find((x) => x.code === sel.value);
  inp.placeholder = found ? found.placeholder : '3585XXXXXX';
}

function parsePhoneIntlValue(rawValue) {
  const str = String(rawValue || '').trim();
  if (!str) return { code: '+549', local: '' };

  const hasExplicitIntl = str.startsWith('+') || str.startsWith('00');
  let digits = str.replace(/\D/g, '');
  if (!digits) return { code: '+549', local: '' };

  if (str.startsWith('00')) {
    digits = digits.slice(2);
  }

  if (hasExplicitIntl) {
    const plusDigits = '+' + digits;
    if (plusDigits.startsWith('+549')) {
      return { code: '+549', local: sanitizeLocalArSubscriber(plusDigits.slice(4)) };
    }
    if (plusDigits.startsWith('+54')) {
      return { code: '+549', local: sanitizeLocalArSubscriber(plusDigits.slice(3)) };
    }
    for (const item of PHONE_CODES_BY_LEN) {
      if (plusDigits.startsWith(item.code)) {
        return { code: item.code, local: plusDigits.slice(item.code.length).replace(/^0+/, '') };
      }
    }
    return { code: '', local: '+' + digits };
  }

  if (digits.startsWith('549') && digits.length >= 12) {
    return { code: '+549', local: sanitizeLocalArSubscriber(digits.slice(3)) };
  }
  if (digits.startsWith('54') && digits.length >= 12) {
    return { code: '+549', local: sanitizeLocalArSubscriber(digits.slice(2)) };
  }
  return { code: '+549', local: sanitizeLocalArSubscriber(digits) };
}

function setPhoneIntlField(inputId, selectId, rawValue) {
  const inp = document.getElementById(inputId);
  const sel = document.getElementById(selectId);
  if (sel) ensurePhoneCountrySelectPopulated(sel);
  const parsed = parsePhoneIntlValue(rawValue);
  if (sel) {
    sel.value = parsed.code;
    syncPhoneInputPlaceholder(sel, inp);
  }
  if (inp) {
    inp.value = parsed.local;
  }
}

function getPhoneIntlField(inputId, selectId) {
  const inp = document.getElementById(inputId);
  const sel = document.getElementById(selectId);
  if (!inp) return '';
  if (sel) ensurePhoneCountrySelectPopulated(sel);

  const rawLocal = String(inp.value || '').trim();
  if (!rawLocal) return '';

  if (rawLocal.startsWith('+') || rawLocal.startsWith('00')) {
    const parsed = parsePhoneIntlValue(rawLocal);
    if (!parsed.local) return '';
    return parsed.code
      ? `${parsed.code}${parsed.local}`
      : (parsed.local.startsWith('+') ? parsed.local : `+${parsed.local}`);
  }

  const code = sel ? String(sel.value ?? '+549') : '+549';
  const digits = rawLocal.replace(/\D/g, '');
  if (!digits) return '';

  if (code === '+549') {
    let cleanAr = digits;
    if (cleanAr.startsWith('549') && cleanAr.length >= 12) cleanAr = cleanAr.slice(3);
    else if (cleanAr.startsWith('54') && cleanAr.length >= 12) cleanAr = cleanAr.slice(2);
    cleanAr = sanitizeLocalArSubscriber(cleanAr);
    return cleanAr ? `+549${cleanAr}` : '';
  }

  if (!code) {
    return `+${digits}`;
  }

  const codeDigits = code.replace(/\D/g, '');
  let cleanIntl = digits;
  if (codeDigits && cleanIntl.startsWith(codeDigits) && cleanIntl.length >= codeDigits.length + 7) {
    cleanIntl = cleanIntl.slice(codeDigits.length);
  }
  cleanIntl = cleanIntl.replace(/^0+/, '');
  return cleanIntl ? `${code}${cleanIntl}` : '';
}

function initPhoneCountrySelects() {
  const pairs = [
    ['cli-celular', 'cli-celular-cod-pais'],
    ['prov-celular', 'prov-celular-cod-pais'],
    ['reg-celular', 'reg-celular-cod-pais'],
    ['fid-cli-whatsapp', 'fid-cli-whatsapp-cod-pais']
  ];
  for (const [inputId, selectId] of pairs) {
    const inp = document.getElementById(inputId);
    const sel = document.getElementById(selectId);
    if (!sel || !inp) continue;
    ensurePhoneCountrySelectPopulated(sel);
    syncPhoneInputPlaceholder(sel, inp);
    if (!sel.dataset.phoneIntlBound) {
      sel.dataset.phoneIntlBound = '1';
      sel.addEventListener('change', () => syncPhoneInputPlaceholder(sel, inp));
      inp.addEventListener('change', () => {
        const val = String(inp.value || '').trim();
        if (val.startsWith('+') || val.startsWith('00')) {
          setPhoneIntlField(inputId, selectId, val);
        }
      });
    }
  }
}

function normalizePhoneForWa(rawPhone) {
  const str = String(rawPhone || '').trim();
  if (!str) return '';
  const hasExplicitIntl = str.startsWith('+') || str.startsWith('00');
  let digits = str.replace(/\D/g, '');
  if (!digits) return '';
  if (str.startsWith('00')) digits = digits.slice(2);

  if (hasExplicitIntl) {
    if (digits.startsWith('549')) return '549' + sanitizeLocalArSubscriber(digits.slice(3));
    if (digits.startsWith('54')) return '549' + sanitizeLocalArSubscriber(digits.slice(2));
    return digits;
  }

  if (digits.startsWith('0')) digits = digits.slice(1);
  if (digits.startsWith('549') && digits.length >= 12) return digits;
  if (digits.startsWith('54') && digits.length >= 11) {
    return '549' + sanitizeLocalArSubscriber(digits.slice(2));
  }
  return '549' + sanitizeLocalArSubscriber(digits);
}

function formatFidelizacionTemplate(template, vars = {}) {
  let msg = String(template || '');
  const replacements = {
    '{NOMBRE}': vars.nombre || 'CLIENTE',
    '{DNI}': vars.dni || 'S/D',
    '{PUNTOS_SUMADOS}': Number(vars.puntosSumados || 0).toLocaleString('es-AR'),
    '{PUNTOS_CANJEADOS}': Number(vars.puntosCanjeados || 0).toLocaleString('es-AR'),
    '{PRODUCTO}': vars.producto || '',
    '{CANTIDAD}': String(vars.cantidad || 1),
    '{MONTO}': formatArs(vars.monto || 0),
    '{SALDO_PUNTOS}': Number(vars.saldoPuntos || 0).toLocaleString('es-AR'),
    '{VENCIMIENTO}': vars.vencimiento || ''
  };
  for (const [key, val] of Object.entries(replacements)) {
    msg = msg.split(key).join(String(val));
  }
  return msg;
}

function triggerFidelizacionNotification(client, canal, messageText, subjectText = 'Puntos de Fidelización - Casa Nueva Supermercado', forceOpenWa = false) {
  if (!client) return { sentWa: false, sentEmail: false };
  const effectiveCanal = String(canal || client.canalFidelizacion || STATE.fidelizacionConfig.canalDefault || 'whatsapp').toLowerCase();
  let sentWa = false;
  let sentEmail = false;

  if (effectiveCanal === 'whatsapp' || effectiveCanal === 'ambos') {
    const rawPhone = client.celular || client.telefono || '';
    const waPhone = normalizePhoneForWa(rawPhone);
    if (waPhone) {
      sentWa = true;
      fetch('api/clientes.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'send_whatsapp_twilio',
          phone: waPhone,
          message: messageText,
          clientName: client.nombre || ''
        })
      })
        .then((r) => (r.ok ? r.json() : null))
        .then((res) => {
          if (res && res.ok) return;
          if (forceOpenWa || STATE.fidelizacionConfig.autoOpenWhatsapp !== false) {
            const waUrl = `https://wa.me/${waPhone}?text=${encodeURIComponent(messageText)}`;
            window.open(waUrl, '_blank', 'noopener');
          }
        })
        .catch(() => {
          if (forceOpenWa || STATE.fidelizacionConfig.autoOpenWhatsapp !== false) {
            const waUrl = `https://wa.me/${waPhone}?text=${encodeURIComponent(messageText)}`;
            window.open(waUrl, '_blank', 'noopener');
          }
        });
    }
  }

  if (effectiveCanal === 'email' || effectiveCanal === 'ambos') {
    const emailAddr = String(client.email || '').trim();
    if (emailAddr && forceOpenWa && effectiveCanal === 'email') {
      const mailtoUrl = `mailto:${encodeURIComponent(emailAddr)}?subject=${encodeURIComponent(subjectText)}&body=${encodeURIComponent(messageText)}`;
      window.open(mailtoUrl, '_blank', 'noopener');
      sentEmail = true;
    } else if (emailAddr) {
      sentEmail = true;
    }
  }

  return { sentWa, sentEmail };
}

function updateFidelizacionKpisAndSummary() {
  recalcAllClientsFidelizacionPoints();

  const pct = Number(STATE.fidelizacionConfig.porcentajeSuma) || 0.80;
  const factor = Number(STATE.fidelizacionConfig.factorCanje) || 1.12;
  const diasVenc = Number(STATE.fidelizacionConfig.diasVencimiento) || 365;
  const pctStr = `${pct.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}%`;
  const factorStr = factor.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  let totalActivePts = 0;
  let clientsWithPts = 0;
  let totalCanjeados = 0;
  let totalPorVencer30d = 0;
  let totalVencidosHist = 0;
  let clientsWithDni = 0;

  for (const c of STATE.clientes) {
    if (c.bajaLogica === 1 || isSystemConfigClient(c)) continue;
    const pts = Number(c.puntosFidelizacion) || 0;
    const canj = Number(c.puntosCanjeadosHist) || 0;
    const pv30 = Number(c.puntosPorVencer30d) || 0;
    const venc = Number(c.puntosVencidosHist) || 0;
    if (pts > 0) {
      totalActivePts += pts;
      clientsWithPts++;
    }
    totalCanjeados += canj;
    totalPorVencer30d += pv30;
    totalVencidosHist += venc;
    if (extractClientDocKeys(c.nroDoc).length > 0) {
      clientsWithDni++;
    }
  }

  let catalogActiveCount = 0;
  let catalogInStockCount = 0;
  for (const a of STATE.articulos) {
    if (a.bl === 1) continue;
    if (Number(a.cfid) === 1) {
      catalogActiveCount++;
      if (Number(a.sf) > 0) catalogInStockCount++;
    }
  }

  const setTxt = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val;
  };

  // Menú Fidelización KPIs (index.html lines 2493-2585)
  setTxt('fid-menu-pct-lbl', pctStr);
  setTxt('fid-menu-factor-lbl', factorStr);
  setTxt('kpi-fid-active-pts', totalActivePts.toLocaleString('es-AR'));
  setTxt('kpi-fid-active-sub', `En ${clientsWithPts.toLocaleString('es-AR')} clientes activos (Vigencia ${diasVenc} días)`);
  setTxt('kpi-fid-catalog-count', catalogActiveCount.toLocaleString('es-AR'));
  setTxt('kpi-fid-catalog-sub', `${catalogInStockCount.toLocaleString('es-AR')} con stock disponible · Factor ${factorStr} × Minorista`);
  setTxt('kpi-fid-clients-count', clientsWithPts.toLocaleString('es-AR'));
  setTxt('kpi-fid-redeemed-sub', `${totalCanjeados.toLocaleString('es-AR')} pts canjeados históricamente (${clientsWithDni.toLocaleString('es-AR')} con DNI)`);
  setTxt('kpi-fid-expiring-pts', totalPorVencer30d.toLocaleString('es-AR'));
  setTxt('kpi-fid-expired-sub', `${totalVencidosHist.toLocaleString('es-AR')} pts ya vencidos (+1 año)`);

  // Legacy / compatibility IDs
  setTxt('fid-kpi-pct', pctStr);
  setTxt('fid-kpi-points-active', totalActivePts.toLocaleString('es-AR'));
  setTxt('fid-kpi-clients-with-points', `${clientsWithPts.toLocaleString('es-AR')} clientes con saldo vigente (Venc. ${diasVenc} días)`);
  setTxt('fid-kpi-catalog-count', catalogActiveCount.toLocaleString('es-AR'));
  setTxt('fid-kpi-factor-sub', `Factor actual: ${factorStr} × Precio Minorista`);

  // Operaciones IDs (index.html lines 2733-2820)
  const vencPreview = addDaysToToday(diasVenc).formatted;
  setTxt('fid-op-pct-legend', pctStr);
  setTxt('fid-calc-pct-txt', pctStr);
  setTxt('fid-calc-emision-txt', todayFormatted());
  setTxt('fid-calc-venc-txt', `${vencPreview} (${diasVenc} días)`);
  setTxt('fid-op-factor-legend', factorStr);

  // Catálogo de Canje Header & Factor Input (index.html lines 2888-2910)
  setTxt('fid-cat-header-factor', factorStr);
  setTxt('fid-cat-th-auto', `Puntos Automáticos (${factorStr}x)`);
  const clampedFactor = Math.min(1.40, Math.max(0.80, round2(factor)));
  const globFactorInp = document.getElementById('fid-cat-factor-input') || document.getElementById('fid-cat-global-factor-input');
  if (globFactorInp && document.activeElement !== globFactorInp) {
    globFactorInp.value = clampedFactor.toFixed(2);
  }
  const globFactorRange = document.getElementById('fid-cat-factor-range');
  if (globFactorRange && document.activeElement !== globFactorRange) {
    globFactorRange.value = clampedFactor.toFixed(2);
  }
  syncFidCatGlobalStockCheckboxes();
  updatePosFidelizacionStrip();
}

function syncFidCatGlobalStockCheckboxes(modeOverride = null) {
  const modeVal =
    (modeOverride || STATE.fidelizacionConfig.mostrarEnCatalogo) === 'todos' ? 'todos' : 'solo_stock';
  const globStockSel = document.getElementById('fid-cat-global-stock-mode');
  if (globStockSel && globStockSel.value !== modeVal) {
    globStockSel.value = modeVal;
  }
  const chkSolo = document.getElementById('fid-cat-chk-solo-stock');
  const chkTodos = document.getElementById('fid-cat-chk-todos');
  const lblSolo = document.getElementById('lbl-fid-cat-chk-solo-stock');
  const lblTodos = document.getElementById('lbl-fid-cat-chk-todos');
  const isSolo = modeVal === 'solo_stock';

  if (chkSolo) chkSolo.checked = isSolo;
  if (chkTodos) chkTodos.checked = !isSolo;
  if (lblSolo) {
    lblSolo.style.borderColor = isSolo ? 'var(--gold-main, #d4a017)' : 'var(--border-subtle, #cbd5e1)';
    lblSolo.style.background = isSolo ? 'rgba(212, 160, 23, 0.14)' : 'transparent';
  }
  if (lblTodos) {
    lblTodos.style.borderColor = !isSolo ? 'var(--gold-main, #d4a017)' : 'var(--border-subtle, #cbd5e1)';
    lblTodos.style.background = !isSolo ? 'rgba(212, 160, 23, 0.14)' : 'transparent';
  }
}

function updatePosFidelizacionStrip() {
  const pct = Number(STATE.fidelizacionConfig.porcentajeSuma) || 0.80;
  const pctStr = `${pct.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}%`;
  const pctLbl = document.getElementById('pos-fid-pct-label');
  if (pctLbl) pctLbl.textContent = pctStr;
  const pctLbl2 = document.getElementById('pos-fid-pct-lbl');
  if (pctLbl2) pctLbl2.textContent = pctStr;

  const importe = Number(document.getElementById('pos-importe-input')?.value || 0);
  const cli = STATE.clientes.find((c) => Number(c.id) === Number(STATE.factSelectedClientId));
  const isClubMember = Boolean(cli && String(cli.codigo) !== '1');

  const calc = isClubMember ? calcPointsFromPurchase(importe, pct) : { points: 0 };
  const currentPts = isClubMember ? (Number(cli.puntosFidelizacion) || 0) : 0;
  const totalPts = currentPts + calc.points;

  const ptsStr = `+${calc.points.toLocaleString('es-AR')} pts`;
  const totalStr = `${totalPts.toLocaleString('es-AR')} pts`;

  const prevEl = document.getElementById('pos-fid-points-preview');
  if (prevEl) prevEl.textContent = ptsStr;
  const prevEl2 = document.getElementById('pos-fid-pts-preview');
  if (prevEl2) prevEl2.textContent = ptsStr;

  const totalEl = document.getElementById('pos-fid-total-pts');
  if (totalEl) totalEl.textContent = totalStr;
}

function buildClubMemberQrPayload(client) {
  if (!client) return '';
  const dni = extractDisplayDni(client);
  const cleanDni = dni !== 'S/DNI' ? String(dni).replace(/\D/g, '') : '';
  const cleanCod = String(client.codigo || client.id || '').trim();
  const prefix = ACTIVE_BRAND.isPaseoAlberdi ? 'CPA' : 'CCN';
  const token = cleanDni ? `${prefix}-${cleanDni}-${cleanCod}` : `${prefix}-COD-${cleanCod}`;
  const baseUrl = ACTIVE_BRAND.isPaseoAlberdi
    ? 'https://paseoalberdi.ar/carrito/'
    : 'https://cn.com.ar/carrito/';
  return `${baseUrl}?qr=${token}`;
}

function isGenericNonClubClient(c) {
  if (!c || c.bajaLogica === 1 || isSystemConfigClient(c)) return true;
  return false;
}

function clientMatchesCodeOrAlias(c, rawCode) {
  if (!c || !rawCode) return false;
  const target = String(rawCode).trim().replace(/^0+/, '');
  if (!target) return false;
  if (String(c.codigo || '').trim().replace(/^0+/, '') === target) return true;
  if (
    Array.isArray(c.aliasCodigos) &&
    c.aliasCodigos.some((ac) => String(ac).trim().replace(/^0+/, '') === target)
  ) {
    return true;
  }
  return false;
}

function findClientsMatchingDniOrName(rawQuery) {
  const raw = String(rawQuery || '').trim();
  if (!raw) return [];

  // Detectar lectura de código QR de Socio Club Fidel (ej: CCN-35123456-235 o https://cn.com.ar/carrito/?qr=CCN-22523947-106)
  const upperRaw = raw.toUpperCase();
  if (upperRaw.includes('CCN') || upperRaw.includes('CPA') || upperRaw.includes('FIDEL') || upperRaw.includes('CACHITA') || upperRaw.includes('PASEO')) {
    const tokenIdx = upperRaw.search(/CCN|CPA/);
    const qrScope = tokenIdx >= 0 ? upperRaw.slice(tokenIdx) : upperRaw;
    const numberGroups = qrScope.match(/\d+/g) || [];
    if (numberGroups.length > 0) {
      const dniCandidate = numberGroups.find((g) => g.length >= 6) || '';
      const codCandidate = numberGroups[numberGroups.length - 1] || '';
      const cleanDniCand = dniCandidate.replace(/^0+/, '');
      const cleanCodCand = codCandidate.replace(/^0+/, '');

      // 1) Priorizar coincidencia por DNI en toda la base (evitando cuentas genéricas)
      if (cleanDniCand) {
        for (const c of STATE.clientes) {
          if (isGenericNonClubClient(c)) continue;
          const docKeys = extractClientDocKeys(c.nroDoc);
          if (docKeys.some((k) => k === cleanDniCand)) {
            return [c];
          }
        }
      }

      // 2) Coincidencia por código de socio o aliasCodigos (ej: #209 -> #106 GHIGLIONE, DANIEL ALEJANDRO)
      if (cleanCodCand) {
        const codeMatches = [];
        for (const c of STATE.clientes) {
          if (isGenericNonClubClient(c)) continue;
          if (clientMatchesCodeOrAlias(c, cleanCodCand)) {
            codeMatches.push(c);
          }
        }
        if (codeMatches.length > 0) {
          // Preferir cuenta con documento cargado / mayor antigüedad si hubiera duplicado
          codeMatches.sort((a, b) => {
            const aHasDoc = extractClientDocKeys(a.nroDoc).length > 0 ? 1 : 0;
            const bHasDoc = extractClientDocKeys(b.nroDoc).length > 0 ? 1 : 0;
            if (bHasDoc !== aHasDoc) return bHasDoc - aHasDoc;
            return (Number(a.id) || 0) - (Number(b.id) || 0);
          });
          return [codeMatches[0]];
        }
      }
    }
    return [];
  }

  const q = normalizeStr(raw);
  const qDigits = raw.replace(/\D/g, '').replace(/^0+/, '');
  const tokens = q.split(/\s+/).filter(Boolean);

  const exactMatches = [];
  const partialMatches = [];

  for (const c of STATE.clientes) {
    if (isGenericNonClubClient(c)) continue;
    const docKeys = extractClientDocKeys(c.nroDoc);
    if (qDigits && qDigits.length >= 6 && docKeys.some((k) => k === qDigits)) {
      exactMatches.push(c);
      continue;
    }
    if (qDigits && qDigits.length <= 5 && clientMatchesCodeOrAlias(c, qDigits)) {
      exactMatches.push(c);
      continue;
    }
    const aliasStr = Array.isArray(c.aliasCodigos) ? c.aliasCodigos.join(' ') : '';
    const hay = normalizeStr(`${c.nroDoc || ''} ${docKeys.join(' ')} ${c.nombre || ''} ${c.razonSocial || ''} ${c.codigo || ''} ${aliasStr} ${c.celular || ''} ${c.email || ''} ${c.emailSecundario || ''}`);
    if (tokens.every((t) => hay.includes(t))) {
      partialMatches.push(c);
    }
  }

  exactMatches.sort((a, b) => {
    const aHasDoc = extractClientDocKeys(a.nroDoc).length > 0 ? 1 : 0;
    const bHasDoc = extractClientDocKeys(b.nroDoc).length > 0 ? 1 : 0;
    if (bHasDoc !== aHasDoc) return bHasDoc - aHasDoc;
    return (Number(a.id) || 0) - (Number(b.id) || 0);
  });

  return [...exactMatches, ...partialMatches].slice(0, 15);
}

function drawClubQrOnCanvas(canvas, qrPayload) {
  if (!canvas || !qrPayload) return;
  const ctx = canvas.getContext('2d');
  const size = canvas.width || 320;
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, size, size);

  const qrImg = new Image();
  qrImg.crossOrigin = 'anonymous';
  qrImg.onload = () => {
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, size, size);
    ctx.drawImage(qrImg, 0, 0, size, size);
  };
  qrImg.src = `https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&ecc=M&margin=2&color=0b2733&bgcolor=ffffff&data=${encodeURIComponent(qrPayload)}`;
}

function loadErpCanvasSafeImage(src) {
  return new Promise((resolve) => {
    if (!src) {
      resolve(null);
      return;
    }
    const img = new Image();
    if (/^https?:\/\//i.test(src)) {
      img.crossOrigin = 'anonymous';
    }
    img.onload = () => {
      try {
        const testC = document.createElement('canvas');
        testC.width = 1;
        testC.height = 1;
        testC.getContext('2d').drawImage(img, 0, 0, 1, 1);
        testC.toDataURL('image/png');
        resolve(img);
      } catch (_e) {
        resolve(null);
      }
    };
    img.onerror = () => resolve(null);
    img.src = src;
  });
}

function drawErpRoundedRect(ctx, x, y, w, h, r) {
  const radius = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

function wrapErpStoryNameLines(ctx, text, maxWidth) {
  const words = String(text || 'SOCIO CLUB FIDEL').trim().split(/\s+/);
  const lines = [];
  let current = '';
  for (const word of words) {
    const test = current ? `${current} ${word}` : word;
    if (ctx.measureText(test).width <= maxWidth || !current) {
      current = test;
    } else {
      lines.push(current);
      current = word;
    }
  }
  if (current) lines.push(current);
  return lines.slice(0, 2);
}

async function openClubMemberQrModal(clientOrId) {
  await loadClientesDatabase();
  const client =
    typeof clientOrId === 'object' && clientOrId !== null
      ? clientOrId
      : STATE.clientes.find((c) => Number(c.id) === Number(clientOrId));
  if (!client) return;

  STATE.activeQrModalClientId = client.id;
  recalcAllClientsFidelizacionPoints();

  const dlg = document.getElementById('club-member-qr-dialog');
  if (!dlg) return;

  const pts = Number(client.puntosFidelizacion) || 0;
  const payload = buildClubMemberQrPayload(client);

  const nameEl = document.getElementById('club-qr-member-name');
  const photoEl = document.getElementById('club-qr-member-photo');
  const ptsEl = document.getElementById('club-qr-member-pts');
  const canvas = document.getElementById('club-member-qr-canvas');
  const chkCnLogo = document.getElementById('club-qr-toggle-cn-logo');
  const cnLogoEl = document.getElementById('club-qr-cn-logo');

  if (nameEl) nameEl.textContent = String(client.nombre || 'SOCIO').trim();
  if (photoEl) {
    photoEl.src = client.fotoUrl || client.picture || 'assets/img/club-fidel/club-fidel-icon.png?v=184';
  }
  if (ptsEl) ptsEl.innerHTML = `${erpClubFidelBadgeSvg(16)} Saldo: ${pts.toLocaleString('es-AR')} puntos`;

  if (chkCnLogo && cnLogoEl) {
    cnLogoEl.style.display = chkCnLogo.checked ? 'block' : 'none';
    if (!chkCnLogo.dataset.boundToggle) {
      chkCnLogo.dataset.boundToggle = '1';
      chkCnLogo.addEventListener('change', () => {
        cnLogoEl.style.display = chkCnLogo.checked ? 'block' : 'none';
      });
    }
  }

  drawClubQrOnCanvas(canvas, payload);
  if (!dlg.open) dlg.showModal();
}

async function downloadClubMemberCredentialPng(client) {
  if (!client) return;
  const qrCanvas = document.getElementById('club-member-qr-canvas');
  if (!qrCanvas) return;

  const includeCnLogo = document.getElementById('club-qr-toggle-cn-logo')?.checked !== false;
  const userPhotoSrc = client.fotoUrl || client.picture || '';

  const [fidelLogoImg, cnBadgeImg, mascotaImg, userPhotoImg, fallbackIconImg] = await Promise.all([
    loadErpCanvasSafeImage('assets/img/club-fidel/club-fidel-logo-horiz.png?v=192'),
    includeCnLogo ? loadErpCanvasSafeImage('assets/img/club-fidel/casa-nueva-badge.png?v=192') : Promise.resolve(null),
    loadErpCanvasSafeImage('assets/img/club-fidel/club-fidel-mascota.png?v=192'),
    userPhotoSrc ? loadErpCanvasSafeImage(userPhotoSrc) : Promise.resolve(null),
    loadErpCanvasSafeImage('assets/img/club-fidel/club-fidel-icon.png?v=192')
  ]);

  // Tamaño Estados / Historias (9:16 = 1080 x 1920 px)
  const out = document.createElement('canvas');
  out.width = 1080;
  out.height = 1920;
  const ctx = out.getContext('2d');

  // 1. Fondo degradado oscuro Club Fidel (#0b2733 -> #071c26 -> #05141c)
  const bgGrad = ctx.createLinearGradient(0, 0, 540, 1920);
  bgGrad.addColorStop(0, '#0b2733');
  bgGrad.addColorStop(0.55, '#071c26');
  bgGrad.addColorStop(1, '#05141c');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, out.width, out.height);

  const topGlow = ctx.createRadialGradient(540, 260, 20, 540, 260, 520);
  topGlow.addColorStop(0, 'rgba(67, 217, 147, 0.20)');
  topGlow.addColorStop(1, 'rgba(67, 217, 147, 0)');
  ctx.fillStyle = topGlow;
  ctx.fillRect(0, 0, out.width, 900);

  const bottomGlow = ctx.createRadialGradient(540, 1620, 20, 540, 1620, 480);
  bottomGlow.addColorStop(0, 'rgba(212, 164, 30, 0.16)');
  bottomGlow.addColorStop(1, 'rgba(212, 164, 30, 0)');
  ctx.fillStyle = bottomGlow;
  ctx.fillRect(0, 1050, out.width, 870);

  drawErpRoundedRect(ctx, 36, 36, out.width - 72, out.height - 72, 48);
  ctx.strokeStyle = 'rgba(67, 217, 147, 0.32)';
  ctx.lineWidth = 4;
  ctx.stroke();

  // 2. Cabecera con Logo Club Fidel + (opcional) Logo Casa Nueva en PNG
  if (fidelLogoImg) {
    const fH = 148;
    const fW = Math.round((fidelLogoImg.width / fidelLogoImg.height) * fH);
    if (includeCnLogo && cnBadgeImg) {
      ctx.drawImage(fidelLogoImg, 96, 86, fW, fH);
      const cnSize = 152;
      ctx.drawImage(cnBadgeImg, out.width - 96 - cnSize, 84, cnSize, cnSize);
    } else {
      ctx.drawImage(fidelLogoImg, Math.round((out.width - fW) / 2), 86, fW, fH);
    }
  }

  // 3. Foto circular del socio (tomada de Google o elegida en su perfil)
  const avatarCx = 540;
  const avatarCy = 415;
  const avatarR = 132;

  ctx.save();
  ctx.beginPath();
  ctx.arc(avatarCx, avatarCy, avatarR + 10, 0, Math.PI * 2);
  ctx.fillStyle = '#43d993';
  ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.beginPath();
  ctx.arc(avatarCx, avatarCy, avatarR, 0, Math.PI * 2);
  ctx.closePath();
  ctx.clip();
  ctx.fillStyle = '#0e3342';
  ctx.fillRect(avatarCx - avatarR, avatarCy - avatarR, avatarR * 2, avatarR * 2);
  const avatarToDraw = userPhotoImg || fallbackIconImg;
  if (avatarToDraw) {
    ctx.drawImage(avatarToDraw, avatarCx - avatarR, avatarCy - avatarR, avatarR * 2, avatarR * 2);
  }
  ctx.restore();

  // 4. SOLO Nombre y Apellido de la persona
  const fullName = String(client.nombre || 'SOCIO CLUB FIDEL').trim().toUpperCase();
  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'center';
  ctx.font = '900 46px "Plus Jakarta Sans", "Segoe UI", sans-serif';
  const nameLines = wrapErpStoryNameLines(ctx, fullName, 880);
  if (nameLines.length === 1) {
    ctx.fillText(nameLines[0], 540, 625);
  } else {
    ctx.font = '900 42px "Plus Jakarta Sans", "Segoe UI", sans-serif';
    ctx.fillText(nameLines[0], 540, 608);
    ctx.fillText(nameLines[1], 540, 660);
  }

  const pillW = 360;
  const pillH = 50;
  const pillX = Math.round((out.width - pillW) / 2);
  const pillY = nameLines.length > 1 ? 684 : 655;
  drawErpRoundedRect(ctx, pillX, pillY, pillW, pillH, 25);
  ctx.fillStyle = 'rgba(67, 217, 147, 0.16)';
  ctx.fill();
  ctx.strokeStyle = 'rgba(67, 217, 147, 0.45)';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.fillStyle = '#43d993';
  ctx.font = '800 22px "Plus Jakarta Sans", "Segoe UI", sans-serif';
  ctx.fillText('SOCIO/A CLUB FIDEL', 540, pillY + 33);

  // 5. Tarjeta blanca central con el Código QR Dual
  const qrBoxSize = 620;
  const qrBoxX = Math.round((out.width - qrBoxSize) / 2);
  const qrBoxY = 765;
  ctx.save();
  ctx.shadowColor = 'rgba(0, 0, 0, 0.42)';
  ctx.shadowBlur = 40;
  ctx.shadowOffsetY = 16;
  drawErpRoundedRect(ctx, qrBoxX, qrBoxY, qrBoxSize, qrBoxSize, 44);
  ctx.fillStyle = '#ffffff';
  ctx.fill();
  ctx.restore();

  ctx.drawImage(qrCanvas, qrBoxX + 34, qrBoxY + 34, qrBoxSize - 68, qrBoxSize - 68);

  // 6. Pie con Mascota de Club Fidel + Leyenda dual (Caja + Registración Web)
  const footerTopY = 1435;
  if (mascotaImg) {
    const mH = 390;
    const mW = Math.round((mascotaImg.width / mascotaImg.height) * mH);
    ctx.save();
    ctx.shadowColor = 'rgba(0, 0, 0, 0.45)';
    ctx.shadowBlur = 24;
    ctx.shadowOffsetY = 10;
    ctx.drawImage(mascotaImg, 105, footerTopY, mW, mH);
    ctx.restore();
  }

  const infoX = 390;
  const infoW = 540;
  const infoY = 1515;
  const infoH = 244;
  drawErpRoundedRect(ctx, infoX, infoY, infoW, infoH, 28);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.08)';
  ctx.fill();
  ctx.strokeStyle = 'rgba(67, 217, 147, 0.30)';
  ctx.lineWidth = 2.5;
  ctx.stroke();

  ctx.textAlign = 'left';
  ctx.fillStyle = '#43d993';
  ctx.font = '900 34px "Plus Jakarta Sans", "Segoe UI", sans-serif';
  ctx.fillText('ESCANEAR EN CAJA', infoX + 30, infoY + 60);
  ctx.fillText('O EN TU CELULAR', infoX + 30, infoY + 100);

  ctx.fillStyle = 'rgba(255, 255, 255, 0.94)';
  ctx.font = '600 28px "Plus Jakarta Sans", "Segoe UI", sans-serif';
  ctx.fillText('Sumá puntos en Casa Nueva o', infoX + 30, infoY + 148);
  ctx.fillText('escanealo para registrarte gratis', infoX + 30, infoY + 184);
  ctx.fillStyle = '#f5d061';
  ctx.font = '800 28px "Plus Jakarta Sans", "Segoe UI", sans-serif';
  const cleanDomain = String(ACTIVE_BRAND.domain || 'cn.com.ar').replace(/^www\./i, '');
  ctx.fillText(`www.${cleanDomain}/carrito`, infoX + 30, infoY + 224);

  const cleanNameSlug = fullName.replace(/[^A-Z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 28) || 'SOCIO';
  const link = document.createElement('a');
  link.download = `Credencial_Historia_${ACTIVE_BRAND.clubName.replace(/\s+/g, '_')}_${cleanNameSlug}.png`;
  link.href = out.toDataURL('image/png');
  link.click();
}

function selectFidelizacionClient(client) {
  if (!client) return;
  STATE.fidSelectedClientId = client.id;
  const searchInp = document.getElementById('fid-dni-search-input');
  const sugBox = document.getElementById('fid-dni-suggestions');
  if (sugBox) sugBox.hidden = true;
  if (searchInp) {
    const dni = extractDisplayDni(client);
    searchInp.value = dni !== 'S/DNI' ? `${dni} — ${client.nombre}` : `${client.nombre} (Cód. #${client.codigo})`;
  }
  renderFidOperacionesClientView();
}

function renderFidOperacionesClientView() {
  recalcAllClientsFidelizacionPoints();
  updateFidelizacionKpisAndSummary();

  const client = STATE.clientes.find((c) => Number(c.id) === Number(STATE.fidSelectedClientId));
  const selectedPanel = document.getElementById('fid-selected-client-panel');

  if (!client) {
    if (selectedPanel) selectedPanel.hidden = true;
    return;
  }

  if (selectedPanel) selectedPanel.hidden = false;

  const setTxt = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val;
  };

  const dni = extractDisplayDni(client);
  const ptsVigentes = Number(client.puntosFidelizacion) || 0;
  const ptsAcum = Number(client.puntosAcumuladosHist) || 0;
  const ptsCanj = Number(client.puntosCanjeadosHist) || 0;

  setTxt('fid-cli-code-badge', `CÓD. #${client.codigo}`);
  setTxt('fid-cli-dni-badge', `DNI: ${dni}`);
  setTxt('fid-cli-name-heading', client.nombre);
  setTxt(
    'fid-cli-sub-info',
    `Lista: ${client.listaPrecio || 'MINORISTA'} · ${client.calle || 'S/D'} ${client.numero || ''} (${client.localidad || 'ALCIRA GIGENA'}) · Acumulados hist.: ${ptsAcum.toLocaleString('es-AR')} pts · Canjeados: ${ptsCanj.toLocaleString('es-AR')} pts`
  );
  setTxt('fid-cli-pts-vigentes', ptsVigentes.toLocaleString('es-AR'));
  setTxt(
    'fid-cli-pts-venc-hint',
    client.proximoVencimiento
      ? `Próx. venc.: ${client.proximoVencimiento} (${Number(client.proximoVencimientoPts || 0).toLocaleString('es-AR')} pts)`
      : 'Vigencia: 1 año desde cada fecha de emisión'
  );

  const waInput = document.getElementById('fid-cli-whatsapp');
  const emailInput = document.getElementById('fid-cli-email');
  if (waInput) setPhoneIntlField('fid-cli-whatsapp', 'fid-cli-whatsapp-cod-pais', client.celular || client.telefono || '');
  if (emailInput) emailInput.value = client.email || '';

  const prefCanal = String(client.canalFidelizacion || STATE.fidelizacionConfig.canalDefault || 'whatsapp').toLowerCase();
  document.querySelectorAll('input[name="fid_canal_pref"], input[name="fid-canal-envio"]').forEach((rad) => {
    rad.checked = rad.value === prefCanal;
  });

  updateFidPurchasePointsPreview();
  renderFidQuickCanjeCards();
  renderFidClientMovementsTable();
}

function updateFidPurchasePointsPreview() {
  const montoInp = document.getElementById('fid-compra-monto');
  const monto = Number(montoInp?.value || 0);
  const calc = calcPointsFromPurchase(monto);
  const pctStr = calc.pct.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const rawStr = calc.raw.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  const pctEl = document.getElementById('fid-calc-pct-txt');
  if (pctEl) pctEl.textContent = `${pctStr}%`;

  const formulaEl = document.getElementById('fid-calc-formula-txt');
  if (formulaEl) {
    formulaEl.textContent = `$ ${formatArs(monto)} × ${pctStr}% = ${rawStr} → Redondeo entero`;
  }

  const ptsInput = document.getElementById('fid-compra-puntos-calc');
  if (ptsInput) {
    ptsInput.value = String(calc.points);
  }

  const diasVenc = Number(STATE.fidelizacionConfig.diasVencimiento) || 365;
  const emisionEl = document.getElementById('fid-calc-emision-txt');
  if (emisionEl) emisionEl.textContent = todayFormatted();
  const vencEl = document.getElementById('fid-calc-venc-txt');
  if (vencEl) vencEl.textContent = `${addDaysToToday(diasVenc).formatted} (${diasVenc} días)`;
}

function renderFidQuickCanjeCards() {
  const container = document.getElementById('fid-canje-products-list');
  if (!container) return;

  const client = STATE.clientes.find((c) => Number(c.id) === Number(STATE.fidSelectedClientId));
  const clientPts = Number(client?.puntosFidelizacion) || 0;
  const qEl = document.getElementById('fid-canje-quick-q') || document.getElementById('fid-canje-search');
  const q = normalizeStr(qEl?.value || '');
  const onlyAffordableChk = document.getElementById('fid-canje-only-affordable');
  const onlyAffordable = Boolean(onlyAffordableChk?.checked);
  const tokens = q ? q.split(/\s+/).filter(Boolean) : [];

  const globalShowStockOnly = STATE.fidelizacionConfig.mostrarEnCatalogo === 'solo_stock';
  const canjeItems = STATE.articulos
    .filter((a) => {
      if (a.bl === 1 || Number(a.cfid) !== 1) return false;
      if (globalShowStockOnly && Number(a.sf) <= 0) return false;
      const ptsReq = calcArticleCanjePoints(a);
      if (onlyAffordable && (clientPts < ptsReq || Number(a.sf) <= 0)) return false;
      if (tokens.length > 0) {
        const hay = normalizeStr(`${a.c} ${a.n}`);
        if (!tokens.every((t) => hay.includes(t))) return false;
      }
      return true;
    })
    .sort((a, b) => calcArticleCanjePoints(a) - calcArticleCanjePoints(b));

  container.textContent = '';

  if (canjeItems.length === 0) {
    const emptyDiv = document.createElement('div');
    emptyDiv.className = 'table-loading-cell';
    emptyDiv.style.padding = '1.25rem';
    emptyDiv.textContent =
      onlyAffordable
        ? `El cliente tiene ${clientPts.toLocaleString('es-AR')} puntos vigentes y no alcanza aún para los productos del catálogo (destildá "Solo alcanzables con saldo" para ver todos).`
        : 'No hay productos incorporados al Catálogo de Canje para este filtro. Podés tildar "Canje" en la tabla de Artículos, dentro de la Ficha del Producto o en la sección "Catálogo de Canje".';
    container.appendChild(emptyDiv);
    return;
  }

  const frag = document.createDocumentFragment();
  canjeItems.slice(0, 60).forEach((art) => {
    const ptsReq = calcArticleCanjePoints(art);
    const hasStock = Number(art.sf) > 0;
    const canAfford = clientPts >= ptsReq;
    const canRedeem = Boolean(client) && hasStock && canAfford;

    const card = document.createElement('div');
    card.className = 'fid-canje-card' + (!canRedeem ? ' fid-canje-card--disabled' : '');

    const left = document.createElement('div');
    const title = document.createElement('div');
    title.className = 'fid-canje-card-title';
    title.textContent = `#${art.c} · ${art.n}`;

    const meta = document.createElement('div');
    meta.className = 'fid-canje-card-meta';
    const factor = Number(STATE.fidelizacionConfig.factorCanje) || 1.12;
    const modeLabel = Number(art.pfidManual) === 1
      ? 'Puntuación manual'
      : `Auto ${factor.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}×`;
    meta.innerHTML = `<span>Minorista: <strong>$ ${formatArs(art.p1f)}</strong> (${modeLabel})</span><span>Stock: <strong style="color:${hasStock ? 'var(--success)' : 'var(--danger)'};">${art.sf}</strong></span>`;
    if (client && !canAfford) {
      const falta = ptsReq - clientPts;
      const faltaSpan = document.createElement('span');
      faltaSpan.style.color = 'var(--gold-dark)';
      faltaSpan.textContent = `Faltan ${falta.toLocaleString('es-AR')} pts`;
      meta.appendChild(faltaSpan);
    }

    left.appendChild(title);
    left.appendChild(meta);

    const right = document.createElement('div');
    right.className = 'fid-canje-card-right';

    const ptsBadge = document.createElement('span');
    ptsBadge.className = 'fid-pts-badge';
    ptsBadge.innerHTML = `${erpClubFidelBadgeSvg(16)} ${ptsReq.toLocaleString('es-AR')} pts`;

    const btnCanje = document.createElement('button');
    btnCanje.type = 'button';
    btnCanje.className = canRedeem ? 'btn-primary btn-sm' : 'btn-secondary btn-sm';
    btnCanje.style.width = 'auto';
    btnCanje.disabled = !canRedeem;
    btnCanje.textContent = !hasStock ? 'Sin Stock' : canAfford ? '🎁 Canjear' : 'Saldo Insuf.';
    btnCanje.addEventListener('click', () => {
      if (!client) return;
      redeemClientCatalogProduct({
        clientId: client.id,
        artId: art.id,
        cantidad: 1,
        notify: true
      });
    });

    right.appendChild(ptsBadge);
    right.appendChild(btnCanje);

    card.appendChild(left);
    card.appendChild(right);
    frag.appendChild(card);
  });

  container.appendChild(frag);
}

function syncUnifiedPaginationControls(pageIndEl, prevBtnEl, nextBtnEl, currentPage, totalPages, onPageChange) {
  const cur = Math.max(1, Number(currentPage) || 1);
  const tot = Math.max(1, Number(totalPages) || 1);
  if (prevBtnEl) {
    prevBtnEl.textContent = '‹ Anterior';
    prevBtnEl.disabled = cur <= 1;
  }
  if (nextBtnEl) {
    nextBtnEl.textContent = 'Siguiente ›';
    nextBtnEl.disabled = cur >= tot;
  }
  if (!pageIndEl) return;
  pageIndEl.textContent = `Página ${cur.toLocaleString('es-AR')} de ${tot.toLocaleString('es-AR')}`;

  const parent = pageIndEl.parentElement;
  if (!parent) return;
  let numsWrap = parent.querySelector('.pagination-numbers');
  if (!numsWrap) {
    numsWrap = document.createElement('div');
    numsWrap.className = 'pagination-numbers';
    numsWrap.style.cssText = 'display:inline-flex; align-items:center; gap:0.3rem; flex-wrap:wrap;';
    parent.insertBefore(numsWrap, pageIndEl);
  }
  numsWrap.textContent = '';

  const start = Math.max(1, Math.min(cur - 2, Math.max(1, tot - 4)));
  const end = Math.min(tot, start + 4);
  for (let p = start; p <= end; p++) {
    const isAct = p === cur;
    const btnNum = document.createElement('button');
    btnNum.type = 'button';
    btnNum.className = `btn-page-num${isAct ? ' is-active' : ''}`;
    btnNum.style.cssText = isAct
      ? 'min-width:34px; height:34px; padding:0 0.5rem; border-radius:8px; border:1px solid var(--gold-primary, #c89b2b); background:var(--gold-primary, #c89b2b); color:#ffffff; font-size:0.84rem; font-weight:700; cursor:pointer; width:auto;'
      : 'min-width:34px; height:34px; padding:0 0.5rem; border-radius:8px; border:1px solid var(--border-subtle, #e2e8f0); background:#ffffff; color:var(--text-primary, #0f172a); font-size:0.84rem; font-weight:600; cursor:pointer; width:auto;';
    btnNum.textContent = String(p);
    btnNum.addEventListener('click', () => {
      if (p !== cur && typeof onPageChange === 'function') {
        onPageChange(p);
      }
    });
    numsWrap.appendChild(btnNum);
  }
}

function renderTenByTenPaginationBar({
  containerId,
  totalItems = 0,
  pageSize = FID_PAGE_SIZE,
  currentPage = 1,
  itemLabel = 'registros',
  onPageChange
}) {
  const pagBar = document.getElementById(containerId);
  if (!pagBar) return;
  pagBar.textContent = '';

  if (totalItems <= 0) {
    pagBar.hidden = true;
    return;
  }

  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const cur = Math.min(Math.max(1, Number(currentPage) || 1), totalPages);
  pagBar.hidden = false;
  pagBar.style.display = 'flex';
  pagBar.style.alignItems = 'center';
  pagBar.style.justifyContent = 'flex-start';
  pagBar.style.flexWrap = 'wrap';
  pagBar.style.gap = '0.45rem';
  pagBar.style.marginTop = '0.7rem';
  pagBar.style.padding = '0.55rem 0.9rem';
  pagBar.style.borderRadius = '12px';
  pagBar.style.border = '1px solid var(--border-subtle, #e2e8f0)';
  pagBar.style.background = 'var(--bg-surface, #ffffff)';

  const btnPrev = document.createElement('button');
  btnPrev.type = 'button';
  btnPrev.className = 'btn-page';
  btnPrev.style.cssText = 'min-height:34px; padding:0.35rem 0.85rem; border-radius:8px; border:1px solid var(--border-subtle, #e2e8f0); background:#ffffff; color:var(--text-primary, #0f172a); font-size:0.84rem; font-weight:500; cursor:pointer; width:auto;';
  btnPrev.disabled = cur <= 1;
  if (btnPrev.disabled) btnPrev.style.opacity = '0.48';
  btnPrev.textContent = '‹ Anterior';
  btnPrev.addEventListener('click', () => {
    if (cur > 1 && typeof onPageChange === 'function') {
      onPageChange(cur - 1);
    }
  });
  pagBar.appendChild(btnPrev);

  const numsWrap = document.createElement('div');
  numsWrap.className = 'pagination-numbers';
  numsWrap.style.cssText = 'display:inline-flex; align-items:center; gap:0.3rem; flex-wrap:wrap;';
  const start = Math.max(1, Math.min(cur - 2, Math.max(1, totalPages - 4)));
  const end = Math.min(totalPages, start + 4);
  for (let p = start; p <= end; p++) {
    const isAct = p === cur;
    const btnNum = document.createElement('button');
    btnNum.type = 'button';
    btnNum.className = `btn-page-num${isAct ? ' is-active' : ''}`;
    btnNum.style.cssText = isAct
      ? 'min-width:34px; height:34px; padding:0 0.5rem; border-radius:8px; border:1px solid var(--gold-primary, #c89b2b); background:var(--gold-primary, #c89b2b); color:#ffffff; font-size:0.84rem; font-weight:700; cursor:pointer; width:auto;'
      : 'min-width:34px; height:34px; padding:0 0.5rem; border-radius:8px; border:1px solid var(--border-subtle, #e2e8f0); background:#ffffff; color:var(--text-primary, #0f172a); font-size:0.84rem; font-weight:600; cursor:pointer; width:auto;';
    btnNum.textContent = String(p);
    btnNum.addEventListener('click', () => {
      if (p !== cur && typeof onPageChange === 'function') {
        onPageChange(p);
      }
    });
    numsWrap.appendChild(btnNum);
  }
  pagBar.appendChild(numsWrap);

  const pageIndSpan = document.createElement('span');
  pageIndSpan.className = 'page-indicator';
  pageIndSpan.style.cssText = 'font-size:0.84rem; font-weight:600; color:var(--silver-muted, #475569); padding:0 0.45rem; white-space:nowrap;';
  pageIndSpan.textContent = `Página ${cur.toLocaleString('es-AR')} de ${totalPages.toLocaleString('es-AR')}`;
  pagBar.appendChild(pageIndSpan);

  const btnNext = document.createElement('button');
  btnNext.type = 'button';
  btnNext.className = 'btn-page';
  btnNext.style.cssText = 'min-height:34px; padding:0.35rem 0.85rem; border-radius:8px; border:1px solid var(--border-subtle, #e2e8f0); background:#ffffff; color:var(--text-primary, #0f172a); font-size:0.84rem; font-weight:500; cursor:pointer; width:auto; margin-left:auto;';
  btnNext.disabled = cur >= totalPages;
  if (btnNext.disabled) btnNext.style.opacity = '0.48';
  btnNext.textContent = 'Siguiente ›';
  btnNext.addEventListener('click', () => {
    if (cur < totalPages && typeof onPageChange === 'function') {
      onPageChange(cur + 1);
    }
  });
  pagBar.appendChild(btnNext);
}

function stampTableDataLabelsFromThead(table) {
  if (!table || !table.tHead) return;
  const headerRow = table.tHead.rows && table.tHead.rows[table.tHead.rows.length - 1];
  if (!headerRow) return;

  const visibleHeaders = Array.from(headerRow.cells)
    .filter((th) => !th.hidden)
    .map((th) => String(th.textContent || '').replace(/\s+/g, ' ').trim().replace(/:$/, ''));

  if (visibleHeaders.length === 0) return;

  Array.from(table.tBodies || []).forEach((tbody) => {
    Array.from(tbody.rows || []).forEach((tr) => {
      const visibleCells = Array.from(tr.cells || []).filter((cell) => !cell.hidden);
      if (visibleCells.length === 1 && visibleCells[0].colSpan > 1) return;
      visibleCells.forEach((cell, idx) => {
        if (cell.tagName !== 'TD') return;
        if (cell.classList.contains('table-loading-cell')) return;
        if (!cell.dataset.label && visibleHeaders[idx]) {
          cell.dataset.label = visibleHeaders[idx];
        }
      });
    });
  });
}

function installCatalogTablesMobileLabelsObserver() {
  const tables = document.querySelectorAll('table.catalog-table');
  tables.forEach((table) => {
    if (table.dataset.mobileLabelsObserved === '1') return;
    table.dataset.mobileLabelsObserved = '1';
    stampTableDataLabelsFromThead(table);

    Array.from(table.tBodies || []).forEach((tbody) => {
      const obs = new MutationObserver(() => {
        stampTableDataLabelsFromThead(table);
      });
      obs.observe(tbody, { childList: true });
    });

    if (table.tHead) {
      const headObs = new MutationObserver(() => {
        Array.from(table.tBodies || []).forEach((tbody) => {
          Array.from(tbody.querySelectorAll('td[data-auto-label="1"]')).forEach((td) => {
            delete td.dataset.label;
            delete td.dataset.autoLabel;
          });
        });
        stampTableDataLabelsFromThead(table);
      });
      headObs.observe(table.tHead, { subtree: true, attributes: true, attributeFilter: ['hidden'] });
    }
  });
}

function renderFidClientMovementsTable(page = null) {
  const tbody = document.getElementById('fid-ledger-tbody') || document.getElementById('fid-movimientos-tbody');
  if (!tbody) return;
  if (typeof page === 'number' && isFinite(page)) {
    STATE.fidLedgerPage = Math.max(1, Math.floor(page));
  }

  const client = STATE.clientes.find((c) => Number(c.id) === Number(STATE.fidSelectedClientId));
  const filterSel = document.getElementById('fid-ledger-filter-tipo') || document.getElementById('fid-movs-filter-estado');
  const filterEst = String(filterSel?.value || 'todos').toLowerCase();
  const countBadge = document.getElementById('fid-ledger-status-msg') || document.getElementById('fid-movs-count-badge');

  if (!client) {
    tbody.innerHTML = '<tr><td colspan="9" class="table-loading-cell">Seleccioná un cliente por DNI para visualizar sus lotes de puntos y fechas de vencimiento.</td></tr>';
    if (countBadge) countBadge.textContent = '0 movimientos';
    renderTenByTenPaginationBar({ containerId: 'fid-ledger-pagination-bar', totalItems: 0 });
    return;
  }

  const allMovs = STATE.movimientosFidelizacion.filter((m) => Number(m.clientId ?? m.cId ?? 0) === Number(client.id));
  const filteredMovs = allMovs.filter((m) => {
    if (filterEst === 'todos') return true;
    const tipo = String(m.tipo || 'SUMA').toUpperCase();
    const est = String(m.estado || 'VIGENTE').toUpperCase();
    if (filterEst === 'vigente' || filterEst === 'vigentes') return tipo === 'SUMA' && est === 'VIGENTE' && Number(m.puntosRestantes) > 0;
    if (filterEst === 'suma') return tipo === 'SUMA';
    if (filterEst === 'canje' || filterEst === 'canjeados') return tipo === 'CANJE' || est === 'CANJEADO';
    if (filterEst === 'vencido' || filterEst === 'vencidos') return est === 'VENCIDO';
    return true;
  });

  const totalMovs = filteredMovs.length;
  const totalPages = Math.max(1, Math.ceil(totalMovs / FID_PAGE_SIZE));
  STATE.fidLedgerPage = Math.min(Math.max(1, Number(STATE.fidLedgerPage) || 1), totalPages);
  const startIdx = (STATE.fidLedgerPage - 1) * FID_PAGE_SIZE;
  const pageMovs = filteredMovs.slice(startIdx, startIdx + FID_PAGE_SIZE);

  if (countBadge) {
    countBadge.textContent =
      totalMovs > 0
        ? `Página ${STATE.fidLedgerPage} de ${totalPages} (${totalMovs} movimiento(s) de ${client.nombre})`
        : `0 movimientos de ${client.nombre} para este filtro`;
  }

  tbody.textContent = '';
  if (pageMovs.length === 0) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = 9;
    td.className = 'table-loading-cell';
    td.textContent = 'No hay movimientos de puntos registrados para este filtro.';
    tr.appendChild(td);
    tbody.appendChild(tr);
    renderTenByTenPaginationBar({ containerId: 'fid-ledger-pagination-bar', totalItems: 0 });
    return;
  }

  const frag = document.createDocumentFragment();
  pageMovs.forEach((m) => {
    const tr = document.createElement('tr');
    const isSuma = String(m.tipo || 'SUMA').toUpperCase() === 'SUMA';

    const th = document.createElement('th');
    th.scope = 'row';
    th.innerHTML = `<span class="art-code-pill">${escapeHtml(m.nroTicketCanje || ('#' + m.id))}</span> <span class="price-neto-val">${m.fechaEmision || ''} ${m.hora || ''}</span>`;
    tr.appendChild(th);

    const tdVenc = document.createElement('td');
    tdVenc.dataset.label = 'Vencimiento (1 Año)';
    tdVenc.textContent = isSuma ? (m.fechaVencimiento || formatIsoToDdMmYyyy(m.fechaVencimientoIso || m.fechaVencIso)) : '—';
    tr.appendChild(tdVenc);

    const tdTipo = document.createElement('td');
    tdTipo.dataset.label = 'Tipo';
    tdTipo.innerHTML = isSuma
      ? '<span class="badge badge--green">➕ SUMA COMPRA</span>'
      : '<span class="badge badge--gold">🎁 CANJE PREMIO</span>';
    tr.appendChild(tdTipo);

    const tdDet = document.createElement('td');
    tdDet.dataset.label = 'Comprobante / Detalle';
    tdDet.innerHTML = `<div class="price-cell-stack"><strong>${m.comprobante || 'OP'}</strong><span class="price-neto-val">${m.observacion || m.obs || ''}</span></div>`;
    tr.appendChild(tdDet);

    const tdMonto = document.createElement('td');
    tdMonto.dataset.label = 'Monto Compra';
    tdMonto.style.textAlign = 'right';
    tdMonto.textContent = isSuma && Number(m.montoCompra) > 0 ? `$ ${formatArs(m.montoCompra)}` : '—';
    tr.appendChild(tdMonto);

    const tdPts = document.createElement('td');
    tdPts.dataset.label = 'Puntos Mov.';
    tdPts.style.textAlign = 'right';
    const ptsNum = Math.round(Number(m.puntos) || 0);
    tdPts.innerHTML = `<strong style="color:${ptsNum >= 0 ? 'var(--success)' : 'var(--gold-dark)'}; font-size:0.95rem;">${ptsNum >= 0 ? '+' : ''}${ptsNum.toLocaleString('es-AR')} pts</strong>`;
    tr.appendChild(tdPts);

    const tdRest = document.createElement('td');
    tdRest.dataset.label = 'Saldo Lote';
    tdRest.style.textAlign = 'right';
    tdRest.textContent = isSuma ? `${Math.max(0, Math.round(Number(m.puntosRestantes) || 0)).toLocaleString('es-AR')} pts` : '—';
    tr.appendChild(tdRest);

    const tdEst = document.createElement('td');
    tdEst.dataset.label = 'Estado';
    const est = String(m.estado || 'VIGENTE').toUpperCase();
    if (!isSuma) {
      tdEst.innerHTML = '<span class="badge badge--gold">APLICADO</span>';
    } else if (est === 'VENCIDO') {
      tdEst.innerHTML = '<span class="saldo-badge saldo-badge--deudor">VENCIDO (+1 AÑO)</span>';
    } else if (Number(m.puntosRestantes) <= 0) {
      tdEst.innerHTML = '<span class="badge">CONSUMIDO EN CANJE</span>';
    } else {
      tdEst.innerHTML = '<span class="badge badge--green">VIGENTE</span>';
    }
    tr.appendChild(tdEst);

    const tdReenviar = document.createElement('td');
    tdReenviar.dataset.label = 'Notificación';
    const btnWa = document.createElement('button');
    btnWa.type = 'button';
    btnWa.className = 'btn-secondary btn-sm';
    btnWa.textContent = '📲 Reenviar';
    btnWa.addEventListener('click', () => {
      const dni = extractDisplayDni(client);
      const msg = isSuma
        ? formatFidelizacionTemplate(STATE.fidelizacionConfig.plantillaSuma, {
            nombre: client.nombre,
            dni,
            puntosSumados: Math.abs(ptsNum),
            monto: m.montoCompra || 0,
            saldoPuntos: client.puntosFidelizacion || 0,
            vencimiento: m.fechaVencimiento || ''
          })
        : formatFidelizacionTemplate(STATE.fidelizacionConfig.plantillaCanje, {
            nombre: client.nombre,
            dni,
            producto: m.productoNombre || m.observacion || 'Producto Catálogo',
            cantidad: m.cantidad || 1,
            puntosCanjeados: Math.abs(ptsNum),
            saldoPuntos: client.puntosFidelizacion || 0
          });
      triggerFidelizacionNotification(client, client.canalFidelizacion || STATE.fidelizacionConfig.canalDefault, msg, 'Aviso de Puntos - Casa Nueva Supermercado', true);
    });
    tdReenviar.appendChild(btnWa);
    tr.appendChild(tdReenviar);

    frag.appendChild(tr);
  });

  tbody.appendChild(frag);
  renderTenByTenPaginationBar({
    containerId: 'fid-ledger-pagination-bar',
    totalItems: totalMovs,
    pageSize: FID_PAGE_SIZE,
    currentPage: STATE.fidLedgerPage,
    itemLabel: 'movimientos',
    onPageChange: (nextPage) => renderFidClientMovementsTable(nextPage)
  });
}

async function accreditClientPurchasePoints({
  clientId,
  montoCompra,
  comprobante = '',
  observacion = '',
  notify = true,
  canalOverride = '',
  items = null,
  fechaIso = '',
  rubroId = 0
}) {
  const client = STATE.clientes.find((c) => Number(c.id) === Number(clientId));
  if (!client) return { ok: false, message: 'Cliente no encontrado.' };

  const calc = Array.isArray(items) && items.length > 0
    ? calcPointsFromPosSaleItems(items, montoCompra, fechaIso)
    : calcPointsFromPurchase(montoCompra, null, rubroId, fechaIso);
  if (calc.points <= 0) {
    return { ok: false, message: 'El monto ingresado no alcanza para generar al menos 1 punto entero.' };
  }

  const dni = extractDisplayDni(client);
  const diasVenc = Number(STATE.fidelizacionConfig.diasVencimiento) || 365;
  const vencObj = addDaysToToday(diasVenc);
  const now = new Date();
  const fechaEmisionIso = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  const fechaEmision = todayFormatted();
  const hora = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
  const canal = canalOverride || client.canalFidelizacion || STATE.fidelizacionConfig.canalDefault || 'whatsapp';

  const nextBalancePreview = (Number(client.puntosFidelizacion) || 0) + calc.points;
  const msgText = formatFidelizacionTemplate(STATE.fidelizacionConfig.plantillaSuma, {
    nombre: client.nombre,
    dni,
    puntosSumados: calc.points,
    monto: montoCompra,
    saldoPuntos: nextBalancePreview,
    vencimiento: vencObj.formatted
  });

  let serverMov = null;
  let alreadyExists = false;
  let twilioDispatched = false;
  try {
    const res = await fetch('api/clientes.php', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'add_fidelizacion_points',
        cId: client.id,
        idCliente: client.id,
        clienteCodigo: client.codigo || '',
        dni: client.nroDoc || dni || '',
        montoCompra,
        porcentaje: calc.pct,
        porcentajeAplicado: calc.pct,
        comprobante: comprobante || 'TICKET COMPRA',
        obs: observacion || `COMPRA $ ${formatArs(montoCompra)} (${calc.pct.toLocaleString('es-AR', { minimumFractionDigits: 2 })}%)`,
        observacion: observacion || `COMPRA $ ${formatArs(montoCompra)} (${calc.pct.toLocaleString('es-AR', { minimumFractionDigits: 2 })}%)`,
        canalEnviado: canal,
        canalNotificacion: canal,
        mensajeNotificacion: notify ? msgText : ''
      })
    });
    if (res.ok) {
      const json = await res.json();
      if (json && json.ok && json.movement) {
        serverMov = json.movement;
        alreadyExists = Boolean(json.alreadyExists);
        twilioDispatched = Boolean(json.twilioResult && json.twilioResult.ok);
      }
    }
  } catch {}

  const newMov = serverMov || {
    id: STATE.movimientosFidelizacion.reduce((m, x) => Math.max(m, Number(x.id) || 0), 0) + 1,
    cId: client.id,
    clientId: client.id,
    dni: client.nroDoc || '',
    clienteNombre: client.nombre,
    tipo: 'SUMA',
    fechaEmisionIso,
    fechaEmision,
    hora,
    fechaVencIso: vencObj.iso,
    fechaVencimientoIso: vencObj.iso,
    fechaVencimiento: vencObj.formatted,
    montoCompra: round2(montoCompra),
    porcentajeAplicado: calc.pct,
    puntos: calc.points,
    puntosRestantes: calc.points,
    comprobante: comprobante || 'TICKET COMPRA',
    obs: observacion || `COMPRA $ ${formatArs(montoCompra)}`,
    observacion: observacion || `COMPRA $ ${formatArs(montoCompra)}`,
    canalEnviado: canal,
    canalNotificado: canal,
    estado: 'VIGENTE'
  };

  if (!alreadyExists) {
    STATE.movimientosFidelizacion.unshift(newMov);
  } else if (serverMov && !STATE.movimientosFidelizacion.some((m) => Number(m.id) === Number(serverMov.id))) {
    STATE.movimientosFidelizacion.unshift(newMov);
  }
  recalcAllClientsFidelizacionPoints();
  saveLocalFidelizacionStore();

  if (notify && !twilioDispatched) {
    triggerFidelizacionNotification(
      client,
      canal,
      msgText,
      `¡Sumaste +${calc.points} puntos en Casa Nueva Supermercado!`,
      true
    );
  }

  updateFidelizacionKpisAndSummary();
  if (Number(STATE.fidSelectedClientId) === Number(client.id)) {
    renderFidOperacionesClientView();
  }
  return { ok: true, movement: newMov, pointsAdded: calc.points, newBalance: client.puntosFidelizacion };
}

async function redeemClientCatalogProduct({ clientId, artId, cantidad = 1, notify = true }) {
  const client = STATE.clientes.find((c) => Number(c.id) === Number(clientId));
  const art = STATE.articulos.find((a) => Number(a.id) === Number(artId));
  if (!client || !art) return { ok: false, message: 'Cliente o producto no encontrado.' };

  const qty = Math.max(1, Math.round(Number(cantidad) || 1));
  const ptsUnit = calcArticleCanjePoints(art);
  const ptsTotal = ptsUnit * qty;

  recalcAllClientsFidelizacionPoints();
  const activeBalance = Number(client.puntosFidelizacion) || 0;
  if (activeBalance < ptsTotal) {
    return {
      ok: false,
      message: `Saldo insuficiente: el cliente tiene ${activeBalance.toLocaleString('es-AR')} pts vigentes y el canje requiere ${ptsTotal.toLocaleString('es-AR')} pts.`
    };
  }

  const dni = extractDisplayDni(client);
  const canal = client.canalFidelizacion || STATE.fidelizacionConfig.canalDefault || 'whatsapp';
  const nextBalancePreview = activeBalance - ptsTotal;
  const msgText = formatFidelizacionTemplate(STATE.fidelizacionConfig.plantillaCanje, {
    nombre: client.nombre,
    dni,
    producto: art.n,
    cantidad: qty,
    puntosCanjeados: ptsTotal,
    saldoPuntos: nextBalancePreview
  });

  let serverHandled = false;
  let serverMov = null;
  try {
    const res = await fetch('api/clientes.php', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'redeem_fidelizacion_product',
        cId: client.id,
        idCliente: client.id,
        artId: art.id,
        idArticulo: art.id,
        artCodigo: art.c,
        codigoArticulo: art.c,
        artNombre: art.n,
        nombreArticulo: art.n,
        cantidad: qty,
        puntosRequeridos: ptsTotal,
        entregarAhora: false,
        canalNotificacion: canal,
        mensajeNotificacion: notify ? msgText : ''
      })
    });
    if (res.ok) {
      const json = await res.json();
      if (json && json.ok && json.movement) {
        serverHandled = true;
        serverMov = json.movement;
      }
    }
  } catch {}

  const now = new Date();
  const todayIso = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  let toDeduct = ptsTotal;
  const clientSumaMovs = STATE.movimientosFidelizacion
    .filter(
      (m) =>
        Number(m.clientId ?? m.cId ?? 0) === Number(client.id) &&
        String(m.tipo || 'SUMA').toUpperCase() === 'SUMA' &&
        Number(m.puntosRestantes) > 0 &&
        (!(m.fechaVencimientoIso || m.fechaVencIso) || (m.fechaVencimientoIso || m.fechaVencIso) >= todayIso)
    )
    .sort((a, b) => String(a.fechaEmisionIso || '').localeCompare(String(b.fechaEmisionIso || '')));

  for (const m of clientSumaMovs) {
    if (toDeduct <= 0) break;
    const avail = Number(m.puntosRestantes) || 0;
    const take = Math.min(avail, toDeduct);
    m.puntosRestantes = avail - take;
    if (m.puntosRestantes <= 0) m.estado = 'CANJEADO';
    toDeduct -= take;
  }

  const nextMovId = serverMov?.id || (STATE.movimientosFidelizacion.reduce((m, x) => Math.max(m, Number(x.id) || 0), 0) + 1);
  const nroTicketCanje = serverMov?.nroTicketCanje || `CJ-${String(nextMovId).padStart(5, '0')}`;

  const canjeMov = {
    id: nextMovId,
    cId: client.id,
    clientId: client.id,
    clienteCodigo: String(client.codigo || client.id),
    dni: client.nroDoc || '',
    clienteNombre: client.nombre,
    tipo: 'CANJE',
    nroTicketCanje,
    fechaEmisionIso: todayIso,
    fechaEmision: todayFormatted(),
    hora: `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`,
    fechaVencimientoIso: null,
    fechaVencimiento: '—',
    montoCompra: 0,
    artId: art.id,
    articuloId: art.id,
    artCodigo: art.c,
    articuloCodigo: art.c,
    artNombre: art.n,
    productoNombre: art.n,
    cantidad: qty,
    estadoEntrega: serverMov?.estadoEntrega || 'PENDIENTE',
    stockDescontado: Boolean(serverMov?.stockDescontado),
    fechaEntrega: serverMov?.fechaEntrega || '',
    entregadoPor: serverMov?.entregadoPor || '',
    origenCanje: 'ERP',
    puntos: -ptsTotal,
    puntosRestantes: 0,
    comprobante: `TICKET ${nroTicketCanje} · CANJE #${art.c} (${art.n})`,
    observacion: `CANJE ${nroTicketCanje}: ${qty}x ${art.n} (#${art.c})`,
    obs: `CANJE ${nroTicketCanje}: ${qty}x ${art.n} (#${art.c})`,
    canalNotificado: canal,
    estado: 'APLICADO'
  };

  STATE.movimientosFidelizacion.unshift(canjeMov);
  recalcAllClientsFidelizacionPoints();
  saveLocalFidelizacionStore();

  const feedbackEl = document.getElementById('fid-op-success') || document.getElementById('fid-canje-feedback');
  if (feedbackEl) {
    feedbackEl.innerHTML = `
      <div style="display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:0.75rem;">
        <div>
          <strong>¡Canje registrado! (Ticket ${escapeHtml(nroTicketCanje)})</strong> Se descontaron <strong>-${ptsTotal.toLocaleString('es-AR')} pts</strong> por <strong>${qty}x ${escapeHtml(art.n)}</strong>.
          Nuevo saldo vigente: <strong>${client.puntosFidelizacion.toLocaleString('es-AR')} pts</strong>.
          <span style="display:block; font-size:0.82rem; margin-top:0.2rem;">⏳ Estado: <strong>Pendiente de Entrega</strong> (el Stock se descuenta al confirmar la entrega en <em>Canjes Efectuados</em>).</span>
        </div>
        <div style="display:flex; gap:0.5rem; flex-wrap:wrap;">
          <button type="button" class="btn-secondary btn-sm" id="btn-fid-op-print-last-ticket" style="width:auto;">🎫 Imprimir Ticket de Retiro</button>
          <button type="button" class="btn-primary btn-sm" id="btn-fid-op-go-canjes" style="width:auto;">📦 Ir a Canjes Efectuados (Entregar)</button>
        </div>
      </div>
    `;
    feedbackEl.hidden = false;
    document.getElementById('btn-fid-op-print-last-ticket')?.addEventListener('click', () => {
      printFidelizacionCanjeTicket(canjeMov);
    });
    document.getElementById('btn-fid-op-go-canjes')?.addEventListener('click', () => {
      document.querySelectorAll('.erp-section').forEach((sec) => {
        sec.hidden = sec.id !== 'sec-fid-canjes';
      });
      updateTopbarModuleState('sec-fid-canjes');
      renderFidCanjesSection();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

  if (notify) {
    triggerFidelizacionNotification(
      client,
      canal,
      msgText,
      `Confirmación de Canje de Puntos - Casa Nueva Supermercado`,
      true
    );
  }

  updateFidelizacionKpisAndSummary();
  renderFidOperacionesClientView();
  updateKpis();
  return { ok: true, movement: canjeMov, serverHandled };
}

function applyFidCatalogoFilters(page = 1) {
  const q = normalizeStr(document.getElementById('fid-cat-q')?.value || '');
  const rubroId = Number(document.getElementById('fid-cat-rubro')?.value) || 0;
  const marcaId = Number(document.getElementById('fid-cat-marca')?.value) || 0;
  const estadoSel = document.getElementById('fid-cat-filter-estado') || document.getElementById('fid-cat-estado');
  const estadoCanje = estadoSel?.value || 'incluidos';
  const globalStockSel = document.getElementById('fid-cat-global-stock-mode');
  const stockMode =
    globalStockSel?.value ||
    STATE.fidelizacionConfig.mostrarEnCatalogo ||
    document.getElementById('fid-cat-stock')?.value ||
    'todos';
  const ordenMode = document.getElementById('fid-cat-orden')?.value || 'canje_primero';
  const tokens = q ? q.split(/\s+/).filter(Boolean) : [];

  const filtered = STATE.articulos.filter((art) => {
    if (art.bl === 1) return false;
    if (rubroId > 0 && Number(art.r) !== rubroId) return false;
    if (marcaId > 0 && Number(art.mk) !== marcaId) return false;
    if (estadoCanje === 'incluidos' && Number(art.cfid) !== 1) return false;
    if (estadoCanje === 'no_incluidos' && Number(art.cfid) === 1) return false;
    if ((stockMode === 'solo_stock' || stockMode === 'positivo' || stockMode === 'con_stock') && Number(art.sf) <= 0) return false;
    if (stockMode === 'sinstock' && Number(art.sf) > 0) return false;

    if (tokens.length > 0) {
      const bcStr = Array.isArray(art.bc) ? art.bc.map((b) => b.c).join(' ') : '';
      const hay = normalizeStr(`${art.c} ${art.n} ${bcStr}`);
      if (!tokens.every((t) => hay.includes(t))) return false;
    }
    return true;
  });

  filtered.sort((a, b) => {
    if (ordenMode === 'canje_primero') {
      const diffCfid = (Number(b.cfid) === 1 ? 1 : 0) - (Number(a.cfid) === 1 ? 1 : 0);
      if (diffCfid !== 0) return diffCfid;
      return calcArticleCanjePoints(a) - calcArticleCanjePoints(b);
    }
    if (ordenMode === 'menor_puntos') {
      return calcArticleCanjePoints(a) - calcArticleCanjePoints(b);
    }
    if (ordenMode === 'mayor_puntos') {
      return calcArticleCanjePoints(b) - calcArticleCanjePoints(a);
    }
    return String(a.n || '').localeCompare(String(b.n || ''), 'es');
  });

  STATE.fidCatFiltered = filtered;

  const totalPages = Math.max(1, Math.ceil(STATE.fidCatFiltered.length / FID_PAGE_SIZE));
  STATE.fidCatPage = Math.min(Math.max(1, page), totalPages);
  renderFidCatalogoTable();
  updateFidelizacionKpisAndSummary();
}

function renderFidCatalogoTable() {
  const tbody = document.getElementById('fid-cat-tbody') || document.getElementById('fid-catalogo-tbody');
  const statusEl = document.getElementById('fid-cat-status-msg');
  const pageInd = document.getElementById('fid-cat-page-ind');
  const prevBtn = document.getElementById('btn-fid-cat-prev');
  const nextBtn = document.getElementById('btn-fid-cat-next');
  if (!tbody) return;

  const estadoSel = document.getElementById('fid-cat-filter-estado') || document.getElementById('fid-cat-estado');
  const estadoCanje = estadoSel?.value || 'incluidos';
  const totalInCanjeGlobal = STATE.articulos.filter((a) => a.bl !== 1 && Number(a.cfid) === 1).length;

  const total = STATE.fidCatFiltered.length;
  const totalPages = Math.max(1, Math.ceil(total / FID_PAGE_SIZE));
  const startIdx = (STATE.fidCatPage - 1) * FID_PAGE_SIZE;
  const pageItems = STATE.fidCatFiltered.slice(startIdx, startIdx + FID_PAGE_SIZE);

  if (statusEl) {
    if (total === 0) {
      statusEl.textContent = '0 productos encontrados para este filtro';
    } else {
      statusEl.textContent =
        estadoCanje === 'incluidos'
          ? `${total.toLocaleString('es-AR')} productos incorporados al Catálogo de Canje`
          : `${total.toLocaleString('es-AR')} productos filtrados (${totalInCanjeGlobal.toLocaleString('es-AR')} en Catálogo de Canje)`;
    }
  }
  syncUnifiedPaginationControls(pageInd, prevBtn, nextBtn, STATE.fidCatPage, totalPages, (nextPage) => {
    renderFidCatalogoSection(nextPage);
  });

  tbody.textContent = '';
  if (pageItems.length === 0) {
    renderTenByTenPaginationBar({ containerId: 'fid-cat-pagination-bar', totalItems: 0 });
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = 8;
    td.className = 'table-loading-cell';
    if (estadoCanje === 'incluidos') {
      td.innerHTML = `
        <div style="display:flex; flex-direction:column; align-items:center; gap:0.65rem; padding:0.75rem;">
          <strong>No hay artículos incorporados al Catálogo de Canje para este filtro.</strong>
          <span style="color:var(--text-secondary); font-size:0.86rem;">
            Podés incorporar productos tildando <strong>${erpClubFidelBadgeSvg(15)} Canje</strong> en <em>Artículos, Precios y Stock</em>, marcando <strong>${erpClubFidelBadgeSvg(15)} Agregar a Catálogo Canje</strong> dentro de la ficha del artículo, o buscando desde aquí en todo el padrón.
          </span>
          <button type="button" id="btn-empty-fid-show-all" class="btn-primary btn-sm" style="width:auto;">
            🔍 Ver Todo el Padrón de Artículos para Incorporar al Canje
          </button>
        </div>
      `;
      tr.appendChild(td);
      tbody.appendChild(tr);
      document.getElementById('btn-empty-fid-show-all')?.addEventListener('click', () => {
        if (estadoSel) estadoSel.value = 'todos';
        applyFidCatalogoFilters(1);
      });
    } else {
      td.textContent = 'No se encontraron productos para los filtros seleccionados.';
      tr.appendChild(td);
      tbody.appendChild(tr);
    }
    return;
  }

  const factor = Number(STATE.fidelizacionConfig.factorCanje) || 1.12;
  const factorStr = factor.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const frag = document.createDocumentFragment();

  pageItems.forEach((art) => {
    const tr = document.createElement('tr');

    // 1. Toggle En Catálogo de Canje
    const th = document.createElement('th');
    th.scope = 'row';
    const chkLabel = document.createElement('label');
    chkLabel.className = 'checkbox-pill';
    chkLabel.style.fontWeight = '700';
    chkLabel.style.color = Number(art.cfid) === 1 ? 'var(--gold-light)' : 'var(--text-secondary)';
    const chk = document.createElement('input');
    chk.type = 'checkbox';
    chk.checked = Number(art.cfid) === 1;
    const chkSpan = document.createElement('span');
    chkSpan.innerHTML = Number(art.cfid) === 1 ? `${erpClubFidelBadgeSvg(15)} En Catálogo` : 'Incorporar';
    chk.addEventListener('change', () => {
      toggleSingleArticleCanje(art.id, chk.checked, art.pfid, art.pfidManual);
    });
    chkLabel.appendChild(chk);
    chkLabel.appendChild(chkSpan);
    th.appendChild(chkLabel);
    tr.appendChild(th);

    // 2. Producto
    const tdProd = document.createElement('td');
    tdProd.dataset.label = 'Producto (Cód. / Nombre)';
    const headWrap = document.createElement('div');
    headWrap.className = 'art-row-head';
    const thumbBox = document.createElement('div');
    thumbBox.className = 'thumb-white-box';
    const imgEl = document.createElement('img');
    imgEl.src = resolveArticleImageUrl(art).url;
    imgEl.alt = art.n;
    imgEl.loading = 'lazy';
    imgEl.onerror = () => {
      imgEl.onerror = null;
      imgEl.src = 'assets/img/icon-192.png';
    };
    thumbBox.appendChild(imgEl);
    const meta = document.createElement('div');
    meta.className = 'art-head-meta';
    meta.innerHTML = `<div class="art-code-pill">#${art.c}</div><span class="art-title-text">${art.n}</span>`;
    headWrap.appendChild(thumbBox);
    headWrap.appendChild(meta);
    tdProd.appendChild(headWrap);
    tr.appendChild(tdProd);

    // 3. Rubro / Marca
    const tdRub = document.createElement('td');
    tdRub.dataset.label = 'Rubro y Marca';
    const rObj = STATE.rubrosMap.get(Number(art.r));
    const mObj = STATE.marcasMap.get(Number(art.mk));
    tdRub.innerHTML = `<div class="price-cell-stack"><strong>${rObj ? rObj.nombre : 'Sin rubro'}</strong><span class="price-neto-val">${mObj ? mObj.nombre : ''}</span></div>`;
    tr.appendChild(tdRub);

    // 4. Stock
    const tdStock = document.createElement('td');
    tdStock.dataset.label = 'Stock Actual';
    const sf = Number(art.sf) || 0;
    tdStock.innerHTML = sf > 0
      ? `<span class="stock-badge">Stock: ${sf}</span>`
      : `<span class="stock-badge stock-badge--zero">SIN STOCK (${sf})</span>`;
    tr.appendChild(tdStock);

    // 5. Precio Minorista Final
    const tdPrecio = document.createElement('td');
    tdPrecio.dataset.label = 'Precio Minorista ($)';
    tdPrecio.style.textAlign = 'right';
    tdPrecio.innerHTML = `<span class="price-final-val">$ ${formatArs(art.p1f)}</span>`;
    tr.appendChild(tdPrecio);

    // 6. Cálculo Base (Factor General o Regla activa de Rubro × Minorista)
    const tdBase = document.createElement('td');
    const resolvedArtRule = resolveEffectiveFidParamsForRubro(Number(art.r) || 0);
    const effArtFactor = resolvedArtRule.factor;
    const effArtFactorStr = effArtFactor.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    tdBase.dataset.label = `Puntos Automáticos (${effArtFactorStr}x)`;
    tdBase.style.textAlign = 'right';
    const p1fVal = Math.max(0, Number(art.p1f) || 0);
    const autoPts = Math.max(1, Math.round(p1fVal * effArtFactor));
    const rubroPromoTag = resolvedArtRule.factorRule
      ? `<span class="badge badge--green" style="font-size:0.68rem; padding:0.1rem 0.4rem;">🎯 Regla Rubro</span>`
      : '';
    tdBase.innerHTML = `<div class="price-cell-stack"><strong>${autoPts.toLocaleString('es-AR')} pts</strong><span class="price-neto-val">${effArtFactorStr} × $ ${formatArs(art.p1f)}</span>${rubroPromoTag}</div>`;
    tr.appendChild(tdBase);

    // 7. Valor en Puntos (Configurable por producto con barra de elección 0,80 a 1,40)
    const tdPtsInput = document.createElement('td');
    tdPtsInput.dataset.label = 'Puntos de Canje (Configurable)';
    const ptsColStack = document.createElement('div');
    ptsColStack.style.display = 'flex';
    ptsColStack.style.flexDirection = 'column';
    ptsColStack.style.alignItems = 'flex-end';
    ptsColStack.style.gap = '0.35rem';

    const currentPts = calcArticleCanjePoints(art);
    const initialRowFactor =
      Number(art.pfidManual) === 1
        ? (Number(art.ffid) >= 0.80 && Number(art.ffid) <= 1.40
            ? round2(Number(art.ffid))
            : p1fVal > 0
              ? Math.min(1.40, Math.max(0.80, round2(currentPts / p1fVal)))
              : Math.min(1.40, Math.max(0.80, factor)))
        : Math.min(1.40, Math.max(0.80, factor));

    const sliderRow = document.createElement('div');
    sliderRow.style.display = 'flex';
    sliderRow.style.alignItems = 'center';
    sliderRow.style.gap = '0.3rem';

    const minLbl = document.createElement('span');
    minLbl.style.fontSize = '0.7rem';
    minLbl.style.fontWeight = '700';
    minLbl.style.color = 'var(--text-secondary)';
    minLbl.textContent = '0,80';

    const rowRange = document.createElement('input');
    rowRange.type = 'range';
    rowRange.min = '0.80';
    rowRange.max = '1.40';
    rowRange.step = '0.01';
    rowRange.value = initialRowFactor.toFixed(2);
    rowRange.style.width = '105px';
    rowRange.style.cursor = 'pointer';
    rowRange.style.accentColor = 'var(--gold-main, #d4a017)';
    rowRange.setAttribute('aria-label', `Factor de canje (0,80 a 1,40) para ${art.n}`);

    const maxLbl = document.createElement('span');
    maxLbl.style.fontSize = '0.7rem';
    maxLbl.style.fontWeight = '700';
    maxLbl.style.color = 'var(--text-secondary)';
    maxLbl.textContent = '1,40';

    const rowFactorBadge = document.createElement('span');
    rowFactorBadge.className = 'badge badge--gold';
    rowFactorBadge.style.fontSize = '0.72rem';
    rowFactorBadge.style.padding = '0.1rem 0.4rem';
    rowFactorBadge.style.minWidth = '46px';
    rowFactorBadge.style.textAlign = 'center';
    rowFactorBadge.textContent = `${initialRowFactor.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}x`;

    sliderRow.appendChild(minLbl);
    sliderRow.appendChild(rowRange);
    sliderRow.appendChild(maxLbl);
    sliderRow.appendChild(rowFactorBadge);

    const ptsWrap = document.createElement('div');
    ptsWrap.style.display = 'flex';
    ptsWrap.style.alignItems = 'center';
    ptsWrap.style.gap = '0.35rem';

    const inpPts = document.createElement('input');
    inpPts.type = 'number';
    inpPts.min = '1';
    inpPts.step = '1';
    inpPts.className = 'form-input form-input--compact code-mono-input';
    inpPts.style.width = '95px';
    inpPts.style.textAlign = 'right';
    inpPts.style.fontWeight = '800';
    inpPts.style.color = 'var(--gold-light)';
    inpPts.value = String(currentPts);
    inpPts.setAttribute('aria-label', `Puntos de canje para ${art.n}`);

    rowRange.addEventListener('input', () => {
      const fVal = Math.min(1.40, Math.max(0.80, round2(Number(rowRange.value) || factor)));
      rowFactorBadge.textContent = `${fVal.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}x`;
      const calcPtsFromSlider = Math.max(1, Math.round(p1fVal * fVal));
      inpPts.value = String(calcPtsFromSlider);
    });

    rowRange.addEventListener('change', () => {
      const fVal = Math.min(1.40, Math.max(0.80, round2(Number(rowRange.value) || factor)));
      const calcPtsFromSlider = Math.max(1, Math.round(p1fVal * fVal));
      inpPts.value = String(calcPtsFromSlider);
      const isMan = Math.abs(fVal - factor) >= 0.005 ? 1 : 0;
      toggleSingleArticleCanje(art.id, Number(art.cfid) === 1 ? true : true, calcPtsFromSlider, isMan, fVal);
    });

    const saveCustomRowPts = () => {
      const customVal = Math.max(1, Math.round(Number(inpPts.value) || autoPts));
      inpPts.value = String(customVal);
      const derivedFactor = p1fVal > 0 ? Math.min(1.40, Math.max(0.80, round2(customVal / p1fVal))) : factor;
      rowRange.value = derivedFactor.toFixed(2);
      rowFactorBadge.textContent = `${derivedFactor.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}x`;
      const isMan = customVal !== autoPts ? 1 : 0;
      toggleSingleArticleCanje(art.id, true, customVal, isMan, derivedFactor);
    };

    inpPts.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter') {
        ev.preventDefault();
        saveCustomRowPts();
      }
    });

    const btnSavePts = document.createElement('button');
    btnSavePts.type = 'button';
    btnSavePts.className = 'btn-secondary btn-sm';
    btnSavePts.title = 'Guardar puntuación manual para este artículo';
    btnSavePts.textContent = '💾';
    btnSavePts.addEventListener('click', saveCustomRowPts);

    ptsWrap.appendChild(inpPts);
    ptsWrap.appendChild(btnSavePts);
    if (Number(art.pfidManual) === 1) {
      const resetAutoBtn = document.createElement('button');
      resetAutoBtn.type = 'button';
      resetAutoBtn.className = 'btn-secondary btn-sm';
      resetAutoBtn.title = `Restaurar al Factor General (${autoPts} pts)`;
      resetAutoBtn.textContent = '↺ Auto';
      resetAutoBtn.addEventListener('click', () => {
        toggleSingleArticleCanje(art.id, Number(art.cfid) === 1, autoPts, 0, null);
      });
      ptsWrap.appendChild(resetAutoBtn);
    }

    ptsColStack.appendChild(sliderRow);
    ptsColStack.appendChild(ptsWrap);
    tdPtsInput.appendChild(ptsColStack);
    tr.appendChild(tdPtsInput);

    // 8. Acción
    const tdAct = document.createElement('td');
    tdAct.dataset.label = 'Acciones';
    const btnEdit = document.createElement('button');
    btnEdit.type = 'button';
    btnEdit.className = 'btn-secondary btn-sm';
    btnEdit.textContent = '✏️ Ficha';
    btnEdit.addEventListener('click', () => openArticleModal(art));
    tdAct.appendChild(btnEdit);
    tr.appendChild(tdAct);

    frag.appendChild(tr);
  });

  tbody.appendChild(frag);
  renderTenByTenPaginationBar({
    containerId: 'fid-cat-pagination-bar',
    totalItems: total,
    pageSize: FID_PAGE_SIZE,
    currentPage: STATE.fidCatPage,
    itemLabel: 'productos',
    onPageChange: (nextPage) => applyFidCatalogoFilters(nextPage)
  });
}

async function toggleSingleArticleCanje(artId, includeInCanje, customPts = null, isManual = 0, customFactor = null) {
  const art = STATE.articulos.find((a) => Number(a.id) === Number(artId));
  if (!art) return;
  const factor = Number(STATE.fidelizacionConfig.factorCanje) || 1.12;
  art.cfid = includeInCanje ? 1 : 0;
  art.pfidManual = Number(isManual) === 1 ? 1 : 0;
  if (art.pfidManual === 1 && Number(customFactor) >= 0.80 && Number(customFactor) <= 1.40) {
    art.ffid = round2(Number(customFactor));
  } else if (art.pfidManual !== 1) {
    delete art.ffid;
  }
  art.pfid =
    art.pfidManual === 1 && Number(customPts) > 0
      ? Math.max(1, Math.round(Number(customPts)))
      : Math.max(1, Math.round((Number(art.p1f) || 0) * factor));

  saveLocalFidelizacionStore();
  updateFidelizacionKpisAndSummary();
  applyFidCatalogoFilters(STATE.fidCatPage || 1);
  renderFidQuickCanjeCards();
  if (!document.getElementById('sec-articulos')?.hidden) {
    applyCatalogFilters(STATE.currentPage || 1);
  }

  try {
    await fetch('api/catalog.php', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'update_article_canje',
        id: art.id,
        cfid: art.cfid,
        pfid: art.pfid,
        pfidManual: art.pfidManual,
        ffid: art.ffid || null,
        factorCanje: factor
      })
    });
  } catch {}
}

async function bulkSetCanjeForFiltered(cfidVal) {
  const targetVal = Number(cfidVal) === 1 ? 1 : 0;
  const factor = Number(STATE.fidelizacionConfig.factorCanje) || 1.12;
  const ids = [];

  STATE.fidCatFiltered.forEach((art) => {
    art.cfid = targetVal;
    if (Number(art.pfidManual) !== 1) {
      art.pfid = Math.max(1, Math.round((Number(art.p1f) || 0) * factor));
    }
    ids.push(art.id);
  });

  saveLocalFidelizacionStore();
  applyFidCatalogoFilters(STATE.fidCatPage);
  renderFidQuickCanjeCards();
  if (!document.getElementById('sec-articulos')?.hidden) {
    applyCatalogFilters(STATE.currentPage || 1);
  }

  try {
    await fetch('api/catalog.php', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'bulk_set_canje_fidelizacion',
        ids,
        cfid: targetVal,
        factorCanje: factor
      })
    });
  } catch {}
}

let fidGlobalFactorSaveTimer = null;

async function recalcAllCatalogCanjePoints(newFactor, { persistBackend = true } = {}) {
  const rawNum = Number(newFactor);
  const cleanFactor = isFinite(rawNum) && rawNum > 0 ? Math.min(1.40, Math.max(0.80, round2(rawNum))) : 1.12;
  STATE.fidelizacionConfig.factorCanje = cleanFactor;

  const cfgFactorInp = document.getElementById('cfg-fid-factor-canje');
  if (cfgFactorInp && document.activeElement !== cfgFactorInp) {
    cfgFactorInp.value = cleanFactor.toFixed(2);
  }
  const cfgFactorRange = document.getElementById('cfg-fid-factor-canje-range');
  if (cfgFactorRange && document.activeElement !== cfgFactorRange) {
    cfgFactorRange.value = cleanFactor.toFixed(2);
  }
  const catFactorInp = document.getElementById('fid-cat-factor-input');
  if (catFactorInp && document.activeElement !== catFactorInp) {
    catFactorInp.value = cleanFactor.toFixed(2);
  }
  const catFactorRange = document.getElementById('fid-cat-factor-range');
  if (catFactorRange && document.activeElement !== catFactorRange) {
    catFactorRange.value = cleanFactor.toFixed(2);
  }

  for (const a of STATE.articulos) {
    if (Number(a.pfidManual) !== 1) {
      a.pfid = Math.max(1, Math.round((Number(a.p1f) || 0) * cleanFactor));
    }
  }

  saveLocalFidelizacionStore();
  applyFidCatalogoFilters(STATE.fidCatPage);
  renderFidQuickCanjeCards();
  updateFidelizacionKpisAndSummary();

  if (!persistBackend) return;

  clearTimeout(fidGlobalFactorSaveTimer);
  fidGlobalFactorSaveTimer = setTimeout(async () => {
    try {
      await fetch('api/catalog.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'recalc_all_canje_points',
          factorCanje: cleanFactor,
          mostrarEnCatalogo: STATE.fidelizacionConfig.mostrarEnCatalogo || 'todos',
          overrideManual: false
        })
      });
      await fetch('api/clientes.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'save_fidelizacion_config',
          config: STATE.fidelizacionConfig
        })
      });
    } catch {}
  }, 180);
}

function renderFidClientesSection(page = null) {
  recalcAllClientsFidelizacionPoints();
  updateFidelizacionKpisAndSummary();

  const tbody = document.getElementById('fid-clients-tbody') || document.getElementById('fid-clientes-tbody');
  const statusEl = document.getElementById('fid-cli-status-msg');
  const pageInd = document.getElementById('fid-cli-page-ind');
  const prevBtn = document.getElementById('btn-fid-cli-prev');
  const nextBtn = document.getElementById('btn-fid-cli-next');
  if (!tbody) return;

  if (typeof page === 'number' && isFinite(page)) {
    STATE.fidClientesPage = Math.max(1, Math.floor(page));
  }

  const qEl = document.getElementById('fid-cli-list-q') || document.getElementById('fid-cli-q');
  const q = normalizeStr(qEl?.value || '');
  const filterSel = document.getElementById('fid-cli-list-filter') || document.getElementById('fid-cli-filter-saldo');
  const saldoFilter = filterSel?.value || 'con_puntos';
  const ordenSel = document.getElementById('fid-cli-list-orden');
  const ordenMode = ordenSel?.value || 'mayor_puntos';
  const tokens = q ? q.split(/\s+/).filter(Boolean) : [];

  const list = STATE.clientes
    .filter((c) => {
      if (c.bajaLogica === 1 || isSystemConfigClient(c)) return false;
      const pts = Number(c.puntosFidelizacion) || 0;
      const pv30 = Number(c.puntosPorVencer30d) || 0;
      const hist = (Number(c.puntosAcumuladosHist) || 0) + (Number(c.puntosCanjeadosHist) || 0);
      if (saldoFilter === 'con_puntos' && pts <= 0) return false;
      if (saldoFilter === 'por_vencer' && pv30 <= 0) return false;
      if (saldoFilter === 'con_historial' && hist <= 0) return false;

      if (tokens.length > 0) {
        const dni = extractDisplayDni(c);
        const hay = normalizeStr(`${c.codigo} ${c.nombre} ${c.nroDoc} ${dni} ${c.celular} ${c.email} ${c.localidad}`);
        if (!tokens.every((t) => hay.includes(t))) return false;
      }
      return true;
    })
    .sort((a, b) => {
      if (ordenMode === 'proximo_venc') {
        const va = a.proximoVencimiento ? a.proximoVencimiento.split('/').reverse().join('-') : '9999-12-31';
        const vb = b.proximoVencimiento ? b.proximoVencimiento.split('/').reverse().join('-') : '9999-12-31';
        return va.localeCompare(vb);
      }
      if (ordenMode === 'nombre') {
        return String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es');
      }
      if (ordenMode === 'fecha_alta_club') {
        const fa = String(a.fechaAltaClubIso || getClientRegistrationIso(a) || '');
        const fb = String(b.fechaAltaClubIso || getClientRegistrationIso(b) || '');
        if (fa !== fb) {
          if (!fa) return 1;
          if (!fb) return -1;
          return fb.localeCompare(fa);
        }
        return (Number(b.id) || 0) - (Number(a.id) || 0);
      }
      return (Number(b.puntosFidelizacion) || 0) - (Number(a.puntosFidelizacion) || 0);
    });

  const totalClientes = list.length;
  const totalPages = Math.max(1, Math.ceil(totalClientes / FID_PAGE_SIZE));
  STATE.fidClientesPage = Math.min(Math.max(1, Number(STATE.fidClientesPage) || 1), totalPages);
  const startIdx = (STATE.fidClientesPage - 1) * FID_PAGE_SIZE;
  const pageClients = list.slice(startIdx, startIdx + FID_PAGE_SIZE);

  if (statusEl) {
    if (totalClientes === 0) {
      statusEl.textContent = '0 clientes encontrados para este filtro';
    } else {
      statusEl.textContent = `${totalClientes.toLocaleString('es-AR')} clientes fidelizados`;
    }
  }
  syncUnifiedPaginationControls(pageInd, prevBtn, nextBtn, STATE.fidClientesPage, totalPages, (nextPage) => {
    renderFidClientesSection(nextPage);
  });

  tbody.textContent = '';
  if (totalClientes === 0) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = 6;
    td.className = 'table-loading-cell';
    td.textContent =
      saldoFilter === 'con_puntos'
        ? 'Aún no hay clientes con puntos vigentes para este filtro (cambiá a "Todos los clientes del padrón" o acreditá puntos por compra).'
        : 'No se encontraron clientes para los filtros aplicados.';
    tr.appendChild(td);
    tbody.appendChild(tr);
    renderTenByTenPaginationBar({ containerId: 'fid-cli-pagination-bar', totalItems: 0 });
    return;
  }

  const frag = document.createDocumentFragment();
  pageClients.forEach((c) => {
    const tr = document.createElement('tr');
    const dni = extractDisplayDni(c);
    const pts = Number(c.puntosFidelizacion) || 0;
    const canal = String(c.canalFidelizacion || STATE.fidelizacionConfig.canalDefault || 'whatsapp').toLowerCase();

    const th = document.createElement('th');
    th.scope = 'row';
    th.innerHTML = `<div class="price-cell-stack"><span class="art-code-pill">DNI ${dni}</span><span class="price-neto-val">Cód. #${c.codigo}</span></div>`;
    tr.appendChild(th);

    const tdNom = document.createElement('td');
    tdNom.dataset.label = 'Cliente (Nombre / Lista)';
    const altaClubTxt = c.fechaAltaClubFmt ? ` · 📅 Alta Club: ${c.fechaAltaClubFmt}` : '';
    tdNom.innerHTML = `<div class="price-cell-stack"><strong class="art-title-text">${c.nombre}</strong><span class="price-neto-val">${c.localidad || 'ALCIRA GIGENA'} · ${c.listaPrecio || 'MINORISTA'}${altaClubTxt}</span></div>`;
    tr.appendChild(tdNom);

    const tdCont = document.createElement('td');
    tdCont.dataset.label = 'WhatsApp / Email';
    const canalBadge =
      canal === 'whatsapp'
        ? '<span class="badge badge--green">WhatsApp ($0)</span>'
        : canal === 'email'
          ? '<span class="badge badge--gold">Email ($0)</span>'
          : '<span class="badge badge--green">WhatsApp + Email</span>';
    tdCont.innerHTML = `<div class="price-cell-stack"><strong>📲 ${c.celular || c.telefono || 'Sin WhatsApp'}</strong><span class="price-neto-val">✉️ ${c.email || 'Sin Email'} · ${canalBadge}</span></div>`;
    tr.appendChild(tdCont);

    const tdSaldo = document.createElement('td');
    tdSaldo.dataset.label = 'Puntos Vigentes';
    tdSaldo.style.textAlign = 'right';
    tdSaldo.innerHTML = `<span class="fid-pts-badge">${erpClubFidelBadgeSvg(16)} ${pts.toLocaleString('es-AR')} pts</span>`;
    tr.appendChild(tdSaldo);

    const tdVenc = document.createElement('td');
    tdVenc.dataset.label = 'Próximo Vencimiento (1 Año)';
    tdVenc.innerHTML = c.proximoVencimiento
      ? `<div class="price-cell-stack"><strong>${c.proximoVencimiento}</strong><span class="price-neto-val">${Number(c.proximoVencimientoPts || 0).toLocaleString('es-AR')} pts</span></div>`
      : '<span class="price-neto-val">1 año desde emisión</span>';
    tr.appendChild(tdVenc);

    const tdAct = document.createElement('td');
    tdAct.dataset.label = 'Acciones Rápidas';
    const actWrap = document.createElement('div');
    actWrap.className = 'fid-cli-actions-stack';
    actWrap.style.display = 'flex';
    actWrap.style.flexDirection = 'column';
    actWrap.style.gap = '0.38rem';
    actWrap.style.width = '165px';

    const applyUniformFidBtnStyle = (btn) => {
      btn.style.width = '165px';
      btn.style.minWidth = '165px';
      btn.style.maxWidth = '165px';
      btn.style.height = '34px';
      btn.style.minHeight = '34px';
      btn.style.padding = '0 0.65rem';
      btn.style.display = 'inline-flex';
      btn.style.alignItems = 'center';
      btn.style.justifyContent = 'center';
      btn.style.gap = '0.35rem';
      btn.style.boxSizing = 'border-box';
      btn.style.whiteSpace = 'nowrap';
    };

    const btnOp = document.createElement('button');
    btnOp.type = 'button';
    btnOp.className = 'btn-primary btn-sm';
    applyUniformFidBtnStyle(btnOp);
    btnOp.innerHTML = `${erpClubFidelBadgeSvg(16)} Operar / Canjear`;
    btnOp.addEventListener('click', () => {
      selectFidelizacionClient(c);
      document.querySelectorAll('.erp-section').forEach((sec) => {
        sec.hidden = sec.id !== 'sec-fid-operaciones';
      });
      updateTopbarModuleState('sec-fid-operaciones');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });

    const btnFicha = document.createElement('button');
    btnFicha.type = 'button';
    btnFicha.className = 'btn-secondary btn-sm';
    applyUniformFidBtnStyle(btnFicha);
    btnFicha.textContent = '✏️ Ficha';
    btnFicha.title = 'Ver y editar la ficha completa del cliente';
    btnFicha.addEventListener('click', () => {
      openClientModal(c.id);
    });

    const btnWa = document.createElement('button');
    btnWa.type = 'button';
    btnWa.className = 'btn-secondary btn-sm';
    applyUniformFidBtnStyle(btnWa);
    btnWa.textContent = '📲 Enviar Saldo';
    btnWa.addEventListener('click', () => {
      const msg = `¡Hola ${c.nombre}! ⭐ Te informamos tu estado de puntos en *Casa Nueva Supermercado* (DNI ${dni}):\n• *Puntos vigentes disponibles:* ${pts.toLocaleString('es-AR')} puntos.\n${c.proximoVencimiento ? `• *Próximo vencimiento:* ${c.proximoVencimiento}\n` : ''}¡Te esperamos para canjear tus puntos por productos de nuestro catálogo!`;
      triggerFidelizacionNotification(c, canal, msg, 'Tu Saldo de Puntos - Casa Nueva Supermercado', true);
    });

    actWrap.appendChild(btnFicha);
    actWrap.appendChild(btnOp);
    actWrap.appendChild(btnWa);
    tdAct.appendChild(actWrap);
    tr.appendChild(tdAct);

    frag.appendChild(tr);
  });

  tbody.appendChild(frag);
  renderTenByTenPaginationBar({
    containerId: 'fid-cli-pagination-bar',
    totalItems: totalClientes,
    pageSize: FID_PAGE_SIZE,
    currentPage: STATE.fidClientesPage,
    itemLabel: 'clientes',
    onPageChange: (nextPage) => {
      renderFidClientesSection(nextPage);
      tbody.closest('.table-wrapper')?.scrollTo({ top: 0, behavior: 'smooth' });
    }
  });
}

function populateFidRubroRuleSelects() {
  const rubros = Array.isArray(STATE.rubros)
    ? [...STATE.rubros].filter((r) => Number(r.bl) !== 1).sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es'))
    : [];

  const createSel = document.getElementById('fid-rr-rubro');
  if (createSel) {
    const prev = createSel.value;
    createSel.innerHTML =
      '<option value="">— Seleccionar Rubro —</option>' +
      '<option value="0">🌟 TODOS LOS RUBROS (Promoción General)</option>' +
      rubros.map((r) => `<option value="${r.id}">${escapeHtml(r.nombre || `RUBRO #${r.id}`)}</option>`).join('');
    if (prev !== '' && [...createSel.options].some((o) => o.value === prev)) {
      createSel.value = prev;
    }
  }

  const editSel = document.getElementById('fid-rr-edit-rubro');
  if (editSel) {
    const prev = editSel.value;
    editSel.innerHTML =
      '<option value="0">🌟 TODOS LOS RUBROS (Promoción General)</option>' +
      rubros.map((r) => `<option value="${r.id}">${escapeHtml(r.nombre || `RUBRO #${r.id}`)}</option>`).join('');
    if (prev !== '' && [...editSel.options].some((o) => o.value === prev)) {
      editSel.value = prev;
    }
  }

  const simSel = document.getElementById('cfg-sim-rubro');
  if (simSel) {
    const prev = simSel.value || '0';
    simSel.innerHTML =
      '<option value="0">Regla General (Sin rubro específico)</option>' +
      rubros.map((r) => `<option value="${r.id}">${escapeHtml(r.nombre || `RUBRO #${r.id}`)}</option>`).join('');
    if ([...simSel.options].some((o) => o.value === prev)) {
      simSel.value = prev;
    }
  }
}

function formatFidPctAr(val) {
  return (Number(val) || 0).toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function syncFidGeneralSlidersAndHints() {
  const pctInp = document.getElementById('cfg-fid-porcentaje');
  const pctRange = document.getElementById('cfg-fid-porcentaje-range');
  const pctBadge = document.getElementById('cfg-fid-pct-badge');
  const pctHint = document.getElementById('cfg-fid-pct-hint');

  const rawPct = Number(pctInp?.value ?? STATE.fidelizacionConfig.porcentajeSuma ?? 0.80);
  const cleanPct = Math.min(5.00, Math.max(0.25, round2(isFinite(rawPct) && rawPct > 0 ? rawPct : 0.80)));
  if (pctRange && document.activeElement !== pctRange) {
    pctRange.value = cleanPct.toFixed(2);
  }
  const pctFmt = formatFidPctAr(cleanPct);
  if (pctBadge) {
    pctBadge.textContent = `${pctFmt}% · Redondeo Entero`;
  }
  if (pctHint) {
    const ej10k = Math.round(10000 * (cleanPct / 100));
    const raw8450 = round2(8450 * (cleanPct / 100));
    const ej8450 = Math.round(8450 * (cleanPct / 100));
    pctHint.innerHTML = `Con <strong>${pctFmt}%</strong>: una compra de $10.000 suma <strong>${ej10k.toLocaleString('es-AR')} puntos</strong>; una de $8.450 (${raw8450.toLocaleString('es-AR')} exactos) redondea automáticamente a <strong>${ej8450.toLocaleString('es-AR')} puntos</strong>.`;
  }

  const facInp = document.getElementById('cfg-fid-factor-canje');
  const facRange = document.getElementById('cfg-fid-factor-canje-range');
  const facBadge = document.getElementById('cfg-fid-factor-badge');
  const facHint = document.getElementById('cfg-fid-factor-hint');

  const rawFac = Number(facInp?.value ?? STATE.fidelizacionConfig.factorCanje ?? 1.12);
  const cleanFac = Math.min(1.40, Math.max(0.80, round2(isFinite(rawFac) && rawFac > 0 ? rawFac : 1.12)));
  if (facRange && document.activeElement !== facRange) {
    facRange.value = cleanFac.toFixed(2);
  }
  const facFmt = formatFidPctAr(cleanFac);
  if (facBadge) {
    facBadge.textContent = `${facFmt} × Precio Minorista`;
  }
  if (facHint) {
    const pts1000 = Math.max(1, Math.round(1000 * cleanFac));
    facHint.innerHTML = `Un producto de <strong>$1.000</strong> minorista requiere <strong>${pts1000.toLocaleString('es-AR')} puntos</strong> para su canje.`;
  }

  const vigInp = document.getElementById('cfg-fid-vigencia');
  const vigBadge = document.getElementById('cfg-fid-vigencia-badge');
  if (vigInp && vigBadge) {
    const d = Math.max(1, Math.round(Number(vigInp.value) || 365));
    vigBadge.textContent = d === 365 ? '365 días = 1 Año Exacto' : `${d.toLocaleString('es-AR')} días desde emisión`;
  }
}

function formatFidRuleDaysLabel(diasSemana) {
  const dias = Array.isArray(diasSemana) ? diasSemana.map(Number) : [];
  if (dias.length === 0 || dias.length >= 7) {
    return '<span class="badge badge--green">Todos los días</span>';
  }
  const ordered = [1, 2, 3, 4, 5, 6, 0].filter((d) => dias.includes(d));
  return ordered
    .map((d) => `<span class="badge badge--gold" style="margin-inline-end:0.2rem;">${FID_DAY_NAMES_SHORT[d] || d}</span>`)
    .join('');
}

function renderFidRubroRulesTable() {
  const tbody = document.getElementById('fid-rr-tbody');
  const statusEl = document.getElementById('fid-rr-status-msg');
  if (!tbody) return;

  const rules = normalizeFidRubroRules(STATE.fidelizacionConfig.reglasRubros);
  STATE.fidelizacionConfig.reglasRubros = rules;

  if (statusEl) {
    const vigCount = rules.filter((r) => getFidRubroRuleStatus(r).code === 'vigente_hoy').length;
    statusEl.textContent = rules.length === 0
      ? '0 reglas especiales configuradas'
      : `${rules.length} regla${rules.length === 1 ? '' : 's'} especial${rules.length === 1 ? '' : 'es'} (${vigCount} vigente${vigCount === 1 ? '' : 's'} hoy)`;
  }

  tbody.textContent = '';
  if (rules.length === 0) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = 6;
    td.className = 'table-loading-cell';
    td.textContent = 'No hay reglas especiales por rubro configuradas. Se aplican las reglas generales en todos los rubros.';
    tr.appendChild(td);
    tbody.appendChild(tr);
    return;
  }

  const rubMap = new Map((Array.isArray(STATE.rubros) ? STATE.rubros : []).map((r) => [Number(r.id), r.nombre || '']));
  const frag = document.createDocumentFragment();

  rules.forEach((rule) => {
    const tr = document.createElement('tr');
    const rId = Number(rule.rubroId) || 0;
    const rubroTitle = rId === 0
      ? '🌟 TODOS LOS RUBROS (General)'
      : (rubMap.get(rId) || rule.rubroNombre || `RUBRO #${rId}`);
    const st = getFidRubroRuleStatus(rule);

    const vigStr = rule.fechaDesde && rule.fechaHasta
      ? `${formatIsoToDdMmYyyy(rule.fechaDesde)} al ${formatIsoToDdMmYyyy(rule.fechaHasta)}`
      : rule.fechaDesde
        ? `Desde ${formatIsoToDdMmYyyy(rule.fechaDesde)} (Sin fecha límite)`
        : rule.fechaHasta
          ? `Hasta ${formatIsoToDdMmYyyy(rule.fechaHasta)}`
          : 'Vigencia permanente';

    const pctCellHtml = rule.usaPorcentaje
      ? `<strong style="color:var(--gold-main, #b7860b); font-size:0.96rem;">${formatFidPctAr(rule.porcentajeCompra)}%</strong>`
      : '<span class="price-neto-val">Usa regla general</span>';

    const facCellHtml = rule.usaFactorCanje
      ? `<strong style="color:var(--success, #16a34a); font-size:0.96rem;">${formatFidPctAr(rule.factorCanje)} ×</strong>`
      : '<span class="price-neto-val">Usa regla general</span>';

    tr.innerHTML = `
      <td>
        <div class="price-cell-stack">
          <strong>${escapeHtml(rubroTitle)}</strong>
          ${rId > 0 ? `<span class="price-neto-val">Rubro ID #${rId}</span>` : '<span class="price-neto-val">Aplica a todo el padrón</span>'}
        </div>
      </td>
      <td class="num-col">${pctCellHtml}</td>
      <td class="num-col">${facCellHtml}</td>
      <td><div style="display:flex; flex-wrap:wrap; gap:0.2rem;">${formatFidRuleDaysLabel(rule.diasSemana)}</div></td>
      <td>
        <div class="price-cell-stack">
          <span class="${st.badgeCls}" style="width:fit-content;">${st.label}</span>
          <span class="price-neto-val">📅 ${escapeHtml(vigStr)}</span>
        </div>
      </td>
      <td class="actions-col">
        <div style="display:flex; gap:0.35rem; justify-content:flex-end; flex-wrap:wrap;">
          <button type="button" class="btn-secondary btn-sm btn-fid-rr-edit" data-rule-id="${escapeHtml(rule.id)}" style="width:auto;">
            ✏️ Modificar
          </button>
          <button type="button" class="btn-secondary btn-sm btn-fid-rr-toggle" data-rule-id="${escapeHtml(rule.id)}" style="width:auto;">
            ${rule.activa !== false ? '⏸️ Pausar' : '▶️ Activar'}
          </button>
          <button type="button" class="btn-secondary btn-sm btn-fid-rr-delete" data-rule-id="${escapeHtml(rule.id)}" style="width:auto; color:var(--danger, #dc2626);">
            🗑️ Eliminar
          </button>
        </div>
      </td>
    `;
    frag.appendChild(tr);
  });

  tbody.appendChild(frag);
}

async function persistFidConfigToBackend() {
  saveLocalFidelizacionStore();
  updateFidelizacionKpisAndSummary();
  applyFidCatalogoFilters(STATE.fidCatPage || 1);
  renderFidQuickCanjeCards();
  updateFidConfigSimulators();
  try {
    await fetch('api/clientes.php', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'save_fidelizacion_config',
        config: STATE.fidelizacionConfig
      })
    });
  } catch {}
}

function renderFidConfigSection() {
  if (!Array.isArray(STATE.rubros) || STATE.rubros.length === 0) {
    loadCatalogDatabase().then(() => {
      populateFidRubroRuleSelects();
      renderFidRubroRulesTable();
      updateFidConfigSimulators();
    });
  }
  populateFidRubroRuleSelects();

  const cfg = STATE.fidelizacionConfig;
  const setVal = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.value = String(val ?? '');
  };

  const cleanPct = Math.min(5.00, Math.max(0.25, round2(Number(cfg.porcentajeSuma ?? cfg.porcentajeCompra) || 0.80)));
  const cleanFac = Math.min(1.40, Math.max(0.80, round2(Number(cfg.factorCanje) || 1.12)));
  const cleanDias = Math.max(1, Math.round(Number(cfg.diasVencimiento ?? cfg.diasVigencia) || 365));

  setVal('cfg-fid-porcentaje', cleanPct.toFixed(2));
  setVal('cfg-fid-porcentaje-range', cleanPct.toFixed(2));
  setVal('cfg-fid-vigencia', cleanDias);
  setVal('cfg-fid-factor-canje', cleanFac.toFixed(2));
  setVal('cfg-fid-factor-canje-range', cleanFac.toFixed(2));
  setVal('cfg-fid-email-remitente', cfg.emailRemitente || 'fidelizacion@cn.com.ar');
  setVal('cfg-fid-webhook-wa', cfg.whatsappWebhookUrl || '');
  setVal('cfg-fid-twilio-sid', cfg.twilioAccountSid || '');
  setVal('cfg-fid-twilio-token', cfg.twilioAuthToken || '');
  setVal('cfg-fid-twilio-from', cfg.twilioFromNumber || '');
  setVal('cfg-fid-tpl-suma', cfg.plantillaSuma || '');
  setVal('cfg-fid-tpl-canje', cfg.plantillaCanje || '');

  const rrDesdeInp = document.getElementById('fid-rr-desde');
  if (rrDesdeInp && !rrDesdeInp.value) {
    rrDesdeInp.value = getLocalIsoAndDow().iso;
  }

  const canalDef = String(cfg.canalDefault || 'whatsapp').toLowerCase();
  document.querySelectorAll('input[name="cfg_fid_canal_def"]').forEach((rad) => {
    rad.checked = rad.value === canalDef;
  });

  const chkAutoWa = document.getElementById('cfg-fid-auto-wa');
  if (chkAutoWa) chkAutoWa.checked = cfg.autoOpenWhatsapp !== false;

  syncFidGeneralSlidersAndHints();
  renderFidRubroRulesTable();
  updateFidConfigSimulators();
}

function updateFidConfigSimulators() {
  syncFidGeneralSlidersAndHints();
  const basePct = Math.min(5.00, Math.max(0.25, Number(document.getElementById('cfg-fid-porcentaje')?.value || STATE.fidelizacionConfig.porcentajeSuma || 0.80)));
  const baseFactor = Math.min(1.40, Math.max(0.80, Number(document.getElementById('cfg-fid-factor-canje')?.value || STATE.fidelizacionConfig.factorCanje || 1.12)));
  const simRubroId = Number(document.getElementById('cfg-sim-rubro')?.value || 0);
  const simCompra = Number(document.getElementById('cfg-sim-compra')?.value || 25000);
  const simPrecio = Number(document.getElementById('cfg-sim-prod')?.value || 5000);

  const resolved = resolveEffectiveFidParamsForRubro(simRubroId, '', { basePct, baseFactor });
  const ptsCompra = Math.max(0, Math.round(simCompra * (resolved.pct / 100)));
  const ptsCanje = Math.max(1, Math.round(simPrecio * resolved.factor));

  const resRubroEl = document.getElementById('cfg-sim-rubro-res');
  if (resRubroEl) {
    if (resolved.pctRule || resolved.factorRule) {
      resRubroEl.style.color = 'var(--success, #16a34a)';
      resRubroEl.style.fontWeight = '700';
      resRubroEl.textContent = `🎯 Regla especial vigente hoy (${formatFidPctAr(resolved.pct)}% · ${formatFidPctAr(resolved.factor)}×)`;
    } else {
      resRubroEl.style.color = '';
      resRubroEl.style.fontWeight = '';
      resRubroEl.textContent = `Aplicando regla general (${formatFidPctAr(resolved.pct)}% · ${formatFidPctAr(resolved.factor)}×)`;
    }
  }

  const resCompraEl = document.getElementById('cfg-sim-compra-res');
  if (resCompraEl) resCompraEl.textContent = `+${ptsCompra.toLocaleString('es-AR')} pts (${formatFidPctAr(resolved.pct)}%)`;

  const resPrecioEl = document.getElementById('cfg-sim-prod-res');
  if (resPrecioEl) resPrecioEl.innerHTML = `${erpClubFidelBadgeSvg(16)} ${ptsCanje.toLocaleString('es-AR')} pts (${formatFidPctAr(resolved.factor)}×)`;
}

function resolveCanjeTicketNumber(mov) {
  if (!mov) return 'CJ-00001';
  const raw = String(mov.nroTicketCanje || '').trim().toUpperCase();
  if (raw) return raw;
  const mComp = String(mov.comprobante || '').match(/CJ-\d+/i);
  if (mComp) return mComp[0].toUpperCase();
  return `CJ-${String(Number(mov.id) || 1).padStart(5, '0')}`;
}

function renderFidCanjesSection(page = null) {
  const tbody = document.getElementById('fid-canjes-tbody');
  const statusEl = document.getElementById('fid-canjes-status-msg');
  if (!tbody) return;

  if (typeof page === 'number' && isFinite(page)) {
    STATE.fidCanjesPage = Math.max(1, Math.floor(page));
  }

  const qRaw = String(document.getElementById('fid-canjes-q')?.value || '').trim();
  const q = normalizeStr(qRaw);
  const tokens = q ? q.split(/\s+/).filter(Boolean) : [];
  const estadoFilter = String(document.getElementById('fid-canjes-filter-estado')?.value || 'todos').toUpperCase();

  const allCanjes = (Array.isArray(STATE.movimientosFidelizacion) ? STATE.movimientosFidelizacion : [])
    .filter((m) => String(m.tipo || '').toUpperCase() === 'CANJE')
    .slice()
    .sort((a, b) => (Number(b.id) || 0) - (Number(a.id) || 0));

  let pendientesCount = 0;
  let entregadosCount = 0;
  let totalPtsCanjeados = 0;

  allCanjes.forEach((m) => {
    const est = String(m.estadoEntrega || (m.stockDescontado ? 'ENTREGADO' : 'PENDIENTE')).toUpperCase();
    if (est === 'ENTREGADO') entregadosCount++;
    else pendientesCount++;
    totalPtsCanjeados += Math.abs(Math.round(Number(m.puntos) || 0));
  });

  const setKpi = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val;
  };
  setKpi('kpi-fid-canjes-total', allCanjes.length.toLocaleString('es-AR'));
  setKpi('kpi-fid-canjes-pendientes', pendientesCount.toLocaleString('es-AR'));
  setKpi('kpi-fid-canjes-entregados', entregadosCount.toLocaleString('es-AR'));
  setKpi('kpi-fid-canjes-puntos', `${totalPtsCanjeados.toLocaleString('es-AR')} pts`);

  const filtered = allCanjes.filter((m) => {
    const est = String(m.estadoEntrega || (m.stockDescontado ? 'ENTREGADO' : 'PENDIENTE')).toUpperCase();
    if (estadoFilter === 'PENDIENTE' && est === 'ENTREGADO') return false;
    if (estadoFilter === 'ENTREGADO' && est !== 'ENTREGADO') return false;

    if (tokens.length > 0) {
      const cid = Number(m.clientId ?? m.cId ?? 0);
      const cli = STATE.clientes.find((c) => Number(c.id) === cid);
      const tk = resolveCanjeTicketNumber(m);
      const artCod = m.artCodigo || m.articuloCodigo || '';
      const artNom = m.artNombre || m.productoNombre || '';
      const hay = normalizeStr(
        `${tk} ${m.id || ''} ${m.clienteNombre || cli?.nombre || ''} ${m.dni || cli?.nroDoc || ''} ${m.clienteCodigo || cli?.codigo || ''} ${artCod} ${artNom} ${m.comprobante || ''} ${m.obs || m.observacion || ''}`
      );
      if (!tokens.every((t) => hay.includes(t))) return false;
    }
    return true;
  });

  const totalCanjes = filtered.length;
  const totalPages = Math.max(1, Math.ceil(totalCanjes / FID_PAGE_SIZE));
  STATE.fidCanjesPage = Math.min(Math.max(1, Number(STATE.fidCanjesPage) || 1), totalPages);
  const startIdx = (STATE.fidCanjesPage - 1) * FID_PAGE_SIZE;
  const pageCanjes = filtered.slice(startIdx, startIdx + FID_PAGE_SIZE);

  if (statusEl) {
    statusEl.textContent =
      totalCanjes > 0
        ? `${totalCanjes.toLocaleString('es-AR')} canjes efectuados (${pendientesCount} pendiente(s) de entrega · ${entregadosCount} entregado(s))`
        : `0 canjes encontrados (${pendientesCount} pendiente(s) de entrega · ${entregadosCount} entregado(s))`;
  }

  tbody.textContent = '';
  if (totalCanjes === 0) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = 8;
    td.className = 'table-loading-cell';
    td.textContent =
      allCanjes.length === 0
        ? 'Aún no se registran canjes efectuados en Club Fidel.'
        : 'No se encontraron canjes efectuados para los filtros seleccionados.';
    tr.appendChild(td);
    tbody.appendChild(tr);
    renderTenByTenPaginationBar({ containerId: 'fid-canjes-pagination-bar', totalItems: 0 });
    return;
  }

  const frag = document.createDocumentFragment();
  pageCanjes.forEach((m) => {
    const tr = document.createElement('tr');
    const cid = Number(m.clientId ?? m.cId ?? 0);
    const cli = STATE.clientes.find((c) => Number(c.id) === cid);
    const tkCode = resolveCanjeTicketNumber(m);
    const cliNom = m.clienteNombre || cli?.nombre || 'SOCIO CLUB FIDEL';
    const cliDni = m.dni || (cli ? extractDisplayDni(cli) : 'S/DNI');
    const cliCod = m.clienteCodigo || cli?.codigo || cid || '—';

    const artId = Number(m.artId ?? m.articuloId ?? 0);
    const rawCod = String(m.artCodigo || m.articuloCodigo || '').trim();
    const artObj =
      STATE.articulos.find((a) => artId > 0 && Number(a.id) === artId) ||
      (rawCod ? STATE.articulos.find((a) => String(a.c || '').toUpperCase() === rawCod.toUpperCase()) : null);

    const artCod = rawCod || artObj?.c || (artId > 0 ? String(artId) : 'S/C');
    const artNom = m.artNombre || m.productoNombre || artObj?.n || m.comprobante || 'PREMIO DE CANJE';
    const qty = Math.max(1, Number(m.cantidad) || 1);
    const ptsAbs = Math.abs(Math.round(Number(m.puntos) || 0));
    const isEntregado = String(m.estadoEntrega || (m.stockDescontado ? 'ENTREGADO' : 'PENDIENTE')).toUpperCase() === 'ENTREGADO';

    // 1. Ticket / Fecha
    const th = document.createElement('th');
    th.scope = 'row';
    const origenLbl = String(m.origenCanje || (String(m.comprobante || '').includes('WEB') ? 'WEB' : 'ERP')).toUpperCase();
    th.innerHTML = `
      <div class="price-cell-stack">
        <span class="art-code-pill" style="font-size:0.84rem;">🎫 ${escapeHtml(tkCode)}</span>
        <span class="price-neto-val">${escapeHtml(m.fechaEmision || '')} ${escapeHtml(m.hora || '')} · ${escapeHtml(origenLbl)}</span>
      </div>
    `;
    tr.appendChild(th);

    // 2. Cliente / DNI
    const tdCli = document.createElement('td');
    tdCli.dataset.label = 'Cliente / DNI';
    tdCli.innerHTML = `
      <div class="price-cell-stack">
        <strong class="art-title-text">${escapeHtml(cliNom)}</strong>
        <span class="price-neto-val">DNI: ${escapeHtml(cliDni)} · Socio #${escapeHtml(String(cliCod))}</span>
      </div>
    `;
    tr.appendChild(tdCli);

    // 3. Producto Recibido en Canje
    const tdProd = document.createElement('td');
    tdProd.dataset.label = 'Producto Recibido en Canje';
    const headWrap = document.createElement('div');
    headWrap.className = 'art-row-head';
    if (artObj) {
      const thumbBox = document.createElement('div');
      thumbBox.className = 'thumb-white-box';
      const imgEl = document.createElement('img');
      imgEl.src = resolveArticleImageUrl(artObj).url;
      imgEl.alt = artNom;
      imgEl.loading = 'lazy';
      imgEl.onerror = () => {
        imgEl.onerror = null;
        imgEl.src = 'assets/img/icon-192.png';
      };
      thumbBox.appendChild(imgEl);
      headWrap.appendChild(thumbBox);
    }
    const meta = document.createElement('div');
    meta.className = 'art-head-meta';
    meta.innerHTML = `<div class="art-code-pill">#${escapeHtml(String(artCod))}</div><span class="art-title-text">${escapeHtml(artNom)}</span>`;
    headWrap.appendChild(meta);
    tdProd.appendChild(headWrap);
    tr.appendChild(tdProd);

    // 4. Cantidad
    const tdCant = document.createElement('td');
    tdCant.dataset.label = 'Cant.';
    tdCant.style.textAlign = 'center';
    tdCant.innerHTML = `<strong style="font-size:0.96rem;">${qty} un.</strong>`;
    tr.appendChild(tdCant);

    // 5. Puntos
    const tdPts = document.createElement('td');
    tdPts.dataset.label = 'Puntos';
    tdPts.style.textAlign = 'right';
    tdPts.innerHTML = `<span class="fid-pts-badge">${erpClubFidelBadgeSvg(15)} -${ptsAbs.toLocaleString('es-AR')} pts</span>`;
    tr.appendChild(tdPts);

    // 6. Stock Actual
    const tdStock = document.createElement('td');
    tdStock.dataset.label = 'Stock Actual';
    tdStock.style.textAlign = 'center';
    if (artObj) {
      const sf = Number(artObj.sf) || 0;
      tdStock.innerHTML =
        sf > 0
          ? `<span class="stock-badge">Stock: ${sf}</span>`
          : `<span class="stock-badge stock-badge--zero">SIN STOCK (${sf})</span>`;
    } else {
      tdStock.innerHTML = `<span class="price-neto-val">—</span>`;
    }
    tr.appendChild(tdStock);

    // 7. Estado de Entrega
    const tdEst = document.createElement('td');
    tdEst.dataset.label = 'Estado de Entrega';
    if (isEntregado) {
      tdEst.innerHTML = `
        <div class="price-cell-stack">
          <span class="badge badge--green">✅ ENTREGADO (Stock descontado)</span>
          <span class="price-neto-val">${escapeHtml(m.fechaEntrega || m.fechaEmision || '')}${m.entregadoPor ? ' · ' + escapeHtml(m.entregadoPor) : ''}</span>
        </div>
      `;
    } else {
      tdEst.innerHTML = `
        <div class="price-cell-stack">
          <span class="badge badge--gold">⏳ PENDIENTE DE ENTREGA</span>
          <span class="price-neto-val">Retiro en Supermercado · Falta descontar Stock</span>
        </div>
      `;
    }
    tr.appendChild(tdEst);

    // 8. Acciones
    const tdAct = document.createElement('td');
    tdAct.dataset.label = 'Acciones';
    const actWrap = document.createElement('div');
    actWrap.style.display = 'flex';
    actWrap.style.gap = '0.45rem';
    actWrap.style.flexWrap = 'wrap';
    actWrap.style.alignItems = 'center';

    if (!isEntregado) {
      const btnDeliver = document.createElement('button');
      btnDeliver.type = 'button';
      btnDeliver.className = 'btn-primary btn-sm';
      btnDeliver.style.width = 'auto';
      btnDeliver.style.whiteSpace = 'nowrap';
      btnDeliver.textContent = '📦 Hacer Entrega (Descontar Stock)';
      btnDeliver.addEventListener('click', () => {
        deliverFidelizacionCanjeItem(m, btnDeliver);
      });
      actWrap.appendChild(btnDeliver);
    }

    const btnTicket = document.createElement('button');
    btnTicket.type = 'button';
    btnTicket.className = 'btn-secondary btn-sm';
    btnTicket.style.width = 'auto';
    btnTicket.style.whiteSpace = 'nowrap';
    btnTicket.textContent = '🎫 Ticket';
    btnTicket.title = 'Ver o imprimir Ticket de Retiro de Canje';
    btnTicket.addEventListener('click', () => {
      printFidelizacionCanjeTicket(m);
    });
    actWrap.appendChild(btnTicket);

    tdAct.appendChild(actWrap);
    tr.appendChild(tdAct);

    frag.appendChild(tr);
  });

  tbody.appendChild(frag);
  renderTenByTenPaginationBar({
    containerId: 'fid-canjes-pagination-bar',
    totalItems: totalCanjes,
    pageSize: FID_PAGE_SIZE,
    currentPage: STATE.fidCanjesPage,
    itemLabel: 'canjes',
    onPageChange: (nextPage) => renderFidCanjesSection(nextPage)
  });
}

async function deliverFidelizacionCanjeItem(mov, triggerBtn = null) {
  if (!mov) return;
  const tkCode = resolveCanjeTicketNumber(mov);
  const qty = Math.max(1, Number(mov.cantidad) || 1);
  const artNom = mov.artNombre || mov.productoNombre || mov.comprobante || 'PREMIO DE CANJE';

  if (triggerBtn) {
    triggerBtn.disabled = true;
    triggerBtn.textContent = '⏳ Entregando...';
  }

  let serverData = null;
  try {
    const res = await fetch('api/clientes.php', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'deliver_fidelizacion_canje',
        movId: mov.id,
        nroTicketCanje: tkCode
      })
    });
    const json = await res.json().catch(() => null);
    if (res.ok && json && json.ok) {
      serverData = json;
    }
  } catch {}

  const now = new Date();
  const fechaEntregaStr =
    serverData?.fechaEntrega ||
    `${todayFormatted()} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

  mov.nroTicketCanje = tkCode;
  mov.estadoEntrega = 'ENTREGADO';
  mov.stockDescontado = true;
  mov.fechaEntrega = fechaEntregaStr;
  mov.entregadoPor = serverData?.entregadoPor || STATE.currentUser?.username || 'caja';

  // Actualizar stock local del artículo en STATE.articulos
  const artId = Number(mov.artId ?? mov.articuloId ?? 0);
  const rawCod = String(mov.artCodigo || mov.articuloCodigo || '').trim().toUpperCase();
  const artObj =
    STATE.articulos.find((a) => artId > 0 && Number(a.id) === artId) ||
    (rawCod ? STATE.articulos.find((a) => String(a.c || '').toUpperCase() === rawCod) : null);

  let newStockVal = null;
  if (Array.isArray(serverData?.updatedArticles) && serverData.updatedArticles.length > 0) {
    serverData.updatedArticles.forEach((ua) => {
      const found = STATE.articulos.find((a) => Number(a.id) === Number(ua.id));
      if (found) {
        found.sf = round2(Number(ua.sf) || 0);
        newStockVal = found.sf;
      }
    });
  } else if (artObj) {
    artObj.sf = round2((Number(artObj.sf) || 0) - qty);
    newStockVal = artObj.sf;
  }

  saveLocalFidelizacionStore();
  renderFidCanjesSection();
  updateFidelizacionKpisAndSummary();
  updateKpis();

  const fbEl = document.getElementById('fid-canjes-feedback');
  if (fbEl) {
    fbEl.innerHTML = `✅ <strong>¡Entrega confirmada!</strong> Ticket <strong>${escapeHtml(tkCode)}</strong> (${escapeHtml(mov.clienteNombre || 'Socio')}) · Se entregó <strong>${qty}x ${escapeHtml(artNom)}</strong> y se descontó de Stock${newStockVal !== null ? ` (Stock actual: <strong>${newStockVal}</strong>)` : ''}.`;
    fbEl.hidden = false;
  }
}

function printFidelizacionCanjeTicket(mov) {
  if (!mov) return;
  const cid = Number(mov.clientId ?? mCidFromMov(mov));
  function mCidFromMov(x) {
    return Number(x?.cId || 0);
  }
  const cli = STATE.clientes.find((c) => Number(c.id) === cid);
  const tkCode = resolveCanjeTicketNumber(mov);
  const cliNom = mov.clienteNombre || cli?.nombre || 'SOCIO CLUB FIDEL';
  const cliDni = mov.dni || (cli ? extractDisplayDni(cli) : 'S/DNI');
  const cliCod = mov.clienteCodigo || cli?.codigo || cid || '1';
  const qty = Math.max(1, Number(mov.cantidad) || 1);
  const artCod = mov.artCodigo || mov.articuloCodigo || 'S/C';
  const artNom = mov.artNombre || mov.productoNombre || mov.comprobante || 'PREMIO DE CANJE';
  const ptsAbs = Math.abs(Math.round(Number(mov.puntos) || 0));
  const isEntregado = String(mov.estadoEntrega || (mov.stockDescontado ? 'ENTREGADO' : 'PENDIENTE')).toUpperCase() === 'ENTREGADO';
  const qrPayload = `CANJE:${tkCode}|DNI:${cliDni}|COD:${artCod}|QTY:${qty}`;
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=170x170&ecc=M&margin=2&data=${encodeURIComponent(qrPayload)}`;

  const win = window.open('', '_blank', 'width=440,height=720');
  if (!win) return;
  win.document.open();
  win.document.write(`<!DOCTYPE html>
<html lang="es-AR">
<head>
  <meta charset="UTF-8">
  <title>Ticket de Canje ${escapeHtml(tkCode)}</title>
  <style>
    @page { size: 80mm auto; margin: 4mm; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      margin: 0;
      padding: 12px;
      background: #ffffff;
      color: #111827;
      max-width: 340px;
      margin-inline: auto;
    }
    .tk-box {
      border: 2px dashed #111827;
      border-radius: 12px;
      padding: 14px;
    }
    .tk-head {
      text-align: center;
      border-bottom: 1px dashed #9ca3af;
      padding-bottom: 10px;
      margin-bottom: 10px;
    }
    .tk-brand { font-size: 15px; font-weight: 900; letter-spacing: 0.03em; }
    .tk-sub { font-size: 11px; font-weight: 700; color: #4b5563; margin-top: 2px; }
    .tk-title {
      display: inline-block;
      margin-top: 6px;
      background: #092837;
      color: #ffffff;
      font-weight: 900;
      font-size: 12px;
      padding: 4px 10px;
      border-radius: 999px;
    }
    .tk-code-big {
      text-align: center;
      font-family: monospace;
      font-size: 24px;
      font-weight: 900;
      margin: 8px 0 4px;
      letter-spacing: 0.06em;
    }
    .tk-status {
      text-align: center;
      font-size: 11px;
      font-weight: 800;
      padding: 4px 8px;
      border-radius: 6px;
      margin-bottom: 10px;
      background: ${isEntregado ? '#dcfce7' : '#fef3c7'};
      color: ${isEntregado ? '#166534' : '#92400e'};
    }
    .tk-row {
      display: flex;
      justify-content: space-between;
      font-size: 12px;
      margin: 4px 0;
      gap: 8px;
    }
    .tk-item-box {
      border-top: 1px dashed #9ca3af;
      border-bottom: 1px dashed #9ca3af;
      padding: 8px 0;
      margin: 8px 0;
    }
    .tk-qr {
      text-align: center;
      margin: 10px 0 6px;
    }
    .tk-sign {
      margin-top: 26px;
      border-top: 1px solid #374151;
      padding-top: 4px;
      text-align: center;
      font-size: 11px;
      color: #4b5563;
    }
    @media print {
      .no-print { display: none !important; }
      body { padding: 0; }
    }
  </style>
</head>
<body>
  <div class="no-print" style="text-align:center; margin-bottom:10px;">
    <button onclick="window.print()" style="padding:8px 16px; font-weight:800; cursor:pointer; border-radius:8px; border:1px solid #092837; background:#092837; color:#fff;">🖨️ Imprimir Ticket</button>
  </div>
  <div class="tk-box">
    <div class="tk-head">
      <div class="tk-brand">${escapeHtml(ACTIVE_BRAND.fullName || 'CASA NUEVA SUPERMERCADO')}</div>
      <div class="tk-sub">${escapeHtml(ACTIVE_BRAND.clubName || 'CLUB FIDEL')} · PROGRAMA DE BENEFICIOS</div>
      <div class="tk-title">TICKET DE RETIRO DE CANJE</div>
    </div>
    <div class="tk-code-big">${escapeHtml(tkCode)}</div>
    <div class="tk-status">
      ${isEntregado ? `✅ ENTREGADO EN SUPERMERCADO (${escapeHtml(mov.fechaEntrega || '')})` : '⏳ PENDIENTE DE RETIRO EN SUPERMERCADO'}
    </div>
    <div class="tk-row"><span>Fecha / Hora:</span><strong>${escapeHtml(mov.fechaEmision || '')} ${escapeHtml(mov.hora || '')}</strong></div>
    <div class="tk-row"><span>Cliente:</span><strong>${escapeHtml(cliNom)}</strong></div>
    <div class="tk-row"><span>DNI / Socio:</span><strong>${escapeHtml(cliDni)} (#${escapeHtml(String(cliCod))})</strong></div>
    <div class="tk-item-box">
      <div style="font-size:11px; font-weight:800; color:#4b5563; margin-bottom:4px;">PRODUCTO CANJEADO:</div>
      <div style="font-size:13px; font-weight:900;">${qty}x ${escapeHtml(artNom)}</div>
      <div style="font-size:11px; color:#4b5563;">Código: #${escapeHtml(String(artCod))} · Puntos canjeados: -${ptsAbs.toLocaleString('es-AR')} pts</div>
    </div>
    <div class="tk-qr">
      <img src="${qrUrl}" width="130" height="130" alt="QR Ticket ${escapeHtml(tkCode)}" />
      <div style="font-size:10.5px; color:#4b5563; margin-top:4px;">Presentar este Ticket en el Supermercado para retirar el producto.</div>
    </div>
    <div class="tk-sign">Firma / Conformidad de Retiro del Cliente</div>
  </div>
</body>
</html>`);
  win.document.close();
}

