  function formatArs4(val) {
    const n = Number(val) || 0;
    return n.toLocaleString('es-AR', { minimumFractionDigits: 4, maximumFractionDigits: 4 });
  }

  function formatQty3(val) {
    const n = Number(val) || 0;
    return n.toLocaleString('es-AR', { minimumFractionDigits: 3, maximumFractionDigits: 3 });
  }

  function setFactMultiplier(multVal) {
    const m = Number(multVal);
    const valid = isFinite(m) && m > 0 ? Math.round(m * 1000) / 1000 : 1;
    STATE.factActiveMultiplier = valid;

    const inlineBadge = document.getElementById('fact-inline-mult-badge');
    const bandPill = document.getElementById('fact-active-mult-pill');
    const clearChip = document.getElementById('btn-clear-mult-chip');
    const qtyInput = document.getElementById('fact-first-qty-input');

    if (inlineBadge) {
      if (valid !== 1) {
        inlineBadge.textContent = `${valid}x ✕`;
        inlineBadge.hidden = false;
      } else {
        inlineBadge.hidden = true;
      }
    }
    if (bandPill) {
      if (valid !== 1) {
        bandPill.textContent = `Multiplicador activo: ${valid}x ✕`;
        bandPill.hidden = false;
      } else {
        bandPill.hidden = true;
      }
    }
    if (clearChip) {
      clearChip.hidden = valid === 1;
    }
    if (qtyInput) {
      qtyInput.value = Number.isInteger(valid) ? String(valid) : valid.toFixed(3);
    }

    document.querySelectorAll('.btn-mult-chip[data-mult]').forEach((btn) => {
      btn.classList.toggle('is-active', Number(btn.getAttribute('data-mult')) === valid);
    });
  }

  /**
   * Interpreta expresiones como:
   * - "2x", "3x", "4x", "3,x", "2,5x", "2*", "1x", "0x" (solo multiplicador)
   * - "2x07435", "3,x7435", "4x7790950133325", "2x PAN" (multiplicador + código/búsqueda)
   * - "07435", "7435", "7790950133325" (código directo)
   */
  function parseFactCodeExpression(rawStr) {
    const trimmed = String(rawStr || '').trim();
    if (!trimmed) {
      return { onlyMultiplier: false, multiplier: null, term: '' };
    }

    // Caso 1: Solo multiplicador al escribir "2x", "3,x", "4x", "2.5x", "3*", "1x", "0x"
    const onlyMultMatch = trimmed.match(/^(\d+(?:[.,]\d+)?)\s*,?\s*[xX*]$/);
    if (onlyMultMatch) {
      const rawM = parseFloat(onlyMultMatch[1].replace(',', '.'));
      if (isFinite(rawM) && rawM >= 0 && rawM <= 9999) {
        return { onlyMultiplier: true, multiplier: rawM === 0 ? 1 : rawM, term: '' };
      }
    }

    // Caso 2: Multiplicador seguido de código de producto, código de barras o texto ("2x7435", "3,x07435", "4x779...")
    const prefixMultMatch = trimmed.match(/^(\d+(?:[.,]\d+)?)\s*,?\s*[xX*]\s*(.+)$/);
    if (prefixMultMatch) {
      const m = parseFloat(prefixMultMatch[1].replace(',', '.'));
      const rest = prefixMultMatch[2].trim();
      if (isFinite(m) && m > 0 && m <= 9999 && rest) {
        return { onlyMultiplier: false, multiplier: m, term: rest };
      }
    }

    return { onlyMultiplier: false, multiplier: null, term: trimmed };
  }

  function isGenericArticleCode(code) {
    const clean = String(code || '').trim().replace(/^0+/, '');
    return clean === '20';
  }

  function expandUpcEToUpcAErp(upcE) {
    if (!/^[01]\d{7}$/.test(upcE)) return null;
    const ns = upcE[0];
    const d1 = upcE[1];
    const d2 = upcE[2];
    const d3 = upcE[3];
    const d4 = upcE[4];
    const d5 = upcE[5];
    const d6 = upcE[6];
    const chk = upcE[7];
    if (d6 === '0' || d6 === '1' || d6 === '2') return `${ns}${d1}${d2}${d6}0000${d3}${d4}${d5}${chk}`;
    if (d6 === '3') return `${ns}${d1}${d2}${d3}00000${d4}${d5}${chk}`;
    if (d6 === '4') return `${ns}${d1}${d2}${d3}${d4}00000${d5}${chk}`;
    return `${ns}${d1}${d2}${d3}${d4}${d5}0000${d6}${chk}`;
  }

  function buildErpBarcodeComparableKeys(rawBc) {
    const keys = new Set();
    const s = sanitizeScannerBarcode(rawBc).toUpperCase();
    if (!s) return keys;
    keys.add(s);
    if (/^\d{8,18}$/.test(s)) {
      const stripped = s.replace(/^0+/, '');
      if (stripped.length >= 7) keys.add(stripped);
      if (s.length === 12) keys.add('0' + s);
      else if (s.length === 13 && s.startsWith('0')) keys.add(s.slice(1));
      if (s.length === 8 && (s[0] === '0' || s[0] === '1')) {
        const upcA = expandUpcEToUpcAErp(s);
        if (upcA) {
          keys.add(upcA);
          keys.add('0' + upcA);
          const upcStripped = upcA.replace(/^0+/, '');
          if (upcStripped.length >= 7) keys.add(upcStripped);
        }
      }
    }
    return keys;
  }

  /**
   * Busca un artículo por Código de Producto (ej. 7435 -> 07435), Código de Barras de Balanza (prefijos 21/23 de Oliver) o Código de Barras (EAN/interno)
   */
  function findArticleByCodeOrBarcode(rawTerm) {
    const clean = sanitizeScannerBarcode(rawTerm);
    if (!clean) return null;

    // 0. Lectura de Código de Barras de Balanza estilo Oliver (CONFIG_COD_BARRAS / GET_CODIGOBARRA_ARTICULO: prefijos 21 o 23 + PLU + Peso)
    const scaleInfo = parseScaleBarcode(clean);
    if (scaleInfo && scaleInfo.art && scaleInfo.isFractionableArt) {
      if (Number(scaleInfo.art.fr) !== 1) {
        scaleInfo.art.fr = 1;
      }
      let scaleQty = scaleInfo.valueDecoded > 0 ? scaleInfo.valueDecoded : 1;
      if (scaleInfo.mode === 'PRECIO') {
        const unitPrice = getArticleUnitPriceForActiveList(scaleInfo.art);
        if (unitPrice > 0 && scaleInfo.valueDecoded > 0) {
          scaleQty = Math.round((scaleInfo.valueDecoded / unitPrice) * 1000) / 1000;
        }
      }
      return {
        art: scaleInfo.art,
        barcodeQty: scaleQty > 0 ? scaleQty : 1,
        isScaleBarcode: true,
        scaleInfo
      };
    }

    // 1. Exact Barcode match (case-insensitive)
    const upper = clean.toUpperCase();
    for (const art of STATE.articulos) {
      if (art.bl === 1) continue;
      if (Array.isArray(art.bc)) {
        const hitBc = art.bc.find((b) => String(b.c || '').trim().toUpperCase() === upper);
        if (hitBc) {
          return { art, barcodeQty: Number(hitBc.q) > 0 ? Number(hitBc.q) : 1 };
        }
      }
    }

    // 1b. Equivalencia UPC-A (12 dígitos) <-> EAN-13 (13 dígitos con 0 inicial), UPC-E (8 dígitos) y prefijo 779 <-> 79
    if (/^\d{8,18}$/.test(clean)) {
      const qKeys = buildErpBarcodeComparableKeys(clean);
      for (const art of STATE.articulos) {
        if (art.bl === 1 || !Array.isArray(art.bc) || art.bc.length === 0) continue;
        const hitEq = art.bc.find((b) => {
          const bKeys = buildErpBarcodeComparableKeys(b.c || '');
          for (const k of bKeys) {
            if (qKeys.has(k)) return true;
          }
          return false;
        });
        if (hitEq) {
          return { art, barcodeQty: Number(hitEq.q) > 0 ? Number(hitEq.q) : 1 };
        }
      }
      const altPref =
        clean.length === 12 && clean.startsWith('79')
          ? '7' + clean
          : clean.length === 13 && clean.startsWith('779')
          ? clean.slice(1)
          : '';
      if (altPref) {
        for (const art of STATE.articulos) {
          if (art.bl === 1 || !Array.isArray(art.bc)) continue;
          const hitPref = art.bc.find((b) => sanitizeScannerBarcode(b.c || '') === altPref);
          if (hitPref) {
            return { art, barcodeQty: Number(hitPref.q) > 0 ? Number(hitPref.q) : 1 };
          }
        }
      }
    }

    // 2. Exact Product Code match (00001 to 99999, with or without leading zeros)
    const padded = /^\d+$/.test(clean) && clean.length <= 5 ? clean.padStart(5, '0') : clean.toUpperCase();
    const byCode = STATE.articulos.find(
      (a) => a.bl !== 1 && (String(a.c).toUpperCase() === padded || String(a.c).toUpperCase() === upper)
    );
    if (byCode) {
      return { art: byCode, barcodeQty: 1 };
    }

    // 3. Fallback including articles in baja if explicitly typed by exact code
    const anyByCode = STATE.articulos.find(
      (a) => String(a.c).toUpperCase() === padded || String(a.c).toUpperCase() === upper
    );
    if (anyByCode) {
      return { art: anyByCode, barcodeQty: 1 };
    }

    // 4. Fallback for Código 20 (Artículo Genérico) if not present in catalog array
    if (isGenericArticleCode(clean)) {
      return {
        art: { id: 4407, c: '00020', n: 'ART. GENERICO', p1f: 0, p2f: 0, iva: 21, sf: 999, isGeneric: true },
        barcodeQty: 1
      };
    }

    // 5. Si era un código de balanza 21/23 cuyo artículo fue deshabilitado explícitamente
    if (scaleInfo && scaleInfo.art && !scaleInfo.isFractionableArt) {
      return {
        art: null,
        barcodeQty: scaleInfo.valueDecoded > 0 ? scaleInfo.valueDecoded : 1,
        scaleBlockedArt: scaleInfo.art,
        scaleInfo
      };
    }

    return null;
  }

  function getArticleUnitPriceForActiveList(art) {
    const lista = document.getElementById('fact-lista-precio')?.value || 'MINORISTA';
    if (lista === 'MAYORISTA') {
      return Number(art.p2f) > 0 ? Number(art.p2f) : Number(art.p1f) || 0;
    }
    return Number(art.p1f) || 0;
  }

  /**
   * Calcula el importe bruto de una línea de facturación.
   * Cuando proviene de un ticket de balanza (isScaleTicket), redondea al entero igual que la balanza Systel/Kretz
   * (ej: PLU 00240 · 0.120 kg × $ 19.805/kg = 2376.6 -> IMPORTE ($): 2377).
   */
  function calcFactItemGross(item) {
    const rawGross = (Number(item.cantidad) || 0) * (Number(item.precioFinal) || 0);
    if (item && item.isScaleTicket) {
      return Math.round(rawGross);
    }
    return rawGross;
  }

  let pendingEnvaseDialogInitialized = false;

  function ensurePosEnvaseDialogEvents() {
    if (pendingEnvaseDialogInitialized) return;
    const dlg = document.getElementById('pos-envase-dialog');
    if (!dlg) return;
    pendingEnvaseDialogInitialized = true;

    const qtyInp = document.getElementById('pos-envase-qty-input');
    const subLbl = document.getElementById('pos-envase-subtotal-label');
    const btnCharge = document.getElementById('btn-pos-envase-charge');
    const btnDiscard = document.getElementById('btn-pos-envase-discard');
    const btnClose = document.getElementById('btn-close-pos-envase-dialog');

    const updateEnvaseSubtotalPreview = () => {
      const envArt = findEnvaseRetornableArticle();
      const unitPrice = getArticleUnitPriceForActiveList(envArt);
      const q = Math.max(1, Math.round(Number(qtyInp?.value) || 1));
      if (subLbl) {
        subLbl.textContent = `Total: $ ${formatArs(round2(q * unitPrice))}`;
      }
    };

    qtyInp?.addEventListener('input', updateEnvaseSubtotalPreview);
    qtyInp?.addEventListener('change', () => {
      const q = Math.max(1, Math.round(Number(qtyInp.value) || 1));
      qtyInp.value = String(q);
      updateEnvaseSubtotalPreview();
    });

    const handleChargeEnvase = () => {
      const envArt = findEnvaseRetornableArticle();
      const q = Math.max(1, Math.round(Number(qtyInp?.value) || 1));
      if (dlg.open) dlg.close('charge');
      addArticleToInvoice(envArt, q, { skipEnvasePrompt: true });
    };

    const handleDiscardEnvase = () => {
      if (dlg.open) dlg.close('discard');
      focusFirstCodeInput();
    };

    btnCharge?.addEventListener('click', handleChargeEnvase);
    btnDiscard?.addEventListener('click', handleDiscardEnvase);
    btnClose?.addEventListener('click', handleDiscardEnvase);

    qtyInp?.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleChargeEnvase();
      } else if (e.key === 'Escape') {
        e.preventDefault();
        handleDiscardEnvase();
      }
    });

    dlg.addEventListener('close', () => {
      focusFirstCodeInput();
    });
  }

  function promptPosEnvaseRetornable(triggerArt, suggestedQty = 1) {
    if (!triggerArt || !doesArticleUseEnvaseRetornable(triggerArt)) return;
    ensurePosEnvaseDialogEvents();
    const dlg = document.getElementById('pos-envase-dialog');
    if (!dlg) return;

    const envArt = findEnvaseRetornableArticle();
    const unitPrice = getArticleUnitPriceForActiveList(envArt);
    const cleanQty = Math.max(1, Math.round(Number(suggestedQty) || 1));

    const nameEl = document.getElementById('pos-envase-trigger-art-name');
    const qtyBadge = document.getElementById('pos-envase-trigger-art-qty');
    const priceEl = document.getElementById('pos-envase-unit-price');
    const qtyInp = document.getElementById('pos-envase-qty-input');
    const subLbl = document.getElementById('pos-envase-subtotal-label');
    const btnCharge = document.getElementById('btn-pos-envase-charge');

    if (nameEl) nameEl.textContent = `#${triggerArt.c} — ${triggerArt.n}`;
    if (qtyBadge) qtyBadge.textContent = `Cant: ${cleanQty}`;
    if (priceEl) priceEl.textContent = `$ ${formatArs(unitPrice)}`;
    if (qtyInp) qtyInp.value = String(cleanQty);
    if (subLbl) subLbl.textContent = `Total: $ ${formatArs(round2(cleanQty * unitPrice))}`;

    if (!dlg.open) {
      dlg.showModal();
    }
    requestAnimationFrame(() => {
      if (btnCharge) {
        btnCharge.focus();
      } else if (qtyInp) {
        qtyInp.focus();
        qtyInp.select();
      }
    });
  }

  function addArticleToInvoice(art, quantity = 1, options = {}) {
    if (!art) return;
    const isScaleTicket = Boolean(options && options.isScaleTicket);
    const allowFrac = isScaleTicket || doesArticleAllowFraction(art);
    const rawQ = Number(quantity) > 0 ? Number(quantity) : 1;
    const qty = allowFrac
      ? Math.round(rawQ * 1000) / 1000
      : Math.max(1, Math.round(rawQ));
    const unitPrice = getArticleUnitPriceForActiveList(art);
    const ivaPct = Number(art.iva ?? 21);
    const isGeneric =
      isGenericArticleCode(art.c) || String(art.n || '').toUpperCase().includes('ART. GENERICO');

    let addedGenericUid = null;

    // Si es código 20 (Artículo Genérico) o un ticket pesado de balanza individual, agregamos fila independiente para respetar el importe exacto de cada etiqueta
    const existing = (!isGeneric && !isScaleTicket)
      ? STATE.factItems.find(
          (item) =>
            !item.isGeneric &&
            !item.isScaleTicket &&
            item.artId === art.id &&
            Math.abs(item.precioFinal - unitPrice) < 0.001 &&
            item.descPct === 0
        )
      : null;

    if (existing) {
      existing.cantidad = allowFrac
        ? Math.round((existing.cantidad + qty) * 1000) / 1000
        : Math.max(1, Math.round(existing.cantidad + qty));
    } else {
      const newUid = Date.now() + Math.random();
      if (isGeneric) addedGenericUid = newUid;
      STATE.factItems.push({
        uid: newUid,
        artId: art.id,
        codigo: art.c || '00020',
        nombre: art.n || 'ART. GENERICO',
        isGeneric,
        isScaleTicket,
        scaleBarcode: options?.scaleInfo?.rawBarcode || null,
        cantidad: qty,
        precioFinal: unitPrice,
        descPct: 0,
        ivaPct,
        stock: Number(art.sf ?? 0)
      });
    }

    // Limpiar la 1° línea de entrada y resetear multiplicador a 1x
    const codeInp = document.getElementById('fact-first-code-input');
    const artInp = document.getElementById('fact-first-art-input');
    const sugBox = document.getElementById('fact-art-suggestions');
    if (codeInp) codeInp.value = '';
    if (artInp) artInp.value = '';
    if (sugBox) sugBox.hidden = true;
    document.getElementById('fact-entry-preview-price').textContent = '0,0000';
    document.getElementById('fact-entry-preview-total').textContent = '0,00';
    document.getElementById('fact-entry-preview-stock').textContent = '—';

    setFactMultiplier(1);
    renderFactItemsAndTotals();

    if (addedGenericUid !== null) {
      requestAnimationFrame(() => {
        const genericNameInp = document.querySelector(
          `input[data-generic-name-uid="${addedGenericUid}"]`
        );
        if (genericNameInp) {
          genericNameInp.focus();
          genericNameInp.select();
        }
      });
    } else if (!options?.skipEnvasePrompt && doesArticleUseEnvaseRetornable(art)) {
      promptPosEnvaseRetornable(art, qty);
    } else {
      focusFirstCodeInput();
    }
  }

  function updateInvoiceTotalsDOM() {
    let subTotal = 0;
    STATE.factItems.forEach((item) => {
      const lineGross = calcFactItemGross(item);
      const lineTotal = round2(lineGross * (1 - (Number(item.descPct) || 0) / 100));
      subTotal = round2(subTotal + lineTotal);
    });

    const dtoPje = parseFloat(document.getElementById('fact-dto-pje')?.value || '0') || 0;
    const factorGlobal = 1 + dtoPje / 100;
    const dtoImp = round2(subTotal * (dtoPje / 100));
    const totalComprobante = round2(subTotal + dtoImp);

    let totalGravado = 0;
    let totalIva = 0;
    let totalExento = 0;

    STATE.factItems.forEach((item) => {
      const lineGross = calcFactItemGross(item);
      const lineAfterItemDesc = lineGross * (1 - (Number(item.descPct) || 0) / 100);
      const lineAdjusted = lineAfterItemDesc * factorGlobal;
      const ivaRate = Number(item.ivaPct ?? 21);

      if (ivaRate > 0) {
        const neto = lineAdjusted / (1 + ivaRate / 100);
        const iva = lineAdjusted - neto;
        totalGravado += neto;
        totalIva += iva;
      } else {
        totalExento += lineAdjusted;
      }
    });

    totalGravado = round2(totalGravado);
    totalIva = round2(totalIva);
    totalExento = round2(totalExento);

    if (STATE.factItems.length > 0 && totalGravado > 0) {
      const diff = round2(totalComprobante - (totalGravado + totalIva + totalExento));
      if (Math.abs(diff) <= 0.05) {
        totalIva = round2(totalIva + diff);
      }
    }

    document.getElementById('fact-subtotal').value = formatArs(subTotal);
    document.getElementById('fact-dto-imp').value = formatArs(dtoImp);
    document.getElementById('fact-tot-gravado').value = formatArs(totalGravado);
    document.getElementById('fact-tot-iva').value = formatArs(totalIva);
    document.getElementById('fact-tot-exento').value = formatArs(totalExento);
    document.getElementById('fact-grand-total-display').textContent = formatArs(totalComprobante);
    const headerTotalEl = document.getElementById('fact-header-total-display');
    if (headerTotalEl) headerTotalEl.textContent = formatArs(totalComprobante);
    document.getElementById('pos-importe-input').value = String(totalComprobante);

    const statusItems = document.getElementById('fact-status-items');
    const statusLista = document.getElementById('fact-status-lista');
    const statusVendedor = document.getElementById('fact-status-vendedor');
    if (statusItems) statusItems.textContent = `Items: ${STATE.factItems.length}`;
    if (statusLista) {
      const l = document.getElementById('fact-lista-precio')?.value || 'MINORISTA';
      statusLista.textContent = `VENTA ${l}`;
    }
    if (statusVendedor) {
      statusVendedor.textContent = document.getElementById('fact-vendedor')?.value || 'ADMINISTRADOR';
    }
    updatePosFidelizacionStrip();
  }

  function renderFactItemsAndTotals() {
    if (typeof window.evaluateActiveOffersOnPosCart === 'function') {
      window.evaluateActiveOffersOnPosCart();
    }
    const tbody = document.getElementById('fact-added-rows-tbody');
    if (!tbody) return;
    tbody.textContent = '';

    STATE.factItems.forEach((item, idx) => {
      const isGeneric =
        Boolean(item.isGeneric) ||
        isGenericArticleCode(item.codigo) ||
        String(item.nombre || '').toUpperCase().includes('ART. GENERICO');
      item.isGeneric = isGeneric;

      const calcRowLineTotal = () => {
        const lineGross = calcFactItemGross(item);
        return round2(lineGross * (1 - (Number(item.descPct) || 0) / 100));
      };

      const tr = document.createElement('tr');

      const tdCode = document.createElement('th');
      tdCode.scope = 'row';
      tdCode.innerHTML = `<span class="art-code-pill">${item.codigo}</span>`;
      tr.appendChild(tdCode);

      const tdName = document.createElement('td');
      const inpQty = document.createElement('input');
      const inpPrice = document.createElement('input');
      const tdTotal = document.createElement('td');
      const dot = document.createElement('span');

      const refreshRowAndTotals = () => {
        const lineTotal = calcRowLineTotal();
        tdTotal.innerHTML = `<span class="price-final-val">${formatArs(lineTotal)}</span>`;
        const hasStock = isGeneric ? true : Number(item.stock) >= item.cantidad;
        dot.className = 'fact-stock-dot ' + (hasStock ? 'fact-stock-dot--ok' : 'fact-stock-dot--low');
        dot.title = isGeneric ? 'Artículo de carga manual' : `Existencia en depósito: ${item.stock}`;
        dot.textContent = hasStock ? '✓' : '↓';
        updateInvoiceTotalsDOM();
      };

      if (isGeneric) {
        const inpName = document.createElement('input');
        inpName.type = 'text';
        inpName.className = 'form-input fact-generic-name-input';
        inpName.value = item.nombre || 'ART. GENERICO';
        inpName.placeholder = 'Descripción del artículo...';
        inpName.setAttribute('data-generic-name-uid', String(item.uid));
        inpName.setAttribute('aria-label', 'Nombre del artículo genérico');
        inpName.addEventListener('focus', () => inpName.select());
        inpName.addEventListener('input', () => {
          item.nombre = inpName.value;
        });
        inpName.addEventListener('change', () => {
          const cleanName = inpName.value.trim().toUpperCase();
          item.nombre = cleanName || 'ART. GENERICO';
          inpName.value = item.nombre;
        });
        inpName.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            const cleanName = inpName.value.trim().toUpperCase();
            item.nombre = cleanName || 'ART. GENERICO';
            inpName.value = item.nombre;
            inpQty.focus();
            inpQty.select();
          }
        });
        tdName.appendChild(inpName);
      } else {
        const scaleBadgeHtml = item.isScaleTicket
          ? ` <span class="mini-tag mini-tag--frac" style="margin-inline-start:0.35rem; font-size:0.68rem;">⚖️ PLU ${item.codigo}</span>`
          : '';
        const ofertaBadgeHtml = item.ofertaLabel
          ? ` <span class="badge badge--gold" style="margin-inline-start:0.35rem; font-size:0.68rem;">🏷️ ${escapeHtml(item.ofertaLabel)}</span>`
          : '';
        const artObjForRow = STATE.articulos.find((a) => a.id === item.artId) || null;
        const envBadgeHtml = artObjForRow && doesArticleUseEnvaseRetornable(artObjForRow)
          ? ` <span class="mini-tag" style="margin-inline-start:0.35rem; font-size:0.68rem; background:rgba(16,185,129,0.15); color:#10b981; border:1px solid rgba(16,185,129,0.4);">🍾 Envase Retornable</span>`
          : '';
        tdName.innerHTML = `<strong>${escapeHtml(item.nombre)}</strong>${scaleBadgeHtml}${envBadgeHtml}${ofertaBadgeHtml}`;
      }
      tr.appendChild(tdName);

      const tdQty = document.createElement('td');
      const rowArtObj = STATE.articulos.find((a) => a.id === item.artId) || null;
      const allowRowFrac = Boolean(item.isScaleTicket) || doesArticleAllowFraction(rowArtObj);
      if (!allowRowFrac) {
        item.cantidad = Math.max(1, Math.round(Number(item.cantidad) || 1));
      }
      let prevCommittedQty = item.cantidad;
      inpQty.type = 'number';
      inpQty.step = allowRowFrac ? '0.001' : '1';
      inpQty.min = allowRowFrac ? '0.001' : '1';
      inpQty.className = 'form-input fact-num-input';
      inpQty.value = allowRowFrac ? item.cantidad.toFixed(3) : String(Math.max(1, Math.round(item.cantidad)));
      inpQty.setAttribute('aria-label', `Cantidad de ${item.nombre}`);
      inpQty.addEventListener('focus', () => {
        prevCommittedQty = item.cantidad;
        inpQty.select();
      });
      inpQty.addEventListener('input', () => {
        stripDecimalInputIfNotFrac(inpQty, allowRowFrac);
        const v = parseFloat(inpQty.value);
        if (isFinite(v) && v > 0) {
          item.cantidad = allowRowFrac ? Math.round(v * 1000) / 1000 : Math.max(1, Math.round(v));
          refreshRowAndTotals();
        }
      });
      const commitRowQtyChange = (fromEnterKey = false) => {
        stripDecimalInputIfNotFrac(inpQty, allowRowFrac);
        const v = parseFloat(inpQty.value);
        const newQty = isFinite(v) && v > 0
          ? (allowRowFrac ? Math.round(v * 1000) / 1000 : Math.max(1, Math.round(v)))
          : 1;
        const deltaQty = allowRowFrac
          ? Math.round((newQty - prevCommittedQty) * 1000) / 1000
          : Math.round(newQty - prevCommittedQty);
        prevCommittedQty = newQty;
        item.cantidad = newQty;
        inpQty.value = allowRowFrac ? item.cantidad.toFixed(3) : String(item.cantidad);
        refreshRowAndTotals();
        const artObjForRow = STATE.articulos.find((a) => a.id === item.artId) || null;
        if (deltaQty > 0 && artObjForRow && doesArticleUseEnvaseRetornable(artObjForRow)) {
          promptPosEnvaseRetornable(artObjForRow, deltaQty);
          return;
        }
        if (fromEnterKey) {
          if (isGeneric) {
            inpPrice.focus();
            inpPrice.select();
          } else {
            focusFirstCodeInput();
          }
        }
      };
      inpQty.addEventListener('change', () => commitRowQtyChange(false));
      inpQty.addEventListener('keydown', (e) => {
        preventDecimalKeyIfNotFrac(e, allowRowFrac);
        if (e.key === 'Enter') {
          e.preventDefault();
          commitRowQtyChange(true);
        }
      });
      tdQty.appendChild(inpQty);
      tr.appendChild(tdQty);

      const tdPrice = document.createElement('td');
      inpPrice.type = 'number';
      inpPrice.step = '0.01';
      inpPrice.min = '0';
      inpPrice.className = 'form-input fact-num-input';
      inpPrice.value = item.precioFinal.toFixed(4);
      inpPrice.setAttribute('aria-label', `Precio final de ${item.nombre}`);
      inpPrice.addEventListener('focus', () => inpPrice.select());
      inpPrice.addEventListener('input', () => {
        const v = parseFloat(inpPrice.value);
        if (isFinite(v) && v >= 0) {
          item.precioFinal = v;
          refreshRowAndTotals();
        }
      });
      inpPrice.addEventListener('change', () => {
        const v = parseFloat(inpPrice.value);
        item.precioFinal = isFinite(v) && v >= 0 ? v : 0;
        inpPrice.value = item.precioFinal.toFixed(4);
        refreshRowAndTotals();
      });
      inpPrice.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          const v = parseFloat(inpPrice.value);
          item.precioFinal = isFinite(v) && v >= 0 ? v : 0;
          inpPrice.value = item.precioFinal.toFixed(4);
          refreshRowAndTotals();
          focusFirstCodeInput();
        }
      });
      tdPrice.appendChild(inpPrice);
      tr.appendChild(tdPrice);

      const tdDesc = document.createElement('td');
      const inpDesc = document.createElement('input');
      inpDesc.type = 'number';
      inpDesc.step = '0.01';
      inpDesc.min = '0';
      inpDesc.max = '100';
      inpDesc.className = 'form-input fact-num-input';
      inpDesc.value = (Number(item.descPct) || 0).toFixed(2);
      inpDesc.setAttribute('aria-label', `Porcentaje de descuento de ${item.nombre}`);
      inpDesc.addEventListener('focus', () => inpDesc.select());
      inpDesc.addEventListener('input', () => {
        const v = parseFloat(inpDesc.value);
        if (isFinite(v) && v >= 0 && v <= 100) {
          item.descPct = v;
          refreshRowAndTotals();
        }
      });
      inpDesc.addEventListener('change', () => {
        const v = parseFloat(inpDesc.value);
        item.descPct = isFinite(v) && v >= 0 && v <= 100 ? v : 0;
        inpDesc.value = item.descPct.toFixed(2);
        refreshRowAndTotals();
      });
      inpDesc.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          const v = parseFloat(inpDesc.value);
          item.descPct = isFinite(v) && v >= 0 && v <= 100 ? v : 0;
          inpDesc.value = item.descPct.toFixed(2);
          refreshRowAndTotals();
          focusFirstCodeInput();
        }
      });
      tdDesc.appendChild(inpDesc);
      tr.appendChild(tdDesc);

      tdTotal.style.textAlign = 'right';
      tr.appendChild(tdTotal);

      const tdStock = document.createElement('td');
      tdStock.style.textAlign = 'center';
      const stockWrap = document.createElement('div');
      stockWrap.style.display = 'inline-flex';
      stockWrap.style.alignItems = 'center';
      stockWrap.style.gap = '0.35rem';

      const btnDel = document.createElement('button');
      btnDel.type = 'button';
      btnDel.className = 'btn-remove-row';
      btnDel.style.minWidth = '26px';
      btnDel.style.minHeight = '26px';
      btnDel.title = 'Quitar ítem del comprobante';
      btnDel.textContent = '✕';
      btnDel.addEventListener('click', () => {
        STATE.factItems.splice(idx, 1);
        renderFactItemsAndTotals();
        focusFirstCodeInput();
      });

      stockWrap.appendChild(dot);
      stockWrap.appendChild(btnDel);
      tdStock.appendChild(stockWrap);
      tr.appendChild(tdStock);

      refreshRowAndTotals();
      tbody.appendChild(tr);
    });

    if (STATE.factItems.length === 0) {
      updateInvoiceTotalsDOM();
    }
  }

  function getCorrelativoKeyForFact(pv, tipoComp, letra) {
    const cleanPv = String(pv || '0004').trim();
    const isRespInsc = letra === 'A';
    if (tipoComp === 'Nota de Crédito') {
      return `${cleanPv}-NC-${isRespInsc ? 'A' : 'B'}`;
    }
    if (tipoComp === 'Nota de Débito') {
      return `${cleanPv}-ND-${isRespInsc ? 'A' : 'B'}`;
    }
    if (isRespInsc) {
      return `${cleanPv}-A`;
    }
    return cleanPv;
  }

  function getNextCorrelativoForFact(pv, tipoComp, letra) {
    const key = getCorrelativoKeyForFact(pv, tipoComp, letra);
    const minOliver = Number(OLIVER_NEXT_CORRELATIVOS[key]) || (key === pv ? Number(OLIVER_NEXT_CORRELATIVOS[pv]) : 1) || 1;
    const current = Number(STATE.factCorrelativos[key]) || 0;
    const val = Math.max(current, minOliver);
    STATE.factCorrelativos[key] = val;
    return val;
  }

  function updateFactLetraAndNumber() {
    const pv = document.getElementById('pos-select-pv')?.value || '0004';
    const tipoComp = document.getElementById('pos-tipo-comp')?.value || 'Factura';
    const respIva = (document.getElementById('fact-cli-respiva')?.value || 'Consumidor Final').toUpperCase();

    const isInternalPv = pv === '0099' || pv === '0100' || pv === '0101' || tipoComp === 'Comprobante Interno';
    const isRespInsc = respIva.includes('INSCRIPTO') && !respIva.includes('NO INSCRIPTO');
    const letra = isRespInsc ? 'A' : 'B';
    let subCode = 'Cód. ARCA 006';

    if (isInternalPv) {
      subCode = `Comprobante Interno ${letra}`;
    } else if (isRespInsc) {
      subCode = tipoComp === 'Nota de Crédito' ? 'Cód. ARCA 003' : tipoComp === 'Nota de Débito' ? 'Cód. ARCA 002' : 'Cód. ARCA 001';
    } else {
      subCode = tipoComp === 'Nota de Crédito' ? 'Cód. ARCA 008' : tipoComp === 'Nota de Débito' ? 'Cód. ARCA 007' : 'Cód. ARCA 006';
    }

    const letraCol = document.getElementById('fact-letra-column');
    const letraBox = document.getElementById('fact-letra-box');
    const letraSub = document.getElementById('fact-letra-sub');
    const nroPv = document.getElementById('fact-nro-pv');
    const nroComp = document.getElementById('fact-nro-comp');
    const nroWrap = document.getElementById('fact-correlativo-wrap');
    const nroFullDisplay = document.getElementById('fact-nro-full-display');
    const pvModePill = document.getElementById('fact-pv-mode-pill');
    const statusModo = document.getElementById('fact-status-modo');

    if (letraBox) letraBox.textContent = letra;
    if (letraSub) {
      letraSub.textContent = isInternalPv ? 'INTERNO' : 'ARCA';
      letraSub.hidden = false;
      letraSub.style.display = '';
      letraSub.title = subCode;
    }
    if (nroPv) nroPv.value = pv;

    // Numeración exacta por Punto de Venta y Letra (A o B) igual que en Oliver Informática
    const nextCorrelativo = getNextCorrelativoForFact(pv, tipoComp, letra);
    if (nroComp) nroComp.value = String(nextCorrelativo).padStart(8, '0');
    if (nroFullDisplay) {
      nroFullDisplay.value = `${pv}-${String(nextCorrelativo).padStart(8, '0')}`;
    }

    // Indicadores visuales de color y texto según Punto de Venta (Verde Fiscal ARCA vs Naranja Comprobante Interno)
    [nroWrap, nroFullDisplay, pvModePill, letraCol, statusModo].forEach((el) => {
      if (!el) return;
      el.classList.toggle('is-pv-interno', isInternalPv);
      el.classList.toggle('is-pv-fiscal', !isInternalPv);
    });
    if (pvModePill) {
      pvModePill.textContent = isInternalPv ? 'INTERNO' : 'ARCA';
    }

    if (statusModo) {
      statusModo.textContent = isInternalPv
        ? `📄 COMPROBANTE INTERNO (PV ${pv})`
        : `🧾 COMPROBANTE ELECTRÓNICO ARCA (PV ${pv})`;
    }
  }

  function doesClientAllowCtaCte(cli) {
    if (!cli) return false;
    if (getGenericSystemClientRule(cli)) return false;
    return Boolean(cli.habilitarCtaCte || Number(cli.habilitaCtaCte));
  }

  function getActiveFactClientObj() {
    const byId = STATE.clientes.find((c) => Number(c.id) === Number(STATE.factSelectedClientId));
    if (byId) return byId;
    const rawCode = String(document.getElementById('fact-cli-codigo')?.value || '').trim();
    if (rawCode && rawCode !== '1') {
      return STATE.clientes.find((c) => String(c.codigo) === rawCode) || null;
    }
    return null;
  }

  function syncFactFormaPagoControl(cli = null, resetSelectionFromClient = false) {
    const fpSel = document.getElementById('pos-medio-pago');
    if (!fpSel) return;
    const targetCli = cli || getActiveFactClientObj();
    const hasCtaCte = doesClientAllowCtaCte(targetCli);
    const optCtaCte = fpSel.querySelector('option[value="Cuenta Corriente"]');
    if (optCtaCte) {
      optCtaCte.disabled = !hasCtaCte;
      optCtaCte.hidden = !hasCtaCte;
    }
    if (hasCtaCte) {
      if (resetSelectionFromClient) {
        const fpPred = String(targetCli?.formaPagoPredeterminada || '').toUpperCase();
        fpSel.value = fpPred === 'CONTADO' ? 'Contado' : 'Cuenta Corriente';
      } else if (fpSel.value !== 'Contado' && fpSel.value !== 'Cuenta Corriente') {
        fpSel.value = 'Contado';
      }
      fpSel.disabled = false;
      fpSel.removeAttribute('aria-disabled');
      fpSel.removeAttribute('tabindex');
      const toggleKey =
        typeof getActiveAtajoKeyForAction === 'function' ? getActiveAtajoKeyForAction('pos:toggle-forma-pago') : '';
      fpSel.title = toggleKey
        ? `Podés elegir entre Contado y Cuenta Corriente (CTRL + ${toggleKey})`
        : 'Podés elegir entre Contado y Cuenta Corriente para este cliente';
    } else {
      fpSel.value = 'Contado';
      fpSel.disabled = true;
      fpSel.setAttribute('aria-disabled', 'true');
      fpSel.title = 'Este cliente no tiene Cuenta Corriente habilitada en el módulo de Clientes (solo Contado)';
    }
  }

  function toggleFactFormaPago() {
    const fpSel = document.getElementById('pos-medio-pago');
    const cli = getActiveFactClientObj();
    const alertEl = document.getElementById('fact-alert-msg');
    if (!doesClientAllowCtaCte(cli)) {
      if (fpSel) fpSel.value = 'Contado';
      if (alertEl) {
        alertEl.textContent =
          '⚠️ Este cliente no tiene configurada la opción de Cuenta Corriente en el módulo de Clientes. Solo puede facturarse de Contado.';
        alertEl.hidden = false;
      }
      focusFirstCodeInput();
      return;
    }
    if (fpSel) {
      fpSel.value = fpSel.value === 'Cuenta Corriente' ? 'Contado' : 'Cuenta Corriente';
    }
    if (alertEl && alertEl.textContent.includes('Cuenta Corriente')) {
      alertEl.hidden = true;
    }
    focusFirstCodeInput();
  }

  function toggleFactPuntoVentaCaja() {
    const cfg = CAJAS_CONFIG[STATE.activeCajaId || 'caja1'];
    const pvSel = document.getElementById('pos-select-pv');
    if (!cfg || !pvSel) return;

    [cfg.pvFiscal, cfg.pvInterno].filter(Boolean).forEach((pvNum) => {
      if (!Array.from(pvSel.options).some((opt) => opt.value === pvNum)) {
        const opt = document.createElement('option');
        opt.value = pvNum;
        opt.textContent = pvNum;
        pvSel.appendChild(opt);
      }
    });

    const currentPv = pvSel.value || document.getElementById('fact-nro-pv')?.value || cfg.pvFiscal;
    const tipoSel = document.getElementById('pos-tipo-comp');
    const isCurrentlyInterno =
      currentPv === cfg.pvInterno ||
      currentPv === '0099' ||
      currentPv === '0100' ||
      currentPv === '0101' ||
      tipoSel?.value === 'Comprobante Interno';

    pvSel.value = isCurrentlyInterno ? cfg.pvFiscal : cfg.pvInterno;
    if (isCurrentlyInterno && tipoSel && tipoSel.value === 'Comprobante Interno') {
      tipoSel.value = 'Factura';
    }
    updateFactLetraAndNumber();

    // Efecto pulso de atención al alternar con CTRL + F12 o clic en Letra / Número
    const nroWrap = document.getElementById('fact-correlativo-wrap');
    const letraCol = document.getElementById('fact-letra-column');
    [nroWrap, letraCol].forEach((el) => {
      if (!el) return;
      el.classList.remove('is-pv-flash');
      void el.offsetWidth;
      el.classList.add('is-pv-flash');
    });

    focusFirstCodeInput();
  }

  document.getElementById('fact-correlativo-wrap')?.addEventListener('click', () => {
    toggleFactPuntoVentaCaja();
  });
  document.getElementById('fact-letra-column')?.addEventListener('click', () => {
    toggleFactPuntoVentaCaja();
  });
  document.getElementById('fact-letra-column')?.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      toggleFactPuntoVentaCaja();
    }
  });

  function selectClientForInvoice(cli) {
    if (!cli) return;
    STATE.factSelectedClientId = cli.id;
    document.getElementById('fact-cli-codigo').value = String(cli.codigo ?? 1);
    document.getElementById('pos-cliente-input').value = String(cli.nombre || 'CONSUMIDOR FINAL').toUpperCase();
    document.getElementById('fact-cli-tipodoc').value = String(cli.tipoDoc || 'OTRO').toUpperCase();
    document.getElementById('fact-cli-nrodoc').value = String(cli.nroDoc || '00.000.000');
    document.getElementById('fact-cli-respiva').value = String(cli.respIva || 'Consumidor Final');
    document.getElementById('fact-cli-calle').value = String(cli.calle || '...');
    document.getElementById('fact-cli-nro').value = String(cli.numero || '0');

    const genericRule = getGenericSystemClientRule(cli);
    const listaSel = document.getElementById('fact-lista-precio');
    if (listaSel) {
      const targetList = genericRule
        ? genericRule.listaPrecio
        : (String(cli.listaPrecio || '').toUpperCase().includes('MAYORISTA') || Number(cli.listaPrecioId ?? cli.listaPrecios ?? 1) === 2
            ? 'MAYORISTA'
            : 'MINORISTA');
      const prevList = listaSel.value;
      listaSel.value = targetList;
      listaSel.disabled = true;
      if (prevList !== targetList || STATE.factItems.length > 0) {
        // Recalcular precios de ítems según la lista del cliente (excepto Artículo Genérico 00020)
        STATE.factItems.forEach((it) => {
          if (it.isGeneric || isGenericArticleCode(it.codigo)) return;
          const art = STATE.articulos.find((a) => a.id === it.artId);
          if (art) it.precioFinal = getArticleUnitPriceForActiveList(art);
        });
      }
    }

    syncFactFormaPagoControl(cli, true);

    const cliDrop = document.getElementById('fact-cli-dropdown');
    if (cliDrop) cliDrop.hidden = true;

    const chkFid = document.getElementById('pos-fid-acreditar-chk');
    if (chkFid) {
      chkFid.checked = String(cli.codigo ?? '1') !== '1';
    }
    const chkFidAuto = document.getElementById('pos-fid-auto-sumar');
    if (chkFidAuto && String(cli.codigo ?? '1') !== '1') {
      chkFidAuto.checked = true;
    }

    updateFactLetraAndNumber();
    renderFactItemsAndTotals();
    if (typeof updatePosFidelizacionPreview === 'function') {
      updatePosFidelizacionPreview();
    }
    focusFirstCodeInput();
  }

  function setDefaultVendedorFromLoggedUser() {
    const vendSel = document.getElementById('fact-vendedor');
    if (!vendSel) return;

    let activeUser = STATE.currentUser || null;
    if (!activeUser) {
      try {
        const raw = getPersistedAdminSessionRaw();
        if (raw) activeUser = JSON.parse(raw);
      } catch {}
    }

    const uname = String(activeUser?.username || '').toLowerCase();
    const dirRecord = ADMIN_DIRECTORY[uname];
    const rawLinkedName = dirRecord?.name || activeUser?.name || dirRecord?.vendedor || activeUser?.vendedor || 'GHIGLIONE DANIEL ALEJANDRO';
    const targetVendedor = String(rawLinkedName).trim().toUpperCase();

    const exists = Array.from(vendSel.options).some((opt) => opt.value === targetVendedor);
    if (!exists && targetVendedor) {
      const opt = document.createElement('option');
      opt.value = targetVendedor;
      opt.textContent = targetVendedor;
      vendSel.appendChild(opt);
    }
    vendSel.value = targetVendedor;

    const statusVendedor = document.getElementById('fact-status-vendedor');
    if (statusVendedor) {
      statusVendedor.textContent = targetVendedor;
    }
  }

  function resetInvoiceToDefaults() {
    STATE.factItems = [];
    setFactMultiplier(1);
    const tipoCompEl = document.getElementById('pos-tipo-comp');
    if (tipoCompEl) tipoCompEl.value = 'Factura';
    const cfg = CAJAS_CONFIG[STATE.activeCajaId || 'caja1'];
    const pvSel = document.getElementById('pos-select-pv');
    if (cfg && pvSel && (!pvSel.value || pvSel.value === cfg.pvFiscal)) {
      pvSel.value = cfg.pvFiscal;
    }
    const dtoPjeEl = document.getElementById('fact-dto-pje');
    if (dtoPjeEl) dtoPjeEl.value = '0.00';
    const obsEl = document.getElementById('fact-observacion-txt');
    if (obsEl) obsEl.value = '';
    const alertEl = document.getElementById('fact-alert-msg');
    if (alertEl) alertEl.hidden = true;

    setDefaultVendedorFromLoggedUser();

    const cfCli = STATE.clientes.find((c) => String(c.codigo) === '1') || {
      id: 1,
      codigo: 1,
      nombre: 'CONSUMIDOR FINAL',
      tipoDoc: 'OTRO',
      nroDoc: '00.000.000',
      respIva: 'Consumidor Final',
      calle: '...',
      numero: '0',
      listaPrecio: 'MINORISTA',
      habilitarCtaCte: false
    };
    selectClientForInvoice(cfCli);
  }

  let clubCameraStream = null;
  let clubCameraScanTimer = null;

  function stopClubCameraScanner() {
    if (clubCameraScanTimer) {
      clearInterval(clubCameraScanTimer);
      clubCameraScanTimer = null;
    }
    if (clubCameraStream) {
      clubCameraStream.getTracks().forEach((t) => t.stop());
      clubCameraStream = null;
    }
    const camBox = document.getElementById('club-camera-box');
    if (camBox) camBox.hidden = true;
  }

  function renderClubSelectedMemberPreview(client) {
    const card = document.getElementById('club-selected-member-card');
    const nameEl = document.getElementById('club-selected-member-name');
    const metaEl = document.getElementById('club-selected-member-meta');
    const ptsEl = document.getElementById('club-selected-member-pts');
    const alertEl = document.getElementById('club-previo-alert');
    if (alertEl) alertEl.hidden = true;

    if (!client || String(client.codigo) === '1') {
      STATE.clubPrevioClientId = null;
      if (card) card.hidden = true;
      return;
    }

    STATE.clubPrevioClientId = client.id;
    recalcAllClientsFidelizacionPoints();
    const dni = extractDisplayDni(client);
    const pts = Number(client.puntosFidelizacion) || 0;

    if (nameEl) nameEl.textContent = client.nombre;
    if (metaEl) metaEl.textContent = `${client.tipoDoc || 'DNI'}: ${client.nroDoc || dni} · Socio #${client.codigo} · Lista ${client.listaPrecio || 'MINORISTA'}`;
    if (ptsEl) ptsEl.innerHTML = `${erpClubFidelBadgeSvg(20)} ${pts.toLocaleString('es-AR')} pts`;
    if (card) card.hidden = false;
  }

