  function requireCajaAperturaBeforeOperar(cajaIdParam) {
    const cajaId = cajaIdParam || STATE.activeCajaId || 'caja1';
    if (!['caja1', 'caja2', 'caja3'].includes(cajaId)) return true;
    const cfg = CAJAS_CONFIG[cajaId];
    const activeAp = typeof getActiveShiftAperturaForCaja === 'function'
      ? getActiveShiftAperturaForCaja(cajaId, true)
      : null;
    if (activeAp) return true;

    const userInfo = getActiveUserClosureInfo();
    const anyOpenAp = typeof getActiveShiftAperturaForCaja === 'function'
      ? getActiveShiftAperturaForCaja(cajaId, false)
      : null;
    if (typeof playFactAlertBeep === 'function') playFactAlertBeep();

    if (anyOpenAp && anyOpenAp.usuario) {
      window.alert(
        `⛔ UN SOLO USUARIO POR CAJA (${cfg ? cfg.nombre.toUpperCase() : cajaId.toUpperCase()})\n\n` +
        `Por caja puede haber un solo usuario con "Apertura de Caja".\n` +
        `Actualmente ${cfg ? cfg.nombre : cajaId} ya tiene una Apertura de Caja activa a nombre de:\n` +
        `👤 ${anyOpenAp.usuario} (${anyOpenAp.fechaHora || 'Turno actual'})\n\n` +
        `El usuario ${userInfo.displayName} no puede abrir ni operar ${cfg ? cfg.nombre : cajaId} hasta que ${anyOpenAp.usuario} realice el Cierre de Caja.`
      );
      return false;
    }

    window.alert(
      `🔒 APERTURA DE CAJA OBLIGATORIA (${cfg ? cfg.nombre.toUpperCase() : cajaId.toUpperCase()})\n\n` +
      `No existe una Apertura de Caja activa en ${cfg ? cfg.nombre : cajaId} luego del último Cierre de Caja.\n` +
      `El usuario (${userInfo.displayName}) debe confirmar primero la Apertura de Caja y el stock de dinero dejado en el cierre anterior antes de operar.`
    );
    STATE.activeCajaId = cajaId;
    switchSection('sec-caja-apertura');
    return false;
  }

