  // =========================================================================
  // EVENTOS DE LA GRILLA DE FACTURACIÓN (1° LÍNEA CÓDIGO, BARCODE Y 2x/3x/4x)
  // =========================================================================
  const factFirstCodeInput = document.getElementById('fact-first-code-input');
  const factFirstArtInput = document.getElementById('fact-first-art-input');
  const factFirstQtyInput = document.getElementById('fact-first-qty-input');
  const factSuggestionsBox = document.getElementById('fact-art-suggestions');
  let factSugMatches = [];
  let factSugIndex = 0;
  let lastMissingBarcodeState = { code: '', scaleInfo: null, effectiveMult: 1 };

  function playFactAlertBeep() {
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;
      const ctx = new AudioCtx();
      const now = ctx.currentTime;
      [0, 0.16].forEach((offset, idx) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(idx === 0 ? 520 : 370, now + offset);
        gain.gain.setValueAtTime(0.18, now + offset);
        gain.gain.exponentialRampToValueAtTime(0.001, now + offset + 0.13);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now + offset);
        osc.stop(now + offset + 0.14);
      });
      setTimeout(() => {
        try {
          ctx.close();
        } catch {}
      }, 450);
    } catch {}
  }

  function hideFactMissingBarcodeAlert() {
    const banner = document.getElementById('fact-scan-alert-banner');
    if (banner) banner.hidden = true;
    const footerAlert = document.getElementById('fact-alert-msg');
    if (footerAlert) footerAlert.hidden = true;
  }

  function triggerFactMissingBarcodeAlert(rawMissingTerm, scaleInfo = null, effectiveMult = 1) {
    const cleanCode = String(rawMissingTerm || '').trim();
    if (!cleanCode) return;

    lastMissingBarcodeState = {
      code: cleanCode,
      scaleInfo: scaleInfo || parseScaleBarcode(cleanCode),
      effectiveMult: Number(effectiveMult) > 0 ? Number(effectiveMult) : 1
    };

    playFactAlertBeep();

    const sc = lastMissingBarcodeState.scaleInfo;
    const hasBlockedScaleArt = Boolean(sc && sc.art && !sc.isFractionableArt);
    const weightFormatted = sc && sc.valueDecoded > 0
      ? sc.valueDecoded.toLocaleString('es-AR', { minimumFractionDigits: 3, maximumFractionDigits: 3 })
      : '1,000';

    let titleMsg = 'CÓDIGO DE BARRAS NO ENCONTRADO EN EL SISTEMA';
    let detailMsg = `El código o código de barras "${cleanCode}" no está registrado en ningún artículo del sistema.`;

    if (hasBlockedScaleArt) {
      titleMsg = 'ARTÍCULO SIN "PERMITIR FRACCIONAMIENTO" HABILITADO';
      detailMsg = `El ticket de balanza "${cleanCode}" (Prefijo ${sc.prefix}) corresponde a #${sc.art.c} — ${sc.art.n} (${weightFormatted} kg), pero dicho artículo no tiene tildada la opción "Permitir fraccionamiento".`;
    } else if (sc && !sc.art) {
      titleMsg = 'CÓDIGO DE BALANZA NO ENCONTRADO EN EL SISTEMA';
      detailMsg = `El ticket de balanza "${cleanCode}" (Prefijo ${sc.prefix}) busca el artículo código #${sc.artCode5} con peso ${weightFormatted} kg, pero el código #${sc.artCode5} no existe en el catálogo.`;
    }

    // 1. Mostrar banner superior inmediato sobre la línea de escaneo
    const banner = document.getElementById('fact-scan-alert-banner');
    const bannerTitle = document.getElementById('fact-scan-alert-title');
    const bannerText = document.getElementById('fact-scan-alert-text');
    const btnBannerEnableFrac = document.getElementById('btn-fact-alert-enable-frac');
    if (bannerTitle) bannerTitle.textContent = titleMsg;
    if (bannerText) bannerText.textContent = detailMsg;
    if (btnBannerEnableFrac) {
      btnBannerEnableFrac.hidden = !hasBlockedScaleArt;
      if (hasBlockedScaleArt) {
        btnBannerEnableFrac.textContent = `⚖️ Habilitar Fraccionamiento en #${sc.art.c} y Cargar (${weightFormatted} kg)`;
      }
    }
    if (banner) banner.hidden = false;

    // 2. Mostrar también en la alerta del pie por compatibilidad
    const alertEl = document.getElementById('fact-alert-msg');
    if (alertEl) {
      alertEl.textContent = `⚠️ ${detailMsg}`;
      alertEl.hidden = false;
    }

    // 3. Abrir diálogo modal de alerta para que el cajero no siga escaneando sin advertirlo
    const dialog = document.getElementById('fact-missing-barcode-dialog');
    const dialogTitle = document.getElementById('fact-missing-bc-title');
    const dialogCode = document.getElementById('fact-missing-bc-code');
    const dialogDetail = document.getElementById('fact-missing-bc-detail');
    const btnModalEnableFrac = document.getElementById('btn-fact-missing-bc-enable-frac');
    const btnModalOk = document.getElementById('btn-fact-missing-bc-ok');
    const searchPanel = document.getElementById('fact-missing-bc-search-panel');
    const searchInp = document.getElementById('fact-missing-bc-search-input');

    if (dialog) {
      dialog.style.maxInlineSize = '580px';
    }
    if (searchPanel) {
      searchPanel.hidden = true;
    }
    if (searchInp) {
      searchInp.value = '';
    }

    if (dialogTitle) dialogTitle.textContent = titleMsg;
    if (dialogCode) dialogCode.textContent = cleanCode;
    if (dialogDetail) dialogDetail.textContent = detailMsg;
    if (btnModalEnableFrac) {
      btnModalEnableFrac.hidden = !hasBlockedScaleArt;
      if (hasBlockedScaleArt) {
        btnModalEnableFrac.textContent = `⚖️ Habilitar "Permitir fraccionamiento" en #${sc.art.c} y Cargar (${weightFormatted} kg)`;
      }
    }

    if (dialog && typeof dialog.showModal === 'function') {
      if (!dialog.open) {
        dialog.showModal();
      }
      requestAnimationFrame(() => {
        if (hasBlockedScaleArt && btnModalEnableFrac) {
          btnModalEnableFrac.focus();
        } else if (btnModalOk) {
          btnModalOk.focus();
        }
      });
    } else if (factFirstCodeInput) {
      factFirstCodeInput.select();
    }
  }

  function closeMissingBarcodeDialogAndRefocus() {
    STATE.pendingFactMissingBarcodeContext = null;
    const dialog = document.getElementById('fact-missing-barcode-dialog');
    if (dialog && dialog.open) {
      dialog.close();
    }
    if (factFirstCodeInput) {
      factFirstCodeInput.focus();
      factFirstCodeInput.select();
    }
  }

  function handleEnableFractionableFromScaleAlert() {
    const sc = lastMissingBarcodeState.scaleInfo;
    if (!sc || !sc.art) return;
    sc.art.fr = 1;
    saveLocalAbmCatalogOverrides();
    fetch('api/catalog.php', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'save_article',
        article: sc.art
      })
    }).catch(() => {});

    const dialog = document.getElementById('fact-missing-barcode-dialog');
    if (dialog && dialog.open) {
      dialog.close();
    }
    hideFactMissingBarcodeAlert();

    const qty = (sc.valueDecoded > 0 ? sc.valueDecoded : 1) * (lastMissingBarcodeState.effectiveMult || 1);
    addArticleToInvoice(sc.art, qty);
  }

  function handleCreateArticleFromMissingBarcodeAlert() {
    const missingCode = lastMissingBarcodeState.code;
    const sc = lastMissingBarcodeState.scaleInfo;
    STATE.pendingFactMissingBarcodeContext = { ...lastMissingBarcodeState };
    const dialog = document.getElementById('fact-missing-barcode-dialog');
    if (dialog && dialog.open) {
      dialog.close();
    }
    openArticleModal(null);
    if (sc && !sc.art) {
      const codeInp = document.getElementById('art-codigo');
      const fracChk = document.getElementById('art-fraccionar');
      if (codeInp) codeInp.value = sc.artCode5;
      if (fracChk) fracChk.checked = true;
      syncModalFraccionarPreview();
    } else if (missingCode) {
      const firstBcInp = document.querySelector('#barcodes-rows-container .bc-code-input');
      if (firstBcInp) {
        firstBcInp.value = missingCode;
      }
    }
  }

  let factMissingBcSearchMode = 'search';

  function getMissingBarcodeEffectiveInvoiceQty() {
    const sc = lastMissingBarcodeState.scaleInfo;
    const baseQty = sc && sc.valueDecoded > 0 ? sc.valueDecoded : 1;
    const mult = Number(lastMissingBarcodeState.effectiveMult) > 0 ? Number(lastMissingBarcodeState.effectiveMult) : 1;
    return baseQty * mult;
  }

  function associateMissingBarcodeToExistingArticleAndBill(art) {
    if (!art) return;
    const missingCode = String(lastMissingBarcodeState.code || '').trim();
    const sc = lastMissingBarcodeState.scaleInfo;
    const dialog = document.getElementById('fact-missing-barcode-dialog');

    if (missingCode && !sc) {
      const dupArt = findArticleWithDuplicateBarcode(missingCode, art.id);
      if (dupArt) {
        window.alert(
          `⛔ El código de barras "${missingCode}" ya pertenece al artículo #${dupArt.c} — ${dupArt.n}.`
        );
        return;
      }
      if (!Array.isArray(art.bc)) art.bc = [];
      const alreadyHas = art.bc.some((b) => String(b.c || '').trim().toUpperCase() === missingCode.toUpperCase());
      if (!alreadyHas) {
        art.bc.push({ c: missingCode, q: 1 });
        saveLocalAbmCatalogOverrides();
        fetch('api/catalog.php', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'save_article',
            article: art
          })
        }).catch(() => {});
      }
    }

    STATE.pendingFactMissingBarcodeContext = null;
    if (dialog && dialog.open) {
      dialog.close();
    }
    hideFactMissingBarcodeAlert();
    addArticleToInvoice(art, getMissingBarcodeEffectiveInvoiceQty());
  }

  function renderFactMissingBcSearchResults(rawQuery = '', mode = factMissingBcSearchMode) {
    const tbody = document.getElementById('fact-missing-bc-search-tbody');
    const statusEl = document.getElementById('fact-missing-bc-search-status');
    if (!tbody) return;

    const missingCode = String(lastMissingBarcodeState.code || '').trim();
    const sc = lastMissingBarcodeState.scaleInfo;
    const q = String(rawQuery || '').trim().toLowerCase();
    const tokens = q ? q.split(/\s+/).filter(Boolean) : [];
    const paddedTerm = /^\d+$/.test(q) && q.length <= 5 ? q.padStart(5, '0') : '';

    const matches = [];
    for (const art of STATE.articulos) {
      if (art.bl === 1) continue;
      if (tokens.length > 0) {
        if (paddedTerm && art.c === paddedTerm) {
          matches.unshift(art);
          continue;
        }
        const codeStr = String(art.c || '').toLowerCase();
        const nameStr = String(art.n || '').toLowerCase();
        const cfStr = String(art.cf || '').toLowerCase();
        const bcJoined = Array.isArray(art.bc) ? art.bc.map((b) => String(b.c).toLowerCase()).join(' ') : '';
        const rubroObj = STATE.rubrosMap.get(Number(art.r));
        const provObj = STATE.proveedoresMap.get(Number(art.p));
        const rubName = rubroObj ? String(rubroObj.nombre || '').toLowerCase() : '';
        const provName = provObj ? String(provObj.nombre || '').toLowerCase() : '';
        const haystack = `${codeStr} ${nameStr} ${cfStr} ${bcJoined} ${rubName} ${provName}`;
        let allMatch = true;
        for (const tk of tokens) {
          if (!haystack.includes(tk)) {
            allMatch = false;
            break;
          }
        }
        if (!allMatch) continue;
      }
      matches.push(art);
      if (matches.length >= 40) break;
    }

    if (statusEl) {
      statusEl.textContent = q
        ? `Mostrando ${matches.length} coincidencia(s) para "${rawQuery.trim()}"`
        : `Mostrando primeros ${matches.length} productos activos (escribí arriba para filtrar):`;
    }

    tbody.textContent = '';
    if (matches.length === 0) {
      const tr = document.createElement('tr');
      const td = document.createElement('td');
      td.colSpan = 4;
      td.className = 'table-loading-cell';
      td.textContent = 'No se encontraron productos existentes con esa búsqueda.';
      tr.appendChild(td);
      tbody.appendChild(tr);
      return;
    }

    const frag = document.createDocumentFragment();
    matches.forEach((art) => {
      const tr = document.createElement('tr');

      const tdArt = document.createElement('td');
      const stackArt = document.createElement('div');
      stackArt.className = 'price-cell-stack';
      const codePill = document.createElement('span');
      codePill.className = 'art-code-pill';
      codePill.textContent = `#${art.c}`;
      const nameStrong = document.createElement('strong');
      nameStrong.className = 'art-title-text';
      nameStrong.style.cursor = 'pointer';
      nameStrong.title = 'Hacé clic para editar la ficha de este artículo';
      nameStrong.textContent = art.n;
      nameStrong.addEventListener('click', () => {
        STATE.pendingFactMissingBarcodeContext = { ...lastMissingBarcodeState };
        document.getElementById('fact-missing-barcode-dialog')?.close();
        openArticleModal(art, !sc && missingCode ? { appendBarcode: missingCode } : {});
      });
      stackArt.appendChild(codePill);
      stackArt.appendChild(nameStrong);
      tdArt.appendChild(stackArt);
      tr.appendChild(tdArt);

      const tdRubProv = document.createElement('td');
      const rubroObj = STATE.rubrosMap.get(Number(art.r));
      const provObj = STATE.proveedoresMap.get(Number(art.p));
      tdRubProv.innerHTML = `<div class="price-cell-stack"><strong style="font-size:0.78rem;">${escapeHtml(rubroObj ? rubroObj.nombre : 'Sin rubro')}</strong><span class="price-neto-val">${escapeHtml(provObj ? provObj.nombre : 'Sin proveedor')}</span></div>`;
      tr.appendChild(tdRubProv);

      const tdPriceSt = document.createElement('td');
      tdPriceSt.innerHTML = `<div class="price-cell-stack"><span class="price-final-val">$ ${formatArs(art.p1f)}</span><span class="price-neto-val">Stock: ${art.sf ?? 0}</span></div>`;
      tr.appendChild(tdPriceSt);

      const tdAct = document.createElement('td');
      const actWrap = document.createElement('div');
      actWrap.style.display = 'flex';
      actWrap.style.gap = '0.35rem';
      actWrap.style.flexWrap = 'wrap';
      actWrap.style.alignItems = 'center';

      const btnDup = document.createElement('button');
      btnDup.type = 'button';
      btnDup.className = mode === 'duplicate' ? 'btn-primary btn-sm' : 'btn-secondary btn-sm';
      btnDup.style.width = 'auto';
      btnDup.textContent = '📋 Duplicar con este Código';
      btnDup.title = `Duplicar "${art.n}" pre-cargando el código "${missingCode}"`;
      btnDup.addEventListener('click', () => {
        STATE.pendingFactMissingBarcodeContext = { ...lastMissingBarcodeState };
        document.getElementById('fact-missing-barcode-dialog')?.close();
        openDuplicateArticleModal(
          art,
          sc && !sc.art && sc.artCode5
            ? { prefillScaleCode5: sc.artCode5 }
            : { prefillBarcode: missingCode }
        );
      });

      const btnAssocAndBill = document.createElement('button');
      btnAssocAndBill.type = 'button';
      btnAssocAndBill.className = mode === 'duplicate' ? 'btn-secondary btn-sm' : 'btn-primary btn-sm';
      btnAssocAndBill.style.width = 'auto';
      btnAssocAndBill.textContent = !sc && missingCode ? '🔗 Asociar Código y Facturar' : '✓ Facturar Producto';
      btnAssocAndBill.title = !sc && missingCode
        ? `Guardar el código de barras "${missingCode}" en #${art.c} (${art.n}) y cargarlo al comprobante`
        : `Cargar #${art.c} (${art.n}) al comprobante`;
      btnAssocAndBill.addEventListener('click', () => {
        associateMissingBarcodeToExistingArticleAndBill(art);
      });

      const btnJustBill = document.createElement('button');
      btnJustBill.type = 'button';
      btnJustBill.className = 'btn-secondary btn-sm';
      btnJustBill.style.width = 'auto';
      btnJustBill.textContent = '✓ Solo Facturar';
      btnJustBill.title = `Cargar #${art.c} (${art.n}) al comprobante sin modificar sus códigos`;
      btnJustBill.addEventListener('click', () => {
        STATE.pendingFactMissingBarcodeContext = null;
        document.getElementById('fact-missing-barcode-dialog')?.close();
        hideFactMissingBarcodeAlert();
        addArticleToInvoice(art, getMissingBarcodeEffectiveInvoiceQty());
      });

      const btnEdit = document.createElement('button');
      btnEdit.type = 'button';
      btnEdit.className = 'btn-secondary btn-sm';
      btnEdit.style.width = 'auto';
      btnEdit.textContent = '✏️ Editar';
      btnEdit.title = `Abrir ficha de #${art.c} (${art.n}) con el código "${missingCode}" pre-agregado`;
      btnEdit.addEventListener('click', () => {
        STATE.pendingFactMissingBarcodeContext = { ...lastMissingBarcodeState };
        document.getElementById('fact-missing-barcode-dialog')?.close();
        openArticleModal(art, !sc && missingCode ? { appendBarcode: missingCode } : {});
      });

      if (mode === 'duplicate') {
        actWrap.appendChild(btnDup);
        actWrap.appendChild(btnAssocAndBill);
        if (!sc && missingCode) actWrap.appendChild(btnJustBill);
        actWrap.appendChild(btnEdit);
      } else {
        actWrap.appendChild(btnAssocAndBill);
        actWrap.appendChild(btnDup);
        if (!sc && missingCode) actWrap.appendChild(btnJustBill);
        actWrap.appendChild(btnEdit);
      }

      tdAct.appendChild(actWrap);
      tr.appendChild(tdAct);
      frag.appendChild(tr);
    });

    tbody.appendChild(frag);
  }

  function openFactMissingBcSearchPanel(mode = 'search') {
    factMissingBcSearchMode = mode === 'duplicate' ? 'duplicate' : 'search';
    const dialog = document.getElementById('fact-missing-barcode-dialog');
    const searchPanel = document.getElementById('fact-missing-bc-search-panel');
    const searchInp = document.getElementById('fact-missing-bc-search-input');
    const modeTitle = document.getElementById('fact-missing-bc-search-mode-title');
    const missingCode = String(lastMissingBarcodeState.code || '').trim();

    if (dialog) {
      dialog.style.maxInlineSize = '880px';
      if (!dialog.open && typeof dialog.showModal === 'function') {
        dialog.showModal();
      }
    }
    if (modeTitle) {
      modeTitle.textContent =
        factMissingBcSearchMode === 'duplicate'
          ? `📋 Buscá el Producto Existente para Duplicarlo con el Código "${missingCode}"`
          : `🔍 Buscá un Producto Existente (Asociar Código "${missingCode}", Facturar o Duplicar)`;
    }
    if (searchPanel) {
      searchPanel.hidden = false;
    }
    renderFactMissingBcSearchResults(searchInp ? searchInp.value : '', factMissingBcSearchMode);
    requestAnimationFrame(() => {
      if (searchInp) {
        searchInp.focus();
        searchInp.select();
      }
    });
  }

  window.refreshFacturacionAfterMissingBarcodeSave = (savedArt) => {
    if (!STATE.pendingFactMissingBarcodeContext || !savedArt) return;
    const ctx = STATE.pendingFactMissingBarcodeContext;
    STATE.pendingFactMissingBarcodeContext = null;
    hideFactMissingBarcodeAlert();
    const sc = ctx.scaleInfo;
    const baseQty = sc && sc.valueDecoded > 0 ? sc.valueDecoded : 1;
    const mult = Number(ctx.effectiveMult) > 0 ? Number(ctx.effectiveMult) : 1;
    addArticleToInvoice(savedArt, baseQty * mult);
  };

  document.getElementById('btn-close-fact-missing-bc')?.addEventListener('click', closeMissingBarcodeDialogAndRefocus);
  document.getElementById('btn-fact-missing-bc-ok')?.addEventListener('click', closeMissingBarcodeDialogAndRefocus);
  document.getElementById('btn-fact-alert-dismiss')?.addEventListener('click', () => {
    hideFactMissingBarcodeAlert();
    focusFirstCodeInput();
  });
  document.getElementById('btn-fact-missing-bc-enable-frac')?.addEventListener('click', handleEnableFractionableFromScaleAlert);
  document.getElementById('btn-fact-alert-enable-frac')?.addEventListener('click', handleEnableFractionableFromScaleAlert);
  document.getElementById('btn-fact-missing-bc-search')?.addEventListener('click', () => openFactMissingBcSearchPanel('search'));
  document.getElementById('btn-fact-alert-search-art')?.addEventListener('click', () => openFactMissingBcSearchPanel('search'));
  document.getElementById('btn-fact-missing-bc-duplicate')?.addEventListener('click', () => openFactMissingBcSearchPanel('duplicate'));
  document.getElementById('btn-fact-alert-dup-art')?.addEventListener('click', () => openFactMissingBcSearchPanel('duplicate'));
  document.getElementById('fact-missing-bc-search-input')?.addEventListener('input', (e) => {
    renderFactMissingBcSearchResults(e.target.value, factMissingBcSearchMode);
  });
  document.getElementById('btn-fact-missing-bc-create')?.addEventListener('click', handleCreateArticleFromMissingBarcodeAlert);
  document.getElementById('btn-fact-alert-new-art')?.addEventListener('click', handleCreateArticleFromMissingBarcodeAlert);
  document.getElementById('fact-missing-barcode-dialog')?.addEventListener('close', () => {
    if (factFirstCodeInput && !document.getElementById('article-dialog')?.open && !document.getElementById('duplicate-search-dialog')?.open) {
      factFirstCodeInput.focus();
      factFirstCodeInput.select();
    }
  });

  function renderFactSuggestions(rawSearch, previewMultiplier = null) {
    if (!factSuggestionsBox) return;
    const cleanRaw = String(rawSearch || '').trim();
    const term = normalizeStr(cleanRaw);
    if (!term) {
      factSuggestionsBox.hidden = true;
      return;
    }

    const scaleSugInfo = parseScaleBarcode(cleanRaw);
    const scaleMatchedArt =
      scaleSugInfo && scaleSugInfo.art && scaleSugInfo.isFractionableArt ? scaleSugInfo.art : null;

    const tokens = term.split(/\s+/).filter(Boolean);
    const paddedTerm = /^\d+$/.test(cleanRaw) && cleanRaw.length <= 5
      ? cleanRaw.padStart(5, '0')
      : '';

    factSugMatches = STATE.articulos
      .filter((a) => {
        if (a.bl === 1) return false;
        if (scaleMatchedArt && a.id === scaleMatchedArt.id) return true;
        if (paddedTerm && a.c === paddedTerm) return true;
        const bcStr = Array.isArray(a.bc) ? a.bc.map((b) => b.c).join(' ') : '';
        const hay = normalizeStr(`${a.c} ${a.n} ${bcStr} ${a.cf || ''}`);
        return tokens.every((tk) => hay.includes(tk));
      })
      .slice(0, 20);

    // Put scale barcode or exact code match first
    if (scaleMatchedArt) {
      factSugMatches.sort((a, b) => (a.id === scaleMatchedArt.id ? -1 : b.id === scaleMatchedArt.id ? 1 : 0));
    } else if (paddedTerm) {
      factSugMatches.sort((a, b) => (a.c === paddedTerm ? -1 : b.c === paddedTerm ? 1 : 0));
    }

    if (factSugMatches.length === 0) {
      factSuggestionsBox.hidden = true;
      return;
    }

    factSugIndex = 0;
    factSuggestionsBox.textContent = '';

    // Posicionar la ventana emergente flotante debajo de la 1° línea de carga (y acotada para monitores chicos)
    const entryRowEl = document.getElementById('fact-entry-row');
    if (entryRowEl) {
      const rect = entryRowEl.getBoundingClientRect();
      const maxTop = Math.max(58, window.innerHeight - 430);
      const idealTop = Math.max(58, Math.min(Math.round(rect.bottom + 6), maxTop));
      factSuggestionsBox.style.top = `${idealTop}px`;
    }

    const baseMult = previewMultiplier || STATE.factActiveMultiplier || 1;
    const scaleQty =
      scaleMatchedArt && scaleSugInfo.valueDecoded > 0 ? scaleSugInfo.valueDecoded : null;
    const effMult = scaleQty !== null ? Math.round(baseMult * scaleQty * 1000) / 1000 : baseMult;

    // Preview first match in entry row
    const topArt = factSugMatches[0];
    const topPrice = getArticleUnitPriceForActiveList(topArt);
    const topPreviewTotal = scaleMatchedArt && topArt.id === scaleMatchedArt.id
      ? Math.round(topPrice * effMult)
      : round2(topPrice * effMult);
    document.getElementById('fact-entry-preview-price').textContent = formatArs4(topPrice);
    document.getElementById('fact-entry-preview-total').textContent = formatArs(topPreviewTotal);
    document.getElementById('fact-entry-preview-stock').textContent = String(topArt.sf ?? 0);

    // Cabecera de la ventana emergente de búsqueda
    const headerEl = document.createElement('div');
    headerEl.className = 'fact-sug-modal-header';
    headerEl.innerHTML = `
      <div class="fact-sug-modal-title">
        <span>🔎 Buscador de Artículos</span>
        <span class="badge badge--gold" style="font-size:0.75rem;">"${escapeHtml(cleanRaw.toUpperCase())}" · ${factSugMatches.length} coincidencia(s)</span>
      </div>
      <div class="fact-sug-modal-actions">
        <span>↑/↓ Elegir · Enter Cargar · Esc Cerrar</span>
        <button type="button" class="fact-sug-modal-close" title="Cerrar ventana de búsqueda (Esc)">✕ Cerrar</button>
      </div>
    `;
    headerEl.querySelector('.fact-sug-modal-close')?.addEventListener('mousedown', (e) => {
      e.preventDefault();
      factSuggestionsBox.hidden = true;
      focusFirstCodeInput();
    });
    factSuggestionsBox.appendChild(headerEl);

    const listEl = document.createElement('div');
    listEl.className = 'fact-sug-modal-list';

    factSugMatches.forEach((art, idx) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'fact-sug-item' + (idx === factSugIndex ? ' is-highlighted' : '');
      btn.setAttribute('role', 'option');

      const price = getArticleUnitPriceForActiveList(art);
      const isThisScaleArt = Boolean(scaleMatchedArt && art.id === scaleMatchedArt.id);
      const allowSugFrac = isThisScaleArt || doesArticleAllowFraction(art);
      const rawSugQty = isThisScaleArt ? effMult : baseMult;
      const itemQty = allowSugFrac ? rawSugQty : Math.max(1, Math.round(rawSugQty));
      const itemLineTotal = isThisScaleArt ? Math.round(price * itemQty) : round2(price * itemQty);
      const mainBc = isThisScaleArt
        ? `⚖️ Balanza PLU ${art.c}: ${scaleQty.toFixed(3)} kg`
        : (Array.isArray(art.bc) && art.bc.length > 0
          ? art.bc[0].c
          : (art.fr === 1 ? `⚖️ 21${art.c}... / 23${art.c}...` : 'S/EAN'));

      const left = document.createElement('div');
      left.style.display = 'flex';
      left.style.alignItems = 'center';
      left.style.gap = '0.55rem';
      left.innerHTML = `<span class="art-code-pill">#${art.c}</span><strong>${art.n}</strong><span class="price-neto-val">(${mainBc})</span>`;

      const right = document.createElement('div');
      right.style.display = 'flex';
      right.style.alignItems = 'center';
      right.style.gap = '0.75rem';
      right.innerHTML = `<span class="price-neto-val">Stock: ${art.sf ?? 0}</span><span class="price-final-val">${itemQty !== 1 ? `${itemQty.toLocaleString('es-AR', { minimumFractionDigits: isThisScaleArt ? 3 : 0, maximumFractionDigits: 3 })}${isThisScaleArt ? ' kg' : 'x'} = $ ${formatArs(itemLineTotal)}` : `$ ${formatArs(price)}`}</span>`;

      btn.appendChild(left);
      btn.appendChild(right);

      btn.addEventListener('mousedown', (e) => {
        e.preventDefault();
        hideFactMissingBarcodeAlert();
        addArticleToInvoice(art, itemQty, {
          isScaleTicket: isThisScaleArt,
          scaleInfo: isThisScaleArt ? scaleSugInfo : null
        });
      });

      listEl.appendChild(btn);
    });

    factSuggestionsBox.appendChild(listEl);
    factSuggestionsBox.hidden = false;
  }

  if (factFirstCodeInput) {
    factFirstCodeInput.addEventListener('input', () => {
      const val = factFirstCodeInput.value;
      // Si el usuario escribe "2x " o "3,x " con espacio al final, fijar el multiplicador inmediatamente
      const spaceMult = val.match(/^(\d+(?:[.,]\d+)?)\s*,?\s*[xX*]\s+$/);
      if (spaceMult) {
        const m = parseFloat(spaceMult[1].replace(',', '.'));
        if (isFinite(m) && m > 0 && m <= 9999) {
          setFactMultiplier(m);
          factFirstCodeInput.value = '';
          factSuggestionsBox.hidden = true;
          return;
        }
      }

      const parsed = parseFactCodeExpression(val);
      if (parsed.onlyMultiplier) {
        factSuggestionsBox.hidden = true;
        return;
      }
      renderFactSuggestions(parsed.term, parsed.multiplier);
    });

    factFirstCodeInput.addEventListener('keydown', (event) => {
      if (
        (event.key === 'Backspace' || event.key === 'Delete') &&
        STATE.factActiveMultiplier !== 1 &&
        (factFirstCodeInput.value === '' ||
          (event.key === 'Backspace' &&
            factFirstCodeInput.selectionStart === 0 &&
            factFirstCodeInput.selectionEnd === 0))
      ) {
        event.preventDefault();
        setFactMultiplier(1);
        return;
      }
      if (event.key === 'ArrowDown' && factSuggestionsBox && !factSuggestionsBox.hidden) {
        event.preventDefault();
        const items = factSuggestionsBox.querySelectorAll('.fact-sug-item');
        if (items.length > 0) {
          factSugIndex = (factSugIndex + 1) % items.length;
          items.forEach((el, i) => el.classList.toggle('is-highlighted', i === factSugIndex));
          items[factSugIndex]?.scrollIntoView({ block: 'nearest' });
        }
        return;
      }
      if (event.key === 'ArrowUp' && factSuggestionsBox && !factSuggestionsBox.hidden) {
        event.preventDefault();
        const items = factSuggestionsBox.querySelectorAll('.fact-sug-item');
        if (items.length > 0) {
          factSugIndex = (factSugIndex - 1 + items.length) % items.length;
          items.forEach((el, i) => el.classList.toggle('is-highlighted', i === factSugIndex));
          items[factSugIndex]?.scrollIntoView({ block: 'nearest' });
        }
        return;
      }
      if (event.key === 'Escape') {
        event.preventDefault();
        setFactMultiplier(1);
        factFirstCodeInput.value = '';
        if (factSuggestionsBox) factSuggestionsBox.hidden = true;
        return;
      }
      if (event.key === 'Enter') {
        event.preventDefault();
        // IME-safe Enter check (modern-web-guidance: ime-safe-enter-submit)
        if (event.isComposing || event.keyCode === 229) {
          return;
        }

        const rawVal = factFirstCodeInput.value.trim();
        if (!rawVal) return;

        const parsed = parseFactCodeExpression(rawVal);

        // Si escribió únicamente "2x", "3x", "4x", "3,x" y presionó Enter:
        if (parsed.onlyMultiplier && parsed.multiplier) {
          setFactMultiplier(parsed.multiplier);
          factFirstCodeInput.value = '';
          if (factSuggestionsBox) factSuggestionsBox.hidden = true;
          focusFirstCodeInput();
          return;
        }

        const effectiveMult = parsed.multiplier !== null
          ? parsed.multiplier
          : (Number(STATE.factActiveMultiplier) !== 1
            ? Number(STATE.factActiveMultiplier)
            : (parseFloat(factFirstQtyInput?.value || '1') || 1));

        // 1. Buscar coincidencia exacta por Código de Producto (00001-99999), Código de Balanza PLU (21/23) o Código de Barras
        const exactHit = findArticleByCodeOrBarcode(parsed.term);
        if (exactHit && exactHit.art) {
          hideFactMissingBarcodeAlert();
          const scaleMult = exactHit.isScaleBarcode
            ? (parsed.multiplier !== null
              ? parsed.multiplier
              : (Number(STATE.factActiveMultiplier) !== 1 ? Number(STATE.factActiveMultiplier) : 1))
            : effectiveMult;
          addArticleToInvoice(exactHit.art, scaleMult * exactHit.barcodeQty, {
            isScaleTicket: Boolean(exactHit.isScaleBarcode),
            scaleInfo: exactHit.scaleInfo || null
          });
          return;
        }

        // Si es un código de balanza cuyo artículo no tiene habilitado "Permitir fraccionamiento", o un código de barras numérico que no existe en el sistema:
        const isNumericBarcodeScan = /^\d{6,}$/.test(sanitizeScannerBarcode(parsed.term));
        if (exactHit?.scaleBlockedArt || isNumericBarcodeScan) {
          if (factSuggestionsBox) factSuggestionsBox.hidden = true;
          triggerFactMissingBarcodeAlert(parsed.term, exactHit?.scaleInfo || null, effectiveMult);
          return;
        }

        // 2. Si no era un código de barras numérico y hay sugerencia resaltada en el desplegable
        if (factSuggestionsBox && !factSuggestionsBox.hidden && factSugMatches[factSugIndex]) {
          hideFactMissingBarcodeAlert();
          addArticleToInvoice(factSugMatches[factSugIndex], effectiveMult);
          return;
        }

        triggerFactMissingBarcodeAlert(parsed.term, exactHit?.scaleInfo || null, effectiveMult);
      }
    });

    // Captura global de lector de código de barras USB en Facturación cuando el foco no está en un input editable ni hay modales abiertos
    document.addEventListener('keydown', (e) => {
      const posSec = document.getElementById('sec-caja-pos');
      if (!posSec || posSec.hidden || !factFirstCodeInput) return;
      if (document.querySelector('dialog[open]')) return;
      const active = document.activeElement;
      if (
        active &&
        (active.tagName === 'INPUT' ||
          active.tagName === 'TEXTAREA' ||
          active.tagName === 'SELECT' ||
          active.isContentEditable)
      ) {
        return;
      }
      if (e.ctrlKey || e.altKey || e.metaKey) return;
      if (/^[0-9xX*]$/.test(e.key)) {
        factFirstCodeInput.focus();
      }
    });
  }

  // Búsqueda por nombre en la celda "Artículo" de la 1° línea
  if (factFirstArtInput) {
    factFirstArtInput.addEventListener('input', () => {
      const parsed = parseFactCodeExpression(factFirstArtInput.value);
      renderFactSuggestions(parsed.term, parsed.multiplier);
    });
    factFirstArtInput.addEventListener('keydown', (event) => {
      if (
        (event.key === 'Backspace' || event.key === 'Delete') &&
        STATE.factActiveMultiplier !== 1 &&
        factFirstArtInput.value === ''
      ) {
        event.preventDefault();
        setFactMultiplier(1);
        return;
      }
      if (event.key === 'Escape') {
        event.preventDefault();
        setFactMultiplier(1);
        factFirstArtInput.value = '';
        if (factSuggestionsBox) factSuggestionsBox.hidden = true;
        return;
      }
      if (event.key === 'ArrowDown' && factSuggestionsBox && !factSuggestionsBox.hidden) {
        event.preventDefault();
        const items = factSuggestionsBox.querySelectorAll('.fact-sug-item');
        if (items.length > 0) {
          factSugIndex = (factSugIndex + 1) % items.length;
          items.forEach((el, i) => el.classList.toggle('is-highlighted', i === factSugIndex));
          items[factSugIndex]?.scrollIntoView({ block: 'nearest' });
        }
        return;
      }
      if (event.key === 'ArrowUp' && factSuggestionsBox && !factSuggestionsBox.hidden) {
        event.preventDefault();
        const items = factSuggestionsBox.querySelectorAll('.fact-sug-item');
        if (items.length > 0) {
          factSugIndex = (factSugIndex - 1 + items.length) % items.length;
          items.forEach((el, i) => el.classList.toggle('is-highlighted', i === factSugIndex));
          items[factSugIndex]?.scrollIntoView({ block: 'nearest' });
        }
        return;
      }
      if (event.key === 'Enter') {
        event.preventDefault();
        if (event.isComposing || event.keyCode === 229) {
          return;
        }
        const parsed = parseFactCodeExpression(factFirstArtInput.value);
        if (!parsed.term) return;
        const effMult = parsed.multiplier || STATE.factActiveMultiplier || 1;
        const exactHit = findArticleByCodeOrBarcode(parsed.term);
        if (exactHit && exactHit.art) {
          hideFactMissingBarcodeAlert();
          addArticleToInvoice(exactHit.art, effMult * exactHit.barcodeQty, {
            isScaleTicket: Boolean(exactHit.isScaleBarcode),
            scaleInfo: exactHit.scaleInfo || null
          });
          return;
        }
        const isNumericBarcodeScan = /^\d{6,}$/.test(sanitizeScannerBarcode(parsed.term));
        if (!isNumericBarcodeScan && factSuggestionsBox && !factSuggestionsBox.hidden && factSugMatches[factSugIndex]) {
          hideFactMissingBarcodeAlert();
          addArticleToInvoice(factSugMatches[factSugIndex], effMult);
          return;
        }
        triggerFactMissingBarcodeAlert(parsed.term, exactHit?.scaleInfo || null, effMult);
      }
    });
  }

  // Cerrar ventana emergente de búsqueda de artículos al hacer clic fuera de ella
  document.addEventListener('mousedown', (e) => {
    if (!factSuggestionsBox || factSuggestionsBox.hidden) return;
    const t = e.target;
    if (
      t &&
      !factSuggestionsBox.contains(t) &&
      t !== factFirstCodeInput &&
      t !== factFirstArtInput
    ) {
      factSuggestionsBox.hidden = true;
    }
  });

  // Botones rápidos de multiplicador (2x, 3x, 4x, 6x, 12x), botón Quitar y badges en línea
  document.querySelectorAll('.btn-mult-chip[data-mult]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const m = Number(btn.getAttribute('data-mult')) || 1;
      setFactMultiplier(STATE.factActiveMultiplier === m ? 1 : m);
      focusFirstCodeInput();
    });
  });

  document.getElementById('btn-clear-mult-chip')?.addEventListener('click', () => {
    setFactMultiplier(1);
    focusFirstCodeInput();
  });

  document.getElementById('fact-inline-mult-badge')?.addEventListener('click', () => {
    setFactMultiplier(1);
    focusFirstCodeInput();
  });

  document.getElementById('fact-active-mult-pill')?.addEventListener('click', () => {
    setFactMultiplier(1);
    focusFirstCodeInput();
  });

  document.getElementById('btn-clear-entry-row')?.addEventListener('click', () => {
    setFactMultiplier(1);
    if (factFirstCodeInput) factFirstCodeInput.value = '';
    if (factFirstArtInput) factFirstArtInput.value = '';
    if (factSuggestionsBox) factSuggestionsBox.hidden = true;
    const prevPrice = document.getElementById('fact-entry-preview-price');
    const prevTotal = document.getElementById('fact-entry-preview-total');
    const prevStock = document.getElementById('fact-entry-preview-stock');
    if (prevPrice) prevPrice.textContent = '0,0000';
    if (prevTotal) prevTotal.textContent = '0,00';
    if (prevStock) prevStock.textContent = '—';
    focusFirstCodeInput();
  });

  if (factFirstQtyInput) {
    factFirstQtyInput.addEventListener('change', () => {
      const v = parseFloat(factFirstQtyInput.value);
      setFactMultiplier(isFinite(v) && v > 0 ? v : 1);
    });
  }

  // Selector de Cliente en Cabecera de Facturación (por código o nombre/CUIT)
  const factCliCodeInp = document.getElementById('fact-cli-codigo');
  const factCliNameInp = document.getElementById('pos-cliente-input');
  const factCliDropdown = document.getElementById('fact-cli-dropdown');

  if (factCliCodeInp) {
    const resolveFactClientByCodeOrQr = (rawCodeVal) => {
      const codeVal = String(rawCodeVal || '').trim();
      if (!codeVal) return null;
      const upper = codeVal.toUpperCase();
      if (upper.includes('CCN') || upper.includes('CPA') || upper.includes('FIDEL') || upper.includes('CACHITA') || upper.includes('PASEO')) {
        const qrMatches = findClientsMatchingDniOrName(codeVal);
        if (qrMatches[0]) return qrMatches[0];
      }
      return (
        STATE.clientes.find((c) => clientMatchesCodeOrAlias(c, codeVal)) ||
        STATE.clientes.find((c) => String(c.codigo) === codeVal) ||
        null
      );
    };
    factCliCodeInp.addEventListener('focus', () => {
      factCliCodeInp.select();
    });
    factCliCodeInp.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        if (event.isComposing || event.keyCode === 229) return;
        const found = resolveFactClientByCodeOrQr(factCliCodeInp.value);
        if (found) {
          selectClientForInvoice(found);
        }
      }
    });
    factCliCodeInp.addEventListener('blur', () => {
      const found = resolveFactClientByCodeOrQr(factCliCodeInp.value);
      if (found) {
        selectClientForInvoice(found);
      } else if (!String(factCliCodeInp.value || '').trim()) {
        const activeCli = getActiveFactClientObj();
        factCliCodeInp.value = String(activeCli?.codigo ?? 1);
      }
    });
  }

  if (factCliNameInp && factCliDropdown) {
    let factCliSugMatches = [];
    let factCliSugIndex = -1;

    const renderFactClientSuggestions = (rawVal) => {
      const q = normalizeStr(rawVal);
      if (!q || q === 'CONSUMIDOR FINAL') {
        factCliDropdown.hidden = true;
        factCliSugMatches = [];
        factCliSugIndex = -1;
        return;
      }
      const upper = rawVal.toUpperCase();
      const matches =
        upper.includes('CCN') || upper.includes('CPA') || upper.includes('FIDEL') || upper.includes('CACHITA') || upper.includes('PASEO')
          ? findClientsMatchingDniOrName(rawVal)
          : STATE.clientes
              .filter((c) => {
                const aliasStr = Array.isArray(c.aliasCodigos) ? c.aliasCodigos.join(' ') : '';
                return normalizeStr(`${c.codigo} ${aliasStr} ${c.nombre} ${c.razonSocial || ''} ${c.nroDoc || ''}`).includes(q);
              })
              .slice(0, 25);

      factCliSugMatches = matches;
      factCliSugIndex = matches.length > 0 ? 0 : -1;

      if (matches.length === 0) {
        factCliDropdown.hidden = true;
        return;
      }

      factCliDropdown.textContent = '';

      // Posicionar la ventana emergente flotante debajo del buscador de clientes
      const rect = factCliNameInp.getBoundingClientRect();
      const maxTop = Math.max(58, window.innerHeight - 430);
      const idealTop = Math.max(58, Math.min(Math.round(rect.bottom + 6), maxTop));
      factCliDropdown.style.top = `${idealTop}px`;

      const headerEl = document.createElement('div');
      headerEl.className = 'fact-sug-modal-header';
      headerEl.innerHTML = `
        <div class="fact-sug-modal-title">
          <span>👤 Buscador de Clientes</span>
          <span class="badge badge--gold" style="font-size:0.75rem;">"${escapeHtml(rawVal.toUpperCase())}" · ${matches.length} coincidencia(s)</span>
        </div>
        <div class="fact-sug-modal-actions">
          <span>↑/↓ Elegir · Enter Seleccionar · Esc Cerrar</span>
          <button type="button" class="fact-sug-modal-close" title="Cerrar ventana de búsqueda (Esc)">✕ Cerrar</button>
        </div>
      `;
      headerEl.querySelector('.fact-sug-modal-close')?.addEventListener('mousedown', (e) => {
        e.preventDefault();
        factCliDropdown.hidden = true;
        factCliNameInp.focus();
      });
      factCliDropdown.appendChild(headerEl);

      const listEl = document.createElement('div');
      listEl.className = 'fact-sug-modal-list';

      matches.forEach((cli, idx) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'fact-sug-item' + (idx === factCliSugIndex ? ' is-highlighted' : '');
        btn.setAttribute('role', 'option');

        const left = document.createElement('div');
        left.style.display = 'flex';
        left.style.alignItems = 'center';
        left.style.gap = '0.55rem';
        const rsDiff = cli.razonSocial && cli.razonSocial !== cli.nombre ? `<span class="price-neto-val">(${escapeHtml(cli.razonSocial)})</span>` : '';
        left.innerHTML = `<span class="art-code-pill">#${cli.codigo}</span><strong>${escapeHtml(cli.nombre)}</strong>${rsDiff}`;

        const right = document.createElement('div');
        right.style.display = 'flex';
        right.style.alignItems = 'center';
        right.style.gap = '0.75rem';
        right.innerHTML = `<span class="price-neto-val">${escapeHtml(cli.nroDoc || '00.000.000')} (${escapeHtml(cli.respIva || 'Consumidor Final')})</span><span class="price-final-val" style="font-size:0.78rem;">${escapeHtml(cli.listaPrecios || 'MINORISTA')}${cli.habilitaCtaCte ? ' · Cta. Cte.' : ''}</span>`;

        btn.appendChild(left);
        btn.appendChild(right);

        btn.addEventListener('mousedown', (e) => {
          e.preventDefault();
          factCliDropdown.hidden = true;
          selectClientForInvoice(cli);
        });
        listEl.appendChild(btn);
      });

      factCliDropdown.appendChild(listEl);
      factCliDropdown.hidden = false;
    };

    const clearConsumidorFinalOnFocus = () => {
      const val = String(factCliNameInp.value || '').trim().toUpperCase();
      if (val === 'CONSUMIDOR FINAL') {
        factCliNameInp.value = '';
      } else if (val) {
        factCliNameInp.select();
      }
    };
    factCliNameInp.addEventListener('focus', clearConsumidorFinalOnFocus);
    factCliNameInp.addEventListener('click', () => {
      if (String(factCliNameInp.value || '').trim().toUpperCase() === 'CONSUMIDOR FINAL') {
        factCliNameInp.value = '';
      }
    });

    factCliNameInp.addEventListener('input', () => {
      renderFactClientSuggestions(factCliNameInp.value.trim());
    });

    factCliNameInp.addEventListener('keydown', (event) => {
      if (
        event.key &&
        event.key.length === 1 &&
        !event.ctrlKey &&
        !event.metaKey &&
        !event.altKey &&
        String(factCliNameInp.value || '').trim().toUpperCase() === 'CONSUMIDOR FINAL'
      ) {
        factCliNameInp.value = '';
      }
      if (event.key === 'Escape') {
        if (!factCliDropdown.hidden) {
          event.preventDefault();
          factCliDropdown.hidden = true;
        }
        return;
      }
      if (event.key === 'ArrowDown') {
        if (!factCliDropdown.hidden && factCliSugMatches.length > 0) {
          event.preventDefault();
          const items = factCliDropdown.querySelectorAll('.fact-sug-item');
          factCliSugIndex = (factCliSugIndex + 1) % items.length;
          items.forEach((el, i) => el.classList.toggle('is-highlighted', i === factCliSugIndex));
          items[factCliSugIndex]?.scrollIntoView({ block: 'nearest' });
        }
        return;
      }
      if (event.key === 'ArrowUp') {
        if (!factCliDropdown.hidden && factCliSugMatches.length > 0) {
          event.preventDefault();
          const items = factCliDropdown.querySelectorAll('.fact-sug-item');
          factCliSugIndex = (factCliSugIndex - 1 + items.length) % items.length;
          items.forEach((el, i) => el.classList.toggle('is-highlighted', i === factCliSugIndex));
          items[factCliSugIndex]?.scrollIntoView({ block: 'nearest' });
        }
        return;
      }
      if (event.key === 'Enter') {
        if (event.isComposing || event.keyCode === 229) return;
        const rawVal = factCliNameInp.value.trim();
        const upper = rawVal.toUpperCase();
        if (upper.includes('CCN') || upper.includes('CPA') || upper.includes('FIDEL') || upper.includes('CACHITA') || upper.includes('PASEO')) {
          event.preventDefault();
          const qrMatches = findClientsMatchingDniOrName(rawVal);
          if (qrMatches[0]) {
            factCliDropdown.hidden = true;
            selectClientForInvoice(qrMatches[0]);
            return;
          }
        }
        if (!factCliDropdown.hidden && factCliSugMatches[factCliSugIndex]) {
          event.preventDefault();
          const chosen = factCliSugMatches[factCliSugIndex];
          factCliDropdown.hidden = true;
          selectClientForInvoice(chosen);
          return;
        }
      }
    });

    factCliNameInp.addEventListener('blur', () => {
      setTimeout(() => {
        factCliDropdown.hidden = true;
        if (!String(factCliNameInp.value || '').trim()) {
          const activeCli = getActiveFactClientObj();
          factCliNameInp.value = String(activeCli?.nombre || 'CONSUMIDOR FINAL').toUpperCase();
        }
      }, 160);
    });

    document.addEventListener('mousedown', (e) => {
      if (factCliDropdown.hidden) return;
      const t = e.target;
      if (t && !factCliDropdown.contains(t) && t !== factCliNameInp && t !== factCliCodeInp) {
        factCliDropdown.hidden = true;
      }
    });
  }

  document.getElementById('btn-fact-new-client')?.addEventListener('click', () => {
    openClientModal(null);
  });
  document.getElementById('btn-fact-reset-cf')?.addEventListener('click', () => {
    const tipoCompEl = document.getElementById('pos-tipo-comp');
    if (tipoCompEl) tipoCompEl.value = 'Factura';
    const cfCli = STATE.clientes.find((c) => String(c.codigo) === '1');
    if (cfCli) selectClientForInvoice(cfCli);
    else resetInvoiceToDefaults();
  });

  // Cambios en Punto de Venta, Tipo Comprobante, Lista de Precios y Dto General
  document.getElementById('pos-select-pv')?.addEventListener('change', () => {
    const cfg = CAJAS_CONFIG[STATE.activeCajaId || 'caja1'];
    const tipoSel = document.getElementById('pos-tipo-comp');
    if (cfg && tipoSel) {
      if (!tipoSel.value || tipoSel.value === 'Comprobante Interno') {
        tipoSel.value = 'Factura';
      }
    }
    updateFactLetraAndNumber();
    focusFirstCodeInput();
  });
  document.getElementById('pos-tipo-comp')?.addEventListener('change', () => {
    const cfg = CAJAS_CONFIG[STATE.activeCajaId || 'caja1'];
    const pvSel = document.getElementById('pos-select-pv');
    const tipoVal = document.getElementById('pos-tipo-comp')?.value;
    if (cfg && pvSel) {
      if (tipoVal === 'Comprobante Interno') {
        pvSel.value = cfg.pvInterno;
      } else if (pvSel.value === cfg.pvInterno) {
        pvSel.value = cfg.pvFiscal;
      }
    }
    updateFactLetraAndNumber();
    focusFirstCodeInput();
  });
  document.getElementById('fact-lista-precio')?.addEventListener('change', () => {
    STATE.factItems.forEach((it) => {
      if (it.isGeneric || isGenericArticleCode(it.codigo)) return;
      const art = STATE.articulos.find((a) => a.id === it.artId);
      if (art) it.precioFinal = getArticleUnitPriceForActiveList(art);
    });
    renderFactItemsAndTotals();
    focusFirstCodeInput();
  });
  document.getElementById('fact-dto-pje')?.addEventListener('input', () => {
    renderFactItemsAndTotals();
  });
  document.getElementById('fact-vendedor')?.addEventListener('change', () => {
    renderFactItemsAndTotals();
    focusFirstCodeInput();
  });
  document.getElementById('pos-medio-pago')?.addEventListener('change', (e) => {
    const cli = getActiveFactClientObj();
    const alertEl = document.getElementById('fact-alert-msg');
    if (e.target.value === 'Cuenta Corriente' && !doesClientAllowCtaCte(cli)) {
      e.target.value = 'Contado';
      syncFactFormaPagoControl(cli, false);
      if (alertEl) {
        alertEl.textContent =
          '⚠️ Este cliente no tiene configurada la opción de Cuenta Corriente en el módulo de Clientes. Solo puede facturarse de Contado.';
        alertEl.hidden = false;
      }
    } else if (alertEl && alertEl.textContent.includes('Cuenta Corriente')) {
      alertEl.hidden = true;
    }
    focusFirstCodeInput();
  });

  // Pestañas Totales / Observación en el pie de Facturación
  document.querySelectorAll('.fact-tab-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      const tab = btn.getAttribute('data-fact-tab');
      document.querySelectorAll('.fact-tab-btn').forEach((b) => {
        const active = b === btn;
        b.classList.toggle('is-active', active);
        b.setAttribute('aria-selected', String(active));
      });
      document.getElementById('fact-tab-totales').hidden = tab !== 'totales';
      document.getElementById('fact-tab-observacion').hidden = tab !== 'observacion';
    });
  });

  // Botón Cancelar Comprobante
  document.getElementById('btn-fact-cancelar')?.addEventListener('click', () => {
    resetInvoiceToDefaults();
  });

  // =========================================================================
  // CIERRE DE VENTA PREDICTIVO (DETALLE DE PAGO + TICKET 78mm / REPORTE A4)
  // =========================================================================
  const POS_LAST_POSNET_KEY = 'cn_erp_pos_last_posnet_v1';
  const POS_CAJA_MOV_COUNTER_KEY = 'cn_erp_pos_caja_mov_counter_v1';

  let activeTicketSaleRecord = null;
  let ticketShouldAdvanceToNextSale = false;

  function parsePosMoneyInput(raw) {
    const s = String(raw ?? '').trim().replace(/\$/g, '').replace(/\s+/g, '');
    if (!s) return 0;
    let normalized = s;
    if (s.includes(',') && s.includes('.')) {
      normalized = s.replace(/\./g, '').replace(',', '.');
    } else if (s.includes(',')) {
      normalized = s.replace(',', '.');
    } else if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
      normalized = s.replace(/\./g, '');
    }
    const val = parseFloat(normalized);
    return isFinite(val) ? round2(Math.max(0, val)) : 0;
  }

  function formatArs4(num) {
    const n = Number(num) || 0;
    return n.toLocaleString('es-AR', {
      minimumFractionDigits: 4,
      maximumFractionDigits: 4
    });
  }

  function getCajaDiariaNumber(cajaId) {
    if (cajaId === 'caja2') return 2;
    if (cajaId === 'caja3') return 3;
    return 1;
  }

  function getNextCajaMovimientoNumber(cajaId, peekOnly = false) {
    const baseByCaja = { caja1: 1159, caja2: 412, caja3: 30 };
    let map = {};
    try {
      const raw = localStorage.getItem(POS_CAJA_MOV_COUNTER_KEY);
      if (raw) map = JSON.parse(raw) || {};
    } catch {}
    const current = Math.max(Number(map[cajaId]) || 0, baseByCaja[cajaId] || 1);
    const nextVal = current + 1;
    if (!peekOnly) {
      map[cajaId] = nextVal;
      try {
        localStorage.setItem(POS_CAJA_MOV_COUNTER_KEY, JSON.stringify(map));
      } catch {}
    }
    return nextVal;
  }

  function getSavedPosnetForCaja(cajaId) {
    try {
      const raw = localStorage.getItem(POS_LAST_POSNET_KEY);
      if (raw) {
        const map = JSON.parse(raw);
        if (map && map[cajaId]) return map[cajaId];
      }
    } catch {}
    return 'Mercado Pago';
  }

  function savePosnetForCaja(cajaId, posnetName) {
    if (!cajaId || !posnetName) return;
    try {
      const raw = localStorage.getItem(POS_LAST_POSNET_KEY);
      const map = raw ? JSON.parse(raw) || {} : {};
      map[cajaId] = posnetName;
      localStorage.setItem(POS_LAST_POSNET_KEY, JSON.stringify(map));
    } catch {}
  }

  // =========================================================================
  // INTEGRACIÓN MERCADO PAGO POINT SMART (ORDERS API v1 · CAJA 1 Y CAJA 2 ACTIVAS)
  // =========================================================================
  const MP_PRINT_TICKET_STORAGE_KEY = 'cn_erp_mp_print_ticket_v1';
  const MP_POINT_STATE = {
    loaded: false,
    pollingTimer: null,
    activeOrderId: null,
    activeOrderCajaId: null,
    waitingApproval: false,
    pendingFinalizeCallback: null,
    cajas: {
      caja1: {
        enabled: true,
        caja_nombre: 'Caja 1',
        terminal_id: 'NEWLAND_N950__N950NCC904940064',
        serial_short: '904940064',
        pos_id: 117470397,
        label: 'Point Smart Newland N950 (S/N ...904940064)',
        operating_mode: 'PDV'
      },
      caja2: {
        enabled: true,
        caja_nombre: 'Caja 2',
        terminal_id: 'NEWLAND_N950__N950NCC904472839',
        serial_short: '904472839',
        pos_id: 126563984,
        label: 'Point Smart Newland N950 (S/N ...904472839)',
        operating_mode: 'PDV'
      },
      caja3: {
        enabled: false,
        caja_nombre: 'Caja 3',
        terminal_id: '',
        serial_short: '',
        pos_id: 0,
        label: 'Sin terminal Point asignada',
        operating_mode: 'STANDALONE'
      }
    }
  };

  function getMpPrintTicketPref(cajaId) {
    try {
      const raw = JSON.parse(localStorage.getItem(MP_PRINT_TICKET_STORAGE_KEY) || '{}');
      return Boolean(raw && raw[cajaId]);
    } catch {
      return false;
    }
  }

  function saveMpPrintTicketPref(cajaId, val) {
    try {
      const raw = JSON.parse(localStorage.getItem(MP_PRINT_TICKET_STORAGE_KEY) || '{}');
      raw[cajaId] = Boolean(val);
      localStorage.setItem(MP_PRINT_TICKET_STORAGE_KEY, JSON.stringify(raw));
    } catch {}
  }

  function playMpApprovedChime() {
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;
      const ctx = new AudioCtx();
      const now = ctx.currentTime;
      [
        { freq: 659.25, offset: 0, dur: 0.12 },
        { freq: 880.0, offset: 0.13, dur: 0.2 }
      ].forEach((n) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(n.freq, now + n.offset);
        gain.gain.setValueAtTime(0.18, now + n.offset);
        gain.gain.exponentialRampToValueAtTime(0.001, now + n.offset + n.dur);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now + n.offset);
        osc.stop(now + n.offset + n.dur + 0.02);
      });
      setTimeout(() => {
        try {
          ctx.close();
        } catch {}
      }, 450);
    } catch {}
  }

  async function refreshMpPointServerStatus() {
    try {
      const res = await fetch(`api/mercadopago_point.php?action=status&_t=${Date.now()}`, {
        cache: 'no-store'
      });
      if (!res.ok) return;
      const json = await res.json();
      if (json && json.ok && json.cajas) {
        Object.keys(json.cajas).forEach((k) => {
          MP_POINT_STATE.cajas[k] = Object.assign({}, MP_POINT_STATE.cajas[k] || {}, json.cajas[k]);
        });
        MP_POINT_STATE.loaded = true;
        if (document.getElementById('pos-payment-dialog')?.open) {
          refreshPosPaymentModalUI(false);
        }
        if (document.getElementById('recibo-caja-preview-dialog')?.open && typeof window.__refreshReciboPreviewPaymentUI === 'function') {
          window.__refreshReciboPreviewPaymentUI();
        }
        if (document.getElementById('edit-comprobante-pago-dialog')?.open) {
          populateEditCompMpCajaSelect(getEditCompSelectedMpCajaId());
          refreshEditComprobantePagoModalUI();
        }
      }
    } catch {}
  }

