  function stopMpPointPolling(hideBox = false) {
    if (MP_POINT_STATE.pollingTimer) {
      clearInterval(MP_POINT_STATE.pollingTimer);
      MP_POINT_STATE.pollingTimer = null;
    }
    MP_POINT_STATE.waitingApproval = false;
    if (hideBox) {
      const boxPos = document.getElementById('pos-mp-live-order-box');
      if (boxPos) boxPos.hidden = true;
      const boxRec = document.getElementById('recibo-mp-live-order-box');
      if (boxRec) boxRec.hidden = true;
      const boxEdit = document.getElementById('edit-comp-mp-live-order-box');
      if (boxEdit) boxEdit.hidden = true;
      MP_POINT_STATE.activeOrderId = null;
      MP_POINT_STATE.activeOrderCajaId = null;
      MP_POINT_STATE.pendingFinalizeCallback = null;
    }
  }

  async function cancelActiveMpPointOrderOnServer(silent = false) {
    const orderId = MP_POINT_STATE.activeOrderId;
    const cajaId = MP_POINT_STATE.activeOrderCajaId || STATE.activeCajaId || 'caja1';
    stopMpPointPolling(false);
    if (!orderId && silent) return;

    const { liveBox: box, titleEl, detailEl, retryBtn, confirmBtn } = getMpPointLiveUiElements();

    if (!silent && titleEl) {
      titleEl.textContent = '⏳ Cancelando orden en el Posnet...';
    }
    try {
      await fetch('api/mercadopago_point.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'cancel_order',
          order_id: orderId || '',
          caja_id: cajaId
        })
      });
    } catch {}

    MP_POINT_STATE.activeOrderId = null;
    if (!silent) {
      if (titleEl) {
        titleEl.style.color = '#fca5a5';
        titleEl.textContent = '❌ Orden cancelada en el Posnet';
      }
      if (detailEl) {
        detailEl.textContent = 'Podés cambiar el medio de pago o presionar "Reenviar al Posnet" para intentarlo de nuevo.';
      }
      if (retryBtn) retryBtn.hidden = false;
      if (confirmBtn) confirmBtn.disabled = false;
    } else {
      if (box) box.hidden = true;
    }
  }

  function isMpPointIntegratedForCurrentSelection() {
    const cajaId = STATE.activeCajaId || 'caja1';
    const mpCaja = MP_POINT_STATE.cajas[cajaId];
    if (!mpCaja || !mpCaja.enabled || !mpCaja.terminal_id) return false;
    const method = getSelectedPosPayMethod();
    const usesPosnet = method === 'qr' || method === 'debito' || method === 'credito' || method === 'combinado';
    if (!usesPosnet) return false;
    if (getSelectedPosPayPosnet() !== 'Mercado Pago') return false;
    const manualBypass = Boolean(document.getElementById('pos-mp-manual-bypass-chk')?.checked);
    return !manualBypass;
  }

  function syncMpPointPanelUI(cajaId, usesPosnet, posnet, amountToSend, elecLabel) {
    const bar = document.getElementById('pos-mp-point-config-bar');
    const devDot = document.getElementById('pos-mp-device-dot');
    const devLbl = document.getElementById('pos-mp-device-label');
    const modeBadge = document.getElementById('pos-mp-mode-badge');
    const posnetSummary = document.getElementById('pos-pay-posnet-summary');

    const mpCaja = MP_POINT_STATE.cajas[cajaId];
    const showBar = Boolean(usesPosnet && posnet === 'Mercado Pago' && mpCaja && mpCaja.enabled && mpCaja.terminal_id);
    if (bar) {
      bar.hidden = !showBar;
    }
    if (!showBar) return;

    const isPdv = String(mpCaja.operating_mode || 'PDV').toUpperCase() === 'PDV';
    if (devDot) {
      devDot.style.background = isPdv ? '#22c55e' : '#f59e0b';
    }
    if (devLbl) {
      devLbl.textContent = `${mpCaja.caja_nombre} · Point Smart S/N ...${mpCaja.serial_short}`;
    }
    if (modeBadge) {
      modeBadge.textContent = isPdv ? 'MODO PDV INTEGRADO' : 'MODO MANUAL (STANDALONE)';
      modeBadge.style.background = isPdv ? 'rgba(34,197,94,0.18)' : 'rgba(245,158,11,0.2)';
      modeBadge.style.color = isPdv ? '#4ade80' : '#fbbf24';
    }

    const manualBypass = Boolean(document.getElementById('pos-mp-manual-bypass-chk')?.checked);
    if (posnetSummary) {
      if (manualBypass) {
        posnetSummary.textContent = `📝 Cobro manual seleccionado: tipeá $ ${formatArs(amountToSend)} en el Posnet y confirmá.`;
      } else {
        posnetSummary.textContent = `📲 Integrado en vivo: se enviarán $ ${formatArs(amountToSend)} (${elecLabel}) directo a la pantalla del Posnet S/N ...${mpCaja.serial_short}.`;
      }
    }
  }

  function buildPredictiveCashSuggestions(total) {
    const t = round2(total);
    if (t <= 0) return [];
    const candidates = new Set([t]);
    const steps = [100, 500, 1000, 2000, 5000, 10000, 20000, 50000, 100000];
    steps.forEach((step) => {
      const roundedUp = Math.ceil(t / step) * step;
      if (roundedUp > t) {
        candidates.add(roundedUp);
      }
    });
    // Agregar billetes redondos superiores habituales en caja
    [1000, 2000, 5000, 10000, 20000, 50000, 100000].forEach((bill) => {
      if (bill > t) candidates.add(bill);
    });
    return Array.from(candidates)
      .sort((a, b) => a - b)
      .slice(0, 6);
  }

  function getSelectedPosPayMethod() {
    return document.querySelector('input[name="pos_pay_method"]:checked')?.value || 'efectivo';
  }

  function getSelectedPosPayPosnet() {
    return document.querySelector('input[name="pos_pay_posnet"]:checked')?.value || 'Mercado Pago';
  }

  function getSelectedPosPayCombElec() {
    return document.querySelector('input[name="pos_pay_comb_elec"]:checked')?.value || 'qr';
  }

  function getElectronicLabel(code) {
    if (code === 'qr') return 'Pago QR';
    if (code === 'debito') return 'Tarjeta Débito';
    if (code === 'credito') return 'Tarjeta Crédito';
    return 'Posnet';
  }

  function updatePosPaymentEmisionLabels() {
    const cajaId = STATE.activeCajaId || 'caja1';
    const cfg = CAJAS_CONFIG[cajaId];
    if (!cfg) return;
    const respIva = (document.getElementById('fact-cli-respiva')?.value || 'Consumidor Final').toUpperCase();
    const isRespInsc = respIva.includes('INSCRIPTO') && !respIva.includes('NO INSCRIPTO');
    const letra = isRespInsc ? 'A' : 'B';
    const tipoComp = document.getElementById('pos-tipo-comp')?.value || 'Factura';
    const tipoFiscal = (!tipoComp || tipoComp === 'Comprobante Interno') ? 'Factura' : tipoComp;

    const nextFiscal = getNextCorrelativoForFact(cfg.pvFiscal, tipoFiscal, letra);
    const nextInterno = getNextCorrelativoForFact(cfg.pvInterno, 'Comprobante Interno', letra);

    const titleArca = document.getElementById('pos-pay-emision-arca-title');
    if (titleArca) {
      titleArca.textContent = `🧾 ${tipoFiscal} Electrónica ARCA`;
    }

    const subArca = document.getElementById('pos-pay-emision-arca-sub');
    const subInt = document.getElementById('pos-pay-emision-interno-sub');
    if (subArca) {
      subArca.textContent = `${tipoFiscal} ${letra} · ${cfg.pvFiscal}-${String(nextFiscal).padStart(8, '0')}`;
    }
    if (subInt) {
      subInt.textContent = `Interno ${letra} · ${cfg.pvInterno}-${String(nextInterno).padStart(8, '0')}`;
    }

    const emisionMode = document.querySelector('input[name="pos_pay_emision"]:checked')?.value || 'arca';
    const ncAlertBar = document.getElementById('pos-pay-nc-alert-bar');
    const ncAlertText = document.getElementById('pos-pay-nc-alert-text');
    if (ncAlertBar) {
      const isNcOrNd = emisionMode === 'arca' && tipoFiscal !== 'Factura';
      ncAlertBar.hidden = !isNcOrNd;
      ncAlertBar.style.display = isNcOrNd ? 'flex' : 'none';
      if (isNcOrNd && ncAlertText) {
        ncAlertText.innerHTML = `⚠️ Atención: El tipo de comprobante seleccionado es <strong>${tipoFiscal.toUpperCase()} ${letra}</strong> (no Factura).`;
      }
    }
  }

  function refreshPosPaymentModalUI(reRenderBills = false) {
    const total = round2(document.getElementById('pos-importe-input')?.value || 0);
    let method = getSelectedPosPayMethod();
    if (method === 'ctacte' && !doesClientAllowCtaCte(getActiveFactClientObj())) {
      const radEf = document.getElementById('pos-pay-method-efectivo');
      if (radEf) radEf.checked = true;
      method = 'efectivo';
    }
    const posnet = getSelectedPosPayPosnet();
    const combElec = getSelectedPosPayCombElec();

    const cashPanel = document.getElementById('pos-pay-cash-panel');
    const cashLegend = document.getElementById('pos-pay-cash-legend');
    const entregaLbl = document.getElementById('pos-pay-entrega-lbl');
    const entregaInp = document.getElementById('pos-pay-entrega-input');
    const vueltoBox = document.getElementById('pos-pay-vuelto-box');
    const vueltoLbl = document.getElementById('pos-pay-vuelto-lbl');
    const vueltoVal = document.getElementById('pos-pay-vuelto-val');
    const vueltoSub = document.getElementById('pos-pay-vuelto-sub');
    const splitBanner = document.getElementById('pos-pay-split-suggestion');
    const splitText = document.getElementById('pos-pay-split-text');
    const combTypePanel = document.getElementById('pos-pay-combinado-type-panel');
    const combRestLbl = document.getElementById('pos-pay-combinado-rest-lbl');
    const posnetPanel = document.getElementById('pos-pay-posnet-panel');
    const posnetLegend = document.getElementById('pos-pay-posnet-legend');
    const posnetSummary = document.getElementById('pos-pay-posnet-summary');
    const transfPanel = document.getElementById('pos-pay-transferencia-panel');
    const bancoSelect = document.getElementById('pos-pay-banco-select');
    const bancoSummary = document.getElementById('pos-pay-banco-summary');
    const confirmBtn = document.getElementById('btn-confirm-pos-payment');
    const alertEl = document.getElementById('pos-pay-alert');
    if (alertEl) alertEl.hidden = true;

    const usesCash = method === 'efectivo' || method === 'combinado';
    const usesPosnet = method === 'qr' || method === 'debito' || method === 'credito' || method === 'combinado';
    const usesTransf = method === 'transferencia';

    if (cashPanel) cashPanel.hidden = !usesCash;
    if (combTypePanel) combTypePanel.hidden = method !== 'combinado';
    if (posnetPanel) posnetPanel.hidden = !usesPosnet;
    if (transfPanel) transfPanel.hidden = !usesTransf;

    if (usesTransf) {
      if (bancoSelect && !bancoSelect.options.length) {
        populateTransferenciaBankSelect(bancoSelect);
      }
      const selectedCuenta = findTransferenciaBankAccount(bancoSelect?.value || '');
      updateTransferenciaSummaryBox(bancoSummary, selectedCuenta, total);
    }

    if (reRenderBills) {
      const billsWrap = document.getElementById('pos-pay-quick-bills');
      if (billsWrap) {
        billsWrap.textContent = '';
        if (method === 'efectivo') {
          const suggestions = buildPredictiveCashSuggestions(total);
          suggestions.forEach((amt) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'pos-pay-bill-chip';
            const isExact = Math.abs(amt - total) < 0.01;
            const diff = round2(amt - total);
            btn.textContent = isExact
              ? `Exacto ($ ${formatArs(amt)})`
              : `$ ${formatArs(amt)} (Vuelto $ ${formatArs(diff)})`;
            btn.addEventListener('click', () => {
              if (entregaInp) {
                entregaInp.value = formatArs(amt);
                refreshPosPaymentModalUI(false);
                entregaInp.focus();
              }
            });
            billsWrap.appendChild(btn);
          });
        }
      }
    }

    const enteredCash = parsePosMoneyInput(entregaInp?.value || 0);

    if (method === 'efectivo') {
      if (cashLegend) cashLegend.textContent = '2. Efectivo Recibido y Vuelto a Entregar';
      if (entregaLbl) entregaLbl.textContent = 'Efectivo recibido del cliente ($)';
      if (enteredCash >= total - 0.009) {
        const vuelto = round2(Math.max(0, enteredCash - total));
        vueltoBox?.classList.remove('is-pending');
        if (vueltoLbl) vueltoLbl.textContent = 'VUELTO A ENTREGAR';
        if (vueltoVal) vueltoVal.textContent = `$ ${formatArs(vuelto)}`;
        if (vueltoSub) {
          vueltoSub.textContent = vuelto > 0
            ? `Recibido: $ ${formatArs(enteredCash)} · Cobrado: $ ${formatArs(total)}`
            : 'Importe exacto recibido (sin vuelto)';
        }
        if (splitBanner) splitBanner.hidden = true;
      } else {
        const faltante = round2(total - enteredCash);
        vueltoBox?.classList.add('is-pending');
        if (vueltoLbl) vueltoLbl.textContent = 'FALTA CUBRIR';
        if (vueltoVal) vueltoVal.textContent = `$ ${formatArs(faltante)}`;
        if (vueltoSub) vueltoSub.textContent = 'Ingresá el efectivo recibido o completá el resto con Posnet';
        if (splitBanner && enteredCash > 0) {
          if (splitText) {
            splitText.innerHTML = `Efectivo <strong>$ ${formatArs(enteredCash)}</strong> · Restan cubrir <strong>$ ${formatArs(faltante)}</strong> con:`;
          }
          splitBanner.hidden = false;
        } else if (splitBanner) {
          splitBanner.hidden = true;
        }
      }
    } else if (method === 'combinado') {
      if (cashLegend) cashLegend.textContent = '2. Parte en Efectivo';
      if (entregaLbl) entregaLbl.textContent = 'Importe que entrega en Efectivo ($)';
      if (splitBanner) splitBanner.hidden = true;
      const cashApplied = Math.min(enteredCash, total);
      const restElec = round2(Math.max(0, total - cashApplied));
      vueltoBox?.classList.remove('is-pending');
      if (vueltoLbl) vueltoLbl.textContent = 'SALDO A ENVIAR A POSNET';
      if (vueltoVal) vueltoVal.textContent = `$ ${formatArs(restElec)}`;
      if (vueltoSub) vueltoSub.textContent = `Efectivo: $ ${formatArs(cashApplied)} + ${getElectronicLabel(combElec)}: $ ${formatArs(restElec)}`;
      if (combRestLbl) combRestLbl.textContent = `$ ${formatArs(restElec)}`;
      if (posnetLegend) posnetLegend.textContent = '4. Seleccionar Posnet / Terminal de Destino';
      if (posnetSummary) {
        posnetSummary.textContent = `📲 Enviar $ ${formatArs(restElec)} (${getElectronicLabel(combElec)}) a Posnet ${posnet}.`;
      }
    } else if (usesPosnet) {
      if (posnetLegend) {
        posnetLegend.textContent = `2. ¿A cuál Posnet enviás el cobro por ${getElectronicLabel(method)}?`;
      }
      if (posnetSummary) {
        posnetSummary.textContent = `📲 Se enviarán $ ${formatArs(total)} por ${getElectronicLabel(method)} a Posnet ${posnet}.`;
      }
    }

    updatePosPaymentEmisionLabels();
    const emisionMode = document.querySelector('input[name="pos_pay_emision"]:checked')?.value || 'arca';
    const tipoCompNow = document.getElementById('pos-tipo-comp')?.value || 'Factura';
    const tipoFiscalNow = (!tipoCompNow || tipoCompNow === 'Comprobante Interno') ? 'Factura' : tipoCompNow;
    const emisionShort = emisionMode === 'interno' ? 'Comprobante Interno' : `${tipoFiscalNow} ARCA`;
    const activeCajaIdNow = STATE.activeCajaId || 'caja1';
    const mpElecCode = method === 'combinado' ? combElec : method;
    const mpAmountToSend = method === 'combinado'
      ? round2(Math.max(0, total - Math.min(enteredCash, total)))
      : total;
    syncMpPointPanelUI(activeCajaIdNow, usesPosnet, posnet, mpAmountToSend, getElectronicLabel(mpElecCode));

    if (confirmBtn && !MP_POINT_STATE.waitingApproval) {
      confirmBtn.disabled = false;
      if (isMpPointIntegratedForCurrentSelection()) {
        confirmBtn.textContent = `📲 Enviar $ ${formatArs(mpAmountToSend)} al Posnet Mercado Pago y Emitir ${emisionShort}`;
      } else {
        confirmBtn.textContent = `✅ Confirmar Cobro ($ ${formatArs(total)}) y Emitir ${emisionShort}`;
      }
    }
  }

  function openPosPaymentDialog() {
    const alertEl = document.getElementById('fact-alert-msg');
    if (alertEl) alertEl.hidden = true;

    const cajaId = STATE.activeCajaId || 'caja1';
    const cfg = CAJAS_CONFIG[cajaId];
    if (!cfg) return;

    // Si aún no hay ítems en la lista pero el cajero dejó un código o artículo escrito en la 1° línea, incorporarlo automáticamente
    if (STATE.factItems.length === 0) {
      const pendingCodeRaw = document.getElementById('fact-first-code-input')?.value.trim() || '';
      if (pendingCodeRaw) {
        const parsed = parseFactCodeExpression(pendingCodeRaw);
        if (!parsed.onlyMultiplier && parsed.term) {
          const exactHit = findArticleByCodeOrBarcode(parsed.term);
          if (exactHit && exactHit.art) {
            const effectiveMult = parsed.multiplier !== null
              ? parsed.multiplier
              : (Number(STATE.factActiveMultiplier) !== 1
                ? Number(STATE.factActiveMultiplier)
                : (parseFloat(document.getElementById('fact-first-qty-input')?.value || '1') || 1));
            const scaleMult = exactHit.isScaleBarcode
              ? (parsed.multiplier !== null
                ? parsed.multiplier
                : (Number(STATE.factActiveMultiplier) !== 1 ? Number(STATE.factActiveMultiplier) : 1))
              : effectiveMult;
            addArticleToInvoice(exactHit.art, scaleMult * exactHit.barcodeQty, {
              isScaleTicket: Boolean(exactHit.isScaleBarcode),
              scaleInfo: exactHit.scaleInfo || null
            });
          } else if (factSugMatches && factSugMatches[factSugIndex]) {
            const effectiveMult = parsed.multiplier !== null
              ? parsed.multiplier
              : (Number(STATE.factActiveMultiplier) !== 1
                ? Number(STATE.factActiveMultiplier)
                : (parseFloat(document.getElementById('fact-first-qty-input')?.value || '1') || 1));
            addArticleToInvoice(factSugMatches[factSugIndex], effectiveMult);
          }
        }
      }
    }

    const importe = round2(document.getElementById('pos-importe-input')?.value || 0);
    if (STATE.factItems.length === 0 || importe <= 0) {
      if (alertEl) {
        alertEl.textContent = 'Ingresá al menos un artículo en la primera línea antes de confirmar la venta.';
        alertEl.hidden = false;
      }
      focusFirstCodeInput();
      return;
    }

    const dlg = document.getElementById('pos-payment-dialog');
    if (!dlg) return;

    const cajaNum = getCajaDiariaNumber(cajaId);
    const nextMov = getNextCajaMovimientoNumber(cajaId, true);
    const today = todayFormatted();
    const clienteNombre = document.getElementById('pos-cliente-input')?.value.trim().toUpperCase() || 'CONSUMIDOR FINAL';
    const formaPagoPos = document.getElementById('pos-medio-pago')?.value || 'Contado';
    const pvCurrent = document.getElementById('pos-select-pv')?.value || cfg.pvFiscal;
    const isInternoNow = pvCurrent === cfg.pvInterno || document.getElementById('pos-tipo-comp')?.value === 'Comprobante Interno';

    const cajaBadge = document.getElementById('pos-pay-caja-badge');
    const fechaBadge = document.getElementById('pos-pay-fecha-badge');
    const totalEl = document.getElementById('pos-pay-total-amount');
    const cliEl = document.getElementById('pos-pay-client-summary');

    if (cajaBadge) cajaBadge.textContent = `CAJA DIARIA ${cajaNum} - Nº: ${String(nextMov).padStart(6, '0')}`;
    if (fechaBadge) fechaBadge.textContent = today;
    if (totalEl) totalEl.textContent = `$ ${formatArs(importe)}`;
    if (cliEl) cliEl.textContent = `Cliente: ${clienteNombre}`;

    // Sincronizar radio de Emisión (Factura ARCA vs Comprobante Interno)
    const radArca = document.getElementById('pos-pay-emision-arca');
    const radInt = document.getElementById('pos-pay-emision-interno');
    if (radArca) radArca.checked = !isInternoNow;
    if (radInt) radInt.checked = isInternoNow;
    const contingenciaWrap = document.getElementById('pos-pay-arca-contingencia-wrap');
    const pendChk = document.getElementById('pos-pay-arca-pendiente-chk');
    if (contingenciaWrap) contingenciaWrap.hidden = isInternoNow;
    if (pendChk) pendChk.checked = STATE.arcaServicioEstado === 'contingencia';
    updatePosPaymentEmisionLabels();

    // Mostrar opción Cuenta Corriente solo si el cliente tiene habilitada Cuenta Corriente en el módulo de Clientes (nunca para genéricos #1, #2, #3)
    const ctaCteCard = document.getElementById('pos-pay-method-ctacte-card');
    const selectedCliObj = getActiveFactClientObj();
    const allowCtaCte = doesClientAllowCtaCte(selectedCliObj);
    if (ctaCteCard) ctaCteCard.hidden = !allowCtaCte;

    // Preseleccionar método de pago predictivo según lo que haya elegido el cajero (Contado vs Cuenta Corriente)
    const radEfectivo = document.getElementById('pos-pay-method-efectivo');
    const radCtaCte = document.getElementById('pos-pay-method-ctacte');
    if (allowCtaCte && formaPagoPos === 'Cuenta Corriente' && radCtaCte) {
      radCtaCte.checked = true;
    } else if (radEfectivo) {
      radEfectivo.checked = true;
    }

    // Preseleccionar último Posnet usado en esta Caja
    const savedPosnet = getSavedPosnetForCaja(cajaId);
    document.querySelectorAll('input[name="pos_pay_posnet"]').forEach((r) => {
      r.checked = r.value === savedPosnet;
    });

    // Poblar selector de cuentas bancarias para Transferencia
    const posBancoSel = document.getElementById('pos-pay-banco-select');
    if (posBancoSel) populateTransferenciaBankSelect(posBancoSel);

    // Precargar importe exacto en Efectivo recibido
    const entregaInp = document.getElementById('pos-pay-entrega-input');
    if (entregaInp) {
      entregaInp.value = formatArs(importe);
    }
    const obsInp = document.getElementById('pos-pay-obs');
    if (obsInp) obsInp.value = '';

    // Preparar estado Mercado Pago Point Smart para la Caja actual
    stopMpPointPolling(true);
    const mpPrintChk = document.getElementById('pos-mp-print-ticket-chk');
    if (mpPrintChk) mpPrintChk.checked = getMpPrintTicketPref(cajaId);
    const mpBypassChk = document.getElementById('pos-mp-manual-bypass-chk');
    if (mpBypassChk) mpBypassChk.checked = false;
    refreshMpPointServerStatus();

    refreshPosPaymentModalUI(true);

    if (!dlg.open) {
      dlg.showModal();
    }
    requestAnimationFrame(() => {
      if (getSelectedPosPayMethod() === 'efectivo' && entregaInp) {
        entregaInp.focus();
        entregaInp.select();
      } else {
        document.getElementById('btn-confirm-pos-payment')?.focus();
      }
    });
  }

  function computeArcaCodeAndQrData({ pv, nro, tipoBase, letra, importe, fechaIso, nroDocCliente }) {
    let codArca = 6; // Factura B
    if (letra === 'A') {
      codArca = tipoBase === 'Nota de Crédito' ? 3 : tipoBase === 'Nota de Débito' ? 2 : 1;
    } else {
      codArca = tipoBase === 'Nota de Crédito' ? 8 : tipoBase === 'Nota de Débito' ? 7 : 6;
    }

    // Generar CAE de 14 dígitos consistente con formato ARCA (ej: 86451894541535) y Vencimiento a +10 días
    const seed = String(Number(pv) * 1000000 + Number(nro)).padStart(8, '0');
    const cae = `864518${seed}`.slice(0, 14);
    const vtoDate = new Date();
    vtoDate.setDate(vtoDate.getDate() + 10);
    const caeVto = `${String(vtoDate.getDate()).padStart(2, '0')}/${String(vtoDate.getMonth() + 1).padStart(2, '0')}/${vtoDate.getFullYear()}`;

    const cleanDoc = String(nroDocCliente || '').replace(/\D/g, '');
    const tipoDocRec = cleanDoc.length === 11 ? 80 : cleanDoc.length >= 7 ? 96 : 99;
    const nroDocRec = tipoDocRec === 99 ? 0 : Number(cleanDoc) || 0;

    const qrJson = {
      ver: 1,
      fecha: fechaIso,
      cuit: ACTIVE_BRAND.fiscal.cuitNum,
      ptoVta: Number(pv) || 2,
      tipoCmp: codArca,
      nroCmp: Number(nro) || 1,
      importe: round2(importe),
      moneda: 'PES',
      ctz: 1,
      tipoDocRec,
      nroDocRec,
      tipoCodAut: 'E',
      codAut: Number(cae)
    };

    let base64Payload = '';
    try {
      base64Payload = btoa(JSON.stringify(qrJson));
    } catch {
      base64Payload = '';
    }
    const arcaQrUrl = `https://www.afip.gob.ar/fe/qr/?p=${base64Payload}`;
    const qrImgSrc = `https://api.qrserver.com/v1/create-qr-code/?size=180x180&ecc=M&margin=1&color=000000&bgcolor=ffffff&data=${encodeURIComponent(arcaQrUrl)}`;

    return {
      codArca: String(codArca).padStart(2, '0'),
      cae,
      caeVto,
      arcaQrUrl,
      qrImgSrc
    };
  }

  function normalizeSaleRecordForPreview(rawSale) {
    if (!rawSale || typeof rawSale !== 'object') return rawSale;
    const rawNum = String(rawSale.numeroCompleto || rawSale.numero || '').trim();
    const numMatch = rawNum.match(/(\d{1,5})\s*-\s*(\d{1,10})/);
    const pv = String(rawSale.pv || (numMatch ? numMatch[1] : '0099')).replace(/\D/g, '').padStart(4, '0');
    const nro = Number(rawSale.nro || (numMatch ? Number(numMatch[2]) : 1)) || 1;
    const esCompensacion = Boolean(
      rawSale.esCompensacion ||
      rawSale.esReciboCompensacion ||
      rawSale.payment?.method === 'compensacion'
    );
    const tipo = String(rawSale.tipo || rawSale.tipoComprobante || (esCompensacion ? 'Recibo por Compensación de Saldos' : 'Factura B')).trim();
    const isReciboLike = esCompensacion || rawSale.entryType === 'recibo' || Boolean(rawSale.esReciboCobroCtaCte) || /recibo/i.test(tipo);
    const letra = String(
      rawSale.letra ||
      (isReciboLike ? 'X' : /\bA\b/.test(tipo) ? 'A' : /\bC\b/.test(tipo) ? 'C' : 'B')
    ).trim().toUpperCase();
    const importe = round2(Number(rawSale.importe ?? rawSale.total ?? 0));
    const fechaHora =
      rawSale.fechaHora ||
      [rawSale.fechaAr || rawSale.fecha || '', rawSale.hora || ''].filter(Boolean).join(' ').trim() ||
      todayFormatted();
    const normItems = (Array.isArray(rawSale.items) ? rawSale.items : []).map((it) => {
      const qty = Number(it.qty ?? it.cantidad ?? 1) || 1;
      const unitPrice = Number(it.unitPrice ?? it.precioUnitario ?? it.subtotal ?? 0);
      const subtotal = Number(it.subtotal ?? round2(qty * unitPrice));
      const ivaPct =
        it.ivaPct !== undefined
          ? Number(it.ivaPct)
          : it.ivaRate !== undefined
            ? Number(it.ivaRate)
            : it.iva !== undefined
              ? Number(it.iva)
              : isReciboLike
                ? 0
                : 21;
      const desc = it.n || it.descripcion || 'CONCEPTO';
      return {
        ...it,
        qty,
        n: desc,
        descripcion: it.descripcion || desc,
        ivaPct,
        unitPrice,
        subtotal
      };
    });
    const payment = rawSale.payment || (esCompensacion
      ? {
          method: 'compensacion',
          isRecibo: true,
          nuevoSaldoRestante: rawSale.nuevoSaldoCliente ?? 0,
          observaciones: rawSale.comprobantesImputadosTexto || '',
          cajaDiariaLabel: `CAJA DIARIA ${rawSale.cajaNumero || 1}`
        }
      : {});
    return {
      ...rawSale,
      pv,
      nro,
      numeroCompleto: `${pv}-${String(nro).padStart(8, '0')}`,
      tipo,
      tipoBase: rawSale.tipoBase || tipo,
      letra,
      esCompensacion,
      importe,
      subTotalBruto: round2(Number(rawSale.subTotalBruto ?? rawSale.subtotalBruto ?? importe)),
      totalGravado: round2(Number(rawSale.totalGravado ?? rawSale.netoGravado ?? (isReciboLike ? importe : importe / 1.21))),
      totalIva: round2(Number(rawSale.totalIva ?? rawSale.ivaTotal ?? (isReciboLike ? 0 : importe - importe / 1.21))),
      fechaHora,
      cliente: rawSale.cliente || rawSale.clienteNombre || 'CONSUMIDOR FINAL',
      clienteCodigo: rawSale.clienteCodigo ?? '1',
      clienteDoc: rawSale.clienteDoc || rawSale.clienteDocNro || '00.000.000',
      clienteRespIva: rawSale.clienteRespIva || 'Consumidor Final',
      clienteDomicilio: rawSale.clienteDomicilio || 'S/D',
      clienteLocalidad: rawSale.clienteLocalidad || 'ALCIRA GIGENA(Córdoba)',
      items: normItems,
      payment
    };
  }

  function buildTicket78mmHtml(sale) {
    const p = sale.payment || {};
    const isCompra = sale.origen === 'COMPRA';
    const isRetiro = sale.entryType === 'retiro' || p.method === 'retiro_efectivo';
    const isCompensacion = Boolean(sale.esCompensacion || p.method === 'compensacion');
    const isRecibo =
      isCompensacion ||
      sale.entryType === 'recibo' ||
      Boolean(p.isRecibo) ||
      /recibo/i.test(String(sale.tipoBase || sale.tipo || ''));
    const isFiscal = Boolean(sale.isFiscal);
    const isFacturaA = sale.letra === 'A' && (isFiscal || sale.isHistoricalCtaCte || isCompra);
    const compHeader = isRetiro
      ? 'TICKET DE RETIRO DE EFECTIVO'
      : isCompensacion
        ? String(sale.tipo || 'RECIBO POR COMPENSACIÓN DE SALDOS').toUpperCase()
        : isCompra
          ? `${String(sale.tipoBase || sale.tipo || 'COMPROBANTE DE PROVEEDOR').toUpperCase()} "${sale.letra}"`
          : isRecibo
            ? 'RECIBO DE PAGO'
            : sale.isHistoricalCtaCte && !isFiscal
              ? `${(sale.tipoBase || 'FACTURA').toUpperCase()} "${sale.letra}"`
              : isFiscal
                ? `${(sale.tipoBase || 'FACTURA').toUpperCase()} "${sale.letra}" (Cód. ${sale.codArca || '06'})`
                : `COMPROBANTE INTERNO "${sale.letra}"`;

    const itemsHtml = (sale.items || [])
      .map((it) => {
        const qtyStr = Number.isInteger(Number(it.qty)) ? String(it.qty) : Number(it.qty).toFixed(3);
        const unitDisplay = isFacturaA ? formatArs(it.unitNeto || it.unitPrice / 1.21) : formatArs(it.unitPrice);
        const lineDisplay = isFacturaA ? formatArs(it.lineNeto || it.subtotal / 1.21) : formatArs(it.subtotal);
        const descText = it.n || it.descripcion || 'CONCEPTO';
        const ivaVal = it.ivaPct !== undefined ? Number(it.ivaPct) : (it.iva !== undefined ? Number(it.iva) : 21);
        return `
          <div class="t78-item">
            <div class="t78-item-desc">${escapeHtml(descText)}</div>
            <div class="t78-row">
              <span>${qtyStr} x $ ${unitDisplay}${isRetiro ? '' : ` (${ivaVal.toFixed(1)}%)`}</span>
              <span class="t78-bold">$ ${lineDisplay}</span>
            </div>
          </div>
        `;
      })
      .join('');

    let payLinesHtml = '';
    if (isRetiro) {
      payLinesHtml = `
        <div class="t78-row"><span>Operación:</span><span class="t78-bold">RETIRO DE EFECTIVO</span></div>
        <div class="t78-row"><span>Cajero:</span><span class="t78-bold">${escapeHtml(sale.usuario || '')}</span></div>
      `;
    } else if (isCompensacion) {
      payLinesHtml = `
        <div class="t78-row"><span>Modalidad:</span><span class="t78-bold">COMPENSACIÓN DE SALDOS</span></div>
        <div class="t78-row"><span>Cruce:</span><span>CLIENTE ↔ PROVEEDOR (DEUDA MÁS VIEJA)</span></div>
        ${p.totalOpenDebeBefore !== undefined ? `<div class="t78-row"><span>Deuda Cliente (Antes → Ahora):</span><span>$ ${formatArs(p.totalOpenDebeBefore)} → $ ${formatArs(p.totalOpenDebeAfter || 0)}</span></div>` : ''}
        ${p.totalOpenHaberBefore !== undefined ? `<div class="t78-row"><span>Crédito Prov. (Antes → Ahora):</span><span>$ ${formatArs(p.totalOpenHaberBefore)} → $ ${formatArs(p.totalOpenHaberAfter || 0)}</span></div>` : ''}
        <div class="t78-row"><span>Saldo Neto Actual Cta. Cte.:</span><span class="t78-bold">$ ${formatArs(p.nuevoSaldoRestante ?? 0)}</span></div>
      `;
    } else if (p.method === 'efectivo') {
      payLinesHtml = `
        <div class="t78-row"><span>Medio de Pago:</span><span class="t78-bold">EFECTIVO</span></div>
        <div class="t78-row"><span>Efectivo Recibido:</span><span>$ ${formatArs(p.efectivoRecibido || sale.importe)}</span></div>
        <div class="t78-row"><span>Vuelto Entregado:</span><span class="t78-bold">$ ${formatArs(p.vuelto || 0)}</span></div>
      `;
    } else if (p.method === 'combinado') {
      payLinesHtml = `
        <div class="t78-row"><span>Efectivo:</span><span>$ ${formatArs(p.efectivoAplicado || 0)}</span></div>
        <div class="t78-row"><span>${escapeHtml(p.electronicoTipo || 'Posnet')} (${escapeHtml(p.posnet || '')}):</span><span>$ ${formatArs(p.electronicoImporte || 0)}</span></div>
        ${p.mpPaymentId ? `<div class="t78-row"><span>Op. Mercado Pago:</span><span>#${escapeHtml(String(p.mpPaymentId))}</span></div>` : ''}
      `;
    } else if (p.method === 'ctacte') {
      payLinesHtml = `<div class="t78-row"><span>Medio de Pago:</span><span class="t78-bold">CUENTA CORRIENTE</span></div>`;
    } else if (p.method === 'transferencia') {
      const bankTxt = p.cuentaBancariaLabel || p.cuentaBancariaBanco || '';
      payLinesHtml = `
        <div class="t78-row"><span>Medio de Pago:</span><span class="t78-bold">TRANSFERENCIA BANCARIA</span></div>
        ${bankTxt ? `<div class="t78-row"><span>Cuenta Destino:</span><span class="t78-bold">${escapeHtml(bankTxt.toUpperCase())}</span></div>` : ''}
      `;
    } else {
      payLinesHtml = `
        <div class="t78-row"><span>Medio de Pago:</span><span class="t78-bold">${escapeHtml((p.electronicoTipo || sale.medioPago || '').toUpperCase())}</span></div>
        <div class="t78-row"><span>Posnet Destino:</span><span class="t78-bold">${escapeHtml((p.posnet || '').toUpperCase())}</span></div>
        ${p.mpPaymentId ? `<div class="t78-row"><span>Op. Mercado Pago:</span><span>#${escapeHtml(String(p.mpPaymentId))}</span></div>` : ''}
      `;
    }

    const fiscalTotalsHtml = isRetiro
      ? ''
      : isFacturaA
        ? `
          <div class="t78-row"><span>SUBTOTAL NETO:</span><span>$ ${formatArs(sale.totalGravado || 0)}</span></div>
          <div class="t78-row"><span>IVA 21,00%:</span><span>$ ${formatArs(sale.totalIva || 0)}</span></div>
        `
        : `
          <div class="t78-row" style="font-size:10px;"><span>IVA Contenido (Ley 27.743):</span><span>$ ${formatArs(sale.totalIva || 0)}</span></div>
        `;

    const isPendingArca = isFiscal && (sale.estadoArca === 'pendiente' || !sale.cae) && !sale.isHistoricalCtaCte;
    const arcaFooterHtml = sale.isHistoricalCtaCte && !sale.cae
      ? `
        <div class="t78-divider"></div>
        <div class="t78-center" style="font-size:9.5px;">
          <div class="t78-bold">REGISTRO DE CUENTA CORRIENTE</div>
          <div>${isCompra ? 'Comprobante de Proveedor registrado en Cta. Cte.' : 'Comprobante registrado en Cuenta Corriente'}</div>
        </div>
      `
      : isFiscal
        ? (isPendingArca
          ? `
            <div class="t78-divider"></div>
            <div class="t78-center" style="border:1px dashed #000; padding:4px; margin:2px 0;">
              <div class="t78-bold" style="font-size:10.5px;">COMPROBANTE PENDIENTE DE EMISIÓN EN ARCA</div>
              <div style="font-size:9.5px;">Contingencia por caída temporal del servicio ARCA · CAE pendiente</div>
            </div>
          `
          : `
            <div class="t78-divider"></div>
            <div class="t78-qr-box">
              <img src="${escapeHtml(sale.qrImgSrc || '')}" alt="QR Oficial ARCA">
              <div class="t78-bold" style="font-size:12px;">ARCA · Comprobante Autorizado</div>
              <div style="font-size:10px;">C.A.E.: ${escapeHtml(sale.cae || '')}</div>
              <div style="font-size:10px;">Vencimiento C.A.E.: ${escapeHtml(sale.caeVto || '')}</div>
            </div>
          `)
        : `
          <div class="t78-divider"></div>
          <div class="t78-center" style="font-size:10px;">${isRetiro ? 'COMPROBANTE INTERNO DE RETIRO DE CAJA' : 'DOCUMENTO NO VÁLIDO COMO FACTURA'}</div>
        `;

    const bottomGreetingHtml = isRetiro
      ? `
        <div style="margin-top:8mm; border-top:1px dotted #000; padding-top:1.5mm; text-align:center; font-size:10px;">
          FIRMA Y ACLARACIÓN RECEPTOR
        </div>
      `
      : `<div class="t78-center t78-bold" style="font-size:10.5px;">¡MUCHAS GRACIAS POR SU COMPRA!</div>`;

    return `
      <div class="ticket-78mm-sheet">
        <div class="t78-center">
          <img src="${ACTIVE_BRAND.assets.logoHorizontal}" alt="${ACTIVE_BRAND.fullName}" class="t78-logo">
          ${ACTIVE_BRAND.isPaseoAlberdi ? '' : '<div style="font-size:12px; font-weight:400;">BIANCHI MARIA ESTHER</div>'}
          <div class="t78-bold" style="font-size:13px;">${ACTIVE_BRAND.shortSuper}</div>
          ${ACTIVE_BRAND.isPaseoAlberdi ? '' : '<div style="font-size:10.5px;">CUIT: 27-05457050-9 · IIBB: 288462551</div>'}
          <div style="font-size:10.5px;">${ACTIVE_BRAND.fiscal.condIva}</div>
          ${ACTIVE_BRAND.isPaseoAlberdi ? '<div style="font-size:10px;">Ignacio Pirovano 193 · Barrio Alberdi · Río Cuarto</div><div style="font-size:10px;">WhatsApp: +54 9 3584 29-2027</div>' : '<div style="font-size:10px;">Inicio Act.: 02/03/2026 · Alcira Gigena (Cba)</div>'}
        </div>

        <div class="t78-divider"></div>

        <div class="t78-center t78-bold" style="font-size:12px;">${escapeHtml(compHeader)}</div>
        <div class="t78-row" style="margin-top:1mm;">
          <span>NRO: <strong>${escapeHtml(sale.pv)}-${String(sale.nro).padStart(8, '0')}</strong></span>
          <span>${escapeHtml(sale.fechaHora)}</span>
        </div>

        <div class="t78-divider"></div>

        <div style="font-size:10.5px;">
          <div><strong>${isRetiro ? 'DESTINATARIO' : isCompra ? 'PROVEEDOR' : 'CLIENTE'}:</strong> ${escapeHtml(sale.cliente)}</div>
          <div><strong>DOC/CUIT:</strong> ${escapeHtml(sale.clienteDoc || '00.000.000')} · <strong>IVA:</strong> ${escapeHtml(sale.clienteRespIva || 'Consumidor Final')}</div>
        </div>

        <div class="t78-divider"></div>

        ${itemsHtml}

        ${Number(sale.dtoImp) !== 0 ? `<div class="t78-row"><span>Dto./Rec. (${Number(sale.dtoPje || 0).toFixed(2)}%):</span><span>$ ${formatArs(sale.dtoImp)}</span></div>` : ''}
        ${fiscalTotalsHtml}

        <div class="t78-row t78-total-box">
          <span>${isRetiro ? 'IMPORTE RETIRADO' : 'TOTAL'}</span>
          <span>$ ${formatArs(sale.importe)}</span>
        </div>

        <div style="font-size:10.5px;">
          ${payLinesHtml}
          ${p.observaciones ? `<div style="margin-top:1mm;">Obs: ${escapeHtml(p.observaciones)}</div>` : ''}
          <div style="margin-top:1.5mm; font-size:9.5px;">${escapeHtml(p.cajaDiariaLabel || 'CAJA DIARIA 1')}</div>
        </div>

        ${arcaFooterHtml}

        <div class="t78-divider"></div>
        ${bottomGreetingHtml}
        <div class="t78-cutter-feed" aria-hidden="true">. . . . . . . . . . . . . . . .</div>
      </div>
    `;
  }

  function buildInvoiceA4Html(sale) {
    const p = sale.payment || {};
    const isCompra = sale.origen === 'COMPRA';
    const isFiscal = Boolean(sale.isFiscal);
    const isFacturaA = sale.letra === 'A';
    const isRetiro = sale.entryType === 'retiro' || p.method === 'retiro_efectivo';
    const isCompensacion = Boolean(sale.esCompensacion || p.method === 'compensacion');
    const isRecibo =
      isCompensacion ||
      sale.entryType === 'recibo' ||
      Boolean(p.isRecibo) ||
      /recibo/i.test(String(sale.tipoBase || sale.tipo || '')) ||
      (Array.isArray(sale.items) && sale.items.length > 0 && sale.items.every((it) => /^CANCELACI[ÓO]N\b|^COBRO A CUENTA\b|^IMPUTACI[ÓO]N\b/i.test(String(it.descripcion || it.n || ''))));
    const compTitle = isCompensacion
      ? String(sale.tipo || 'RECIBO POR COMPENSACIÓN DE SALDOS').toUpperCase()
      : isCompra
        ? String(sale.tipoBase || sale.tipo || 'COMPROBANTE DE PROVEEDOR').toUpperCase()
        : isRecibo
          ? 'RECIBO DE PAGO'
          : isRetiro
            ? 'RETIRO DE CAJA'
            : sale.isHistoricalCtaCte && !isFiscal
              ? (sale.tipoBase || 'FACTURA').toUpperCase()
              : isFiscal
                ? (sale.tipoBase || 'FACTURA').toUpperCase()
                : 'COMPROBANTE INTERNO';
    const codDisplay = isCompra ? 'PROVEEDOR' : isFiscal ? `Cod: ${sale.codArca || '06'}` : sale.isHistoricalCtaCte ? 'CTA. CTE.' : 'INTERNO';
    const fechaOnly = String(sale.fechaHora || '').split(' ')[0] || todayFormatted();

    let totalUnits = 0;
    const rowsHtml = (sale.items || [])
      .map((it) => {
        const qty = Number(it.qty) || 1;
        totalUnits += qty;
        const qtyFormatted = Number.isInteger(qty) ? String(qty) : qty.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 3 });
        const ivaPctStr = `${(Number(it.ivaPct) || 21).toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} %`;
        const prUnit = isFacturaA ? (Number(it.unitNeto) || Number(it.unitPrice) / 1.21) : Number(it.unitPrice);
        const importeRow = isFacturaA ? (Number(it.lineNeto) || Number(it.subtotal) / 1.21) : Number(it.subtotal);
        return `
          <tr>
            <td class="a4-center" style="width:58px;">${qtyFormatted}</td>
            <td>${escapeHtml(it.n || it.descripcion || 'CONCEPTO')}</td>
            <td class="a4-num" style="width:78px;">${ivaPctStr}</td>
            <td class="a4-num" style="width:105px;">${formatArs4(prUnit)}</td>
            <td class="a4-num" style="width:105px;">${formatArs(importeRow)}</td>
          </tr>
        `;
      })
      .join('');

    const subtotalCol1 = isFacturaA ? formatArs(sale.totalGravado || 0) : formatArs(sale.subTotalBruto || sale.importe);
    const descPctStr = (Number(sale.dtoPje) || 0).toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const descValStr = formatArs(Math.abs(Number(sale.dtoImp) || 0));
    const subtotalCol3 = isFacturaA ? formatArs(sale.totalGravado || 0) : formatArs(sale.importe);
    const ivaCellStr = isFacturaA
      ? `%21,00: $ ${formatArs(sale.totalIva || 0)}`
      : `$ ${formatArs(sale.totalIva || 0)}`;

    const cliCodPadded = String(sale.clienteCodigo || '1').padStart(6, '0');
    const senoresText = `${sale.cliente || 'CONSUMIDOR FINAL'} ${cliCodPadded}`;
    const condVenta =
      p.method === 'ctacte'
        ? 'Cuenta Corriente'
        : sale.medioPago
          ? `Contado (${sale.medioPago})`
          : 'Contado';

    const isPendingArca = isFiscal && (sale.estadoArca === 'pendiente' || !sale.cae) && !sale.isHistoricalCtaCte;
    const arcaBlockHtml = sale.isHistoricalCtaCte && !sale.cae
      ? `
        <div class="a4-arca-row">
          <div></div>
          <div class="a4-arca-box" style="text-align:center; padding:8px 10px; border-style:dashed;">
            <strong>${isCompra ? 'COMPROBANTE DE PROVEEDOR REGISTRADO EN CUENTA CORRIENTE' : 'COMPROBANTE REGISTRADO EN CUENTA CORRIENTE'}</strong><br>
            <span style="font-size:9.5px;">Visualización generada a partir del registro contable e imputaciones de Cuenta Corriente</span>
          </div>
        </div>
      `
      : isFiscal
        ? (isPendingArca
          ? `
            <div class="a4-arca-row">
              <div></div>
              <div class="a4-arca-box" style="text-align:center; padding:10px; border-style:dashed;">
                <strong>COMPROBANTE ELECTRÓNICO PENDIENTE DE EMISIÓN EN ARCA</strong><br>
                <span style="font-size:9.5px;">Servicio ARCA sin conexión al momento de la operación — Pendiente de obtención de C.A.E. en Administración Comprobantes Electrónicos</span>
              </div>
            </div>
          `
          : `
            <div class="a4-arca-row">
              <div></div>
              <div class="a4-arca-box">
                <div class="a4-arca-inner">
                  <img src="${escapeHtml(sale.qrImgSrc || '')}" alt="QR Oficial ARCA" class="a4-arca-qr">
                  <div>
                    <div class="a4-arca-brand">ARCA</div>
                    <div class="a4-arca-sub">AGENCIA DE RECAUDACIÓN<br>Y CONTROL ADUANERO</div>
                    <div class="a4-arca-auth">Comprobante Autorizado</div>
                    <div class="a4-arca-cae">C.A.E.: ${escapeHtml(sale.cae || '')} - Vencimiento: ${escapeHtml(sale.caeVto || '')}</div>
                  </div>
                </div>
                <div class="a4-arca-disclaimer">
                  Esta agencia no se responsabiliza por los datos ingresados en el detalle de la operación
                </div>
              </div>
            </div>
          `)
        : '';

    const footerLine = p.footerValoresLine || `${p.cajaDiariaLabel || 'CAJA DIARIA 3'} ${sale.medioPago}: $ ${formatArs(sale.importe)} -`;

    return `
      <div class="invoice-a4-sheet">
        <div>
          <!-- CABECERA 3 COLUMNAS ESTILO OFICIAL ARCA / CASA NUEVA -->
          <div class="a4-header-grid">
            <div class="a4-header-left">
              <div class="a4-logo-wrap">
                <img src="${ACTIVE_BRAND.assets.logoHorizontal}" alt="${ACTIVE_BRAND.fullName}" class="a4-logo-img">
              </div>
              <div class="a4-emisor-info">
                ${ACTIVE_BRAND.isPaseoAlberdi ? '' : '<div style="font-weight:400;">BIANCHI MARIA ESTHER</div>'}
                <strong>${ACTIVE_BRAND.shortSuper}</strong>
                ${ACTIVE_BRAND.isPaseoAlberdi ? '<div style="font-weight:400; font-size:10.5px;">Ignacio Pirovano 193, Barrio Alberdi, Río Cuarto · WhatsApp: +54 9 3584 29-2027</div>' : ''}
              </div>
            </div>

            <div class="a4-header-center">
              <div class="a4-letra-square">${escapeHtml(sale.letra || 'B')}</div>
              <div class="a4-letra-cod">${escapeHtml(codDisplay)}</div>
              <div class="a4-center-vline"></div>
            </div>

            <div class="a4-header-right">
              <div class="a4-comp-top">
                <div class="a4-comp-title">${escapeHtml(compTitle)}</div>
                <div class="a4-comp-nro"><strong>NRO.</strong> ${escapeHtml(sale.pv)} - ${String(sale.nro).padStart(8, '0')}</div>
                <div class="a4-comp-fecha"><strong>FECHA</strong> ${escapeHtml(fechaOnly)}</div>
              </div>
              <div class="a4-fiscal-meta">
                <div>
                  <div>Nº CUIT: ${ACTIVE_BRAND.fiscal.cuitFmt}</div>
                  <div>Resp. IVA: Inscripto</div>
                  <div>Nro. IIBB: ${ACTIVE_BRAND.fiscal.iibb}</div>
                  <div>Inicio de Actividades: ${ACTIVE_BRAND.isPaseoAlberdi ? '—' : '02/03/2026'}</div>
                </div>
                <div class="a4-page-badge">
                  <div>ORIGINAL</div>
                  <div style="font-size:12px;">Hoja 1 de 1</div>
                </div>
              </div>
            </div>
          </div>

          <!-- DATOS DEL CLIENTE -->
          <div class="a4-client-box">
            <div class="a4-client-row a4-client-row--full">
              <div><span class="a4-lbl">${isCompra ? 'PROVEEDOR' : 'SEÑOR/ES'}</span> ${escapeHtml(senoresText)}</div>
            </div>
            <div class="a4-client-row">
              <div><span class="a4-lbl">DOMICILIO</span> ${escapeHtml(sale.clienteDomicilio || 'S/D')}</div>
              <div><span class="a4-lbl">LOCALIDAD</span> ${escapeHtml(sale.clienteLocalidad || 'ALCIRA GIGENA(Córdoba)')}</div>
            </div>
            <div class="a4-client-row">
              <div><span class="a4-lbl">TEL.</span> ${escapeHtml(sale.clienteTel || '')}</div>
              <div><span class="a4-lbl">C.U.I.T. Nº</span> ${escapeHtml(sale.clienteDoc || '00.000.000')}</div>
            </div>
            <div class="a4-client-row">
              <div><span class="a4-lbl">CONDICION IVA</span> ${escapeHtml(sale.clienteRespIva || 'Consumidor Final')}</div>
              <div><span class="a4-lbl">IIBB Nº</span> ${escapeHtml(sale.clienteIibb || '')}</div>
            </div>
            <div class="a4-client-row a4-client-row--full">
              <div><span class="a4-lbl">CONDICION DE VENTA</span> ${escapeHtml(condVenta)}</div>
            </div>
          </div>

          <!-- TABLA DE ARTÍCULOS -->
          <table class="a4-items-table">
            <thead>
              <tr>
                <th class="a4-center" style="width:58px;">CANT.</th>
                <th>DESCRIPCION</th>
                <th class="a4-num" style="width:78px;">% IVA</th>
                <th class="a4-num" style="width:105px;">PR. UNIT.</th>
                <th class="a4-num" style="width:105px;">IMPORTE</th>
              </tr>
            </thead>
            <tbody>
              ${rowsHtml}
            </tbody>
          </table>
        </div>

        <!-- PIE DE PÁGINA A4: SUBTOTALES, IVA, ARCA QR + CAE Y DETALLE DE VALORES DE CAJA -->
        <div class="a4-bottom-block">
          <div class="a4-total-qty-line">Cantidad total de artículos: ${Number.isInteger(totalUnits) ? totalUnits : totalUnits.toLocaleString('es-AR')}.</div>

          <table class="a4-totals-table">
            <thead>
              <tr>
                <th>SUBTOTAL</th>
                <th>DESC. %${descPctStr}</th>
                <th>SUBTOTAL</th>
                <th>I.V.A. INSC.</th>
                <th>Imp. Interno</th>
                <th>Perc. IIBB</th>
                <th>TOTAL</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>${subtotalCol1}</td>
                <td>${descValStr}</td>
                <td>${subtotalCol3}</td>
                <td>${ivaCellStr}</td>
                <td>0,00</td>
                <td>0,00% &nbsp; 0,00</td>
                <td class="a4-grand-total-cell">${formatArs(sale.importe)}</td>
              </tr>
            </tbody>
          </table>

          ${arcaBlockHtml}

          <div class="a4-caja-footer-box">
            ${escapeHtml(footerLine)}
            ${p.observaciones ? `<div style="margin-top:2px; font-size:9.5px;">Obs: ${escapeHtml(p.observaciones)}</div>` : ''}
          </div>
        </div>
      </div>
    `;
  }

  function renderPosTicketPreview() {
    const stage = document.getElementById('pos-ticket-preview-stage');
    if (!stage || !activeTicketSaleRecord) return;
    const fmt = document.querySelector('input[name="pos_ticket_format"]:checked')?.value || '78mm';
    stage.innerHTML = fmt === 'a4'
      ? buildInvoiceA4Html(activeTicketSaleRecord)
      : buildTicket78mmHtml(activeTicketSaleRecord);
  }

  function openPosTicketDialog(saleRecord, { goToNextSaleOnClose = false, defaultFormat = null, sourceLabel = '' } = {}) {
    if (!saleRecord) return;
    const normalizedSale = normalizeSaleRecordForPreview(saleRecord);
    activeTicketSaleRecord = normalizedSale;
    ticketShouldAdvanceToNextSale = Boolean(goToNextSaleOnClose);

    const dlg = document.getElementById('pos-ticket-dialog');
    if (!dlg) return;

    const ctacteDlg = document.getElementById('ctacte-dialog');
    if (ctacteDlg?.open) {
      ctacteDlg.dataset.prevClosedby = ctacteDlg.getAttribute('closedby') || 'any';
      ctacteDlg.setAttribute('closedby', 'none');
    }

    // Caja 1 y Caja 2 -> Papel Continuo 78mm por defecto | Caja 3 o Vista Cta. Cte. -> Hoja A4 por defecto
    const chosenFormat =
      defaultFormat === 'a4' || defaultFormat === '78mm'
        ? defaultFormat
        : normalizedSale.cajaId === 'caja3'
          ? 'a4'
          : '78mm';
    const rad78 = document.getElementById('pos-ticket-fmt-78mm');
    const radA4 = document.getElementById('pos-ticket-fmt-a4');
    if (rad78) rad78.checked = chosenFormat === '78mm';
    if (radA4) radA4.checked = chosenFormat === 'a4';

    const cajaCfg = CAJAS_CONFIG[normalizedSale.cajaId] || { nombre: 'Caja 1' };
    const badgeEl = document.getElementById('pos-ticket-caja-badge');
    const titleEl = document.getElementById('pos-ticket-dialog-title');
    if (badgeEl) {
      badgeEl.textContent =
        sourceLabel ||
        `✅ ${cajaCfg.nombre.toUpperCase()} · ${chosenFormat === 'a4' ? 'REPORTE HOJA A4' : 'TICKET CONTINUO 78mm'}`;
    }
    if (titleEl) {
      titleEl.textContent = `${normalizedSale.tipo} ${normalizedSale.pv}-${String(normalizedSale.nro).padStart(8, '0')} ($ ${formatArs(normalizedSale.importe)})`;
    }

    const btnDone = document.getElementById('btn-done-pos-ticket');
    if (btnDone) {
      btnDone.textContent = goToNextSaleOnClose ? '✅ Cerrar y Nueva Venta (Esc)' : '✕ Cerrar Vista (Esc)';
    }
    const btnEditPago = document.getElementById('btn-edit-pago-from-ticket');
    if (btnEditPago) {
      btnEditPago.hidden = Boolean(normalizedSale.esCompensacion || normalizedSale.origen === 'COMPRA');
    }

    renderPosTicketPreview();
    if (!dlg.open) {
      dlg.showModal();
    }
    requestAnimationFrame(() => {
      document.getElementById('btn-print-pos-ticket')?.focus();
    });
  }
  window.openPosTicketDialog = openPosTicketDialog;

  function printActivePosTicket() {
    const stage = document.getElementById('pos-ticket-preview-stage');
    if (!stage || !activeTicketSaleRecord) return;
    const fmt = document.querySelector('input[name="pos_ticket_format"]:checked')?.value || '78mm';
    const isThermal78 = fmt !== 'a4';
    const pageRule = fmt === 'a4'
      ? '@page { size: A4 portrait; margin: 6mm; }'
      : '@page { size: 80mm auto; margin: 0mm !important; }';

    const thermalPrintRules = isThermal78
      ? `
          html, body {
            width: 72mm !important;
            max-width: 72mm !important;
            min-height: 0 !important;
            height: auto !important;
            overflow: visible !important;
          }
          .ticket-78mm-sheet {
            width: 72mm !important;
            max-width: 72mm !important;
            padding: 2mm 1.5mm 1mm 1.5mm !important;
            margin: 0 !important;
            box-shadow: none !important;
            page-break-inside: avoid !important;
            break-inside: avoid !important;
            page-break-after: avoid !important;
            break-after: avoid !important;
          }
          .ticket-78mm-sheet,
          .ticket-78mm-sheet * {
            page-break-inside: avoid !important;
            break-inside: avoid !important;
          }
          .t78-cutter-feed {
            display: block !important;
            padding-top: 20mm !important;
            margin-top: 2mm !important;
            font-size: 9px !important;
            line-height: 1 !important;
            text-align: center !important;
            color: #000000 !important;
          }
        `
      : '';

    const baseHref = window.location.href.replace(/[^/]*$/, '');
    const printWin = window.open('', '_blank', 'width=900,height=780');
    if (!printWin) {
      window.print();
      return;
    }

    const stylesHref = document.querySelector('link[href*="assets/css/styles.css"]')?.href || `${baseHref}assets/css/styles.css`;
    printWin.document.open();
    printWin.document.write(`<!DOCTYPE html>
      <html lang="es-AR">
      <head>
        <meta charset="UTF-8">
        <base href="${baseHref}">
        <title>${escapeHtml(activeTicketSaleRecord.tipo)} ${escapeHtml(activeTicketSaleRecord.pv)}-${String(activeTicketSaleRecord.nro).padStart(8, '0')}</title>
        <link rel="stylesheet" href="${stylesHref}">
        <style>
          ${pageRule}
          html, body {
            margin: 0 !important;
            padding: 0 !important;
            min-height: 0 !important;
            height: auto !important;
            background: #ffffff !important;
            color: #000000 !important;
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
          }
          .ticket-78mm-sheet, .invoice-a4-sheet {
            box-shadow: none !important;
            margin: 0 auto !important;
          }
          ${thermalPrintRules}
        </style>
      </head>
      <body>
        ${stage.innerHTML}
        <script>
          (function () {
            var printed = false;
            function triggerPrintNow() {
              if (printed) return;
              printed = true;
              try {
                void document.body.offsetHeight;
                window.focus();
                window.print();
              } catch (e) {}
            }
            function waitAllImagesAndPrint() {
              var imgs = Array.prototype.slice.call(document.images || []);
              if (imgs.length === 0) {
                setTimeout(triggerPrintNow, 180);
                return;
              }
              var remaining = imgs.length;
              function onImgDone() {
                remaining -= 1;
                if (remaining <= 0) {
                  setTimeout(triggerPrintNow, 220);
                }
              }
              imgs.forEach(function (img) {
                if (img.complete) {
                  if (typeof img.decode === 'function') {
                    img.decode().then(onImgDone).catch(onImgDone);
                  } else {
                    onImgDone();
                  }
                } else {
                  img.addEventListener('load', function () {
                    if (typeof img.decode === 'function') {
                      img.decode().then(onImgDone).catch(onImgDone);
                    } else {
                      onImgDone();
                    }
                  }, { once: true });
                  img.addEventListener('error', onImgDone, { once: true });
                }
              });
              setTimeout(triggerPrintNow, 1800);
            }
            if (document.readyState === 'complete') {
              waitAllImagesAndPrint();
            } else {
              window.addEventListener('load', waitAllImagesAndPrint, { once: true });
              setTimeout(triggerPrintNow, 2200);
            }
          })();
        <\/script>
      </body>
      </html>`);
    printWin.document.close();
  }

  function closePosTicketAndContinue() {
    const dlg = document.getElementById('pos-ticket-dialog');
    const shouldAdvance = ticketShouldAdvanceToNextSale;
    const cajaId = STATE.activeCajaId || 'caja1';
    ticketShouldAdvanceToNextSale = false;
    if (dlg?.open) {
      dlg.close();
    }
    if (shouldAdvance) {
      openClubPrevioScreen(cajaId);
    }
  }

  // Emitir Comprobante: Al confirmar la compra en el POS, abrir primero el Detalle de Pago Predictivo
  const factForm = document.getElementById('facturacion-form');
  if (factForm) {
    factForm.addEventListener('submit', (e) => {
      e.preventDefault();
      if (!requireCajaAperturaBeforeOperar(STATE.activeCajaId || 'caja1')) {
        return;
      }
      openPosPaymentDialog();
    });
  }

  // Listeners del Modal de Detalle de Pago Predictivo
  document.querySelectorAll('input[name="pos_pay_emision"]').forEach((rad) => {
    rad.addEventListener('change', () => {
      const cajaId = STATE.activeCajaId || 'caja1';
      const cfg = CAJAS_CONFIG[cajaId];
      const pvSel = document.getElementById('pos-select-pv');
      const tipoSel = document.getElementById('pos-tipo-comp');
      if (cfg && pvSel) {
        if (rad.value === 'interno' && rad.checked) {
          pvSel.value = cfg.pvInterno;
        } else if (rad.value === 'arca' && rad.checked) {
          pvSel.value = cfg.pvFiscal;
          if (tipoSel && (!tipoSel.value || tipoSel.value === 'Comprobante Interno')) {
            tipoSel.value = 'Factura';
          }
        }
        updateFactLetraAndNumber();
      }
      const contingenciaWrap = document.getElementById('pos-pay-arca-contingencia-wrap');
      if (contingenciaWrap) contingenciaWrap.hidden = rad.value !== 'arca';
      updatePosPaymentEmisionLabels();
      refreshPosPaymentModalUI(false);
    });
  });

  document.getElementById('btn-pos-pay-switch-to-factura')?.addEventListener('click', () => {
    const tipoSel = document.getElementById('pos-tipo-comp');
    if (tipoSel) tipoSel.value = 'Factura';
    updateFactLetraAndNumber();
    updatePosPaymentEmisionLabels();
    refreshPosPaymentModalUI(false);
  });

  document.querySelectorAll('input[name="pos_pay_method"]').forEach((rad) => {
    rad.addEventListener('change', () => {
      const importe = round2(document.getElementById('pos-importe-input')?.value || 0);
      const entregaInp = document.getElementById('pos-pay-entrega-input');
      if (rad.value === 'efectivo' && entregaInp) {
        entregaInp.value = formatArs(importe);
      } else if (rad.value === 'combinado' && entregaInp) {
        const currentVal = parsePosMoneyInput(entregaInp.value);
        if (currentVal <= 0 || currentVal >= importe) {
          entregaInp.value = formatArs(Math.floor(importe / 2));
        }
      }
      refreshPosPaymentModalUI(true);
      if ((rad.value === 'efectivo' || rad.value === 'combinado') && entregaInp) {
        entregaInp.focus();
        entregaInp.select();
      }
    });
  });

  document.querySelectorAll('input[name="pos_pay_posnet"]').forEach((rad) => {
    rad.addEventListener('change', () => {
      if (rad.checked) {
        savePosnetForCaja(STATE.activeCajaId || 'caja1', rad.value);
      }
      refreshPosPaymentModalUI(false);
    });
  });

  document.querySelectorAll('input[name="pos_pay_comb_elec"]').forEach((rad) => {
    rad.addEventListener('change', () => {
      refreshPosPaymentModalUI(false);
    });
  });

  document.getElementById('pos-pay-banco-select')?.addEventListener('change', () => {
    refreshPosPaymentModalUI(false);
  });

  document.getElementById('pos-pay-entrega-input')?.addEventListener('input', () => {
    refreshPosPaymentModalUI(false);
  });

  document.querySelectorAll('[data-split-elec]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const elecType = btn.getAttribute('data-split-elec') || 'qr';
      const combRad = document.getElementById('pos-pay-method-combinado');
      if (combRad) combRad.checked = true;
      document.querySelectorAll('input[name="pos_pay_comb_elec"]').forEach((r) => {
        r.checked = r.value === elecType;
      });
      refreshPosPaymentModalUI(true);
    });
  });

  document.getElementById('pos-mp-print-ticket-chk')?.addEventListener('change', (e) => {
    saveMpPrintTicketPref(STATE.activeCajaId || 'caja1', Boolean(e.target.checked));
  });

  document.getElementById('pos-mp-manual-bypass-chk')?.addEventListener('change', () => {
    if (MP_POINT_STATE.waitingApproval) {
      cancelActiveMpPointOrderOnServer(true);
    }
    refreshPosPaymentModalUI(false);
  });

  document.getElementById('btn-pos-mp-toggle-mode')?.addEventListener('click', async () => {
    const cajaId = STATE.activeCajaId || 'caja1';
    const mpCaja = MP_POINT_STATE.cajas[cajaId];
    if (!mpCaja || !mpCaja.terminal_id) return;
    const currentMode = String(mpCaja.operating_mode || 'PDV').toUpperCase();
    const targetMode = currentMode === 'PDV' ? 'STANDALONE' : 'PDV';
    const confirmSwitch = await showBrandConfirmDialog(
      `¿Cambiar el Posnet de ${mpCaja.caja_nombre} (S/N ...${mpCaja.serial_short}) a modo ${targetMode === 'PDV' ? 'INTEGRADO (PDV)' : 'MANUAL (STANDALONE)'}?\n\nNota de Mercado Pago: después de cambiar el modo hay que reiniciar físicamente el Posnet para que tome el cambio.`
    );
    if (!confirmSwitch) return;
    try {
      const res = await fetch('api/mercadopago_point.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'set_mode',
          caja_id: cajaId,
          operating_mode: targetMode
        })
      });
      const json = await res.json();
      if (json && json.ok) {
        mpCaja.operating_mode = targetMode;
        refreshPosPaymentModalUI(false);
        window.alert(`✅ ${json.message}`);
      } else {
        window.alert(`⚠️ ${json?.message || 'No se pudo actualizar el modo del Posnet.'}`);
      }
    } catch {
      window.alert('⚠️ Error de conexión al intentar cambiar el modo del Posnet.');
    }
  });

  document.getElementById('btn-pos-mp-cancel-order')?.addEventListener('click', () => {
    cancelActiveMpPointOrderOnServer(false);
  });

  document.getElementById('btn-pos-mp-retry-order')?.addEventListener('click', () => {
    const form = document.getElementById('pos-payment-form');
    if (form) form.requestSubmit();
  });

  document.getElementById('btn-pos-mp-force-complete')?.addEventListener('click', () => {
    if (typeof MP_POINT_STATE.pendingFinalizeCallback === 'function') {
      const fn = MP_POINT_STATE.pendingFinalizeCallback;
      const oid = MP_POINT_STATE.activeOrderId || '';
      stopMpPointPolling(true);
      fn({ orderId: oid, paymentId: 'CONFIRMADO-CAJA', manualForced: true });
    }
  });

  document.getElementById('btn-close-pos-payment')?.addEventListener('click', () => {
    if (MP_POINT_STATE.waitingApproval || MP_POINT_STATE.activeOrderId) {
      cancelActiveMpPointOrderOnServer(true);
    }
    document.getElementById('pos-payment-dialog')?.close();
    focusFirstCodeInput();
  });

  document.getElementById('btn-cancel-pos-payment')?.addEventListener('click', () => {
    if (MP_POINT_STATE.waitingApproval || MP_POINT_STATE.activeOrderId) {
      cancelActiveMpPointOrderOnServer(true);
    }
    document.getElementById('pos-payment-dialog')?.close();
    focusFirstCodeInput();
  });

  async function startMpPointIntegratedFlow({
    uiContext = 'pos',
    cajaId,
    amountToSend,
    elecCode,
    printOnTerminal,
    externalRef,
    description,
    onApproved
  }) {
    MP_POINT_STATE.activeUiContext =
      uiContext === 'recibo' ? 'recibo' : uiContext === 'edit_comp' ? 'edit_comp' : 'pos';
    const { liveBox, titleEl, detailEl, oidEl, retryBtn, confirmBtn } = getMpPointLiveUiElements(MP_POINT_STATE.activeUiContext);
    const mpCaja = MP_POINT_STATE.cajas[cajaId] || {};

    stopMpPointPolling(false);
    MP_POINT_STATE.waitingApproval = true;
    MP_POINT_STATE.activeOrderCajaId = cajaId;
    MP_POINT_STATE.pendingFinalizeCallback = onApproved;

    if (retryBtn) retryBtn.hidden = true;
    if (titleEl) {
      titleEl.style.color = '#38bdf8';
      titleEl.textContent = `📡 Enviando $ ${formatArs(amountToSend)} al Posnet S/N ...${mpCaja.serial_short || ''}...`;
    }
    if (detailEl) {
      detailEl.textContent = 'Conectando con Mercado Pago Point Smart...';
    }
    if (oidEl) oidEl.textContent = '';
    if (liveBox) liveBox.hidden = false;

    let createJson = null;
    try {
      const res = await fetch('api/mercadopago_point.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'create_order',
          caja_id: cajaId,
          amount: amountToSend,
          payment_type: elecCode,
          print_on_terminal: printOnTerminal,
          external_reference: externalRef,
          description
        })
      });
      createJson = await res.json();
      if (!res.ok || !createJson || !createJson.ok) {
        throw new Error(createJson?.message || 'No se pudo enviar la orden al Posnet.');
      }
    } catch (err) {
      MP_POINT_STATE.waitingApproval = false;
      if (titleEl) {
        titleEl.style.color = '#fca5a5';
        titleEl.textContent = '⚠️ No se pudo enviar la orden al Posnet';
      }
      if (detailEl) {
        detailEl.textContent = err?.message || 'Verificá que el Posnet esté encendido, con Wi-Fi/4G y sin otro cobro en pantalla.';
      }
      if (retryBtn) retryBtn.hidden = false;
      if (confirmBtn) confirmBtn.disabled = false;
      return;
    }

    const orderSummary = createJson.order || {};
    const orderId = orderSummary.order_id;
    MP_POINT_STATE.activeOrderId = orderId;

    if (titleEl) {
      titleEl.style.color = '#38bdf8';
      titleEl.textContent = `💳 Cobro de $ ${formatArs(amountToSend)} en pantalla del Posnet`;
    }
    if (detailEl) {
      detailEl.textContent =
        elecCode === 'qr'
          ? 'El código QR / cobro ya está en la pantalla del Posnet. Esperando pago del cliente...'
          : 'Pedile al cliente que apoye, inserte o deslice su tarjeta en el Posnet...';
    }
    if (oidEl) {
      oidEl.textContent = `Orden MP: ${orderId}`;
    }

    // Si por alguna razón ya vino aprobada instantáneamente
    if (orderSummary.is_approved) {
      playMpApprovedChime();
      stopMpPointPolling(true);
      onApproved({
        orderId,
        paymentId: orderSummary.payment_id || orderId,
        paymentMethod: orderSummary.payment_method || elecCode
      });
      return;
    }

    let pollInFlight = false;
    MP_POINT_STATE.pollingTimer = setInterval(async () => {
      if (pollInFlight || !MP_POINT_STATE.waitingApproval || !MP_POINT_STATE.activeOrderId) return;
      pollInFlight = true;
      try {
        const res = await fetch(
          `api/mercadopago_point.php?action=check_order&order_id=${encodeURIComponent(orderId)}&_t=${Date.now()}`,
          { cache: 'no-store' }
        );
        if (!res.ok) return;
        const json = await res.json();
        if (!json || !json.ok || !json.order) return;
        const ord = json.order;

        if (ord.status === 'at_terminal' && titleEl) {
          titleEl.style.color = '#38bdf8';
          titleEl.textContent = `💳 Posnet activo esperando tarjeta / QR ($ ${formatArs(amountToSend)})`;
        }

        if (ord.is_approved) {
          playMpApprovedChime();
          if (titleEl) {
            titleEl.style.color = '#4ade80';
            titleEl.textContent = `✅ ¡Pago Aprobado! (Op. #${ord.payment_id || orderId})`;
          }
          if (detailEl) {
            detailEl.textContent =
              MP_POINT_STATE.activeUiContext === 'edit_comp'
                ? 'Guardando forma de pago actualizada...'
                : 'Emitiendo comprobante automáticamente...';
          }
          stopMpPointPolling(true);
          onApproved({
            orderId,
            paymentId: ord.payment_id || orderId,
            paymentMethod: ord.payment_method || elecCode
          });
          return;
        }

        if (ord.is_rejected) {
          stopMpPointPolling(false);
          if (typeof playFactAlertBeep === 'function') playFactAlertBeep();
          if (titleEl) {
            titleEl.style.color = '#fca5a5';
            titleEl.textContent = `❌ Pago rechazado o cancelado en el Posnet`;
          }
          if (detailEl) {
            detailEl.textContent = `Estado informado por Mercado Pago: ${ord.status_detail || ord.status}. Podés reenviar la orden o cambiar de medio de pago.`;
          }
          if (retryBtn) retryBtn.hidden = false;
          if (confirmBtn) confirmBtn.disabled = false;
        }
      } catch {
        // Ignorar microcortes transitorios de red durante el polling
      } finally {
        pollInFlight = false;
      }
    }, 1800);
  }

  document.getElementById('pos-payment-form')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const payAlert = document.getElementById('pos-pay-alert');
    if (payAlert) payAlert.hidden = true;

    const cajaId = STATE.activeCajaId || 'caja1';
    const cfg = CAJAS_CONFIG[cajaId];
    if (!cfg) return;

    const importe = round2(document.getElementById('pos-importe-input')?.value || 0);
    if (STATE.factItems.length === 0 || importe <= 0) return;

    const method = getSelectedPosPayMethod();
    if (method === 'ctacte' && !doesClientAllowCtaCte(getActiveFactClientObj())) {
      if (payAlert) {
        payAlert.textContent =
          'Este cliente no tiene configurada la opción de Cuenta Corriente en el módulo de Clientes. Seleccioná un medio de pago de Contado.';
        payAlert.hidden = false;
      }
      return;
    }
    const posnet = getSelectedPosPayPosnet();
    const combElec = getSelectedPosPayCombElec();
    const rawEntregaStr = (document.getElementById('pos-pay-entrega-input')?.value || '').trim();
    let enteredCash = parsePosMoneyInput(rawEntregaStr);
    if (method === 'efectivo' && (!rawEntregaStr || enteredCash <= 0)) {
      enteredCash = importe;
    }
    const observacionesPago = document.getElementById('pos-pay-obs')?.value.trim().toUpperCase() || '';

    if (method === 'efectivo' && enteredCash < importe - 0.009) {
      if (payAlert) {
        payAlert.textContent = `El efectivo recibido ($ ${formatArs(enteredCash)}) es menor al Total a Pagar ($ ${formatArs(importe)}). Ingresá el monto entregado o elegí "Efectivo + Posnet" para completar el saldo.`;
        payAlert.hidden = false;
      }
      document.getElementById('pos-pay-entrega-input')?.focus();
      return;
    }

    if (method === 'combinado' && (enteredCash <= 0 || enteredCash >= importe)) {
      if (payAlert) {
        payAlert.textContent = 'En pago combinado, ingresá un importe en Efectivo mayor a $ 0 y menor al Total para enviar la diferencia al Posnet.';
        payAlert.hidden = false;
      }
      document.getElementById('pos-pay-entrega-input')?.focus();
      return;
    }

    const confirmBtn = document.getElementById('btn-confirm-pos-payment');
    if (confirmBtn) confirmBtn.disabled = true;

    if (method === 'qr' || method === 'debito' || method === 'credito' || method === 'combinado') {
      savePosnetForCaja(cajaId, posnet);
    }

    const finalizePosSaleEmission = async (mpApprovedMeta = null) => {
      try {
        // Determinar si es emisión ARCA Fiscal o Comprobante Interno
        const emisionMode = document.querySelector('input[name="pos_pay_emision"]:checked')?.value || 'arca';
        const isFiscal = emisionMode === 'arca';
        const pv = isFiscal ? cfg.pvFiscal : cfg.pvInterno;
        const pvSel = document.getElementById('pos-select-pv');
        if (pvSel) pvSel.value = pv;

        const respIvaRaw = document.getElementById('fact-cli-respiva')?.value || 'Consumidor Final';
        const respIvaUpper = respIvaRaw.toUpperCase();
        const isRespInscEmit = respIvaUpper.includes('INSCRIPTO') && !respIvaUpper.includes('NO INSCRIPTO');
        const letra = isRespInscEmit ? 'A' : 'B';

        const rawTipoComp = document.getElementById('pos-tipo-comp')?.value || 'Factura';
        const tipoBase = isFiscal
          ? (rawTipoComp === 'Comprobante Interno' ? 'Factura' : rawTipoComp)
          : 'Comprobante Interno';
        const tipo = `${tipoBase} ${letra}`;

        const cliente = document.getElementById('pos-cliente-input')?.value.trim().toUpperCase() || 'CONSUMIDOR FINAL';
        const selectedCliIdSnapshot = STATE.factSelectedClientId;
        const rawCliCodInput = String(document.getElementById('fact-cli-codigo')?.value || '').trim();
        const selectedCliObj =
          STATE.clientes.find((c) => Number(c.id) === Number(selectedCliIdSnapshot)) ||
          (rawCliCodInput && rawCliCodInput !== '1'
            ? STATE.clientes.find((c) => String(c.codigo) === rawCliCodInput)
            : null);

        // Construir resumen de Pago y línea de pie de Caja Diaria
        const cajaNum = getCajaDiariaNumber(cajaId);
        const movNro = getNextCajaMovimientoNumber(cajaId, false);
        const cajaDiariaLabel = `CAJA DIARIA ${cajaNum} - Nº: ${String(movNro).padStart(6, '0')}`;

        let medioPagoResumen = 'Efectivo';
        let efectivoAplicado = 0;
        let efectivoRecibido = 0;
        let vuelto = 0;
        let electronicoTipo = '';
        let electronicoImporte = 0;
        let footerValoresLine = '';
        let selectedBankAccount = null;

        if (method === 'efectivo') {
          efectivoAplicado = importe;
          efectivoRecibido = enteredCash;
          vuelto = round2(Math.max(0, enteredCash - importe));
          medioPagoResumen = 'Efectivo';
          footerValoresLine = vuelto > 0
            ? `${cajaDiariaLabel} Efectivo: $${importe.toFixed(2)} (Entrega: $${efectivoRecibido.toFixed(2)} - Vuelto: $${vuelto.toFixed(2)}) -`
            : `${cajaDiariaLabel} Efectivo: $${importe.toFixed(2)} -`;
        } else if (method === 'combinado') {
          efectivoAplicado = enteredCash;
          efectivoRecibido = enteredCash;
          vuelto = 0;
          electronicoTipo = getElectronicLabel(combElec);
          electronicoImporte = round2(importe - efectivoAplicado);
          medioPagoResumen = `Efectivo + ${electronicoTipo} (${posnet})`;
          footerValoresLine = `${cajaDiariaLabel} Efectivo: $${efectivoAplicado.toFixed(2)} / ${electronicoTipo} (${posnet}): $${electronicoImporte.toFixed(2)} -`;
        } else if (method === 'transferencia') {
          const bankIdSel = document.getElementById('pos-pay-banco-select')?.value || '';
          selectedBankAccount = findTransferenciaBankAccount(bankIdSel);
          const shortBank = selectedBankAccount ? formatBankAccountShortLabel(selectedBankAccount) : '';
          medioPagoResumen = shortBank ? `Transferencia (${shortBank})` : 'Transferencia Bancaria';
          footerValoresLine = shortBank
            ? `${cajaDiariaLabel} Transferencia (${shortBank}): $${importe.toFixed(2)} -`
            : `${cajaDiariaLabel} Transferencia Bancaria: $${importe.toFixed(2)} -`;
        } else if (method === 'ctacte') {
          medioPagoResumen = 'Cuenta Corriente';
          footerValoresLine = `${cajaDiariaLabel} Cuenta Corriente: $${importe.toFixed(2)} -`;
        } else {
          electronicoTipo = getElectronicLabel(method);
          electronicoImporte = importe;
          medioPagoResumen = `${electronicoTipo} · ${posnet}`;
          footerValoresLine = `${cajaDiariaLabel} ${electronicoTipo} (${posnet}): $${importe.toFixed(2)} -`;
        }

        if (!Array.isArray(STATE.turnosCajas[cajaId])) {
          STATE.turnosCajas[cajaId] = [];
        }

        const correlKey = getCorrelativoKeyForFact(pv, tipoBase, letra);
        const nro = getNextCorrelativoForFact(pv, tipoBase, letra);
        STATE.factCorrelativos[correlKey] = nro + 1;

        const now = new Date();
        const fechaHora = `${todayFormatted()} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
        const fechaIso = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

        const dtoPje = parseFloat(document.getElementById('fact-dto-pje')?.value || '0') || 0;
        const factorGlobal = 1 + dtoPje / 100;
        let subTotalBruto = 0;
        let totalGravado = 0;
        let totalIva = 0;

        // Descontar stock de los artículos vendidos (permitiendo stock negativo < 0) y guardar detalle fiscal completo para el Ticket / A4
        const dhStockSale = tipoBase === 'Nota de Crédito' ? -1 : 1;
        const itemsSnapshot = STATE.factItems.map((it) => {
          const art = STATE.articulos.find((a) => a.id === it.artId);
          const codeRawItem = String(it.codigo || art?.c || '').trim();
          const codeCleanItem = codeRawItem.replace(/\D/g, '').replace(/^0+/, '');
          const isNonStockConcept = Boolean(
            it.isGeneric ||
            isGenericArticleCode(codeRawItem) ||
            Number(art?.id) === 4407 ||
            Number(art?.id) === 7860 ||
            codeCleanItem === '20' ||
            codeCleanItem === '3000'
          );
          if (art && !isNonStockConcept) {
            const nextSf = round2((Number(art.sf) || 0) - ((Number(it.cantidad) || 0) * dhStockSale));
            art.sf = nextSf;
            art.sc = round2(nextSf - (Number(art.si) || 0));
          }
          const qty = Number(it.cantidad) || 1;
          const unitVenta = Number(it.precioFinal) || 0;
          const descPctItem = Number(it.descPct) || 0;
          const unitAfterItemDesc = unitVenta * (1 - descPctItem / 100);
          const lineFinalBeforeGlobal = round2(qty * unitAfterItemDesc);
          subTotalBruto = round2(subTotalBruto + lineFinalBeforeGlobal);

          const ivaPct = Number(it.ivaPct ?? art?.iva ?? 21) || 21;
          const unitAdjusted = unitAfterItemDesc * factorGlobal;
          const unitNeto = unitAdjusted / (1 + ivaPct / 100);
          const lineAdjusted = qty * unitAdjusted;
          const lineNeto = round2(lineAdjusted / (1 + ivaPct / 100));
          const lineIva = round2(lineAdjusted - lineNeto);

          totalGravado = round2(totalGravado + lineNeto);
          totalIva = round2(totalIva + lineIva);

          const unitCosto = art ? (Number(art.cfn) > 0 ? Number(art.cfn) : round2(unitVenta * 0.72)) : round2(unitVenta * 0.72);
          return {
            artId: it.artId,
            c: it.codigo || art?.c || '',
            n: it.nombre || art?.n || 'ARTÍCULO',
            isGeneric: Boolean(it.isGeneric || isGenericArticleCode(it.codigo || art?.c || '')),
            rId: Number(art?.r) || Number(art?.rId) || 0,
            mId: Number(art?.mk) || Number(art?.mId) || 0,
            pId: Number(art?.p) || Number(art?.pId) || 0,
            qty,
            ivaPct,
            unitCost: unitCosto,
            unitPrice: round2(unitAfterItemDesc),
            unitNeto,
            lineNeto,
            subtotal: lineFinalBeforeGlobal,
            costoTotal: round2(qty * unitCosto)
          };
        });

        const diffRounding = round2(importe - (totalGravado + totalIva));
        if (Math.abs(diffRounding) <= 0.08) {
          totalIva = round2(totalIva + diffRounding);
        }
        const dtoImp = round2(subTotalBruto * (dtoPje / 100));

        const cliDoc = document.getElementById('fact-cli-nrodoc')?.value.trim() || selectedCliObj?.nroDoc || '00.000.000';
        const cliCalle = selectedCliObj?.calle || document.getElementById('fact-cli-calle')?.value.trim() || '';
        const cliNro = selectedCliObj?.numero || document.getElementById('fact-cli-nro')?.value.trim() || '';
        const cliDomicilio = cliCalle && cliCalle !== '...'
          ? `${cliCalle}${cliNro ? ` NRO ${cliNro}` : ''}`
          : 'CONSUMIDOR FINAL';
        const cliLocalidad = selectedCliObj?.localidad
          ? `${selectedCliObj.localidad}(${selectedCliObj.provincia || 'Córdoba'})`
          : 'ALCIRA GIGENA(Córdoba)';

        const emitPendingArca =
          isFiscal &&
          (Boolean(document.getElementById('pos-pay-arca-pendiente-chk')?.checked) ||
            STATE.arcaServicioEstado === 'contingencia');

        const arcaMeta = isFiscal
          ? (emitPendingArca
            ? {
                codArca: letra === 'A'
                  ? (tipoBase === 'Nota de Crédito' ? '03' : tipoBase === 'Nota de Débito' ? '02' : '01')
                  : (tipoBase === 'Nota de Crédito' ? '08' : tipoBase === 'Nota de Débito' ? '07' : '06'),
                cae: '',
                caeVto: '',
                arcaQrUrl: '',
                qrImgSrc: ''
              }
            : computeArcaCodeAndQrData({
                pv,
                nro,
                tipoBase,
                letra,
                importe,
                fechaIso,
                nroDocCliente: cliDoc
              }))
          : { codArca: '99', cae: '', caeVto: '', arcaQrUrl: '', qrImgSrc: '' };

        const obsComprobante = document.getElementById('fact-observacion-txt')?.value.trim().toUpperCase() || '';
        const mpObsSuffix = mpApprovedMeta && mpApprovedMeta.paymentId
          ? `MP OP #${mpApprovedMeta.paymentId}`
          : '';
        const fullObs = [observacionesPago, mpObsSuffix, obsComprobante].filter(Boolean).join(' · ');

        const activeClosureUser = getActiveUserClosureInfo();
        const saleRecord = {
          uid: `VTA-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
          entryType: 'venta',
          cajaId,
          nro,
          pv,
          correlKey,
          numeroCompleto: `${pv}-${String(nro).padStart(8, '0')}`,
          fechaHora,
          fechaIso,
          isFiscal,
          estadoArca: isFiscal ? (emitPendingArca ? 'pendiente' : 'informado') : 'interno',
          tipoBase,
          letra,
          tipo,
          codArca: arcaMeta.codArca,
          cae: arcaMeta.cae,
          caeVto: arcaMeta.caeVto,
          qrImgSrc: arcaMeta.qrImgSrc,
          cliente,
          clienteCodigo: selectedCliObj?.codigo || document.getElementById('fact-cli-codigo')?.value || '1',
          clienteDoc: cliDoc,
          clienteRespIva: respIvaRaw,
          clienteDomicilio: cliDomicilio,
          clienteLocalidad: cliLocalidad,
          clienteTel: selectedCliObj?.telefono || selectedCliObj?.celular || '',
          clienteIibb: selectedCliObj?.nroIibb || '',
          medioPago: medioPagoResumen,
          importe,
          subTotalBruto,
          dtoPje,
          dtoImp,
          totalGravado,
          totalIva,
          itemsCount: itemsSnapshot.length,
          items: itemsSnapshot,
          usuario: activeClosureUser.displayName,
          username: activeClosureUser.username,
          payment: {
            method,
            posnet: (method === 'qr' || method === 'debito' || method === 'credito' || method === 'combinado') ? posnet : '',
            cuentaBancariaId: selectedBankAccount ? String(selectedBankAccount.id || '') : '',
            cuentaBancariaCodigo: selectedBankAccount ? String(selectedBankAccount.codigo || '') : '',
            cuentaBancariaBanco: selectedBankAccount ? String(selectedBankAccount.banco || '') : '',
            cuentaBancariaDenominacion: selectedBankAccount ? String(selectedBankAccount.denominacion || '') : '',
            cuentaBancariaAlias: selectedBankAccount ? String(selectedBankAccount.alias || '') : '',
            cuentaBancariaCbu: selectedBankAccount ? String(selectedBankAccount.cbu || '') : '',
            cuentaBancariaLabel: selectedBankAccount ? formatBankAccountShortLabel(selectedBankAccount) : '',
            mpOrderId: mpApprovedMeta?.orderId || '',
            mpPaymentId: mpApprovedMeta?.paymentId || '',
            efectivoAplicado,
            efectivoRecibido,
            vuelto,
            electronicoTipo,
            electronicoImporte,
            observaciones: fullObs,
            cajaDiariaLabel,
            footerValoresLine
          }
        };

        // 1. Cerrar modal de cobro, registrar venta en la Caja y mostrar el Ticket de inmediato (sin bloqueo de red)
        STATE.turnosCajas[cajaId].unshift(saleRecord);
        STATE.estDatasetCache = null;
        syncComprobanteTransferenciaIntoFondos(saleRecord);

        if (isFiscal && typeof window.registerFiscalSaleInArcaAdmin === 'function') {
          window.registerFiscalSaleInArcaAdmin(saleRecord);
        }

        const autoSumarPts =
          document.getElementById('pos-fid-acreditar-chk')?.checked !== false &&
          document.getElementById('pos-fid-auto-sumar')?.checked !== false;
        const canalPos = document.getElementById('pos-fid-canal-sel')?.value || 'WHATSAPP';
        const autoNotifyPts =
          canalPos !== 'NO_ENVIAR' &&
          (document.getElementById('pos-fid-auto-notify')?.checked === true || canalPos === 'WHATSAPP' || canalPos === 'EMAIL');

        saveCajasState();
        renderCajaPosView();
        resetInvoiceToDefaults();

        if (confirmBtn) confirmBtn.disabled = false;
        document.getElementById('pos-payment-dialog')?.close();

        // Mostrar el Ticket inmediatamente (78mm continuo para Caja 1 y 2 / Reporte A4 para Caja 3)
        openPosTicketDialog(saleRecord, { goToNextSaleOnClose: true });

        // 2. Persistir en segundo plano en el servidor (ventas_db, catalog_db, Cta. Cte. y Puntos Club Cachita)
        const sellerCode = String(
          STATE.currentUser?.vendedorCodigo ||
          ADMIN_DIRECTORY[String(STATE.currentUser?.username || '').toLowerCase()]?.vendedorCodigo ||
          '001'
        );
        const sellerUsername = String(STATE.currentUser?.username || 'sistema');
        fetch('api/ventas.php', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'record_pos_sale',
            sale: {
              ...saleRecord,
              vendedorCodigo: sellerCode,
              vendedorNombre: sellerUsername,
              usuarioDisplay: saleRecord.usuario || sellerUsername,
              usuario: saleRecord.usuario || sellerUsername,
              username: saleRecord.username || sellerUsername
            }
          })
        })
          .then((resVenta) => (resVenta.ok ? resVenta.json() : null))
          .then((ventaData) => {
            if (ventaData && ventaData.ok) {
              if (Number(ventaData.assignedNro) > 0 && Number(ventaData.assignedNro) !== Number(saleRecord.nro)) {
                saleRecord.nro = Number(ventaData.assignedNro);
                saleRecord.numeroCompleto = `${saleRecord.pv}-${String(saleRecord.nro).padStart(8, '0')}`;
                saveCajasState();
              }
              if (ventaData.nextCorrelativos && typeof ventaData.nextCorrelativos === 'object') {
                Object.entries(ventaData.nextCorrelativos).forEach(([k, val]) => {
                  const num = Number(val) || 0;
                  if (num > 0) {
                    OLIVER_NEXT_CORRELATIVOS[k] = Math.max(Number(OLIVER_NEXT_CORRELATIVOS[k]) || 0, num);
                    STATE.factCorrelativos[k] = Math.max(Number(STATE.factCorrelativos[k]) || 0, num);
                  }
                });
              }
              if (ventaData.updatedStocks && typeof ventaData.updatedStocks === 'object') {
                Object.entries(ventaData.updatedStocks).forEach(([aidKey, srvSf]) => {
                  const aidNum = Number(aidKey) || 0;
                  if (aidNum > 0 && Number.isFinite(Number(srvSf))) {
                    const artTarget = STATE.articulos.find((a) => Number(a.id) === aidNum);
                    if (artTarget) {
                      artTarget.sf = round2(Number(srvSf));
                      artTarget.sc = round2(artTarget.sf - (Number(artTarget.si) || 0));
                    }
                  }
                });
                updateKpis();
                if (!document.getElementById('sec-stock-negativo')?.hidden && typeof window.initOrRefreshStockNegativoSection === 'function') {
                  window.initOrRefreshStockNegativoSection();
                }
              }
            }
          })
          .catch(() => {});

        if (method === 'ctacte' && selectedCliIdSnapshot) {
          const tcaPos =
            tipoBase === 'Nota de Crédito'
              ? 'NC'
              : tipoBase === 'Nota de Débito'
                ? 'ND'
                : tipoBase === 'Comprobante Interno'
                  ? 'CI'
                  : 'FA';
          const cleanPvNro = `${pv}-${String(nro).padStart(8, '0')}`;
          const compFormatted = `${tcaPos} ${letra} ${cleanPvNro}`;
          const dh = tipoBase === 'Nota de Crédito' ? -1 : 1;
          fetch('api/clientes.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              action: 'add_ctacte_movement',
              idCliente: selectedCliIdSnapshot,
              movement: {
                cId: selectedCliIdSnapshot,
                imp: importe,
                tcn: `${tipoBase.toUpperCase()} ${letra}`.trim(),
                tca: tcaPos,
                l: letra,
                n: cleanPvNro,
                tipoComp: `${tipoBase.toUpperCase()} ${letra}`.trim(),
                dh,
                comprobante: compFormatted,
                importe,
                obs: fullObs,
                uid: saleRecord.uid || '',
                cae: saleRecord.cae || '',
                caeVto: saleRecord.caeVto || '',
                items: itemsSnapshot
              }
            })
          }).catch(() => {});
        }

        if (
          tipoBase !== 'Nota de Crédito' &&
          selectedCliObj &&
          String(selectedCliObj.codigo) !== '1' &&
          importe > 0
        ) {
          const compPrefix = tipoBase === 'Comprobante Interno' ? 'CI' : 'FA';
          const compFormatted = `${compPrefix} ${letra} ${pv}-${String(nro).padStart(8, '0')}`;
          accreditClientPurchasePoints({
            clientId: selectedCliObj.id,
            montoCompra: importe,
            items: itemsSnapshot,
            fechaIso,
            comprobante: compFormatted,
            observacion: `VENTA POS ${cfg.nombre.toUpperCase()} ($ ${formatArs(importe)})`,
            notify: autoSumarPts && autoNotifyPts,
            canalOverride: canalPos === 'EMAIL' ? 'email' : 'whatsapp'
          }).catch(() => {});
        }
      } finally {
        if (confirmBtn) confirmBtn.disabled = false;
      }
    };

    // Si es Caja con Point Smart de Mercado Pago integrado activo (Caja 1) y no está tildado el bypass manual:
    if (isMpPointIntegratedForCurrentSelection()) {
      const mpElecCode = method === 'combinado' ? combElec : method;
      const mpAmountToSend = method === 'combinado' ? round2(importe - enteredCash) : importe;
      const printOnTerm = Boolean(document.getElementById('pos-mp-print-ticket-chk')?.checked);
      const extRef = `CN-${cajaId.toUpperCase()}-${Date.now()}`;
      await startMpPointIntegratedFlow({
        cajaId,
        amountToSend: mpAmountToSend,
        elecCode: mpElecCode,
        printOnTerminal: printOnTerm,
        externalRef: extRef,
        description: `Casa Nueva Supermercado - ${cfg.nombre}`,
        onApproved: (mpMeta) => {
          finalizePosSaleEmission(mpMeta);
        }
      });
      return;
    }

    await finalizePosSaleEmission(null);
  });

  // Listeners del Modal de Ticket / Reporte (78mm vs A4)
  document.querySelectorAll('input[name="pos_ticket_format"]').forEach((rad) => {
    rad.addEventListener('change', () => {
      const cajaCfg = CAJAS_CONFIG[activeTicketSaleRecord?.cajaId] || { nombre: 'Caja 1' };
      const badgeEl = document.getElementById('pos-ticket-caja-badge');
      if (badgeEl && rad.checked) {
        badgeEl.textContent = `✅ ${cajaCfg.nombre.toUpperCase()} · ${rad.value === 'a4' ? 'REPORTE HOJA A4' : 'TICKET CONTINUO 78mm'}`;
      }
      renderPosTicketPreview();
    });
  });

  document.getElementById('btn-print-pos-ticket')?.addEventListener('click', () => {
    printActivePosTicket();
  });

  document.getElementById('btn-edit-pago-from-ticket')?.addEventListener('click', (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (activeTicketSaleRecord && typeof openEditComprobantePagoDialog === 'function') {
      openEditComprobantePagoDialog(activeTicketSaleRecord);
    }
  });

  document.getElementById('btn-close-pos-ticket')?.addEventListener('click', () => {
    closePosTicketAndContinue();
  });

  document.getElementById('btn-done-pos-ticket')?.addEventListener('click', () => {
    closePosTicketAndContinue();
  });

  document.getElementById('pos-ticket-dialog')?.addEventListener('close', () => {
    const ctacteDlg = document.getElementById('ctacte-dialog');
    if (ctacteDlg && ctacteDlg.dataset.prevClosedby) {
      ctacteDlg.setAttribute('closedby', ctacteDlg.dataset.prevClosedby);
      delete ctacteDlg.dataset.prevClosedby;
    }
    if (ticketShouldAdvanceToNextSale) {
      ticketShouldAdvanceToNextSale = false;
      openClubPrevioScreen(STATE.activeCajaId || 'caja1');
    }
  });

  // Atajos globales de respaldo en Facturación: F10 para emitir, F2 para ir a 1° línea Código (si no fueron reasignados en Atajos)
  document.addEventListener('keydown', (e) => {
    if (e.ctrlKey || e.metaKey || e.altKey || e.shiftKey) return;
    if (document.activeElement === document.getElementById('atajo-tecla')) return;
    const posSec = document.getElementById('sec-caja-pos');
    if (!posSec || posSec.hidden) return;
    const fnKey = String(e.key || '').toUpperCase();
    if ((STATE.atajos || []).some((a) => a.activo !== false && String(a.tecla || '').toUpperCase() === fnKey)) {
      return;
    }
    if (e.key === 'F10') {
      e.preventDefault();
      if (document.getElementById('pos-payment-dialog')?.open) {
        document.getElementById('pos-payment-form')?.requestSubmit();
      } else if (document.getElementById('pos-ticket-dialog')?.open) {
        closePosTicketAndContinue();
      } else {
        document.getElementById('facturacion-form')?.requestSubmit();
      }
    } else if (e.key === 'F2') {
      e.preventDefault();
      focusFirstCodeInput();
    }
  });

  // =========================================================================
  // PLANILLA DE RENDICIÓN DIARIA · CIERRE DE CAJA Y PASO A CAJA CENTRAL
  // - Efectivo: suma de billetes ($ 20.000 a $ 100 · excluye $ 50, $ 20 y $ 10)
  // - Sin Monedas y sin Cheques de 3ros
  // - Tarjetas: Débito, Crédito y QR discriminados por Plataforma de Pago
  // - Otros Valores: Tickets recibidos por el cajero
  // =========================================================================
  function createEmptyBilletesMap() {
    const map = {};
    BILLETES_DENOMINACIONES.forEach((denom) => {
      map[denom] = 0;
    });
    return map;
  }

  function createEmptyPlataformasMap() {
    const map = {};
    PLATAFORMAS_PAGO_CIERRE.forEach((plat) => {
      map[plat] = { debito: 0, credito: 0, qr: 0 };
    });
    return map;
  }

  function clonePlataformasMap(src) {
    const out = createEmptyPlataformasMap();
    if (!src || typeof src !== 'object') return out;
    PLATAFORMAS_PAGO_CIERRE.forEach((plat) => {
      if (src[plat] && typeof src[plat] === 'object') {
        out[plat] = {
          debito: round2(Math.max(0, Number(src[plat].debito) || 0)),
          credito: round2(Math.max(0, Number(src[plat].credito) || 0)),
          qr: round2(Math.max(0, Number(src[plat].qr) || 0))
        };
      }
    });
    return out;
  }

  const CIERRE_STATE = {
    cajaId: 'caja1',
    nextNumero: 1249,
    cajaMovNum: 1,
    billetes: createEmptyBilletesMap(),
    billetesTotalCaja: createEmptyBilletesMap(),
    billetesCambio: createEmptyBilletesMap(),
    draftBilletes: createEmptyBilletesMap(),
    draftBilletesTotalCaja: createEmptyBilletesMap(),
    draftBilletesCambio: createEmptyBilletesMap(),
    plataformas: createEmptyPlataformasMap(),
    draftPlataformas: createEmptyPlataformasMap(),
    tickets: [],
    draftTickets: [],
    activeCentralCierre: null
  };

  function normalizeCierreBilletesTransferidos(c) {
    if (!c || typeof c !== 'object') return c;
    // Reconciliación de Planilla 1260 (Caja 1 · 16/11/2026 15:40 · Samuel Ramadú):
    // Excluir los 26 comprobantes viejos que estaban en localStorage de turnos anteriores y dejar los 48 comprobantes reales del turno
    if (
      Number(c.numeroPlanilla) === 1260 &&
      (Number(c.cantidadComprobantes) === 74 || Math.abs((Number(c.ventasBrutasEfectivo) || 0) - 333668.96) < 0.05)
    ) {
      c.cantidadComprobantes = 48;
      c.subtotalFiscal = 224223.17;
      c.subtotalInterno = 266508.36;
      c.totalFacturadoTurno = 490731.53;
      c.ventasBrutasEfectivo = 206450.05;
      c.notasCreditoEfectivo = 0;
      c.ventasNetasEfectivo = 206450.05;
      c.cobranzasRecibosEfectivo = 0;
      c.ingresosEfectivoBruto = 206450.05;
      c.totalCtaCte = 91081.31;
      const efIni1260 = round2(Number(c.efectivoInicial ?? 125000) || 125000);
      const efCamb1260 = round2(Number(c.efectivoCambio ?? 114400) || 0);
      const efRend1260 = round2(Number(c.efectivoRendicion ?? c.efectivo ?? 110000) || 0);
      const ret1260 = round2((Number(c.retiros ?? c.retirosEfectivoTurno ?? 0) || 0) + (Number(c.egresos ?? 0) || 0));
      c.efectivoEsperadoFinal = round2(efIni1260 + 206450.05 - ret1260);
      c.efectivoEsperadoTraspasoCentral = round2(c.efectivoEsperadoFinal - efCamb1260);
      c.esperadoContadoPos = round2(c.efectivoEsperadoFinal + 193200.17);
      c.diferencia = round2(efRend1260 - c.efectivoEsperadoTraspasoCentral);
      c.diferenciaEfectivo = c.diferencia;
      c.diferenciaTipo = Math.abs(c.diferencia) < 0.01 ? 'EXACTO' : c.diferencia > 0 ? 'EN_MAS' : 'EN_MENOS';
    }
    if (
      Number(c.numeroPlanilla) === 1264 &&
      !c.editedInCentralAt &&
      !c.aperturaEditadaAdminAt &&
      Math.abs((Number(c.efectivoInicial) || 0) - 614200) < 0.05
    ) {
      const efIni1264 = 97800;
      const vBrutas1264 = round2(Number(c.ventasBrutasEfectivo ?? c.ingresosEfectivoBruto ?? 540393.25) || 0);
      const nc1264 = round2(Number(c.notasCreditoEfectivo ?? 0) || 0);
      const cob1264 = round2(Number(c.cobranzasRecibosEfectivo ?? 0) || 0);
      const ret1264 = round2((Number(c.retiros ?? c.retirosEfectivoTurno ?? 0) || 0) + (Number(c.egresos ?? 0) || 0));
      const camb1264 = round2(Number(c.efectivoCambio ?? 118200) || 0);
      const rend1264 = round2(Number(c.efectivoRendicion ?? c.efectivo ?? 504000) || 0);
      c.efectivoInicial = efIni1264;
      c.efectivoEsperadoFinal = round2(efIni1264 + vBrutas1264 + cob1264 - nc1264 - ret1264);
      c.efectivoEsperadoTraspasoCentral = round2(c.efectivoEsperadoFinal - camb1264);
      c.diferencia = round2(rend1264 - c.efectivoEsperadoTraspasoCentral);
      c.diferenciaEfectivo = c.diferencia;
      c.diferenciaTipo = Math.abs(c.diferencia) < 0.01 ? 'EXACTO' : c.diferencia > 0 ? 'EN_MAS' : 'EN_MENOS';
    }
    if (
      Number(c.numeroPlanilla) === 1268 &&
      (Number(c.cantidadComprobantes) === 8 || Math.abs((Number(c.ventasBrutasEfectivo) || 0) - 23727.19) < 0.05)
    ) {
      // Reconciliación de Planilla 1268 (Caja 1 · 18/11/2026 15:40 · José Michelutti):
      // Incluir los 51 comprobantes reales del turno (08:07 a 15:40, CAJA DIARIA 1 - Nº: 002417 al 002467)
      const ctaCteDetalle1268 = [
        { numeroCompleto: '0099-00053406', tipo: 'Comp. Interno B', cliente: 'MICHELUTTI, JOSE IGNACIO', clienteCodigo: '82', fechaHora: '18/11/2026 15:38', importe: 10604.0 },
        { numeroCompleto: '0099-00053405', tipo: 'Comp. Interno B', cliente: 'DEVIA ROXANA GISELLE', clienteCodigo: '5', fechaHora: '18/11/2026 15:38', importe: 2769.45 },
        { numeroCompleto: '0099-00053402', tipo: 'Comp. Interno B', cliente: 'SAMUEL RAMADU', clienteCodigo: '165', fechaHora: '18/11/2026 14:57', importe: 25603.41 },
        { numeroCompleto: '0099-00053377', tipo: 'Comp. Interno B', cliente: 'GHIGLIONE, ANTONIO ANGEL', clienteCodigo: '7', fechaHora: '18/11/2026 11:34', importe: 22595.08 },
        { numeroCompleto: '0099-00053374', tipo: 'Comp. Interno B', cliente: 'RIVERO, ARIEL IGNACIO', clienteCodigo: '299', fechaHora: '18/11/2026 10:12', importe: 33600.0 },
        { numeroCompleto: '0099-00053373', tipo: 'Comp. Interno B', cliente: 'RIVERO, ARIEL IGNACIO', clienteCodigo: '299', fechaHora: '18/11/2026 10:11', importe: 50190.22 }
      ];
      const plataformas1268 = {
        'Mercado Pago': { debito: 103918.87, credito: 0, qr: 86168.78 },
        SiPago: { debito: 0, credito: 0, qr: 0 },
        PayWay: { debito: 0, credito: 0, qr: 26720.99 },
        'Otra Plataforma': { debito: 0, credito: 0, qr: 0 }
      };
      c.cantidadComprobantes = 51;
      c.subtotalFiscal = 210501.32;
      c.subtotalInterno = 432655.63;
      c.totalFacturadoTurno = 643156.95;
      c.ventasBrutasEfectivo = 287293.47;
      c.notasCreditoEfectivo = 6307.32;
      c.ventasNetasEfectivo = 280986.15;
      c.cobranzasRecibosEfectivo = 0;
      c.ingresosEfectivoBruto = 280986.15;
      c.totalCtaCte = 145362.16;
      c.ctaCteCount = 6;
      c.ctaCteDetalle = ctaCteDetalle1268;

      if (!c.editedInCentralAt || Math.abs((Number(c.tarjetasTotal) || 0) - 8660.33) < 0.05) {
        c.plataformas = clonePlataformasMap(plataformas1268);
        c.tarjetasDebito = 103918.87;
        c.tarjetasCredito = 0;
        c.tarjetasQr = 112889.77;
        c.tarjetasTotal = 216808.64;
        c.tarjetas = 216808.64;
      }
      if (c.arqueoOriginalCajero && typeof c.arqueoOriginalCajero === 'object') {
        c.arqueoOriginalCajero.plataformas = clonePlataformasMap(plataformas1268);
        c.arqueoOriginalCajero.tarjetasDebito = 103918.87;
        c.arqueoOriginalCajero.tarjetasCredito = 0;
        c.arqueoOriginalCajero.tarjetasQr = 112889.77;
        c.arqueoOriginalCajero.tarjetasTotal = 216808.64;
        c.arqueoOriginalCajero.totalCtaCte = 145362.16;
        c.arqueoOriginalCajero.ctaCteCount = 6;
        c.arqueoOriginalCajero.ctaCteDetalle = ctaCteDetalle1268.map((d) => ({ ...d }));
        const efRendOrig1268 = round2(Number(c.arqueoOriginalCajero.efectivoRendicion ?? c.efectivoRendicion ?? 250000) || 0);
        const otrosOrig1268 = round2(Number(c.arqueoOriginalCajero.otrosValoresTotal ?? 0) || 0);
        const transfOrig1268 = round2(Number(c.arqueoOriginalCajero.transferencia ?? 0) || 0);
        c.arqueoOriginalCajero.total = round2(efRendOrig1268 + 216808.64 + otrosOrig1268 + transfOrig1268);
      }

      const efIni1268 = round2(Number(c.efectivoInicial ?? 105800) || 105800);
      const efCamb1268 = round2(Number(c.efectivoCambio ?? 44800) || 0);
      const efRend1268 = round2(Number(c.efectivoRendicion ?? c.efectivo ?? 250000) || 0);
      const efFinal1268 = round2(Number(c.efectivoFinal ?? (efRend1268 + efCamb1268)) || 0);
      const ret1268 = round2((Number(c.retiros ?? c.retirosEfectivoTurno ?? 0) || 0) + (Number(c.egresos ?? 0) || 0));
      const tarjTot1268 = round2(Number(c.tarjetasTotal ?? 216808.64) || 0);
      const otrosTot1268 = round2(Number(c.otrosValoresTotal ?? c.otrosValores ?? 0) || 0);
      const transf1268 = round2(Number(c.transferencia ?? 0) || 0);

      c.efectivoEsperadoFinal = round2(efIni1268 + 287293.47 - 6307.32 - ret1268);
      c.efectivoEsperadoTraspasoCentral = round2(c.efectivoEsperadoFinal - efCamb1268);
      c.esperadoContadoPos = round2(c.efectivoEsperadoFinal + tarjTot1268 + transf1268);
      c.diferencia = round2(efRend1268 - c.efectivoEsperadoTraspasoCentral);
      c.diferenciaEfectivo = c.diferencia;
      c.diferenciaTipo = Math.abs(c.diferencia) < 0.01 ? 'EXACTO' : c.diferencia > 0 ? 'EN_MAS' : 'EN_MENOS';
      c.total = round2(efRend1268 + tarjTot1268 + otrosTot1268 + transf1268);
      c.totalGeneral = c.total;
      c.totalRecontado = round2(efFinal1268 + tarjTot1268 + otrosTot1268 + transf1268);
    }
    if (c.billetesDeclaradosTransferidos === true) return c;

    const rawTotalMap = {};
    const rawCambMap = {};
    let hasCambio = false;
    let allGeCambio = true;
    let hasEqualNonZero = false;

    BILLETES_DENOMINACIONES.forEach((denom) => {
      let qR = 0;
      let qC = 0;
      if (Array.isArray(c.billetes)) {
        const row = c.billetes.find((b) => Number(b?.denom) === Number(denom));
        if (row) {
          qR = Math.max(0, Math.floor(Number(row.cantidadRendicion ?? row.cantidad ?? 0) || 0));
          qC = Math.max(0, Math.floor(Number(row.cantidadCambio ?? 0) || 0));
        }
      } else if (c.billetes && typeof c.billetes === 'object') {
        qR = Math.max(0, Math.floor(Number(c.billetes[denom]) || 0));
      }
      if (qC === 0 && c.billetesCambio && typeof c.billetesCambio === 'object' && !Array.isArray(c.billetesCambio)) {
        qC = Math.max(0, Math.floor(Number(c.billetesCambio[denom]) || 0));
      }
      if (qC === 0 && c.billetesCambioDeclaradosCajero && typeof c.billetesCambioDeclaradosCajero === 'object') {
        qC = Math.max(0, Math.floor(Number(c.billetesCambioDeclaradosCajero[denom]) || 0));
      }
      rawTotalMap[denom] = qR;
      rawCambMap[denom] = qC;
      if (qC > 0) {
        hasCambio = true;
        if (qR < qC) {
          allGeCambio = false;
        }
        if (qR === qC) {
          hasEqualNonZero = true;
        }
      }
    });

    if (hasCambio && allGeCambio && hasEqualNonZero) {
      let sumRend = 0;
      let sumCamb = 0;
      let cntRend = 0;
      let cntCamb = 0;
      const transfMap = {};
      const cambMap = {};
      const totCajaMap = {};

      c.billetes = BILLETES_DENOMINACIONES.map((denom) => {
        const qTot = rawTotalMap[denom];
        const qCamb = rawCambMap[denom];
        const qTransf = Math.max(0, qTot - qCamb);
        const subTransf = round2(denom * qTransf);
        const subCamb = round2(denom * qCamb);
        const subTot = round2(denom * qTot);
        transfMap[denom] = qTransf;
        cambMap[denom] = qCamb;
        totCajaMap[denom] = qTot;
        sumRend = round2(sumRend + subTransf);
        sumCamb = round2(sumCamb + subCamb);
        cntRend += qTransf;
        cntCamb += qCamb;
        return {
          denom,
          nombre: `Billete de $ ${denom.toLocaleString('es-AR')}`,
          cantidad: qTransf,
          subtotal: subTransf,
          cantidadRendicion: qTransf,
          subtotalRendicion: subTransf,
          cantidadCambio: qCamb,
          subtotalCambio: subCamb,
          cantidadTotal: qTot,
          subtotalTotal: subTot
        };
      });

      c.billetesTotalCaja = { ...totCajaMap };
      c.billetesDeclaradosCajero = { ...transfMap };
      c.billetesCambioDeclaradosCajero = { ...cambMap };
      c.billetesRecontadosCentral = { ...transfMap };
      c.billetesCambio = { ...cambMap };
      c.billetesCantidadRendicion = cntRend;
      c.billetesCantidadCambio = cntCamb;
      c.billetesCantidad = cntRend + cntCamb;

      c.efectivo = sumRend;
      c.efectivoRendicion = sumRend;
      c.efectivoDeclaradoCajero = sumRend;
      c.efectivoCambio = sumCamb;
      c.efectivoCambioDeclaradoCajero = sumCamb;
      c.efectivoFinal = round2(sumRend + sumCamb);
      c.efectivoFisicoTotal = c.efectivoFinal;

      const efIni = round2(Number(c.efectivoInicial ?? 0) || 0);
      const vBrutas = round2(Number(c.ventasBrutasEfectivo ?? c.ingresosEfectivoBruto ?? 0) || 0);
      const ncEfec = round2(Number(c.notasCreditoEfectivo ?? 0) || 0);
      const cobRec = round2(Number(c.cobranzasRecibosEfectivo ?? 0) || 0);
      const retEfec = round2((Number(c.retiros ?? c.retirosEfectivoTurno ?? 0) || 0) + (Number(c.egresos ?? 0) || 0));
      const efEspFinal = typeof c.efectivoEsperadoFinal === 'number'
        ? round2(c.efectivoEsperadoFinal)
        : round2(efIni + vBrutas + cobRec - ncEfec - retEfec);
      c.efectivoEsperadoFinal = efEspFinal;
      c.efectivoEsperadoTraspasoCentral = round2(efEspFinal - sumCamb);
      c.diferencia = round2(sumRend - c.efectivoEsperadoTraspasoCentral);
      c.diferenciaEfectivo = c.diferencia;
      c.diferenciaTipo = Math.abs(c.diferencia) < 0.01 ? 'EXACTO' : c.diferencia > 0 ? 'EN_MAS' : 'EN_MENOS';

      const tarjTot = round2(Number(c.tarjetasTotal ?? c.tarjetas ?? 0) || 0);
      const otrosTot = round2(Number(c.otrosValoresTotal ?? c.otrosValores ?? 0) || 0);
      const transfBanc = round2(Number(c.transferencia ?? 0) || 0);
      c.total = round2(sumRend + tarjTot + otrosTot + transfBanc);
      c.totalGeneral = c.total;
      c.totalRecontado = round2(c.efectivoFinal + tarjTot + otrosTot + transfBanc);

      if (c.arqueoOriginalCajero && typeof c.arqueoOriginalCajero === 'object') {
        c.arqueoOriginalCajero.efectivoRendicion = sumRend;
        c.arqueoOriginalCajero.efectivoCambio = sumCamb;
        c.arqueoOriginalCajero.efectivoFinal = c.efectivoFinal;
        c.arqueoOriginalCajero.billetes = c.billetes.map((b) => ({ ...b }));
        c.arqueoOriginalCajero.billetesTotalCaja = { ...totCajaMap };
        c.arqueoOriginalCajero.billetesDeclaradosCajero = { ...transfMap };
        c.arqueoOriginalCajero.billetesCambioDeclaradosCajero = { ...cambMap };
        c.arqueoOriginalCajero.total = c.total;
      }
    }

    c.billetesDeclaradosTransferidos = true;
    return c;
  }
  window.normalizeCierreBilletesTransferidos = normalizeCierreBilletesTransferidos;

  if (Array.isArray(STATE.cierresCajaCentral)) {
    STATE.cierresCajaCentral.forEach((c) => normalizeCierreBilletesTransferidos(c));
  }

  function getClosureKey(c) {
    if (!c || typeof c !== 'object') return '';
    if (c.uid) return String(c.uid);
    if (c.numeroPlanilla) return `NP-${c.numeroPlanilla}-${c.cajaId || ''}`;
    return `ID-${c.id || ''}-${c.fechaHora || ''}-${c.cajaId || ''}`;
  }

  function getEfectivoInicialForCaja(cajaId) {
    const activeAp = typeof getActiveTurnoAperturaForCaja === 'function'
      ? getActiveTurnoAperturaForCaja(cajaId)
      : null;
    if (activeAp && typeof activeAp.efectivoConfirmado === 'number') {
      return round2(activeAp.efectivoConfirmado);
    }
    if (STATE.efectivoInicialPorCaja && typeof STATE.efectivoInicialPorCaja[cajaId] === 'number' && STATE.efectivoInicialPorCaja[cajaId] > 0) {
      return round2(STATE.efectivoInicialPorCaja[cajaId]);
    }
    const cierres = Array.isArray(STATE.cierresCajaCentral) ? STATE.cierresCajaCentral : [];
    const lastCierre = cierres.find(
      (c) => c && c.cajaId === cajaId && (c.tipoRendicion || 'Cierre de caja') === 'Cierre de caja' && typeof c.efectivoCambio !== 'undefined'
    );
    if (lastCierre) {
      return round2(Number(lastCierre.efectivoCambio) || 0);
    }
    return round2(Number(STATE.efectivoInicialPorCaja?.[cajaId]) || 0);
  }

  async function syncCierresCajaFromServer() {
    try {
      const resp = await fetch('api/ventas.php?action=cierres', { cache: 'no-store' });
      if (!resp.ok) return;
      const data = await resp.json();
      if (!data || !data.ok) return;

      if (Number(data.nextNumero) > 0) {
        CIERRE_STATE.nextNumero = Math.max(CIERRE_STATE.nextNumero, Number(data.nextNumero));
      }

      if (data.nextCorrelativos && typeof data.nextCorrelativos === 'object') {
        Object.entries(data.nextCorrelativos).forEach(([k, val]) => {
          const num = Number(val) || 0;
          if (num > 0) {
            OLIVER_NEXT_CORRELATIVOS[k] = Math.max(Number(OLIVER_NEXT_CORRELATIVOS[k]) || 0, num);
            STATE.factCorrelativos[k] = Math.max(Number(STATE.factCorrelativos[k]) || 0, num);
          }
        });
      }

      if (data.comprobantesPorCaja && typeof data.comprobantesPorCaja === 'object') {
        if (STATE.ventasDb && typeof STATE.ventasDb === 'object') {
          STATE.ventasDb.comprobantesPorCaja = data.comprobantesPorCaja;
        }
        syncTurnosCajasFromServerMap(data.comprobantesPorCaja);
      }

      if (data.efectivoInicialPorCaja && typeof data.efectivoInicialPorCaja === 'object') {
        STATE.efectivoInicialPorCaja = {
          caja1: round2(Number(data.efectivoInicialPorCaja.caja1) || 0),
          caja2: round2(Number(data.efectivoInicialPorCaja.caja2) || 0),
          caja3: round2(Number(data.efectivoInicialPorCaja.caja3) || 0)
        };
      }

      if (Array.isArray(data.aperturasCajaCentral)) {
        STATE.aperturasCajaCentral = data.aperturasCajaCentral;
        if (typeof normalizeClientAperturasState === 'function') {
          normalizeClientAperturasState();
        }
      }

      const serverList = Array.isArray(data.cierres)
        ? data.cierres
        : Array.isArray(data.cierresCajaCentral)
          ? data.cierresCajaCentral
          : [];
      if (serverList.length > 0) {
        const localList = Array.isArray(STATE.cierresCajaCentral) ? STATE.cierresCajaCentral : [];
        const localByKey = new Map();
        const localByPlanilla = new Map();
        localList.forEach((loc) => {
          if (!loc) return;
          normalizeCierreBilletesTransferidos(loc);
          const k = getClosureKey(loc);
          if (k) localByKey.set(k, loc);
          const pNum = Number(loc.numeroPlanilla || 0);
          if (pNum > 0) localByPlanilla.set(pNum, loc);
        });
        const seen = new Set();
        const merged = [];
        [...serverList, ...localList].forEach((rawItem) => {
          if (!rawItem) return;
          normalizeCierreBilletesTransferidos(rawItem);
          const key = getClosureKey(rawItem);
          const pNum = Number(rawItem.numeroPlanilla || 0);
          const dedupKey = pNum > 0 ? `PLAN-${pNum}-${rawItem.cajaId || ''}` : key;
          if (!dedupKey || seen.has(dedupKey)) return;
          seen.add(dedupKey);
          const localMatch = localByKey.get(key) || (pNum > 0 ? localByPlanilla.get(pNum) : null);
          let item = rawItem;
          if (localMatch) {
            if (localMatch.editadoAt && (!rawItem.editadoAt || localMatch.editadoAt >= rawItem.editadoAt)) {
              item = normalizeCierreBilletesTransferidos({ ...rawItem, ...localMatch });
            }
            if (localMatch.confirmadoCajaCentral && !item.confirmadoCajaCentral) {
              item = {
                ...item,
                confirmadoCajaCentral: true,
                estadoRecepcion: 'CONFIRMADA',
                confirmadoAt: localMatch.confirmadoAt || item.confirmadoAt,
                confirmadoPor: localMatch.confirmadoPor || item.confirmadoPor
              };
            }
          }
          merged.push(item);
          if (Number(item.numeroPlanilla) >= CIERRE_STATE.nextNumero) {
            CIERRE_STATE.nextNumero = Number(item.numeroPlanilla) + 1;
          }
        });
        STATE.cierresCajaCentral = merged;
        saveCajasState();
        const centralSec = document.getElementById('sec-caja-central');
        if (centralSec && !centralSec.hidden) {
          renderCajaCentralView();
        }
      }
    } catch {}
  }

  syncCierresCajaFromServer();

  function getActiveUserClosureInfo() {
    let activeUser = STATE.currentUser || null;
    if (!activeUser) {
      try {
        const raw = getPersistedAdminSessionRaw();
        if (raw) activeUser = JSON.parse(raw);
      } catch {}
    }
    const username = String(activeUser?.username || '').trim().toLowerCase();
    const dirRecord = username ? ADMIN_DIRECTORY[username] : null;
    const displayName = String(
      activeUser?.displayName ||
      activeUser?.name ||
      dirRecord?.name ||
      document.getElementById('user-display-name')?.textContent ||
      'ADMINISTRADOR'
    ).trim().toUpperCase();
    return { username, displayName };
  }

  function doesTurnoItemBelongToActiveUser(item, activeUserInfo = null) {
    if (!item || typeof item !== 'object') return false;
    const info = activeUserInfo || getActiveUserClosureInfo();
    const itemUname = String(item.username || item.vendedorNombre || '').trim().toLowerCase();
    if (!info.username) return true;
    if (!itemUname || itemUname === 'sistema' || itemUname === 'administrador') return true;
    return itemUname === info.username;
  }

  function computeShiftExpectedBreakdown(cajaId) {
    const cfg = CAJAS_CONFIG[cajaId];
    const rawTurnoItems = Array.isArray(STATE.turnosCajas[cajaId]) ? STATE.turnosCajas[cajaId] : [];
    const serverCajaItems = Array.isArray(STATE.ventasDb?.comprobantesPorCaja?.[cajaId])
      ? STATE.ventasDb.comprobantesPorCaja[cajaId]
      : [];
    // Combinar comprobantes abiertos (!cerradoEnTurno) en memoria con los del servidor deduplicados por clave
    const seenKeys = new Set();
    const turnoItems = [];
    [...rawTurnoItems, ...serverCajaItems].forEach((it) => {
      if (!it || it.cerradoEnTurno) return;
      const k = getTurnoComprobanteUniqueKey(it);
      if (k && seenKeys.has(k)) return;
      if (k) seenKeys.add(k);
      turnoItems.push(it);
    });
    const plataformas = createEmptyPlataformasMap();

    const efectivoInicial = getEfectivoInicialForCaja(cajaId);
    let ventasBrutasEfectivo = 0;
    let notasCreditoEfectivo = 0;
    let cobranzasRecibosEfectivo = 0;
    let totalRetirosEfectivo = 0;
    let esperadoTarjetas = 0;
    let esperadoTransferencia = 0;
    let totalCtaCte = 0;
    let ctaCteCount = 0;
    const ctaCteDetalle = [];
    let subtotalFiscal = 0;
    let subtotalInterno = 0;
    let ventasCount = 0;
    let notasCreditoCount = 0;
    let recibosCount = 0;
    let retirosCount = 0;
    let efectivoOpsCount = 0;

    const addCashMovement = (entryType, isNC, amount) => {
      const val = round2(Math.max(0, Number(amount) || 0));
      if (val <= 0) return;
      efectivoOpsCount++;
      if (entryType === 'recibo') {
        cobranzasRecibosEfectivo = round2(cobranzasRecibosEfectivo + val);
      } else if (isNC) {
        notasCreditoEfectivo = round2(notasCreditoEfectivo + val);
      } else {
        ventasBrutasEfectivo = round2(ventasBrutasEfectivo + val);
      }
    };

    turnoItems.forEach((item) => {
      const entryType = String(item.entryType || 'venta').toLowerCase();
      const imp = round2(Math.abs(Number(item.importe) || 0));
      const tipoStr = String(item.tipoBase || item.tipo || '');
      const isNC = /cr[eé]dito/i.test(tipoStr);
      const sign = isNC ? -1 : 1;

      if (entryType === 'retiro') {
        totalRetirosEfectivo = round2(totalRetirosEfectivo + imp);
        retirosCount++;
        return;
      }

      if (entryType === 'recibo') {
        recibosCount++;
      } else {
        ventasCount++;
        if (isNC) notasCreditoCount++;
        if (cfg && item.pv === cfg.pvFiscal) subtotalFiscal = round2(subtotalFiscal + imp * sign);
        else subtotalInterno = round2(subtotalInterno + imp * sign);
      }

      const p = item.payment;
      const mp = String(item.medioPago || '').toLowerCase();
      const isCtaCteSale =
        entryType !== 'recibo' &&
        ((p && typeof p === 'object' && String(p.method || '').toLowerCase() === 'ctacte') ||
          mp.includes('cuenta corriente') ||
          mp.includes('cta. cte') ||
          mp.includes('cta cte'));

      // Las ventas en Cuenta Corriente NUNCA son movimiento de efectivo (solo generan ingreso de caja cuando se emite un Recibo de Pago)
      if (isCtaCteSale) {
        totalCtaCte = round2(totalCtaCte + imp * sign);
        ctaCteCount++;
        const nroComp = item.numeroCompleto || `${String(item.pv || '').padStart(4, '0')}-${String(item.nro || '').padStart(8, '0')}`;
        const tipoLbl = String(item.tipo || `${item.tipoBase || 'Factura'} ${item.letra || 'B'}`).trim();
        ctaCteDetalle.push({
          numeroCompleto: nroComp,
          tipo: tipoLbl,
          cliente: String(item.cliente || 'CLIENTE').trim().toUpperCase(),
          clienteCodigo: String(item.clienteCodigo || ''),
          fechaHora: String(item.fechaHora || ''),
          importe: round2(imp * sign)
        });
        return;
      }

      if (p && typeof p === 'object') {
        const pMethod = String(p.method || '').toLowerCase();
        const platName = PLATAFORMAS_PAGO_CIERRE.includes(p.posnet) ? p.posnet : 'Otra Plataforma';
        if (pMethod === 'efectivo') {
          addCashMovement(entryType, isNC, imp);
        } else if (pMethod === 'transferencia') {
          esperadoTransferencia = round2(esperadoTransferencia + imp * sign);
        } else if (pMethod === 'debito') {
          plataformas[platName].debito = round2(plataformas[platName].debito + imp * sign);
          esperadoTarjetas = round2(esperadoTarjetas + imp * sign);
        } else if (pMethod === 'credito') {
          plataformas[platName].credito = round2(plataformas[platName].credito + imp * sign);
          esperadoTarjetas = round2(esperadoTarjetas + imp * sign);
        } else if (pMethod === 'qr') {
          plataformas[platName].qr = round2(plataformas[platName].qr + imp * sign);
          esperadoTarjetas = round2(esperadoTarjetas + imp * sign);
        } else if (pMethod === 'combinado') {
          const cashPart = round2(Number(p.efectivoAplicado) || 0);
          const elecPart = round2(Number(p.electronicoImporte) || Math.max(0, imp - cashPart));
          addCashMovement(entryType, isNC, cashPart);
          esperadoTarjetas = round2(esperadoTarjetas + elecPart * sign);
          const eTipo = String(p.electronicoTipo || '').toLowerCase();
          if (eTipo.includes('débito') || eTipo.includes('debito')) {
            plataformas[platName].debito = round2(plataformas[platName].debito + elecPart * sign);
          } else if (eTipo.includes('crédito') || eTipo.includes('credito')) {
            plataformas[platName].credito = round2(plataformas[platName].credito + elecPart * sign);
          } else {
            plataformas[platName].qr = round2(plataformas[platName].qr + elecPart * sign);
          }
        } else if (pMethod === 'ctacte') {
          totalCtaCte = round2(totalCtaCte + imp * sign);
        } else if (mp.includes('transferencia')) {
          esperadoTransferencia = round2(esperadoTransferencia + imp * sign);
        } else if (mp.includes('débito') || mp.includes('debito')) {
          plataformas[platName].debito = round2(plataformas[platName].debito + imp * sign);
          esperadoTarjetas = round2(esperadoTarjetas + imp * sign);
        } else if (mp.includes('crédito') || mp.includes('credito')) {
          plataformas[platName].credito = round2(plataformas[platName].credito + imp * sign);
          esperadoTarjetas = round2(esperadoTarjetas + imp * sign);
        } else if (mp.includes('qr')) {
          plataformas[platName].qr = round2(plataformas[platName].qr + imp * sign);
          esperadoTarjetas = round2(esperadoTarjetas + imp * sign);
        } else {
          addCashMovement(entryType, isNC, imp);
        }
      } else {
        const platName = mp.includes('mercado pago')
          ? 'Mercado Pago'
          : mp.includes('sipago')
            ? 'SiPago'
            : mp.includes('payway')
              ? 'PayWay'
              : 'Otra Plataforma';
        if (mp.includes('cuenta corriente') || mp.includes('cta. cte') || mp.includes('cta cte')) {
          totalCtaCte = round2(totalCtaCte + imp * sign);
        } else if (mp.includes('transferencia')) {
          esperadoTransferencia = round2(esperadoTransferencia + imp * sign);
        } else if (mp.includes('débito') || mp.includes('debito')) {
          plataformas[platName].debito = round2(plataformas[platName].debito + imp * sign);
          esperadoTarjetas = round2(esperadoTarjetas + imp * sign);
        } else if (mp.includes('crédito') || mp.includes('credito')) {
          plataformas[platName].credito = round2(plataformas[platName].credito + imp * sign);
          esperadoTarjetas = round2(esperadoTarjetas + imp * sign);
        } else if (mp.includes('qr')) {
          plataformas[platName].qr = round2(plataformas[platName].qr + imp * sign);
          esperadoTarjetas = round2(esperadoTarjetas + imp * sign);
        } else {
          addCashMovement(entryType, isNC, imp);
        }
      }
    });

    ventasBrutasEfectivo = round2(ventasBrutasEfectivo);
    notasCreditoEfectivo = round2(notasCreditoEfectivo);
    const ventasNetasEfectivo = round2(ventasBrutasEfectivo - notasCreditoEfectivo);
    cobranzasRecibosEfectivo = round2(cobranzasRecibosEfectivo);
    const ingresosEfectivo = round2(ventasNetasEfectivo + cobranzasRecibosEfectivo);
    totalRetirosEfectivo = round2(totalRetirosEfectivo);
    // Ecuación de Efectivo en Caja: + Dinero de Apertura + Facturas A+B - Notas de Crédito A+B + Cobranzas Recibos - Retiros
    const esperadoEfectivo = round2(efectivoInicial + ventasBrutasEfectivo + cobranzasRecibosEfectivo - notasCreditoEfectivo - totalRetirosEfectivo);
    esperadoTarjetas = round2(esperadoTarjetas);
    esperadoTransferencia = round2(esperadoTransferencia);
    const esperadoContadoPos = round2(esperadoEfectivo + esperadoTarjetas + esperadoTransferencia);
    const esperadoBrutoPos = round2(ingresosEfectivo + esperadoTarjetas + esperadoTransferencia);

    return {
      turnoCount: turnoItems.length,
      ventasCount,
      notasCreditoCount,
      recibosCount,
      retirosCount,
      efectivoOpsCount,
      plataformas,
      efectivoInicial,
      ventasBrutasEfectivo,
      notasCreditoEfectivo,
      ventasNetasEfectivo,
      cobranzasRecibosEfectivo,
      ingresosEfectivo,
      totalRetirosEfectivo,
      esperadoEfectivo,
      esperadoTarjetas,
      esperadoTransferencia,
      esperadoContadoPos,
      esperadoBrutoPos,
      totalCtaCte: round2(totalCtaCte),
      ctaCteCount,
      ctaCteDetalle,
      subtotalFiscal: round2(subtotalFiscal),
      subtotalInterno: round2(subtotalInterno),
      totalFacturadoTurno: round2(subtotalFiscal + subtotalInterno),
      firstDate: turnoItems.length > 0 && turnoItems[turnoItems.length - 1]?.fechaHora
        ? String(turnoItems[turnoItems.length - 1].fechaHora).slice(0, 10)
        : todayFormatted()
    };
  }

  function sumBilletesMap(map) {
    let total = 0;
    let totalCount = 0;
    BILLETES_DENOMINACIONES.forEach((denom) => {
      const qty = Math.max(0, Math.floor(Number(map?.[denom]) || 0));
      totalCount += qty;
      total += denom * qty;
    });
    return { total: round2(total), totalCount };
  }

  function sumPlataformasMap(map) {
    let debito = 0;
    let credito = 0;
    let qr = 0;
    PLATAFORMAS_PAGO_CIERRE.forEach((plat) => {
      const row = map?.[plat] || { debito: 0, credito: 0, qr: 0 };
      debito += Number(row.debito) || 0;
      credito += Number(row.credito) || 0;
      qr += Number(row.qr) || 0;
    });
    debito = round2(debito);
    credito = round2(credito);
    qr = round2(qr);
    return {
      debito,
      credito,
      qr,
      total: round2(debito + credito + qr)
    };
  }

  function sumTicketsList(list) {
    if (!Array.isArray(list)) return 0;
    return round2(list.reduce((acc, t) => acc + (Number(t.importe) || 0), 0));
  }

  function recalcCierreCajaTotals() {
    const cajaId = CIERRE_STATE.cajaId || STATE.activeCajaId || 'caja1';
    const expected = computeShiftExpectedBreakdown(cajaId);

    const billetesRendicionRes = sumBilletesMap(CIERRE_STATE.billetes);
    const billetesCambioRes = sumBilletesMap(CIERRE_STATE.billetesCambio);
    const efectivoRendicion = billetesRendicionRes.total;
    const efectivoCambio = billetesCambioRes.total;
    const efectivoFinal = round2(efectivoRendicion + efectivoCambio);
    const totalBilletesCount = billetesRendicionRes.totalCount + billetesCambioRes.totalCount;

    const tarjetasRes = sumPlataformasMap(CIERRE_STATE.plataformas);
    const otrosTotal = sumTicketsList(CIERRE_STATE.tickets);

    const transferencia = parsePosMoneyInput(document.getElementById('cierre-val-transferencia')?.value || 0);
    const egresos = parsePosMoneyInput(document.getElementById('cierre-val-egresos')?.value || 0);
    const retiros = parsePosMoneyInput(document.getElementById('cierre-val-retiros')?.value || 0);

    // Total de valores que pasan efectivamente a Caja Central
    const totalValoresEnMano = round2(efectivoRendicion + tarjetasRes.total + otrosTotal + transferencia);

    // Ecuación de Cierre de Caja:
    // + Dinero de Apertura de Caja (+)
    // + Facturas A+B (sean ARCA o no) (+) [+ Cobranzas de Recibos en Efectivo]
    // - Notas de Crédito A+B (sean ARCA o no) (-)
    // - Retiros de Caja (-)
    // - Dinero Cambio Caja (-)
    // = Dinero traspasado a Caja Central (=) (sobre este monto se determinan las diferencias)
    const efectivoEsperadoFinal = round2(
      expected.efectivoInicial +
      expected.ventasBrutasEfectivo +
      expected.cobranzasRecibosEfectivo -
      expected.notasCreditoEfectivo -
      retiros -
      egresos
    );
    const efectivoEsperadoTraspasoCentral = round2(efectivoEsperadoFinal - efectivoCambio);
    const diferencia = round2(efectivoRendicion - efectivoEsperadoTraspasoCentral);

    const inpEfectivo = document.getElementById('cierre-val-efectivo');
    const inpCambio = document.getElementById('cierre-val-cambio');
    const subEfectivo = document.getElementById('cierre-sub-efectivo');
    if (inpEfectivo) inpEfectivo.value = formatArs(efectivoRendicion);
    if (inpCambio) inpCambio.value = formatArs(efectivoCambio);
    if (subEfectivo) {
      subEfectivo.textContent = totalBilletesCount > 0
        ? `${totalBilletesCount} billete(s) · Pasa a Caja Central: $ ${formatArs(efectivoRendicion)} · Cambio en Caja: $ ${formatArs(efectivoCambio)}`
        : `Sin billetes cargados · Pasa a Caja Central: $ 0,00`;
    }

    const inpTarjetas = document.getElementById('cierre-val-tarjetas');
    const subTarjetas = document.getElementById('cierre-sub-tarjetas');
    if (inpTarjetas) inpTarjetas.value = formatArs(tarjetasRes.total);
    if (subTarjetas) {
      subTarjetas.textContent = `Débito: $ ${formatArs(tarjetasRes.debito)} · Crédito: $ ${formatArs(tarjetasRes.credito)} · QR: $ ${formatArs(tarjetasRes.qr)}`;
    }

    const inpOtros = document.getElementById('cierre-val-otros');
    const subOtros = document.getElementById('cierre-sub-otros');
    if (inpOtros) inpOtros.value = formatArs(otrosTotal);
    if (subOtros) {
      const tLen = CIERRE_STATE.tickets.length;
      subOtros.textContent = tLen > 0
        ? `${tLen} ticket(s) recibido(s) por el cajero`
        : '0 tickets cargados';
    }

    const grandTotalEl = document.getElementById('cierre-grand-total');
    if (grandTotalEl) {
      grandTotalEl.textContent = formatArs(totalValoresEnMano);
    }

    return {
      expected,
      efectivo: efectivoRendicion,
      efectivoRendicion,
      efectivoCambio,
      efectivoFinal,
      efectivoEsperadoFinal,
      efectivoEsperadoTraspasoCentral,
      billetesCount: totalBilletesCount,
      billetesRendicionCount: billetesRendicionRes.totalCount,
      billetesCambioCount: billetesCambioRes.totalCount,
      tarjetasTotal: tarjetasRes.total,
      tarjetasDebito: tarjetasRes.debito,
      tarjetasCredito: tarjetasRes.credito,
      tarjetasQr: tarjetasRes.qr,
      otrosValoresTotal: otrosTotal,
      transferencia,
      egresos,
      retiros,
      diferencia,
      totalPlanilla: totalValoresEnMano
    };
  }

  function extractRecordTimestampMs(rec, prefix) {
    if (!rec || typeof rec !== 'object') return 0;
    const uid = String(rec.uid || '');
    const re = new RegExp(`^${prefix}-(\\d{10,15})-`);
    const m = uid.match(re);
    if (m && m[1]) {
      const ts = Number(m[1]);
      if (Number.isFinite(ts) && ts > 0) return ts;
    }
    return 0;
  }

  function getActiveShiftAperturaForCaja(cajaId, requireCurrentUser = false) {
    const activeAp = typeof getActiveTurnoAperturaForCaja === 'function'
      ? getActiveTurnoAperturaForCaja(cajaId)
      : null;
    if (!activeAp) return null;
    if (requireCurrentUser && !isAperturaOwnedByUser(activeAp)) {
      return null;
    }
    return activeAp;
  }

  function openCierreCajaDialog(cajaIdParam) {
    const cajaId = cajaIdParam || STATE.activeCajaId || 'caja1';
    const cfg = CAJAS_CONFIG[cajaId];
    if (!cfg) return;

    const dlg = document.getElementById('cierre-caja-dialog');
    if (!dlg) return;

    CIERRE_STATE.cajaId = cajaId;
    CIERRE_STATE.cajaMovNum = getNextCajaMovimientoNumber(cajaId, true);
    CIERRE_STATE.billetes = createEmptyBilletesMap();
    CIERRE_STATE.billetesTotalCaja = createEmptyBilletesMap();
    CIERRE_STATE.billetesCambio = createEmptyBilletesMap();

    // Precargar automáticamente los lotes del turno y los retiros de efectivo del usuario
    const expected = computeShiftExpectedBreakdown(cajaId);
    CIERRE_STATE.plataformas = clonePlataformasMap(expected.plataformas);
    CIERRE_STATE.tickets = [];

    const activeUserInfo = getActiveUserClosureInfo();
    const activeUser = activeUserInfo.displayName;
    const activeApertura = getActiveShiftAperturaForCaja(cajaId);

    const cajaDiariaNum = getCajaDiariaNumber(cajaId);
    const cajaOrigenText = `CAJA DIARIA ${cajaDiariaNum} - Nº: ${String(CIERRE_STATE.cajaMovNum).padStart(6, '0')}`;

    const headerBadge = document.getElementById('cierre-caja-header-badge');
    if (headerBadge) {
      headerBadge.textContent = `${cfg.nombre.toUpperCase()} · RENDICIÓN Y PASO DE FONDOS A CAJA CENTRAL (${activeUser})`;
    }

    const tipoSel = document.getElementById('cierre-tipo');
    if (tipoSel) tipoSel.value = 'Cierre de caja';

    const numInp = document.getElementById('cierre-numero');
    if (numInp) numInp.value = String(CIERRE_STATE.nextNumero).padStart(8, '0');

    const fechaInp = document.getElementById('cierre-fecha');
    if (fechaInp) fechaInp.value = todayFormatted();

    const empInp = document.getElementById('cierre-empleado');
    if (empInp) empInp.value = activeUser;

    const origInp = document.getElementById('cierre-caja-origen');
    if (origInp) origInp.value = cajaOrigenText;

    const fechaApInp = document.getElementById('cierre-fecha-apertura');
    if (fechaApInp) {
      fechaApInp.value = activeApertura
        ? (String(activeApertura.fechaHora || '').split(' ')[0] || expected.firstDate)
        : expected.firstDate;
    }

    const estadoInp = document.getElementById('cierre-estado-caja');
    if (estadoInp) {
      if (activeApertura) {
        estadoInp.value = 'Abierta';
        estadoInp.style.color = '';
        estadoInp.style.fontWeight = '';
      } else {
        estadoInp.value = '⚠️ SIN APERTURA';
        estadoInp.style.color = '#dc2626';
        estadoInp.style.fontWeight = '800';
      }
    }

    const destInp = document.getElementById('cierre-caja-destino');
    if (destInp) destInp.value = 'CAJA CENTRAL - Nº: 000001';

    const obsInp = document.getElementById('cierre-observacion');
    if (obsInp) obsInp.value = '';

    const transfEl = document.getElementById('cierre-val-transferencia');
    if (transfEl) transfEl.value = formatArs(expected.esperadoTransferencia || 0);
    const egrEl = document.getElementById('cierre-val-egresos');
    if (egrEl) egrEl.value = '0,00';
    const retEl = document.getElementById('cierre-val-retiros');
    if (retEl) retEl.value = formatArs(expected.totalRetirosEfectivo || 0);

    const alertBox = document.getElementById('cierre-caja-alert');
    if (alertBox) {
      if (!activeApertura) {
        alertBox.hidden = false;
        alertBox.innerHTML = `
          <div style="display:flex; align-items:center; justify-content:space-between; gap:0.75rem; flex-wrap:wrap;">
            <div>
              <strong>⚠️ ATENCIÓN: NO SE HIZO LA APERTURA DE CAJA (${escapeHtml(cfg.nombre.toUpperCase())})</strong><br>
              <span>No se registra ninguna Apertura de Caja para el turno actual luego del último cierre. Se recomienda registrar la Apertura antes de efectuar el Cierre.</span>
            </div>
            <button type="button" id="btn-cierre-goto-apertura" class="btn-secondary btn-sm" style="white-space:nowrap; font-weight:800; border-color:#dc2626; color:#b91c1c; background:#fff;">
              🔓 Ir a Apertura de Caja
            </button>
          </div>
        `;
        document.getElementById('btn-cierre-goto-apertura')?.addEventListener('click', () => {
          dlg.close();
          STATE.activeCajaId = cajaId;
          const apSel = document.getElementById('apertura-caja-select');
          if (apSel) apSel.value = cajaId;
          switchSection('sec-caja-apertura');
        });
      } else {
        alertBox.hidden = true;
        alertBox.textContent = '';
      }
    }

    recalcCierreCajaTotals();

    if (!dlg.open) {
      dlg.showModal();
    }

    // Sincronizar con el servidor al abrir el diálogo para garantizar que todos los comprobantes del turno estén actualizados
    syncCierresCajaFromServer().then(() => {
      if (!dlg.open || (CIERRE_STATE.cajaId || STATE.activeCajaId || 'caja1') !== cajaId) return;
      const freshExpected = computeShiftExpectedBreakdown(cajaId);
      if (freshExpected.turnoCount !== expected.turnoCount || Math.abs(freshExpected.esperadoTarjetas - expected.esperadoTarjetas) > 0.009) {
        CIERRE_STATE.plataformas = clonePlataformasMap(freshExpected.plataformas);
        const trEl = document.getElementById('cierre-val-transferencia');
        if (trEl) trEl.value = formatArs(freshExpected.esperadoTransferencia || 0);
        const rtEl = document.getElementById('cierre-val-retiros');
        if (rtEl) rtEl.value = formatArs(freshExpected.totalRetirosEfectivo || 0);
      }
      recalcCierreCajaTotals();
    }).catch(() => {});

    if (!activeApertura) {
      if (typeof playFactAlertBeep === 'function') playFactAlertBeep();
      setTimeout(() => {
        window.alert(
          `⚠️ ALERTA DE CAJA: No se hizo la Apertura de Caja en ${cfg.nombre} para este turno.\n\nNo existe una Apertura de Caja registrada después del último cierre.`
        );
      }, 60);
    }
  }

  // -------------------------------------------------------------------------
  // SUB-MODAL 1: EFECTIVO · DETALLE DE BILLETES ($ 20.000 A $ 100)
  // Dos columnas de carga: 1) Pasa a Caja Central y 2) Deja como Cambio en Caja
  // -------------------------------------------------------------------------
  function renderCierreBilletesTable() {
    const tbody = document.getElementById('cierre-billetes-tbody');
    const totalRendicionEl = document.getElementById('cierre-billetes-total-rendicion');
    const totalCambioEl = document.getElementById('cierre-billetes-total-cambio');
    const totalEl = document.getElementById('cierre-billetes-total');
    if (!tbody) return [];
    tbody.textContent = '';

    const totalCajaInputs = [];
    const cambioInputs = [];

    const updateBilletesDraftTotal = () => {
      const resRend = sumBilletesMap(CIERRE_STATE.draftBilletes);
      const resCamb = sumBilletesMap(CIERRE_STATE.draftBilletesCambio);
      const totFinal = round2(resRend.total + resCamb.total);
      if (totalRendicionEl) totalRendicionEl.textContent = `$ ${formatArs(resRend.total)}`;
      if (totalCambioEl) totalCambioEl.textContent = `$ ${formatArs(resCamb.total)}`;
      if (totalEl) totalEl.textContent = `$ ${formatArs(totFinal)}`;
    };

    const createQtyInput = (denom, initialQty, ariaText) => {
      const inp = document.createElement('input');
      inp.type = 'text';
      inp.inputMode = 'numeric';
      inp.autocomplete = 'off';
      inp.autocapitalize = 'off';
      inp.setAttribute('autocorrect', 'off');
      inp.spellcheck = false;
      inp.className = 'cierre-billete-qty-input';
      inp.setAttribute('aria-label', ariaText);
      inp.value = String(initialQty);
      inp.addEventListener('focus', () => {
        inp.select();
      });
      return inp;
    };

    BILLETES_DENOMINACIONES.forEach((denom, idx) => {
      const tr = document.createElement('tr');

      const tdNombre = document.createElement('td');
      tdNombre.innerHTML = renderBilleteDenomCellHtml(denom);
      tr.appendChild(tdNombre);

      const tdNominal = document.createElement('td');
      tdNominal.className = 'cierre-cell-readonly-num';
      tdNominal.textContent = `$ ${formatArs(denom)}`;
      tr.appendChild(tdNominal);

      const initCambQty = Math.max(0, Math.floor(Number(CIERRE_STATE.draftBilletesCambio[denom]) || 0));
      const initRendQty = Math.max(0, Math.floor(Number(CIERRE_STATE.draftBilletes[denom]) || 0));
      const initTotQty = Math.max(
        initRendQty + initCambQty,
        Math.floor(Number(CIERRE_STATE.draftBilletesTotalCaja?.[denom]) || 0)
      );
      CIERRE_STATE.draftBilletesTotalCaja[denom] = initTotQty;
      CIERRE_STATE.draftBilletes[denom] = Math.max(0, initTotQty - initCambQty);

      // Columna 1: Cantidad total de billetes en la caja
      const tdCantTot = document.createElement('td');
      tdCantTot.className = 'cierre-cell-input';
      const inpTot = createQtyInput(
        denom,
        initTotQty,
        `Cantidad total de billetes de $ ${denom.toLocaleString('es-AR')} en la caja`
      );
      tdCantTot.appendChild(inpTot);
      tr.appendChild(tdCantTot);

      const tdTotalCaja = document.createElement('td');
      tdTotalCaja.className = 'cierre-cell-subtotal';
      tdTotalCaja.textContent = `$ ${formatArs(denom * initTotQty)}`;
      tr.appendChild(tdTotalCaja);

      // Columna 2: Cantidad de billetes que deja como Cambio en la Caja
      const tdCantCamb = document.createElement('td');
      tdCantCamb.className = 'cierre-cell-input';
      const inpCamb = createQtyInput(
        denom,
        initCambQty,
        `Cantidad de billetes de $ ${denom.toLocaleString('es-AR')} que quedan como cambio en la caja`
      );
      tdCantCamb.appendChild(inpCamb);
      tr.appendChild(tdCantCamb);

      const tdTotalCamb = document.createElement('td');
      tdTotalCamb.className = 'cierre-cell-subtotal';
      tdTotalCamb.textContent = `$ ${formatArs(denom * initCambQty)}`;
      tr.appendChild(tdTotalCamb);

      // Columna 3 (calculada automáticamente): Billetes transferidos a Caja Central (= Total en Caja - Cambio en Caja)
      const tdCantRend = document.createElement('td');
      tdCantRend.className = 'cierre-cell-readonly-num';
      tdCantRend.style.fontWeight = '800';
      tdCantRend.style.color = '#1e40af';
      tdCantRend.style.background = '#eff6ff';
      tdCantRend.textContent = String(CIERRE_STATE.draftBilletes[denom]);
      tr.appendChild(tdCantRend);

      const tdTotalRend = document.createElement('td');
      tdTotalRend.className = 'cierre-cell-subtotal';
      tdTotalRend.style.fontWeight = '800';
      tdTotalRend.style.color = '#1e40af';
      tdTotalRend.style.background = '#eff6ff';
      tdTotalRend.textContent = `$ ${formatArs(denom * CIERRE_STATE.draftBilletes[denom])}`;
      tr.appendChild(tdTotalRend);

      const syncRowValues = () => {
        const qTot = Math.max(0, Math.floor(Number(CIERRE_STATE.draftBilletesTotalCaja[denom]) || 0));
        const qCamb = Math.max(0, Math.floor(Number(CIERRE_STATE.draftBilletesCambio[denom]) || 0));
        const qRend = Math.max(0, qTot - qCamb);
        CIERRE_STATE.draftBilletes[denom] = qRend;
        tdTotalCaja.textContent = `$ ${formatArs(denom * qTot)}`;
        tdTotalCamb.textContent = `$ ${formatArs(denom * qCamb)}`;
        tdCantRend.textContent = String(qRend);
        tdTotalRend.textContent = `$ ${formatArs(denom * qRend)}`;
        updateBilletesDraftTotal();
      };

      inpTot.addEventListener('input', () => {
        const digits = inpTot.value.replace(/\D+/g, '');
        const qty = digits ? Math.min(999999, parseInt(digits, 10)) : 0;
        if (inpTot.value !== digits && digits !== '') {
          inpTot.value = String(qty);
        }
        CIERRE_STATE.draftBilletesTotalCaja[denom] = qty;
        syncRowValues();
      });

      inpTot.addEventListener('blur', () => {
        const qty = Math.max(0, Math.floor(Number(CIERRE_STATE.draftBilletesTotalCaja[denom]) || 0));
        inpTot.value = String(qty);
      });

      inpCamb.addEventListener('input', () => {
        const digits = inpCamb.value.replace(/\D+/g, '');
        const qty = digits ? Math.min(999999, parseInt(digits, 10)) : 0;
        if (inpCamb.value !== digits && digits !== '') {
          inpCamb.value = String(qty);
        }
        CIERRE_STATE.draftBilletesCambio[denom] = qty;
        if (qty > (Number(CIERRE_STATE.draftBilletesTotalCaja[denom]) || 0)) {
          CIERRE_STATE.draftBilletesTotalCaja[denom] = qty;
          inpTot.value = String(qty);
        }
        syncRowValues();
      });

      inpCamb.addEventListener('blur', () => {
        const qty = Math.max(0, Math.floor(Number(CIERRE_STATE.draftBilletesCambio[denom]) || 0));
        inpCamb.value = String(qty);
      });

      inpTot.addEventListener('keydown', (e) => {
        if (e.isComposing) return;
        if (e.key === 'ArrowDown' || e.key === 'Enter') {
          e.preventDefault();
          if (idx < totalCajaInputs.length - 1) {
            totalCajaInputs[idx + 1].focus();
          } else {
            cambioInputs[0]?.focus();
          }
        } else if (e.key === 'ArrowUp' && idx > 0) {
          e.preventDefault();
          totalCajaInputs[idx - 1].focus();
        } else if (e.key === 'ArrowRight') {
          e.preventDefault();
          cambioInputs[idx]?.focus();
        }
      });

      inpCamb.addEventListener('keydown', (e) => {
        if (e.isComposing) return;
        if (e.key === 'ArrowDown' || e.key === 'Enter') {
          e.preventDefault();
          if (idx < cambioInputs.length - 1) {
            cambioInputs[idx + 1].focus();
          } else if (e.key === 'Enter') {
            document.getElementById('btn-accept-billetes')?.focus();
          }
        } else if (e.key === 'ArrowUp') {
          e.preventDefault();
          if (idx > 0) {
            cambioInputs[idx - 1].focus();
          } else {
            totalCajaInputs[totalCajaInputs.length - 1]?.focus();
          }
        } else if (e.key === 'ArrowLeft') {
          e.preventDefault();
          totalCajaInputs[idx]?.focus();
        }
      });

      totalCajaInputs.push(inpTot);
      cambioInputs.push(inpCamb);
      tbody.appendChild(tr);
    });

    updateBilletesDraftTotal();
    return [...totalCajaInputs, ...cambioInputs];
  }

  function openCierreBilletesDialog() {
    const dlg = document.getElementById('cierre-billetes-dialog');
    if (!dlg) return;
    CIERRE_STATE.draftBilletes = { ...createEmptyBilletesMap(), ...CIERRE_STATE.billetes };
    CIERRE_STATE.draftBilletesCambio = { ...createEmptyBilletesMap(), ...CIERRE_STATE.billetesCambio };
    CIERRE_STATE.draftBilletesTotalCaja = createEmptyBilletesMap();
    BILLETES_DENOMINACIONES.forEach((denom) => {
      const qR = Math.max(0, Math.floor(Number(CIERRE_STATE.billetes[denom]) || 0));
      const qC = Math.max(0, Math.floor(Number(CIERRE_STATE.billetesCambio[denom]) || 0));
      const qT = Math.max(qR + qC, Math.floor(Number(CIERRE_STATE.billetesTotalCaja?.[denom]) || 0));
      CIERRE_STATE.draftBilletesTotalCaja[denom] = qT;
    });
    const inputs = renderCierreBilletesTable();
    if (!dlg.open) {
      dlg.showModal();
    }
    requestAnimationFrame(() => {
      if (inputs && inputs[0]) {
        inputs[0].focus();
        inputs[0].select();
      }
    });
  }

  document.getElementById('btn-open-cierre-billetes')?.addEventListener('click', openCierreBilletesDialog);

  document.getElementById('btn-clear-billetes')?.addEventListener('click', () => {
    CIERRE_STATE.draftBilletes = createEmptyBilletesMap();
    CIERRE_STATE.draftBilletesTotalCaja = createEmptyBilletesMap();
    CIERRE_STATE.draftBilletesCambio = createEmptyBilletesMap();
    const inputs = renderCierreBilletesTable();
    if (inputs && inputs[0]) {
      inputs[0].focus();
      inputs[0].select();
    }
  });

  document.getElementById('cierre-billetes-form')?.addEventListener('submit', (e) => {
    e.preventDefault();
    CIERRE_STATE.billetes = { ...CIERRE_STATE.draftBilletes };
    CIERRE_STATE.billetesTotalCaja = { ...CIERRE_STATE.draftBilletesTotalCaja };
    CIERRE_STATE.billetesCambio = { ...CIERRE_STATE.draftBilletesCambio };
    document.getElementById('cierre-billetes-dialog')?.close();
    recalcCierreCajaTotals();
  });

  ['btn-cancel-billetes', 'btn-close-billetes-top'].forEach((id) => {
    document.getElementById(id)?.addEventListener('click', () => {
      document.getElementById('cierre-billetes-dialog')?.close();
    });
  });

  // -------------------------------------------------------------------------
  // SUB-MODAL 2: TARJETAS (DÉBITO, CRÉDITO Y QR POR PLATAFORMA DE PAGO)
  // -------------------------------------------------------------------------
  function renderCierreTarjetasTable() {
    const tbody = document.getElementById('cierre-tarjetas-tbody');
    if (!tbody) return [];
    tbody.textContent = '';

    const allInputs = [];

    const updateTarjetasDraftTotals = () => {
      const res = sumPlataformasMap(CIERRE_STATE.draftPlataformas);
      const colDeb = document.getElementById('cierre-tarj-col-debito');
      const colCred = document.getElementById('cierre-tarj-col-credito');
      const colQr = document.getElementById('cierre-tarj-col-qr');
      const grandEl = document.getElementById('cierre-tarjetas-total');
      if (colDeb) colDeb.textContent = `$ ${formatArs(res.debito)}`;
      if (colCred) colCred.textContent = `$ ${formatArs(res.credito)}`;
      if (colQr) colQr.textContent = `$ ${formatArs(res.qr)}`;
      if (grandEl) grandEl.textContent = `$ ${formatArs(res.total)}`;
    };

    PLATAFORMAS_PAGO_CIERRE.forEach((plat) => {
      const tr = document.createElement('tr');
      const rowState = CIERRE_STATE.draftPlataformas[plat] || { debito: 0, credito: 0, qr: 0 };

      const th = document.createElement('th');
      th.scope = 'row';
      th.textContent = plat;
      tr.appendChild(th);

      const tdSub = document.createElement('td');
      tdSub.className = 'num-col';
      tdSub.style.fontWeight = '800';

      const refreshRowSubtotal = () => {
        const sub = round2((Number(rowState.debito) || 0) + (Number(rowState.credito) || 0) + (Number(rowState.qr) || 0));
        tdSub.textContent = `$ ${formatArs(sub)}`;
      };

      ['debito', 'credito', 'qr'].forEach((colKey) => {
        const td = document.createElement('td');
        td.className = 'num-col';
        const inp = document.createElement('input');
        inp.type = 'text';
        inp.inputMode = 'decimal';
        inp.autocomplete = 'off';
        inp.autocapitalize = 'off';
        inp.setAttribute('autocorrect', 'off');
        inp.spellcheck = false;
        inp.className = 'form-input form-input--compact cierre-money-cell-input';
        const colLabel = colKey === 'debito' ? 'Débito' : colKey === 'credito' ? 'Crédito' : 'QR';
        inp.setAttribute('aria-label', `${plat} - ${colLabel}`);
        inp.value = formatArs(rowState[colKey] || 0);

        inp.addEventListener('focus', () => {
          inp.select();
        });

        inp.addEventListener('input', () => {
          rowState[colKey] = parsePosMoneyInput(inp.value);
          CIERRE_STATE.draftPlataformas[plat] = rowState;
          refreshRowSubtotal();
          updateTarjetasDraftTotals();
        });

        inp.addEventListener('blur', () => {
          inp.value = formatArs(rowState[colKey] || 0);
        });

        const myIdx = allInputs.length;
        inp.addEventListener('keydown', (e) => {
          if (e.isComposing) return;
          if (e.key === 'Enter') {
            e.preventDefault();
            if (myIdx < allInputs.length - 1) {
              allInputs[myIdx + 1].focus();
            } else {
              document.getElementById('btn-accept-tarjetas')?.focus();
            }
          }
        });

        allInputs.push(inp);
        td.appendChild(inp);
        tr.appendChild(td);
      });

      refreshRowSubtotal();
      tr.appendChild(tdSub);
      tbody.appendChild(tr);
    });

    updateTarjetasDraftTotals();
    return allInputs;
  }

  function openCierreTarjetasDialog() {
    const dlg = document.getElementById('cierre-tarjetas-dialog');
    if (!dlg) return;
    CIERRE_STATE.draftPlataformas = clonePlataformasMap(CIERRE_STATE.plataformas);
    const inputs = renderCierreTarjetasTable();
    if (!dlg.open) {
      dlg.showModal();
    }
    requestAnimationFrame(() => {
      if (inputs && inputs[0]) {
        inputs[0].focus();
        inputs[0].select();
      }
    });
  }

  document.getElementById('btn-open-cierre-tarjetas')?.addEventListener('click', openCierreTarjetasDialog);

  document.getElementById('btn-tarjetas-sync-sys')?.addEventListener('click', () => {
    const expected = computeShiftExpectedBreakdown(CIERRE_STATE.cajaId);
    CIERRE_STATE.draftPlataformas = clonePlataformasMap(expected.plataformas);
    const inputs = renderCierreTarjetasTable();
    if (inputs && inputs[0]) inputs[0].focus();
  });

  document.getElementById('btn-tarjetas-zero')?.addEventListener('click', () => {
    CIERRE_STATE.draftPlataformas = createEmptyPlataformasMap();
    const inputs = renderCierreTarjetasTable();
    if (inputs && inputs[0]) {
      inputs[0].focus();
      inputs[0].select();
    }
  });

  document.getElementById('cierre-tarjetas-form')?.addEventListener('submit', (e) => {
    e.preventDefault();
    CIERRE_STATE.plataformas = clonePlataformasMap(CIERRE_STATE.draftPlataformas);
    document.getElementById('cierre-tarjetas-dialog')?.close();
    recalcCierreCajaTotals();
  });

  ['btn-cancel-tarjetas', 'btn-close-tarjetas-top'].forEach((id) => {
    document.getElementById(id)?.addEventListener('click', () => {
      document.getElementById('cierre-tarjetas-dialog')?.close();
    });
  });

  // -------------------------------------------------------------------------
  // SUB-MODAL 3: OTROS VALORES (TICKETS RECIBIDOS POR EL CAJERO)
  // -------------------------------------------------------------------------
  function renderCierreOtrosTicketsTable() {
    const tbody = document.getElementById('cierre-otros-tbody');
    const totalEl = document.getElementById('cierre-otros-total');
    if (!tbody) return;
    tbody.textContent = '';

    const list = Array.isArray(CIERRE_STATE.draftTickets) ? CIERRE_STATE.draftTickets : [];
    const total = sumTicketsList(list);
    if (totalEl) totalEl.textContent = `$ ${formatArs(total)}`;

    if (list.length === 0) {
      const tr = document.createElement('tr');
      const td = document.createElement('td');
      td.colSpan = 4;
      td.className = 'table-loading-cell';
      td.textContent = 'No se cargaron tickets en Otros Valores.';
      tr.appendChild(td);
      tbody.appendChild(tr);
      return;
    }

    list.forEach((tk, idx) => {
      const tr = document.createElement('tr');

      const th = document.createElement('th');
      th.scope = 'row';
      th.textContent = tk.tipo || 'TICKET';
      tr.appendChild(th);

      const tdRef = document.createElement('td');
      tdRef.textContent = tk.referencia || 'SIN DETALLE';
      tr.appendChild(tdRef);

      const tdImp = document.createElement('td');
      tdImp.className = 'num-col';
      tdImp.innerHTML = `<strong>$ ${formatArs(tk.importe)}</strong>`;
      tr.appendChild(tdImp);

      const tdDel = document.createElement('td');
      tdDel.style.textAlign = 'center';
      const btnDel = document.createElement('button');
      btnDel.type = 'button';
      btnDel.className = 'btn-secondary btn-sm';
      btnDel.style.width = 'auto';
      btnDel.style.padding = '0.2rem 0.5rem';
      btnDel.setAttribute('aria-label', `Quitar ticket ${tk.referencia || idx + 1}`);
      btnDel.textContent = '✕';
      btnDel.addEventListener('click', () => {
        CIERRE_STATE.draftTickets.splice(idx, 1);
        renderCierreOtrosTicketsTable();
      });
      tdDel.appendChild(btnDel);
      tr.appendChild(tdDel);

      tbody.appendChild(tr);
    });
  }

  function openCierreOtrosDialog() {
    const dlg = document.getElementById('cierre-otros-dialog');
    if (!dlg) return;
    CIERRE_STATE.draftTickets = CIERRE_STATE.tickets.map((t) => ({ ...t }));
    const refInp = document.getElementById('cierre-ticket-ref');
    const impInp = document.getElementById('cierre-ticket-importe');
    if (refInp) refInp.value = '';
    if (impInp) impInp.value = '';
    renderCierreOtrosTicketsTable();
    if (!dlg.open) {
      dlg.showModal();
    }
    requestAnimationFrame(() => {
      refInp?.focus();
    });
  }

  document.getElementById('btn-open-cierre-otros')?.addEventListener('click', openCierreOtrosDialog);

  document.getElementById('cierre-add-ticket-form')?.addEventListener('submit', (e) => {
    e.preventDefault();
    const tipoSel = document.getElementById('cierre-ticket-tipo');
    const refInp = document.getElementById('cierre-ticket-ref');
    const impInp = document.getElementById('cierre-ticket-importe');

    const importe = parsePosMoneyInput(impInp?.value || 0);
    if (importe <= 0) {
      impInp?.focus();
      return;
    }

    CIERRE_STATE.draftTickets.push({
      id: Date.now() + Math.floor(Math.random() * 1000),
      tipo: (tipoSel?.value || 'TICKET / VALE DE COMPRA').toUpperCase(),
      referencia: (refInp?.value || '').trim().toUpperCase() || `TICKET #${CIERRE_STATE.draftTickets.length + 1}`,
      importe
    });

    if (refInp) refInp.value = '';
    if (impInp) impInp.value = '';
    renderCierreOtrosTicketsTable();
    refInp?.focus();
  });

  document.getElementById('btn-clear-otros')?.addEventListener('click', () => {
    CIERRE_STATE.draftTickets = [];
    renderCierreOtrosTicketsTable();
    document.getElementById('cierre-ticket-ref')?.focus();
  });

  document.getElementById('btn-accept-otros')?.addEventListener('click', () => {
    CIERRE_STATE.tickets = CIERRE_STATE.draftTickets.map((t) => ({ ...t }));
    document.getElementById('cierre-otros-dialog')?.close();
    recalcCierreCajaTotals();
  });

  ['btn-cancel-otros', 'btn-close-otros-top'].forEach((id) => {
    document.getElementById(id)?.addEventListener('click', () => {
      document.getElementById('cierre-otros-dialog')?.close();
    });
  });

  // -------------------------------------------------------------------------
  // EVENTOS DEL MODAL PRINCIPAL DE CIERRE DE CAJA Y ENVÍO A CAJA CENTRAL
  // -------------------------------------------------------------------------
  ['cierre-val-transferencia', 'cierre-val-egresos', 'cierre-val-retiros'].forEach((id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.addEventListener('focus', () => el.select());
    el.addEventListener('input', () => recalcCierreCajaTotals());
    el.addEventListener('blur', () => {
      el.value = formatArs(parsePosMoneyInput(el.value));
      recalcCierreCajaTotals();
    });
  });

  ['btn-cancel-cierre-caja', 'btn-close-cierre-caja-top'].forEach((id) => {
    document.getElementById(id)?.addEventListener('click', () => {
      document.getElementById('cierre-caja-dialog')?.close();
    });
  });

  const cardSubCajaCierre = document.getElementById('card-sub-caja-cierre');
  if (cardSubCajaCierre) {
    const triggerCierre = () => {
      openCierreCajaDialog(STATE.activeCajaId || 'caja1');
    };
    cardSubCajaCierre.addEventListener('click', triggerCierre);
    attachButtonRoleKeyboard(cardSubCajaCierre, triggerCierre);
  }

  document.getElementById('cierre-caja-form')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const cajaId = CIERRE_STATE.cajaId || STATE.activeCajaId || 'caja1';
    const cfg = CAJAS_CONFIG[cajaId];
    if (!cfg) return;

    const summary = recalcCierreCajaTotals();
    const now = new Date();
    const horaStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
    const fechaCierre = document.getElementById('cierre-fecha')?.value || todayFormatted();
    const fechaHora = `${fechaCierre} ${horaStr}`;
    const tipoRendicion = document.getElementById('cierre-tipo')?.value || 'Cierre de caja';
    const empleado = document.getElementById('cierre-empleado')?.value || 'ADMINISTRADOR';
    const cajaOrigenLabel = document.getElementById('cierre-caja-origen')?.value || cfg.nombre.toUpperCase();
    const cajaDestinoLabel = document.getElementById('cierre-caja-destino')?.value || 'CAJA CENTRAL - Nº: 000001';
    const fechaApertura = document.getElementById('cierre-fecha-apertura')?.value || fechaCierre;
    let observacion = (document.getElementById('cierre-observacion')?.value || '').trim().toUpperCase();

    const activeAperturaOnSubmit = getActiveShiftAperturaForCaja(cajaId);
    if (tipoRendicion === 'Cierre de caja' && !activeAperturaOnSubmit) {
      if (typeof playFactAlertBeep === 'function') playFactAlertBeep();
      const confirmarSinApertura = await showBrandConfirmDialog(
        `⚠️ ATENCIÓN: No se hizo la Apertura de Caja en ${cfg.nombre} para este turno.\n\n¿Deseás confirmar igualmente el Cierre de Caja dejando constancia de que no se realizó la apertura?`
      );
      if (!confirmarSinApertura) {
        return;
      }
      if (!observacion.includes('SIN APERTURA DE CAJA')) {
        observacion = observacion
          ? `${observacion} | [ALERTA: CIERRE SIN APERTURA DE CAJA]`
          : '[ALERTA: CIERRE SIN APERTURA DE CAJA]';
      }
    }

    const billetesDetalle = BILLETES_DENOMINACIONES.map((denom) => {
      const cantidadRendicion = Math.max(0, Math.floor(Number(CIERRE_STATE.billetes[denom]) || 0));
      const cantidadCambio = Math.max(0, Math.floor(Number(CIERRE_STATE.billetesCambio[denom]) || 0));
      const subtotalRendicion = round2(denom * cantidadRendicion);
      const subtotalCambio = round2(denom * cantidadCambio);
      return {
        denom,
        nombre: `Billete de $ ${denom.toLocaleString('es-AR')}`,
        cantidad: cantidadRendicion,
        subtotal: subtotalRendicion,
        cantidadRendicion,
        subtotalRendicion,
        cantidadCambio,
        subtotalCambio,
        cantidadTotal: cantidadRendicion + cantidadCambio,
        subtotalTotal: round2(subtotalRendicion + subtotalCambio)
      };
    });

    const numeroPlanilla = CIERRE_STATE.nextNumero;
    CIERRE_STATE.nextNumero = numeroPlanilla + 1;

    if (tipoRendicion === 'Cierre de caja') {
      getNextCajaMovimientoNumber(cajaId, false);
    }

    const activeUserInfo = getActiveUserClosureInfo();
    const billetesDeclaradosMap = {};
    const billetesCambioDeclaradosMap = {};
    const billetesTotalCajaMap = {};
    BILLETES_DENOMINACIONES.forEach((denom) => {
      const qR = Math.max(0, Math.floor(Number(CIERRE_STATE.billetes[denom]) || 0));
      const qC = Math.max(0, Math.floor(Number(CIERRE_STATE.billetesCambio[denom]) || 0));
      billetesDeclaradosMap[denom] = qR;
      billetesCambioDeclaradosMap[denom] = qC;
      billetesTotalCajaMap[denom] = qR + qC;
    });

    const arqueoOriginalCajero = {
      fechaHora,
      usuario: empleado,
      efectivoRendicion: summary.efectivoRendicion,
      efectivoCambio: summary.efectivoCambio,
      efectivoFinal: summary.efectivoFinal,
      billetes: billetesDetalle.map((b) => ({ ...b })),
      billetesTotalCaja: { ...billetesTotalCajaMap },
      billetesDeclaradosCajero: { ...billetesDeclaradosMap },
      billetesCambioDeclaradosCajero: { ...billetesCambioDeclaradosMap },
      billetesDeclaradosTransferidos: true,
      tarjetasTotal: summary.tarjetasTotal,
      tarjetasDebito: summary.tarjetasDebito,
      tarjetasCredito: summary.tarjetasCredito,
      tarjetasQr: summary.tarjetasQr,
      plataformas: clonePlataformasMap(CIERRE_STATE.plataformas),
      otrosValoresTotal: summary.otrosValoresTotal,
      tickets: CIERRE_STATE.tickets.map((t) => ({ ...t })),
      transferencia: summary.transferencia,
      egresos: summary.egresos,
      retiros: summary.retiros,
      totalCtaCte: summary.expected.totalCtaCte,
      ctaCteCount: summary.expected.ctaCteCount || 0,
      ctaCteDetalle: Array.isArray(summary.expected.ctaCteDetalle) ? summary.expected.ctaCteDetalle.map((d) => ({ ...d })) : [],
      observacion,
      total: summary.totalPlanilla
    };

    const nuevoCierre = {
      uid: `CC-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
      id: STATE.cierresCajaCentral.length + 1,
      numeroPlanilla,
      tipoRendicion,
      cajaId: cfg.id,
      cajaNombre: cfg.nombre,
      cajaOrigenLabel,
      cajaDestinoLabel,
      pvFiscal: cfg.pvFiscal,
      pvInterno: cfg.pvInterno,
      fechaCierre,
      fechaApertura,
      fechaHora,
      usuario: empleado,
      username: activeUserInfo.username,
      cantidadComprobantes: summary.expected.turnoCount,
      subtotalFiscal: summary.expected.subtotalFiscal,
      subtotalInterno: summary.expected.subtotalInterno,
      totalFacturadoTurno: summary.expected.totalFacturadoTurno,
      efectivoInicial: summary.expected.efectivoInicial,
      ventasBrutasEfectivo: summary.expected.ventasBrutasEfectivo,
      notasCreditoEfectivo: summary.expected.notasCreditoEfectivo,
      ventasNetasEfectivo: summary.expected.ventasNetasEfectivo,
      cobranzasRecibosEfectivo: summary.expected.cobranzasRecibosEfectivo,
      ingresosEfectivoBruto: summary.expected.ingresosEfectivo,
      retirosEfectivoTurno: summary.expected.totalRetirosEfectivo,
      efectivoEsperadoFinal: summary.efectivoEsperadoFinal,
      efectivoEsperadoTraspasoCentral: summary.efectivoEsperadoTraspasoCentral,
      esperadoContadoPos: summary.expected.esperadoContadoPos,
      totalCtaCte: summary.expected.totalCtaCte,
      ctaCteCount: summary.expected.ctaCteCount || 0,
      ctaCteDetalle: Array.isArray(summary.expected.ctaCteDetalle) ? summary.expected.ctaCteDetalle.map((d) => ({ ...d })) : [],
      efectivo: summary.efectivoRendicion,
      efectivoRendicion: summary.efectivoRendicion,
      efectivoCambio: summary.efectivoCambio,
      efectivoFinal: summary.efectivoFinal,
      billetes: billetesDetalle,
      billetesTotalCaja: billetesTotalCajaMap,
      billetesDeclaradosCajero: billetesDeclaradosMap,
      billetesCambioDeclaradosCajero: billetesCambioDeclaradosMap,
      billetesDeclaradosTransferidos: true,
      efectivoDeclaradoCajero: summary.efectivoRendicion,
      efectivoCambioDeclaradoCajero: summary.efectivoCambio,
      arqueoOriginalCajero,
      tarjetasTotal: summary.tarjetasTotal,
      tarjetasDebito: summary.tarjetasDebito,
      tarjetasCredito: summary.tarjetasCredito,
      tarjetasQr: summary.tarjetasQr,
      plataformas: clonePlataformasMap(CIERRE_STATE.plataformas),
      otrosValoresTotal: summary.otrosValoresTotal,
      tickets: CIERRE_STATE.tickets.map((t) => ({ ...t })),
      transferencia: summary.transferencia,
      egresos: summary.egresos,
      retiros: summary.retiros,
      diferencia: summary.diferencia,
      observacion,
      total: summary.totalPlanilla,
      closedAtIso: new Date().toISOString()
    };

    STATE.cierresCajaCentral.unshift(nuevoCierre);
    if (tipoRendicion === 'Cierre de caja') {
      if (!STATE.efectivoInicialPorCaja || typeof STATE.efectivoInicialPorCaja !== 'object') {
        STATE.efectivoInicialPorCaja = { caja1: 0, caja2: 0, caja3: 0 };
      }
      // El cambio en billetes que deja en la caja pasa a ser el Efectivo Inicial del próximo turno de esa caja
      STATE.efectivoInicialPorCaja[cajaId] = round2(summary.efectivoCambio);
      // Limpiar todos los comprobantes del turno cerrado de esa Caja física
      STATE.turnosCajas[cajaId] = [];
      // Marcar las aperturas de esa Caja como cerradas para habilitar la apertura del próximo turno
      if (Array.isArray(STATE.aperturasCajaCentral)) {
        STATE.aperturasCajaCentral.forEach((ap) => {
          if (ap && ap.cajaId === cajaId) {
            ap.cerradaEnTurno = true;
            if (!ap.cerradaPorPlanilla) {
              ap.cerradaPorPlanilla = nuevoCierre.numeroPlanilla;
            }
          }
        });
      }
      normalizeClientAperturasState();
      notifyServerActiveCaja(null, { closedCajaId: cajaId });
    }
    saveCajasState();
    renderCajaPosView();
    if (typeof renderCajaSubmenuView === 'function') {
      renderCajaSubmenuView(cajaId);
    }
    const centralSec = document.getElementById('sec-caja-central');
    if (centralSec && !centralSec.hidden) {
      renderCajaCentralView();
    }

    document.getElementById('cierre-caja-dialog')?.close();

    // Imprimir SIEMPRE el reporte simple del cajero (Fecha y Hora, N° de Planilla, Billetes y Total que traspasa)
    if (typeof window.printReporteSimpleTraspasoCajero === 'function') {
      window.printReporteSimpleTraspasoCajero(nuevoCierre);
    }

    fetch('api/ventas.php', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'save_cierre',
        cajaId: cfg.id,
        cierre: nuevoCierre
      })
    })
      .then((r) => (r.ok ? r.json() : null))
      .then((res) => {
        if (res && res.ok) {
          if (Number(res.nextNumero) > 0) {
            CIERRE_STATE.nextNumero = Math.max(CIERRE_STATE.nextNumero, Number(res.nextNumero));
          }
          if (Array.isArray(res.aperturasCajaCentral)) {
            STATE.aperturasCajaCentral = res.aperturasCajaCentral;
          }
          if (res.efectivoInicialPorCaja && typeof res.efectivoInicialPorCaja === 'object') {
            STATE.efectivoInicialPorCaja = {
              caja1: round2(Number(res.efectivoInicialPorCaja.caja1) || 0),
              caja2: round2(Number(res.efectivoInicialPorCaja.caja2) || 0),
              caja3: round2(Number(res.efectivoInicialPorCaja.caja3) || 0)
            };
          }
          saveCajasState();
        }
      })
      .catch(() => {});
  });

  // -------------------------------------------------------------------------
  // REPORTE SIMPLE DE CIERRE DE CAJA PARA EL CAJERO (SIEMPRE SE IMPRIME AL CERRAR)
  // Contiene: Fecha y hora de Cierre, Número de Planilla, Billetes y Total que traspasa
  // -------------------------------------------------------------------------
  window.printReporteSimpleTraspasoCajero = function (cierreParam) {
    const c = cierreParam || CIERRE_STATE.activeCentralCierre || STATE.cierresCajaCentral?.[0];
    if (!c) return;
    normalizeCierreBilletesTransferidos(c);

    const orig = c.arqueoOriginalCajero && typeof c.arqueoOriginalCajero === 'object'
      ? c.arqueoOriginalCajero
      : null;

    const planillaNum = c.numeroPlanilla
      ? String(c.numeroPlanilla).padStart(8, '0')
      : String(c.id || 1).padStart(8, '0');

    const declRendMap = orig?.billetesDeclaradosCajero || c.billetesDeclaradosCajero || null;
    const origBilletesArr = Array.isArray(orig?.billetes) ? orig.billetes : (Array.isArray(c.billetes) ? c.billetes : []);

    let sumRendCajero = 0;
    let cantRendCajero = 0;

    const billetesRowsHtml = BILLETES_DENOMINACIONES.map((denom) => {
      const rowOrig = origBilletesArr.find((b) => Number(b?.denom) === Number(denom));
      const qRend = declRendMap && typeof declRendMap[denom] !== 'undefined'
        ? Math.max(0, Math.floor(Number(declRendMap[denom]) || 0))
        : Math.max(0, Math.floor(Number(rowOrig?.cantidadRendicion ?? rowOrig?.cantidad ?? 0) || 0));

      const subRend = round2(denom * qRend);
      sumRendCajero = round2(sumRendCajero + subRend);
      cantRendCajero += qRend;

      const rowStyle = qRend > 0 ? 'font-weight:700; color:#0f172a;' : 'color:#64748b;';
      return `<tr style="${rowStyle}">
        <td>$ ${denom.toLocaleString('es-AR')}</td>
        <td style="text-align:center;">${qRend}</td>
        <td style="text-align:right;">$ ${formatArs(subRend)}</td>
      </tr>`;
    }).join('');

    const efectivoRendicionCajero = orig && typeof orig.efectivoRendicion === 'number'
      ? round2(orig.efectivoRendicion)
      : typeof c.efectivoDeclaradoCajero === 'number' && c.efectivoDeclaradoCajero > 0
        ? round2(c.efectivoDeclaradoCajero)
        : sumRendCajero > 0
          ? sumRendCajero
          : round2(Number(c.efectivoRendicion ?? c.efectivo ?? 0) || 0);

    const brandTitle = (window.ACTIVE_BRAND && window.ACTIVE_BRAND.title) || 'CASA NUEVA SUPER';
    const docHtml = `<!DOCTYPE html>
      <html lang="es-AR">
      <head>
        <meta charset="UTF-8">
        <title>Cierre de Caja · Planilla N° ${escapeHtml(planillaNum)}</title>
        <style>
          @page { margin: 8mm 10mm; }
          body {
            font-family: Arial, sans-serif;
            color: #0f172a;
            background: #ffffff;
            margin: 0;
            padding: 0;
            font-size: 10pt;
            -webkit-print-color-adjust: exact;
            print-color-adjust: exact;
          }
          .report-box {
            max-width: 480px;
            margin: 0 auto;
            border: 1.5px solid #0f172a;
            border-radius: 6px;
            padding: 12px 14px;
          }
          .hdr {
            text-align: center;
            border-bottom: 2px solid #0f172a;
            padding-bottom: 8px;
            margin-bottom: 10px;
          }
          .hdr h1 {
            margin: 0;
            font-size: 13pt;
            font-weight: 900;
            letter-spacing: -0.01em;
          }
          .hdr .sub {
            font-size: 8.5pt;
            font-weight: 700;
            color: #334155;
            margin-top: 2px;
            text-transform: uppercase;
          }
          .meta-table {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 10px;
          }
          .meta-table td {
            padding: 3px 0;
            font-size: 9.5pt;
            border: none;
          }
          .meta-table td.lbl {
            color: #475569;
            font-weight: 700;
          }
          .meta-table td.val {
            text-align: right;
            font-weight: 800;
            color: #0f172a;
          }
          .sec-title {
            font-size: 9pt;
            font-weight: 800;
            text-transform: uppercase;
            background: #f1f5f9;
            padding: 5px 8px;
            border: 1px solid #cbd5e1;
            border-bottom: none;
            margin: 0;
          }
          table.bills {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 10px;
          }
          table.bills th, table.bills td {
            border: 1px solid #cbd5e1;
            padding: 4.5px 8px;
            font-size: 9.2pt;
          }
          table.bills th {
            background: #f8fafc;
            font-weight: 800;
            text-align: left;
          }
          .total-box {
            border: 2px solid #0f172a;
            background: #f8fafc;
            border-radius: 5px;
            padding: 8px 10px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 6px;
          }
          .total-box .t-lbl {
            font-size: 9.5pt;
            font-weight: 800;
            text-transform: uppercase;
          }
          .total-box .t-sub {
            display: block;
            font-size: 8pt;
            color: #475569;
            font-weight: 600;
          }
          .total-box .t-val {
            font-size: 13.5pt;
            font-weight: 900;
          }
          .firmas {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 24px;
            margin-top: 28px;
            text-align: center;
            font-size: 8.5pt;
          }
          .firma-line {
            border-top: 1px solid #334155;
            padding-top: 4px;
          }
        </style>
      </head>
      <body>
        <div class="report-box">
          <div class="hdr">
            <h1>${escapeHtml(brandTitle)}</h1>
            <div class="sub">Reporte de Cierre de Caja · Traspaso a Caja Central</div>
          </div>

          <table class="meta-table">
            <tr>
              <td class="lbl">NÚMERO DE PLANILLA:</td>
              <td class="val" style="font-size:11pt;">N° ${escapeHtml(planillaNum)}</td>
            </tr>
            <tr>
              <td class="lbl">FECHA Y HORA DE CIERRE:</td>
              <td class="val">${escapeHtml(c.fechaHora || '')}</td>
            </tr>
            <tr>
              <td class="lbl">CAJA / ORIGEN:</td>
              <td class="val">${escapeHtml(c.cajaNombre || 'Caja')}</td>
            </tr>
            <tr>
              <td class="lbl">CAJERO:</td>
              <td class="val">${escapeHtml(c.usuario || '')}</td>
            </tr>
          </table>

          <div class="sec-title">Billetes que Traspasa a Caja Central</div>
          <table class="bills">
            <thead>
              <tr>
                <th>Billete</th>
                <th style="text-align:center; width:80px;">Cantidad</th>
                <th style="text-align:right; width:130px;">Subtotal ($)</th>
              </tr>
            </thead>
            <tbody>
              ${billetesRowsHtml}
            </tbody>
          </table>

          <div class="total-box">
            <div>
              <span class="t-lbl">Total que Traspasa</span>
              <span class="t-sub">Total billetes traspasados: ${cantRendCajero}</span>
            </div>
            <div class="t-val">$ ${formatArs(efectivoRendicionCajero)}</div>
          </div>

          <div class="firmas">
            <div class="firma-line">
              <strong>Firma Cajero</strong><br>
              <span>${escapeHtml(c.usuario || '')}</span>
            </div>
            <div class="firma-line">
              <strong>Recibió Caja Central</strong><br>
              <span>Control de Billetes</span>
            </div>
          </div>
        </div>
        <script>
          window.addEventListener('load', function () {
            setTimeout(function () {
              window.focus();
              window.print();
            }, 180);
          });
        <\/script>
      </body>
      </html>`;

    const w = window.open('', '_blank', 'width=680,height=760');
    if (w) {
      w.document.open();
      w.document.write(docHtml);
      w.document.close();
      return;
    }

    // Fallback en iframe oculto por si el navegador bloqueó ventanas emergentes
    let printFrame = document.getElementById('cajero-simple-print-frame');
    if (!printFrame) {
      printFrame = document.createElement('iframe');
      printFrame.id = 'cajero-simple-print-frame';
      printFrame.style.position = 'fixed';
      printFrame.style.right = '0';
      printFrame.style.bottom = '0';
      printFrame.style.width = '0';
      printFrame.style.height = '0';
      printFrame.style.border = '0';
      document.body.appendChild(printFrame);
    }
    const frameDoc = printFrame.contentWindow?.document || printFrame.contentDocument;
    if (frameDoc) {
      frameDoc.open();
      frameDoc.write(docHtml);
      frameDoc.close();
      setTimeout(() => {
        try {
          printFrame.contentWindow?.focus();
          printFrame.contentWindow?.print();
        } catch {}
      }, 220);
    }
  };

  // -------------------------------------------------------------------------
  // AUDITORÍA E IMPRESIÓN A4 DE PLANILLA EN CAJA CENTRAL
  // (Solo aquí el responsable de Caja Central ve el Faltante o Sobrante)
  // -------------------------------------------------------------------------
  function resolveCierreCtaCteInfo(c) {
    if (!c) return { total: 0, count: 0, detalle: [] };
    const orig = c.arqueoOriginalCajero && typeof c.arqueoOriginalCajero === 'object' ? c.arqueoOriginalCajero : null;
    const savedDetalle = Array.isArray(c.ctaCteDetalle) && c.ctaCteDetalle.length > 0
      ? c.ctaCteDetalle
      : (Array.isArray(orig?.ctaCteDetalle) && orig.ctaCteDetalle.length > 0 ? orig.ctaCteDetalle : []);
    let total = round2(Number(c.totalCtaCte ?? orig?.totalCtaCte ?? 0) || 0);
    let count = Number(c.ctaCteCount ?? orig?.ctaCteCount ?? savedDetalle.length) || 0;
    if (savedDetalle.length > 0) {
      if (total === 0) {
        total = round2(savedDetalle.reduce((acc, it) => acc + (Number(it.importe) || 0), 0));
      }
      return { total, count: Math.max(count, savedDetalle.length), detalle: savedDetalle };
    }

    // Fallback para cierres anteriores: buscar comprobantes en Cuenta Corriente de esa caja y fecha
    const cajaKey = String(c.cajaId || '').trim();
    const fechaCierreStr = String(c.fechaCierre || (c.fechaHora ? String(c.fechaHora).split(' ')[0] : '')).trim();
    const srvArr = Array.isArray(STATE.ventasDb?.comprobantesPorCaja?.[cajaKey])
      ? STATE.ventasDb.comprobantesPorCaja[cajaKey]
      : [];
    const locArr = Array.isArray(STATE.turnosCajas?.[cajaKey]) ? STATE.turnosCajas[cajaKey] : [];
    const seen = new Set();
    const fallbackDetalle = [];
    for (const item of [...srvArr, ...locArr]) {
      if (!item || String(item.entryType || 'venta').toLowerCase() === 'recibo' || String(item.entryType || 'venta').toLowerCase() === 'retiro') continue;
      const itemFecha = String(item.fechaHora || '').split(' ')[0] || '';
      if (fechaCierreStr && itemFecha && itemFecha !== fechaCierreStr) continue;
      const p = item.payment;
      const mp = String(item.medioPago || '').toLowerCase();
      const isCtaCteSale =
        (p && typeof p === 'object' && String(p.method || '').toLowerCase() === 'ctacte') ||
        mp.includes('cuenta corriente') ||
        mp.includes('cta. cte') ||
        mp.includes('cta cte');
      if (!isCtaCteSale) continue;
      const nroComp = item.numeroCompleto || `${String(item.pv || '').padStart(4, '0')}-${String(item.nro || '').padStart(8, '0')}`;
      if (seen.has(nroComp)) continue;
      seen.add(nroComp);
      const imp = round2(Math.abs(Number(item.importe) || 0));
      const isNC = /cr[eé]dito/i.test(String(item.tipoBase || item.tipo || ''));
      const sign = isNC ? -1 : 1;
      fallbackDetalle.push({
        numeroCompleto: nroComp,
        tipo: String(item.tipo || `${item.tipoBase || 'Factura'} ${item.letra || 'B'}`).trim(),
        cliente: String(item.cliente || 'CLIENTE').trim().toUpperCase(),
        clienteCodigo: String(item.clienteCodigo || ''),
        fechaHora: String(item.fechaHora || ''),
        importe: round2(imp * sign)
      });
    }
    if (total > 0 && fallbackDetalle.length > 0) {
      const sumFallback = round2(fallbackDetalle.reduce((acc, it) => acc + (Number(it.importe) || 0), 0));
      if (Math.abs(sumFallback - total) < 1) {
        return { total, count: fallbackDetalle.length, detalle: fallbackDetalle };
      }
    }
    if (total === 0 && fallbackDetalle.length > 0 && !c.confirmadoCajaCentral) {
      // Solo usar fallback automático cuando totalCtaCte no estaba grabado si coincide el usuario
      const sumFallback = round2(fallbackDetalle.reduce((acc, it) => acc + (Number(it.importe) || 0), 0));
      if (sumFallback > 0 && typeof c.totalCtaCte === 'undefined') {
        return { total: sumFallback, count: fallbackDetalle.length, detalle: fallbackDetalle };
      }
    }
    return { total, count, detalle: [] };
  }

  function buildCierreDetalleHtml(c, forPrintA4 = false) {
    normalizeCierreBilletesTransferidos(c);
    const planillaNum = c.numeroPlanilla
      ? String(c.numeroPlanilla).padStart(8, '0')
      : String(c.id || 1).padStart(8, '0');
    const billetesRows = Array.isArray(c.billetes) && c.billetes.length > 0
      ? c.billetes
      : BILLETES_DENOMINACIONES.map((d) => ({
          denom: d,
          nombre: `Billete de $ ${d.toLocaleString('es-AR')}`,
          cantidad: 0,
          subtotal: 0,
          cantidadRendicion: 0,
          subtotalRendicion: 0,
          cantidadCambio: 0,
          subtotalCambio: 0
        }));

    const platMap = c.plataformas && typeof c.plataformas === 'object'
      ? c.plataformas
      : createEmptyPlataformasMap();
    const ticketsList = Array.isArray(c.tickets) ? c.tickets : [];

    const efectivoRendicion = round2(Number(c.efectivoRendicion ?? c.efectivo ?? 0) || 0);
    const efectivoCambio = round2(Number(c.efectivoCambio ?? 0) || 0);
    const efectivoFinal = round2(Number(c.efectivoFinal ?? (efectivoRendicion + efectivoCambio)) || 0);

    const efectivoInicial = round2(Number(c.efectivoInicial ?? 0) || 0);
    const ventasBrutasEfec = round2(Number(c.ventasBrutasEfectivo ?? c.ingresosEfectivoBruto ?? 0) || 0);
    const notasCreditoEfec = round2(Number(c.notasCreditoEfectivo ?? 0) || 0);
    const cobranzasRecibosEfec = round2(Number(c.cobranzasRecibosEfectivo ?? 0) || 0);
    const facturasMasRecibosEfec = round2(ventasBrutasEfec + cobranzasRecibosEfec);
    const retirosEfec = round2((Number(c.retiros ?? c.retirosEfectivoTurno ?? 0) || 0) + (Number(c.egresos ?? 0) || 0));
    const ctaCteInfoAudit = resolveCierreCtaCteInfo(c);
    const totalCtaCteTurno = ctaCteInfoAudit.total;
    const ctaCteCountAudit = ctaCteInfoAudit.count;
    const ctaCteDetTextAudit = ctaCteInfoAudit.detalle.length > 0
      ? ` · ${ctaCteInfoAudit.detalle.map((d) => `${escapeHtml(d.cliente)} (${escapeHtml(d.numeroCompleto)}: $ ${formatArs(d.importe)})`).join(' · ')}`
      : '';

    // Ecuación de Cierre de Caja:
    // + Dinero de Apertura de Caja (+)
    // + Facturas y Comp. Int. A+B Efectivo (+)
    // + Recibos de Pago (+)
    // - Notas de Crédito A+B (sean ARCA o no) (-)
    // - Retiros de Caja (-)
    // - Dinero Cambio Caja (-)
    // = Dinero traspasado a Caja Central (Esperado) (=)
    const efectivoEsperadoEnCaja = round2(
      typeof c.efectivoEsperadoFinal === 'number'
        ? c.efectivoEsperadoFinal
        : efectivoInicial + facturasMasRecibosEfec - notasCreditoEfec - retirosEfec
    );
    const dineroEsperadoTraspasoCentral = round2(efectivoEsperadoEnCaja - efectivoCambio);

    // Sobre el Dinero traspasado a Caja Central es donde se determinan las diferencias
    const difVal = round2(efectivoRendicion - dineroEsperadoTraspasoCentral);
    const difPrefix = difVal > 0.009 ? '+' : '';
    const difLabel = difVal > 0.009
      ? 'SOBRANTE EN TRASPASO A CAJA CENTRAL'
      : difVal < -0.009
        ? 'FALTANTE EN TRASPASO A CAJA CENTRAL'
        : 'SIN DIFERENCIA (EXACTO)';
    const difColor = difVal > 0.009
      ? '#15803d'
      : difVal < -0.009
        ? '#b91c1c'
        : '#334155';

    const billetesTrHtml = billetesRows
      .map((b) => {
        const cantRend = Number(b.cantidadRendicion ?? b.cantidad ?? 0) || 0;
        const subRend = round2(Number(b.subtotalRendicion ?? b.subtotal ?? (Number(b.denom || 0) * cantRend)) || 0);
        const cantCamb = Number(b.cantidadCambio ?? 0) || 0;
        const subCamb = round2(Number(b.subtotalCambio ?? (Number(b.denom || 0) * cantCamb)) || 0);
        const denomNum = Number(b.denom || 0);
        const cellDenomHtml = !forPrintA4 && denomNum > 0
          ? renderBilleteDenomCellHtml(denomNum)
          : escapeHtml(b.nombre || `Billete de $ ${denomNum.toLocaleString('es-AR')}`);
        return `<tr>
          <td>${cellDenomHtml}</td>
          <td style="text-align:right;">$ ${formatArs(b.denom || 0)}</td>
          <td style="text-align:right; font-weight:700; background:#ffffff;">${cantRend}</td>
          <td style="text-align:right; font-weight:700;">$ ${formatArs(subRend)}</td>
          <td style="text-align:right; font-weight:700; background:#ffffff;">${cantCamb}</td>
          <td style="text-align:right; font-weight:700;">$ ${formatArs(subCamb)}</td>
        </tr>`;
      })
      .join('');

    const platTrHtml = PLATAFORMAS_PAGO_CIERRE.map((plat) => {
      const r = platMap[plat] || { debito: 0, credito: 0, qr: 0 };
      const sub = round2((Number(r.debito) || 0) + (Number(r.credito) || 0) + (Number(r.qr) || 0));
      return `<tr>
        <td><strong>${escapeHtml(plat)}</strong></td>
        <td style="text-align:right;">$ ${formatArs(r.debito || 0)}</td>
        <td style="text-align:right;">$ ${formatArs(r.credito || 0)}</td>
        <td style="text-align:right;">$ ${formatArs(r.qr || 0)}</td>
        <td style="text-align:right; font-weight:800;">$ ${formatArs(sub)}</td>
      </tr>`;
    }).join('');

    const ticketsTrHtml = ticketsList.length > 0
      ? ticketsList
          .map(
            (tk) => `<tr>
              <td>${escapeHtml(tk.tipo || 'TICKET')}</td>
              <td>${escapeHtml(tk.referencia || '—')}</td>
              <td style="text-align:right; font-weight:700;">$ ${formatArs(tk.importe || 0)}</td>
            </tr>`
          )
          .join('')
      : `<tr><td colspan="3" style="text-align:center; color:#64748b;">Sin tickets registrados en Otros Valores</td></tr>`;

    return `
      <div class="cierre-audit-sheet">
        ${
          forPrintA4
            ? `<div class="cierre-print-hdr" style="display:flex; justify-content:space-between; align-items:flex-start; border-bottom:2px solid #1e293b; padding-bottom:5px; margin-bottom:7px;">
                <div>
                  <div style="font-size:13.5pt; font-weight:800; letter-spacing:-0.02em;">CASA NUEVA SUPER · PLANILLA DE RENDICIÓN DIARIA</div>
                  <div style="font-size:8.8pt; color:#334155; margin-top:1px;">Paso de Fondos desde <strong>${escapeHtml(c.cajaNombre || 'Caja')}</strong> (${escapeHtml(c.cajaOrigenLabel || '')}) hacia <strong>${escapeHtml(c.cajaDestinoLabel || 'CAJA CENTRAL - Nº: 000001')}</strong></div>
                </div>
                <div style="text-align:right; white-space:nowrap;">
                  <div style="font-size:11.5pt; font-weight:800;">PLANILLA N° ${escapeHtml(planillaNum)}</div>
                  <div style="font-size:8.5pt; color:#334155;">Fecha/Hora: ${escapeHtml(c.fechaHora || '')} · Cajero: <strong>${escapeHtml(c.usuario || '')}</strong></div>
                </div>
              </div>`
            : ''
        }

        <div class="cierre-audit-summary-grid">
          <div class="cierre-audit-card">
            <span>Caja Origen → Destino</span>
            <strong>${escapeHtml(c.cajaNombre || 'Caja')} → Caja Central</strong>
            <small style="display:block; color:var(--text-secondary); font-size:0.74rem; margin-top:0.15rem;">${escapeHtml(c.cajaOrigenLabel || `PV ${c.pvFiscal || ''} / ${c.pvInterno || ''}`)} · ${escapeHtml(c.tipoRendicion || 'Cierre de caja')}</small>
          </div>
          <div class="cierre-audit-card">
            <span>Dinero Traspasado a Caja Central</span>
            <strong style="color:#1e40af;">$ ${formatArs(efectivoRendicion)}</strong>
            <small style="display:block; color:var(--text-secondary); font-size:0.74rem; margin-top:0.15rem;">Esperado a Central: $ ${formatArs(dineroEsperadoTraspasoCentral)} · Cambio en Caja: $ ${formatArs(efectivoCambio)}</small>
          </div>
          <div class="cierre-audit-card">
            <span>Diferencia (sobre Traspaso a Central)</span>
            <strong style="color:${difColor};">${difPrefix}$ ${formatArs(difVal)}</strong>
            <small style="display:block; color:${difColor}; font-weight:700; font-size:0.74rem; margin-top:0.15rem;">${escapeHtml(difLabel)}</small>
          </div>
          <div class="cierre-audit-card">
            <span>Tarjetas / QR / Otros / Transf.</span>
            <strong>$ ${formatArs(round2((Number(c.tarjetasTotal) || 0) + (Number(c.otrosValoresTotal) || 0) + (Number(c.transferencia) || 0)))}</strong>
            <small style="display:block; color:var(--text-secondary); font-size:0.74rem; margin-top:0.15rem;">Posnet: $ ${formatArs(c.tarjetasTotal ?? 0)} · Otros/Transf: $ ${formatArs((Number(c.otrosValoresTotal) || 0) + (Number(c.transferencia) || 0))}</small>
          </div>
          <div class="cierre-audit-card">
            <span>Total Recibido en Caja Central</span>
            <strong style="color:var(--brand-gold-dark);">$ ${formatArs(c.total ?? 0)}</strong>
            <small style="display:block; color:var(--text-secondary); font-size:0.74rem; margin-top:0.15rem;">Efec. a Central ($ ${formatArs(efectivoRendicion)}) + Valores</small>
          </div>
        </div>

        <!-- ECUACIÓN DE AUDITORÍA DE CIERRE DE CAJA (SOLO VISIBLE EN CAJA CENTRAL) -->
        <div class="cierre-audit-eq-section" style="margin-top:0.85rem;">
          <h3 class="cierre-audit-sec-title" style="font-size:0.88rem; font-weight:800; margin:0 0 0.4rem;">1. Ecuación de Cierre de Caja y Diferencia sobre Dinero Traspasado a Caja Central</h3>
          <table class="cierre-classic-table cierre-eq-table" style="font-size:0.83rem;">
            <thead>
              <tr>
                <th style="text-align:left;">Concepto del Cierre de Caja</th>
                <th style="text-align:right; width:190px;">Importe ($)</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td><strong>(+) Dinero de Apertura de Caja</strong></td>
                <td style="text-align:right; font-weight:700; color:#15803d;">+ $ ${formatArs(efectivoInicial)}</td>
              </tr>
              <tr>
                <td><strong>(+) Facturas y Comp. Int. A+B Efectivo</strong></td>
                <td style="text-align:right; font-weight:700; color:#15803d;">+ $ ${formatArs(ventasBrutasEfec)}</td>
              </tr>
              <tr>
                <td><strong>(+) Recibos de Pago</strong></td>
                <td style="text-align:right; font-weight:700; color:#15803d;">+ $ ${formatArs(cobranzasRecibosEfec)}</td>
              </tr>
              <tr>
                <td><strong>(-) Notas de Créditos A+B y Comp. Int. NC A+B</strong></td>
                <td style="text-align:right; font-weight:700; color:#b91c1c;">− $ ${formatArs(notasCreditoEfec)}</td>
              </tr>
              <tr>
                <td><strong>(-) Retiros de Caja</strong></td>
                <td style="text-align:right; font-weight:700; color:#b91c1c;">− $ ${formatArs(retirosEfec)}</td>
              </tr>
              <tr>
                <td><strong>(-) Dinero Cambio Caja</strong></td>
                <td style="text-align:right; font-weight:700; color:#b91c1c;">− $ ${formatArs(efectivoCambio)}</td>
              </tr>
              <tr style="background:#e2e8f0;">
                <td><strong>(=) Dinero a Traspasar a Caja Central (Esperado)</strong></td>
                <td style="text-align:right; font-weight:800;">$ ${formatArs(dineroEsperadoTraspasoCentral)}</td>
              </tr>
              <tr style="background:#eff6ff;">
                <td><strong>Dinero Traspasado a Caja Central (Arqueado)</strong></td>
                <td style="text-align:right; font-weight:800; color:#1e40af;">$ ${formatArs(efectivoRendicion)}</td>
              </tr>
              <tr style="background:${difVal > 0.009 ? '#dcfce7' : difVal < -0.009 ? '#fee2e2' : '#f1f5f9'};">
                <td><strong>Diferencia de Caja (${escapeHtml(difLabel)})</strong></td>
                <td style="text-align:right; font-weight:900; color:${difColor};">${difPrefix}$ ${formatArs(difVal)}</td>
              </tr>
              <tr style="background:#f8fafc; color:#475569;">
                <td><strong>(i) Ventas en Cuenta Corriente del Turno</strong> <span style="font-weight:500;">(No es movimiento de efectivo)</span></td>
                <td style="text-align:right; font-weight:700; color:#475569;">$ ${formatArs(totalCtaCteTurno)}</td>
              </tr>
            </tbody>
          </table>
        </div>

        <div class="cierre-audit-bottom-grid">
          <div class="cierre-audit-col">
            <h3 class="cierre-audit-sec-title" style="font-size:0.88rem; font-weight:800; margin:0 0 0.4rem;">2. Detalle de Billetes (A Caja Central vs. Cambio en Caja)</h3>
            <table class="cierre-classic-table" style="font-size:0.82rem;">
              <thead>
                <tr>
                  <th style="text-align:left;">Nombre</th>
                  <th style="text-align:right;">Valor Nominal</th>
                  <th class="col-group-rendicion" style="text-align:right;">Cant. Central</th>
                  <th class="col-group-rendicion" style="text-align:right;">Total Central</th>
                  <th class="col-group-cambio" style="text-align:right;">Cant. Cambio</th>
                  <th class="col-group-cambio" style="text-align:right;">Total Cambio</th>
                </tr>
              </thead>
              <tbody>${billetesTrHtml}</tbody>
              <tfoot>
                <tr style="font-weight:800; background:#ffffff;">
                  <td colspan="3">SUBTOTALES EFECTIVO</td>
                  <td style="text-align:right; color:#1e40af; white-space:nowrap;">$ ${formatArs(efectivoRendicion)}</td>
                  <td></td>
                  <td style="text-align:right; color:#15803d; white-space:nowrap;">$ ${formatArs(efectivoCambio)}</td>
                </tr>
                <tr style="font-weight:900; background:#e2e8f0;">
                  <td colspan="5">EFECTIVO FINAL (TRASPASADO A CENTRAL + CAMBIO EN CAJA)</td>
                  <td style="text-align:right; white-space:nowrap;">$ ${formatArs(efectivoFinal)}</td>
                </tr>
              </tfoot>
            </table>
          </div>

          <div class="cierre-audit-col cierre-audit-col--right" style="display:flex; flex-direction:column; gap:0.85rem;">
            <div>
              <h3 class="cierre-audit-sec-title" style="font-size:0.88rem; font-weight:800; margin:0 0 0.4rem;">3. Tarjetas y QR por Plataforma de Pago</h3>
              <table class="cierre-classic-table" style="font-size:0.82rem;">
                <thead>
                  <tr>
                    <th style="text-align:left;">Plataforma</th>
                    <th style="text-align:right;">Débito</th>
                    <th style="text-align:right;">Crédito</th>
                    <th style="text-align:right;">QR</th>
                    <th style="text-align:right;">Subtotal</th>
                  </tr>
                </thead>
                <tbody>${platTrHtml}</tbody>
                <tfoot>
                  <tr style="font-weight:800; background:#ffffff;">
                    <td>TOTALES</td>
                    <td style="text-align:right; white-space:nowrap;">$ ${formatArs(c.tarjetasDebito ?? 0)}</td>
                    <td style="text-align:right; white-space:nowrap;">$ ${formatArs(c.tarjetasCredito ?? 0)}</td>
                    <td style="text-align:right; white-space:nowrap;">$ ${formatArs(c.tarjetasQr ?? 0)}</td>
                    <td style="text-align:right; white-space:nowrap;">$ ${formatArs(c.tarjetasTotal ?? 0)}</td>
                  </tr>
                  <tr style="background:#f8fafc;">
                    <td colspan="4"><strong>Ventas en Cuenta Corriente del Turno:</strong> <span style="color:#475569;">(Imputado en Cta. Cte. Clientes)</span></td>
                    <td style="text-align:right; font-weight:800; white-space:nowrap;">$ ${formatArs(totalCtaCteTurno)}</td>
                  </tr>
                </tfoot>
              </table>
            </div>

            <div>
              <h3 class="cierre-audit-sec-title" style="font-size:0.88rem; font-weight:800; margin:0 0 0.4rem;">4. Otros Valores (Tickets recibidos por el cajero)</h3>
              <table class="cierre-classic-table" style="font-size:0.82rem;">
                <thead>
                  <tr>
                    <th style="text-align:left;">Tipo de Ticket</th>
                    <th style="text-align:left;">N° / Referencia</th>
                    <th style="text-align:right;">Importe</th>
                  </tr>
                </thead>
                <tbody>${ticketsTrHtml}</tbody>
                <tfoot>
                  <tr style="font-weight:800; background:#ffffff;">
                    <td colspan="2">TOTAL OTROS VALORES</td>
                    <td style="text-align:right; white-space:nowrap;">$ ${formatArs(c.otrosValoresTotal ?? 0)}</td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>
        </div>

        ${
          c.observacion
            ? `<div class="cierre-audit-obs" style="margin-top:0.85rem; padding:0.65rem 0.85rem; border:1px solid var(--border-subtle); border-radius:var(--radius-sm); font-size:0.84rem;">
                <strong>Observación:</strong> ${escapeHtml(c.observacion)}
              </div>`
            : ''
        }

        ${
          forPrintA4
            ? `<div class="cierre-print-signatures" style="display:grid; grid-template-columns:1fr 1fr; gap:40px; margin-top:18px; padding-top:8px; text-align:center; font-size:8.8pt; break-inside:avoid; page-break-inside:avoid;">
                <div style="border-top:1px solid #334155; padding-top:5px;">
                  <strong>Firma Cajero / Entregó (${escapeHtml(c.usuario || '')})</strong><br>
                  <span>${escapeHtml(c.cajaNombre || '')}</span>
                </div>
                <div style="border-top:1px solid #334155; padding-top:5px;">
                  <strong>Recibió Conforme · Caja Central</strong><br>
                  <span>${escapeHtml(c.cajaDestinoLabel || 'CAJA CENTRAL - Nº: 000001')}</span>
                </div>
              </div>`
            : ''
        }
      </div>
    `;
  }

  // -------------------------------------------------------------------------
  // VISUALIZACIÓN E IMPRESIÓN A4 DEL ARQUEO ORIGINAL TAL COMO LO PASÓ EL CAJERO
  // Permite en Caja Central previsualizar en pantalla y luego imprimir A4
  // -------------------------------------------------------------------------
  let activeArqueoCajeroCierre = null;

  const ARQUEO_CAJERO_SHEET_CSS = `
    .arq-caj-sheet {
      font-family: Arial, sans-serif;
      color: #0f172a;
      font-size: 9pt;
      background: #ffffff;
      max-width: 210mm;
      margin: 0 auto;
      padding: 10mm 11mm;
      border-radius: 6px;
      box-shadow: 0 4px 18px rgba(15, 23, 42, 0.12);
      box-sizing: border-box;
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
    .arq-caj-sheet .hdr {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 12px;
      border-bottom: 2px solid #0f172a;
      padding-bottom: 6px;
      margin-bottom: 8px;
    }
    .arq-caj-sheet .hdr h1 {
      margin: 0;
      font-size: 13pt;
      letter-spacing: -0.02em;
      color: #0f172a;
    }
    .arq-caj-sheet .badge-orig {
      display: inline-block;
      background: #1e3a8a;
      color: #ffffff;
      padding: 2.5px 8px;
      border-radius: 4px;
      font-size: 7.8pt;
      font-weight: 800;
      margin-top: 3px;
    }
    .arq-caj-sheet .meta-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 6px;
      margin-bottom: 8px;
    }
    @media (max-width: 680px) {
      .arq-caj-sheet {
        padding: 12px;
      }
      .arq-caj-sheet .hdr {
        flex-direction: column;
      }
      .arq-caj-sheet .meta-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }
    .arq-caj-sheet .meta-card {
      border: 1px solid #cbd5e1;
      background: #f8fafc;
      border-radius: 5px;
      padding: 5px 8px;
    }
    .arq-caj-sheet .meta-card span {
      display: block;
      font-size: 7.3pt;
      color: #475569;
      text-transform: uppercase;
      font-weight: 700;
    }
    .arq-caj-sheet .meta-card strong {
      display: block;
      font-size: 10.2pt;
      margin-top: 2px;
    }
    .arq-caj-sheet h2 {
      font-size: 9.2pt;
      margin: 8px 0 4px;
      color: #0f172a;
      text-transform: uppercase;
      border-left: 3px solid #1e3a8a;
      padding-left: 6px;
    }
    .arq-caj-sheet table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 6px;
    }
    .arq-caj-sheet th,
    .arq-caj-sheet td {
      border: 1px solid #cbd5e1;
      padding: 3.5px 6px;
      font-size: 8.2pt;
      text-align: left;
      color: #0f172a;
    }
    .arq-caj-sheet th {
      background: #f1f5f9;
      font-weight: 800;
    }
    .arq-caj-sheet .firmas {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 40px;
      margin-top: 16px;
      text-align: center;
      font-size: 8.3pt;
      break-inside: avoid;
      page-break-inside: avoid;
    }
    .arq-caj-sheet .firma-box {
      border-top: 1px solid #334155;
      padding-top: 4px;
    }
  `;

  function buildArqueoOriginalCajeroDataAndHtml(cierreParam) {
    const c = cierreParam || activeArqueoCajeroCierre || CIERRE_STATE.activeCentralCierre || centralEditPlanillaState?.activeCierre;
    if (!c) return null;
    normalizeCierreBilletesTransferidos(c);

    const orig = c.arqueoOriginalCajero && typeof c.arqueoOriginalCajero === 'object'
      ? c.arqueoOriginalCajero
      : null;

    const planillaNum = c.numeroPlanilla
      ? String(c.numeroPlanilla).padStart(8, '0')
      : String(c.id || 1).padStart(8, '0');

    // Reconstruir los billetes exactamente tal como los declaró el cajero al cerrar
    const declRendMap = orig?.billetesDeclaradosCajero || c.billetesDeclaradosCajero || null;
    const declCambMap = orig?.billetesCambioDeclaradosCajero || c.billetesCambioDeclaradosCajero || null;
    const origBilletesArr = Array.isArray(orig?.billetes) ? orig.billetes : (Array.isArray(c.billetes) ? c.billetes : []);

    let sumRendCajero = 0;
    let sumCambCajero = 0;
    let cantRendCajero = 0;
    let cantCambCajero = 0;

    const billetesRowsHtml = BILLETES_DENOMINACIONES.map((denom) => {
      const rowOrig = origBilletesArr.find((b) => Number(b?.denom) === Number(denom));
      const qRend = declRendMap && typeof declRendMap[denom] !== 'undefined'
        ? Math.max(0, Math.floor(Number(declRendMap[denom]) || 0))
        : Math.max(0, Math.floor(Number(rowOrig?.cantidadRendicion ?? rowOrig?.cantidad ?? 0) || 0));
      const qCamb = declCambMap && typeof declCambMap[denom] !== 'undefined'
        ? Math.max(0, Math.floor(Number(declCambMap[denom]) || 0))
        : Math.max(0, Math.floor(Number(rowOrig?.cantidadCambio ?? 0) || 0));

      const subRend = round2(denom * qRend);
      const subCamb = round2(denom * qCamb);
      sumRendCajero = round2(sumRendCajero + subRend);
      sumCambCajero = round2(sumCambCajero + subCamb);
      cantRendCajero += qRend;
      cantCambCajero += qCamb;

      return `<tr>
        <td><strong>Billete de $ ${denom.toLocaleString('es-AR')}</strong></td>
        <td style="text-align:right;">$ ${formatArs(denom)}</td>
        <td style="text-align:right; font-weight:800; background:#eff6ff; color:#1e3a8a;">${qRend}</td>
        <td style="text-align:right; font-weight:800; background:#eff6ff; color:#1e3a8a;">$ ${formatArs(subRend)}</td>
        <td style="text-align:center; width:125px; color:#64748b;">[ &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ]</td>
        <td style="text-align:right; font-weight:700; background:#f0fdf4; color:#14532d;">${qCamb}</td>
        <td style="text-align:right; font-weight:700; background:#f0fdf4; color:#14532d;">$ ${formatArs(subCamb)}</td>
      </tr>`;
    }).join('');

    const efectivoRendicionCajero = orig && typeof orig.efectivoRendicion === 'number'
      ? round2(orig.efectivoRendicion)
      : typeof c.efectivoDeclaradoCajero === 'number' && c.efectivoDeclaradoCajero > 0
        ? round2(c.efectivoDeclaradoCajero)
        : sumRendCajero > 0
          ? sumRendCajero
          : round2(Number(c.efectivoRendicion ?? c.efectivo ?? 0) || 0);

    const efectivoCambioCajero = orig && typeof orig.efectivoCambio === 'number'
      ? round2(orig.efectivoCambio)
      : typeof c.efectivoCambioDeclaradoCajero === 'number'
        ? round2(c.efectivoCambioDeclaradoCajero)
        : sumCambCajero > 0
          ? sumCambCajero
          : round2(Number(c.efectivoCambio ?? 0) || 0);

    const efectivoFinalCajero = round2(efectivoRendicionCajero + efectivoCambioCajero);

    const efectivoInicial = round2(Number(c.efectivoInicial ?? 0) || 0);
    const ventasBrutasEfec = round2(Number(c.ventasBrutasEfectivo ?? c.ingresosEfectivoBruto ?? 0) || 0);
    const notasCreditoEfec = round2(Number(c.notasCreditoEfectivo ?? 0) || 0);
    const cobranzasRecibosEfec = round2(Number(c.cobranzasRecibosEfectivo ?? 0) || 0);
    const facturasMasRecibosEfec = round2(ventasBrutasEfec + cobranzasRecibosEfec);
    const retirosEfec = round2((Number(orig?.retiros ?? c.retiros ?? c.retirosEfectivoTurno ?? 0) || 0) + (Number(orig?.egresos ?? c.egresos ?? 0) || 0));
    const ctaCteInfo = resolveCierreCtaCteInfo(c);
    const totalCtaCteTurno = ctaCteInfo.total;
    const ctaCteCountTurno = ctaCteInfo.count;
    const ctaCteDetalleStr = ctaCteInfo.detalle.length > 0
      ? ` <span style="color:#334155; font-weight:600;">[${ctaCteInfo.detalle.map((d) => `${escapeHtml(d.cliente)} (${escapeHtml(d.numeroCompleto)}: $ ${formatArs(d.importe)})`).join(' · ')}]</span>`
      : '';

    const efectivoEsperadoEnCaja = round2(
      typeof c.efectivoEsperadoFinal === 'number'
        ? c.efectivoEsperadoFinal
        : efectivoInicial + facturasMasRecibosEfec - notasCreditoEfec - retirosEfec
    );
    const dineroEsperadoTraspasoCentral = round2(efectivoEsperadoEnCaja - efectivoCambioCajero);
    const difCajero = round2(efectivoRendicionCajero - dineroEsperadoTraspasoCentral);
    const difPrefix = difCajero > 0.009 ? '+ ' : difCajero < -0.009 ? '- ' : '';
    const difColor = difCajero > 0.009 ? '#15803d' : difCajero < -0.009 ? '#b91c1c' : '#0f172a';
    const difLabel = difCajero > 0.009
      ? 'SOBRANTE EN TRASPASO A CAJA CENTRAL'
      : difCajero < -0.009
        ? 'FALTANTE EN TRASPASO A CAJA CENTRAL'
        : 'SIN DIFERENCIA (EXACTO)';

    const platMap = (orig?.plataformas && typeof orig.plataformas === 'object')
      ? orig.plataformas
      : (c.plataformas && typeof c.plataformas === 'object' ? c.plataformas : createEmptyPlataformasMap());
    const platRes = sumPlataformasMap(platMap);

    const platRowsHtml = PLATAFORMAS_PAGO_CIERRE.map((plat) => {
      const r = platMap[plat] || { debito: 0, credito: 0, qr: 0 };
      const sub = round2((Number(r.debito) || 0) + (Number(r.credito) || 0) + (Number(r.qr) || 0));
      return `<tr>
        <td><strong>${escapeHtml(plat)}</strong></td>
        <td style="text-align:right;">$ ${formatArs(r.debito || 0)}</td>
        <td style="text-align:right;">$ ${formatArs(r.credito || 0)}</td>
        <td style="text-align:right;">$ ${formatArs(r.qr || 0)}</td>
        <td style="text-align:right; font-weight:800;">$ ${formatArs(sub)}</td>
        <td style="text-align:center; width:75px; color:#64748b;">[ &nbsp;&nbsp;&nbsp; ]</td>
      </tr>`;
    }).join('');

    const ticketsList = Array.isArray(orig?.tickets) ? orig.tickets : (Array.isArray(c.tickets) ? c.tickets : []);
    const otrosTotal = round2(Number(orig?.otrosValoresTotal ?? c.otrosValoresTotal ?? 0) || 0);
    const transfVal = round2(Number(orig?.transferencia ?? c.transferencia ?? 0) || 0);
    const totalValoresCajero = round2(efectivoRendicionCajero + platRes.total + otrosTotal + transfVal);
    const brandTitle = String(ACTIVE_BRAND?.shortSuper || 'CASA NUEVA SUPER').toUpperCase();

    const sheetHtml = `
      <div class="arq-caj-sheet">
        <div class="hdr">
          <div>
            <h1>${escapeHtml(brandTitle)} · ARQUEO PASADO POR EL CAJERO</h1>
            <div class="badge-orig">HOJA DE CHEQUEO Y CONTROL DE DIFERENCIAS EN CAJA CENTRAL</div>
            <div style="font-size:8.4pt; color:#334155; margin-top:3px;">
              Caja: <strong>${escapeHtml(c.cajaNombre || 'Caja')}</strong> (${escapeHtml(c.cajaOrigenLabel || '')}) ·
              Cajero de Turno: <strong>${escapeHtml(c.usuario || '')}</strong> ·
              Comprobantes emitidos: <strong>${Number(c.cantidadComprobantes) || 0}</strong>
            </div>
          </div>
          <div style="text-align:right;">
            <div style="font-size:11.8pt; font-weight:900;">PLANILLA N° ${escapeHtml(planillaNum)}</div>
            <div style="font-size:8.3pt; color:#334155;">Fecha Apertura: ${escapeHtml(c.fechaApertura || '')}</div>
            <div style="font-size:8.3pt; color:#334155;">Fecha/Hora Cierre: <strong>${escapeHtml(c.fechaHora || '')}</strong></div>
          </div>
        </div>

        <div class="meta-grid">
          <div class="meta-card">
            <span>Esperado a Traspasar a Central</span>
            <strong>$ ${formatArs(dineroEsperadoTraspasoCentral)}</strong>
          </div>
          <div class="meta-card">
            <span>Dinero Traspasado por Cajero</span>
            <strong style="color:#1e40af;">$ ${formatArs(efectivoRendicionCajero)}</strong>
          </div>
          <div class="meta-card">
            <span>Dinero Cambio Caja (Cajero)</span>
            <strong style="color:#15803d;">$ ${formatArs(efectivoCambioCajero)}</strong>
          </div>
          <div class="meta-card" style="border-color:${difColor};">
            <span>Diferencia sobre Traspaso</span>
            <strong style="color:${difColor};">${difPrefix}$ ${formatArs(Math.abs(difCajero))}</strong>
          </div>
        </div>

        <h2>1. Ecuación del Cierre de Caja (Determinación de Diferencias sobre el Dinero Traspasado a Caja Central)</h2>
        <table>
          <thead>
            <tr>
              <th>Concepto del Cierre de Caja</th>
              <th style="text-align:right; width:150px;">Importe ($)</th>
              <th style="text-align:center; width:85px;">Chequeo</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td><strong>(+) Dinero de Apertura de Caja</strong></td>
              <td style="text-align:right; font-weight:700; color:#15803d;">+ $ ${formatArs(efectivoInicial)}</td>
              <td style="text-align:center;">[ &nbsp;&nbsp;&nbsp; ]</td>
            </tr>
            <tr>
              <td><strong>(+) Facturas y Comp. Int. A+B Efectivo</strong></td>
              <td style="text-align:right; font-weight:700; color:#15803d;">+ $ ${formatArs(ventasBrutasEfec)}</td>
              <td style="text-align:center;">[ &nbsp;&nbsp;&nbsp; ]</td>
            </tr>
            <tr>
              <td><strong>(+) Recibos de Pago</strong></td>
              <td style="text-align:right; font-weight:700; color:#15803d;">+ $ ${formatArs(cobranzasRecibosEfec)}</td>
              <td style="text-align:center;">[ &nbsp;&nbsp;&nbsp; ]</td>
            </tr>
            <tr>
              <td><strong>(-) Notas de Créditos A+B y Comp. Int. NC A+B</strong></td>
              <td style="text-align:right; font-weight:700; color:#b91c1c;">− $ ${formatArs(notasCreditoEfec)}</td>
              <td style="text-align:center;">[ &nbsp;&nbsp;&nbsp; ]</td>
            </tr>
            <tr>
              <td><strong>(-) Retiros de Caja</strong></td>
              <td style="text-align:right; font-weight:700; color:#b91c1c;">− $ ${formatArs(retirosEfec)}</td>
              <td style="text-align:center;">[ &nbsp;&nbsp;&nbsp; ]</td>
            </tr>
            <tr>
              <td><strong>(-) Dinero Cambio Caja</strong></td>
              <td style="text-align:right; font-weight:700; color:#b91c1c;">− $ ${formatArs(efectivoCambioCajero)}</td>
              <td style="text-align:center;">[ &nbsp;&nbsp;&nbsp; ]</td>
            </tr>
            <tr style="background:#e2e8f0; font-weight:800;">
              <td><strong>(=) Dinero a Traspasar a Caja Central (Esperado)</strong></td>
              <td style="text-align:right;">$ ${formatArs(dineroEsperadoTraspasoCentral)}</td>
              <td style="text-align:center;">—</td>
            </tr>
            <tr style="background:#eff6ff; font-weight:800;">
              <td><strong>Dinero Traspasado a Caja Central (Pasado por el Cajero)</strong></td>
              <td style="text-align:right; color:#1e40af;">$ ${formatArs(efectivoRendicionCajero)}</td>
              <td style="text-align:center;">[ &nbsp;&nbsp;&nbsp; ]</td>
            </tr>
            <tr style="background:${difCajero > 0.009 ? '#dcfce7' : difCajero < -0.009 ? '#fee2e2' : '#f8fafc'}; font-weight:900;">
              <td><strong>Diferencia (${escapeHtml(difLabel)})</strong></td>
              <td style="text-align:right; color:${difColor};">${difPrefix}$ ${formatArs(Math.abs(difCajero))}</td>
              <td style="text-align:center;">—</td>
            </tr>
            <tr style="background:#f8fafc; color:#475569;">
              <td><strong>(i) Ventas en Cuenta Corriente del Turno</strong> (No es movimiento de efectivo)</td>
              <td style="text-align:right; font-weight:700; color:#475569;">$ ${formatArs(totalCtaCteTurno)}</td>
              <td style="text-align:center;">—</td>
            </tr>
          </tbody>
        </table>

        <h2>2. Detalle de Billetes Declarados por el Cajero (Para Punteo Físico en Caja Central)</h2>
        <table>
          <thead>
            <tr>
              <th>Denominación</th>
              <th style="text-align:right;">Valor Nominal</th>
              <th style="text-align:right; background:#dbeafe; color:#1e3a8a;">Cant. a Central (Cajero)</th>
              <th style="text-align:right; background:#dbeafe; color:#1e3a8a;">Total a Central ($)</th>
              <th style="text-align:center;">Recuento Caja Central</th>
              <th style="text-align:right; background:#dcfce7; color:#14532d;">Cant. Cambio Caja</th>
              <th style="text-align:right; background:#dcfce7; color:#14532d;">Total Cambio ($)</th>
            </tr>
          </thead>
          <tbody>${billetesRowsHtml}</tbody>
          <tfoot>
            <tr style="font-weight:800; background:#f8fafc;">
              <td colspan="2">SUBTOTALES DECLARADOS POR EL CAJERO</td>
              <td style="text-align:right; color:#1e3a8a;">${cantRendCajero} bill.</td>
              <td style="text-align:right; color:#1e3a8a;">$ ${formatArs(efectivoRendicionCajero)}</td>
              <td style="text-align:center; color:#475569;">$ ....................</td>
              <td style="text-align:right; color:#14532d;">${cantCambCajero} bill.</td>
              <td style="text-align:right; color:#14532d;">$ ${formatArs(efectivoCambioCajero)}</td>
            </tr>
            <tr style="font-weight:900; background:#e2e8f0;">
              <td colspan="6">EFECTIVO TOTAL ARQUEADO POR EL CAJERO (TRASPASO A CENTRAL + CAMBIO EN CAJA)</td>
              <td style="text-align:right;">$ ${formatArs(efectivoFinalCajero)}</td>
            </tr>
          </tfoot>
        </table>

        <h2>3. Tarjetas / QR por Plataforma, Transferencias y Otros Valores Declarados por el Cajero</h2>
        <table>
          <thead>
            <tr>
              <th>Plataforma Posnet / QR</th>
              <th style="text-align:right;">Débito</th>
              <th style="text-align:right;">Crédito</th>
              <th style="text-align:right;">QR</th>
              <th style="text-align:right;">Subtotal</th>
              <th style="text-align:center; width:75px;">Chequeo</th>
            </tr>
          </thead>
          <tbody>${platRowsHtml}</tbody>
          <tfoot>
            <tr style="font-weight:800; background:#f8fafc;">
              <td>TOTAL TARJETAS Y QR</td>
              <td style="text-align:right;">$ ${formatArs(platRes.debito)}</td>
              <td style="text-align:right;">$ ${formatArs(platRes.credito)}</td>
              <td style="text-align:right;">$ ${formatArs(platRes.qr)}</td>
              <td style="text-align:right;">$ ${formatArs(platRes.total)}</td>
              <td style="text-align:center;">[ &nbsp;&nbsp;&nbsp; ]</td>
            </tr>
            <tr>
              <td colspan="4"><strong>Transferencias Bancarias Declaradas:</strong> $ ${formatArs(transfVal)} · <strong>Otros Valores / Tickets (${ticketsList.length}):</strong> $ ${formatArs(otrosTotal)}</td>
              <td style="text-align:right; font-weight:800;">$ ${formatArs(round2(transfVal + otrosTotal))}</td>
              <td style="text-align:center;">[ &nbsp;&nbsp;&nbsp; ]</td>
            </tr>
            <tr>
              <td colspan="4"><strong>Ventas en Cuenta Corriente del Turno:</strong> <span style="color:#475569;">(Imputado en Cta. Cte. Clientes)</span></td>
              <td style="text-align:right; font-weight:800;">$ ${formatArs(totalCtaCteTurno)}</td>
              <td style="text-align:center;">[ &nbsp;&nbsp;&nbsp; ]</td>
            </tr>
            <tr style="font-weight:900; background:#e2e8f0;">
              <td colspan="4">TOTAL GENERAL RENDIDO A CAJA CENTRAL (EFECTIVO TRASPASADO + TARJETAS/QR + TRANSF. + OTROS)</td>
              <td style="text-align:right;">$ ${formatArs(totalValoresCajero)}</td>
              <td style="text-align:center;">—</td>
            </tr>
          </tfoot>
        </table>

        ${
          (orig?.observacion || c.observacion)
            ? `<div style="border:1px solid #cbd5e1; border-radius:4px; padding:5px 8px; margin-top:5px; font-size:8.2pt;">
                <strong>Observación del Cajero:</strong> ${escapeHtml(orig?.observacion || c.observacion || '')}
              </div>`
            : ''
        }

        <div class="firmas">
          <div class="firma-box">
            <strong>Firma Cajero que Rindió (${escapeHtml(c.usuario || '')})</strong><br>
            <span>${escapeHtml(c.cajaNombre || '')}</span>
          </div>
          <div class="firma-box">
            <strong>Control y Punteo en Caja Central</strong><br>
            <span>Firma Responsable Caja Central</span>
          </div>
        </div>
      </div>
    `;

    return { c, planillaNum, sheetHtml };
  }

  window.openArqueoOriginalCajeroDialog = function (cierreParam) {
    const built = buildArqueoOriginalCajeroDataAndHtml(cierreParam);
    if (!built) return;
    activeArqueoCajeroCierre = built.c;

    const dlg = document.getElementById('arqueo-cajero-preview-dialog');
    const body = document.getElementById('arqueo-cajero-preview-body');
    const title = document.getElementById('arqueo-cajero-preview-title');
    const badge = document.getElementById('arqueo-cajero-preview-badge');
    if (!dlg || !body) {
      window.printArqueoOriginalCajeroA4(built.c);
      return;
    }

    ['cierre-detalle-central-dialog', 'central-edit-planilla-dialog'].forEach((underId) => {
      const underDlg = document.getElementById(underId);
      if (underDlg?.open) {
        underDlg.dataset.prevClosedby = underDlg.getAttribute('closedby') || 'any';
        underDlg.setAttribute('closedby', 'none');
      }
    });

    if (badge) {
      badge.textContent = `PLANILLA N° ${built.planillaNum} · ${String(built.c.cajaNombre || 'CAJA').toUpperCase()} · ARQUEO CAJERO`;
    }
    if (title) {
      title.textContent = `Arqueo Pasado por el Cajero · ${built.c.usuario || ''} · ${built.c.fechaHora || ''}`;
    }

    const adminEditApBtn = document.getElementById('btn-admin-edit-apertura-from-arqueo');
    if (adminEditApBtn) {
      adminEditApBtn.hidden = !isErpAdminUser(STATE.currentUser);
    }

    body.innerHTML = `<style>${ARQUEO_CAJERO_SHEET_CSS}</style>${built.sheetHtml}`;
    if (!dlg.open) {
      dlg.showModal();
    }
    requestAnimationFrame(() => {
      document.getElementById('btn-print-arqueo-cajero-confirm')?.focus();
    });
  };

  window.printArqueoOriginalCajeroA4 = function (cierreParam) {
    const built = buildArqueoOriginalCajeroDataAndHtml(cierreParam);
    if (!built) return;
    const { c, planillaNum, sheetHtml } = built;

    const w = window.open('', '_blank', 'width=1050,height=820');
    if (!w) {
      window.print();
      return;
    }

    w.document.open();
    w.document.write(`<!DOCTYPE html>
      <html lang="es-AR">
      <head>
        <meta charset="UTF-8">
        <title>Arqueo del Cajero · Planilla N° ${escapeHtml(planillaNum)} (${escapeHtml(c.usuario || '')})</title>
        <style>
          @page { size: A4 portrait; margin: 7mm 10mm; }
          html, body {
            margin: 0;
            padding: 0;
            background: #ffffff;
            -webkit-print-color-adjust: exact;
            print-color-adjust: exact;
          }
          ${ARQUEO_CAJERO_SHEET_CSS}
          .arq-caj-sheet {
            max-width: none !important;
            padding: 0 !important;
            border-radius: 0 !important;
            box-shadow: none !important;
          }
        </style>
      </head>
      <body>
        ${sheetHtml}
        <script>
          window.addEventListener('load', function () {
            setTimeout(function () {
              window.focus();
              window.print();
            }, 220);
          });
        <\/script>
      </body>
      </html>`);
    w.document.close();
  };

  function openCierreDetalleCentralDialog(cierre) {
    if (!cierre) return;
    CIERRE_STATE.activeCentralCierre = cierre;
    const dlg = document.getElementById('cierre-detalle-central-dialog');
    const body = document.getElementById('cierre-detalle-central-body');
    const title = document.getElementById('cierre-detalle-central-title');
    const badge = document.getElementById('cierre-central-det-badge');
    if (!dlg || !body) return;

    const planillaNum = cierre.numeroPlanilla
      ? String(cierre.numeroPlanilla).padStart(8, '0')
      : String(cierre.id || 1).padStart(8, '0');
    if (badge) {
      badge.textContent = `PLANILLA N° ${planillaNum} · ${String(cierre.cajaNombre || 'CAJA').toUpperCase()} → CAJA CENTRAL`;
    }
    if (title) {
      title.textContent = `Planilla de Rendición Diaria · ${cierre.fechaHora || ''} · ${cierre.usuario || ''}`;
    }

    body.innerHTML = buildCierreDetalleHtml(cierre, false);
    const btnConfirmDet = document.getElementById('btn-confirm-cierre-det');
    if (btnConfirmDet) {
      if (cierre.confirmadoCajaCentral) {
        btnConfirmDet.disabled = true;
        btnConfirmDet.textContent = '✅ Fondos Recibidos en Caja';
      } else {
        btnConfirmDet.disabled = false;
        btnConfirmDet.textContent = '✅ Confirmar Recepción y Pasar Fondos a Caja';
      }
    }
    if (!dlg.open) {
      dlg.showModal();
    }
  }

