  function renderFuncOmnibox(rawQuery) {
    if (!funcResultsBox) return;
    const q = normalizeStr(rawQuery);
    const tokens = q.split(/\s+/).filter(Boolean);

    currentFuncMatches = ERP_FUNCTIONS_DIRECTORY.filter((item) => {
      if (tokens.length === 0) return true;
      const hay = normalizeStr(`${item.title} ${item.category} ${item.keywords}`);
      return tokens.every((t) => hay.includes(t));
    });

    if (rawQuery.trim().length >= 2) {
      const cleanTerm = rawQuery.trim();
      currentFuncMatches.push({
        title: `Buscar "${cleanTerm}" en Artículos y Stock`,
        category: 'Búsqueda directa',
        keywords: '',
        action: () => {
          switchSection('sec-articulos');
          const fq = document.getElementById('filter-q');
          fq.value = cleanTerm;
          applyCatalogFilters(1);
        }
      });
      currentFuncMatches.push({
        title: `Buscar "${cleanTerm.toUpperCase()}" en Padrón de Clientes`,
        category: 'Clientes y Cta. Cte.',
        keywords: '',
        action: () => {
          switchSection('sec-clientes');
          loadClientesDatabase().then(() => {
            const cq = document.getElementById('cli-filter-q');
            if (cq) {
              cq.value = cleanTerm.toUpperCase();
              applyClientesFilters(1);
            }
          });
        }
      });
      currentFuncMatches.push({
        title: `Buscar "${cleanTerm.toUpperCase()}" en Padrón de Proveedores`,
        category: 'Proveedores y Cta. Cte.',
        keywords: '',
        action: () => {
          switchSection('sec-proveedores');
          loadClientesDatabase().then(() => {
            const pq = document.getElementById('prov-filter-q');
            if (pq) {
              pq.value = cleanTerm.toUpperCase();
              applyProveedoresFilters(1);
            }
          });
        }
      });
    }

    highlightedFuncIdx = 0;
    funcResultsBox.textContent = '';

    currentFuncMatches.slice(0, 8).forEach((item, idx) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'omnibox-item' + (idx === highlightedFuncIdx ? ' is-highlighted' : '');
      btn.setAttribute('role', 'option');

      const titleSpan = document.createElement('span');
      titleSpan.className = 'omnibox-item-title';
      titleSpan.textContent = item.title;

      const badgeSpan = document.createElement('span');
      badgeSpan.className = 'omnibox-item-badge';
      badgeSpan.textContent = item.category;

      btn.appendChild(titleSpan);
      btn.appendChild(badgeSpan);

      btn.addEventListener('mousedown', (e) => {
        e.preventDefault();
        item.action();
        funcSearchInput.value = '';
        funcResultsBox.hidden = true;
        funcSearchInput.setAttribute('aria-expanded', 'false');
        funcSearchInput.blur();
      });

      funcResultsBox.appendChild(btn);
    });

    const hasItems = currentFuncMatches.length > 0;
    funcResultsBox.hidden = !hasItems;
    funcSearchInput.setAttribute('aria-expanded', String(hasItems));
  }

  if (funcSearchInput && funcResultsBox) {
    funcSearchInput.addEventListener('focus', () => {
      renderFuncOmnibox(funcSearchInput.value);
    });

    funcSearchInput.addEventListener('input', () => {
      renderFuncOmnibox(funcSearchInput.value);
    });

    funcSearchInput.addEventListener('blur', () => {
      setTimeout(() => {
        funcResultsBox.hidden = true;
        funcSearchInput.setAttribute('aria-expanded', 'false');
      }, 150);
    });

    funcSearchInput.addEventListener('keydown', (e) => {
      const visibleItems = funcResultsBox.querySelectorAll('.omnibox-item');
      if (e.key === 'ArrowDown' && visibleItems.length > 0) {
        e.preventDefault();
        highlightedFuncIdx = (highlightedFuncIdx + 1) % visibleItems.length;
        visibleItems.forEach((el, i) => el.classList.toggle('is-highlighted', i === highlightedFuncIdx));
      } else if (e.key === 'ArrowUp' && visibleItems.length > 0) {
        e.preventDefault();
        highlightedFuncIdx = (highlightedFuncIdx - 1 + visibleItems.length) % visibleItems.length;
        visibleItems.forEach((el, i) => el.classList.toggle('is-highlighted', i === highlightedFuncIdx));
      } else if (e.key === 'Enter') {
        e.preventDefault();
        const chosen = currentFuncMatches[highlightedFuncIdx];
        if (chosen) {
          chosen.action();
          funcSearchInput.value = '';
          funcResultsBox.hidden = true;
          funcSearchInput.setAttribute('aria-expanded', 'false');
          funcSearchInput.blur();
        }
      } else if (e.key === 'Escape') {
        funcResultsBox.hidden = true;
        funcSearchInput.setAttribute('aria-expanded', 'false');
        funcSearchInput.blur();
      }
    });
  }

  function showDashboard(user, options = {}) {
    const uKey = String(user.username || '').toLowerCase();
    const dir = ADMIN_DIRECTORY[uKey] || {};
    const mergedUser = Object.assign({}, dir, user, {
      username: uKey || user.username,
      role: uKey === PRIMARY_ADMIN_USER ? 'Administrador' : (user.role || dir.role || 'Operador'),
      whatsapp: user.whatsapp !== undefined ? user.whatsapp : (dir.whatsapp || ''),
      avatar: user.avatar !== undefined ? user.avatar : (dir.avatar || ''),
      modules: uKey === PRIMARY_ADMIN_USER ? [...DEFAULT_MODULE_KEYS] : (Array.isArray(user.modules) ? user.modules : (dir.modules || [...DEFAULT_MODULE_KEYS]))
    });
    STATE.currentUser = mergedUser;
    document.documentElement.setAttribute('data-has-session', '1');
    savePersistedAdminSession(mergedUser);
    applyThemeMode(getUserThemePreference(mergedUser.username), false);
    updateTopbarUserDisplay(mergedUser);
    applyUserAllowedModules(mergedUser);
    setDefaultVendedorFromLoggedUser();
    loginView.hidden = true;
    dashboardView.hidden = false;
    loadCatalogDatabase();
    loadClientesDatabase();
    loadVentasDatabase();
    loadFondosLocalState();
    syncFondosFromServer();
    syncUsersFromServer();
    startOpenCajaWebOrderWatcher();

    const savedNav = !options.isFreshLogin ? getPersistedNavState() : null;
    const savedNavUser = String(savedNav?.username || '').toLowerCase();
    const canRestoreNav = Boolean(
      savedNav &&
      savedNav.sectionId &&
      (!savedNavUser || savedNavUser === String(mergedUser.username || '').toLowerCase())
    );
    if (canRestoreNav && savedNav.activeCajaId && CAJAS_CONFIG[savedNav.activeCajaId]) {
      STATE.activeCajaId = savedNav.activeCajaId;
    }
    const targetSecId =
      canRestoreNav &&
      document.getElementById(savedNav.sectionId) &&
      isSectionAllowedForCurrentUser(savedNav.sectionId)
        ? savedNav.sectionId
        : 'sec-inicio';

    if (targetSecId === 'sec-caja-pos') {
      openCajaPos(STATE.activeCajaId || 'caja1', true);
    } else if (targetSecId === 'sec-club-previo') {
      openCajaPos(STATE.activeCajaId || 'caja1', false);
    } else if (targetSecId === 'sec-submenu-caja') {
      openCajaSubmenu(STATE.activeCajaId || 'caja1');
    } else {
      switchSection(targetSecId);
    }
  }

