  // =========================================================================
  // BIDIRECTIONAL AUTOMATIC PRICE CALCULATIONS (Neto <-> Final & Margins)
  // =========================================================================
  const inpCostoNeto = document.getElementById('art-costo-neto');
  const inpCostoFinal = document.getElementById('art-costo-final');
  const selAlicuota = document.getElementById('art-alicuota');
  const chkUsaConfig = document.getElementById('art-usa-config-precio');
  const selConfigPrecio = document.getElementById('art-config-precio');

  const inpMargenMin = document.getElementById('art-margen-min');
  const inpMinNeto = document.getElementById('art-min-neto');
  const inpMinFinal = document.getElementById('art-min-final');

  const inpMargenMay = document.getElementById('art-margen-may');
  const inpMayNeto = document.getElementById('art-may-neto');
  const inpMayFinal = document.getElementById('art-may-final');
  const inpPuntosCanje = document.getElementById('art-puntos-canje');
  const chkPuntosCanjeManual = document.getElementById('art-puntos-canje-manual');
  const chkCanjeFidelizacion = document.getElementById('art-canje-fidelizacion');
  const boxCanjeConfig = document.getElementById('art-canje-config-box');

  function syncModalAutoCanjePoints() {
    if (!inpPuntosCanje || (chkPuntosCanjeManual && chkPuntosCanjeManual.checked)) return;
    const factor = Number(STATE.fidelizacionConfig.factorCanje) || 1.12;
    const minFin = Number(inpMinFinal.value) || 0;
    inpPuntosCanje.value = String(Math.max(1, Math.round(minFin * factor)));
  }

  chkCanjeFidelizacion?.addEventListener('change', () => {
    if (boxCanjeConfig) boxCanjeConfig.hidden = !chkCanjeFidelizacion.checked;
    if (chkCanjeFidelizacion.checked) {
      syncModalAutoCanjePoints();
    }
  });

  chkPuntosCanjeManual?.addEventListener('change', () => {
    if (!chkPuntosCanjeManual.checked) {
      syncModalAutoCanjePoints();
    }
  });
  inpPuntosCanje?.addEventListener('input', () => {
    if (chkPuntosCanjeManual) chkPuntosCanjeManual.checked = true;
  });

  function recalcSalesListsFromCostAndMargins() {
    const ivaFrac = getSelectedIvaFraction();
    const costoNeto = Number(inpCostoNeto.value) || 0;
    const mMin = Number(inpMargenMin.value) || 0;
    const mMay = Number(inpMargenMay.value) || 0;

    if (costoNeto > 0) {
      const minNeto = round2(costoNeto * (1 + mMin / 100));
      const minFinal = round2(minNeto * (1 + ivaFrac));
      inpMinNeto.value = String(minNeto);
      inpMinFinal.value = String(minFinal);

      const mayNeto = round2(costoNeto * (1 + mMay / 100));
      const mayFinal = round2(mayNeto * (1 + ivaFrac));
      inpMayNeto.value = String(mayNeto);
      inpMayFinal.value = String(mayFinal);
      syncModalAutoCanjePoints();
    }
  }

  // Costo Neto -> Costo Final (+ Sales Lists)
  inpCostoNeto.addEventListener('input', () => {
    const ivaFrac = getSelectedIvaFraction();
    const neto = Number(inpCostoNeto.value) || 0;
    inpCostoFinal.value = String(round2(neto * (1 + ivaFrac)));
    recalcSalesListsFromCostAndMargins();
  });

  // Costo Final -> Costo Neto (+ Sales Lists)
  inpCostoFinal.addEventListener('input', () => {
    const ivaFrac = getSelectedIvaFraction();
    const fin = Number(inpCostoFinal.value) || 0;
    inpCostoNeto.value = String(round2(fin / (1 + ivaFrac)));
    recalcSalesListsFromCostAndMargins();
  });

  // Alicuota IVA change -> Recalculate Finals from Netos (bloqueada cuando hay Configuración de Precios activa)
  selAlicuota.addEventListener('change', () => {
    if (chkUsaConfig.checked && (Number(selConfigPrecio.value) || 0) > 0) {
      syncArticleModalIvaLockUI();
      return;
    }
    const ivaFrac = getSelectedIvaFraction();
    const cNeto = Number(inpCostoNeto.value) || 0;
    inpCostoFinal.value = String(round2(cNeto * (1 + ivaFrac)));

    const minNeto = Number(inpMinNeto.value) || 0;
    inpMinFinal.value = String(round2(minNeto * (1 + ivaFrac)));

    const mayNeto = Number(inpMayNeto.value) || 0;
    inpMayFinal.value = String(round2(mayNeto * (1 + ivaFrac)));
    syncModalAutoCanjePoints();
  });

  // Price Configuration selection -> Apply associated IVA (locked) + Minorista & Mayorista margins
  function getFirstAvailablePriceConfigId() {
    if (Array.isArray(STATE.configuracionesPrecios) && STATE.configuracionesPrecios.length > 0) {
      return Number(STATE.configuracionesPrecios[0].id) || 0;
    }
    const firstValidOpt = Array.from(selConfigPrecio.options).find(opt => Number(opt.value) > 0);
    return firstValidOpt ? Number(firstValidOpt.value) : 0;
  }

  function applySelectedPriceConfig() {
    if (!chkUsaConfig.checked) {
      syncArticleModalIvaLockUI();
      return;
    }
    let cfgId = Number(selConfigPrecio.value) || 0;
    if (cfgId <= 0 || !STATE.configPreciosMap.has(cfgId)) {
      const firstId = getFirstAvailablePriceConfigId();
      if (firstId > 0) {
        selConfigPrecio.value = String(firstId);
        cfgId = firstId;
      }
    }
    const cfg = STATE.configPreciosMap.get(cfgId);
    if (cfg) {
      syncArticleModalIvaLockUI();
      const ivaFrac = getSelectedIvaFraction();
      const cNeto = Number(inpCostoNeto.value) || 0;
      if (cNeto > 0) {
        inpCostoFinal.value = String(round2(cNeto * (1 + ivaFrac)));
      }
      inpMargenMin.value = String(cfg.margenMinorista);
      inpMargenMay.value = String(cfg.margenMayorista);
      recalcSalesListsFromCostAndMargins();
    }
  }

  selConfigPrecio.addEventListener('change', () => {
    const cfgId = Number(selConfigPrecio.value) || 0;
    if (cfgId > 0) {
      chkUsaConfig.checked = true;
      applySelectedPriceConfig();
    } else {
      chkUsaConfig.checked = false;
      syncArticleModalIvaLockUI();
    }
  });

  chkUsaConfig.addEventListener('change', () => {
    if (chkUsaConfig.checked) {
      applySelectedPriceConfig();
    } else {
      selConfigPrecio.value = '0';
      syncArticleModalIvaLockUI();
    }
  });

  // Nueva o Editar Configuración de Precios (con Alícuota IVA obligatoria y cambio de Nombre)
  const priceConfigDialog = document.getElementById('price-config-dialog');
  document.getElementById('btn-add-price-config')?.addEventListener('click', () => {
    openNewPriceConfigModal(null);
  });
  document.getElementById('btn-close-price-config-dialog')?.addEventListener('click', () => {
    priceConfigDialog?.close();
  });
  document.getElementById('btn-cancel-price-config-dialog')?.addEventListener('click', () => {
    priceConfigDialog?.close();
  });
  document.getElementById('price-config-form')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const alertCfgEl = document.getElementById('price-config-form-alert');
    if (alertCfgEl) alertCfgEl.hidden = true;

    const editId = Number(document.getElementById('new-cfg-edit-id')?.value || 0);
    const rawName = (document.getElementById('new-cfg-nombre')?.value || '').trim().toUpperCase();
    if (!rawName) {
      if (alertCfgEl) {
        alertCfgEl.textContent = 'Ingresá el nombre de la Configuración de Precios.';
        alertCfgEl.hidden = false;
      }
      return;
    }
    const existsCfg = STATE.configuracionesPrecios.some(
      (c) => Number(c.id) !== editId && String(c.nombre || '').trim().toUpperCase() === rawName
    );
    if (existsCfg) {
      if (alertCfgEl) {
        alertCfgEl.textContent = `Ya existe otra configuración llamada "${rawName}".`;
        alertCfgEl.hidden = false;
      }
      return;
    }

    const selNewAlic = document.getElementById('new-cfg-alicuota');
    const chosenAlicId = Number(selNewAlic?.value) || 5;
    const chosenAlicObj = STATE.alicuotasMap.get(chosenAlicId) || { id: 5, descripcion: '21%', porcentaje: 21 };
    const newIvaPct = Number(chosenAlicObj.porcentaje ?? 21);
    const ivaFrac = newIvaPct / 100;
    const factorCanje = Number(STATE.fidelizacionConfig.factorCanje) || 1.12;
    const mMinNew = round2(document.getElementById('new-cfg-margen-min')?.value || 0);
    const mMayNew = round2(document.getElementById('new-cfg-margen-may')?.value || 0);

    if (editId > 0) {
      const targetCfg = STATE.configuracionesPrecios.find((c) => Number(c.id) === editId);
      if (targetCfg) {
        targetCfg.nombre = rawName;
        targetCfg.margenMinorista = mMinNew;
        targetCfg.margenMayorista = mMayNew;
        targetCfg.idAlicuotaIva = Number(chosenAlicObj.id);
        targetCfg.iva = newIvaPct;
        STATE.configPreciosMap.set(editId, targetCfg);

        STATE.articulos.forEach((a) => {
          if (Number(a.cp) === editId && Number(a.ucp) === 1) {
            const oldSnap = { p1f: a.p1f, p2f: a.p2f };
            a.iv = targetCfg.idAlicuotaIva;
            a.iva = targetCfg.iva;
            a.m1 = targetCfg.margenMinorista;
            a.m2 = targetCfg.margenMayorista;
            if (Number(a.cn) > 0) {
              a.cfn = round2(Number(a.cn) * (1 + ivaFrac));
              a.p1n = round2(Number(a.cn) * (1 + a.m1 / 100));
              a.p1f = round2(a.p1n * (1 + ivaFrac));
              a.p2n = round2(Number(a.cn) * (1 + a.m2 / 100));
              a.p2f = round2(a.p2n * (1 + ivaFrac));
              if (Number(a.pfidManual) !== 1 && a.pfid !== undefined) {
                a.pfid = Math.max(1, Math.round(a.p1f * factorCanje));
              }
            }
            registerGondolaPriceUpdate(a, oldSnap, `Config. Precios: ${targetCfg.nombre}`);
          }
        });
        saveLocalGondolaQueue();
      }
    } else {
      const nextCfgId = STATE.configuracionesPrecios.reduce((maxId, c) => Math.max(maxId, Number(c.id) || 0), 0) + 1;
      const newCfgObj = {
        id: nextCfgId,
        nombre: rawName,
        margenMinorista: mMinNew,
        margenMayorista: mMayNew,
        idAlicuotaIva: Number(chosenAlicObj.id),
        iva: newIvaPct
      };
      STATE.configuracionesPrecios.push(newCfgObj);
      STATE.configPreciosMap.set(newCfgObj.id, newCfgObj);
    }

    STATE.configuracionesPrecios.sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es-AR'));

    const btnSubCfg = document.getElementById('btn-submit-price-config');
    if (btnSubCfg) {
      btnSubCfg.disabled = true;
      btnSubCfg.textContent = 'Guardando...';
    }
    await persistPriceConfigsToServer();
    if (btnSubCfg) {
      btnSubCfg.disabled = false;
      btnSubCfg.textContent = editId > 0 ? '💾 Guardar Cambios' : '💾 Crear Configuración';
    }

    populateMasterSelects();
    syncArticleModalIvaLockUI();
    applyCatalogFilters(STATE.currentPage);
    renderPriceConfigsSection();
    priceConfigDialog?.close();
  });

  // Minorista Margin -> Minorista Neto & Final
  inpMargenMin.addEventListener('input', () => {
    const ivaFrac = getSelectedIvaFraction();
    const costoNeto = Number(inpCostoNeto.value) || 0;
    const mMin = Number(inpMargenMin.value) || 0;
    if (costoNeto > 0) {
      const minNeto = round2(costoNeto * (1 + mMin / 100));
      inpMinNeto.value = String(minNeto);
      inpMinFinal.value = String(round2(minNeto * (1 + ivaFrac)));
      syncModalAutoCanjePoints();
    }
  });

  // Minorista Neto -> Minorista Final (& update Margin)
  inpMinNeto.addEventListener('input', () => {
    const ivaFrac = getSelectedIvaFraction();
    const minNeto = Number(inpMinNeto.value) || 0;
    inpMinFinal.value = String(round2(minNeto * (1 + ivaFrac)));
    const costoNeto = Number(inpCostoNeto.value) || 0;
    if (costoNeto > 0) {
      inpMargenMin.value = String(round2(((minNeto / costoNeto) - 1) * 100));
    }
    syncModalAutoCanjePoints();
  });

  // Minorista Final -> Minorista Neto (& update Margin)
  inpMinFinal.addEventListener('input', () => {
    const ivaFrac = getSelectedIvaFraction();
    const minFinal = Number(inpMinFinal.value) || 0;
    const minNeto = round2(minFinal / (1 + ivaFrac));
    inpMinNeto.value = String(minNeto);
    const costoNeto = Number(inpCostoNeto.value) || 0;
    if (costoNeto > 0) {
      inpMargenMin.value = String(round2(((minNeto / costoNeto) - 1) * 100));
    }
    syncModalAutoCanjePoints();
  });

  // Mayorista Margin -> Mayorista Neto & Final
  inpMargenMay.addEventListener('input', () => {
    const ivaFrac = getSelectedIvaFraction();
    const costoNeto = Number(inpCostoNeto.value) || 0;
    const mMay = Number(inpMargenMay.value) || 0;
    if (costoNeto > 0) {
      const mayNeto = round2(costoNeto * (1 + mMay / 100));
      inpMayNeto.value = String(mayNeto);
      inpMayFinal.value = String(round2(mayNeto * (1 + ivaFrac)));
    }
  });

  // Mayorista Neto -> Mayorista Final (& update Margin)
  inpMayNeto.addEventListener('input', () => {
    const ivaFrac = getSelectedIvaFraction();
    const mayNeto = Number(inpMayNeto.value) || 0;
    inpMayFinal.value = String(round2(mayNeto * (1 + ivaFrac)));
    const costoNeto = Number(inpCostoNeto.value) || 0;
    if (costoNeto > 0) {
      inpMargenMay.value = String(round2(((mayNeto / costoNeto) - 1) * 100));
    }
  });

  // Mayorista Final -> Mayorista Neto (& update Margin)
  inpMayFinal.addEventListener('input', () => {
    const ivaFrac = getSelectedIvaFraction();
    const mayFinal = Number(inpMayFinal.value) || 0;
    const mayNeto = round2(mayFinal / (1 + ivaFrac));
    inpMayNeto.value = String(mayNeto);
    const costoNeto = Number(inpCostoNeto.value) || 0;
    if (costoNeto > 0) {
      inpMargenMay.value = String(round2(((mayNeto / costoNeto) - 1) * 100));
    }
  });

  // =========================================================================
  // INVENTORY FORMULA: Stock Inicial + Compras = Stock Final
  // =========================================================================
  const inpStockIni = document.getElementById('art-stock-inicial');
  const inpStockComp = document.getElementById('art-stock-compras');
  const inpStockFin = document.getElementById('art-stock-final');

  function recalcStockFinal() {
    const allowFrac = Boolean(document.getElementById('art-fraccionar')?.checked);
    const si = allowFrac ? (Number(inpStockIni.value) || 0) : Math.round(Number(inpStockIni.value) || 0);
    const sc = allowFrac ? (Number(inpStockComp.value) || 0) : Math.round(Number(inpStockComp.value) || 0);
    inpStockFin.value = String(allowFrac ? round2(si + sc) : Math.round(si + sc));
  }

  inpStockIni.addEventListener('keydown', (e) => {
    preventDecimalKeyIfNotFrac(e, Boolean(document.getElementById('art-fraccionar')?.checked));
  });
  inpStockComp.addEventListener('keydown', (e) => {
    preventDecimalKeyIfNotFrac(e, Boolean(document.getElementById('art-fraccionar')?.checked));
  });
  inpStockIni.addEventListener('input', () => {
    stripDecimalInputIfNotFrac(inpStockIni, Boolean(document.getElementById('art-fraccionar')?.checked));
    recalcStockFinal();
  });
  inpStockComp.addEventListener('input', () => {
    stripDecimalInputIfNotFrac(inpStockComp, Boolean(document.getElementById('art-fraccionar')?.checked));
    recalcStockFinal();
  });

  document.getElementById('btn-add-purchase-qty').addEventListener('click', () => {
    const allowFrac = Boolean(document.getElementById('art-fraccionar')?.checked);
    const addStr = prompt(
      allowFrac
        ? 'Ingresá la cantidad comprada que querés sumar al stock:'
        : 'Ingresá la cantidad entera comprada que querés sumar al stock:'
    );
    if (addStr === null) return;
    const rawVal = Number(addStr.replace(',', '.'));
    if (!isNaN(rawVal) && rawVal !== 0) {
      const addVal = allowFrac ? round2(rawVal) : Math.round(rawVal);
      if (addVal === 0) return;
      const currentComp = Number(inpStockComp.value) || 0;
      inpStockComp.value = String(allowFrac ? round2(currentComp + addVal) : Math.round(currentComp + addVal));
      recalcStockFinal();
    }
  });

  // =========================================================================
  // SMART WEB IMAGE SEARCH & WHITE-BACKGROUND UPLOAD
  // =========================================================================
  document.getElementById('btn-smart-web-search').addEventListener('click', async () => {
    const panel = document.getElementById('smart-candidates-panel');
    const grid = document.getElementById('smart-candidates-grid');
    panel.hidden = false;
    grid.textContent = 'Buscando imágenes en fondo blanco...';

    const nombre = document.getElementById('art-nombre').value.trim();
    const firstBcInput = document.querySelector('#barcodes-rows-container .bc-code-input');
    const barcode = firstBcInput ? firstBcInput.value.trim() : '';

    let candidates = [];
    try {
      const res = await fetch(
        `api/catalog.php?action=smart_images&barcode=${encodeURIComponent(barcode)}&nombre=${encodeURIComponent(nombre)}`
      );
      if (res.ok) {
        const json = await res.json();
        if (json.ok && Array.isArray(json.candidates)) {
          candidates = json.candidates;
        }
      }
    } catch {}

    if (candidates.length === 0) {
      const q1 = `${barcode} ${nombre} supermercado argentina fondo blanco`.trim();
      const q2 = `${nombre} producto envase fondo blanco`.trim();
      candidates = [
        { label: 'Opción 1', url: `https://tse1.mm.bing.net/th?q=${encodeURIComponent(q1)}&w=400&h=400&c=7&rs=1&p=0` },
        { label: 'Opción 2', url: `https://tse2.mm.bing.net/th?q=${encodeURIComponent(q2)}&w=400&h=400&c=7&rs=1&p=0` },
        { label: 'Opción 3', url: `https://tse3.mm.bing.net/th?q=${encodeURIComponent(nombre + ' argentina')}&w=400&h=400&c=7&rs=1&p=0` },
        { label: 'Opción 4', url: `https://tse4.mm.bing.net/th?q=${encodeURIComponent(barcode + ' producto')}&w=400&h=400&c=7&rs=1&p=0` }
      ];
    }

    grid.textContent = '';
    candidates.forEach((cand) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'candidate-thumb-btn';
      btn.title = cand.label;
      const im = document.createElement('img');
      im.src = cand.url;
      im.alt = cand.label;
      btn.appendChild(im);
      btn.addEventListener('click', () => {
        STATE.currentEditImage = cand.url;
        updateModalImagePreview({ id: STATE.editingArticleId || 1, n: nombre, bc: [] });
      });
      grid.appendChild(btn);
    });
  });

  document.getElementById('art-file-upload').addEventListener('change', async (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    try {
      const whiteDataUrl = await normalizeImageFileToWhiteBg(file);
      STATE.currentEditImage = whiteDataUrl;
      updateModalImagePreview({ id: STATE.editingArticleId || 1, n: '', bc: [] });

      // Upload to server if available
      const codigo = document.getElementById('art-codigo').value.trim() || 'art';
      const res = await fetch('api/catalog.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'upload_image',
          codigo,
          dataUrl: whiteDataUrl
        })
      });
      if (res.ok) {
        const json = await res.json();
        if (json.ok && json.imageUrl) {
          STATE.currentEditImage = json.imageUrl;
        }
      }
    } catch {}
  });

  // =========================================================================
  // SAVE ARTICLE FORM SUBMISSION
  // =========================================================================
  const chkEnvRetMain = document.getElementById('art-envase-retornable');
  const chkEnvRetTopPill = document.getElementById('art-envase-retornable-top');
  chkEnvRetMain?.addEventListener('change', () => {
    if (chkEnvRetTopPill) chkEnvRetTopPill.checked = chkEnvRetMain.checked;
  });
  chkEnvRetTopPill?.addEventListener('change', () => {
    if (chkEnvRetMain) chkEnvRetMain.checked = chkEnvRetTopPill.checked;
  });

  const articleFormEl = document.getElementById('article-form');
  const btnSaveArticleEl = document.getElementById('btn-save-article');

  articleFormEl.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && e.target && e.target.tagName !== 'TEXTAREA' && e.target.tagName !== 'BUTTON') {
      e.preventDefault();
      e.stopPropagation();
      if (e.target.classList && e.target.classList.contains('bc-code-input')) {
        const cleaned = sanitizeScannerBarcode(e.target.value);
        if (cleaned) e.target.value = cleaned;
        e.target.dispatchEvent(new Event('input', { bubbles: true }));
      }
    }
  });

  const handleSaveArticleModal = async (e) => {
    if (e && typeof e.preventDefault === 'function') e.preventDefault();
    const alertEl = document.getElementById('article-form-alert');
    alertEl.hidden = true;

    const rawCode = document.getElementById('art-codigo').value.trim();
    const numCode = parseInt(rawCode, 10);
    if (isNaN(numCode) || numCode < 1 || numCode > 99999) {
      alertEl.textContent = 'El código debe ser un número entre 00001 y 99999.';
      alertEl.hidden = false;
      return;
    }
    const formattedCode = String(numCode).padStart(5, '0');
    const nombre = document.getElementById('art-nombre').value.trim().toUpperCase();
    if (!nombre) {
      alertEl.textContent = 'El nombre del producto es obligatorio.';
      alertEl.hidden = false;
      return;
    }

    // Check duplicate code in client state
    const duplicate = STATE.articulos.find(
      (a) => a.c === formattedCode && a.id !== STATE.editingArticleId
    );
    if (duplicate) {
      alertEl.textContent = `El código ${formattedCode} ya está en uso por "${duplicate.n}". Usá el botón "⚡ Libre" para asignar uno disponible.`;
      alertEl.hidden = false;
      return;
    }

    // Collect Suppliers + Manufacturer codes
    const suppliersList = [];
    document.querySelectorAll('#suppliers-rows-container .supplier-dyn-row').forEach((row) => {
      const pId = Number(row.querySelector('.sup-select').value) || 0;
      const cfVal = row.querySelector('.sup-cf-input').value.trim();
      if (pId > 0 || cfVal !== '') {
        suppliersList.push({ p: pId, cf: cfVal });
      }
    });

    // Collect Barcodes + Quantities
    const barcodesList = [];
    const barcodeInputs = [];
    document.querySelectorAll('#barcodes-rows-container .barcode-dyn-row').forEach((row) => {
      const inpEl = row.querySelector('.bc-code-input');
      const cVal = inpEl ? inpEl.value.trim() : '';
      const qVal = Number(row.querySelector('.bc-qty-input')?.value) || 1;
      if (cVal !== '') {
        barcodesList.push({ c: cVal, q: qVal });
        if (inpEl) barcodeInputs.push({ inpEl, cVal });
      }
    });

    // Regla de Código de Barras duplicado (dentro del mismo artículo o contra el catálogo)
    const seenBarcodesInForm = new Set();
    for (const item of barcodeInputs) {
      const upperBc = item.cVal.toUpperCase();
      if (seenBarcodesInForm.has(upperBc)) {
        const msgInterno = `⚠️ CÓDIGO DE BARRAS REPETIDO: Cargaste dos veces el mismo código de barras "${item.cVal}" dentro de este artículo.`;
        alertEl.textContent = msgInterno;
        alertEl.hidden = false;
        item.inpEl.style.borderColor = '#dc2626';
        item.inpEl.focus();
        if (typeof playFactAlertBeep === 'function') playFactAlertBeep();
        window.alert(msgInterno);
        return;
      }
      seenBarcodesInForm.add(upperBc);

      const dupBcArt = findArticleWithDuplicateBarcode(item.cVal, STATE.editingArticleId);
      if (dupBcArt) {
        const msgDup = `⚠️ CÓDIGO DE BARRAS DUPLICADO: El código "${item.cVal}" ya pertenece al producto #${dupBcArt.c} — "${dupBcArt.n}". No se permite crear ni guardar un artículo con un código de barras duplicado.`;
        alertEl.textContent = msgDup;
        alertEl.hidden = false;
        item.inpEl.style.borderColor = '#dc2626';
        item.inpEl.style.backgroundColor = '#fef2f2';
        item.inpEl.focus();
        if (typeof playFactAlertBeep === 'function') playFactAlertBeep();
        window.alert(
          `⛔ CÓDIGO DE BARRAS DUPLICADO\n\nEl código de barras "${item.cVal}" ya lo tiene asignado el producto:\n• Código: #${dupBcArt.c}\n• Producto: ${dupBcArt.n}\n\nNo se permite crear ni guardar otro artículo con este código de barras.`
        );
        return;
      }
    }

    const selAlic = document.getElementById('art-alicuota');
    const selectedCfgId = chkUsaConfig.checked ? (Number(selConfigPrecio.value) || 0) : 0;
    const activeSaveCfg = selectedCfgId > 0 ? STATE.configPreciosMap.get(selectedCfgId) : null;
    const resolvedSaveAlic = activeSaveCfg
      ? resolveAlicuotaForConfig(activeSaveCfg)
      : (() => {
          const aid = Number(selAlic.value) || 5;
          const aObj = STATE.alicuotasMap.get(aid);
          return aObj
            ? { id: Number(aObj.id), porcentaje: Number(aObj.porcentaje ?? 21) }
            : { id: aid, porcentaje: 21 };
        })();
    const alicId = resolvedSaveAlic.id;
    const ivaPct = resolvedSaveAlic.porcentaje;

    const isBaja = document.getElementById('art-baja-logica').checked;
    const fechaBaja = isBaja
      ? (document.getElementById('art-fecha-baja').value || todayFormatted())
      : null;

    const prevArt = STATE.editingArticleId
      ? STATE.articulos.find((a) => a.id === STATE.editingArticleId)
      : null;
    const factorCanje = Number(STATE.fidelizacionConfig.factorCanje) || 1.12;
    const modalCanjeManual = document.getElementById('art-puntos-canje-manual');
    const modalPuntosCanje = document.getElementById('art-puntos-canje');
    const isCanjeManual = modalCanjeManual
      ? (modalCanjeManual.checked ? 1 : 0)
      : (prevArt && Number(prevArt.pfidManual) === 1 ? 1 : 0);
    const autoCanjePts = Math.max(1, Math.round(round2(inpMinFinal.value) * factorCanje));
    const enteredCanjePts = Number(modalPuntosCanje?.value || (prevArt ? prevArt.pfid : 0));
    const finalCanjePts = isCanjeManual && enteredCanjePts > 0
      ? Math.max(1, Math.round(enteredCanjePts))
      : autoCanjePts;

    const isSaveFrac = Boolean(document.getElementById('art-fraccionar').checked);
    const normalizedBarcodesList = barcodesList.map((b) => ({
      c: b.c,
      q: isSaveFrac ? round2(Math.max(0.01, Number(b.q) || 1)) : Math.max(1, Math.round(Number(b.q) || 1))
    }));

    const newArtObj = {
      id: STATE.editingArticleId || (STATE.articulos.reduce((m, x) => Math.max(m, x.id), 0) + 1),
      c: formattedCode,
      n: nombre,
      cf: suppliersList[0] ? suppliersList[0].cf : '',
      r: Number(document.getElementById('art-rubro').value) || 0,
      mk: Number(document.getElementById('art-marca')?.value) || 0,
      p: suppliersList[0] ? suppliersList[0].p : 0,
      pr: suppliersList,
      bc: normalizedBarcodesList,
      bl: isBaja ? 1 : 0,
      fb: fechaBaja,
      fr: isSaveFrac ? 1 : 0,
      env: (document.getElementById('art-envase-retornable')?.checked || document.getElementById('art-envase-retornable-top')?.checked) ? 1 : 0,
      idEnvase: (document.getElementById('art-envase-retornable')?.checked || document.getElementById('art-envase-retornable-top')?.checked) ? OLIVER_ENVASE_RETORNABLE_ID : 0,
      cw: document.getElementById('art-carrito-web')?.checked === false ? 0 : 1,
      cfid: document.getElementById('art-canje-fidelizacion')?.checked ? 1 : 0,
      pfid: finalCanjePts,
      pfidManual: isCanjeManual,
      iv: alicId,
      iva: ivaPct,
      cn: round2(inpCostoNeto.value),
      cfn: round2(inpCostoFinal.value),
      cp: Number(selConfigPrecio.value) || 0,
      ucp: chkUsaConfig.checked ? 1 : 0,
      m1: round2(inpMargenMin.value),
      m2: round2(inpMargenMay.value),
      p1n: round2(inpMinNeto.value),
      p1f: round2(inpMinFinal.value),
      p2n: round2(inpMayNeto.value),
      p2f: round2(inpMayFinal.value),
      si: isSaveFrac ? round2(inpStockIni.value) : Math.round(Number(inpStockIni.value) || 0),
      sc: isSaveFrac ? round2(inpStockComp.value) : Math.round(Number(inpStockComp.value) || 0),
      sf: isSaveFrac
        ? round2((Number(inpStockIni.value) || 0) + (Number(inpStockComp.value) || 0))
        : Math.round((Math.round(Number(inpStockIni.value) || 0)) + (Math.round(Number(inpStockComp.value) || 0))),
      sm: (() => {
        const inpSmEl = document.getElementById('art-stock-minimo');
        const rawSm = inpSmEl ? String(inpSmEl.value).trim() : '';
        if (rawSm !== '' && !Number.isNaN(Number(rawSm))) {
          return Math.max(0, isSaveFrac ? round2(Number(rawSm)) : Math.round(Number(rawSm)));
        }
        return prevArt ? getArticleStockMinimo(prevArt) : getDefaultStockMinimoByRubro(Number(document.getElementById('art-rubro').value) || 0);
      })(),
      im: STATE.currentEditImage,
      fup: prevArt?.fup || ''
    };

    registerGondolaPriceUpdate(newArtObj, prevArt, prevArt ? 'Ficha Artículo' : 'Alta de Artículo');
    saveLocalGondolaQueue();

    const saveBtn = document.getElementById('btn-save-article');
    saveBtn.disabled = true;
    saveBtn.textContent = 'Guardando...';

    try {
      const resSave = await fetch('api/catalog.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'save_article',
          article: newArtObj
        })
      });
      if (!resSave.ok) {
        let errMsg = 'No se pudo guardar el artículo porque presenta un código duplicado.';
        try {
          const errJson = await resSave.json();
          if (errJson && errJson.message) errMsg = errJson.message;
        } catch {}
        alertEl.textContent = `⚠️ ${errMsg}`;
        alertEl.hidden = false;
        saveBtn.disabled = false;
        saveBtn.textContent = '💾 Guardar Artículo';
        if (typeof playFactAlertBeep === 'function') playFactAlertBeep();
        window.alert(`⛔ ${errMsg}`);
        return;
      }
      const jsonSave = await resSave.json();
      if (jsonSave && jsonSave.gondolaQueue) {
        STATE.gondolaQueue = normalizeGondolaQueueMap(jsonSave.gondolaQueue);
        saveLocalGondolaQueue();
        updateGondolaMenuBadges();
      }
    } catch {}

    const idx = STATE.articulos.findIndex((a) => a.id === newArtObj.id);
    if (idx >= 0) {
      STATE.articulos[idx] = newArtObj;
    } else {
      STATE.articulos.unshift(newArtObj);
    }

    saveLocalFidelizacionStore();
    updateFidelizacionKpisAndSummary();
    applyFidCatalogoFilters(STATE.fidCatPage || 1);
    renderFidQuickCanjeCards();

    saveBtn.disabled = false;
    saveBtn.textContent = '💾 Guardar Artículo';
    articleDialog.close();
    updateKpis();
    applyCatalogFilters(STATE.currentPage);
    if (typeof window.refreshFacturaProveedorViewsAfterArticleSave === 'function') {
      window.refreshFacturaProveedorViewsAfterArticleSave(newArtObj);
    }
    if (typeof window.refreshPedidosProveedoresAfterArticleSave === 'function') {
      window.refreshPedidosProveedoresAfterArticleSave(newArtObj);
    }
    if (typeof window.refreshStockValorizadoAfterArticleSave === 'function') {
      window.refreshStockValorizadoAfterArticleSave();
    }
    if (typeof window.refreshFacturaCargaRapidaAfterArticleSave === 'function') {
      window.refreshFacturaCargaRapidaAfterArticleSave(newArtObj);
    }
    if (typeof window.refreshFacturacionAfterMissingBarcodeSave === 'function') {
      window.refreshFacturacionAfterMissingBarcodeSave(newArtObj);
    }
    if (typeof window.broadcastErpRealtimeEvent === 'function') {
      window.broadcastErpRealtimeEvent({
        type: 'article_saved',
        article: newArtObj
      });
    }
  };

