  // Suggest Web Credentials button (Proveedor)
  document.getElementById('btn-prov-gen-web-credentials')?.addEventListener('click', () => {
    const rawName = document.getElementById('prov-nombre').value.trim();
    const code = document.getElementById('prov-codigo').value.trim() || '235';
    const cleanAlpha = rawName.replace(/[^A-Z0-9]/g, '').slice(0, 10) || 'PROVEEDOR';
    const uEl = document.getElementById('prov-usuario-web');
    const pEl = document.getElementById('prov-clave-web');
    if (uEl && !uEl.value.trim()) uEl.value = `${cleanAlpha}${code}`;
    if (pEl && !pEl.value.trim()) pEl.value = `CN${code}2026`;
  });

