  // --- ABM MARCA ---
  document.getElementById('btn-abm-marca-free-code')?.addEventListener('click', () => {
    const codInp = document.getElementById('abm-marca-codigo');
    if (codInp) codInp.value = findNextFreeMarcaCode(STATE.editingMarcaId);
  });

  document.getElementById('btn-abm-marca-cancel')?.addEventListener('click', () => {
    resetAbmMarcaForm();
  });

  document.getElementById('btn-abm-marca-new-focus')?.addEventListener('click', () => {
    resetAbmMarcaForm();
    document.getElementById('abm-marca-nombre')?.focus();
  });

  let abmMarcaDebounce = null;
  document.getElementById('abm-marca-q')?.addEventListener('input', () => {
    clearTimeout(abmMarcaDebounce);
    abmMarcaDebounce = setTimeout(() => applyAbmMarcasFilters(1), 90);
  });
  ['abm-marca-filter-estado', 'abm-marca-orden'].forEach((id) => {
    document.getElementById(id)?.addEventListener('change', () => applyAbmMarcasFilters(1));
  });
  document.getElementById('btn-abm-marca-prev')?.addEventListener('click', () => {
    if (STATE.abmMarcasPage > 1) applyAbmMarcasFilters(STATE.abmMarcasPage - 1);
  });
  document.getElementById('btn-abm-marca-next')?.addEventListener('click', () => {
    applyAbmMarcasFilters((STATE.abmMarcasPage || 1) + 1);
  });

  document.getElementById('abm-marca-form')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const alertEl = document.getElementById('abm-marca-alert');
    const okEl = document.getElementById('abm-marca-success');
    if (alertEl) alertEl.hidden = true;
    if (okEl) okEl.hidden = true;

    const editId = STATE.editingMarcaId ? Number(STATE.editingMarcaId) : 0;
    const rawCode = document.getElementById('abm-marca-codigo')?.value.trim().toUpperCase() || '';
    const nombre = document.getElementById('abm-marca-nombre')?.value.trim().toUpperCase() || '';
    const bl = document.getElementById('abm-marca-baja')?.checked ? 1 : 0;

    if (!nombre) {
      if (alertEl) {
        alertEl.textContent = 'EL NOMBRE DE LA MARCA ES OBLIGATORIO.';
        alertEl.hidden = false;
      }
      document.getElementById('abm-marca-nombre')?.focus();
      return;
    }

    if (editId > 0 && bl === 1) {
      const linkedCount = countArticlesByMarcaMap().counts.get(editId) || 0;
      if (linkedCount > 0) {
        if (alertEl) {
          alertEl.textContent = `NO SE PUEDE DAR DE BAJA LA MARCA "${nombre}" PORQUE TIENE ${linkedCount} PRODUCTO(S) ASOCIADO(S).`;
          alertEl.hidden = false;
        }
        return;
      }
    }

    let effectiveEditId = editId;
    let finalCode = rawCode || findNextFreeMarcaCode(editId || null);
    let wasReactivatedFromBaja = false;

    // Validar nombre duplicado (si está en baja lógica y se da de alta como activa, reactivarla automáticamente)
    const dupName = STATE.marcas.find(
      (m) => String(m.nombre || '').trim().toUpperCase() === nombre && Number(m.id) !== editId
    );
    if (dupName) {
      if (Number(dupName.bl) === 1 && bl === 0) {
        effectiveEditId = Number(dupName.id);
        finalCode = String(dupName.codigo ?? dupName.id);
        wasReactivatedFromBaja = true;
      } else {
        // Asegurar que figure activa en todos los selectores
        dupName.bl = 0;
        delete dupName.fb;
        rebuildRubrosAndMarcasMaps();
        populateMasterSelects();
        if (alertEl) {
          alertEl.textContent = `LA MARCA "${nombre}" YA ESTÁ ACTIVA EN EL PADRÓN (CÓDIGO #${dupName.codigo ?? dupName.id}) Y DISPONIBLE EN EL SELECTOR DE ARTÍCULOS.`;
          alertEl.hidden = false;
        }
        document.getElementById('abm-marca-nombre')?.focus();
        return;
      }
    }

    // Validar código duplicado
    const dupCode = STATE.marcas.find(
      (m) => String(m.codigo ?? m.id).trim().toUpperCase() === finalCode && Number(m.id) !== effectiveEditId
    );
    if (dupCode) {
      if (alertEl) {
        alertEl.textContent = `EL CÓDIGO #${finalCode} YA ESTÁ ASIGNADO A LA MARCA "${dupCode.nombre}". USÁ EL BOTÓN "⚡ LIBRE".`;
        alertEl.hidden = false;
      }
      document.getElementById('abm-marca-codigo')?.focus();
      return;
    }

    const saveBtn = document.getElementById('btn-abm-marca-save');
    if (saveBtn) saveBtn.disabled = true;

    let savedMarca = {
      id: effectiveEditId > 0 ? effectiveEditId : (STATE.marcas.reduce((mx, x) => Math.max(mx, Number(x.id) || 0), 0) + 1),
      codigo: finalCode,
      nombre,
      bl,
      fb: bl === 1 ? todayFormatted() : null
    };

    try {
      const res = await fetch('api/catalog.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'save_marca',
          marca: savedMarca
        })
      });
      if (res.ok) {
        const json = await res.json();
        if (json && json.ok === false) {
          if (saveBtn) saveBtn.disabled = false;
          if (alertEl) {
            alertEl.textContent = json.message || 'No se pudo guardar la marca.';
            alertEl.hidden = false;
          }
          return;
        }
        if (json && json.ok && json.marca) {
          savedMarca = json.marca;
        }
      }
    } catch {}

    const existingIdx = STATE.marcas.findIndex((m) => Number(m.id) === Number(savedMarca.id));
    if (existingIdx >= 0) {
      STATE.marcas[existingIdx] = Object.assign({}, STATE.marcas[existingIdx], savedMarca);
      if (Number(savedMarca.bl) !== 1) {
        delete STATE.marcas[existingIdx].fb;
      }
    } else {
      STATE.marcas.push(savedMarca);
    }

    rebuildRubrosAndMarcasMaps();
    saveLocalAbmCatalogOverrides();
    populateMasterSelects();
    updateKpis();
    resetAbmMarcaForm();
    applyAbmMarcasFilters(STATE.abmMarcasPage || 1);
    applyCatalogFilters(STATE.currentPage);

    if (saveBtn) saveBtn.disabled = false;
    if (okEl) {
      if (wasReactivatedFromBaja) {
        okEl.innerHTML = `<strong>¡Marca reactivada y habilitada!</strong> La marca <strong>#${savedMarca.codigo ?? savedMarca.id} — ${savedMarca.nombre}</strong> se encontraba en baja lógica y quedó nuevamente <strong>ACTIVA</strong> en todos los selectores de artículos.`;
      } else {
        okEl.innerHTML = editId > 0
          ? `<strong>¡Marca actualizada!</strong> Se guardaron los cambios de <strong>#${savedMarca.codigo ?? savedMarca.id} — ${savedMarca.nombre}</strong>.`
          : `<strong>¡Nueva Marca dada de alta!</strong> Se registró <strong>#${savedMarca.codigo ?? savedMarca.id} — ${savedMarca.nombre}</strong> y ya está disponible en todos los selectores de artículos.`;
      }
      okEl.hidden = false;
    }
  });

