  function setAdminEditorAvatarState(avatarUrl, userName) {
    const hiddenInp = document.getElementById('admin-edit-avatar-value');
    const previewEl = document.getElementById('admin-edit-avatar-preview');
    const galleryEl = document.getElementById('admin-edit-avatar-options');
    const cleanUrl = String(avatarUrl || '').trim();
    if (hiddenInp) hiddenInp.value = cleanUrl;
    renderUserAvatarElement(previewEl, userName || 'U', cleanUrl);
    renderAvatarGalleryPicker(galleryEl, cleanUrl, (chosenUrl) => {
      setAdminEditorAvatarState(chosenUrl, document.getElementById('admin-edit-name')?.value || userName);
    });
  }

  document.getElementById('btn-admin-upload-avatar')?.addEventListener('click', () => {
    document.getElementById('admin-edit-avatar-file')?.click();
  });

  document.getElementById('admin-edit-avatar-file')?.addEventListener('change', async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const dataUrl = await resizeUserAvatarImageFile(file);
      const currName = document.getElementById('admin-edit-name')?.value || 'U';
      setAdminEditorAvatarState(dataUrl, currName);
    } catch {}
    e.target.value = '';
  });

  document.getElementById('btn-admin-clear-avatar')?.addEventListener('click', () => {
    const currName = document.getElementById('admin-edit-name')?.value || 'U';
    setAdminEditorAvatarState('', currName);
  });

  function renderAdminModulesCheckboxes(selectedModules, isTargetPrimaryAdmin = false) {
    const gridEl = document.getElementById('admin-edit-modules-grid');
    if (!gridEl) return;
    gridEl.textContent = '';
    const expanded = isTargetPrimaryAdmin
      ? [...DEFAULT_MODULE_KEYS]
      : expandUserModulesWithDefaults(selectedModules);
    const activeSet = new Set(expanded);

    // Nodo raíz del Organigrama
    const rootWrap = document.createElement('div');
    rootWrap.className = 'admin-orgchart-root-wrap';
    const rootNode = document.createElement('div');
    rootNode.className = 'admin-orgchart-root-node';
    rootNode.innerHTML = `<span>🏢</span><span>Sistema ERP · Organigrama de Módulos y Submódulos</span>`;
    const rootStem = document.createElement('div');
    rootStem.className = 'admin-orgchart-root-stem';
    rootWrap.appendChild(rootNode);
    rootWrap.appendChild(rootStem);
    gridEl.appendChild(rootWrap);

    // Contenedor de ramas (Módulos Principales -> Submódulos)
    const branchesEl = document.createElement('div');
    branchesEl.className = 'admin-orgchart-branches';

    ALL_SYSTEM_MODULES.forEach((mod) => {
      const branch = document.createElement('div');
      branch.className = 'admin-orgchart-branch';

      const parentLbl = document.createElement('label');
      parentLbl.className = 'admin-orgchart-parent-label';

      const parentChk = document.createElement('input');
      parentChk.type = 'checkbox';
      parentChk.name = 'admin_user_module';
      parentChk.value = mod.key;
      parentChk.dataset.moduleParent = mod.key;
      parentChk.checked = activeSet.has(mod.key) || mod.key === 'perfil';
      if (isTargetPrimaryAdmin || mod.key === 'perfil') {
        parentChk.disabled = true;
      }

      const parentSpan = document.createElement('span');
      parentSpan.textContent = mod.label;

      parentLbl.appendChild(parentChk);
      parentLbl.appendChild(parentSpan);
      branch.appendChild(parentLbl);

      const subs = Array.isArray(mod.submodules) ? mod.submodules : [];
      const childCheckboxes = [];

      if (subs.length > 0) {
        const childrenWrap = document.createElement('div');
        childrenWrap.className = 'admin-orgchart-children';

        subs.forEach((sub) => {
          const childLbl = document.createElement('label');
          childLbl.className = 'admin-orgchart-child-label';

          const childChk = document.createElement('input');
          childChk.type = 'checkbox';
          childChk.name = 'admin_user_module';
          childChk.value = sub.key;
          childChk.dataset.submoduleOf = mod.key;
          childChk.checked = isTargetPrimaryAdmin || (parentChk.checked && activeSet.has(sub.key));
          if (isTargetPrimaryAdmin) {
            childChk.disabled = true;
          }
          childLbl.classList.toggle('is-checked', childChk.checked);

          const childSpan = document.createElement('span');
          childSpan.textContent = sub.label;

          childLbl.appendChild(childChk);
          childLbl.appendChild(childSpan);
          childrenWrap.appendChild(childLbl);
          childCheckboxes.push({ chk: childChk, lbl: childLbl });

          childChk.addEventListener('change', () => {
            childLbl.classList.toggle('is-checked', childChk.checked);
            const anyChecked = childCheckboxes.some((c) => c.chk.checked);
            const allChecked = childCheckboxes.every((c) => c.chk.checked);
            parentChk.checked = anyChecked;
            parentChk.indeterminate = anyChecked && !allChecked;
            branch.classList.toggle('is-checked', parentChk.checked);
          });
        });

        branch.appendChild(childrenWrap);

        // Sincronizar estado inicial del padre según sus submódulos
        const anySub = childCheckboxes.some((c) => c.chk.checked);
        const allSub = childCheckboxes.every((c) => c.chk.checked);
        parentChk.checked = anySub;
        parentChk.indeterminate = anySub && !allSub;

        parentChk.addEventListener('change', () => {
          parentChk.indeterminate = false;
          childCheckboxes.forEach(({ chk, lbl }) => {
            if (!chk.disabled) {
              chk.checked = parentChk.checked;
              lbl.classList.toggle('is-checked', chk.checked);
            }
          });
          branch.classList.toggle('is-checked', parentChk.checked);
        });
      } else {
        const leafNote = document.createElement('div');
        leafNote.className = 'admin-orgchart-leaf-note';
        leafNote.textContent = mod.key === 'perfil'
          ? 'Acceso directo obligatorio'
          : 'Módulo de acceso directo';
        branch.appendChild(leafNote);
        parentChk.addEventListener('change', () => {
          branch.classList.toggle('is-checked', parentChk.checked);
        });
      }

      branch.classList.toggle('is-checked', parentChk.checked);
      branchesEl.appendChild(branch);
    });

    gridEl.appendChild(branchesEl);
  }

  document.getElementById('btn-admin-mods-all')?.addEventListener('click', () => {
    const targetUser = document.getElementById('admin-edit-username')?.value || '';
    renderAdminModulesCheckboxes(DEFAULT_MODULE_KEYS, targetUser === PRIMARY_ADMIN_USER);
  });

  document.getElementById('btn-admin-mods-none')?.addEventListener('click', () => {
    const targetUser = document.getElementById('admin-edit-username')?.value || '';
    if (targetUser === PRIMARY_ADMIN_USER) return;
    renderAdminModulesCheckboxes(['perfil'], false);
  });

  document.getElementById('btn-admin-mods-caja')?.addEventListener('click', () => {
    const targetUser = document.getElementById('admin-edit-username')?.value || '';
    if (targetUser === PRIMARY_ADMIN_USER) return;
    const cajaMods = expandUserModulesWithDefaults(['facturacion', 'clientes', 'fidelizacion', 'verificador', 'tema', 'perfil', 'atajos']);
    renderAdminModulesCheckboxes(cajaMods, false);
  });

  function openAdminUserEditor(uKey) {
    const card = document.getElementById('admin-edit-user-card');
    if (!card) return;

    const alertEl = document.getElementById('admin-edit-user-alert');
    if (alertEl) alertEl.hidden = true;

    const isCreatingNew = !uKey;
    const rec = isCreatingNew ? null : ADMIN_DIRECTORY[uKey];
    if (!isCreatingNew && !rec) return;

    const isTargetPrimary = !isCreatingNew && uKey === PRIMARY_ADMIN_USER;
    const hiddenUserEl = document.getElementById('admin-edit-username');
    const userInpEl = document.getElementById('admin-edit-username-input');
    const headingEl = document.getElementById('admin-edit-user-heading');
    const subEl = document.getElementById('admin-edit-user-sub');
    const roleInp = document.getElementById('admin-edit-role');

    if (hiddenUserEl) hiddenUserEl.value = isCreatingNew ? '' : uKey;
    if (userInpEl) {
      userInpEl.value = isCreatingNew ? '' : uKey;
      userInpEl.readOnly = isTargetPrimary;
    }

    const currentActorIsGeneral = isErpGeneralAdminUser(STATE.currentUser);
    if (roleInp) {
      Array.from(roleInp.options || []).forEach((opt) => {
        if (opt.value === 'Administrador') {
          opt.disabled = !currentActorIsGeneral;
          opt.hidden = !currentActorIsGeneral;
        }
      });
    }
    if (isCreatingNew) {
      if (headingEl) headingEl.textContent = currentActorIsGeneral ? '➕ Habilitar Nuevo Administrador o Usuario' : '➕ Habilitar Nuevo Usuario';
      if (subEl) subEl.textContent = currentActorIsGeneral
        ? 'Como Administrador General (@danielg), podés habilitar tanto Administradores como Usuarios.'
        : 'Como Administrador del comercio, podés habilitar cuentas con rol Usuario.';
      document.getElementById('admin-edit-name').value = '';
      if (roleInp) {
        roleInp.value = 'Usuario';
        roleInp.disabled = !currentActorIsGeneral;
      }
      document.getElementById('admin-edit-pass').value = '';
      document.getElementById('admin-edit-whatsapp').value = '';
      document.getElementById('admin-edit-branch').value = ACTIVE_BRAND.defaultBranch || 'Casa Central';
      setAdminEditorAvatarState('', 'U');
      renderAdminModulesCheckboxes(DEFAULT_MODULE_KEYS, false);
    } else {
      if (headingEl) headingEl.textContent = `✏️ Editando a ${rec.name} (@${uKey})`;
      if (subEl) {
        subEl.textContent = isTargetPrimary
          ? 'Administrador Principal del Sistema (acceso total a todos los módulos y submódulos)'
          : 'Definí su Rol (Administrador o Usuario), Contraseña, WhatsApp y tildá/destildá Módulos y Submódulos';
      }
      document.getElementById('admin-edit-name').value = rec.name || '';
      if (roleInp) {
        const targetNorm = normalizeErpUserRole(rec.role, uKey);
        roleInp.value = targetNorm === 'Administrador General' ? 'Administrador' : targetNorm;
        roleInp.disabled = isTargetPrimary || !currentActorIsGeneral;
      }
      document.getElementById('admin-edit-pass').value = rec.pass || '';
      document.getElementById('admin-edit-whatsapp').value = rec.whatsapp || '';
      document.getElementById('admin-edit-branch').value = rec.branch || ACTIVE_BRAND.defaultBranch || 'Casa Central';

      setAdminEditorAvatarState(rec.avatar || '', rec.name);
      renderAdminModulesCheckboxes(rec.modules || DEFAULT_MODULE_KEYS, isTargetPrimary);
    }

    card.hidden = false;
    card.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    if (isCreatingNew && userInpEl) {
      setTimeout(() => userInpEl.focus(), 80);
    }
  }

  document.getElementById('btn-admin-new-user')?.addEventListener('click', () => {
    openAdminUserEditor(null);
  });

  document.getElementById('btn-admin-close-editor')?.addEventListener('click', () => {
    const card = document.getElementById('admin-edit-user-card');
    if (card) card.hidden = true;
  });

  document.getElementById('btn-admin-cancel-user')?.addEventListener('click', () => {
    const card = document.getElementById('admin-edit-user-card');
    if (card) card.hidden = true;
  });

  function renderAdminUsersTable() {
    const tbody = document.getElementById('perfil-admin-users-tbody');
    if (!tbody) return;
    tbody.textContent = '';

    const orderedKeys = [
      PRIMARY_ADMIN_USER, ...Object.keys(ADMIN_DIRECTORY).filter((k) => k !== PRIMARY_ADMIN_USER)
    ];

    orderedKeys.forEach((uKey) => {
      const rec = ADMIN_DIRECTORY[uKey];
      if (!rec) return;

      const tr = document.createElement('tr');

      // 1. Avatar
      const tdAv = document.createElement('td');
      const avSpan = document.createElement('span');
      avSpan.className = 'user-avatar';
      avSpan.style.width = '40px';
      avSpan.style.height = '40px';
      avSpan.style.fontSize = '1rem';
      renderUserAvatarElement(avSpan, rec.name, rec.avatar);
      tdAv.appendChild(avSpan);
      tr.appendChild(tdAv);

      // 2. Usuario y Nombre
      const tdUser = document.createElement('td');
      tdUser.innerHTML = `<div class="price-cell-stack"><strong>${rec.name}</strong><span class="art-code-pill">@${rec.username}</span></div>`;
      tr.appendChild(tdUser);

      // Ocultar a @danielg si quien mira la tabla NO es Administrador General
      const viewerIsGeneral = isErpGeneralAdminUser(STATE.currentUser);
      if (uKey === 'danielg' && !viewerIsGeneral) return;

      // 3. Rol en el Sistema (Administrador General > Administrador > Usuario)
      const tdRole = document.createElement('td');
      const normRole = normalizeErpUserRole(rec.role, uKey);
      const isGenAdmin = normRole === 'Administrador General';
      const isRoleAdmin = normRole === 'Administrador';
      const roleBadgeClass = (isGenAdmin || isRoleAdmin) ? 'badge badge--gold' : 'badge badge--green';
      const roleLabel = isGenAdmin ? '🛡️ Administrador General' : (isRoleAdmin ? '👑 Administrador' : '👤 Usuario');
      const statusPill = rec.active === false ? ' <span class="badge" style="background:#fee2e2;color:#991b1b;">⛔ Deshabilitado</span>' : '';
      tdRole.innerHTML = `<span class="${roleBadgeClass}">${roleLabel}</span>${statusPill}`;
      tr.appendChild(tdRole);

      // 4. WhatsApp + Estado de Caja
      const tdWa = document.createElement('td');
      const cajaLabel = rec.cajaAbierta && CAJAS_CONFIG[rec.cajaAbierta]
        ? `<span class="badge badge--green" style="font-size:0.7rem;">🟢 ${CAJAS_CONFIG[rec.cajaAbierta].nombre} Abierta</span>`
        : `<span class="price-neto-val">Caja cerrada</span>`;
      if (rec.whatsapp) {
        tdWa.innerHTML = `<div class="price-cell-stack"><strong>📲 ${rec.whatsapp}</strong>${cajaLabel}</div>`;
      } else {
        tdWa.innerHTML = `<div class="price-cell-stack"><span class="price-neto-val">Sin WhatsApp cargado</span>${cajaLabel}</div>`;
      }
      tr.appendChild(tdWa);

      // 5. Módulos que puede visualizar (sin detallar listado)
      const tdMods = document.createElement('td');
      const userMods = uKey === PRIMARY_ADMIN_USER
        ? DEFAULT_MODULE_KEYS
        : expandUserModulesWithDefaults(rec.modules);
      if (userMods.length >= DEFAULT_MODULE_KEYS.length) {
        tdMods.innerHTML = `<span class="badge badge--gold">✓ Todos habilitados</span>`;
      } else {
        tdMods.innerHTML = `<span class="badge badge--green">⚙️ Personalizado</span>`;
      }
      tr.appendChild(tdMods);

      // 6. Acciones
      const tdAct = document.createElement('td');
      const btnEdit = document.createElement('button');
      btnEdit.type = 'button';
      btnEdit.className = 'btn-edit-row';
      btnEdit.textContent = '✏️ Editar';
      btnEdit.addEventListener('click', () => {
        openAdminUserEditor(uKey);
      });
      tdAct.appendChild(btnEdit);
      tr.appendChild(tdAct);

      tbody.appendChild(tr);
    });
  }

  document.getElementById('admin-edit-user-form')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const alertEl = document.getElementById('admin-edit-user-alert');
    const globalOk = document.getElementById('admin-users-global-success');
    if (alertEl) alertEl.hidden = true;
    if (globalOk) globalOk.hidden = true;

    const existingUsername = (document.getElementById('admin-edit-username')?.value || '').trim().toLowerCase();
    const typedUsername = (document.getElementById('admin-edit-username-input')?.value || '')
      .trim()
      .toLowerCase()
      .replace(/^@+/, '')
      .replace(/[^a-z0-9._-]/g, '');
    const isCreatingNew = !existingUsername;
    const isPrimaryTarget = existingUsername === PRIMARY_ADMIN_USER;
    const targetUsername = isPrimaryTarget ? PRIMARY_ADMIN_USER : (typedUsername || existingUsername);

    if (!targetUsername || targetUsername.length < 3) {
      if (alertEl) {
        alertEl.textContent = 'Ingresá un nombre de usuario (@login) válido de al menos 3 caracteres.';
        alertEl.hidden = false;
      }
      return;
    }

    const name = document.getElementById('admin-edit-name')?.value.trim() || '';
    const role = normalizeErpUserRole(document.getElementById('admin-edit-role')?.value, targetUsername);
    const pass = document.getElementById('admin-edit-pass')?.value.trim() || '';
    const whatsapp = document.getElementById('admin-edit-whatsapp')?.value.trim() || '';
    const vendedor = name.toUpperCase();
    const branch = document.getElementById('admin-edit-branch')?.value.trim() || ACTIVE_BRAND.defaultBranch || 'Casa Central';
    const avatar = document.getElementById('admin-edit-avatar-value')?.value || '';

    if (!name || pass.length < 4) {
      if (alertEl) {
        alertEl.textContent = 'Completá el Nombre y Apellido y una Contraseña de al menos 4 caracteres.';
        alertEl.hidden = false;
      }
      return;
    }

    const checkedModules = Array.from(
      document.querySelectorAll('#admin-edit-modules-grid input[name="admin_user_module"]:checked')
    ).map((chk) => chk.value);
    if (!checkedModules.includes('perfil')) checkedModules.push('perfil');
    ALL_SYSTEM_MODULES.forEach((mod) => {
      if (Array.isArray(mod.submodules) && mod.submodules.some((s) => checkedModules.includes(s.key))) {
        if (!checkedModules.includes(mod.key)) checkedModules.push(mod.key);
      }
    });
    const finalModules = targetUsername === PRIMARY_ADMIN_USER ? [...DEFAULT_MODULE_KEYS] : checkedModules;

    const saveBtn = document.getElementById('btn-admin-save-user');
    if (saveBtn) saveBtn.disabled = true;

    try {
      await fetch('api/auth.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'admin_save_user',
          previousUsername: existingUsername,
          targetUsername,
          name,
          role,
          pass,
          whatsapp,
          vendedor,
          branch,
          avatar,
          modules: finalModules
        })
      });
    } catch {}

    if (existingUsername && existingUsername !== targetUsername) {
      removeOrRenameCustomUserKey(existingUsername, targetUsername);
    }

    const newHash = await sha256Hex(`cn-erp-2026:${targetUsername}:${pass}`);
    saveCustomUserOverride(targetUsername, {
      username: targetUsername,
      name,
      role,
      pass,
      hash: newHash,
      whatsapp,
      vendedor,
      branch,
      avatar,
      modules: finalModules
    });

    if (STATE.currentUser && String(STATE.currentUser.username).toLowerCase() === targetUsername) {
      STATE.currentUser = Object.assign({}, STATE.currentUser, {
        name,
        role,
        whatsapp,
        vendedor,
        branch,
        avatar,
        modules: finalModules
      });
      sessionStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(STATE.currentUser));
      updateTopbarUserDisplay(STATE.currentUser);
      applyUserAllowedModules(STATE.currentUser);
    }

    if (saveBtn) saveBtn.disabled = false;
    const card = document.getElementById('admin-edit-user-card');
    if (card) card.hidden = true;

    renderPerfilUsuarioSection();

    if (globalOk) {
      const actionLbl = isCreatingNew ? 'creado' : 'actualizado';
      globalOk.innerHTML = `<strong>✓ Usuario @${targetUsername} (${name}) ${actionLbl} correctamente.</strong> Rol: <strong>${role}</strong> · WhatsApp: <strong>${whatsapp || 'S/D'}</strong>.`;
      globalOk.hidden = false;
    }
  });

  // =========================================================================
  // NOTIFICACIONES DE VENTAS WEB AL WHATSAPP DEL USUARIO CON CAJA ABIERTA
  // =========================================================================
  let openCajaWebWatcherTimer = null;
  let lastSeenWebOrderId = null;
  let activePendingDispatchOrder = null;

  function buildWhatsappDispatchUrlForOrder(order, userProfile) {
    const rawWa = String(userProfile?.whatsapp || '').replace(/\D/g, '');
    if (!rawWa) return null;
    const intlPhone = rawWa.startsWith('54') ? rawWa : `549${rawWa.replace(/^0+/, '')}`;
    const cajaCfg = CAJAS_CONFIG[STATE.activeCajaId || 'caja1'];
    const itemsLines = Array.isArray(order.items)
      ? order.items.map((it) => `• ${it.qty}x ${it.no} (#${it.co}) — $ ${formatArs(it.sub)}`)
      : [];
    const text = [
      `📦 *AVISO DE VENTA WEB #${order.id} — DESPACHAR DESDE ${(cajaCfg?.nombre || 'CAJA').toUpperCase()}*`,
      `👤 *Cajero con Caja Abierta:* ${userProfile.name} (@${userProfile.username})`,
      `🧑 *Cliente Web:* ${order.clNo || 'CLIENTE WEB'} (${order.lp || 'MINORISTA'})`,
      `🕒 *Fecha/Hora:* ${order.fechaHora || todayFormatted()}`,
      `🛒 *Artículos para preparar y despachar:*`,
      ...itemsLines,
      `💰 *Total del Pedido:* *$ ${formatArs(order.total || 0)}*`,
      order.ob ? `📝 *Observaciones:* ${order.ob}` : ''
    ]
      .filter(Boolean)
      .join('\n');
    return `https://wa.me/${intlPhone}?text=${encodeURIComponent(text)}`;
  }

  function showPosWebDispatchBanner(order) {
    const banner = document.getElementById('pos-web-order-dispatch-banner');
    const titleEl = document.getElementById('pos-web-dispatch-title');
    const detailEl = document.getElementById('pos-web-dispatch-detail');
    if (!banner || !order) return;

    activePendingDispatchOrder = order;
    const profile = getActiveUserProfile();
    const waText = profile?.whatsapp ? ` · Enviado a tu WhatsApp (${profile.whatsapp})` : '';
    const itemCount = Array.isArray(order.items) ? order.items.reduce((acc, i) => acc + (Number(i.qty) || 1), 0) : 0;

    if (titleEl) {
      titleEl.textContent = `📦 ¡Nueva Venta Web #${order.id} para Despachar! (${order.clNo || 'CLIENTE WEB'})${waText}`;
    }
    if (detailEl) {
      detailEl.textContent = `${itemCount} unidad(es) · Total: $ ${formatArs(order.total || 0)} · Lista: ${order.lp || 'MINORISTA'}. Prepará el pedido desde tu Caja abierta.`;
    }
    banner.hidden = false;
  }

  document.getElementById('btn-pos-web-open-wa')?.addEventListener('click', () => {
    const profile = getActiveUserProfile();
    if (!profile) return;
    if (!profile.whatsapp) {
      switchSection('sec-perfil-usuario');
      document.getElementById('perfil-whatsapp')?.focus();
      return;
    }
    const order = activePendingDispatchOrder || {
      id: (STATE.pedidosWeb?.length || 1),
      clNo: 'CLIENTE CARRITO WEB',
      lp: 'MINORISTA',
      fechaHora: todayFormatted(),
      total: 15400,
      items: [{ qty: 2, co: '00001', no: 'PRODUCTO PEDIDO WEB', sub: 15400 }]
    };
    const waUrl = buildWhatsappDispatchUrlForOrder(order, profile);
    if (waUrl) {
      window.open(waUrl, '_blank', 'noopener,noreferrer');
    }
  });

  document.getElementById('btn-pos-web-mark-dispatched')?.addEventListener('click', async () => {
    const banner = document.getElementById('pos-web-order-dispatch-banner');
    if (banner) banner.hidden = true;
    if (activePendingDispatchOrder?.id) {
      try {
        await fetch('api/clientes.php', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'mark_web_order_dispatched',
            orderId: activePendingDispatchOrder.id,
            username: STATE.currentUser?.username || ''
          })
        });
      } catch {}
    }
    activePendingDispatchOrder = null;
  });

  document.getElementById('btn-perfil-test-wa-dispatch')?.addEventListener('click', () => {
    const alertEl = document.getElementById('perfil-datos-alert');
    if (alertEl) alertEl.hidden = true;
    const rawWa = (document.getElementById('perfil-whatsapp')?.value || '').trim();
    if (!rawWa) {
      if (alertEl) {
        alertEl.textContent = 'Ingresá primero tu número de WhatsApp para probar el aviso de despacho de Venta Web.';
        alertEl.hidden = false;
      }
      document.getElementById('perfil-whatsapp')?.focus();
      return;
    }
    const profile = Object.assign({}, getActiveUserProfile() || {}, { whatsapp: rawWa });
    const sampleOrder = {
      id: (STATE.pedidosWeb?.length || 0) + 1,
      clNo: 'CLIENTE DEMO CARRITO WEB',
      lp: 'MINORISTA',
      fechaHora: `${todayFormatted()} ${new Date().toTimeString().slice(0, 5)}`,
      total: 18500,
      items: [
        { qty: 2, co: '00105', no: 'ARTÍCULO DE PRUEBA VENTA WEB', sub: 18500 }
      ],
      ob: 'PRUEBA DE NOTIFICACIÓN CON CAJA ABIERTA PARA DESPACHO'
    };
    const waUrl = buildWhatsappDispatchUrlForOrder(sampleOrder, profile);
    if (waUrl) {
      window.open(waUrl, '_blank', 'noopener,noreferrer');
    }
  });

  function startOpenCajaWebOrderWatcher() {
    if (openCajaWebWatcherTimer) clearInterval(openCajaWebWatcherTimer);
    openCajaWebWatcherTimer = setInterval(async () => {
      const posOpen = !document.getElementById('sec-caja-pos')?.hidden || !document.getElementById('sec-club-previo')?.hidden;
      if (!posOpen || !STATE.currentUser) return;
      try {
        const res = await fetch(`api/clientes.php?action=all&t=${Date.now()}`, { cache: 'no-store' });
        if (!res.ok) return;
        const data = await res.json();
        const orders = Array.isArray(data?.pedidosWeb) ? data.pedidosWeb : [];
        if (orders.length === 0) return;
        const latest = orders[orders.length - 1];
        const latestId = Number(latest.id) || orders.length;
        if (lastSeenWebOrderId === null) {
          lastSeenWebOrderId = latestId;
          if (latest.estadoDespacho !== 'DESPACHADO') {
            showPosWebDispatchBanner(latest);
          }
          return;
        }
        if (latestId > lastSeenWebOrderId) {
          lastSeenWebOrderId = latestId;
          STATE.pedidosWeb = orders;
          showPosWebDispatchBanner(latest);
          const profile = getActiveUserProfile();
          if (profile?.whatsapp) {
            const waUrl = buildWhatsappDispatchUrlForOrder(latest, profile);
            if (waUrl) {
              try {
                window.open(waUrl, '_blank', 'noopener,noreferrer');
              } catch {}
            }
          }
        }
      } catch {}
    }, 10000);
  }

