  function normalizeAtajoKey(raw) {
    const val = String(raw || '').trim().toUpperCase();
    if (/^(?:[A-Z0-9]|F(?:[1-9]|1[0-2]))$/.test(val)) return val;
    return '';
  }

  function getActiveAtajoKeyForAction(accionCode) {
    if (!accionCode || !Array.isArray(STATE.atajos)) return null;
    // Priorizar atajos personalizados o el último configurado para esa acción
    const matches = STATE.atajos.filter((a) => a && a.activo !== false && a.accion === accionCode && normalizeAtajoKey(a.tecla));
    if (matches.length === 0) return null;
    const customMatch = matches.find((a) => a.esPersonalizado);
    return normalizeAtajoKey((customMatch || matches[0]).tecla);
  }

  function syncAtajosUIInModules() {
    if (!Array.isArray(STATE.atajos)) return;

    // 1. Buscador Inteligente (Omnibox) en Topbar
    const omniboxKey = getActiveAtajoKeyForAction('act:omnibox');
    const omniboxKbd = document.querySelector('.omnibox-kbd');
    if (omniboxKbd) {
      if (omniboxKey) {
        omniboxKbd.textContent = `CTRL + ${omniboxKey}`;
        omniboxKbd.hidden = false;
      } else {
        omniboxKbd.hidden = true;
      }
    }
    const omniboxInp = document.getElementById('global-func-search');
    if (omniboxInp) {
      omniboxInp.title = omniboxKey
        ? `Buscador Inteligente de Funciones (CTRL + ${omniboxKey})`
        : 'Buscador Inteligente de Funciones';
    }

    // 2. Club Fidel: Botón Continuar sin Club Fidel
    const clubSkipKey = getActiveAtajoKeyForAction('pos:continuar-sin-club');
    const clubSkipBtn = document.getElementById('btn-club-continue-without');
    if (clubSkipBtn) {
      const kbd = clubSkipBtn.querySelector('.club-skip-kbd');
      if (kbd) {
        if (clubSkipKey) {
          kbd.textContent = `CTRL + ${clubSkipKey}`;
          kbd.hidden = false;
        } else {
          kbd.hidden = true;
        }
      }
      clubSkipBtn.title = clubSkipKey
        ? `Atajo de teclado: CTRL + ${clubSkipKey}`
        : 'Continuar sin Club Fidel';
    }

    // 3. Caja POS / Facturación: Botón Aceptar, Cancelar, Punto de Venta, Forma de Pago, 1° Línea Código
    const posEmitirKey = getActiveAtajoKeyForAction('pos:emitir');
    const btnPosReg = document.getElementById('btn-pos-registrar');
    if (btnPosReg) {
      btnPosReg.textContent = posEmitirKey
        ? `✅ Aceptar (CTRL + ${posEmitirKey})`
        : '✅ Aceptar';
      btnPosReg.title = posEmitirKey
        ? `Emitir / Aceptar comprobante (CTRL + ${posEmitirKey})`
        : 'Emitir / Aceptar comprobante';
    }

    const posCancelKey = getActiveAtajoKeyForAction('pos:cancelar');
    const btnPosCancel = document.getElementById('btn-fact-cancelar');
    if (btnPosCancel) {
      btnPosCancel.textContent = posCancelKey
        ? `❌ Cancelar (Esc / CTRL + ${posCancelKey})`
        : '❌ Cancelar (Esc)';
    }

    const posTogglePvKey = getActiveAtajoKeyForAction('pos:toggle-interno');
    const factCorrWrap = document.getElementById('fact-correlativo-wrap');
    if (factCorrWrap) {
      factCorrWrap.title = posTogglePvKey
        ? `CTRL + ${posTogglePvKey} (o clic aquí) para alternar Punto de Venta ARCA / Comprobante Interno`
        : 'Clic aquí para alternar Punto de Venta ARCA / Comprobante Interno';
    }

    syncFactFormaPagoControl(null, false);
    const factListaPrecioSel = document.getElementById('fact-lista-precio');
    if (factListaPrecioSel) {
      factListaPrecioSel.disabled = true;
      factListaPrecioSel.title = 'Definido por la configuración del cliente seleccionado (no modificable desde Caja)';
    }

    const posFocusCodeKey = getActiveAtajoKeyForAction('pos:focus-code');
    const firstCodeInp = document.getElementById('fact-first-code-input');
    if (firstCodeInp) {
      firstCodeInp.title = posFocusCodeKey
        ? `Ir a 1° línea de Código / Lector (CTRL + ${posFocusCodeKey})`
        : '1° línea de Código / Lector';
    }

    const posCambiarClubKey = getActiveAtajoKeyForAction('pos:cambiar-club');
    const btnCambiarClub = document.getElementById('btn-pos-cambiar-club');
    if (btnCambiarClub) {
      btnCambiarClub.title = posCambiarClubKey
        ? `Abrir ¿Tenés Club Fidel? (CTRL + ${posCambiarClubKey})`
        : 'Abrir ¿Tenés Club Fidel?';
    }

    // 4. Botones de acción en Artículos, Clientes y Proveedores
    const newArtKey = getActiveAtajoKeyForAction('modal:nuevo-articulo');
    const btnNewArt = document.getElementById('btn-new-article');
    if (btnNewArt) {
      btnNewArt.textContent = newArtKey
        ? `+ Nuevo Artículo (CTRL + ${newArtKey})`
        : '+ Nuevo Artículo';
      btnNewArt.title = newArtKey ? `Atajo: CTRL + ${newArtKey}` : '';
    }

    const dupArtKey = getActiveAtajoKeyForAction('modal:duplicar-articulo');
    const btnDupArt = document.getElementById('btn-open-duplicate-search');
    if (btnDupArt) {
      btnDupArt.textContent = dupArtKey
        ? `📋 Duplicar Artículo (CTRL + ${dupArtKey})`
        : '📋 Duplicar Artículo';
      btnDupArt.title = dupArtKey ? `Atajo: CTRL + ${dupArtKey}` : '';
    }

    const newCliKey = getActiveAtajoKeyForAction('modal:nuevo-cliente');
    ['btn-new-client', 'btn-new-client-from-ctacte'].forEach((id) => {
      const btn = document.getElementById(id);
      if (btn) {
        btn.textContent = newCliKey
          ? `+ Nuevo Cliente (CTRL + ${newCliKey})`
          : '+ Nuevo Cliente';
        btn.title = newCliKey ? `Atajo: CTRL + ${newCliKey}` : '';
      }
    });

    const newProvKey = getActiveAtajoKeyForAction('modal:nuevo-proveedor');
    const btnNewProv = document.getElementById('btn-new-proveedor');
    if (btnNewProv) {
      btnNewProv.textContent = newProvKey
        ? `+ Nuevo Proveedor (CTRL + ${newProvKey})`
        : '+ Nuevo Proveedor';
      btnNewProv.title = newProvKey ? `Atajo: CTRL + ${newProvKey}` : '';
    }

    // 5. Tarjetas de Módulos y Submódulos (.module-card) en toda la aplicación
    const cardActionResolver = (card) => {
      const openSec = card.getAttribute('data-open-section');
      if (openSec) return `nav:${openSec}`;
      const openCaja = card.getAttribute('data-open-caja');
      if (openCaja) return `caja:${openCaja}`;
      if (card.id === 'module-card-theme-toggle') return 'act:toggle-theme';
      if (card.id === 'card-new-article') return 'modal:nuevo-articulo';
      if (card.id === 'card-duplicate-article') return 'modal:duplicar-articulo';
      if (card.id === 'card-new-client') return 'modal:nuevo-cliente';
      if (card.id === 'card-new-proveedor') return 'modal:nuevo-proveedor';
      if (card.id === 'card-online-client-reg' || card.id === 'card-carrito-online-reg') return 'modal:registro-web';
      return null;
    };

    document.querySelectorAll('.module-card').forEach((card) => {
      const accionCode = cardActionResolver(card);
      const key = accionCode ? getActiveAtajoKeyForAction(accionCode) : null;
      let badge = card.querySelector('.module-card-kbd');
      if (key) {
        const isCajaCard = card.hasAttribute('data-open-caja');
        const targetParent = (isCajaCard && card.querySelector('h3')) || card;
        if (!badge) {
          badge = document.createElement('kbd');
          badge.className = 'module-card-kbd';
          badge.setAttribute('aria-hidden', 'true');
          targetParent.appendChild(badge);
        } else if (badge.parentElement !== targetParent) {
          targetParent.appendChild(badge);
        }
        badge.textContent = `CTRL + ${key}`;
        card.title = `Atajo rápido: CTRL + ${key}`;
      } else {
        if (badge) badge.remove();
        if (card.title && card.title.startsWith('Atajo rápido:')) {
          card.removeAttribute('title');
        }
      }
    });
  }

  function loadAtajosStore() {
    try {
      const raw = localStorage.getItem(ATAJOS_STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed) && parsed.length > 0) {
          STATE.atajos = parsed
            .map((a, idx) => ({
              id: Number(a.id) || idx + 1,
              tecla: normalizeAtajoKey(a.tecla),
              accion: String(a.accion || 'nav:sec-inicio'),
              nombre: String(a.nombre || '')
                .trim()
                .toUpperCase()
                .replace(/CLUB CACHITA/g, 'CLUB FIDEL')
                .replace(/CLUB PASEO ALBERDI/g, 'CLUB FIDEL'),
              modulo: String(a.modulo || 'NAVEGACIÓN Y SISTEMA')
                .trim()
                .toUpperCase()
                .replace(/CLUB CACHITA/g, 'CLUB FIDEL')
                .replace(/CLUB PASEO ALBERDI/g, 'CLUB FIDEL'),
              activo: a.activo !== false,
              esPersonalizado: Boolean(a.esPersonalizado)
            }))
            .filter((a) => Boolean(a.tecla));
          if (STATE.atajos.length > 0) {
            let changed = false;
            if (!STATE.atajos.some((a) => a.accion === 'pos:continuar-sin-club')) {
              const nextId = STATE.atajos.reduce((mx, a) => Math.max(mx, Number(a.id) || 0), 0) + 1;
              if (!STATE.atajos.some((a) => a.tecla === 'C')) {
                STATE.atajos.push({
                  id: nextId,
                  tecla: 'C',
                  accion: 'pos:continuar-sin-club',
                  nombre: 'CONTINUAR SIN CLUB FIDEL (VENTA DIRECTA EN CAJA)',
                  modulo: 'FACTURACIÓN Y CAJAS',
                  activo: true,
                  esPersonalizado: false
                });
                changed = true;
              }
            }
            if (!STATE.atajos.some((a) => a.accion === 'pos:toggle-forma-pago') && !STATE.atajos.some((a) => a.tecla === 'F11')) {
              const nextId = STATE.atajos.reduce((mx, a) => Math.max(mx, Number(a.id) || 0), 0) + 1;
              STATE.atajos.push({
                id: nextId,
                tecla: 'F11',
                accion: 'pos:toggle-forma-pago',
                nombre: 'ALTERNAR FORMA DE PAGO (CONTADO / CUENTA CORRIENTE) EN CAJA POS',
                modulo: 'FACTURACIÓN Y CAJAS',
                activo: true,
                esPersonalizado: false
              });
              changed = true;
            }
            const legacyInterno = STATE.atajos.find(
              (a) => a.accion === 'pos:toggle-interno' && a.tecla === 'I' && !a.esPersonalizado
            );
            if (legacyInterno && !STATE.atajos.some((a) => a.tecla === 'F12')) {
              legacyInterno.tecla = 'F12';
              changed = true;
            } else if (!STATE.atajos.some((a) => a.accion === 'pos:toggle-interno') && !STATE.atajos.some((a) => a.tecla === 'F12')) {
              const nextId = STATE.atajos.reduce((mx, a) => Math.max(mx, Number(a.id) || 0), 0) + 1;
              STATE.atajos.push({
                id: nextId,
                tecla: 'F12',
                accion: 'pos:toggle-interno',
                nombre: 'ALTERNAR COMPROBANTE INTERNO / FACTURA ELECTRÓNICA EN CAJA POS',
                modulo: 'FACTURACIÓN Y CAJAS',
                activo: true,
                esPersonalizado: false
              });
              changed = true;
            }
            if (!STATE.atajos.some((a) => a.accion === 'nav:sec-manual-usuario') && !STATE.atajos.some((a) => a.tecla === 'H')) {
              const nextId = STATE.atajos.reduce((mx, a) => Math.max(mx, Number(a.id) || 0), 0) + 1;
              STATE.atajos.push({
                id: nextId,
                tecla: 'H',
                accion: 'nav:sec-manual-usuario',
                nombre: 'ABRIR MANUAL DEL USUARIO INTELIGENTE (PROCESOS, IA Y PDF)',
                modulo: 'NAVEGACIÓN Y SISTEMA',
                activo: true,
                esPersonalizado: false
              });
              changed = true;
            }
            if (changed) saveAtajosStore({ syncServer: false });
            syncAtajosUIInModules();
            return;
          }
        }
      }
    } catch {}
    STATE.atajos = getDefaultAtajosList();
    syncAtajosUIInModules();
  }

  function normalizeAtajosArray(rawList) {
    if (!Array.isArray(rawList)) return [];
    const cleaned = rawList
      .map((a, idx) => ({
        id: Number(a.id) || idx + 1,
        tecla: normalizeAtajoKey(a.tecla),
        accion: String(a.accion || 'nav:sec-inicio'),
        nombre: String(a.nombre || '')
          .trim()
          .toUpperCase()
          .replace(/CLUB CACHITA/g, 'CLUB FIDEL')
          .replace(/CLUB PASEO ALBERDI/g, 'CLUB FIDEL'),
        modulo: String(a.modulo || 'NAVEGACIÓN Y SISTEMA')
          .trim()
          .toUpperCase()
          .replace(/CLUB CACHITA/g, 'CLUB FIDEL')
          .replace(/CLUB PASEO ALBERDI/g, 'CLUB FIDEL'),
        activo: a.activo !== false,
        esPersonalizado: Boolean(a.esPersonalizado)
      }))
      .filter((a) => Boolean(a.tecla));
    if (cleaned.length > 0 && !cleaned.some((a) => a.accion === 'nav:sec-manual-usuario') && !cleaned.some((a) => a.tecla === 'H')) {
      const nextId = cleaned.reduce((mx, a) => Math.max(mx, Number(a.id) || 0), 0) + 1;
      cleaned.push({
        id: nextId,
        tecla: 'H',
        accion: 'nav:sec-manual-usuario',
        nombre: 'ABRIR MANUAL DEL USUARIO INTELIGENTE (PROCESOS, IA Y PDF)',
        modulo: 'NAVEGACIÓN Y SISTEMA',
        activo: true,
        esPersonalizado: false
      });
    }
    return cleaned;
  }

  function hasCustomOrModifiedAtajos(list) {
    if (!Array.isArray(list) || list.length === 0) return false;
    if (list.some((a) => a && a.esPersonalizado)) return true;
    const defaults = getDefaultAtajosList();
    if (list.length !== defaults.length) return true;
    const defMap = new Map(defaults.map((d) => [d.accion, normalizeAtajoKey(d.tecla)]));
    return list.some((a) => defMap.get(a.accion) !== normalizeAtajoKey(a.tecla));
  }

  function mergeFedericodCustomAtajos(baseList, localList) {
    const merged = normalizeAtajosArray(baseList.length > 0 ? baseList : getDefaultAtajosList());
    const defaults = getDefaultAtajosList();
    const defMap = new Map(defaults.map((d) => [d.accion, normalizeAtajoKey(d.tecla)]));

    normalizeAtajosArray(localList).forEach((loc) => {
      const isCustomLoc = Boolean(loc.esPersonalizado) || defMap.get(loc.accion) !== loc.tecla;
      if (!isCustomLoc) return;
      // Liberar tecla si estaba ocupada por otro atajo distinto
      for (let i = merged.length - 1; i >= 0; i--) {
        if (merged[i].tecla === loc.tecla && merged[i].accion !== loc.accion) {
          merged.splice(i, 1);
        }
      }
      const existingByAction = merged.find((m) => m.accion === loc.accion);
      if (existingByAction) {
        existingByAction.tecla = loc.tecla;
        existingByAction.nombre = loc.nombre || existingByAction.nombre;
        existingByAction.modulo = loc.modulo || existingByAction.modulo;
        existingByAction.activo = loc.activo !== false;
        existingByAction.esPersonalizado = true;
      } else {
        const nextId = merged.reduce((mx, item) => Math.max(mx, Number(item.id) || 0), 0) + 1;
        merged.push({
          ...loc,
          id: nextId,
          esPersonalizado: true
        });
      }
    });
    return merged;
  }

  function saveAtajosStore(opts = {}) {
    const syncServer = opts.syncServer !== false;
    const isAutoSync = Boolean(opts.isAutoSync);
    try {
      localStorage.setItem(ATAJOS_STORAGE_KEY, JSON.stringify(STATE.atajos || []));
    } catch {}
    syncAtajosUIInModules();

    if (syncServer && Array.isArray(STATE.atajos) && STATE.atajos.length > 0) {
      const currentUsername = String(STATE.currentUser?.username || '').trim().toLowerCase();
      fetch('api/auth.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'save_global_atajos',
          username: currentUsername || 'federicod',
          isAutoSync,
          hasCustom: hasCustomOrModifiedAtajos(STATE.atajos),
          atajos: STATE.atajos
        })
      }).catch(() => {});
    }
  }

  async function syncGlobalAtajosFromServer() {
    try {
      const res = await fetch(`api/auth.php?action=get_global_atajos&t=${Date.now()}`, { cache: 'no-store' });
      if (!res.ok) return;
      const data = await res.json();
      if (!data || !data.ok) return;

      const serverAtajos = normalizeAtajosArray(data.atajos || []);
      const seededFromFedericod = Boolean(data.seededFromFedericod);
      const currentUsername = String(STATE.currentUser?.username || '').trim().toLowerCase();
      const localHasCustom = hasCustomOrModifiedAtajos(STATE.atajos);

      // Si este navegador pertenece a federicod (o tiene atajos personalizados locales) y el servidor aún no los unificó, subirlos y unificarlos para todas las Cajas
      if ((currentUsername === 'federicod' || localHasCustom) && (serverAtajos.length === 0 || (!seededFromFedericod && localHasCustom))) {
        STATE.atajos = mergeFedericodCustomAtajos(serverAtajos, STATE.atajos);
        saveAtajosStore({ syncServer: true, isAutoSync: false });
        if (!document.getElementById('sec-atajos')?.hidden && typeof renderAtajosSection === 'function') {
          renderAtajosSection();
        }
        return;
      }

      if (serverAtajos.length > 0) {
        const prevJson = JSON.stringify(STATE.atajos || []);
        const nextJson = JSON.stringify(serverAtajos);
        if (prevJson !== nextJson) {
          STATE.atajos = serverAtajos;
          saveAtajosStore({ syncServer: false });
          if (!document.getElementById('sec-atajos')?.hidden && typeof renderAtajosSection === 'function') {
            renderAtajosSection();
          }
        }
      } else if (Array.isArray(STATE.atajos) && STATE.atajos.length > 0) {
        saveAtajosStore({ syncServer: true, isAutoSync: true });
      }
    } catch {}
  }

  loadAtajosStore();
  syncGlobalAtajosFromServer();
  setInterval(syncGlobalAtajosFromServer, 20000);
  STATE.editingAtajoId = null;

  function executeAtajoAction(accionCode, shortcutObj = null) {
    if (!accionCode) return;

    if (shortcutObj) {
      const lastEl = document.getElementById('kpi-atajos-last');
      const lastSub = document.getElementById('kpi-atajos-last-sub');
      if (lastEl) lastEl.textContent = `CTRL + ${shortcutObj.tecla}`;
      if (lastSub) lastSub.textContent = shortcutObj.nombre;
    }

    if (accionCode.startsWith('nav:')) {
      const targetSec = accionCode.slice(4);
      switchSection(targetSec);
      if (targetSec === 'sec-articulos') {
        setTimeout(() => document.getElementById('filter-q')?.focus(), 60);
      } else if (targetSec === 'sec-clientes') {
        setTimeout(() => document.getElementById('cli-filter-q')?.focus(), 60);
      } else if (targetSec === 'sec-proveedores') {
        setTimeout(() => document.getElementById('prov-filter-q')?.focus(), 60);
      }
      return;
    }

    if (accionCode.startsWith('caja:')) {
      const cajaId = accionCode.slice(5);
      openCajaSubmenu(cajaId);
      return;
    }

    if (accionCode === 'act:omnibox') {
      const inp = document.getElementById('global-func-search');
      if (inp) {
        inp.focus();
        inp.select();
      }
      return;
    }

    if (accionCode === 'act:toggle-theme') {
      toggleThemeMode();
      return;
    }

    if (accionCode === 'modal:nuevo-articulo') {
      switchSection('sec-articulos');
      openArticleModal(null);
      return;
    }

    if (accionCode === 'modal:duplicar-articulo') {
      switchSection('sec-articulos');
      openDuplicateSearchDialog();
      return;
    }

    if (accionCode === 'modal:nuevo-cliente') {
      switchSection('sec-clientes');
      openClientModal(null);
      return;
    }

    if (accionCode === 'modal:nuevo-proveedor') {
      switchSection('sec-proveedores');
      openProveedorModal(null);
      return;
    }

    if (accionCode === 'modal:registro-web') {
      openOnlineRegModal();
      return;
    }

    if (accionCode === 'pos:emitir') {
      if (document.getElementById('pos-payment-dialog')?.open) {
        document.getElementById('pos-payment-form')?.requestSubmit();
        return;
      }
      if (document.getElementById('pos-ticket-dialog')?.open) {
        closePosTicketAndContinue();
        return;
      }
      const posSec = document.getElementById('sec-caja-pos');
      if (posSec && !posSec.hidden) {
        document.getElementById('facturacion-form')?.requestSubmit();
      } else {
        openCajaPos(STATE.activeCajaId || 'caja1');
      }
      return;
    }

    if (accionCode === 'pos:focus-code') {
      const posSec = document.getElementById('sec-caja-pos');
      if (posSec && !posSec.hidden) {
        focusFirstCodeInput();
      } else {
        openCajaPos(STATE.activeCajaId || 'caja1');
      }
      return;
    }

    if (accionCode === 'pos:toggle-interno') {
      const posSec = document.getElementById('sec-caja-pos');
      if (!posSec || posSec.hidden) {
        openCajaPos(STATE.activeCajaId || 'caja1');
        return;
      }
      toggleFactPuntoVentaCaja();
      return;
    }

    if (accionCode === 'pos:toggle-forma-pago') {
      const posSec = document.getElementById('sec-caja-pos');
      if (!posSec || posSec.hidden) {
        openCajaPos(STATE.activeCajaId || 'caja1');
      }
      toggleFactFormaPago();
      return;
    }

    if (accionCode === 'pos:continuar-sin-club') {
      proceedFromClubToCajaPos(null);
      return;
    }

    if (accionCode === 'pos:cambiar-club') {
      openClubPrevioScreen(STATE.activeCajaId || 'caja1');
      return;
    }

    if (accionCode === 'pos:cancelar') {
      const posSec = document.getElementById('sec-caja-pos');
      if (posSec && !posSec.hidden) {
        resetInvoiceToDefaults();
      }
    }
  }

  function highlightActiveFnChip(teclaVal) {
    const clean = normalizeAtajoKey(teclaVal);
    document.querySelectorAll('.shortcut-fn-chip').forEach((chip) => {
      chip.classList.toggle('is-active', chip.getAttribute('data-fn-key') === clean);
    });
  }

  function syncAtajoFormFieldsFromAction() {
    const sel = document.getElementById('atajo-accion');
    const nomInp = document.getElementById('atajo-nombre');
    const modInp = document.getElementById('atajo-modulo');
    const tInp = document.getElementById('atajo-tecla');
    if (!sel) return;
    const meta = ATAJOS_ACTION_META[sel.value];
    if (meta && !STATE.editingAtajoId) {
      if (nomInp) nomInp.value = meta.nombre;
      if (modInp) modInp.value = meta.modulo;
      const existing = (STATE.atajos || []).find((a) => a.accion === sel.value);
      if (existing && tInp && !tInp.value) {
        tInp.value = existing.tecla;
        highlightActiveFnChip(existing.tecla);
      }
    }
  }

  function resetAtajoForm() {
    STATE.editingAtajoId = null;
    const form = document.getElementById('atajo-form');
    if (form) form.reset();
    const tInp = document.getElementById('atajo-tecla');
    if (tInp) tInp.value = '';
    highlightActiveFnChip('');
    const leg = document.getElementById('atajo-form-legend');
    if (leg) leg.textContent = '➕ Crear / Configurar Atajo (CTRL + Tecla / F1–F12)';
    const saveBtn = document.getElementById('btn-atajo-save');
    if (saveBtn) saveBtn.textContent = '💾 Guardar Atajo (CTRL + Tecla)';
    const cancelBtn = document.getElementById('btn-atajo-cancel');
    if (cancelBtn) cancelBtn.hidden = true;
    const alertEl = document.getElementById('atajo-form-alert');
    if (alertEl) alertEl.hidden = true;
    const sel = document.getElementById('atajo-accion');
    const meta = sel ? ATAJOS_ACTION_META[sel.value] : null;
    if (meta) {
      const nomInp = document.getElementById('atajo-nombre');
      const modInp = document.getElementById('atajo-modulo');
      if (nomInp) nomInp.value = meta.nombre;
      if (modInp) modInp.value = meta.modulo;
    }
  }

  function startEditingAtajo(a) {
    if (!a) return;
    STATE.editingAtajoId = a.id;
    const tInp = document.getElementById('atajo-tecla');
    const aSel = document.getElementById('atajo-accion');
    const nInp = document.getElementById('atajo-nombre');
    const mInp = document.getElementById('atajo-modulo');
    const actChk = document.getElementById('atajo-activo');
    const leg = document.getElementById('atajo-form-legend');
    const saveBtn = document.getElementById('btn-atajo-save');
    const cancelBtn = document.getElementById('btn-atajo-cancel');

    if (tInp) tInp.value = a.tecla;
    highlightActiveFnChip(a.tecla);
    if (aSel) aSel.value = a.accion;
    if (nInp) nInp.value = a.nombre;
    if (mInp) mInp.value = a.modulo;
    if (actChk) actChk.checked = a.activo !== false;
    if (leg) leg.textContent = `✏️ Editando Atajo CTRL + ${a.tecla}`;
    if (saveBtn) saveBtn.textContent = `💾 Actualizar Atajo (CTRL + ${a.tecla})`;
    if (cancelBtn) cancelBtn.hidden = false;
    tInp?.focus();
    tInp?.select();
  }

  function renderAtajosSection() {
    if (!Array.isArray(STATE.atajos) || STATE.atajos.length === 0) {
      loadAtajosStore();
    }
    syncAtajosUIInModules();

    const total = STATE.atajos.length;
    const activos = STATE.atajos.filter((a) => a.activo !== false).length;
    const custom = STATE.atajos.filter((a) => a.esPersonalizado).length;

    const kpiAct = document.getElementById('kpi-atajos-activos');
    const kpiSub = document.getElementById('kpi-atajos-total-sub');
    const kpiCus = document.getElementById('kpi-atajos-custom');
    if (kpiAct) kpiAct.textContent = String(activos);
    if (kpiSub) kpiSub.textContent = `${total} atajos configurados en total`;
    if (kpiCus) kpiCus.textContent = String(custom);

    if (!STATE.editingAtajoId && !document.getElementById('atajo-nombre')?.value) {
      syncAtajoFormFieldsFromAction();
    }

    const q = normalizeStr(document.getElementById('atajos-filter-q')?.value || '');
    const modFilter = (document.getElementById('atajos-filter-modulo')?.value || '').trim().toUpperCase();

    const filtered = STATE.atajos.filter((a) => {
      if (modFilter && String(a.modulo).toUpperCase() !== modFilter) return false;
      if (q) {
        const hay = normalizeStr(`CTRL + ${a.tecla} CTRL+${a.tecla} ${a.tecla} ${a.nombre} ${a.modulo}`);
        return hay.includes(q);
      }
      return true;
    });

    const tbody = document.getElementById('atajos-tbody');
    if (!tbody) return;
    tbody.textContent = '';

    if (filtered.length === 0) {
      const tr = document.createElement('tr');
      const td = document.createElement('td');
      td.colSpan = 4;
      td.className = 'table-loading-cell';
      td.textContent = 'No se encontraron atajos con el filtro seleccionado.';
      tr.appendChild(td);
      tbody.appendChild(tr);
      return;
    }

    filtered.forEach((a) => {
      const tr = document.createElement('tr');

      const th = document.createElement('th');
      th.scope = 'row';
      th.style.cursor = 'pointer';
      th.title = `Hacé clic para cambiar la tecla de CTRL + ${a.tecla}`;
      th.innerHTML = `<span class="kbd-combo"><kbd class="kbd-key">CTRL</kbd><span class="kbd-plus">+</span><kbd class="kbd-key">${a.tecla}</kbd></span>`;
      th.addEventListener('click', () => startEditingAtajo(a));
      tr.appendChild(th);

      const tdNom = document.createElement('td');
      tdNom.innerHTML = `<div class="price-cell-stack"><strong>${a.nombre}</strong>${a.esPersonalizado ? '<span class="price-neto-val">Personalizado por el usuario</span>' : '<span class="price-neto-val">Atajo del sistema</span>'}</div>`;
      tr.appendChild(tdNom);

      const tdMod = document.createElement('td');
      tdMod.innerHTML = `<span class="badge badge--gold">${a.modulo}</span>`;
      tr.appendChild(tdMod);

      const tdAcc = document.createElement('td');
      const wrap = document.createElement('div');
      wrap.style.display = 'flex';
      wrap.style.gap = '0.35rem';
      wrap.style.flexWrap = 'wrap';

      const btnRun = document.createElement('button');
      btnRun.type = 'button';
      btnRun.className = 'btn-secondary btn-sm';
      btnRun.textContent = '▶️ Probar';
      btnRun.title = `Ejecutar CTRL + ${a.tecla}`;
      btnRun.addEventListener('click', () => {
        executeAtajoAction(a.accion, a);
      });

      const btnEdit = document.createElement('button');
      btnEdit.type = 'button';
      btnEdit.className = 'btn-edit-row';
      btnEdit.textContent = '✏️ Editar';
      btnEdit.addEventListener('click', () => startEditingAtajo(a));

      const btnDel = document.createElement('button');
      btnDel.type = 'button';
      btnDel.className = 'btn-remove-row';
      btnDel.textContent = '🗑️';
      btnDel.title = `Eliminar atajo CTRL + ${a.tecla}`;
      btnDel.addEventListener('click', () => {
        STATE.atajos = STATE.atajos.filter((x) => x.id !== a.id);
        if (STATE.editingAtajoId === a.id) resetAtajoForm();
        saveAtajosStore();
        renderAtajosSection();
      });

      wrap.appendChild(btnRun);
      wrap.appendChild(btnEdit);
      wrap.appendChild(btnDel);
      tdAcc.appendChild(wrap);
      tr.appendChild(tdAcc);

      tbody.appendChild(tr);
    });
  }

  // Captura directa de letras (A-Z), números (0-9) y teclas de función (F1-F12) en #atajo-tecla
  const atajoTeclaInp = document.getElementById('atajo-tecla');
  if (atajoTeclaInp) {
    atajoTeclaInp.addEventListener('keydown', (e) => {
      if (e.key === 'Tab' || e.key === 'Enter') return;
      if (e.key === 'Backspace' || e.key === 'Delete' || e.key === 'Escape') {
        e.preventDefault();
        atajoTeclaInp.value = '';
        highlightActiveFnChip('');
        return;
      }

      // Captura directa de teclas físicas F1 a F12 (con o sin CTRL)
      const fnMatch = /^F([1-9]|1[0-2])$/i.exec(e.key || e.code || '');
      if (fnMatch) {
        e.preventDefault();
        e.stopPropagation();
        const fnVal = `F${fnMatch[1]}`;
        atajoTeclaInp.value = fnVal;
        highlightActiveFnChip(fnVal);
        return;
      }

      if (/^[a-zA-Z0-9]$/.test(e.key)) {
        e.preventDefault();
        const ch = e.key.toUpperCase();
        const cur = String(atajoTeclaInp.value || '').trim().toUpperCase();
        // Permitir también escribir manualmente "F" seguido de "1".."12"
        if (cur === 'F' && /^[1-9]$/.test(ch)) {
          atajoTeclaInp.value = `F${ch}`;
          highlightActiveFnChip(atajoTeclaInp.value);
          return;
        }
        if (cur === 'F1' && /^[0-2]$/.test(ch)) {
          atajoTeclaInp.value = `F1${ch}`;
          highlightActiveFnChip(atajoTeclaInp.value);
          return;
        }
        atajoTeclaInp.value = ch;
        highlightActiveFnChip(ch);
      }
    });

    atajoTeclaInp.addEventListener('input', () => {
      const raw = String(atajoTeclaInp.value || '').trim().toUpperCase();
      highlightActiveFnChip(raw);
    });
  }

  document.querySelectorAll('.shortcut-fn-chip').forEach((chip) => {
    chip.addEventListener('click', () => {
      const fnKey = normalizeAtajoKey(chip.getAttribute('data-fn-key'));
      if (!fnKey || !atajoTeclaInp) return;
      atajoTeclaInp.value = fnKey;
      highlightActiveFnChip(fnKey);
      atajoTeclaInp.focus();
    });
  });

  document.getElementById('atajo-accion')?.addEventListener('change', () => {
    const sel = document.getElementById('atajo-accion');
    const meta = sel ? ATAJOS_ACTION_META[sel.value] : null;
    if (meta) {
      const nomInp = document.getElementById('atajo-nombre');
      const modInp = document.getElementById('atajo-modulo');
      if (nomInp) nomInp.value = meta.nombre;
      if (modInp) modInp.value = meta.modulo;
      if (!STATE.editingAtajoId && atajoTeclaInp && !atajoTeclaInp.value) {
        const existing = (STATE.atajos || []).find((a) => a.accion === sel.value);
        if (existing) {
          atajoTeclaInp.value = existing.tecla;
          highlightActiveFnChip(existing.tecla);
        }
      }
    }
  });

  document.getElementById('btn-atajo-cancel')?.addEventListener('click', () => {
    resetAtajoForm();
  });

  document.getElementById('btn-atajos-new-focus')?.addEventListener('click', () => {
    resetAtajoForm();
    document.getElementById('atajo-tecla')?.focus();
  });

  document.getElementById('btn-atajos-reset-defaults')?.addEventListener('click', () => {
    STATE.atajos = getDefaultAtajosList();
    saveAtajosStore();
    resetAtajoForm();
    renderAtajosSection();
    const okEl = document.getElementById('atajo-form-success');
    if (okEl) {
      okEl.innerHTML = '<strong>✓ Se restauraron todos los atajos predeterminados (CTRL + Tecla / F1–F12) y se actualizaron en todos los módulos.</strong>';
      okEl.hidden = false;
    }
  });

  ['atajos-filter-q', 'atajos-filter-modulo', 'atajos-filter-estado'].forEach((id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.addEventListener(el.tagName === 'SELECT' ? 'change' : 'input', () => renderAtajosSection());
  });

  document.getElementById('atajo-form')?.addEventListener('submit', (e) => {
    e.preventDefault();
    const alertEl = document.getElementById('atajo-form-alert');
    const okEl = document.getElementById('atajo-form-success');
    if (alertEl) alertEl.hidden = true;
    if (okEl) okEl.hidden = true;

    const tecla = normalizeAtajoKey(document.getElementById('atajo-tecla')?.value || '');
    const accion = document.getElementById('atajo-accion')?.value || 'nav:sec-inicio';
    const nombre = (document.getElementById('atajo-nombre')?.value || '').trim().toUpperCase();
    const modulo = (document.getElementById('atajo-modulo')?.value || 'NAVEGACIÓN Y SISTEMA').trim().toUpperCase();
    const activo = document.getElementById('atajo-activo')?.checked !== false;

    if (!tecla) {
      if (alertEl) {
        alertEl.textContent = 'INGRESÁ UNA LETRA (A–Z), UN NÚMERO (0–9) O UNA TECLA DE FUNCIÓN (F1–F12) PARA FORMAR EL ATAJO "CTRL + TECLA".';
        alertEl.hidden = false;
      }
      document.getElementById('atajo-tecla')?.focus();
      return;
    }

    if (!nombre) {
      if (alertEl) {
        alertEl.textContent = 'COMPLETÁ EL NOMBRE O DETALLE DE LA FUNCIÓN DEL ATAJO.';
        alertEl.hidden = false;
      }
      document.getElementById('atajo-nombre')?.focus();
      return;
    }

    const editId = STATE.editingAtajoId ? Number(STATE.editingAtajoId) : null;
    // Si no estaba en modo edición pero eligió una acción que ya existe, actualizamos ese atajo existente
    const targetEntry = editId
      ? STATE.atajos.find((a) => Number(a.id) === editId)
      : STATE.atajos.find((a) => a.accion === accion);
    const targetId = targetEntry ? Number(targetEntry.id) : null;

    const duplicate = STATE.atajos.find(
      (a) => normalizeAtajoKey(a.tecla) === tecla && Number(a.id) !== targetId
    );
    if (duplicate) {
      if (alertEl) {
        alertEl.textContent = `EL ATAJO "CTRL + ${tecla}" YA ESTÁ ASIGNADO A "${duplicate.nombre}". ELEGÍ OTRA TECLA O EDITÁ ESE ATAJO DE LA LISTA.`;
        alertEl.hidden = false;
      }
      document.getElementById('atajo-tecla')?.focus();
      return;
    }

    if (targetId !== null) {
      const idx = STATE.atajos.findIndex((a) => Number(a.id) === targetId);
      if (idx >= 0) {
        STATE.atajos[idx] = Object.assign({}, STATE.atajos[idx], {
          tecla,
          accion,
          nombre,
          modulo,
          activo,
          esPersonalizado: true
        });
      }
    } else {
      const nextId = STATE.atajos.reduce((mx, a) => Math.max(mx, Number(a.id) || 0), 0) + 1;
      STATE.atajos.unshift({
        id: nextId,
        tecla,
        accion,
        nombre,
        modulo,
        activo,
        esPersonalizado: true
      });
    }

    saveAtajosStore();
    resetAtajoForm();
    renderAtajosSection();

    if (okEl) {
      okEl.innerHTML = `<strong>✓ Atajo actualizado en todos los módulos:</strong> <kbd class="kbd-key">CTRL</kbd> + <kbd class="kbd-key">${tecla}</kbd> → <strong>${nombre}</strong>.`;
      okEl.hidden = false;
    }
  });

  // Listener Global Unificado en fase de captura para todos los Atajos Activos (CTRL + A..Z / 0..9 / F1..F12)
  window.addEventListener(
    'keydown',
    (e) => {
      if (dashboardView.hidden) return;
      if (document.activeElement === atajoTeclaInp) return;

      const fnKeyMatch = /^F([1-9]|1[0-2])$/i.exec(e.key || e.code || '');
      const hasCtrlOrMeta = Boolean(e.ctrlKey || e.metaKey);

      // Si se presiona F1..F10 sin modificadores y el usuario asignó esa tecla F en STATE.atajos (excepto F5 recarga nativa)
      if (!hasCtrlOrMeta && !e.altKey && !e.shiftKey && fnKeyMatch) {
        const fnKey = `F${fnKeyMatch[1]}`;
        if (fnKey !== 'F5' && fnKey !== 'F11' && fnKey !== 'F12') {
          const fnShortcut = (STATE.atajos || []).find(
            (a) => a.activo !== false && normalizeAtajoKey(a.tecla) === fnKey
          );
          if (fnShortcut) {
            e.preventDefault();
            e.stopPropagation();
            executeAtajoAction(fnShortcut.accion, fnShortcut);
            return;
          }
        }
        return;
      }

      if (!hasCtrlOrMeta || e.altKey || e.shiftKey) return;

      let pressedKey = '';
      if (fnKeyMatch) {
        pressedKey = `F${fnKeyMatch[1]}`;
      } else {
        pressedKey = normalizeAtajoKey(e.key);
        if (!pressedKey && e.code) {
          if (/^Key[A-Z]$/.test(e.code)) pressedKey = e.code.slice(3);
          else if (/^Digit[0-9]$/.test(e.code)) pressedKey = e.code.slice(5);
        }
      }
      if (!pressedKey) return;

      const activeEl = document.activeElement;
      const isTextInput =
        activeEl &&
        ((activeEl.tagName === 'INPUT' && !['button', 'checkbox', 'radio', 'submit'].includes(activeEl.type)) ||
          activeEl.tagName === 'TEXTAREA' ||
          activeEl.isContentEditable);
      const isEditableInput = Boolean(isTextInput && !activeEl.readOnly && !activeEl.disabled);
      const hasSelectedInputText =
        isTextInput &&
        typeof activeEl.selectionStart === 'number' &&
        typeof activeEl.selectionEnd === 'number' &&
        activeEl.selectionEnd > activeEl.selectionStart;

      // Respetar Copiar / Cortar cuando hay texto seleccionado dentro de un input
      if ((pressedKey === 'C' || pressedKey === 'X') && hasSelectedInputText) {
        return;
      }

      const match = (STATE.atajos || []).find(
        (a) => a.activo !== false && normalizeAtajoKey(a.tecla) === pressedKey
      );
      if (!match) {
        // Si no hay un atajo configurado para esta tecla, dejamos el comportamiento nativo del navegador (ej. Ctrl+V, Ctrl+Z, Ctrl+A)
        return;
      }

      // Si el usuario está escribiendo en un input editable con texto y presiona Ctrl+V (pegar) o Ctrl+Z (deshacer),
      // solo ejecutamos atajo si fue explícitamente personalizado por el usuario
      if (isEditableInput && (pressedKey === 'V' || pressedKey === 'Z') && !match.esPersonalizado) {
        return;
      }

      e.preventDefault();
      e.stopPropagation();
      executeAtajoAction(match.accion, match);
    },
    true
  );

  // =========================================================================
  // MÓDULO DE ESTADÍSTICAS (4 SUBMÓDULOS + FILTROS MULTI-PV Y MULTI-MES/RANGO + GRÁFICOS DE CONTROL)
  // =========================================================================
  const EST_ALL_PVS = ['0002', '0003', '0004', '0099', '0100', '0101'];
  const EST_PV_LABELS = {
    '0002': 'PV 0002 (Caja 1 · Fiscal)',
    '0003': 'PV 0003 (Caja 2 · Fiscal)',
    '0004': 'PV 0004 (Caja 3 · Fiscal)',
    '0099': 'PV 0099 (Caja 1 · Interno)',
    '0100': 'PV 0100 (Caja 2 · Interno)',
    '0101': 'PV 0101 (Caja 3 · Interno)'
  };
  const EST_MEDIOS_LIST = ['Efectivo', 'Débito', 'Crédito', 'QR', 'Cuenta Corriente'];
  const EST_CHART_PALETTE = [
    '#d97706',
    '#2563eb',
    '#16a34a',
    '#9333ea',
    '#e11d48',
    '#0891b2',
    '#4f46e5',
    '#ca8a04',
    '#059669',
    '#dc2626',
    '#7c3aed',
    '#0284c7'
  ];

  const EST_STATE = {
    chartTypeDashEvolucion: 'line',
    chartTypeDashMedios: 'pie',
    chartTypeFact: 'line',
    chartTypeFactPv: 'bar',
    chartTypeRanking: 'bar',
    chartTypeMedios: 'pie',
    chartTypeMargenBar: 'bar',
    chartTypeMargenPie: 'pie',
    chartTypeGananciaBruta: 'bar',
    chartTypeGananciaNeta: 'bar',
    chartTypeGananciaNetaGastos: 'bar',
    populatedSelects: false,
    excludedRankProductKeys: new Set()
  };

  function getMonthLabelsList() {
    const nombres = [
      'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
      'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
    ];
    const now = new Date();
    const curYear = now.getFullYear();
    const curMonth = now.getMonth() + 1;
    const list = [];
    for (let m = 1; m <= 12; m++) {
      const ym = `${curYear}-${String(m).padStart(2, '0')}`;
      list.push({
        ym,
        shortLabel: `${nombres[m - 1].slice(0, 3)} ${curYear}`,
        fullLabel: `${nombres[m - 1]} ${curYear}`,
        isCurrentOrPast: m <= curMonth
      });
    }
    return list;
  }

  function initEstFiltersDOM() {
    const mesesContainer = document.getElementById('est-meses-checks-container');
    if (mesesContainer && mesesContainer.children.length === 0) {
      const months = getMonthLabelsList();
      const now = new Date();
      const curYm = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
      const prevMonthNum = now.getMonth() === 0 ? 12 : now.getMonth();
      const prevYear = now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear();
      const prevYm = `${prevYear}-${String(prevMonthNum).padStart(2, '0')}`;

      months.forEach((m) => {
        const checked = m.ym === curYm || m.ym === prevYm;
        const lbl = document.createElement('label');
        lbl.className = `checkbox-pill est-pv-pill ${checked ? 'is-checked' : ''}`;
        lbl.innerHTML = `<input type="checkbox" class="est-mes-chk" value="${m.ym}" ${checked ? 'checked' : ''} /> <span>${m.shortLabel}</span>`;
        mesesContainer.appendChild(lbl);
      });
    }

    const fromInp = document.getElementById('est-date-from');
    const toInp = document.getElementById('est-date-to');
    if (fromInp && !fromInp.value) {
      const now = new Date();
      const y = now.getFullYear();
      const m = String(now.getMonth() + 1).padStart(2, '0');
      const d = String(now.getDate()).padStart(2, '0');
      fromInp.value = `${y}-${m}-01`;
      if (toInp) toInp.value = `${y}-${m}-${d}`;
    }
  }

  function mountEstSharedFilterBar(targetId) {
    initEstFiltersDOM();
    const filterBar = document.getElementById('est-shared-filter-bar');
    if (!filterBar) return;
    const slotMap = {
      'sec-est-dashboard': 'est-shared-filter-slot-dashboard',
      'sec-est-facturacion': 'est-shared-filter-slot-facturacion',
      'sec-est-ranking': 'est-shared-filter-slot-ranking',
      'sec-est-medios': 'est-shared-filter-slot-medios',
      'sec-est-margenes': 'est-shared-filter-slot-margenes',
      'sec-est-ganancia-bruta': 'est-filter-host-ganancia-bruta',
      'sec-est-art-generico': 'est-shared-filter-slot-art-generico'
    };
    const slotId = slotMap[targetId];
    if (!slotId) {
      filterBar.hidden = true;
      return;
    }
    const slot = document.getElementById(slotId);
    if (slot) {
      slot.appendChild(filterBar);
      filterBar.hidden = false;
      updateEstFilterSummaryBadge();
    }
  }

  function getSelectedEstPVs() {
    const chks = Array.from(document.querySelectorAll('.est-pv-chk:checked')).map((el) => el.value);
    return chks.length > 0 ? chks : [...EST_ALL_PVS];
  }

  function getSelectedEstDateFilter() {
    const modeRadio = document.querySelector('input[name="est_date_mode"]:checked');
    const mode = modeRadio ? modeRadio.value : 'rango';
    const fromVal = document.getElementById('est-date-from')?.value || '2026-11-01';
    const toVal = document.getElementById('est-date-to')?.value || '2026-11-30';
    const selectedMonths = Array.from(document.querySelectorAll('.est-mes-chk:checked')).map((el) => el.value);
    if (selectedMonths.length === 0) {
      const now = new Date();
      selectedMonths.push(`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`);
    }
    return {
      mode,
      from: fromVal <= toVal ? fromVal : toVal,
      to: fromVal <= toVal ? toVal : fromVal,
      months: selectedMonths.sort()
    };
  }

  function updateEstFilterSummaryBadge() {
    const badge = document.getElementById('est-filter-summary-badge');
    if (!badge) return;
    const pvs = getSelectedEstPVs();
    const df = getSelectedEstDateFilter();
    const pvTxt = pvs.length === EST_ALL_PVS.length ? 'Todos los PVs (6)' : `PVs: ${pvs.join(', ')}`;
    const dateTxt =
      df.mode === 'rango'
        ? `Rango: ${df.from.split('-').reverse().join('/')} al ${df.to.split('-').reverse().join('/')}`
        : `Meses (${df.months.length}): ${df.months.join(', ')}`;
    badge.textContent = `${pvTxt} · ${dateTxt}`;
  }

  function getEstRubroName(rId) {
    const idNum = Number(rId) || 0;
    if (idNum > 0 && STATE.rubrosMap instanceof Map && STATE.rubrosMap.has(idNum)) {
      return STATE.rubrosMap.get(idNum).nombre || `RUBRO #${idNum}`;
    }
    const found = (STATE.rubros || []).find((r) => Number(r.id) === idNum);
    return found ? found.nombre : 'ALMACÉN GENERAL';
  }

  function getEstMarcaName(mId) {
    const idNum = Number(mId) || 0;
    if (idNum > 0 && STATE.marcasMap instanceof Map && STATE.marcasMap.has(idNum)) {
      return STATE.marcasMap.get(idNum).nombre || `MARCA #${idNum}`;
    }
    const found = (STATE.marcas || []).find((m) => Number(m.id) === idNum);
    return found ? found.nombre : 'VARIAS MARCAS';
  }

  function populateEstSelectFilters() {
    if (!STATE.loaded && (!Array.isArray(STATE.rubros) || STATE.rubros.length === 0)) return;
    const activeRubros = (STATE.rubros || [])
      .filter((r) => Number(r.bl) !== 1 && r.nombre)
      .sort((a, b) => String(a.nombre).localeCompare(String(b.nombre), 'es-AR'));
    const activeMarcas = (STATE.marcas || [])
      .filter((m) => Number(m.bl) !== 1 && m.nombre)
      .sort((a, b) => String(a.nombre).localeCompare(String(b.nombre), 'es-AR'));
    const activeProvs = (STATE.proveedores || [])
      .filter((p) => Number(p.bl) !== 1 && p.nombre)
      .sort((a, b) => String(a.nombre).localeCompare(String(b.nombre), 'es-AR'));

    const fillSelect = (selId, defaultText, items) => {
      const sel = document.getElementById(selId);
      if (!sel || items.length === 0) return;
      if (sel.options.length > 1) return;
      const prevVal = sel.value || '0';
      sel.innerHTML = `<option value="0">${defaultText} (${items.length})</option>`;
      items.forEach((item) => {
        const opt = document.createElement('option');
        opt.value = String(item.id);
        opt.textContent = item.nombre;
        sel.appendChild(opt);
      });
      sel.value = prevVal;
    };

    fillSelect('est-rank-rubro', 'Todos los rubros', activeRubros);
    fillSelect('est-margen-rubro', 'Todos los rubros', activeRubros);
    fillSelect('est-rank-proveedor', 'Todos los proveedores', activeProvs);
    fillSelect('est-margen-proveedor', 'Todos los proveedores', activeProvs);
    fillSelect('est-rank-marca', 'Todas las marcas', activeMarcas);
    fillSelect('est-margen-marca', 'Todas las marcas', activeMarcas);

    if (activeRubros.length > 0 && activeMarcas.length > 0 && activeProvs.length > 0) {
      EST_STATE.populatedSelects = true;
    }
  }

  function getArticleProviderInfo(art) {
    if (!art) return { id: 0, nombre: 'PROVEEDOR GENERAL CASA NUEVA' };
    const explicitId = Number(art.p ?? art.pId) || 0;
    if (explicitId > 0 && STATE.proveedoresMap instanceof Map && STATE.proveedoresMap.has(explicitId)) {
      const pObj = STATE.proveedoresMap.get(explicitId);
      return { id: Number(pObj.id), nombre: pObj.nombre || `PROVEEDOR #${explicitId}` };
    }
    const provList = (STATE.proveedores && STATE.proveedores.length > 0)
      ? STATE.proveedores
      : (STATE.clientes || []).filter((c) => c.esProveedor);
    if (provList.length === 0) {
      return { id: 1, nombre: 'DISTRIBUIDORA MAYORISTA REGIONAL S.A.' };
    }
    const artId = Number(art.id ?? art.artId) || 1;
    const rId = Number(art.r ?? art.rId) || 1;
    const mId = Number(art.mk ?? art.mId) || 1;
    const idx = Math.abs(artId * 7 + rId * 13 + mId * 5) % provList.length;
    const chosen = provList[idx];
    return {
      id: Number(chosen?.id) || (idx + 1),
      nombre: chosen?.nombre || 'PROVEEDOR GENERAL'
    };
  }

  function getArticleProviderName(art) {
    return getArticleProviderInfo(art).nombre;
  }

  function isGenericStatisticArticle(artOrItem, artById = {}) {
    if (!artOrItem) return false;
    if (artOrItem.isGeneric) return true;
    const aid = Number(artOrItem.artId ?? artOrItem.a ?? artOrItem.id) || 0;
    if (aid === 4407 || aid === 7860) return true;
    const catArt = aid > 0 ? artById[aid] : null;
    const rawCode = String(artOrItem.codigo ?? artOrItem.c ?? catArt?.c ?? '').trim();
    if (rawCode) {
      if (isGenericArticleCode(rawCode)) return true;
      const cleanDigits = rawCode.replace(/\D/g, '').replace(/^0+/, '');
      if (cleanDigits === '3000') return true;
    }
    const rawName = String(artOrItem.nombre ?? artOrItem.n ?? catArt?.n ?? '').trim().toUpperCase();
    if (
      rawName.includes('ART. GENERICO') ||
      rawName.includes('ARTICULO GENERICO') ||
      rawName.includes('ARTÍCULO GENÉRICO') ||
      rawName.includes('ENVASE RETORNABLE')
    ) {
      return true;
    }
    return false;
  }

  function classifyLivePosOperationForStats(op) {
    if (!op) return { include: false, dh: 1, tipoLabel: '' };
    const entryType = String(op.entryType || 'venta').trim().toLowerCase();
    // Excluir estrictamente Recibos de Pago y Retiros / Movimientos de Caja
    if (entryType === 'recibo' || entryType === 'retiro' || entryType === 'movimiento') {
      return { include: false, dh: 1, tipoLabel: '' };
    }
    const pv = String(op.pv || '').replace(/\D/g, '').padStart(4, '0');
    if (!EST_ALL_PVS.includes(pv)) {
      return { include: false, dh: 1, tipoLabel: '' };
    }
    const letra = String(op.letra || '').trim().toUpperCase();
    const codArca = String(op.codArca || '').trim();
    const tipoFull = String(`${op.tipoBase || ''} ${op.tipo || ''}`).toUpperCase();
    if (
      tipoFull.includes('RECIBO') ||
      tipoFull.includes('RETIRO') ||
      tipoFull.includes('ORDEN DE PAGO') ||
      tipoFull.includes('AJUSTE') ||
      tipoFull.includes('DÉBITO') ||
      tipoFull.includes('DEBITO') ||
      /\bND\b/.test(tipoFull) ||
      letra === 'X' ||
      codArca === '99'
    ) {
      return { include: false, dh: 1, tipoLabel: '' };
    }

    const isNotaCredito =
      tipoFull.includes('CRÉDITO') ||
      tipoFull.includes('CREDITO') ||
      /\bNC\b/.test(tipoFull) ||
      Number(op.tc) === 6 ||
      Number(op.dh) === -1;

    const isInternalPv = pv === '0099' || pv === '0100' || pv === '0101';
    const cleanLetra = letra === 'A' ? 'A' : 'B';
    const tipoLabel = isNotaCredito
      ? `Nota de Crédito ${cleanLetra}`
      : isInternalPv
        ? `Comprobante Interno ${cleanLetra}`
        : `Factura ${cleanLetra}`;

    return {
      include: true,
      dh: isNotaCredito ? -1 : 1,
      isNotaCredito,
      pv,
      letra: cleanLetra,
      tipoLabel
    };
  }

  function getEstadisticasDataset() {
    if (STATE.estDatasetCache && STATE.loaded && STATE.ventasLoaded) {
      return STATE.estDatasetCache;
    }

    const records = [];
    const now = new Date();
    const curYear = now.getFullYear();
    const curMonth = now.getMonth() + 1;
    const curDay = now.getDate();

    // 1. Ventas netas reales desde ventas_db.json (únicamente Facturas ARCA A/B, Comprobantes Internos no ARCA y Notas de Crédito restando; excluyendo Recibos y otros movimientos)
    if (STATE.ventasDb && Array.isArray(STATE.ventasDb.dailyRecords) && STATE.ventasDb.dailyRecords.length > 0) {
      for (const r of STATE.ventasDb.dailyRecords) {
        const pv = String(r.pv || '0002').replace(/\D/g, '').padStart(4, '0');
        if (!EST_ALL_PVS.includes(pv)) continue;
        const fechaIso = String(r.f || '');
        if (!fechaIso) continue;
        const tc = Number(r.tc ?? 1);
        // Solo se contabilizan Ventas (tc=1: Factura ARCA A/B o Comprobante Interno) y Notas de Crédito (tc=6, restando)
        if (tc !== 1 && tc !== 6) continue;
        const letra = String(r.l || 'B').trim().toUpperCase();
        if (letra === 'X') continue;

        const ym = fechaIso.slice(0, 7);
        const isNotaCredito = tc === 6 || Number(r.v) < 0;
        const rawImp = Math.abs(round2(r.v || 0));
        const rawCosto = Math.abs(round2(r.c || 0));
        const importe = isNotaCredito ? -rawImp : rawImp;
        const costoTotal = isNotaCredito ? -rawCosto : rawCosto;
        const isInternalPv = pv === '0099' || pv === '0100' || pv === '0101';
        records.push({
          pv,
          fechaIso,
          ym,
          tipo: isNotaCredito
            ? `Nota de Crédito ${letra || 'B'}`
            : isInternalPv
              ? `Comprobante Interno ${letra || 'B'}`
              : `Factura ${letra || 'B'}`,
          medioPago: EST_MEDIOS_LIST.includes(r.mp) ? r.mp : 'Efectivo',
          tickets: Math.max(1, Number(r.t) || 1),
          importe,
          costoTotal,
          ganancia: round2(importe - costoTotal),
          items: []
        });
      }
    }

    // 2. Incorporar comprobantes nuevos emitidos en vivo en las Cajas POS durante la sesión que aún no estén consolidados en dailyRecords (excluyendo Recibos, Retiros y los ya importados)
    Object.keys(STATE.turnosCajas || {}).forEach((cajaKey) => {
      const lista = STATE.turnosCajas[cajaKey] || [];
      lista.forEach((op) => {
        if (op.origenOliver || op._inServerDailyRecords) return;
        const cls = classifyLivePosOperationForStats(op);
        if (!cls.include) return;

        let fechaIso = op.fechaIso;
        if (!fechaIso && op.fechaHora) {
          const m = String(op.fechaHora).match(/(\d{2})\/(\d{2})\/(\d{4})/);
          if (m) fechaIso = `${m[3]}-${m[2]}-${m[1]}`;
        }
        if (!fechaIso) {
          fechaIso = `${curYear}-${String(curMonth).padStart(2, '0')}-${String(curDay).padStart(2, '0')}`;
        }
        const ym = fechaIso.slice(0, 7);
        let medioPago = op.medioPago || 'Efectivo';
        if (medioPago === 'Contado') medioPago = 'Efectivo';
        if (!EST_MEDIOS_LIST.includes(medioPago)) medioPago = 'Efectivo';

        const rawImp = Math.abs(round2(op.importe || 0));
        if (rawImp <= 0) return;

        const items = Array.isArray(op.items) ? op.items : [];
        const rawCosto = items.length > 0
          ? Math.abs(round2(items.reduce((acc, it) => acc + (Number(it.costoTotal) || 0), 0)))
          : round2(rawImp * 0.72);
        const importe = round2(rawImp * cls.dh);
        const costoTotal = round2(rawCosto * cls.dh);
        records.push({
          pv: cls.pv,
          fechaIso,
          ym,
          tipo: cls.tipoLabel,
          medioPago,
          tickets: 1,
          importe,
          costoTotal,
          ganancia: round2(importe - costoTotal),
          items
        });
      });
    });

    if (STATE.loaded && STATE.ventasLoaded) {
      STATE.estDatasetCache = records;
    }
    return records;
  }

  function getFilteredRealProductSalesItems(artById = {}) {
    const pvs = new Set(getSelectedEstPVs());
    const df = getSelectedEstDateFilter();
    const monthsSet = new Set(df.months);
    const out = [];

    if (STATE.ventasDb) {
      if (df.mode === 'rango' && df.from >= '2026-10-01' && Array.isArray(STATE.ventasDb.artRecentDaily)) {
        for (const row of STATE.ventasDb.artRecentDaily) {
          if (!pvs.has(String(row.pv))) continue;
          if (row.f < df.from || row.f > df.to) continue;
          const art = artById[row.a];
          if (isGenericStatisticArticle({ a: row.a, c: art?.c, n: art?.n }, artById)) continue;
          out.push({
            artId: row.a,
            c: art?.c || String(row.a).padStart(5, '0'),
            n: art?.n || `ARTÍCULO #${row.a}`,
            rId: Number(art?.r) || 0,
            mId: Number(art?.mk) || 0,
            pId: Number(art?.p) || 0,
            qty: Number(row.q) || 0,
            subtotal: Number(row.v) || 0,
            costoTotal: Number(row.c) || 0
          });
        }
      } else if (Array.isArray(STATE.ventasDb.artMonthly)) {
        const fromYm = df.mode === 'rango' ? String(df.from || '').slice(0, 7) : '';
        const toYm = df.mode === 'rango' ? String(df.to || '').slice(0, 7) : '';
        for (const row of STATE.ventasDb.artMonthly) {
          if (!pvs.has(String(row.pv))) continue;
          if (df.mode === 'rango') {
            if (row.ym < fromYm || row.ym > toYm) continue;
          } else if (!monthsSet.has(row.ym)) {
            continue;
          }
          const art = artById[row.a];
          if (isGenericStatisticArticle({ a: row.a, c: art?.c, n: art?.n }, artById)) continue;
          out.push({
            artId: row.a,
            c: art?.c || String(row.a).padStart(5, '0'),
            n: art?.n || `ARTÍCULO #${row.a}`,
            rId: Number(art?.r) || 0,
            mId: Number(art?.mk) || 0,
            pId: Number(art?.p) || 0,
            qty: Number(row.q) || 0,
            subtotal: Number(row.v) || 0,
            costoTotal: Number(row.c) || 0
          });
        }
      }
    }

    // Sumar ítems de comprobantes nuevos emitidos en vivo en POS durante la sesión (excluyendo Recibos, Retiros y Código 20)
    Object.keys(STATE.turnosCajas || {}).forEach((cajaKey) => {
      (STATE.turnosCajas[cajaKey] || []).forEach((op) => {
        if (op.origenOliver || op._inServerDailyRecords) return;
        const cls = classifyLivePosOperationForStats(op);
        if (!cls.include) return;
        if (!pvs.has(cls.pv)) return;
        const fIso = op.fechaIso || '';
        const ym = fIso.slice(0, 7);
        if (df.mode === 'rango') {
          if (fIso && (fIso < df.from || fIso > df.to)) return;
        } else if (ym && !monthsSet.has(ym)) {
          return;
        }
        (op.items || []).forEach((it) => {
          const art = artById[it.artId];
          if (isGenericStatisticArticle(it, artById) || isGenericStatisticArticle(art, artById)) return;
          out.push({
            artId: it.artId,
            c: it.c || it.codigo || art?.c || '',
            n: it.n || it.nombre || art?.n || 'ARTÍCULO',
            rId: Number(it.rId ?? art?.r) || 0,
            mId: Number(it.mId ?? art?.mk) || 0,
            pId: Number(it.pId ?? art?.p) || 0,
            qty: (Number(it.qty) || 0) * cls.dh,
            subtotal: (Number(it.subtotal) || 0) * cls.dh,
            costoTotal: (Number(it.costoTotal) || 0) * cls.dh
          });
        });
      });
    });

    return out;
  }

  function getFilteredEstRecords() {
    const all = getEstadisticasDataset();
    const pvs = new Set(getSelectedEstPVs());
    const df = getSelectedEstDateFilter();
    const monthsSet = new Set(df.months);

    return all.filter((r) => {
      if (!pvs.has(r.pv)) return false;
      if (df.mode === 'rango') {
        return r.fechaIso >= df.from && r.fechaIso <= df.to;
      }
      return monthsSet.has(r.ym);
    });
  }

  // =========================================================================
  // MOTOR DE GRÁFICOS DE CONTROL EN CANVAS (LÍNEA, BARRAS Y TORTA)
  // =========================================================================
  function formatCompactArs(val) {
    const n = Number(val) || 0;
    if (Math.abs(n) >= 1_000_000) {
      return `$ ${(n / 1_000_000).toLocaleString('es-AR', { minimumFractionDigits: 1, maximumFractionDigits: 2 })}M`;
    }
    if (Math.abs(n) >= 1_000) {
      return `$ ${(n / 1_000).toLocaleString('es-AR', { minimumFractionDigits: 0, maximumFractionDigits: 1 })}k`;
    }
    return `$ ${formatArs(n)}`;
  }

  function getOrCreateEstChartTooltip() {
    let tip = document.getElementById('est-chart-hover-tooltip');
    if (!tip) {
      tip = document.createElement('div');
      tip.id = 'est-chart-hover-tooltip';
      tip.style.cssText = [
        'position:fixed',
        'z-index:99999',
        'pointer-events:none',
        'background:rgba(15, 23, 42, 0.96)',
        'color:#f8fafc',
        'border:1px solid rgba(217, 119, 6, 0.65)',
        'border-radius:10px',
        'padding:8px 12px',
        'font-size:12px',
        'line-height:1.4',
        'box-shadow:0 10px 25px rgba(0,0,0,0.28)',
        'white-space:nowrap',
        'transition:opacity 0.08s ease',
        'opacity:0'
      ].join(';');
      tip.hidden = true;
      document.body.appendChild(tip);
    }
    return tip;
  }

  function hideEstChartTooltip() {
    const tip = document.getElementById('est-chart-hover-tooltip');
    if (tip) {
      tip.style.opacity = '0';
      tip.hidden = true;
    }
  }

  function formatEstAxisDateShort(rawLabel) {
    const s = String(rawLabel ?? '').trim();
    const mFullDate = s.match(/^(\d{2})\/(\d{2})\/\d{4}$/);
    if (mFullDate) {
      return `${mFullDate[1]}/${mFullDate[2]}`;
    }
    const mIsoDate = s.match(/^\d{4}-(\d{2})-(\d{2})$/);
    if (mIsoDate) {
      return `${mIsoDate[2]}/${mIsoDate[1]}`;
    }
    return s;
  }

  function drawEstControlChart(canvasOrId, chartType, labels, values, options = {}) {
    const canvas = typeof canvasOrId === 'string' ? document.getElementById(canvasOrId) : canvasOrId;
    if (!canvas) return;
    const canvasId = canvas.id || (typeof canvasOrId === 'string' ? canvasOrId : '');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    const cssWidth = Math.max(320, rect.width || canvas.width || 680);
    const cssHeight = Math.max(230, rect.height || canvas.height || 300);

    canvas.width = Math.round(cssWidth * dpr);
    canvas.height = Math.round(cssHeight * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, cssWidth, cssHeight);

    const isDark =
      document.documentElement.getAttribute('data-theme') === 'dark' ||
      document.body.classList.contains('theme-dark');
    const textColor = isDark ? '#e2e8f0' : '#1e293b';
    const mutedColor = isDark ? '#94a3b8' : '#64748b';
    const gridColor = isDark ? 'rgba(148, 163, 184, 0.16)' : 'rgba(100, 116, 139, 0.16)';
    const fontFamily = "'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";

    const safeLabels = Array.isArray(labels) ? labels : [];
    const fullLabels = Array.isArray(options.fullLabels) && options.fullLabels.length === safeLabels.length
      ? options.fullLabels
      : safeLabels;
    const extraTooltipLines = Array.isArray(options.extraTooltipLines) ? options.extraTooltipLines : [];
    const safeValues = Array.isArray(values) ? values.map((v) => Math.max(0, Number(v) || 0)) : [];
    const totalSum = safeValues.reduce((a, b) => a + b, 0);
    const hoverIndex = typeof options._hoverIndex === 'number' ? options._hoverIndex : -1;

    if (safeLabels.length === 0 || totalSum <= 0) {
      canvas.__estChartMeta = null;
      ctx.fillStyle = mutedColor;
      ctx.font = `600 13px ${fontFamily}`;
      ctx.textAlign = 'center';
      ctx.fillText('Sin datos para los filtros seleccionados', cssWidth / 2, cssHeight / 2);
      return;
    }

    const isCurrency = options.isCurrency !== false;
    const isPercentValue = Boolean(options.isPercent);
    const fmtVal = (v) =>
      isPercentValue
        ? `${Number(v || 0).toLocaleString('es-AR', { minimumFractionDigits: 1, maximumFractionDigits: 2 })}%`
        : isCurrency
          ? formatCompactArs(v)
          : v.toLocaleString('es-AR');
    const fmtExactVal = (v) =>
      isPercentValue
        ? `${Number(v || 0).toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}%`
        : isCurrency
          ? `$ ${formatArs(v)}`
          : `${Number(v || 0).toLocaleString('es-AR')} unid.`;

    if (chartType === 'pie') {
      const centerX = Math.min(cssWidth * 0.25, cssHeight * 0.52);
      const centerY = cssHeight / 2;
      const radius = Math.max(55, Math.min(centerX - 18, cssHeight / 2 - 22));
      const innerRadius = radius * 0.52;
      const slicesMeta = [];
      const legendRowsMeta = [];

      let startAngle = -Math.PI / 2;
      safeValues.forEach((val, idx) => {
        const sliceAngle = (val / totalSum) * Math.PI * 2;
        const endAngle = startAngle + sliceAngle;
        const color = EST_CHART_PALETTE[idx % EST_CHART_PALETTE.length];
        const isHovered = idx === hoverIndex;
        const midAngle = startAngle + sliceAngle / 2;
        const offset = isHovered ? 6 : 0;
        const cx = centerX + Math.cos(midAngle) * offset;
        const cy = centerY + Math.sin(midAngle) * offset;

        ctx.beginPath();
        ctx.moveTo(cx, cy);
        ctx.arc(cx, cy, isHovered ? radius + 3 : radius, startAngle, endAngle);
        ctx.closePath();
        ctx.fillStyle = color;
        ctx.fill();
        ctx.lineWidth = isHovered ? 2.5 : 2;
        ctx.strokeStyle = isDark ? '#0f172a' : '#ffffff';
        ctx.stroke();

        const pct = (val / totalSum) * 100;
        if (pct >= 5) {
          const labelR = (radius + innerRadius) / 2 + offset;
          const lx = centerX + Math.cos(midAngle) * labelR;
          const ly = centerY + Math.sin(midAngle) * labelR;
          ctx.fillStyle = '#ffffff';
          ctx.font = `700 11px ${fontFamily}`;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText(`${pct.toFixed(1)}%`, lx, ly);
        }

        slicesMeta.push({
          idx,
          startAngle,
          endAngle,
          val,
          pct,
          label: String(fullLabels[idx] || safeLabels[idx] || ''),
          extra: extraTooltipLines[idx] || ''
        });
        startAngle = endAngle;
      });

      // Centro hueco para estilo Donut limpio con total
      ctx.beginPath();
      ctx.arc(centerX, centerY, innerRadius, 0, Math.PI * 2);
      ctx.fillStyle = isDark ? '#111827' : '#ffffff';
      ctx.fill();

      ctx.fillStyle = mutedColor;
      ctx.font = `600 10px ${fontFamily}`;
      ctx.textAlign = 'center';
      ctx.fillText('TOTAL', centerX, centerY - 8);
      ctx.fillStyle = textColor;
      ctx.font = `800 12px ${fontFamily}`;
      ctx.fillText(fmtVal(totalSum), centerX, centerY + 9);

      // Leyenda lateral derecha: Primero porcentaje, luego descripción completa sin cortar
      const legendX = centerX + radius + 22;
      const maxItems = Math.min(safeLabels.length, 12);
      const rowH = Math.min(23, Math.max(16, (cssHeight - 18) / Math.max(1, maxItems)));
      const startY = Math.max(14, (cssHeight - maxItems * rowH) / 2 + rowH / 2);
      const availTextW = Math.max(180, cssWidth - (legendX + 18) - 8);

      for (let i = 0; i < maxItems; i++) {
        const y = startY + i * rowH;
        const color = EST_CHART_PALETTE[i % EST_CHART_PALETTE.length];
        const pct = ((safeValues[i] / totalSum) * 100).toFixed(1);
        const isHovered = i === hoverIndex;

        if (isHovered) {
          ctx.fillStyle = isDark ? 'rgba(217, 119, 6, 0.18)' : 'rgba(217, 119, 6, 0.10)';
          ctx.beginPath();
          ctx.roundRect(legendX - 4, y - rowH / 2 + 1, Math.max(160, cssWidth - legendX - 6), rowH - 2, 5);
          ctx.fill();
        }

        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.roundRect(legendX, y - 5.5, 11, 11, 3);
        ctx.fill();

        const fullLbl = String(fullLabels[i] || safeLabels[i] || '').trim();
        const legendLine = `(${pct}%)  ${fullLbl}`;
        const weight = isHovered ? '800' : '600';
        let fontSize = 11;
        ctx.font = `${weight} ${fontSize}px ${fontFamily}`;
        while (fontSize > 8.5 && ctx.measureText(legendLine).width > availTextW) {
          fontSize -= 0.5;
          ctx.font = `${weight} ${fontSize}px ${fontFamily}`;
        }

        ctx.fillStyle = isHovered ? '#d97706' : textColor;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText(legendLine, legendX + 17, y);

        legendRowsMeta.push({
          idx: i,
          xMin: legendX - 4,
          xMax: cssWidth - 4,
          yMin: y - rowH / 2,
          yMax: y + rowH / 2
        });
      }

      canvas.__estChartMeta = {
        chartType: 'pie',
        canvasId,
        labels: safeLabels,
        values: safeValues,
        options: { ...options, _hoverIndex: undefined },
        centerX,
        centerY,
        radius,
        innerRadius,
        slicesMeta,
        legendRowsMeta,
        fmtExactVal
      };
      bindEstCanvasHoverEvents(canvas);
      return;
    }

    // Formatear etiquetas de eje X (fechas siempre en dd/mm)
    const axisLabels = safeLabels.map((lbl) => formatEstAxisDateShort(lbl));
    const n = safeValues.length;
    const padLeft = 68;
    const padRight = 22;
    const padTop = 26;
    const prelimPlotW = Math.max(120, cssWidth - padLeft - padRight);
    const prelimStepX = prelimPlotW / Math.max(1, n);
    const maxAxisLabelLen = axisLabels.reduce((m, s) => Math.max(m, String(s || '').length), 0);
    const allAreShortDates = axisLabels.every((s) => /^\d{1,2}\/\d{1,2}$/.test(String(s || '').trim()));

    // Determinar orientación óptima en eje X: horizontal, cruzado (diagonal -42°) o vertical (-90°)
    let labelOrientation = 'horizontal';
    if (options.labelOrientation) {
      labelOrientation = options.labelOrientation;
    } else if (allAreShortDates) {
      if (prelimStepX < 20) {
        labelOrientation = 'vertical';
      } else if (prelimStepX < 44 || n > 10) {
        labelOrientation = 'diagonal';
      }
    } else {
      const estPxNeeded = maxAxisLabelLen * 6.2 + 10;
      if (prelimStepX < 22) {
        labelOrientation = 'vertical';
      } else if (estPxNeeded > prelimStepX || n > 7) {
        labelOrientation = 'diagonal';
      }
    }

    const padBottom =
      labelOrientation === 'vertical'
        ? (allAreShortDates ? 52 : 76)
        : labelOrientation === 'diagonal'
          ? (allAreShortDates ? 50 : 68)
          : 44;

    const plotW = Math.max(120, cssWidth - padLeft - padRight);
    const plotH = Math.max(100, cssHeight - padTop - padBottom);

    const maxVal = Math.max(...safeValues, 1) * 1.12;
    const steps = 4;

    ctx.textBaseline = 'middle';
    for (let s = 0; s <= steps; s++) {
      const ratio = s / steps;
      const y = padTop + plotH - ratio * plotH;
      const gridVal = maxVal * ratio;

      ctx.beginPath();
      ctx.moveTo(padLeft, y);
      ctx.lineTo(padLeft + plotW, y);
      ctx.strokeStyle = gridColor;
      ctx.lineWidth = 1;
      ctx.stroke();

      ctx.fillStyle = mutedColor;
      ctx.font = `600 10px ${fontFamily}`;
      ctx.textAlign = 'right';
      ctx.fillText(fmtVal(gridVal), padLeft - 8, y);
    }

    const stepX = plotW / Math.max(1, n);
    const singleChartColor = '#d97706';
    const singleAvgLineColor = isDark ? '#fbbf24' : '#92400e';
    const avgVal = n > 0 ? totalSum / n : 0;
    const hitItems = [];

    if (chartType === 'bar') {
      const barW = Math.max(6, Math.min(44, stepX * 0.62));
      safeValues.forEach((val, idx) => {
        const h = (val / maxVal) * plotH;
        const x = padLeft + idx * stepX + (stepX - barW) / 2;
        const y = padTop + plotH - h;
        const isHovered = idx === hoverIndex;

        ctx.fillStyle = isHovered ? '#b45309' : singleChartColor;
        ctx.beginPath();
        ctx.roundRect(x, y, barW, Math.max(2, h), [4, 4, 0, 0]);
        ctx.fill();

        if (isHovered) {
          ctx.lineWidth = 2;
          ctx.strokeStyle = isDark ? '#fde68a' : '#78350f';
          ctx.stroke();
        }

        if ((n <= 12 && val > 0) || isHovered) {
          ctx.fillStyle = textColor;
          ctx.font = `700 10px ${fontFamily}`;
          ctx.textAlign = 'center';
          ctx.fillText(fmtVal(val), x + barW / 2, Math.max(12, y - 8));
        }

        const pct = totalSum > 0 ? (val / totalSum) * 100 : 0;
        hitItems.push({
          idx,
          cx: x + barW / 2,
          cy: y,
          xMin: padLeft + idx * stepX,
          xMax: padLeft + (idx + 1) * stepX,
          val,
          pct,
          label: String(fullLabels[idx] || axisLabels[idx] || ''),
          shortLabel: String(axisLabels[idx] || ''),
          extra: extraTooltipLines[idx] || ''
        });
      });
    } else {
      // Línea + área suave (un solo color)
      const pts = safeValues.map((val, idx) => {
        const pct = totalSum > 0 ? (val / totalSum) * 100 : 0;
        const cx = padLeft + idx * stepX + stepX / 2;
        const cy = padTop + plotH - (val / maxVal) * plotH;
        hitItems.push({
          idx,
          cx,
          cy,
          xMin: padLeft + idx * stepX,
          xMax: padLeft + (idx + 1) * stepX,
          val,
          pct,
          label: String(fullLabels[idx] || axisLabels[idx] || ''),
          shortLabel: String(axisLabels[idx] || ''),
          extra: extraTooltipLines[idx] || ''
        });
        return { x: cx, y: cy, val, idx };
      });

      if (pts.length > 1) {
        const grad = ctx.createLinearGradient(0, padTop, 0, padTop + plotH);
        grad.addColorStop(0, 'rgba(217, 119, 6, 0.30)');
        grad.addColorStop(1, 'rgba(217, 119, 6, 0.02)');
        ctx.beginPath();
        ctx.moveTo(pts[0].x, padTop + plotH);
        pts.forEach((p) => ctx.lineTo(p.x, p.y));
        ctx.lineTo(pts[pts.length - 1].x, padTop + plotH);
        ctx.closePath();
        ctx.fillStyle = grad;
        ctx.fill();
      }

      if (hoverIndex >= 0 && pts[hoverIndex]) {
        const hp = pts[hoverIndex];
        ctx.save();
        ctx.setLineDash([3, 3]);
        ctx.beginPath();
        ctx.moveTo(hp.x, padTop);
        ctx.lineTo(hp.x, padTop + plotH);
        ctx.strokeStyle = isDark ? 'rgba(251, 191, 36, 0.55)' : 'rgba(180, 83, 9, 0.45)';
        ctx.lineWidth = 1.3;
        ctx.stroke();
        ctx.restore();
      }

      ctx.beginPath();
      pts.forEach((p, i) => {
        if (i === 0) ctx.moveTo(p.x, p.y);
        else ctx.lineTo(p.x, p.y);
      });
      ctx.strokeStyle = singleChartColor;
      ctx.lineWidth = 2.6;
      ctx.stroke();

      pts.forEach((p) => {
        const isHovered = p.idx === hoverIndex;
        if (isHovered) {
          ctx.beginPath();
          ctx.arc(p.x, p.y, 8, 0, Math.PI * 2);
          ctx.fillStyle = 'rgba(217, 119, 6, 0.24)';
          ctx.fill();
        }
        ctx.beginPath();
        ctx.arc(p.x, p.y, isHovered ? 5.5 : 4, 0, Math.PI * 2);
        ctx.fillStyle = isHovered ? singleChartColor : '#ffffff';
        ctx.fill();
        ctx.lineWidth = isHovered ? 2.5 : 2.2;
        ctx.strokeStyle = isHovered ? '#ffffff' : singleChartColor;
        ctx.stroke();
      });
    }

    // Línea de control de Promedio si hay más de 1 punto (mismo tono monocromático)
    if (n > 1 && options.showAverage !== false) {
      const avgY = padTop + plotH - (avgVal / maxVal) * plotH;
      ctx.save();
      ctx.setLineDash([5, 4]);
      ctx.beginPath();
      ctx.moveTo(padLeft, avgY);
      ctx.lineTo(padLeft + plotW, avgY);
      ctx.strokeStyle = singleAvgLineColor;
      ctx.lineWidth = 1.5;
      ctx.stroke();
      ctx.restore();

      ctx.fillStyle = singleAvgLineColor;
      ctx.font = `700 10px ${fontFamily}`;
      ctx.textAlign = 'right';
      ctx.fillText(`Prom: ${fmtVal(avgVal)}`, padLeft + plotW - 4, Math.max(12, avgY - 7));
    }

    // Etiquetas eje X (con soporte horizontal, cruzado -42° o vertical -90° sin superposición)
    const minPxBetweenLabels = labelOrientation === 'vertical' ? 12 : labelOrientation === 'diagonal' ? 18 : 48;
    const maxLabelsPossible = Math.max(2, Math.floor(plotW / minPxBetweenLabels));
    const skip = n <= maxLabelsPossible ? 1 : Math.max(1, Math.ceil(n / maxLabelsPossible));

    axisLabels.forEach((lbl, idx) => {
      const isLast = idx === n - 1;
      if (idx % skip !== 0 && !isLast) return;
      // Evitar que la última etiqueta se pise con la anterior cuando skip > 1
      if (isLast && skip > 1 && idx % skip !== 0) {
        const prevShownIdx = Math.floor(idx / skip) * skip;
        if ((idx - prevShownIdx) * stepX < minPxBetweenLabels * 0.8) {
          return;
        }
      }

      const x = padLeft + idx * stepX + stepX / 2;
      const raw = String(lbl || '');
      const maxChars = labelOrientation === 'horizontal' ? 12 : 16;
      const short = raw.length > maxChars ? `${raw.slice(0, maxChars - 1)}…` : raw;
      const isHovered = idx === hoverIndex;

      ctx.save();
      ctx.fillStyle = isHovered ? singleChartColor : mutedColor;
      ctx.font = `${isHovered ? '800' : '600'} 10px ${fontFamily}`;

      if (labelOrientation === 'vertical') {
        ctx.translate(x, padTop + plotH + 8);
        ctx.rotate(-Math.PI / 2);
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillText(short, 0, 0);
      } else if (labelOrientation === 'diagonal') {
        ctx.translate(x, padTop + plotH + 10);
        ctx.rotate(-Math.PI / 4.2);
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillText(short, 0, 0);
      } else {
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(short, x, padTop + plotH + 16);
      }
      ctx.restore();
    });

    canvas.__estChartMeta = {
      chartType,
      canvasId,
      labels: safeLabels,
      values: safeValues,
      options: { ...options, _hoverIndex: undefined },
      padLeft,
      padRight,
      padTop,
      padBottom,
      plotW,
      plotH,
      avgVal,
      totalSum,
      hitItems,
      fmtExactVal
    };
    bindEstCanvasHoverEvents(canvas);
  }

  function bindEstCanvasHoverEvents(canvas) {
    if (!canvas || canvas.__estHoverBound) return;
    canvas.__estHoverBound = true;

    canvas.addEventListener('mousemove', (ev) => {
      const meta = canvas.__estChartMeta;
      if (!meta) {
        hideEstChartTooltip();
        return;
      }
      const rect = canvas.getBoundingClientRect();
      const mx = ev.clientX - rect.left;
      const my = ev.clientY - rect.top;

      let foundItem = null;

      if (meta.chartType === 'pie') {
        const dx = mx - meta.centerX;
        const dy = my - meta.centerY;
        const dist = Math.hypot(dx, dy);
        if (dist >= meta.innerRadius * 0.45 && dist <= meta.radius + 8) {
          let ang = Math.atan2(dy, dx);
          if (ang < -Math.PI / 2) ang += Math.PI * 2;
          foundItem = (meta.slicesMeta || []).find((s) => ang >= s.startAngle && ang <= s.endAngle) || null;
        }
        if (!foundItem && Array.isArray(meta.legendRowsMeta)) {
          const hitRow = meta.legendRowsMeta.find(
            (r) => mx >= r.xMin && mx <= r.xMax && my >= r.yMin && my <= r.yMax
          );
          if (hitRow) {
            foundItem = (meta.slicesMeta || [])[hitRow.idx] || null;
          }
        }
      } else {
        if (
          mx >= meta.padLeft - 8 &&
          mx <= meta.padLeft + meta.plotW + 8 &&
          my >= meta.padTop - 12 &&
          my <= meta.padTop + meta.plotH + 24
        ) {
          foundItem =
            (meta.hitItems || []).find((it) => mx >= it.xMin && mx <= it.xMax) || null;
        }
      }

      if (!foundItem) {
        canvas.style.cursor = 'default';
        if (typeof canvas.__lastHoverIdx === 'number' && canvas.__lastHoverIdx !== -1) {
          canvas.__lastHoverIdx = -1;
          drawEstControlChart(meta.canvasId, meta.chartType, meta.labels, meta.values, meta.options);
        }
        hideEstChartTooltip();
        return;
      }

      canvas.style.cursor = 'pointer';
      if (canvas.__lastHoverIdx !== foundItem.idx) {
        canvas.__lastHoverIdx = foundItem.idx;
        drawEstControlChart(meta.canvasId, meta.chartType, meta.labels, meta.values, {
          ...meta.options,
          _hoverIndex: foundItem.idx
        });
      }

      const tip = getOrCreateEstChartTooltip();
      const valStr = meta.fmtExactVal(foundItem.val);
      const pctStr = `${Number(foundItem.pct || 0).toLocaleString('es-AR', {
        minimumFractionDigits: 1,
        maximumFractionDigits: 1
      })}% del total`;
      const extraHtml = foundItem.extra
        ? `<div style="color:#cbd5e1; font-size:11px; margin-top:2px;">${escapeHtml(foundItem.extra)}</div>`
        : '';

      tip.innerHTML = `
        <div style="font-weight:800; color:#fbbf24; margin-bottom:2px;">${escapeHtml(foundItem.label)}</div>
        <div style="font-weight:700; color:#ffffff;">${escapeHtml(valStr)} <span style="color:#94a3b8; font-weight:600;">(${escapeHtml(pctStr)})</span></div>
        ${extraHtml}
      `;
      tip.hidden = false;
      tip.style.opacity = '1';

      const tipRect = tip.getBoundingClientRect();
      let left = ev.clientX + 14;
      let top = ev.clientY - (tipRect.height || 54) - 12;
      if (left + (tipRect.width || 180) > window.innerWidth - 12) {
        left = ev.clientX - (tipRect.width || 180) - 14;
      }
      if (top < 10) {
        top = ev.clientY + 16;
      }
      tip.style.left = `${Math.max(8, Math.round(left))}px`;
      tip.style.top = `${Math.max(8, Math.round(top))}px`;
    });

    canvas.addEventListener('mouseleave', () => {
      canvas.style.cursor = 'default';
      const meta = canvas.__estChartMeta;
      if (meta && typeof canvas.__lastHoverIdx === 'number' && canvas.__lastHoverIdx !== -1) {
        canvas.__lastHoverIdx = -1;
        drawEstControlChart(meta.canvasId, meta.chartType, meta.labels, meta.values, meta.options);
      }
      hideEstChartTooltip();
    });
  }

  // =========================================================================
  // RENDERIZADO DE SUBMÓDULO 1: FACTURACIÓN, PROMEDIO DIARIO Y PROYECCIÓN MENSUAL
  // =========================================================================
  function renderEstFacturacionSubmodule() {
    const records = getFilteredEstRecords();
    const agrupar = document.getElementById('est-fact-group-by')?.value || 'dia';

    const totalFacturado = round2(records.reduce((acc, r) => acc + r.importe, 0));
    const uniqueDays = new Set(records.map((r) => r.fechaIso));
    const daysCount = Math.max(1, uniqueDays.size);
    const promDiario = round2(totalFacturado / daysCount);

    // Proyección del mes en curso basada en el promedio diario del mes en curso (para los PVs seleccionados)
    const now = new Date();
    const curYear = now.getFullYear();
    const curMonth = now.getMonth() + 1;
    const curYm = `${curYear}-${String(curMonth).padStart(2, '0')}`;
    const totalDaysInCurMonth = new Date(curYear, curMonth, 0).getDate();

    const selectedPvs = new Set(getSelectedEstPVs());
    const curMonthRecs = getEstadisticasDataset().filter((r) => r.ym === curYm && selectedPvs.has(r.pv));
    const curMonthTotal = round2(curMonthRecs.reduce((acc, r) => acc + r.importe, 0));
    const curMonthActiveDays = Math.max(1, new Set(curMonthRecs.map((r) => r.fechaIso)).size);
    const curMonthDailyAvg = curMonthRecs.length > 0 ? round2(curMonthTotal / curMonthActiveDays) : promDiario;
    const proyeccionMesCurso = round2(curMonthDailyAvg * totalDaysInCurMonth);

    // Totales por Punto de Venta
    const pvMap = {};
    EST_ALL_PVS.forEach((pv) => {
      pvMap[pv] = { pv, total: 0, comps: 0, days: new Set() };
    });
    const totalComps = records.reduce((acc, r) => acc + (Number(r.tickets) || 1), 0);
    records.forEach((r) => {
      const tk = Number(r.tickets) || 1;
      if (!pvMap[r.pv]) pvMap[r.pv] = { pv: r.pv, total: 0, comps: 0, days: new Set() };
      pvMap[r.pv].total = round2(pvMap[r.pv].total + r.importe);
      pvMap[r.pv].comps += tk;
      pvMap[r.pv].days.add(r.fechaIso);
    });

    const pvRows = Object.values(pvMap)
      .filter((p) => selectedPvs.has(p.pv))
      .sort((a, b) => b.total - a.total);

    // Actualizar KPIs
    const kpiTotalEl = document.getElementById('est-kpi-fact-total');
    const kpiCompsEl = document.getElementById('est-kpi-fact-comps');
    const kpiPromEl = document.getElementById('est-kpi-fact-prom-diario');
    const kpiDiasEl = document.getElementById('est-kpi-fact-dias-sub');
    const kpiMesActualEl = document.getElementById('est-kpi-fact-mes-actual');
    const kpiMesActualSubEl = document.getElementById('est-kpi-fact-mes-actual-sub');
    const kpiProyEl = document.getElementById('est-kpi-fact-proyeccion');
    const kpiProyDetEl = document.getElementById('est-kpi-fact-proyeccion-sub');

    if (kpiTotalEl) kpiTotalEl.textContent = `$ ${formatArs(totalFacturado)}`;
    if (kpiCompsEl) kpiCompsEl.textContent = `${totalComps.toLocaleString('es-AR')} comprobantes registrados`;
    if (kpiPromEl) kpiPromEl.textContent = `$ ${formatArs(promDiario)}`;
    if (kpiDiasEl) kpiDiasEl.textContent = `Sobre ${daysCount} día(s) con actividad`;
    if (kpiMesActualEl) kpiMesActualEl.textContent = `$ ${formatArs(curMonthTotal)}`;
    if (kpiMesActualSubEl) {
      kpiMesActualSubEl.textContent = `Promedio diario mes actual: $ ${formatArs(curMonthDailyAvg)}`;
    }
    if (kpiProyEl) kpiProyEl.textContent = `$ ${formatArs(proyeccionMesCurso)}`;
    if (kpiProyDetEl) {
      kpiProyDetEl.textContent = `$ ${formatArs(curMonthDailyAvg)}/día × ${totalDaysInCurMonth} días (${curYm})`;
    }

    // Agrupación para gráfico principal y tabla inferior
    const groupMap = {};
    records.forEach((r) => {
      let key = r.fechaIso;
      let label = r.fechaIso.split('-').reverse().join('/');
      if (agrupar === 'mes') {
        key = r.ym;
        label = r.ym;
      }
      if (!groupMap[key]) {
        groupMap[key] = { key, label, comps: 0, total: 0, days: new Set(), pvs: new Set() };
      }
      groupMap[key].comps += Number(r.tickets) || 1;
      groupMap[key].total = round2(groupMap[key].total + r.importe);
      groupMap[key].days.add(r.fechaIso);
      groupMap[key].pvs.add(r.pv);
    });

    const groupedRows = Object.values(groupMap).sort((a, b) => a.key.localeCompare(b.key));
    const chartLabels = groupedRows.map((g) => formatEstAxisDateShort(g.label));
    const chartValues = groupedRows.map((g) => g.total);

    drawEstControlChart('canvas-est-fact-evolucion', EST_STATE.chartTypeFact, chartLabels, chartValues, {
      isCurrency: true,
      multiColor: EST_STATE.chartTypeFact !== 'line',
      showAverage: true,
      fullLabels: groupedRows.map((g) => g.label),
      extraTooltipLines: groupedRows.map((g) => `${g.comps.toLocaleString('es-AR')} comprobante(s)`)
    });

    // Gráfico secundario por Punto de Venta
    drawEstControlChart(
      'canvas-est-fact-pv',
      EST_STATE.chartTypeFactPv,
      pvRows.map((p) => `PV ${p.pv}`),
      pvRows.map((p) => p.total),
      { isCurrency: true, multiColor: true, showAverage: false }
    );

    // Tabla por Punto de Venta
    const pvTbody = document.getElementById('est-fact-pv-tbody');
    if (pvTbody) {
      pvTbody.innerHTML = pvRows
        .map((p) => {
          const dCount = Math.max(1, p.days.size);
          const avgPvDay = round2(p.total / dCount);
          const proyPvMes = round2(avgPvDay * totalDaysInCurMonth);
          const pct = totalFacturado > 0 ? ((p.total / totalFacturado) * 100).toFixed(1) : '0.0';
          return `
            <tr>
              <td><span class="badge badge--gold">${escapeHtml(EST_PV_LABELS[p.pv] || `PV ${p.pv}`)}</span></td>
              <td class="text-right">${p.comps.toLocaleString('es-AR')}</td>
              <td class="text-right"><strong>$ ${formatArs(p.total)}</strong></td>
              <td class="text-right">$ ${formatArs(avgPvDay)}</td>
              <td class="text-right" style="color: var(--gold-light); font-weight: 700;">$ ${formatArs(proyPvMes)}</td>
              <td class="text-right">${pct}%</td>
            </tr>
          `;
        })
        .join('');
    }

    // Tabla de desglose por período (Día / Mes Calendario)
    const detTbody = document.getElementById('est-fact-periodo-tbody');
    if (detTbody) {
      const displayRows = [...groupedRows].reverse();
      detTbody.innerHTML = displayRows
        .map((g) => {
          const ticketProm = g.comps > 0 ? round2(g.total / g.comps) : 0;
          const dCount = Math.max(1, g.days.size);
          const promDia = round2(g.total / dCount);
          return `
            <tr>
              <td><strong>${escapeHtml(g.label)}</strong></td>
              <td class="text-right">${g.comps.toLocaleString('es-AR')}</td>
              <td class="text-right"><strong>$ ${formatArs(g.total)}</strong></td>
              <td class="text-right">$ ${formatArs(promDia)}</td>
              <td class="text-right">$ ${formatArs(ticketProm)}</td>
            </tr>
          `;
        })
        .join('');
    }
  }

  // =========================================================================
  // RENDERIZADO DE SUBMÓDULO 2: RANKING DE PRODUCTOS MÁS VENDIDOS
  // =========================================================================
  function renderEstRankingSubmodule() {
    populateEstSelectFilters();
    const records = getFilteredEstRecords();
    const criterio = document.getElementById('est-rank-orden')?.value || 'unidades';
    const rubroFilter = document.getElementById('est-rank-rubro')?.value || '0';
    const provFilter = document.getElementById('est-rank-proveedor')?.value || '0';
    const marcaFilter = document.getElementById('est-rank-marca')?.value || '0';
    const limit = Number(document.getElementById('est-rank-limit')?.value) || 50;
    const q = normalizeStr(document.getElementById('est-rank-q')?.value || '');

    const artById = {};
    (STATE.articulos || []).forEach((a) => {
      artById[a.id] = a;
    });

    const activeDaysCount = Math.max(1, new Set(records.map((r) => r.fechaIso)).size);
    const prodMap = {};
    const realItems = getFilteredRealProductSalesItems(artById);
    realItems.forEach((it) => {
      const artObj = artById[it.artId] || it;
      if (isGenericStatisticArticle(it, artById) || isGenericStatisticArticle(artObj, artById)) return;
      const pInfo = getArticleProviderInfo(artObj);
      if (rubroFilter && rubroFilter !== '0' && String(it.rId) !== String(rubroFilter)) return;
      if (provFilter && provFilter !== '0' && String(pInfo.id) !== String(provFilter)) return;
      if (marcaFilter && marcaFilter !== '0' && String(it.mId) !== String(marcaFilter)) return;
      if (q) {
        const hay = normalizeStr(`${it.c} ${it.n} ${pInfo.nombre}`);
        if (!hay.includes(q)) return;
      }

      const key = String(it.artId || it.c);
      if (!prodMap[key]) {
        prodMap[key] = {
          key,
          artId: it.artId,
          c: it.c || String(it.artId),
          n: it.n || 'ARTÍCULO',
          rId: it.rId,
          mId: it.mId,
          pId: pInfo.id,
          provName: pInfo.nombre,
          unidades: 0,
          facturado: 0,
          costo: 0,
          ganancia: 0
        };
      }
      prodMap[key].unidades = round2(prodMap[key].unidades + (Number(it.qty) || 0));
      prodMap[key].facturado = round2(prodMap[key].facturado + (Number(it.subtotal) || 0));
      prodMap[key].costo = round2(prodMap[key].costo + (Number(it.costoTotal) || 0));
      prodMap[key].ganancia = round2(prodMap[key].facturado - prodMap[key].costo);
    });

    const allProducts = Object.values(prodMap);
    allProducts.sort((a, b) => {
      if (criterio === 'importe') return b.facturado - a.facturado;
      if (criterio === 'ganancia') return b.ganancia - a.ganancia;
      return b.unidades - a.unidades;
    });

    const excludedSet = EST_STATE.excludedRankProductKeys || new Set();
    const activeProducts = allProducts.filter((p) => !excludedSet.has(p.key));
    const totalUnidades = round2(activeProducts.reduce((acc, p) => acc + p.unidades, 0));
    const totalFacturado = round2(activeProducts.reduce((acc, p) => acc + p.facturado, 0));
    const topRows = allProducts.slice(0, limit);
    EST_STATE.lastTopRankKeys = topRows.map((p) => p.key);

    const excludedInFilterCount = allProducts.length - activeProducts.length;
    const resetExclBtn = document.getElementById('btn-est-rank-reset-excluded');
    if (resetExclBtn) {
      resetExclBtn.hidden = excludedSet.size === 0;
      if (excludedSet.size > 0) {
        resetExclBtn.textContent = `↺ Volver a incluir todos (${excludedSet.size} destildado${excludedSet.size === 1 ? '' : 's'})`;
      }
    }

    const chkAllEl = document.getElementById('est-rank-check-all');
    if (chkAllEl) {
      const checkedTopCount = topRows.filter((p) => !excludedSet.has(p.key)).length;
      chkAllEl.checked = topRows.length > 0 && checkedTopCount === topRows.length;
      chkAllEl.indeterminate = checkedTopCount > 0 && checkedTopCount < topRows.length;
    }

    const subEl = document.getElementById('est-rank-chart-subtitle');
    if (subEl) {
      const exclNote = excludedInFilterCount > 0 ? ` · ${excludedInFilterCount} excluido(s)` : '';
      subEl.textContent = `Top 12 productos activos · Total activo: ${totalUnidades.toLocaleString('es-AR')} unid. ($ ${formatArs(totalFacturado)})${exclNote}`;
    }

    // Gráfico Top 12 (se rearma dinámicamente sólo con los productos tildados)
    const chartSlice = activeProducts.slice(0, 12);
    const chartLabels = chartSlice.map((p) => p.n);
    const chartValues = chartSlice.map((p) => {
      if (criterio === 'importe') return p.facturado;
      if (criterio === 'ganancia') return p.ganancia;
      return p.unidades;
    });

    drawEstControlChart('canvas-est-ranking', EST_STATE.chartTypeRanking, chartLabels, chartValues, {
      isCurrency: criterio !== 'unidades',
      multiColor: true,
      showAverage: true,
      fullLabels: chartSlice.map((p) => p.n),
      extraTooltipLines: chartSlice.map(
        (p) => `Facturado: $ ${formatArs(p.facturado)} · Ganancia: $ ${formatArs(p.ganancia)}`
      )
    });

    // Tabla Ranking
    const tbody = document.getElementById('est-ranking-tbody');
    if (tbody) {
      let activePos = 0;
      tbody.innerHTML = topRows
        .map((p) => {
          const isExcluded = excludedSet.has(p.key);
          if (!isExcluded) activePos += 1;
          const rubroName = getEstRubroName(p.rId);
          const marcaName = getEstMarcaName(p.mId);
          const promDiarioUnid = round2(p.unidades / activeDaysCount);
          const partPct = !isExcluded && totalFacturado > 0 ? `${((p.facturado / totalFacturado) * 100).toFixed(1)}%` : '—';
          const badgeHtml = isExcluded
            ? `<span class="badge" style="background:#e2e8f0; color:#64748b;">Excl.</span>`
            : `<span class="badge ${activePos <= 3 ? 'badge--green' : 'badge--gold'}">#${activePos}</span>`;
          return `
            <tr style="${isExcluded ? 'opacity:0.48;' : ''}">
              <td style="text-align:center;">
                <input
                  type="checkbox"
                  class="est-rank-row-chk"
                  data-rank-key="${escapeHtml(p.key)}"
                  ${isExcluded ? '' : 'checked'}
                  title="Destildar para excluir del gráfico o tildar para volver a incluir"
                  style="width:16px; height:16px; cursor:pointer; accent-color:#16a34a;"
                />
              </td>
              <td>${badgeHtml}</td>
              <td><strong>${escapeHtml(p.n)}</strong></td>
              <td><div class="price-cell-stack"><span>${escapeHtml(rubroName)}</span><span class="price-neto-val">${escapeHtml(marcaName)}</span></div></td>
              <td class="text-right"><strong>${p.unidades.toLocaleString('es-AR')}</strong></td>
              <td class="text-right">${promDiarioUnid.toLocaleString('es-AR')} / día</td>
              <td class="text-right"><strong>$ ${formatArs(p.facturado)}</strong></td>
              <td class="text-right">$ ${formatArs(p.costo)}</td>
              <td class="text-right" style="color: var(--success); font-weight: 700;">$ ${formatArs(p.ganancia)}</td>
              <td class="text-right">${partPct}</td>
            </tr>
          `;
        })
        .join('');
    }
  }

  // =========================================================================
  // RENDERIZADO DE SUBMÓDULO 3: IMPORTES POR TIPO DE FACTURACIÓN / MEDIOS DE PAGO
  // =========================================================================
  function renderEstMediosSubmodule() {
    const records = getFilteredEstRecords();
    const activeDaysCount = Math.max(1, new Set(records.map((r) => r.fechaIso)).size);
    const mediosMap = {};
    EST_MEDIOS_LIST.forEach((m) => {
      mediosMap[m] = { medio: m, comps: 0, total: 0 };
    });

    records.forEach((r) => {
      const m = EST_MEDIOS_LIST.includes(r.medioPago) ? r.medioPago : 'Efectivo';
      mediosMap[m].comps += Number(r.tickets) || 1;
      mediosMap[m].total = round2(mediosMap[m].total + r.importe);
    });

    const totalGral = round2(records.reduce((acc, r) => acc + r.importe, 0));
    const pctStr = (val) => (totalGral > 0 ? `${((val / totalGral) * 100).toFixed(1)}% del total` : '0.0% del total');

    const setMedioKpi = (idVal, idPct, mObj) => {
      const elV = document.getElementById(idVal);
      const elP = document.getElementById(idPct);
      if (elV) elV.textContent = `$ ${formatArs(mObj.total)}`;
      if (elP) elP.textContent = `${pctStr(mObj.total)} (${mObj.comps} op.)`;
    };

    setMedioKpi('est-kpi-mp-efectivo', 'est-kpi-mp-efectivo-sub', mediosMap['Efectivo']);
    setMedioKpi('est-kpi-mp-debito', 'est-kpi-mp-debito-sub', mediosMap['Débito']);
    setMedioKpi('est-kpi-mp-credito', 'est-kpi-mp-credito-sub', mediosMap['Crédito']);
    setMedioKpi('est-kpi-mp-qr', 'est-kpi-mp-qr-sub', mediosMap['QR']);
    setMedioKpi('est-kpi-mp-ctacte', 'est-kpi-mp-ctacte-sub', mediosMap['Cuenta Corriente']);

    const rows = Object.values(mediosMap).sort((a, b) => b.total - a.total);
    drawEstControlChart(
      'canvas-est-medios',
      EST_STATE.chartTypeMedios,
      rows.map((r) => r.medio),
      rows.map((r) => r.total),
      { isCurrency: true, multiColor: true, showAverage: false }
    );

    const tbody = document.getElementById('est-medios-tbody');
    if (tbody) {
      tbody.innerHTML = rows
        .map((r) => {
          const promDiario = round2(r.total / activeDaysCount);
          const ticketProm = r.comps > 0 ? round2(r.total / r.comps) : 0;
          const pct = totalGral > 0 ? ((r.total / totalGral) * 100).toFixed(1) : '0.0';
          return `
            <tr>
              <td><strong>${escapeHtml(r.medio)}</strong></td>
              <td class="text-right">${r.comps.toLocaleString('es-AR')}</td>
              <td class="text-right"><strong>$ ${formatArs(r.total)}</strong></td>
              <td class="text-right">$ ${formatArs(promDiario)}</td>
              <td class="text-right">$ ${formatArs(ticketProm)}</td>
              <td class="text-right"><span class="badge badge--gold">${pct}%</span></td>
            </tr>
          `;
        })
        .join('');
    }
  }

  // =========================================================================
  // RENDERIZADO DE SUBMÓDULO 4: MARGEN DE GANANCIA (COMPRA VS VENTA POR RUBRO, MARCA O PROVEEDOR)
  // =========================================================================
  function renderEstMargenesSubmodule() {
    populateEstSelectFilters();
    const records = getFilteredEstRecords();
    const dim = document.getElementById('est-margen-group-by')?.value || 'rubro';
    const rubroFilter = document.getElementById('est-margen-rubro')?.value || '0';
    const provFilter = document.getElementById('est-margen-proveedor')?.value || '0';
    const marcaFilter = document.getElementById('est-margen-marca')?.value || '0';
    const fuente = document.getElementById('est-margen-base')?.value || 'ventas';
    const q = normalizeStr(document.getElementById('est-margen-q')?.value || '');

    const groups = {};
    const artById = {};
    (STATE.articulos || []).forEach((a) => {
      artById[a.id] = a;
    });

    // Si se filtra específicamente la misma dimensión en la que estamos agrupando (ej. eligió un Rubro puntual estando en "Por Rubro"),
    // desglosar por los Artículos de ese Rubro/Proveedor/Marca para mostrar todo el listado detallado
    const isSingleSameDimSelected =
      (dim === 'rubro' && rubroFilter !== '0') ||
      (dim === 'proveedor' && provFilter !== '0') ||
      (dim === 'marca' && marcaFilter !== '0');

    const getGroupKeyAndName = (rId, mId, pInfo, artObj) => {
      if (isSingleSameDimSelected) {
        const code = artObj?.c || artObj?.id || '';
        const name = `${artObj?.n || 'ARTÍCULO'} (#${code})`;
        return { key: `A_${artObj?.id || code}`, name };
      }
      if (dim === 'marca') {
        const name = getEstMarcaName(mId);
        return { key: `M_${mId}`, name };
      }
      if (dim === 'proveedor') {
        return { key: `P_${pInfo.id}`, name: pInfo.nombre };
      }
      const name = getEstRubroName(rId);
      return { key: `R_${rId}`, name };
    };

    const matchesEntityFilters = (rId, mId, pId) => {
      if (rubroFilter && rubroFilter !== '0' && String(rId) !== String(rubroFilter)) return false;
      if (provFilter && provFilter !== '0' && String(pId) !== String(provFilter)) return false;
      if (marcaFilter && marcaFilter !== '0' && String(mId) !== String(marcaFilter)) return false;
      return true;
    };

    if (fuente === 'padron_minorista' || fuente === 'padron_mayorista') {
      (STATE.articulos || []).forEach((art) => {
        if (Number(art.bl) === 1) return;
        const venta = fuente === 'padron_mayorista' ? (Number(art.p2f) || Number(art.p1f) || 0) : (Number(art.p1f) || 0);
        if (venta <= 0) return;
        const costo = Number(art.cfn) > 0 && Number(art.cfn) < venta ? Number(art.cfn) : round2(venta * 0.7);
        const rId = Number(art.r ?? art.rId) || 0;
        const mId = Number(art.mk ?? art.mId) || 0;
        const pInfo = getArticleProviderInfo(art);
        if (!matchesEntityFilters(rId, mId, pInfo.id)) return;

        const { key, name } = getGroupKeyAndName(rId, mId, pInfo, art);
        if (!groups[key]) {
          groups[key] = { key, name, artsSet: new Set(), unidades: 0, costoTotal: 0, ventaTotal: 0 };
        }
        groups[key].artsSet.add(art.id);
        groups[key].unidades += 1;
        groups[key].costoTotal = round2(groups[key].costoTotal + costo);
        groups[key].ventaTotal = round2(groups[key].ventaTotal + venta);
      });
    } else {
      const realItems = getFilteredRealProductSalesItems(artById);
      realItems.forEach((it) => {
        const artObj = artById[it.artId] || it;
        const rId = Number(it.rId ?? artObj?.r) || 0;
        const mId = Number(it.mId ?? artObj?.mk) || 0;
        const pInfo = getArticleProviderInfo(artObj);
        if (!matchesEntityFilters(rId, mId, pInfo.id)) return;

        const { key, name } = getGroupKeyAndName(rId, mId, pInfo, artObj);
        if (!groups[key]) {
          groups[key] = { key, name, artsSet: new Set(), unidades: 0, costoTotal: 0, ventaTotal: 0 };
        }
        groups[key].artsSet.add(it.artId || it.c);
        groups[key].unidades = round2(groups[key].unidades + (Number(it.qty) || 0));
        groups[key].costoTotal = round2(groups[key].costoTotal + (Number(it.costoTotal) || 0));
        groups[key].ventaTotal = round2(groups[key].ventaTotal + (Number(it.subtotal) || 0));
      });
    }

    let rows = Object.values(groups).map((g) => {
      const ganancia = round2(g.ventaTotal - g.costoTotal);
      const markupPct = g.costoTotal > 0 ? ((ganancia / g.costoTotal) * 100) : 0;
      const margenVentaPct = g.ventaTotal > 0 ? ((ganancia / g.ventaTotal) * 100) : 0;
      return {
        ...g,
        artsCount: g.artsSet.size,
        ganancia,
        markupPct,
        margenVentaPct
      };
    });

    if (q) {
      rows = rows.filter((r) => normalizeStr(r.name).includes(q));
    }
    rows.sort((a, b) => b.ganancia - a.ganancia);

    const totalCosto = round2(rows.reduce((acc, r) => acc + r.costoTotal, 0));
    const totalVenta = round2(rows.reduce((acc, r) => acc + r.ventaTotal, 0));
    const totalGanancia = round2(totalVenta - totalCosto);
    const globalMargenVenta = totalVenta > 0 ? ((totalGanancia / totalVenta) * 100).toFixed(1) : '0.0';
    const globalMarkup = totalCosto > 0 ? ((totalGanancia / totalCosto) * 100).toFixed(1) : '0.0';

    // Actualizar KPIs
    const elCosto = document.getElementById('est-kpi-mg-costo');
    const elItemsSub = document.getElementById('est-kpi-mg-items-sub');
    const elVenta = document.getElementById('est-kpi-mg-venta');
    const elGanancia = document.getElementById('est-kpi-mg-ganancia');
    const elPct = document.getElementById('est-kpi-mg-pct');
    const elMarkup = document.getElementById('est-kpi-mg-pct-sub');
    const elColHeader = document.getElementById('est-margen-col-title');

    if (elCosto) elCosto.textContent = `$ ${formatArs(totalCosto)}`;
    if (elItemsSub) elItemsSub.textContent = `${rows.length} agrupaciones analizadas`;
    if (elVenta) elVenta.textContent = `$ ${formatArs(totalVenta)}`;
    if (elGanancia) elGanancia.textContent = `$ ${formatArs(totalGanancia)}`;
    if (elPct) elPct.textContent = `${globalMargenVenta}%`;
    if (elMarkup) elMarkup.textContent = `Markup s/Compra: +${globalMarkup}% · Margen s/Venta: ${globalMargenVenta}%`;
    if (elColHeader) {
      if (isSingleSameDimSelected) {
        elColHeader.textContent = 'Artículo (Detalle de la Selección)';
      } else {
        elColHeader.textContent = dim === 'marca' ? 'Marca' : dim === 'proveedor' ? 'Proveedor' : 'Rubro';
      }
    }

    const topChartRows = rows.slice(0, 10);
    const margenExtraTooltip = topChartRows.map(
      (r) => `Margen s/Venta: ${r.margenVentaPct.toFixed(1)}% · Markup: +${r.markupPct.toFixed(1)}%`
    );
    drawEstControlChart(
      'canvas-est-margen-bar',
      EST_STATE.chartTypeMargenBar,
      topChartRows.map((r) => r.name.slice(0, 15)),
      topChartRows.map((r) => r.ganancia),
      {
        isCurrency: true,
        multiColor: true,
        showAverage: true,
        fullLabels: topChartRows.map((r) => r.name),
        extraTooltipLines: margenExtraTooltip
      }
    );

    drawEstControlChart(
      'canvas-est-margen-pie',
      EST_STATE.chartTypeMargenPie,
      topChartRows.map((r) => r.name),
      topChartRows.map((r) => r.ganancia),
      {
        isCurrency: true,
        multiColor: true,
        showAverage: false,
        fullLabels: topChartRows.map((r) => r.name),
        extraTooltipLines: margenExtraTooltip
      }
    );

    const tbody = document.getElementById('est-margenes-tbody');
    if (tbody) {
      tbody.innerHTML = rows
        .slice(0, 80)
        .map((r) => {
          const partGan = totalGanancia > 0 ? ((r.ganancia / totalGanancia) * 100).toFixed(1) : '0.0';
          return `
            <tr>
              <td><strong>${escapeHtml(r.name)}</strong></td>
              <td class="text-right">${r.artsCount.toLocaleString('es-AR')} art. (${r.unidades.toLocaleString('es-AR')} u.)</td>
              <td class="text-right">$ ${formatArs(r.costoTotal)}</td>
              <td class="text-right"><strong>$ ${formatArs(r.ventaTotal)}</strong></td>
              <td class="text-right" style="color: var(--success); font-weight: 700;">$ ${formatArs(r.ganancia)}</td>
              <td class="text-right"><span class="badge badge--gold">+${r.markupPct.toFixed(1)}%</span></td>
              <td class="text-right"><span class="badge badge--green">${r.margenVentaPct.toFixed(1)}%</span></td>
              <td class="text-right">${partGan}%</td>
            </tr>
          `;
        })
        .join('');
    }
  }

  // =========================================================================
  // RENDERIZADO DE SUBMÓDULO 5: GANANCIA BRUTA (POR DÍA, SEMANA, MES Y RANGO DE HORAS DE 1 EN 1 HORA)
  // =========================================================================
  const SUPERMARKET_HOURLY_WEIGHTS = {
    8: 0.05,
    9: 0.08,
    10: 0.11,
    11: 0.13,
    12: 0.12,
    13: 0.06,
    16: 0.05,
    17: 0.08,
    18: 0.11,
    19: 0.11,
    20: 0.07,
    21: 0.03
  };

  function getIsoWeekKeyAndLabel(fechaIso) {
    const parts = String(fechaIso || '').split('-').map(Number);
    if (parts.length !== 3 || !parts[0]) return { key: fechaIso, label: fechaIso };
    const dt = new Date(parts[0], parts[1] - 1, parts[2]);
    const dayOfWeek = (dt.getDay() + 6) % 7; // Lunes = 0 .. Domingo = 6
    const monday = new Date(dt);
    monday.setDate(dt.getDate() - dayOfWeek);
    const sunday = new Date(monday);
    sunday.setDate(monday.getDate() + 6);
    const monIso = `${monday.getFullYear()}-${String(monday.getMonth() + 1).padStart(2, '0')}-${String(monday.getDate()).padStart(2, '0')}`;
    const fmtShort = (d) => `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}`;
    return {
      key: `SEM_${monIso}`,
      sortKey: monIso,
      label: `Sem. ${fmtShort(monday)} al ${fmtShort(sunday)}/${sunday.getFullYear()}`,
      shortLabel: `${fmtShort(monday)}-${fmtShort(sunday)}`
    };
  }

  function collectTimestampedVouchersByDateAndPv() {
    const map = new Map();
    const seen = new Set();
    const addOp = (op) => {
      if (!op) return;
      const cls = classifyLivePosOperationForStats(op);
      if (!cls.include) return;
      const fh = String(op.fechaHora || '').trim();
      const hmMatch = fh.match(/(\d{1,2}):(\d{2})/);
      if (!hmMatch) return;
      const hour = Math.min(23, Math.max(0, parseInt(hmMatch[1], 10)));
      let fIso = String(op.fechaIso || '').trim();
      if (!fIso) {
        const dm = fh.match(/(\d{2})\/(\d{2})\/(\d{4})/);
        if (dm) fIso = `${dm[3]}-${dm[2]}-${dm[1]}`;
      }
      if (!fIso) return;
      const uniqueKey = op.uid || `${cls.pv}-${op.nro || ''}-${fIso}-${fh}`;
      if (seen.has(uniqueKey)) return;
      seen.add(uniqueKey);

      const rawImp = Math.abs(round2(op.importe || 0));
      if (rawImp <= 0) return;
      const items = Array.isArray(op.items) ? op.items : [];
      const rawCosto = items.length > 0
        ? Math.abs(round2(items.reduce((acc, it) => acc + (Number(it.costoTotal) || 0), 0)))
        : round2(rawImp * 0.72);
      const importe = round2(rawImp * cls.dh);
      const costoTotal = round2(rawCosto * cls.dh);
      const bucketKey = `${fIso}|${cls.pv}`;
      if (!map.has(bucketKey)) map.set(bucketKey, []);
      map.get(bucketKey).push({
        fechaIso: fIso,
        ym: fIso.slice(0, 7),
        pv: cls.pv,
        hour,
        tickets: 1,
        importe,
        costoTotal
      });
    };

    Object.keys(STATE.ventasDb?.comprobantesPorCaja || {}).forEach((cid) => {
      (STATE.ventasDb.comprobantesPorCaja[cid] || []).forEach(addOp);
    });
    Object.keys(STATE.turnosCajas || {}).forEach((cid) => {
      (STATE.turnosCajas[cid] || []).forEach(addOp);
    });
    return map;
  }

  function renderEstGananciaBrutaSubmodule() {
    const records = getFilteredEstRecords();
    const groupBy = document.getElementById('est-gb-group-by')?.value || 'dia';
    let horaDesde = parseInt(document.getElementById('est-gb-hora-desde')?.value ?? '0', 10);
    let horaHasta = parseInt(document.getElementById('est-gb-hora-hasta')?.value ?? '23', 10);
    if (!isFinite(horaDesde)) horaDesde = 0;
    if (!isFinite(horaHasta)) horaHasta = 23;
    if (horaDesde > horaHasta) {
      const tmp = horaDesde;
      horaDesde = horaHasta;
      horaHasta = tmp;
    }
    const isFullDayHours = horaDesde === 0 && horaHasta === 23;

    // Expandir registros con soporte horario de 1 en 1 hora
    const tsMap = collectTimestampedVouchersByDateAndPv();
    const byDatePv = new Map();
    records.forEach((r) => {
      const k = `${r.fechaIso}|${r.pv}`;
      if (!byDatePv.has(k)) {
        byDatePv.set(k, { fechaIso: r.fechaIso, ym: r.ym, pv: r.pv, tickets: 0, importe: 0, costoTotal: 0 });
      }
      const agg = byDatePv.get(k);
      agg.tickets += Number(r.tickets) || 1;
      agg.importe = round2(agg.importe + r.importe);
      agg.costoTotal = round2(agg.costoTotal + r.costoTotal);
    });

    const hourlySlices = [];
    byDatePv.forEach((agg, k) => {
      if (isFullDayHours && groupBy !== 'hora') {
        hourlySlices.push({
          fechaIso: agg.fechaIso,
          ym: agg.ym,
          pv: agg.pv,
          hour: 12,
          tickets: agg.tickets,
          importe: agg.importe,
          costoTotal: agg.costoTotal
        });
        return;
      }

      const exactOps = tsMap.get(k) || [];
      let exactImp = 0;
      let exactCosto = 0;
      let exactTickets = 0;
      exactOps.forEach((op) => {
        exactImp = round2(exactImp + op.importe);
        exactCosto = round2(exactCosto + op.costoTotal);
        exactTickets += op.tickets;
        if (op.hour >= horaDesde && op.hour <= horaHasta) {
          hourlySlices.push(op);
        }
      });

      const remImp = round2(agg.importe - exactImp);
      const remCosto = round2(agg.costoTotal - exactCosto);
      const remTickets = Math.max(0, agg.tickets - exactTickets);
      if (Math.abs(remImp) > 0.01) {
        Object.keys(SUPERMARKET_HOURLY_WEIGHTS).forEach((hStr) => {
          const h = Number(hStr);
          if (h < horaDesde || h > horaHasta) return;
          const w = SUPERMARKET_HOURLY_WEIGHTS[h] || 0;
          hourlySlices.push({
            fechaIso: agg.fechaIso,
            ym: agg.ym,
            pv: agg.pv,
            hour: h,
            tickets: Math.max(0, Math.round(remTickets * w)),
            importe: round2(remImp * w),
            costoTotal: round2(remCosto * w)
          });
        });
      }
    });

    const buckets = {};
    if (groupBy === 'hora') {
      for (let h = horaDesde; h <= horaHasta; h++) {
        const h1 = String(h).padStart(2, '0');
        const h2 = String((h + 1) % 24).padStart(2, '0');
        const key = `H_${h1}`;
        buckets[key] = {
          key,
          sortKey: h1,
          label: `${h1}:00 a ${h2}:00 hs`,
          shortLabel: `${h1}:00`,
          tickets: 0,
          costoTotal: 0,
          ventaTotal: 0
        };
      }
    }

    hourlySlices.forEach((s) => {
      let key = '';
      let sortKey = '';
      let label = '';
      let shortLabel = '';

      if (groupBy === 'hora') {
        const h1 = String(s.hour).padStart(2, '0');
        const h2 = String((s.hour + 1) % 24).padStart(2, '0');
        key = `H_${h1}`;
        sortKey = h1;
        label = `${h1}:00 a ${h2}:00 hs`;
        shortLabel = `${h1}:00`;
      } else if (groupBy === 'semana') {
        const wk = getIsoWeekKeyAndLabel(s.fechaIso);
        key = wk.key;
        sortKey = wk.sortKey;
        label = wk.label;
        shortLabel = wk.shortLabel;
      } else if (groupBy === 'mes') {
        key = `M_${s.ym}`;
        sortKey = s.ym;
        const [yStr, mStr] = String(s.ym || '').split('-');
        const mNames = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
        const mName = mNames[(Number(mStr) || 1) - 1] || s.ym;
        label = `${mName} ${yStr || ''}`;
        shortLabel = `${mName.slice(0, 3)} ${yStr || ''}`;
      } else {
        key = `D_${s.fechaIso}`;
        sortKey = s.fechaIso;
        const [yStr, mStr, dStr] = String(s.fechaIso || '').split('-');
        label = `${dStr}/${mStr}/${yStr}`;
        shortLabel = `${dStr}/${mStr}`;
      }

      if (!buckets[key]) {
        buckets[key] = { key, sortKey, label, shortLabel, tickets: 0, costoTotal: 0, ventaTotal: 0 };
      }
      buckets[key].tickets += Number(s.tickets) || 0;
      buckets[key].costoTotal = round2(buckets[key].costoTotal + s.costoTotal);
      buckets[key].ventaTotal = round2(buckets[key].ventaTotal + s.importe);
    });

    const rows = Object.values(buckets)
      .sort((a, b) => String(a.sortKey).localeCompare(String(b.sortKey)))
      .map((b) => {
        const ganancia = round2(b.ventaTotal - b.costoTotal);
        const markupPct = b.costoTotal > 0 ? (ganancia / b.costoTotal) * 100 : 0;
        const margenPct = b.ventaTotal > 0 ? (ganancia / b.ventaTotal) * 100 : 0;
        return { ...b, ganancia, markupPct, margenPct };
      });

    const totalCosto = round2(rows.reduce((acc, r) => acc + r.costoTotal, 0));
    const totalVenta = round2(rows.reduce((acc, r) => acc + r.ventaTotal, 0));
    const totalGanancia = round2(totalVenta - totalCosto);
    const totalTickets = rows.reduce((acc, r) => acc + r.tickets, 0);
    const globalMarkup = totalCosto > 0 ? ((totalGanancia / totalCosto) * 100).toFixed(1) : '0.0';
    const globalMargen = totalVenta > 0 ? ((totalGanancia / totalVenta) * 100).toFixed(1) : '0.0';

    const setTxt = (id, t) => {
      const el = document.getElementById(id);
      if (el) el.textContent = t;
    };
    const horaDesc = `${String(horaDesde).padStart(2, '0')}:00 a ${String(horaHasta).padStart(2, '0')}:59 hs`;
    setTxt('est-gb-kpi-costo', `$ ${formatArs(totalCosto)}`);
    setTxt('est-gb-kpi-costo-sub', `Horario: ${horaDesc}`);
    setTxt('est-gb-kpi-venta', `$ ${formatArs(totalVenta)}`);
    setTxt('est-gb-kpi-venta-sub', `${totalTickets.toLocaleString('es-AR')} comprobantes en el período`);
    setTxt('est-gb-kpi-ganancia', `$ ${formatArs(totalGanancia)}`);
    setTxt('est-gb-kpi-ganancia-sub', `Venta − Costo de Compra`);
    setTxt('est-gb-kpi-margen', `${globalMargen}%`);
    setTxt('est-gb-kpi-margen-sub', `Markup s/Compra: +${globalMarkup}% · Margen s/Venta: ${globalMargen}%`);

    const groupTitles = {
      dia: 'Día',
      semana: 'Semana',
      mes: 'Mes',
      hora: 'Rango de Horas (de 1 en 1 hora)'
    };
    setTxt('est-gb-col-periodo', groupTitles[groupBy] || 'Período');
    setTxt(
      'est-gb-chart-subtitle',
      `Agrupado por ${groupTitles[groupBy] || 'Día'} · Rango horario: ${horaDesc} · Ganancia Bruta Total: $ ${formatArs(totalGanancia)}`
    );

    drawEstControlChart(
      'canvas-est-ganancia-bruta',
      EST_STATE.chartTypeGananciaBruta || 'bar',
      rows.map((r) => r.shortLabel),
      rows.map((r) => r.ganancia),
      {
        isCurrency: true,
        multiColor: groupBy === 'mes' || groupBy === 'semana',
        showAverage: true,
        fullLabels: rows.map((r) => r.label),
        extraTooltipLines: rows.map(
          (r) => `Venta: $ ${formatArs(r.ventaTotal)} · Margen: ${r.margenPct.toFixed(1)}% · Markup: +${r.markupPct.toFixed(1)}%`
        )
      }
    );

    const tbody = document.getElementById('est-ganancia-bruta-tbody');
    if (tbody) {
      if (rows.length === 0) {
        tbody.innerHTML = `<tr><td colspan="8" class="table-loading-cell">No hay ventas registradas para los filtros y rango horario seleccionados.</td></tr>`;
      } else {
        tbody.innerHTML = rows
          .slice()
          .reverse()
          .map((r) => {
            const part = totalGanancia > 0 ? ((r.ganancia / totalGanancia) * 100).toFixed(1) : '0.0';
            return `
              <tr>
                <td><strong>${escapeHtml(r.label)}</strong></td>
                <td class="text-right">${r.tickets.toLocaleString('es-AR')}</td>
                <td class="text-right">$ ${formatArs(r.costoTotal)}</td>
                <td class="text-right"><strong>$ ${formatArs(r.ventaTotal)}</strong></td>
                <td class="text-right" style="color:var(--success); font-weight:800;">$ ${formatArs(r.ganancia)}</td>
                <td class="text-right"><span class="badge badge--gold">+${r.markupPct.toFixed(1)}%</span></td>
                <td class="text-right"><span class="badge badge--green">${r.margenPct.toFixed(1)}%</span></td>
                <td class="text-right">${part}%</td>
              </tr>
            `;
          })
          .join('');
      }
    }
  }

  // =========================================================================
  // RENDERIZADO DE SUBMÓDULO 6: GANANCIA NETA (POR MES CALENDARIO DETRAYENDO GASTOS IMPUTADOS)
  // =========================================================================
  function getAllFondosGastosRecords() {
    loadFondosLocalState();
    const out = [];
    const seenIds = new Set();

    (FONDOS_STATE.ordenesPago || []).forEach((op) => {
      if (!op || op.anulada) return;
      if (op.modo !== 'gastos' && !op.esGasto) return;
      const uid = String(op.id || op.numeroCompleto || '');
      if (uid) seenIds.add(uid);
      const fIso = String(op.fechaIso || '').slice(0, 10);
      const periodoImputado = String(op.periodoImputado || fIso.slice(0, 7) || '').slice(0, 7);
      out.push({
        id: uid,
        fechaPago: op.fecha || (fIso ? fIso.split('-').reverse().join('/') : ''),
        fechaIso: fIso,
        nroOrden: op.numeroCompleto || op.comprobante || 'OP',
        categoriaId: op.categoriaGastoId || 'GASTO_GRAL',
        categoriaNombre: op.categoriaGastoNombre || 'Otros Gastos',
        periodoImputado,
        beneficiario: op.beneficiario || op.destinatario || '—',
        comprobanteRef: op.comprobanteRef || '',
        concepto: op.concepto || op.observacion || '',
        importe: round2(Number(op.importe) || 0)
      });
    });

    (FONDOS_STATE.movimientosCaja || []).forEach((m) => {
      if (!m || m.anulado) return;
      if (String(m.imputacion || '').toUpperCase() !== 'GASTO' && !m.esGasto) return;
      const refId = String(m.ordenPagoId || m.id || '');
      if (refId && seenIds.has(refId)) return;
      const fIso = String(m.fechaIso || '').slice(0, 10);
      const periodoImputado = String(m.periodoImputado || fIso.slice(0, 7) || '').slice(0, 7);
      out.push({
        id: refId,
        fechaPago: m.fecha || '',
        fechaIso: fIso,
        nroOrden: m.comprobante || 'OP',
        categoriaId: m.categoriaGastoId || 'GASTO_GRAL',
        categoriaNombre: m.categoriaGastoNombre || 'Otros Gastos',
        periodoImputado,
        beneficiario: m.destinatario || '—',
        comprobanteRef: m.comprobanteRef || '',
        concepto: m.concepto || '',
        importe: round2(Number(m.egreso) || Number(m.importe) || 0)
      });
    });

    return out;
  }

  function formatPeriodoImputadoLabel(ym) {
    const [yStr, mStr] = String(ym || '').split('-');
    const nombres = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
    const mIdx = (Number(mStr) || 1) - 1;
    return `${nombres[mIdx] || mStr} ${yStr || ''}`.trim();
  }

  function initEstGananciaNetaSelectors() {
    const mesSel = document.getElementById('est-gn-mes-select');
    const anioSel = document.getElementById('est-gn-anio-select');
    const now = new Date();
    const curY = now.getFullYear();
    const curM = String(now.getMonth() + 1).padStart(2, '0');
    if (anioSel && anioSel.options.length === 0) {
      for (let y = curY - 2; y <= curY + 1; y++) {
        const opt = document.createElement('option');
        opt.value = String(y);
        opt.textContent = String(y);
        if (y === curY) opt.selected = true;
        anioSel.appendChild(opt);
      }
    }
    if (mesSel && !mesSel.dataset.initialized) {
      mesSel.dataset.initialized = '1';
      mesSel.value = curM;
    }
  }

  function renderEstGananciaNetaSubmodule() {
    initEstGananciaNetaSelectors();
    const mesVal = document.getElementById('est-gn-mes-select')?.value || String(new Date().getMonth() + 1).padStart(2, '0');
    const anioVal = document.getElementById('est-gn-anio-select')?.value || String(new Date().getFullYear());
    const selectedYm = `${anioVal}-${mesVal}`;
    const selectedLabel = formatPeriodoImputadoLabel(selectedYm);

    const pvChks = Array.from(document.querySelectorAll('.est-gn-pv-chk:checked')).map((c) => c.value);
    const activePvs = new Set(pvChks.length > 0 ? pvChks : EST_ALL_PVS);

    const allSales = getEstadisticasDataset().filter((r) => activePvs.has(r.pv));
    const allGastos = getAllFondosGastosRecords();

    // Calcular mes a mes del año seleccionado
    const nombresMes = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
    const monthlyRows = [];
    for (let m = 1; m <= 12; m++) {
      const mPad = String(m).padStart(2, '0');
      const ym = `${anioVal}-${mPad}`;
      const salesM = allSales.filter((r) => r.ym === ym);
      const gastosM = allGastos.filter((g) => g.periodoImputado === ym);

      const venta = round2(salesM.reduce((acc, r) => acc + r.importe, 0));
      const costo = round2(salesM.reduce((acc, r) => acc + r.costoTotal, 0));
      const bruta = round2(venta - costo);
      const gastos = round2(gastosM.reduce((acc, g) => acc + g.importe, 0));
      const neta = round2(bruta - gastos);
      const pctNeta = venta > 0 ? (neta / venta) * 100 : 0;

      monthlyRows.push({
        ym,
        mPad,
        label: `${nombresMes[m - 1]} ${anioVal}`,
        shortLabel: nombresMes[m - 1].slice(0, 3),
        venta,
        costo,
        bruta,
        gastos,
        gastosCount: gastosM.length,
        neta,
        pctNeta
      });
    }

    const curMonthRow = monthlyRows.find((r) => r.ym === selectedYm) || {
      ym: selectedYm,
      label: selectedLabel,
      venta: 0,
      costo: 0,
      bruta: 0,
      gastos: 0,
      gastosCount: 0,
      neta: 0,
      pctNeta: 0
    };

    const setTxt = (id, t) => {
      const el = document.getElementById(id);
      if (el) el.textContent = t;
    };

    setTxt('est-gn-kpi-bruta', `$ ${formatArs(curMonthRow.bruta)}`);
    setTxt('est-gn-kpi-bruta-sub', `Venta $ ${formatArs(curMonthRow.venta)} − Costo $ ${formatArs(curMonthRow.costo)}`);
    setTxt('est-gn-kpi-gastos', `- $ ${formatArs(curMonthRow.gastos)}`);
    setTxt('est-gn-kpi-gastos-sub', `${curMonthRow.gastosCount} gasto(s) imputado(s) a ${selectedLabel}`);

    const elNeta = document.getElementById('est-gn-kpi-neta');
    if (elNeta) {
      elNeta.textContent = `$ ${formatArs(curMonthRow.neta)}`;
      elNeta.style.color = curMonthRow.neta < -0.009 ? 'var(--red-danger)' : 'var(--green-ok)';
    }
    setTxt('est-gn-kpi-neta-sub', `Período Calendario: ${selectedLabel}`);
    setTxt('est-gn-kpi-pct', `${curMonthRow.pctNeta.toFixed(2)}%`);
    const incGastos = curMonthRow.bruta > 0 ? ((curMonthRow.gastos / curMonthRow.bruta) * 100).toFixed(1) : '0.0';
    setTxt('est-gn-kpi-pct-sub', `Gastos representan el ${incGastos}% de la Ganancia Bruta`);

    setTxt('est-gn-chart-anual-legend', `Ganancia Neta Mensual · Año ${anioVal} (Meses Calendario)`);
    setTxt('est-gn-chart-gastos-legend', `Gastos Imputados a ${selectedLabel} por Rubro ($ ${formatArs(curMonthRow.gastos)})`);
    setTxt('est-gn-gastos-detalle-title', `🧾 Detalle de Gastos Imputados a ${selectedLabel}`);

    // Gráfico 1: Ganancia Neta mes a mes del año
    const activeMonthsChart = monthlyRows.filter((r) => r.venta > 0 || r.gastos > 0 || r.ym === selectedYm);
    drawEstControlChart(
      'canvas-est-ganancia-neta',
      EST_STATE.chartTypeGananciaNeta || 'bar',
      activeMonthsChart.map((r) => r.shortLabel),
      activeMonthsChart.map((r) => Math.max(0, r.neta)),
      {
        isCurrency: true,
        multiColor: true,
        showAverage: true,
        fullLabels: activeMonthsChart.map((r) => r.label),
        extraTooltipLines: activeMonthsChart.map(
          (r) => `Margen Neto: ${r.pctNeta.toFixed(2)}% · Bruta: $ ${formatArs(r.bruta)} · Gastos: $ ${formatArs(r.gastos)}`
        )
      }
    );

    // Gráfico 2: Desglose de Gastos del mes seleccionado por Rubro
    const gastosMesActual = allGastos.filter((g) => g.periodoImputado === selectedYm);
    const byCat = {};
    gastosMesActual.forEach((g) => {
      const k = g.categoriaNombre || 'Otros Gastos';
      byCat[k] = round2((byCat[k] || 0) + g.importe);
    });
    const catEntries = Object.entries(byCat).sort((a, b) => b[1] - a[1]);
    drawEstControlChart(
      'canvas-est-ganancia-neta-gastos',
      EST_STATE.chartTypeGananciaNetaGastos || 'bar',
      catEntries.map((e) => e[0].slice(0, 16)),
      catEntries.map((e) => e[1]),
      {
        isCurrency: true,
        multiColor: true,
        showAverage: false,
        fullLabels: catEntries.map((e) => e[0])
      }
    );

    // Tabla 1: Resumen Mensual del Año
    const tbodyMensual = document.getElementById('est-gn-mensual-tbody');
    if (tbodyMensual) {
      tbodyMensual.innerHTML = monthlyRows
        .filter((r) => r.venta > 0 || r.gastos > 0 || r.ym === selectedYm)
        .map((r) => {
          const isSel = r.ym === selectedYm;
          return `
            <tr data-gn-select-ym="${r.ym}" style="cursor:pointer; ${isSel ? 'background:rgba(212, 160, 23, 0.14); font-weight:700;' : ''}" title="Clic para ver el detalle de ${escapeHtml(r.label)}">
              <td>
                <strong>${escapeHtml(r.label)}</strong>
                ${isSel ? '<span class="badge badge--gold" style="margin-left:0.4rem;">Seleccionado</span>' : ''}
              </td>
              <td class="text-right">$ ${formatArs(r.venta)}</td>
              <td class="text-right">$ ${formatArs(r.costo)}</td>
              <td class="text-right" style="color:var(--green-ok); font-weight:700;">$ ${formatArs(r.bruta)}</td>
              <td class="text-right" style="color:var(--red-danger); font-weight:700;">- $ ${formatArs(r.gastos)} <span class="art-sub-meta">(${r.gastosCount})</span></td>
              <td class="text-right" style="color:${r.neta < -0.009 ? 'var(--red-danger)' : 'var(--green-ok)'}; font-weight:800; font-size:0.96rem;">$ ${formatArs(r.neta)}</td>
              <td class="text-right"><span class="badge ${r.neta < -0.009 ? 'badge--danger' : 'badge--green'}">${r.pctNeta.toFixed(2)}%</span></td>
            </tr>
          `;
        })
        .join('');
    }

    // Tabla 2: Detalle de Gastos Imputados al Mes Seleccionado
    const tbodyDetalle = document.getElementById('est-gn-gastos-detalle-tbody');
    if (tbodyDetalle) {
      if (gastosMesActual.length === 0) {
        tbodyDetalle.innerHTML = `<tr><td colspan="7" class="table-loading-cell">No hay gastos imputados a <strong>${escapeHtml(selectedLabel)}</strong>. Podés registrarlos desde <strong>Fondos → Orden de Pago (tildando Gastos)</strong> e imputando este mes.</td></tr>`;
      } else {
        tbodyDetalle.innerHTML = gastosMesActual
          .map((g) => `
            <tr>
              <td><strong>${escapeHtml(g.fechaPago || '—')}</strong></td>
              <td><span class="art-code-pill">${escapeHtml(g.nroOrden)}</span></td>
              <td><span class="badge badge--gold">${escapeHtml(g.categoriaNombre)}</span></td>
              <td><strong>${escapeHtml(formatPeriodoImputadoLabel(g.periodoImputado))}</strong></td>
              <td>${escapeHtml(g.beneficiario)}${g.comprobanteRef ? ` <span class="art-sub-meta">(${escapeHtml(g.comprobanteRef)})</span>` : ''}</td>
              <td>${escapeHtml(g.concepto || '—')}</td>
              <td class="text-right"><strong style="color:var(--red-danger);">- $ ${formatArs(g.importe)}</strong></td>
            </tr>
          `)
          .join('');
      }
    }
  }

  // =========================================================================
  // RENDERIZADO DE SUBMÓDULO 7: LISTADO ARTÍCULO GENÉRICO (CÓDIGO 20)
  // Lista a los usuarios que utilizaron el Código 20 y permite visualizar
  // el detalle exacto que escribieron en el código genérico.
  // =========================================================================
  let estArtGenericoPage = 1;
  let estArtGenericoBound = false;

  function resolveGenericCode20UserDisplay(raw) {
    const rawUser = String(
      raw?.usuarioDisplay || raw?.usuario || raw?.vendedorNombre || raw?.username || raw?.closedBy || ''
    ).trim();
    const rawUsername = String(raw?.username || raw?.vendedorNombre || rawUser || '').trim().toLowerCase();

    if (rawUsername && ADMIN_DIRECTORY[rawUsername]) {
      const rec = ADMIN_DIRECTORY[rawUsername];
      const disp = String(rec.name || rec.vendedor || rawUser || rawUsername).trim().toUpperCase();
      return {
        userKey: rawUsername,
        displayName: disp,
        username: rawUsername
      };
    }

    if (rawUser) {
      const upper = rawUser.toUpperCase();
      const foundKey = Object.keys(ADMIN_DIRECTORY).find((k) => {
        const r = ADMIN_DIRECTORY[k];
        return (
          k.toLowerCase() === rawUser.toLowerCase() ||
          String(r?.name || '').trim().toUpperCase() === upper ||
          String(r?.vendedor || '').trim().toUpperCase() === upper
        );
      });
      if (foundKey) {
        const rec = ADMIN_DIRECTORY[foundKey];
        return {
          userKey: foundKey,
          displayName: String(rec.name || rec.vendedor || upper).trim().toUpperCase(),
          username: foundKey
        };
      }
      return {
        userKey: upper,
        displayName: upper,
        username: rawUsername || upper.toLowerCase()
      };
    }

    return {
      userKey: 'SISTEMA',
      displayName: 'CAJERO / SISTEMA',
      username: 'sistema'
    };
  }

  function isCode20GenericItem(it) {
    if (!it || typeof it !== 'object') return false;
    const aid = Number(it.artId ?? it.a ?? it.id) || 0;
    if (aid === 7860) return false; // 03000 Envase Retornable no es Código 20
    const rawCode = String(it.c ?? it.codigo ?? '').trim();
    const cleanDigits = rawCode.replace(/\D/g, '').replace(/^0+/, '');
    if (cleanDigits === '3000') return false;
    if (aid === 4407 || cleanDigits === '20' || Boolean(it.isGeneric)) {
      return true;
    }
    const rawName = String(it.n ?? it.nombre ?? it.descripcion ?? '').trim().toUpperCase();
    if (
      rawName === 'ART. GENERICO' ||
      rawName === 'ARTICULO GENERICO' ||
      rawName === 'ARTÍCULO GENÉRICO'
    ) {
      return true;
    }
    return false;
  }

  function collectAllGenericCode20Usages() {
    const entries = [];
    const seenKeys = new Set();

    const allComprobantes = typeof getAllComprobantesEmitidos === 'function' ? getAllComprobantesEmitidos() : [];
    allComprobantes.forEach((sale) => {
      if (!sale || !Array.isArray(sale.items) || sale.items.length === 0) return;
      const entryType = String(sale.entryType || 'venta').toLowerCase();
      if (entryType === 'recibo' || entryType === 'retiro') return;

      const pv = String(sale.pv || '0002').replace(/\D/g, '').padStart(4, '0');
      const nro = Number(sale.nro) || 0;
      const nroComp = sale.numeroCompleto || `${pv}-${String(nro).padStart(8, '0')}`;
      const fechaIso = sale.fechaIso || extractComprobanteFechaIso(sale) || '';
      const ym = fechaIso ? fechaIso.slice(0, 7) : '';
      const dh = /cr[eé]dito/i.test(String(sale.tipo || sale.tipoBase || '')) ? -1 : 1;
      const userInfo = resolveGenericCode20UserDisplay(sale);
      const cajaLabel =
        pv === '0003' || pv === '0100'
          ? 'Caja 2'
          : pv === '0004' || pv === '0101'
            ? 'Caja 3'
            : 'Caja 1';

      sale.items.forEach((it, idx) => {
        if (!isCode20GenericItem(it)) return;
        const qty = (Number(it.qty ?? it.cantidad) || 1) * dh;
        const unitPrice = round2(Number(it.unitPrice ?? it.precioFinal ?? it.subtotal ?? 0) || 0);
        const subtotal = round2((Number(it.subtotal ?? ( Math.abs(qty) * unitPrice )) || 0) * dh);
        const detalleEscrito = String(it.n ?? it.nombre ?? it.descripcion ?? 'ART. GENERICO').trim();
        const dedupKey = `${pv}-${nro}-${idx}-${detalleEscrito}-${ Math.abs(subtotal).toFixed(2) }`;
        if (seenKeys.has(dedupKey)) return;
        seenKeys.add(dedupKey);

        entries.push({
          key: dedupKey,
          fechaIso,
          ym,
          fechaHora: sale.fechaHora || (fechaIso ? fechaIso.split('-').reverse().join('/') : '—'),
          pv,
          cajaLabel,
          nro,
          numeroCompleto: nroComp,
          tipo: sale.tipo || 'Comprobante',
          cliente: sale.cliente || 'CONSUMIDOR FINAL',
          medioPago: sale.medioPago || 'Efectivo',
          userKey: userInfo.userKey,
          userDisplay: userInfo.displayName,
          username: userInfo.username,
          codigo: '00020',
          detalleEscrito,
          qty,
          unitPrice,
          subtotal,
          saleRef: sale
        });
      });
    });

    // Incluir también registros persistidos en STATE.ventasDb.genericCode20Log por si algún comprobante antiguo salió del buffer de 350
    const logArr = Array.isArray(STATE.ventasDb?.genericCode20Log) ? STATE.ventasDb.genericCode20Log : [];
    logArr.forEach((row, idx) => {
      if (!row || typeof row !== 'object') return;
      const pv = String(row.pv || '0002').replace(/\D/g, '').padStart(4, '0');
      const nro = Number(row.nro) || 0;
      const detalleEscrito = String(row.detalleEscrito ?? row.n ?? 'ART. GENERICO').trim();
      const subtotal = round2(Number(row.subtotal) || 0);
      const itemIdx = Number(row.itemIdx ?? idx) || 0;
      const dedupKey = `${pv}-${nro}-${itemIdx}-${detalleEscrito}-${Math.abs(subtotal).toFixed(2)}`;
      if (seenKeys.has(dedupKey)) return;
      seenKeys.add(dedupKey);

      const fechaIso = String(row.fechaIso || '').trim();
      const userInfo = resolveGenericCode20UserDisplay(row);
      const cajaLabel =
        pv === '0003' || pv === '0100'
          ? 'Caja 2'
          : pv === '0004' || pv === '0101'
            ? 'Caja 3'
            : 'Caja 1';

      entries.push({
        key: dedupKey,
        fechaIso,
        ym: fechaIso ? fechaIso.slice(0, 7) : '',
        fechaHora: row.fechaHora || (fechaIso ? fechaIso.split('-').reverse().join('/') : '—'),
        pv,
        cajaLabel,
        nro,
        numeroCompleto: row.numeroCompleto || `${pv}-${String(nro).padStart(8, '0')}`,
        tipo: row.tipo || 'Comprobante',
        cliente: row.cliente || 'CONSUMIDOR FINAL',
        medioPago: row.medioPago || 'Efectivo',
        userKey: userInfo.userKey,
        userDisplay: userInfo.displayName,
        username: userInfo.username,
        codigo: '00020',
        detalleEscrito,
        qty: Number(row.qty) || 1,
        unitPrice: round2(Number(row.unitPrice) || 0),
        subtotal,
        saleRef: null
      });
    });

    entries.sort((a, b) => {
      if (a.fechaIso !== b.fechaIso) {
        return String(b.fechaIso || '').localeCompare(String(a.fechaIso || ''));
      }
      const tA = String(a.fechaHora || '').split(' ')[1] || '00:00';
      const tB = String(b.fechaHora || '').split(' ')[1] || '00:00';
      if (tA !== tB) return tB.localeCompare(tA);
      return (Number(b.nro) || 0) - (Number(a.nro) || 0);
    });

    return entries;
  }

  function renderEstArtGenericoSubmodule(page = null) {
    if (typeof page === 'number' && isFinite(page)) {
      estArtGenericoPage = Math.max(1, Math.floor(page));
    }

    if (!estArtGenericoBound) {
      estArtGenericoBound = true;
      document.getElementById('est-ag-usuario-select')?.addEventListener('change', () => {
        estArtGenericoPage = 1;
        renderEstArtGenericoSubmodule(1);
      });
      document.getElementById('est-ag-search-input')?.addEventListener('input', () => {
        estArtGenericoPage = 1;
        renderEstArtGenericoSubmodule(1);
      });
    }

    const allEntries = collectAllGenericCode20Usages();
    const activePvs = new Set(getSelectedEstPVs());
    const df = getSelectedEstDateFilter();
    const monthsSet = new Set(df.months);

    // Poblar selector de Usuarios con todos los usuarios del sistema + los que figuren en registros
    const userSel = document.getElementById('est-ag-usuario-select');
    if (userSel) {
      const prevUserVal = userSel.value || 'TODOS';
      const usersMap = new Map();
      Object.keys(ADMIN_DIRECTORY || {}).forEach((uKey) => {
        const r = ADMIN_DIRECTORY[uKey];
        const disp = String(r?.name || r?.vendedor || uKey).trim().toUpperCase();
        if (disp) usersMap.set(uKey, disp);
      });
      allEntries.forEach((e) => {
        if (e.userKey && e.userDisplay && !usersMap.has(e.userKey)) {
          usersMap.set(e.userKey, e.userDisplay);
        }
      });
      const sortedUsers = Array.from(usersMap.entries()).sort((a, b) => a[1].localeCompare(b[1], 'es-AR'));
      userSel.innerHTML =
        `<option value="TODOS">Todos los usuarios (${sortedUsers.length})</option>` +
        sortedUsers.map(([k, name]) => `<option value="${escapeHtml(k)}">${escapeHtml(name)}</option>`).join('');
      if (Array.from(userSel.options).some((o) => o.value === prevUserVal)) {
        userSel.value = prevUserVal;
      }
    }

    const selectedUser = userSel?.value || 'TODOS';
    const searchQ = normalizeStr(document.getElementById('est-ag-search-input')?.value || '');
    const searchTokens = searchQ ? searchQ.split(/\s+/).filter(Boolean) : [];

    // Filtrar primero por PV y Fecha para armar el resumen por usuario y luego por usuario/búsqueda
    const byPvAndDate = allEntries.filter((e) => {
      if (!activePvs.has(e.pv)) return false;
      if (e.fechaIso) {
        if (df.mode === 'rango') {
          if (e.fechaIso < df.from || e.fechaIso > df.to) return false;
        } else {
          if (!monthsSet.has(e.ym)) return false;
        }
      }
      return true;
    });

    const filtered = byPvAndDate.filter((e) => {
      if (selectedUser !== 'TODOS' && e.userKey !== selectedUser) return false;
      if (searchTokens.length > 0) {
        const hay = normalizeStr(`${e.detalleEscrito} ${e.userDisplay} ${e.numeroCompleto} ${e.cliente} ${e.cajaLabel}`);
        if (!searchTokens.every((t) => hay.includes(t))) return false;
      }
      return true;
    });

    // Agrupar resumen por Usuario
    const userStatsMap = new Map();
    byPvAndDate.forEach((e) => {
      let st = userStatsMap.get(e.userKey);
      if (!st) {
        st = {
          userKey: e.userKey,
          userDisplay: e.userDisplay,
          cajas: new Set(),
          count: 0,
          unidades: 0,
          totalImporte: 0,
          lastDetalle: e.detalleEscrito,
          lastFechaHora: e.fechaHora
        };
        userStatsMap.set(e.userKey, st);
      }
      st.cajas.add(`${e.cajaLabel} (PV ${e.pv})`);
      st.count += 1;
      st.unidades = round2(st.unidades + e.qty);
      st.totalImporte = round2(st.totalImporte + e.subtotal);
    });

    const userStatsRows = Array.from(userStatsMap.values()).sort((a, b) => b.count - a.count || b.totalImporte - a.totalImporte);

    // KPIs
    const totalCount = filtered.length;
    const totalUnits = round2(filtered.reduce((acc, e) => acc + e.qty, 0));
    const totalImporte = round2(filtered.reduce((acc, e) => acc + e.subtotal, 0));
    const uniqueUsersCount = new Set(filtered.map((e) => e.userKey)).size;
    const uniqueCompsCount = new Set(filtered.map((e) => e.numeroCompleto)).size;

    const setTxt = (id, t) => {
      const el = document.getElementById(id);
      if (el) el.textContent = t;
    };
    setTxt('est-ag-kpi-count', totalCount.toLocaleString('es-AR'));
    setTxt('est-ag-kpi-count-sub', `${totalUnits.toLocaleString('es-AR')} unidad(es) vendidas con Código 20`);
    setTxt('est-ag-kpi-importe', `$ ${formatArs(totalImporte)}`);
    setTxt('est-ag-kpi-importe-sub', totalCount > 0 ? `Promedio por ítem: $ ${formatArs(totalImporte / totalCount)}` : 'En el período seleccionado');
    setTxt('est-ag-kpi-users', uniqueUsersCount.toLocaleString('es-AR'));
    setTxt(
      'est-ag-kpi-users-sub',
      userStatsRows.length > 0
        ? `Mayor uso: ${userStatsRows[0].userDisplay} (${userStatsRows[0].count})`
        : 'Sin registros en el período'
    );
    setTxt('est-ag-kpi-comprobantes', uniqueCompsCount.toLocaleString('es-AR'));
    setTxt('est-ag-kpi-comprobantes-sub', 'Facturas y Comprobantes Internos con Cód. 20');
    setTxt('est-ag-status-msg', `${totalCount.toLocaleString('es-AR')} registro(s)`);

    // Render Tabla 1: Resumen por Usuario
    const usersTbody = document.getElementById('est-ag-users-tbody');
    if (usersTbody) {
      if (userStatsRows.length === 0) {
        usersTbody.innerHTML = `<tr><td colspan="7" class="table-loading-cell">Ningún usuario utilizó el Código 20 (Artículo Genérico) en el período y puntos de venta seleccionados.</td></tr>`;
      } else {
        usersTbody.innerHTML = userStatsRows
          .map((u) => {
            const isSelected = selectedUser === u.userKey;
            return `
              <tr style="${isSelected ? 'background:rgba(212, 160, 23, 0.14);' : ''}">
                <td><strong>👤 ${escapeHtml(u.userDisplay)}</strong></td>
                <td>${escapeHtml(Array.from(u.cajas).join(' · '))}</td>
                <td class="num-col"><span class="badge badge--gold">${u.count.toLocaleString('es-AR')} vez/veces</span></td>
                <td class="num-col"><strong>${u.unidades.toLocaleString('es-AR')}</strong></td>
                <td class="num-col"><strong>$ ${formatArs(u.totalImporte)}</strong></td>
                <td>
                  <strong>${escapeHtml(u.lastDetalle)}</strong>
                  <span class="art-sub-meta" style="display:block;">${escapeHtml(u.lastFechaHora)}</span>
                </td>
                <td class="action-col">
                  <button type="button" class="btn-secondary btn-sm btn-est-ag-filter-user" data-user-key="${escapeHtml(u.userKey)}" style="width:auto; white-space:nowrap;">
                    ${isSelected ? '✓ Mostrando todos' : '🔍 Ver sus cargas'}
                  </button>
                </td>
              </tr>
            `;
          })
          .join('');

        usersTbody.querySelectorAll('.btn-est-ag-filter-user').forEach((btn) => {
          btn.addEventListener('click', () => {
            const uKey = btn.getAttribute('data-user-key') || 'TODOS';
            if (userSel) {
              userSel.value = userSel.value === uKey ? 'TODOS' : uKey;
              estArtGenericoPage = 1;
              renderEstArtGenericoSubmodule(1);
            }
          });
        });
      }
    }

    // Render Tabla 2: Detalle escrito en cada uso del Código 20
    const detalleTbody = document.getElementById('est-ag-detalle-tbody');
    if (!detalleTbody) return;
    detalleTbody.textContent = '';

    if (filtered.length === 0) {
      detalleTbody.innerHTML = `<tr><td colspan="10" class="table-loading-cell">No se registran usos del Código 20 (Artículo Genérico) para los filtros seleccionados.</td></tr>`;
      renderTenByTenPaginationBar({ containerId: 'est-ag-pagination-bar', totalItems: 0 });
      return;
    }

    const AG_PAGE_SIZE = 10;
    const totalPages = Math.max(1, Math.ceil(filtered.length / AG_PAGE_SIZE));
    estArtGenericoPage = Math.min(Math.max(1, estArtGenericoPage), totalPages);
    const startIdx = (estArtGenericoPage - 1) * AG_PAGE_SIZE;
    const pageRows = filtered.slice(startIdx, startIdx + AG_PAGE_SIZE);

    pageRows.forEach((row) => {
      const tr = document.createElement('tr');
      const isDefaultText =
        row.detalleEscrito.toUpperCase() === 'ART. GENERICO' ||
        row.detalleEscrito.toUpperCase() === 'ARTICULO GENERICO' ||
        row.detalleEscrito.toUpperCase() === 'ARTÍCULO GENÉRICO';

      tr.innerHTML = `
        <td style="white-space:nowrap;"><strong>${escapeHtml(row.fechaHora)}</strong></td>
        <td><span class="badge badge--gold">👤 ${escapeHtml(row.userDisplay)}</span></td>
        <td style="white-space:nowrap;">
          <span class="art-code-pill">${escapeHtml(row.numeroCompleto)}</span>
          <span class="art-sub-meta" style="display:block;">${escapeHtml(row.cajaLabel)} · ${escapeHtml(row.tipo)}</span>
        </td>
        <td>${escapeHtml(row.cliente)}</td>
        <td><span class="art-code-pill">#00020</span></td>
        <td>
          <strong style="font-size:0.95rem; color:${isDefaultText ? 'var(--text-secondary)' : 'var(--text-primary)'};">
            ${escapeHtml(row.detalleEscrito)}
          </strong>
          ${isDefaultText ? '<span class="art-sub-meta" style="display:block; color:var(--danger);">⚠️ Sin detalle específico escrito (dejó nombre por defecto)</span>' : '<span class="art-sub-meta" style="display:block; color:var(--success);">✓ Detalle escrito por el cajero</span>'}
        </td>
        <td class="num-col"><strong>${row.qty.toLocaleString('es-AR')}</strong></td>
        <td class="num-col">$ ${formatArs(row.unitPrice)}</td>
        <td class="num-col"><strong>$ ${formatArs(row.subtotal)}</strong></td>
        <td class="action-col"></td>
      `;

      const tdAction = tr.lastElementChild;
      if (row.saleRef && typeof openPosTicketDialog === 'function') {
        const btnVer = document.createElement('button');
        btnVer.type = 'button';
        btnVer.className = 'btn-secondary btn-sm';
        btnVer.style.width = 'auto';
        btnVer.style.whiteSpace = 'nowrap';
        btnVer.textContent = '🖨️ Ver Ticket';
        btnVer.addEventListener('click', () => {
          openPosTicketDialog(row.saleRef, { goToNextSaleOnClose: false });
        });
        tdAction.appendChild(btnVer);
      } else {
        tdAction.textContent = '—';
      }

      detalleTbody.appendChild(tr);
    });

    renderTenByTenPaginationBar({
      containerId: 'est-ag-pagination-bar',
      totalItems: filtered.length,
      pageSize: AG_PAGE_SIZE,
      currentPage: estArtGenericoPage,
      itemLabel: 'registros de Código 20',
      onPageChange: (nextPage) => renderEstArtGenericoSubmodule(nextPage)
    });
  }

  // =========================================================================
  // SUBMÓDULO 0: DASHBOARD AUTOMÁTICO GERENCIAL EN TIEMPO REAL
  // =========================================================================
  function renderEstDashboardSubmodule() {
    const records = getFilteredEstRecords();
    const allRecords = getEstadisticasDataset();
    const pvs = getSelectedEstPVs();
    const now = new Date();
    const curYear = now.getFullYear();
    const curMonth = now.getMonth() + 1;
    const curDay = now.getDate();
    const todayIso = `${curYear}-${String(curMonth).padStart(2, '0')}-${String(curDay).padStart(2, '0')}`;
    const curYm = `${curYear}-${String(curMonth).padStart(2, '0')}`;
    const daysInCurMonth = new Date(curYear, curMonth, 0).getDate();

    const syncEl = document.getElementById('est-dash-last-sync');
    if (syncEl) {
      const hh = String(now.getHours()).padStart(2, '0');
      const mm = String(now.getMinutes()).padStart(2, '0');
      const ss = String(now.getSeconds()).padStart(2, '0');
      syncEl.textContent = `Sincronizado: ${hh}:${mm}:${ss}`;
    }

    // 1. KPIs del período y de Hoy
    const yesterdayDt = new Date(now.getTime() - 86400000);
    const yesterdayIso = `${yesterdayDt.getFullYear()}-${String(yesterdayDt.getMonth() + 1).padStart(2, '0')}-${String(yesterdayDt.getDate()).padStart(2, '0')}`;

    let factHoy = 0;
    let ticketsHoy = 0;
    let factAyer = 0;
    let factMesActual = 0;
    const diasMesActualSet = new Set();

    allRecords.forEach((r) => {
      if (!pvs.includes(r.pv)) return;
      if (r.fechaIso === todayIso) {
        factHoy = round2(factHoy + r.importe);
        ticketsHoy += Number(r.tickets) || 1;
      } else if (r.fechaIso === yesterdayIso) {
        factAyer = round2(factAyer + r.importe);
      }
      if (r.ym === curYm) {
        factMesActual = round2(factMesActual + r.importe);
        diasMesActualSet.add(r.fechaIso);
      }
    });

    let totalFactPeriodo = 0;
    let totalCostoPeriodo = 0;
    let totalGananciaPeriodo = 0;
    let totalTicketsPeriodo = 0;
    const diasPeriodoSet = new Set();

    records.forEach((r) => {
      totalFactPeriodo = round2(totalFactPeriodo + r.importe);
      totalCostoPeriodo = round2(totalCostoPeriodo + r.costoTotal);
      totalGananciaPeriodo = round2(totalGananciaPeriodo + r.ganancia);
      totalTicketsPeriodo += Number(r.tickets) || 1;
      diasPeriodoSet.add(r.fechaIso);
    });

    const diasActivosPeriodo = Math.max(1, diasPeriodoSet.size);
    const promDiarioPeriodo = round2(totalFactPeriodo / diasActivosPeriodo);
    const diasTranscurridosMes = Math.max(1, curDay, diasMesActualSet.size);
    const promDiarioMes = round2(factMesActual / diasTranscurridosMes);
    const proyeccionMes = round2(promDiarioMes * daysInCurMonth);

    const margenSobreVenta = totalFactPeriodo > 0 ? (totalGananciaPeriodo / totalFactPeriodo) * 100 : 0;
    const markupSobreCosto = totalCostoPeriodo > 0 ? (totalGananciaPeriodo / totalCostoPeriodo) * 100 : 0;
    const ticketPromedio = totalTicketsPeriodo > 0 ? round2(totalFactPeriodo / totalTicketsPeriodo) : 0;

    let compAyerTxt = '';
    if (factAyer > 0) {
      const diffPct = ((factHoy - factAyer) / factAyer) * 100;
      const sign = diffPct >= 0 ? '▲ +' : '▼ ';
      compAyerTxt = ` · ${sign}${diffPct.toFixed(1).replace('.', ',')}% vs. ayer`;
    } else if (promDiarioMes > 0 && factHoy > 0) {
      const diffPct = ((factHoy - promDiarioMes) / promDiarioMes) * 100;
      const sign = diffPct >= 0 ? '▲ +' : '▼ ';
      compAyerTxt = ` · ${sign}${diffPct.toFixed(1).replace('.', ',')}% vs. prom. diario`;
    }

    const elHoy = document.getElementById('est-dash-kpi-hoy');
    const elHoySub = document.getElementById('est-dash-kpi-hoy-sub');
    const elPeriodo = document.getElementById('est-dash-kpi-periodo');
    const elProy = document.getElementById('est-dash-kpi-proyeccion');
    const elGan = document.getElementById('est-dash-kpi-ganancia');
    const elMargen = document.getElementById('est-dash-kpi-margen');
    const elTkProm = document.getElementById('est-dash-kpi-ticket-prom');
    const elTks = document.getElementById('est-dash-kpi-tickets');

    if (elHoy) elHoy.textContent = `$ ${formatArs(factHoy)}`;
    if (elHoySub) elHoySub.textContent = `${ticketsHoy.toLocaleString('es-AR')} comprobantes hoy${compAyerTxt}`;
    if (elPeriodo) elPeriodo.textContent = `$ ${formatArs(totalFactPeriodo)}`;
    if (elProy) elProy.textContent = `Proyección cierre mes: $ ${formatArs(proyeccionMes)}`;
    if (elGan) elGan.textContent = `$ ${formatArs(totalGananciaPeriodo)}`;
    if (elMargen) {
      elMargen.textContent = `Margen s/Venta: ${margenSobreVenta.toFixed(1).replace('.', ',')}% · Markup: ${markupSobreCosto.toFixed(1).replace('.', ',')}%`;
    }
    if (elTkProm) elTkProm.textContent = `$ ${formatArs(ticketPromedio)}`;
    if (elTks) {
      elTks.textContent = `${totalTicketsPeriodo.toLocaleString('es-AR')} tickets · Prom. diario: $ ${formatArs(promDiarioPeriodo)}`;
    }

    // 2. Estado de las 3 Cajas en Vivo (Hoy)
    const cajasGrid = document.getElementById('est-dash-cajas-grid');
    if (cajasGrid) {
      cajasGrid.textContent = '';
      const cajasDefs = [
        { id: 'caja1', nombre: 'Caja 1', pvs: ['0002', '0099'], labelPvs: 'PV 0002 / 0099' },
        { id: 'caja2', nombre: 'Caja 2', pvs: ['0003', '0100'], labelPvs: 'PV 0003 / 0100' },
        { id: 'caja3', nombre: 'Caja 3', pvs: ['0004', '0101'], labelPvs: 'PV 0004 / 0101' }
      ];
      cajasDefs.forEach((cj) => {
        const activeAp = typeof getActiveShiftAperturaForCaja === 'function' ? getActiveShiftAperturaForCaja(cj.id) : null;
        let hoyImp = 0;
        let hoyTks = 0;
        let mesImp = 0;
        allRecords.forEach((r) => {
          if (!cj.pvs.includes(r.pv)) return;
          if (r.fechaIso === todayIso) {
            hoyImp = round2(hoyImp + r.importe);
            hoyTks += Number(r.tickets) || 1;
          }
          if (r.ym === curYm) {
            mesImp = round2(mesImp + r.importe);
          }
        });
        const isOpen = Boolean(activeAp) || hoyTks > 0;
        const cajeroTxt = activeAp?.empleado
          ? `Abierta (${activeAp.empleado})`
          : hoyTks > 0
            ? 'Con Ventas Hoy'
            : 'Sin Apertura Hoy';
        const statusColor = activeAp ? '#16a34a' : hoyTks > 0 ? '#2563eb' : '#6b7280';
        const statusBg = activeAp ? '#dcfce7' : hoyTks > 0 ? '#dbeafe' : '#f3f4f6';

        const card = document.createElement('div');
        card.style.cssText = 'padding:12px; border-radius:10px; border:1px solid var(--color-border); background:var(--color-surface); display:flex; flex-direction:column; gap:6px;';
        card.innerHTML = `
          <div style="display:flex; justify-content:space-between; align-items:center; gap:6px;">
            <strong style="font-size:0.88rem; color:#092837;">🖥️ ${escapeHtml(cj.nombre)}</strong>
            <span style="font-size:0.7rem; font-weight:800; padding:2px 8px; border-radius:999px; background:${statusBg}; color:${statusColor};">
              ${isOpen ? '🟢' : '⚪'} ${escapeHtml(cajeroTxt)}
            </span>
          </div>
          <div style="font-size:0.72rem; color:var(--color-text-muted); font-weight:700;">${escapeHtml(cj.labelPvs)}</div>
          <div style="font-size:1.12rem; font-weight:900; color:#092837;">$ ${formatArs(hoyImp)}</div>
          <div style="font-size:0.73rem; color:var(--color-text-muted); display:flex; justify-content:space-between;">
            <span>Hoy: <strong>${hoyTks}</strong> tickets</span>
            <span>Mes: <strong>$ ${formatArs(mesImp)}</strong></span>
          </div>
        `;
        cajasGrid.appendChild(card);
      });
    }

    // 3. Semáforo de Alertas Operativas Automáticas (con acceso directo en 1 clic)
    const alertasGrid = document.getElementById('est-dash-alertas-grid');
    if (alertasGrid) {
      alertasGrid.textContent = '';
      const activeArts = (STATE.articulos || []).filter((a) => Number(a.bl) !== 1);
      let negCount = 0;
      let minStockCount = 0;
      let cwPublishedCount = 0;
      const cwMode = STATE.carritoWebStockMode === 'todos_sin_stock' ? 'todos_sin_stock' : 'solo_con_stock';

      activeArts.forEach((a) => {
        const sf = Number(a.sf) || 0;
        const sm = Number(a.sm) || 0;
        if (sf < 0) negCount++;
        else if (sm > 0 && sf <= sm) minStockCount++;
        const isTildado = Number(a.cw ?? 1) === 1;
        if (isTildado && (cwMode === 'todos_sin_stock' || sf > 0)) {
          cwPublishedCount++;
        }
      });

      const gondolaQueueCount = Object.keys(STATE.gondolaQueue || {}).length;
      let pendingCanjesCount = 0;
      (STATE.clientes || []).forEach((c) => {
        if (Array.isArray(c.historialPuntos)) {
          c.historialPuntos.forEach((m) => {
            if (m && m.tipo === 'CANJE' && !m.entregado) pendingCanjesCount++;
          });
        }
      });

      const alertasList = [
        {
          icon: negCount > 0 ? '🚨' : '✅',
          title: 'Stock Negativo',
          value: `${negCount.toLocaleString('es-AR')} art.`,
          sub: negCount > 0 ? 'Requiere ajuste de stock' : 'Sin stock negativo',
          bg: negCount > 0 ? '#fef2f2' : '#f0fdf4',
          border: negCount > 0 ? '#fecaca' : '#bbf7d0',
          color: negCount > 0 ? '#b91c1c' : '#166534',
          target: 'sec-stock-negativo'
        },
        {
          icon: minStockCount > 0 ? '⚠️' : '📦',
          title: 'Bajo Stock Mínimo',
          value: `${minStockCount.toLocaleString('es-AR')} art.`,
          sub: 'Para reposición a proveedor',
          bg: minStockCount > 0 ? '#fffbeb' : '#f0fdf4',
          border: minStockCount > 0 ? '#fde68a' : '#bbf7d0',
          color: minStockCount > 0 ? '#b45309' : '#166534',
          target: 'sec-pedidos-proveedores'
        },
        {
          icon: '🏷️',
          title: 'Etiquetas de Góndola',
          value: `${gondolaQueueCount.toLocaleString('es-AR')} pend.`,
          sub: gondolaQueueCount > 0 ? 'Listas para imprimir' : 'Cola de impresión al día',
          bg: gondolaQueueCount > 0 ? '#eff6ff' : '#f9fafb',
          border: gondolaQueueCount > 0 ? '#bfdbfe' : '#e5e7eb',
          color: gondolaQueueCount > 0 ? '#1d4ed8' : '#374151',
          target: 'sec-precios-gondola'
        },
        {
          icon: '🛒',
          title: 'Tienda Carrito Web',
          value: `${cwPublishedCount.toLocaleString('es-AR')} pub.`,
          sub: cwMode === 'solo_con_stock' ? 'Modo: Solo con Stock' : 'Modo: Todos (c/s Stock)',
          bg: '#f0fdf4',
          border: '#bbf7d0',
          color: '#166534',
          target: 'sec-carrito-articulos'
        }
      ];

      if (pendingCanjesCount > 0) {
        alertasList.push({
          icon: '🎁',
          title: 'Canjes Club Pendientes',
          value: `${pendingCanjesCount} retiro(s)`,
          sub: 'Pendientes de entrega en local',
          bg: '#faf5ff',
          border: '#e9d5ff',
          color: '#6b21a8',
          target: 'sec-fid-canjes'
        });
      }

      alertasList.forEach((al) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.setAttribute('data-open-section', al.target);
        btn.style.cssText = `text-align:left; padding:10px 12px; border-radius:10px; background:${al.bg}; border:1px solid ${al.border}; cursor:pointer; display:flex; flex-direction:column; gap:3px; transition:transform 0.12s ease;`;
        btn.innerHTML = `
          <div style="display:flex; justify-content:space-between; align-items:center; width:100%;">
            <span style="font-size:0.75rem; font-weight:800; color:${al.color};">${al.icon} ${escapeHtml(al.title)}</span>
            <span style="font-size:0.72rem; font-weight:800; color:${al.color};">Abrir →</span>
          </div>
          <strong style="font-size:1.05rem; font-weight:900; color:${al.color};">${escapeHtml(al.value)}</strong>
          <span style="font-size:0.71rem; color:${al.color}; opacity:0.88;">${escapeHtml(al.sub)}</span>
        `;
        btn.addEventListener('click', () => switchSection(al.target));
        alertasGrid.appendChild(btn);
      });
    }

    // 4. Gráfico 1: Evolución Diaria de Facturación
    const byDateMap = new Map();
    records.forEach((r) => {
      const prev = byDateMap.get(r.fechaIso) || 0;
      byDateMap.set(r.fechaIso, round2(prev + r.importe));
    });
    const sortedDates = Array.from(byDateMap.keys()).sort();
    const chartDates = sortedDates.slice(-31);
    const chartLabels = chartDates.map((iso) => {
      const parts = iso.split('-');
      return parts.length === 3 ? `${parts[2]}/${parts[1]}` : iso;
    });
    const chartValues = chartDates.map((iso) => byDateMap.get(iso) || 0);

    drawEstControlChart(
      'canvas-est-dash-evolucion',
      EST_STATE.chartTypeDashEvolucion || 'line',
      chartLabels.length > 0 ? chartLabels : ['Sin datos'],
      chartValues.length > 0 ? chartValues : [0],
      {
        showAverageLine: true,
        averageValue: promDiarioPeriodo,
        averageLabel: `Prom. Diario: $ ${formatArs(promDiarioPeriodo)}`
      }
    );

    // 5. Gráfico 2: Distribución por Medios de Pago
    const mediosMap = new Map();
    EST_MEDIOS_LIST.forEach((m) => mediosMap.set(m, 0));
    records.forEach((r) => {
      const m = mediosMap.has(r.medioPago) ? r.medioPago : 'Efectivo';
      mediosMap.set(m, round2((mediosMap.get(m) || 0) + r.importe));
    });
    const mediosEntries = Array.from(mediosMap.entries()).filter(([, val]) => val > 0);
    drawEstControlChart(
      'canvas-est-dash-medios',
      EST_STATE.chartTypeDashMedios || 'pie',
      mediosEntries.length > 0 ? mediosEntries.map(([k]) => k) : ['Sin ventas'],
      mediosEntries.length > 0 ? mediosEntries.map(([, v]) => v) : [0]
    );

    // 6. Top 10 Productos Estrella y Top 5 Rubros del Período
    const artById = {};
    (STATE.articulos || []).forEach((a) => {
      artById[a.id] = a;
    });
    const realItems = getFilteredRealProductSalesItems(artById);
    const prodAgg = new Map();
    const rubroAgg = new Map();
    let totalRubrosVenta = 0;

    realItems.forEach((it) => {
      const codigo = it.c || it.codigo || String(it.artId || '-');
      const nombre = it.n || it.nombre || 'ARTÍCULO';
      const unidades = Number(it.qty ?? it.unidades) || 0;
      const venta = Number(it.subtotal ?? it.venta) || 0;
      const costo = Number(it.costoTotal) || 0;
      const ganancia = it.ganancia !== undefined ? Number(it.ganancia) : round2(venta - costo);

      const key = `${it.artId || codigo}__${nombre}`;
      const prevP = prodAgg.get(key) || {
        codigo,
        nombre,
        unidades: 0,
        venta: 0,
        ganancia: 0
      };
      prevP.unidades = round2(prevP.unidades + unidades);
      prevP.venta = round2(prevP.venta + venta);
      prevP.ganancia = round2(prevP.ganancia + ganancia);
      prodAgg.set(key, prevP);

      const rName = getEstRubroName(it.rId);
      const prevR = rubroAgg.get(rName) || { rubro: rName, venta: 0, ganancia: 0 };
      prevR.venta = round2(prevR.venta + venta);
      prevR.ganancia = round2(prevR.ganancia + ganancia);
      rubroAgg.set(rName, prevR);
      totalRubrosVenta = round2(totalRubrosVenta + venta);
    });

    const topProducts = Array.from(prodAgg.values())
      .sort((a, b) => b.venta - a.venta)
      .slice(0, 10);

    const topProdTbody = document.getElementById('est-dash-top-productos-tbody');
    if (topProdTbody) {
      topProdTbody.textContent = '';
      if (topProducts.length === 0) {
        topProdTbody.innerHTML = '<tr><td colspan="5" class="table-loading-cell">Sin ventas detalladas de artículos en el período seleccionado.</td></tr>';
      } else {
        topProducts.forEach((p, idx) => {
          const tr = document.createElement('tr');
          tr.innerHTML = `
            <td><strong>#${idx + 1}</strong></td>
            <td>
              <span class="art-code-pill" style="margin-right:4px;">#${escapeHtml(String(p.codigo))}</span>
              <strong>${escapeHtml(p.nombre)}</strong>
            </td>
            <td class="num-col">${Number.isInteger(p.unidades) ? p.unidades.toLocaleString('es-AR') : p.unidades.toFixed(2).replace('.', ',')}</td>
            <td class="num-col"><strong>$ ${formatArs(p.venta)}</strong></td>
            <td class="num-col" style="color:#166534; font-weight:700;">$ ${formatArs(p.ganancia)}</td>
          `;
          topProdTbody.appendChild(tr);
        });
      }
    }

    const topRubros = Array.from(rubroAgg.values())
      .sort((a, b) => b.venta - a.venta)
      .slice(0, 5);

    const topRubrosTbody = document.getElementById('est-dash-top-rubros-tbody');
    if (topRubrosTbody) {
      topRubrosTbody.textContent = '';
      if (topRubros.length === 0) {
        topRubrosTbody.innerHTML = '<tr><td colspan="4" class="table-loading-cell">Sin datos de rubros en el período.</td></tr>';
      } else {
        topRubros.forEach((r) => {
          const pct = totalRubrosVenta > 0 ? (r.venta / totalRubrosVenta) * 100 : 0;
          const tr = document.createElement('tr');
          tr.innerHTML = `
            <td><strong>${escapeHtml(r.rubro)}</strong></td>
            <td class="num-col">${pct.toFixed(1).replace('.', ',')}%</td>
            <td class="num-col"><strong>$ ${formatArs(r.venta)}</strong></td>
            <td class="num-col" style="color:#166534; font-weight:700;">$ ${formatArs(r.ganancia)}</td>
          `;
          topRubrosTbody.appendChild(tr);
        });
      }
    }

    // 7. Finanzas en Vivo: Cuentas Corrientes (Clientes y Proveedores)
    let totalCobrarClientes = 0;
    let countClientesDeudores = 0;
    let totalPagarProvs = 0;
    let countProvsAcreedores = 0;
    const clientesDeudoresList = [];
    const provsAcreedoresList = [];

    (STATE.clientes || []).forEach((c) => {
      if (!c || (typeof isSystemConfigClient === 'function' && isSystemConfigClient(c))) return;
      const saldo = round2(Number(c.saldoActual) || 0);
      if (c.esProveedor && !c.esCliente) {
        const deudaProv = Math.abs(saldo);
        if (deudaProv > 0.01) {
          totalPagarProvs = round2(totalPagarProvs + deudaProv);
          countProvsAcreedores++;
          provsAcreedoresList.push({ id: c.id, nombre: c.nombre || 'PROVEEDOR', saldo: deudaProv });
        }
      } else {
        if (saldo > 0.01) {
          totalCobrarClientes = round2(totalCobrarClientes + saldo);
          countClientesDeudores++;
          clientesDeudoresList.push({ id: c.id, nombre: c.nombre || 'CLIENTE', saldo });
        } else if (c.esProveedor && saldo < -0.01) {
          const deudaProv = Math.abs(saldo);
          totalPagarProvs = round2(totalPagarProvs + deudaProv);
          countProvsAcreedores++;
          provsAcreedoresList.push({ id: c.id, nombre: c.nombre || 'PROVEEDOR', saldo: deudaProv });
        }
      }
    });

    const elCtaCli = document.getElementById('est-dash-ctacte-clientes-total');
    const elCtaCliSub = document.getElementById('est-dash-ctacte-clientes-sub');
    const elCtaProv = document.getElementById('est-dash-ctacte-provs-total');
    const elCtaProvSub = document.getElementById('est-dash-ctacte-provs-sub');
    const elCtaNeto = document.getElementById('est-dash-ctacte-neto');

    if (elCtaCli) elCtaCli.textContent = `$ ${formatArs(totalCobrarClientes)}`;
    if (elCtaCliSub) elCtaCliSub.textContent = `${countClientesDeudores} cliente(s) con saldo`;
    if (elCtaProv) elCtaProv.textContent = `$ ${formatArs(totalPagarProvs)}`;
    if (elCtaProvSub) elCtaProvSub.textContent = `${countProvsAcreedores} proveedor(es) con saldo`;
    if (elCtaNeto) {
      const neto = round2(totalCobrarClientes - totalPagarProvs);
      elCtaNeto.textContent = `${neto < 0 ? '- ' : ''}$ ${formatArs(Math.abs(neto))}`;
      elCtaNeto.style.color = neto >= 0 ? '#15803d' : '#b91c1c';
    }

    const topCliTbody = document.getElementById('est-dash-top-clientes-deudores');
    if (topCliTbody) {
      topCliTbody.textContent = '';
      const top5Cli = clientesDeudoresList.sort((a, b) => b.saldo - a.saldo).slice(0, 5);
      if (top5Cli.length === 0) {
        topCliTbody.innerHTML = '<tr><td colspan="2" class="table-loading-cell">No hay clientes con saldo deudor pendiente.</td></tr>';
      } else {
        top5Cli.forEach((c) => {
          const tr = document.createElement('tr');
          tr.innerHTML = `
            <td><strong>${escapeHtml(c.nombre)}</strong></td>
            <td class="num-col" style="color:#b91c1c; font-weight:800;">$ ${formatArs(c.saldo)}</td>
          `;
          topCliTbody.appendChild(tr);
        });
      }
    }

    const topProvTbody = document.getElementById('est-dash-top-provs-acreedores');
    if (topProvTbody) {
      topProvTbody.textContent = '';
      const top5Prov = provsAcreedoresList.sort((a, b) => b.saldo - a.saldo).slice(0, 5);
      if (top5Prov.length === 0) {
        topProvTbody.innerHTML = '<tr><td colspan="2" class="table-loading-cell">No hay saldos pendientes a proveedores.</td></tr>';
      } else {
        top5Prov.forEach((p) => {
          const tr = document.createElement('tr');
          tr.innerHTML = `
            <td><strong>${escapeHtml(p.nombre)}</strong></td>
            <td class="num-col" style="color:#b45309; font-weight:800;">$ ${formatArs(p.saldo)}</td>
          `;
          topProvTbody.appendChild(tr);
        });
      }
    }
  }

  function renderActiveEstSection(sectionId) {
    const activeId =
      sectionId ||
      [
        'sec-est-dashboard',
        'sec-est-facturacion',
        'sec-est-ranking',
        'sec-est-medios',
        'sec-est-margenes',
        'sec-est-ganancia-bruta',
        'sec-est-ganancia-neta',
        'sec-est-art-generico'
      ].find((id) => !document.getElementById(id)?.hidden);
    updateEstFilterSummaryBadge();
    if (activeId === 'sec-est-dashboard') renderEstDashboardSubmodule();
    else if (activeId === 'sec-est-facturacion') renderEstFacturacionSubmodule();
    else if (activeId === 'sec-est-ranking') renderEstRankingSubmodule();
    else if (activeId === 'sec-est-medios') renderEstMediosSubmodule();
    else if (activeId === 'sec-est-margenes') renderEstMargenesSubmodule();
    else if (activeId === 'sec-est-ganancia-bruta') renderEstGananciaBrutaSubmodule();
    else if (activeId === 'sec-est-ganancia-neta') renderEstGananciaNetaSubmodule();
    else if (activeId === 'sec-est-art-generico') renderEstArtGenericoSubmodule();
  }

  window.__onVentasDbLoaded = () => {
    saveCajasState();
    updateFactLetraAndNumber();
    if (!document.getElementById('sec-caja-pos')?.hidden) {
      renderCajaPosView();
    }
    renderActiveEstSection();
  };

  // Eventos de la Barra Compartida de Filtros de Estadísticas
  initEstFiltersDOM();

  document.getElementById('est-shared-filter-bar')?.addEventListener('change', (e) => {
    const pvChk = e.target.closest('.est-pv-chk');
    if (pvChk) {
      pvChk.closest('.est-pv-pill')?.classList.toggle('is-checked', pvChk.checked);
      renderActiveEstSection();
      return;
    }
    const mesChk = e.target.closest('.est-mes-chk');
    if (mesChk) {
      mesChk.closest('.est-pv-pill')?.classList.toggle('is-checked', mesChk.checked);
      renderActiveEstSection();
    }
  });

  document.getElementById('btn-est-pv-all')?.addEventListener('click', () => {
    const allChecked = Array.from(document.querySelectorAll('.est-pv-chk')).every((c) => c.checked);
    document.querySelectorAll('.est-pv-chk').forEach((chk, idx) => {
      chk.checked = allChecked ? idx === 0 : true;
      chk.closest('.est-pv-pill')?.classList.toggle('is-checked', chk.checked);
    });
    renderActiveEstSection();
  });

  document.querySelectorAll('input[name="est_date_mode"]').forEach((radio) => {
    radio.addEventListener('change', () => {
      const mode = radio.value;
      const boxRango = document.getElementById('est-date-rango-panel');
      const boxMeses = document.getElementById('est-date-meses-panel');
      if (boxRango) boxRango.hidden = mode !== 'rango';
      if (boxMeses) boxMeses.hidden = mode !== 'meses';
      renderActiveEstSection();
    });
  });

  document.querySelectorAll('.est-preset-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      const preset = btn.getAttribute('data-preset');
      const now = new Date();
      const y = now.getFullYear();
      const m = String(now.getMonth() + 1).padStart(2, '0');
      const d = String(now.getDate()).padStart(2, '0');
      const todayIso = `${y}-${m}-${d}`;
      let fromIso = `${y}-${m}-01`;

      if (preset === 'hoy') {
        fromIso = todayIso;
      } else if (preset === '7d') {
        const dt = new Date(now.getTime() - 6 * 86400000);
        fromIso = `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}-${String(dt.getDate()).padStart(2, '0')}`;
      } else if (preset === '30d') {
        const dt = new Date(now.getTime() - 29 * 86400000);
        fromIso = `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}-${String(dt.getDate()).padStart(2, '0')}`;
      } else if (preset === 'anio') {
        fromIso = `${y}-01-01`;
      }

      const fromInp = document.getElementById('est-date-from');
      const toInp = document.getElementById('est-date-to');
      if (fromInp) fromInp.value = fromIso;
      if (toInp) toInp.value = todayIso;
      renderActiveEstSection();
    });
  });

  document.getElementById('est-date-from')?.addEventListener('change', () => renderActiveEstSection());
  document.getElementById('est-date-to')?.addEventListener('change', () => renderActiveEstSection());

  document.getElementById('btn-est-meses-all')?.addEventListener('click', () => {
    document.querySelectorAll('.est-mes-chk').forEach((chk) => {
      chk.checked = true;
      chk.closest('.est-pv-pill')?.classList.add('is-checked');
    });
    renderActiveEstSection();
  });

  document.getElementById('btn-est-meses-current')?.addEventListener('click', () => {
    const now = new Date();
    const curYm = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    document.querySelectorAll('.est-mes-chk').forEach((chk) => {
      const active = chk.value === curYm;
      chk.checked = active;
      chk.closest('.est-pv-pill')?.classList.toggle('is-checked', active);
    });
    renderActiveEstSection();
  });

  // Controles de Submódulos y Botones de Tipo de Gráfico (Línea, Barras, Torta)
  document.getElementById('est-fact-group-by')?.addEventListener('change', () => renderEstFacturacionSubmodule());
  document.getElementById('est-rank-q')?.addEventListener('input', () => renderEstRankingSubmodule());
  document.getElementById('est-rank-orden')?.addEventListener('change', () => renderEstRankingSubmodule());
  document.getElementById('est-rank-rubro')?.addEventListener('change', () => renderEstRankingSubmodule());
  document.getElementById('est-rank-proveedor')?.addEventListener('change', () => renderEstRankingSubmodule());
  document.getElementById('est-rank-marca')?.addEventListener('change', () => renderEstRankingSubmodule());
  document.getElementById('est-rank-limit')?.addEventListener('change', () => renderEstRankingSubmodule());

  document.getElementById('est-ranking-tbody')?.addEventListener('change', (e) => {
    const chk = e.target.closest('.est-rank-row-chk');
    if (!chk) return;
    const rankKey = chk.getAttribute('data-rank-key');
    if (!rankKey) return;
    if (!EST_STATE.excludedRankProductKeys) EST_STATE.excludedRankProductKeys = new Set();
    if (chk.checked) {
      EST_STATE.excludedRankProductKeys.delete(rankKey);
    } else {
      EST_STATE.excludedRankProductKeys.add(rankKey);
    }
    renderEstRankingSubmodule();
  });

  document.getElementById('est-rank-check-all')?.addEventListener('change', (e) => {
    const shouldCheckAll = Boolean(e.target.checked);
    if (!EST_STATE.excludedRankProductKeys) EST_STATE.excludedRankProductKeys = new Set();
    if (shouldCheckAll) {
      EST_STATE.excludedRankProductKeys.clear();
    } else {
      (EST_STATE.lastTopRankKeys || []).forEach((k) => EST_STATE.excludedRankProductKeys.add(k));
    }
    renderEstRankingSubmodule();
  });

  document.getElementById('btn-est-rank-reset-excluded')?.addEventListener('click', () => {
    if (EST_STATE.excludedRankProductKeys) {
      EST_STATE.excludedRankProductKeys.clear();
    }
    renderEstRankingSubmodule();
  });

  document.getElementById('est-margen-group-by')?.addEventListener('change', () => renderEstMargenesSubmodule());
  document.getElementById('est-margen-rubro')?.addEventListener('change', () => renderEstMargenesSubmodule());
  document.getElementById('est-margen-proveedor')?.addEventListener('change', () => renderEstMargenesSubmodule());
  document.getElementById('est-margen-marca')?.addEventListener('change', () => renderEstMargenesSubmodule());
