  function selectArticleForControlStock(art, scannedCode = '') {
    if (!art) return;
    CS_STATE.activeArt = art;
    CS_STATE.scannedCode = scannedCode || art.c;

    const idlePanel = document.getElementById('cs-idle-panel');
    const notFoundPanel = document.getElementById('cs-notfound-panel');
    const prodPanel = document.getElementById('cs-product-panel');
    const suggBox = document.getElementById('cs-suggestions');

    if (idlePanel) idlePanel.hidden = true;
    if (notFoundPanel) notFoundPanel.hidden = true;
    if (prodPanel) prodPanel.hidden = false;
    if (suggBox) suggBox.hidden = true;

    const codeEl = document.getElementById('cs-prod-code');
    const eanEl = document.getElementById('cs-prod-ean');
    const rubroEl = document.getElementById('cs-prod-rubro');
    const marcaEl = document.getElementById('cs-prod-marca');
    const nameEl = document.getElementById('cs-prod-name');
    const priceEl = document.getElementById('cs-prod-price');
    const breakdownEl = document.getElementById('cs-prod-breakdown');
    const mediaEl = document.getElementById('cs-product-media');

    const barcodes = Array.isArray(art.bc) && art.bc.length > 0 ? art.bc.map((b) => b.c).join(' · ') : 'SIN EAN';
    const rubroEntry = STATE.rubrosMap.get(Number(art.r));
    const marcaEntry = STATE.marcasMap.get(Number(art.mk ?? art.m));
    const rubroName = (typeof rubroEntry === 'object' ? rubroEntry?.nombre : rubroEntry) || 'GENERAL';
    const marcaName = (typeof marcaEntry === 'object' ? marcaEntry?.nombre : marcaEntry) || 'SIN MARCA';

    if (codeEl) codeEl.textContent = `CÓD. #${art.c}`;
    if (eanEl) eanEl.textContent = `EAN: ${barcodes}`;
    if (rubroEl) rubroEl.textContent = `RUBRO: ${rubroName}`;
    if (marcaEl) marcaEl.textContent = `MARCA: ${marcaName}`;
    if (nameEl) nameEl.textContent = art.n || 'ARTÍCULO';
    if (priceEl) priceEl.textContent = `$ ${formatArs(art.p1f || 0)}`;

    const si = round2(Number(art.si) || 0);
    const sc = round2(Number(art.sc) || 0);
    const sf = round2(Number(art.sf ?? si + sc) || 0);
    if (breakdownEl) {
      breakdownEl.textContent = `Stock Inicial: ${si} | Compras/Ajustes: ${sc >= 0 ? `+${sc}` : sc}`;
    }

    if (mediaEl) {
      const imgUrl = typeof getProductImageUrl === 'function' ? getProductImageUrl(art) : (art.img || '');
      if (imgUrl) {
        mediaEl.innerHTML = `<img src="${escapeHtml(imgUrl)}" alt="${escapeHtml(art.n)}">`;
      } else {
        mediaEl.innerHTML = '<div class="cs-product-placeholder">📦</div>';
      }
    }

    const currentDisplay = document.getElementById('cs-current-stock-display');
    const diffInput = document.getElementById('cs-diff-input');
    const finalInput = document.getElementById('cs-final-stock-input');
    const obsInput = document.getElementById('cs-obs-input');

    const csAllowFrac = doesArticleAllowFraction(art);
    if (currentDisplay) {
      currentDisplay.textContent = String(sf);
      currentDisplay.style.removeProperty('color');
      currentDisplay.classList.toggle('is-zero-or-neg', sf <= 0);
    }
    if (diffInput) {
      diffInput.step = csAllowFrac ? '0.001' : '1';
      diffInput.value = '0';
    }
    if (finalInput) {
      finalInput.step = csAllowFrac ? '0.001' : '1';
      finalInput.value = String(csAllowFrac ? sf : Math.round(sf));
    }
    if (obsInput) obsInput.value = '';
    updateControlStockDiffBadge(0);
  }

  function applyControlStockDiffChange(newDiffRaw) {
    const art = CS_STATE.activeArt;
    if (!art) return;
    const allowFrac = doesArticleAllowFraction(art);
    const currentStock = round2(Number(art.sf) || 0);
    const diff = allowFrac ? round2(Number(newDiffRaw) || 0) : Math.round(Number(newDiffRaw) || 0);
    const finalStock = allowFrac ? round2(currentStock + diff) : Math.round(currentStock + diff);

    const diffInput = document.getElementById('cs-diff-input');
    const finalInput = document.getElementById('cs-final-stock-input');
    if (diffInput && document.activeElement !== diffInput) {
      diffInput.value = String(diff);
    }
    if (finalInput && document.activeElement !== finalInput) {
      finalInput.value = String(finalStock);
    }
    updateControlStockDiffBadge(diff);
  }

  function applyControlStockFinalChange(newFinalRaw) {
    const art = CS_STATE.activeArt;
    if (!art) return;
    const allowFrac = doesArticleAllowFraction(art);
    const currentStock = round2(Number(art.sf) || 0);
    const finalStock = allowFrac ? round2(Number(newFinalRaw) || 0) : Math.round(Number(newFinalRaw) || 0);
    const diff = allowFrac ? round2(finalStock - currentStock) : Math.round(finalStock - currentStock);

    const diffInput = document.getElementById('cs-diff-input');
    if (diffInput) {
      diffInput.value = String(diff);
    }
    updateControlStockDiffBadge(diff);
  }

  function renderControlStockSuggestions(rawQuery) {
    const suggBox = document.getElementById('cs-suggestions');
    if (!suggBox) return;
    const cleaned = extractCodeFromBarcodeOrQrPayload(rawQuery);
    const q = normalizeStr(cleaned);
    if (!q || q.length < 2) {
      suggBox.hidden = true;
      suggBox.textContent = '';
      return;
    }

    const tokens = q.split(/\s+/).filter(Boolean);
    const matches = [];
    for (const art of STATE.articulos) {
      if (art.bl === 1) continue;
      const bcs = Array.isArray(art.bc) ? art.bc.map((b) => b.c).join(' ') : '';
      const hay = normalizeStr(`${art.c} ${parseInt(art.c, 10) || ''} ${art.n} ${bcs}`);
      if (tokens.every((t) => hay.includes(t))) {
        matches.push(art);
        if (matches.length >= 8) break;
      }
    }

    if (matches.length === 0) {
      suggBox.hidden = true;
      suggBox.textContent = '';
      return;
    }

    suggBox.textContent = '';
    const frag = document.createDocumentFragment();
    matches.forEach((art) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'verificador-suggestion-item';
      const ean = Array.isArray(art.bc) && art.bc.length > 0 ? art.bc[0].c : `CÓD. ${art.c}`;
      btn.innerHTML = `
        <div class="verificador-sugg-left">
          <span class="verificador-sugg-code">#${escapeHtml(art.c)} · ${escapeHtml(ean)}</span>
          <strong class="verificador-sugg-name">${escapeHtml(art.n)}</strong>
        </div>
        <div class="verificador-sugg-right">
          <span class="stock-badge ${Number(art.sf) <= 0 ? 'stock-badge--zero' : ''}" style="margin-inline-end:0.5rem;">Stock: ${round2(art.sf || 0)}</span>
          <span class="verificador-sugg-price">$ ${formatArs(art.p1f || 0)}</span>
        </div>
      `;
      btn.addEventListener('click', () => {
        const inp = document.getElementById('cs-scan-input');
        if (inp) inp.value = '';
        const clearBtn = document.getElementById('cs-scan-clear');
        if (clearBtn) clearBtn.hidden = true;
        selectArticleForControlStock(art, ean);
      });
      frag.appendChild(btn);
    });
    suggBox.appendChild(frag);
    suggBox.hidden = false;
  }

  function handleControlStockScanSubmit(rawTerm) {
    const code = extractCodeFromBarcodeOrQrPayload(rawTerm);
    if (!code) return;

    const suggBox = document.getElementById('cs-suggestions');
    if (suggBox) suggBox.hidden = true;

    // 1. Buscar por código de barras exacto o código interno
    const exactHit = findArticleByCodeOrBarcode(code);
    if (exactHit && exactHit.art) {
      const inp = document.getElementById('cs-scan-input');
      if (inp) inp.value = '';
      const clearBtn = document.getElementById('cs-scan-clear');
      if (clearBtn) clearBtn.hidden = true;
      selectArticleForControlStock(exactHit.art, code);
      return;
    }

    // 2. Buscar por coincidencia de nombre / código parcial
    const q = normalizeStr(code);
    const tokens = q.split(/\s+/).filter(Boolean);
    const partialMatches = STATE.articulos.filter((art) => {
      if (art.bl === 1) return false;
      const bcs = Array.isArray(art.bc) ? art.bc.map((b) => b.c).join(' ') : '';
      const hay = normalizeStr(`${art.c} ${art.n} ${bcs}`);
      return tokens.every((t) => hay.includes(t));
    });

    if (partialMatches.length === 1) {
      const inp = document.getElementById('cs-scan-input');
      if (inp) inp.value = '';
      const clearBtn = document.getElementById('cs-scan-clear');
      if (clearBtn) clearBtn.hidden = true;
      selectArticleForControlStock(partialMatches[0], code);
      return;
    }

    if (partialMatches.length > 1) {
      renderControlStockSuggestions(code);
      return;
    }

    // No encontrado
    const idlePanel = document.getElementById('cs-idle-panel');
    const notFoundPanel = document.getElementById('cs-notfound-panel');
    const notFoundCode = document.getElementById('cs-notfound-code');
    if (idlePanel) idlePanel.hidden = true;
    if (notFoundCode) notFoundCode.textContent = code;
    if (notFoundPanel) notFoundPanel.hidden = false;
  }

  async function saveControlStockAdjustment(forceZeroDiff = false) {
    const art = CS_STATE.activeArt;
    if (!art) return;

    const allowFrac = doesArticleAllowFraction(art);
    const stockAnterior = round2(Number(art.sf) || 0);
    const diffInput = document.getElementById('cs-diff-input');
    const finalInput = document.getElementById('cs-final-stock-input');
    const motivoSelect = document.getElementById('cs-motivo-select');
    const obsInput = document.getElementById('cs-obs-input');

    let diff = forceZeroDiff
      ? 0
      : (allowFrac ? round2(Number(diffInput?.value) || 0) : Math.round(Number(diffInput?.value) || 0));
    let nuevoStock = forceZeroDiff
      ? (allowFrac ? stockAnterior : Math.round(stockAnterior))
      : (allowFrac
          ? round2(Number(finalInput?.value ?? stockAnterior + diff))
          : Math.round(Number(finalInput?.value ?? stockAnterior + diff)));

    // Sincronizar si el usuario editó directamente el stock físico final
    if (!forceZeroDiff && Math.abs(nuevoStock - (stockAnterior + diff)) > 0.001) {
      diff = allowFrac ? round2(nuevoStock - stockAnterior) : Math.round(nuevoStock - stockAnterior);
    }

    art.sf = allowFrac ? round2(nuevoStock) : Math.round(nuevoStock);
    if (!allowFrac) {
      art.si = Math.round(Number(art.si) || 0);
    }
    art.sc = allowFrac ? round2(art.sf - (Number(art.si) || 0)) : Math.round(art.sf - (Number(art.si) || 0));

    saveLocalFacturaProveedorArticleOverrides([art]);

    const saveBtn = document.getElementById('btn-cs-save-adjustment');
    if (saveBtn) {
      saveBtn.disabled = true;
      saveBtn.textContent = 'Guardando...';
    }

    try {
      await fetch('api/catalog.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'save_article',
          article: art
        })
      });
    } catch {}

    if (saveBtn) {
      saveBtn.disabled = false;
      saveBtn.textContent = '💾 Guardar Corrección de Stock';
    }

    const now = new Date();
    const fechaHora = `${todayFormatted()} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
    const motivo = motivoSelect?.value || 'CONTROL DE GÓNDOLA';
    const obs = String(obsInput?.value || '').trim().toUpperCase();
    const ean = Array.isArray(art.bc) && art.bc.length > 0 ? art.bc[0].c : art.c;
    const usuario = STATE.activeAdmin?.name || STATE.activeAdmin?.username || 'OPERADOR';

    CS_STATE.history.unshift({
      id: Date.now() + Math.floor(Math.random() * 1000),
      fechaHora,
      artId: art.id,
      codInterno: art.c,
      ean,
      nombre: art.n,
      stockAnterior,
      diferencia: diff,
      stockNuevo: art.sf,
      motivo: obs ? `${motivo} (${obs})` : motivo,
      usuario
    });

    saveControlStockHistory();
    renderControlStockHistoryTable();

    // Limpiar el artículo activo tras guardar y dejar foco listo para escanear el siguiente
    clearControlStockActiveArticle(true);
    updateKpis();
    applyCatalogFilters(STATE.currentPage);
  }

  function renderControlStockHistoryTable() {
    const tbody = document.getElementById('cs-history-tbody');
    const counterEl = document.getElementById('cs-history-counter');
    if (!tbody) return;

    if (counterEl) {
      counterEl.textContent = `${CS_STATE.history.length} control${CS_STATE.history.length === 1 ? '' : 'es'} registrado${CS_STATE.history.length === 1 ? '' : 's'}`;
    }

    tbody.textContent = '';
    if (CS_STATE.history.length === 0) {
      const tr = document.createElement('tr');
      const td = document.createElement('td');
      td.colSpan = 8;
      td.className = 'table-loading-cell';
      td.textContent = 'Aún no se realizaron controles de stock en góndola.';
      tr.appendChild(td);
      tbody.appendChild(tr);
      return;
    }

    const frag = document.createDocumentFragment();
    CS_STATE.history.slice(0, 60).forEach((item) => {
      const tr = document.createElement('tr');
      const diff = round2(Number(item.diferencia) || 0);
      const diffLabel = diff > 0 ? `+${diff}` : String(diff);
      const diffBadgeClass =
        Math.abs(diff) < 0.001
          ? 'badge'
          : diff > 0
          ? 'badge badge--green'
          : 'mini-tag mini-tag--baja';

      tr.innerHTML = `
        <td><span class="code-mono-input">${escapeHtml(item.fechaHora || '')}</span></td>
        <td>
          <div class="price-cell-stack">
            <span class="art-code-pill">#${escapeHtml(item.codInterno || '')}</span>
            <span class="price-neto-val">${escapeHtml(item.ean || '')}</span>
          </div>
        </td>
        <td><strong>${escapeHtml(item.nombre || '')}</strong></td>
        <td class="num-col"><strong>${round2(item.stockAnterior || 0)}</strong></td>
        <td class="num-col"><span class="${diffBadgeClass}">${escapeHtml(diffLabel)}</span></td>
        <td class="num-col"><strong style="font-size:1.05rem;">${round2(item.stockNuevo || 0)}</strong></td>
        <td>
          <div class="price-cell-stack">
            <span>${escapeHtml(item.motivo || 'CONTROL DE GÓNDOLA')}</span>
            <span class="price-neto-val">👤 ${escapeHtml(item.usuario || 'OPERADOR')}</span>
          </div>
        </td>
        <td class="actions-col"></td>
      `;

      const actionTd = tr.querySelector('.actions-col');
      if (actionTd) {
        const btnWrap = document.createElement('div');
        btnWrap.style.display = 'inline-flex';
        btnWrap.style.gap = '0.35rem';
        btnWrap.style.alignItems = 'center';

        const btnSelect = document.createElement('button');
        btnSelect.type = 'button';
        btnSelect.className = 'btn-secondary btn-sm';
        btnSelect.style.width = 'auto';
        btnSelect.textContent = '🔎 Ver';
        btnSelect.title = 'Cargar este artículo en el panel de control de stock';
        btnSelect.addEventListener('click', () => {
          const found = STATE.articulos.find((a) => Number(a.id) === Number(item.artId) || String(a.c) === String(item.codInterno));
          if (found) {
            selectArticleForControlStock(found, item.ean || found.c);
            window.scrollTo({ top: 0, behavior: 'smooth' });
          }
        });
        btnWrap.appendChild(btnSelect);

        const btnDel = document.createElement('button');
        btnDel.type = 'button';
        btnDel.className = 'btn-secondary btn-sm cs-btn-clear-article';
        btnDel.style.width = 'auto';
        btnDel.textContent = '🗑️';
        btnDel.title = 'Borrar este registro del historial';
        btnDel.addEventListener('click', () => {
          CS_STATE.history = CS_STATE.history.filter((h) => h.id !== item.id);
          saveControlStockHistory();
          renderControlStockHistoryTable();
        });
        btnWrap.appendChild(btnDel);

        actionTd.appendChild(btnWrap);
      }

      frag.appendChild(tr);
    });
    tbody.appendChild(frag);
  }

  // =========================================================================
  // SOPORTE UNIVERSAL DE LECTURA DE CÓDIGOS DE BARRAS Y QR EN iOS (iPhone / iPad)
  // Y NAVEGADORES SIN BarcodeDetector NATIVO (MEDIANTE ZXING RGBLuminanceSource + AUTO-CONTRASTE)
  // =========================================================================
  let zxingOneDReaderInstance = null;
  let zxingQrReaderInstance = null;
  let zxingMultiReaderInstance = null;
  let zxingScratchCanvas = null;

  const isIOSOrSafariWebKit = () => {
    const ua = String(navigator.userAgent || '');
    return (
      /iPad|iPhone|iPod/i.test(ua) ||
      (navigator.platform === 'MacIntel' && Number(navigator.maxTouchPoints) > 1) ||
      (/^((?!chrome|android).)*safari/i.test(ua))
    );
  };

  function getZXingReaders() {
    const ZX = window.ZXing;
    if (!ZX) return null;
    if (!zxingMultiReaderInstance && ZX.MultiFormatReader) {
      const hints = new Map();
      if (ZX.DecodeHintType && ZX.BarcodeFormat) {
        hints.set(ZX.DecodeHintType.TRY_HARDER, true);
        hints.set(ZX.DecodeHintType.POSSIBLE_FORMATS, [
          ZX.BarcodeFormat.EAN_13,
          ZX.BarcodeFormat.EAN_8,
          ZX.BarcodeFormat.UPC_A,
          ZX.BarcodeFormat.UPC_E,
          ZX.BarcodeFormat.CODE_128,
          ZX.BarcodeFormat.CODE_39,
          ZX.BarcodeFormat.ITF,
          ZX.BarcodeFormat.QR_CODE
        ]);
      }
      if (ZX.MultiFormatOneDReader) {
        zxingOneDReaderInstance = new ZX.MultiFormatOneDReader(hints);
      }
      if (ZX.QRCodeReader) {
        zxingQrReaderInstance = new ZX.QRCodeReader();
      }
      const multi = new ZX.MultiFormatReader();
      multi.setHints(hints);
      zxingMultiReaderInstance = { multi, oneD: zxingOneDReaderInstance, qr: zxingQrReaderInstance, hints };
    }
    return zxingMultiReaderInstance;
  }

  function decodeZXingGrayBuffer(ZX, readers, grayBuf, w, h, tryQr = true) {
    if (!ZX || !readers || !ZX.RGBLuminanceSource || w < 16 || h < 16) return null;
    // Usamos RGBLuminanceSource con 1 byte por píxel para evitar el bug de rotate(-90) de HTMLCanvasElementLuminanceSource en zxing.min.js
    try {
      const lumHist = new ZX.RGBLuminanceSource(grayBuf, w, h);
      const bmpHist = new ZX.BinaryBitmap(new ZX.GlobalHistogramBinarizer(lumHist));
      if (readers.oneD) {
        try {
          const r1 = readers.oneD.decode(bmpHist, readers.hints);
          if (r1 && r1.getText()) return String(r1.getText()).trim();
        } catch {}
      } else if (readers.multi) {
        try {
          const r1 = readers.multi.decodeWithState(bmpHist);
          if (r1 && r1.getText()) return String(r1.getText()).trim();
        } catch {}
      }
    } catch {}

    try {
      const lumHyb = new ZX.RGBLuminanceSource(grayBuf, w, h);
      const bmpHyb = new ZX.BinaryBitmap(new ZX.HybridBinarizer(lumHyb));
      if (readers.oneD) {
        try {
          const r2 = readers.oneD.decode(bmpHyb, readers.hints);
          if (r2 && r2.getText()) return String(r2.getText()).trim();
        } catch {}
      }
      if (tryQr && readers.qr) {
        try {
          const rQr = readers.qr.decode(bmpHyb, readers.hints);
          if (rQr && rQr.getText()) return String(rQr.getText()).trim();
        } catch {}
      } else if (!readers.oneD && readers.multi) {
        try {
          const rM = readers.multi.decodeWithState(bmpHyb);
          if (rM && rM.getText()) return String(rM.getText()).trim();
        } catch {}
      }
    } catch {}
    return null;
  }

  function tryDecodeCanvasWithZXing(canvas, opts = {}) {
    const ZX = window.ZXing;
    const readers = getZXingReaders();
    if (!ZX || !readers || !canvas || canvas.width < 16 || canvas.height < 16) return null;
    const w = canvas.width;
    const h = canvas.height;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return null;

    let rgba;
    try {
      rgba = ctx.getImageData(0, 0, w, h).data;
    } catch {
      return null;
    }

    const len = w * h;
    const rawGray = new Uint8ClampedArray(len);
    let minL = 255;
    let maxL = 0;

    for (let i = 0, p = 0; i < len; i++, p += 4) {
      const lum = (306 * rgba[p] + 601 * rgba[p + 1] + 117 * rgba[p + 2] + 512) >> 10;
      rawGray[i] = lum;
      if (lum < minL) minL = lum;
      if (lum > maxL) maxL = lum;
    }

    // 1) Pase directo en escala de grises original
    const hitRaw = decodeZXingGrayBuffer(ZX, readers, rawGray, w, h, true);
    if (hitRaw) return hitRaw;

    // 2) Pase con estiramiento de contraste (Auto-Levels) crucial en iPhone cuando la cámara está cerca o con reflejo de góndola
    const range = maxL - minL;
    let normGray = rawGray;
    if (range >= 18 && range < 245) {
      normGray = new Uint8ClampedArray(len);
      const scale = 255 / range;
      for (let i = 0; i < len; i++) {
        normGray[i] = Math.min(255, Math.max(0, Math.round((rawGray[i] - minL) * scale)));
      }
      const hitNorm = decodeZXingGrayBuffer(ZX, readers, normGray, w, h, true);
      if (hitNorm) return hitNorm;
    }

    // 3) Pase rotado 90° real (con ancho y alto intercambiados correctamente) para códigos verticales en iPhone
    if (opts.allowRotate90 !== false) {
      const rotGray = new Uint8ClampedArray(len);
      for (let y = 0; y < h; y++) {
        const rowOff = y * w;
        const dstCol = h - 1 - y;
        for (let x = 0; x < w; x++) {
          rotGray[x * h + dstCol] = normGray[rowOff + x];
        }
      }
      const hitRot = decodeZXingGrayBuffer(ZX, readers, rotGray, h, w, false);
      if (hitRot) return hitRot;
    }

    return null;
  }

  window.decodeBarcodeFromVideoOrImage = async function decodeBarcodeFromVideoOrImage(source, opts = {}) {
    if (!source) return null;
    const isVideo = source instanceof HTMLVideoElement;
    const srcW = isVideo ? (source.videoWidth || 0) : (source.naturalWidth || source.width || 0);
    const srcH = isVideo ? (source.videoHeight || 0) : (source.naturalHeight || source.height || 0);
    if (srcW < 32 || srcH < 32) return null;

    if (!zxingScratchCanvas) {
      zxingScratchCanvas = document.createElement('canvas');
    }
    const ctx = zxingScratchCanvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return null;

    const pickBestErpDetectedCode = (codes) => {
      if (!Array.isArray(codes) || codes.length === 0) return null;
      const vals = codes
        .map((c) => (c && c.rawValue ? String(c.rawValue).trim() : ''))
        .filter(Boolean);
      if (vals.length === 0) return null;
      for (const v of vals) {
        if (/^(FM-|CF-|https?:|\{)/i.test(v)) return v;
        const hit = findArticleByCodeOrBarcode(v);
        if (hit && hit.art) return v;
      }
      vals.sort((a, b) => b.length - a.length);
      return vals[0];
    };

    // 1. Si el navegador NO es iOS Safari y tiene BarcodeDetector nativo (ej. Android Chrome), probar rápido con timeout para no bloquear si Play Services tarda o falla
    if (window.__nativeBarcodeDetectorClass && !isIOSOrSafariWebKit()) {
      try {
        if (!window.__nativeBarcodeDetectorInstance) {
          window.__nativeBarcodeDetectorInstance = new window.__nativeBarcodeDetectorClass({
            formats: ['ean_13', 'ean_8', 'upc_a', 'upc_e', 'code_128', 'code_39', 'itf', 'qr_code']
          });
        }
        const nativeRes = await Promise.race([
          window.__nativeBarcodeDetectorInstance.detect(source),
          new Promise((r) => setTimeout(() => r(null), 90))
        ]);
        const bestNative = pickBestErpDetectedCode(nativeRes);
        if (bestNative) {
          return bestNative;
        }
      } catch {}
    }

    const zoomFactor = Number(opts.zoom) > 1 ? Number(opts.zoom) : 1;
    // Regiones de escaneo optimizadas para Android, iOS / iPhone y fotos de alta resolución:
    // a) Franja horizontal central (puntería de código de barras 1D)
    // b) Recorte central medio (con soporte de rotación 90°)
    // c) Cuadro completo
    const regions = zoomFactor > 1
      ? [
          { x: 0.16, y: 0.30, w: 0.68, h: 0.40, maxW: 960, rot90: true },
          { x: 0.10, y: 0.15, w: 0.80, h: 0.70, maxW: 840, rot90: true }
        ]
      : [
          { x: 0.05, y: 0.28, w: 0.90, h: 0.44, maxW: 960, rot90: false },
          { x: 0.12, y: 0.18, w: 0.76, h: 0.64, maxW: 800, rot90: true },
          { x: 0.0, y: 0.0, w: 1.0, h: 1.0, maxW: 720, rot90: true }
        ];

    for (const reg of regions) {
      const sx = Math.floor(srcW * reg.x);
      const sy = Math.floor(srcH * reg.y);
      const sw = Math.max(32, Math.floor(srcW * reg.w));
      const sh = Math.max(32, Math.floor(srcH * reg.h));
      const scale = sw > reg.maxW ? reg.maxW / sw : 1;
      const dw = Math.max(32, Math.round(sw * scale));
      const dh = Math.max(32, Math.round(sh * scale));

      zxingScratchCanvas.width = dw;
      zxingScratchCanvas.height = dh;
      ctx.drawImage(source, sx, sy, sw, sh, 0, 0, dw, dh);

      // Probar BarcodeDetector nativo sobre el Canvas recortado con timeout corto (tanto en Android como en iOS)
      if (window.__nativeBarcodeDetectorClass) {
        try {
          if (!window.__nativeBarcodeDetectorInstance) {
            window.__nativeBarcodeDetectorInstance = new window.__nativeBarcodeDetectorClass({
              formats: ['ean_13', 'ean_8', 'upc_a', 'upc_e', 'code_128', 'code_39', 'itf', 'qr_code']
            });
          }
          const nativeCanvasRes = await Promise.race([
            window.__nativeBarcodeDetectorInstance.detect(zxingScratchCanvas),
            new Promise((r) => setTimeout(() => r(null), 60))
          ]);
          const bestCanvasNative = pickBestErpDetectedCode(nativeCanvasRes);
          if (bestCanvasNative) {
            return bestCanvasNative;
          }
        } catch {}
      }

      const decoded = tryDecodeCanvasWithZXing(zxingScratchCanvas, { allowRotate90: reg.rot90 });
      if (decoded) return decoded;
    }

    return null;
  };

  // Instalar polyfill global de window.BarcodeDetector siempre en iOS/Safari o cuando falte soporte nativo completo
  (async function initUniversalBarcodeDetectorPolyfill() {
    if ('BarcodeDetector' in window && typeof window.BarcodeDetector === 'function') {
      try {
        window.__nativeBarcodeDetectorClass = window.BarcodeDetector;
      } catch {}
    }

    window.BarcodeDetector = class ZXingBarcodeDetectorPolyfill {
      constructor(options = {}) {
        this.formats = options.formats || ['ean_13', 'ean_8', 'upc_a', 'upc_e', 'code_128', 'code_39', 'itf', 'qr_code'];
      }
      static async getSupportedFormats() {
        return ['ean_13', 'ean_8', 'upc_a', 'upc_e', 'code_128', 'code_39', 'itf', 'qr_code'];
      }
      async detect(imageSource) {
        const val = await window.decodeBarcodeFromVideoOrImage(imageSource, {
          zoom: CS_STATE?.cameraZoom || 1
        });
        return val ? [{ rawValue: val }] : [];
      }
    };
  })();

  async function startControlStockCamera(preferredDeviceId = null) {
    const camPanel = document.getElementById('cs-camera-panel');
    const video = document.getElementById('cs-camera-video');
    const statusEl = document.getElementById('cs-camera-status');
    const btnSwitch = document.getElementById('btn-cs-camera-switch');
    const btnZoom = document.getElementById('btn-cs-camera-zoom');
    if (!camPanel || !video) return;

    camPanel.hidden = false;
    video.setAttribute('playsinline', '');
    video.setAttribute('webkit-playsinline', '');
    video.setAttribute('autoplay', '');
    video.muted = true;

    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      if (statusEl) {
        statusEl.textContent = 'El navegador actual no permite video en vivo. Tocá "📸 Captura Nítida" arriba para escanear con la cámara del teléfono.';
      }
      return;
    }

    try {
      if (CS_STATE.cameraScanTimer) {
        clearInterval(CS_STATE.cameraScanTimer);
        CS_STATE.cameraScanTimer = null;
      }
      if (CS_STATE.cameraRafId) {
        cancelAnimationFrame(CS_STATE.cameraRafId);
        CS_STATE.cameraRafId = null;
      }
      if (CS_STATE.cameraStream) {
        CS_STATE.cameraStream.getTracks().forEach((t) => t.stop());
        CS_STATE.cameraStream = null;
      }

      if (statusEl) {
        statusEl.textContent = 'Iniciando cámara para lectura de código de barras / QR...';
      }

      const activeDeviceId = preferredDeviceId || CS_STATE.selectedDeviceId || null;
      const videoConstraints = activeDeviceId
        ? {
            deviceId: { exact: activeDeviceId },
            width: { ideal: 1280 },
            height: { ideal: 720 }
          }
        : {
            facingMode: { ideal: 'environment' },
            width: { ideal: 1280 },
            height: { ideal: 720 }
          };

      let stream;
      try {
        stream = await navigator.mediaDevices.getUserMedia({
          video: videoConstraints,
          audio: false
        });
      } catch {
        stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'environment' },
          audio: false
        });
      }

      CS_STATE.cameraStream = stream;
      CS_STATE.cameraZoom = CS_STATE.cameraZoom || 1;
      video.srcObject = stream;
      await video.play().catch(() => {});

      const videoTrack = stream.getVideoTracks()[0];
      if (videoTrack) {
        const settings = typeof videoTrack.getSettings === 'function' ? videoTrack.getSettings() : {};
        if (settings.deviceId) {
          CS_STATE.selectedDeviceId = settings.deviceId;
        }
        // En iOS WebKit evitamos focusMode:'continuous' dentro de applyConstraints porque puede congelar el track de video
        if (!isIOSOrSafariWebKit() && typeof videoTrack.getCapabilities === 'function') {
          try {
            const caps = videoTrack.getCapabilities() || {};
            const adv = {};
            if (Array.isArray(caps.focusMode) && caps.focusMode.includes('continuous')) {
              adv.focusMode = 'continuous';
            }
            if (caps.zoom && CS_STATE.cameraZoom > 1) {
              const targetZoom = Math.min(caps.zoom.max || 2, Math.max(caps.zoom.min || 1, CS_STATE.cameraZoom));
              adv.zoom = targetZoom;
            }
            if (Object.keys(adv).length > 0 && typeof videoTrack.applyConstraints === 'function') {
              await videoTrack.applyConstraints({ advanced: [adv] }).catch(() => {});
            }
          } catch {}
        }
      }

      // Aplicar zoom visual si está activo en 2x
      video.style.transform = CS_STATE.cameraZoom > 1 ? 'scale(1.85)' : 'none';
      video.style.transformOrigin = 'center center';
      if (btnZoom) {
        btnZoom.textContent = CS_STATE.cameraZoom > 1 ? '🔍 Zoom 1x' : '🔍 Zoom 2x';
      }

      // Listar cámaras traseras disponibles para permitir cambiar al lente Macro / Ultra Gran Angular en iPhone
      if (navigator.mediaDevices.enumerateDevices && btnSwitch) {
        try {
          const allDevs = await navigator.mediaDevices.enumerateDevices();
          const videoDevs = allDevs.filter((d) => d.kind === 'videoinput');
          const rearDevs = videoDevs.filter((d) => /back|rear|trasera|environment|triple|dual|ultra|wide/i.test(d.label));
          CS_STATE.availableCameras = rearDevs.length >= 2 ? rearDevs : videoDevs;
          btnSwitch.hidden = CS_STATE.availableCameras.length < 2;
        } catch {}
      }

      if (statusEl) {
        statusEl.textContent = 'Apuntá al código de barras dentro del recuadro. En iPhone podés tocar "🔍 Zoom 2x" o "🔄 Cambiar Lente" para foco cercano.';
      }

      let isDecodingFrame = false;
      let csPendingUnknown = '';
      let csPendingHits = 0;
      CS_STATE.cameraScanTimer = setInterval(async () => {
        if (!CS_STATE.cameraStream || camPanel.hidden || isDecodingFrame) return;
        if (video.paused && !video.ended) {
          video.play().catch(() => {});
        }
        if (video.readyState < 2 || !video.videoWidth) return;
        isDecodingFrame = true;
        try {
          const code = await window.decodeBarcodeFromVideoOrImage(video, {
            zoom: CS_STATE.cameraZoom || 1
          });
          if (code) {
            const isQrLike = /^(FM-|CF-|https?:|\{)/i.test(code);
            const hit = findArticleByCodeOrBarcode(code);
            if (!isQrLike && !(hit && hit.art)) {
              if (code === csPendingUnknown) csPendingHits += 1;
              else {
                csPendingUnknown = code;
                csPendingHits = 1;
              }
              if (csPendingHits < 3) return;
            }
            csPendingUnknown = '';
            csPendingHits = 0;
            window.stopControlStockCamera();
            handleControlStockScanSubmit(code);
          }
        } catch {} finally {
          isDecodingFrame = false;
        }
      }, 120);
    } catch {
      if (statusEl) {
        statusEl.textContent = 'No se pudo iniciar el video en vivo. Podés tocar "📸 Captura Nítida" arriba para tomar foto del código o usar el buscador.';
      }
    }
  }

  window.stopControlStockCamera = function stopControlStockCamera() {
    if (CS_STATE.cameraScanTimer) {
      clearInterval(CS_STATE.cameraScanTimer);
      CS_STATE.cameraScanTimer = null;
    }
    if (CS_STATE.cameraRafId) {
      cancelAnimationFrame(CS_STATE.cameraRafId);
      CS_STATE.cameraRafId = null;
    }
    if (CS_STATE.cameraStream) {
      CS_STATE.cameraStream.getTracks().forEach((t) => t.stop());
      CS_STATE.cameraStream = null;
    }
    const video = document.getElementById('cs-camera-video');
    if (video) {
      video.srcObject = null;
      video.style.transform = 'none';
    }
    const camPanel = document.getElementById('cs-camera-panel');
    if (camPanel) camPanel.hidden = true;
  };

  // =========================================================================
  // ESCÁNER UNIVERSAL DE CÓDIGO DE BARRAS Y QR PARA FACTURADOR Y ARTÍCULOS (ANDROID / iOS / PWA)
  // =========================================================================
  const UNI_SCAN_STATE = {
    stream: null,
    timer: null,
    zoom: 1,
    selectedDeviceId: null,
    availableCameras: [],
    onDetect: null,
    continuous: false,
    lastCode: '',
    lastTime: 0
  };

  function playScannerSuccessBeep() {
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;
      const ctx = new AudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(1046.5, ctx.currentTime);
      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.11);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.12);
      setTimeout(() => {
        try { ctx.close(); } catch {}
      }, 250);
    } catch {}
  }

  window.stopUniversalBarcodeScanner = function stopUniversalBarcodeScanner() {
    if (UNI_SCAN_STATE.timer) {
      clearInterval(UNI_SCAN_STATE.timer);
      UNI_SCAN_STATE.timer = null;
    }
    if (UNI_SCAN_STATE.stream) {
      UNI_SCAN_STATE.stream.getTracks().forEach((t) => t.stop());
      UNI_SCAN_STATE.stream = null;
    }
    const video = document.getElementById('uni-scan-video');
    if (video) {
      video.srcObject = null;
      video.style.transform = 'none';
    }
    const dlg = document.getElementById('universal-barcode-scanner-dialog');
    if (dlg && dlg.open) {
      dlg.close();
    }
  };

  async function startUniversalScannerStream(preferredDeviceId = null) {
    const video = document.getElementById('uni-scan-video');
    const statusEl = document.getElementById('uni-scan-status');
    const btnSwitch = document.getElementById('btn-uni-scan-switch');
    const btnZoom = document.getElementById('btn-uni-scan-zoom');
    if (!video) return;

    video.setAttribute('playsinline', '');
    video.setAttribute('webkit-playsinline', '');
    video.setAttribute('autoplay', '');
    video.muted = true;

    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      if (statusEl) {
        statusEl.textContent = 'Tocá "📸 Captura Nítida" arriba para tomar la foto del código con la cámara.';
      }
      return;
    }

    try {
      if (UNI_SCAN_STATE.timer) {
        clearInterval(UNI_SCAN_STATE.timer);
        UNI_SCAN_STATE.timer = null;
      }
      if (UNI_SCAN_STATE.stream) {
        UNI_SCAN_STATE.stream.getTracks().forEach((t) => t.stop());
        UNI_SCAN_STATE.stream = null;
      }

      if (statusEl) {
        statusEl.textContent = 'Iniciando cámara para lectura de Código de Barras / QR...';
      }

      const activeDeviceId = preferredDeviceId || UNI_SCAN_STATE.selectedDeviceId || null;
      const videoConstraints = activeDeviceId
        ? { deviceId: { exact: activeDeviceId }, width: { ideal: 1280 }, height: { ideal: 720 } }
        : { facingMode: { ideal: 'environment' }, width: { ideal: 1280 }, height: { ideal: 720 } };

      let stream;
      try {
        stream = await navigator.mediaDevices.getUserMedia({ video: videoConstraints, audio: false });
      } catch {
        stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' }, audio: false });
      }

      UNI_SCAN_STATE.stream = stream;
      video.srcObject = stream;
      await video.play().catch(() => {});

      const videoTrack = stream.getVideoTracks()[0];
      if (videoTrack) {
        const settings = typeof videoTrack.getSettings === 'function' ? videoTrack.getSettings() : {};
        if (settings.deviceId) {
          UNI_SCAN_STATE.selectedDeviceId = settings.deviceId;
        }
        if (!isIOSOrSafariWebKit() && typeof videoTrack.getCapabilities === 'function') {
          try {
            const caps = videoTrack.getCapabilities() || {};
            const adv = {};
            if (Array.isArray(caps.focusMode) && caps.focusMode.includes('continuous')) {
              adv.focusMode = 'continuous';
            }
            if (caps.zoom && UNI_SCAN_STATE.zoom > 1) {
              adv.zoom = Math.min(caps.zoom.max || 2, Math.max(caps.zoom.min || 1, UNI_SCAN_STATE.zoom));
            }
            if (Object.keys(adv).length > 0 && typeof videoTrack.applyConstraints === 'function') {
              await videoTrack.applyConstraints({ advanced: [adv] }).catch(() => {});
            }
          } catch {}
        }
      }

      video.style.transform = UNI_SCAN_STATE.zoom > 1 ? 'scale(1.85)' : 'none';
      video.style.transformOrigin = 'center center';
      if (btnZoom) {
        btnZoom.textContent = UNI_SCAN_STATE.zoom > 1 ? '🔍 Zoom 1x' : '🔍 Zoom 2x';
      }

      if (navigator.mediaDevices.enumerateDevices && btnSwitch) {
        try {
          const devices = await navigator.mediaDevices.enumerateDevices();
          const videoInputs = devices.filter((d) => d.kind === 'videoinput');
          const backCams = videoInputs.filter((d) => /back|rear|trasera|environment|wide|ultra|macro/i.test(d.label || ''));
          UNI_SCAN_STATE.availableCameras = backCams.length >= 2 ? backCams : videoInputs;
          btnSwitch.hidden = UNI_SCAN_STATE.availableCameras.length < 2;
        } catch {}
      }

      if (statusEl) {
        statusEl.textContent = isIOSOrSafariWebKit()
          ? 'Apuntá al código de barras o QR (si es pequeño usá 🔍 Zoom 2x o 📸 Captura Nítida).'
          : 'Apuntá la cámara al código de barras (EAN) o código QR...';
      }

      let busy = false;
      let uniPendingUnknown = '';
      let uniPendingHits = 0;
      UNI_SCAN_STATE.timer = setInterval(async () => {
        if (busy || !UNI_SCAN_STATE.stream) return;
        if (video.paused && !video.ended) {
          video.play().catch(() => {});
        }
        if (video.readyState < 2) return;
        busy = true;
        try {
          const rawCode = await Promise.race([
            window.decodeBarcodeFromVideoOrImage(video, {
              zoom: UNI_SCAN_STATE.zoom || 1
            }),
            new Promise((r) => setTimeout(() => r(null), 420))
          ]);
          if (rawCode) {
            const isQrLike = /^(FM-|CF-|https?:|\{)/i.test(rawCode);
            const hit = findArticleByCodeOrBarcode(rawCode);
            if (!isQrLike && !(hit && hit.art)) {
              if (rawCode === uniPendingUnknown) uniPendingHits += 1;
              else {
                uniPendingUnknown = rawCode;
                uniPendingHits = 1;
              }
              if (uniPendingHits < 3) {
                busy = false;
                return;
              }
            }
            uniPendingUnknown = '';
            uniPendingHits = 0;

            const now = Date.now();
            if (rawCode === UNI_SCAN_STATE.lastCode && now - UNI_SCAN_STATE.lastTime < 1600) {
              busy = false;
              return;
            }
            UNI_SCAN_STATE.lastCode = rawCode;
            UNI_SCAN_STATE.lastTime = now;
            playScannerSuccessBeep();

            const contChk = document.getElementById('uni-scan-continuous-chk');
            const keepOpen = UNI_SCAN_STATE.continuous && contChk && contChk.checked;
            const cb = UNI_SCAN_STATE.onDetect;

            if (!keepOpen) {
              window.stopUniversalBarcodeScanner();
            } else if (statusEl) {
              statusEl.textContent = `✅ Leído: ${rawCode} · Listo para escanear el siguiente...`;
            }

            if (typeof cb === 'function') {
              cb(rawCode);
            }
          }
        } catch {}
        busy = false;
      }, 150);
    } catch {
      if (statusEl) {
        statusEl.textContent = 'No se pudo acceder a la cámara en vivo. Tocá "📸 Captura Nítida" arriba para escanear tomando una foto.';
      }
    }
  }

  window.openUniversalBarcodeScanner = function openUniversalBarcodeScanner(options = {}) {
    const dlg = document.getElementById('universal-barcode-scanner-dialog');
    const titleEl = document.getElementById('uni-scan-dialog-title');
    const contWrap = document.getElementById('uni-scan-continuous-wrap');
    const contChk = document.getElementById('uni-scan-continuous-chk');
    if (!dlg) return;

    UNI_SCAN_STATE.onDetect = typeof options.onDetect === 'function' ? options.onDetect : null;
    UNI_SCAN_STATE.continuous = Boolean(options.continuous);
    UNI_SCAN_STATE.lastCode = '';
    UNI_SCAN_STATE.lastTime = 0;

    if (titleEl) {
      titleEl.textContent = options.title || '📷 Lector de Código de Barras y QR';
    }
    if (contWrap) {
      contWrap.hidden = !UNI_SCAN_STATE.continuous;
    }
    if (contChk) {
      contChk.checked = UNI_SCAN_STATE.continuous;
    }

    if (document.fullscreenElement && document.fullscreenElement !== document.documentElement && !document.fullscreenElement.contains(dlg)) {
      try {
        document.exitFullscreen?.().catch(() => {});
      } catch {}
    }

    if (!dlg.open && typeof dlg.showModal === 'function') {
      dlg.showModal();
    }
    startUniversalScannerStream();
  };

