  document.getElementById('btn-uni-scan-zoom')?.addEventListener('click', async () => {
    UNI_SCAN_STATE.zoom = UNI_SCAN_STATE.zoom === 2 ? 1 : 2;
    const video = document.getElementById('uni-scan-video');
    const btnZoom = document.getElementById('btn-uni-scan-zoom');
    if (video) {
      video.style.transform = UNI_SCAN_STATE.zoom > 1 ? 'scale(1.85)' : 'none';
      video.style.transformOrigin = 'center center';
    }
    if (btnZoom) {
      btnZoom.textContent = UNI_SCAN_STATE.zoom > 1 ? '🔍 Zoom 1x' : '🔍 Zoom 2x';
    }
    if (UNI_SCAN_STATE.stream) {
      const track = UNI_SCAN_STATE.stream.getVideoTracks()[0];
      if (track && typeof track.getCapabilities === 'function' && typeof track.applyConstraints === 'function') {
        try {
          const caps = track.getCapabilities() || {};
          if (caps.zoom) {
            const z = Math.min(caps.zoom.max || 2, Math.max(caps.zoom.min || 1, UNI_SCAN_STATE.zoom));
            await track.applyConstraints({ advanced: [{ zoom: z }] }).catch(() => {});
          }
        } catch {}
      }
    }
  });

  document.getElementById('btn-uni-scan-switch')?.addEventListener('click', () => {
    const cams = Array.isArray(UNI_SCAN_STATE.availableCameras) ? UNI_SCAN_STATE.availableCameras : [];
    if (cams.length < 2) return;
    const curIdx = cams.findIndex((c) => c.deviceId === UNI_SCAN_STATE.selectedDeviceId);
    const nextCam = cams[(curIdx + 1) % cams.length];
    if (nextCam && nextCam.deviceId) {
      UNI_SCAN_STATE.selectedDeviceId = nextCam.deviceId;
      startUniversalScannerStream(nextCam.deviceId);
    }
  });

  document.getElementById('uni-scan-photo-fallback')?.addEventListener('change', async (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const statusEl = document.getElementById('uni-scan-status');
    if (statusEl) statusEl.textContent = 'Analizando fotografía en alta resolución...';
    try {
      const imgUrl = URL.createObjectURL(file);
      const img = new Image();
      const loaded = await new Promise((resolve) => {
        img.onload = () => resolve(true);
        img.onerror = () => resolve(false);
        img.src = imgUrl;
      });
      if (loaded) {
        let code = await window.decodeBarcodeFromVideoOrImage(img, { zoom: 1 });
        if (!code) {
          code = await window.decodeBarcodeFromVideoOrImage(img, { zoom: 2 });
        }
        URL.revokeObjectURL(imgUrl);
        if (code) {
          playScannerSuccessBeep();
          const cb = UNI_SCAN_STATE.onDetect;
          window.stopUniversalBarcodeScanner();
          if (typeof cb === 'function') cb(code);
          e.target.value = '';
          return;
        }
      } else {
        URL.revokeObjectURL(imgUrl);
      }
      if (statusEl) {
        statusEl.textContent = 'No se detectó un código nítido en la foto. Intentá acercar más el código o usar Zoom 2x.';
      }
    } catch {
      if (statusEl) {
        statusEl.textContent = 'No se pudo procesar la foto tomada.';
      }
    }
    e.target.value = '';
  });

