  const handleFacturadorCameraScan = () => {
    window.openUniversalBarcodeScanner({
      title: '📷 Escanear Producto / QR en Facturador',
      continuous: true,
      onDetect: (rawCode) => {
        const cleaned = extractCodeFromBarcodeOrQrPayload(rawCode) || sanitizeScannerBarcode(rawCode) || String(rawCode || '').trim();
        if (!cleaned) return;
        const codeInp = document.getElementById('fact-first-code-input');
        if (!codeInp) return;
        codeInp.value = cleaned;
        codeInp.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true, cancelable: true }));
        // Si el código no existía y se abrió el diálogo de código faltante, cerrar la cámara para que el usuario vea el diálogo
        const missingDlg = document.getElementById('fact-missing-barcode-dialog');
        if (missingDlg && missingDlg.open) {
          window.stopUniversalBarcodeScanner();
        }
      }
    });
  };
