  document.getElementById('btn-scan-barcode-modal')?.addEventListener('click', () => {
    window.openUniversalBarcodeScanner({
      title: '📷 Escanear Código de Barras para este Artículo',
      continuous: false,
      onDetect: (rawCode) => {
        const cleaned = sanitizeScannerBarcode(rawCode) || extractCodeFromBarcodeOrQrPayload(rawCode) || String(rawCode || '').trim();
        if (!cleaned) return;
        const container = document.getElementById('barcodes-rows-container');
        if (!container) return;
        const existingInputs = Array.from(container.querySelectorAll('.bc-code-input'));
        const emptyInp = existingInputs.find((inp) => !inp.value.trim());
        if (emptyInp) {
          emptyInp.value = cleaned;
          emptyInp.dispatchEvent(new Event('input', { bubbles: true }));
          emptyInp.focus();
        } else {
          const newRow = createBarcodeRowElement(cleaned, 1);
          container.appendChild(newRow);
          const newInp = newRow.querySelector('.bc-code-input');
          if (newInp) {
            newInp.dispatchEvent(new Event('input', { bubbles: true }));
            newInp.focus();
          }
        }
      }
    });
  });

