  function populateStockNegativoFilterSelects() {
    const rubSel = document.getElementById('sn-filter-rubro');
    const marSel = document.getElementById('sn-filter-marca');
    const provSel = document.getElementById('sn-filter-proveedor');

    if (rubSel) {
      const prevRub = rubSel.value;
      const rubros = Array.isArray(STATE.rubros) ? [...STATE.rubros].filter((r) => !r.bl) : [];
      rubros.sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es'));
      rubSel.innerHTML = '<option value="">Todos los rubros</option>' +
        rubros.map((r) => `<option value="${r.id}">${escapeHtml(r.nombre || '')}</option>`).join('');
      if (prevRub) rubSel.value = prevRub;
    }

    if (marSel) {
      const prevMar = marSel.value;
      const marcas = Array.isArray(STATE.marcas) ? [...STATE.marcas].filter((m) => !m.bl) : [];
      marcas.sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es'));
      marSel.innerHTML = '<option value="">Todas las marcas</option>' +
        marcas.map((m) => `<option value="${m.id}">${escapeHtml(m.nombre || '')}</option>`).join('');
      if (prevMar) marSel.value = prevMar;
    }

    if (provSel) {
      const prevProv = provSel.value;
      const provs = Array.isArray(STATE.proveedores) ? [...STATE.proveedores].filter((p) => !p.bl) : [];
      provs.sort((a, b) => String(a.nombre || a.razonSocial || '').localeCompare(String(b.nombre || b.razonSocial || ''), 'es'));
      provSel.innerHTML = '<option value="">Todos los proveedores</option>' +
        provs.map((p) => `<option value="${p.id}">${escapeHtml(p.nombre || p.razonSocial || `#${p.codigo || p.id}`)}</option>`).join('');
      if (prevProv) provSel.value = prevProv;
    }
  }

  function getNegativeStockArticlesList() {
    const qRaw = String(document.getElementById('sn-search-input')?.value || '').trim();
    const qNorm = normalizeStr(qRaw);
    const tokens = qNorm.split(/\s+/).filter(Boolean);
    const rubId = Number(document.getElementById('sn-filter-rubro')?.value || 0);
    const marId = Number(document.getElementById('sn-filter-marca')?.value || 0);
    const provId = Number(document.getElementById('sn-filter-proveedor')?.value || 0);
    const sortBy = String(document.getElementById('sn-sort-select')?.value || 'most_negative');

    const allNeg = (Array.isArray(STATE.articulos) ? STATE.articulos : []).filter((a) => {
      if (a.bl === 1) return false;
      const aid = Number(a.id) || 0;
      const codeClean = String(a.c || '').replace(/\D/g, '').replace(/^0+/, '');
      if (aid === 4407 || aid === 7860 || codeClean === '20' || codeClean === '3000') return false;
      const sf = round2(Number(a.sf) || 0);
      return sf < -0.0001;
    });

    const filtered = allNeg.filter((a) => {
      if (rubId > 0 && Number(a.r) !== rubId) return false;
      if (marId > 0 && Number(a.mk ?? a.m) !== marId) return false;
      if (provId > 0) {
        const mainP = Number(a.p) === provId;
        const inPr = Array.isArray(a.pr) && a.pr.some((item) => Number(item.p) === provId);
        if (!mainP && !inPr) return false;
      }
      if (tokens.length > 0) {
        const bcs = Array.isArray(a.bc) ? a.bc.map((b) => b.c).join(' ') : '';
        const hay = normalizeStr(`${a.c || ''} ${a.n || ''} ${bcs} ${a.cf || ''}`);
        if (!tokens.every((t) => hay.includes(t))) return false;
      }
      return true;
    });

    filtered.sort((a, b) => {
      const sfA = Number(a.sf) || 0;
      const sfB = Number(b.sf) || 0;
      if (sortBy === 'least_negative') return sfB - sfA;
      if (sortBy === 'name_asc') return String(a.n || '').localeCompare(String(b.n || ''), 'es');
      if (sortBy === 'code_asc') return String(a.c || '').localeCompare(String(b.c || ''), 'es', { numeric: true });
      return sfA - sfB; // most_negative: -100 first, then -1
    });

    return { allNeg, filtered };
  }

  function updateStockNegativoKpis(allNeg, filtered) {
    const totalArtsEl = document.getElementById('sn-kpi-total-arts');
    const filteredSubEl = document.getElementById('sn-kpi-filtered-sub');
    const totalUnitsEl = document.getElementById('sn-kpi-total-units');
    const selectedCountEl = document.getElementById('sn-kpi-selected-count');
    const selectedSubEl = document.getElementById('sn-kpi-selected-sub');
    const totalCostEl = document.getElementById('sn-kpi-total-cost');
    const badgeEl = document.getElementById('sn-list-counter-badge');
    const checkHeader = document.getElementById('sn-check-header');

    let sumNegUnits = 0;
    let sumNegCost = 0;
    filtered.forEach((a) => {
      const sf = round2(Number(a.sf) || 0);
      const costoFinal = Number(a.cfn ?? a.pcf ?? a.cn ?? a.pc) || 0;
      sumNegUnits += sf;
      sumNegCost += Math.abs(sf) * costoFinal;
    });

    const visibleSelectedCount = filtered.filter((a) => SN_STATE.selectedIds.has(Number(a.id))).length;

    if (totalArtsEl) totalArtsEl.textContent = filtered.length.toLocaleString('es-AR');
    if (filteredSubEl) {
      filteredSubEl.textContent = filtered.length === allNeg.length
        ? 'Total general en el padrón'
        : `Filtrados de ${allNeg.length.toLocaleString('es-AR')} en total`;
    }
    if (totalUnitsEl) totalUnitsEl.textContent = round2(sumNegUnits).toLocaleString('es-AR');
    if (selectedCountEl) selectedCountEl.textContent = visibleSelectedCount.toLocaleString('es-AR');
    if (selectedSubEl) {
      selectedSubEl.textContent = visibleSelectedCount === filtered.length && filtered.length > 0
        ? 'Todos los listados seleccionados'
        : `De ${filtered.length.toLocaleString('es-AR')} visibles`;
    }
    if (totalCostEl) totalCostEl.textContent = formatARS(sumNegCost);
    if (badgeEl) {
      badgeEl.textContent = `${filtered.length.toLocaleString('es-AR')} artículo${filtered.length === 1 ? '' : 's'} con stock negativo`;
    }
    if (checkHeader) {
      checkHeader.checked = filtered.length > 0 && visibleSelectedCount === filtered.length;
      checkHeader.indeterminate = visibleSelectedCount > 0 && visibleSelectedCount < filtered.length;
    }
  }

  async function applyStockNegativoCorrectionBatch(itemsToFix, successLabel = '') {
    if (!Array.isArray(itemsToFix) || itemsToFix.length === 0) {
      showStockNegativoFeedback('⚠️ No hay artículos seleccionados para corregir.', true);
      return;
    }

    const normalizedItems = itemsToFix.map((it) => ({
      id: Number(it.id),
      sf: round2(Number(it.sf) || 0)
    })).filter((it) => it.id > 0 && Number.isFinite(it.sf));

    if (normalizedItems.length === 0) return;

    const btnZero = document.getElementById('btn-sn-fix-all-zero');
    const btnSaveAll = document.getElementById('btn-sn-save-all-rows');
    if (btnZero) btnZero.disabled = true;
    if (btnSaveAll) btnSaveAll.disabled = true;

    const byId = new Map(normalizedItems.map((it) => [it.id, it.sf]));
    const modifiedArticles = [];

    const now = new Date();
    const fechaHora = `${todayFormatted()} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
    const usuario = STATE.activeAdmin?.name || STATE.activeAdmin?.username || 'OPERADOR';

    STATE.articulos.forEach((art) => {
      const aid = Number(art.id);
      if (byId.has(aid)) {
        const stockAnterior = round2(Number(art.sf) || 0);
        const nuevoStock = byId.get(aid);
        const diff = round2(nuevoStock - stockAnterior);
        art.sf = nuevoStock;
        art.sc = round2(nuevoStock - (Number(art.si) || 0));
        modifiedArticles.push(art);
        delete SN_STATE.draftStockById[aid];
        if (nuevoStock >= 0) {
          SN_STATE.selectedIds.delete(aid);
        }

        const ean = Array.isArray(art.bc) && art.bc.length > 0 ? art.bc[0].c : art.c;
        CS_STATE.history.unshift({
          id: Date.now() + Math.floor(Math.random() * 100000),
          fechaHora,
          artId: art.id,
          codInterno: art.c,
          ean,
          nombre: art.n,
          stockAnterior,
          diferencia: diff,
          stockNuevo: art.sf,
          motivo: 'CORRECCIÓN STOCK NEGATIVO',
          usuario
        });
      }
    });

    if (CS_STATE.history.length > 250) {
      CS_STATE.history.length = 250;
    }
    saveControlStockHistory();
    saveLocalFacturaProveedorArticleOverrides(modifiedArticles);

    try {
      const res = await fetch('api/catalog.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'bulk_fix_negative_stock',
          items: normalizedItems
        })
      });
      const data = await res.json();
      if (!data || !data.ok) {
        throw new Error(data?.message || 'Error al guardar en el servidor.');
      }
      showStockNegativoFeedback(
        successLabel || `✅ Se corrigió el stock de ${normalizedItems.length} artículo${normalizedItems.length === 1 ? '' : 's'} correctamente.`
      );
    } catch (err) {
      showStockNegativoFeedback(`⚠️ Guardado local aplicado (${err.message || 'verificar conexión'}).`, true);
    } finally {
      if (btnZero) btnZero.disabled = false;
      if (btnSaveAll) btnSaveAll.disabled = false;
    }

    updateKpis();
    applyCatalogFilters(STATE.currentPage);
    renderStockNegativoTable();
  }

  function renderStockNegativoTable() {
    const tbody = document.getElementById('sn-tbody');
    if (!tbody) return;

    const { allNeg, filtered } = getNegativeStockArticlesList();
    SN_STATE.filteredRows = filtered;

    // Limpiar IDs seleccionados que ya no tengan stock negativo
    const validNegIds = new Set(allNeg.map((a) => Number(a.id)));
    Array.from(SN_STATE.selectedIds).forEach((id) => {
      if (!validNegIds.has(id)) SN_STATE.selectedIds.delete(id);
    });

    updateStockNegativoKpis(allNeg, filtered);

    tbody.textContent = '';
    if (filtered.length === 0) {
      const tr = document.createElement('tr');
      const td = document.createElement('td');
      td.colSpan = 8;
      td.className = 'table-loading-cell';
      td.innerHTML = allNeg.length === 0
        ? '🎉 <strong>¡Excelente! No hay ningún artículo con Stock Negativo en el padrón.</strong>'
        : 'No se encontraron artículos con stock negativo para los filtros seleccionados.';
      tr.appendChild(td);
      tbody.appendChild(tr);
      return;
    }

    const rubMap = new Map((Array.isArray(STATE.rubros) ? STATE.rubros : []).map((r) => [Number(r.id), r.nombre || '']));
    const marMap = new Map((Array.isArray(STATE.marcas) ? STATE.marcas : []).map((m) => [Number(m.id), m.nombre || '']));
    const provMap = new Map((Array.isArray(STATE.proveedores) ? STATE.proveedores : []).map((p) => [Number(p.id), p.nombre || p.razonSocial || '']));

    const frag = document.createDocumentFragment();
    filtered.forEach((art) => {
      const aid = Number(art.id);
      const isChecked = SN_STATE.selectedIds.has(aid);
      const currentSf = round2(Number(art.sf) || 0);
      const draftVal = Object.prototype.hasOwnProperty.call(SN_STATE.draftStockById, aid)
        ? SN_STATE.draftStockById[aid]
        : 0;
      const ean = Array.isArray(art.bc) && art.bc.length > 0 ? art.bc[0].c : 'SIN EAN';
      const rubroName = rubMap.get(Number(art.r)) || 'SIN RUBRO';
      const marcaName = marMap.get(Number(art.mk ?? art.m)) || 'SIN MARCA';
      const provName = provMap.get(Number(art.p)) || (Array.isArray(art.pr) && art.pr[0] ? provMap.get(Number(art.pr[0].p)) || '' : '');
      const costoFinal = Number(art.cfn ?? art.pcf ?? art.cn ?? art.pc) || 0;
      const precioPub = Number(art.p1f) || 0;

      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td style="text-align:center;">
          <input type="checkbox" class="sn-row-check" data-art-id="${aid}" ${isChecked ? 'checked' : ''} aria-label="Seleccionar ${escapeHtml(art.n || '')}">
        </td>
        <td>
          <div class="price-cell-stack">
            <span class="art-code-pill">#${escapeHtml(art.c || '')}</span>
            <span class="price-neto-val">${escapeHtml(ean)}</span>
          </div>
        </td>
        <td>
          <strong>${escapeHtml(art.n || '')}</strong>
        </td>
        <td>
          <div class="price-cell-stack">
            <span>${escapeHtml(rubroName)} · <strong>${escapeHtml(marcaName)}</strong></span>
            ${provName ? `<span class="price-neto-val">🚚 ${escapeHtml(provName)}</span>` : ''}
          </div>
        </td>
        <td class="num-col">
          <div class="price-cell-stack">
            <span>Púb: <strong>${formatARS(precioPub)}</strong></span>
            <span class="price-neto-val">Costo: ${formatARS(costoFinal)}</span>
          </div>
        </td>
        <td class="num-col">
          <span class="mini-tag mini-tag--baja" style="font-size:0.95rem; font-weight:800; padding:0.25rem 0.6rem;">
            ${currentSf.toLocaleString('es-AR')} u.
          </span>
        </td>
        <td class="num-col">
          <div style="display:inline-flex; align-items:center; gap:0.3rem; justify-content:flex-end;">
            <input
              type="number"
              class="form-input code-mono-input sn-row-stock-input"
              data-art-id="${aid}"
              step="${doesArticleAllowFraction(art) ? '0.01' : '1'}"
              value="${escapeHtml(String(doesArticleAllowFraction(art) ? draftVal : Math.round(Number(draftVal) || 0)))}"
              style="width:92px; text-align:center; font-weight:800; padding:0.32rem 0.45rem;"
              aria-label="Nuevo stock para ${escapeHtml(art.n || '')}"
            >
          </div>
        </td>
        <td class="actions-col">
          <div style="display:flex; gap:0.35rem; justify-content:flex-end; flex-wrap:wrap;">
            <button type="button" class="btn-gold btn-sm sn-btn-zero-one" data-art-id="${aid}" title="Poner el stock de este artículo en 0 inmediatamente">
              ✓ A 0
            </button>
            <button type="button" class="btn-primary btn-sm sn-btn-save-one" data-art-id="${aid}" title="Guardar el Nuevo Stock ingresado en esta fila">
              💾 Guardar
            </button>
            <button type="button" class="btn-secondary btn-sm sn-btn-edit-art" data-art-id="${aid}" title="Abrir ficha completa del artículo">
              ✏️
            </button>
          </div>
        </td>
      `;
      frag.appendChild(tr);
    });

    tbody.appendChild(frag);
  }

  window.initOrRefreshStockNegativoSection = function initOrRefreshStockNegativoSection() {
    populateStockNegativoFilterSelects();
    const { allNeg } = getNegativeStockArticlesList();
    // Seleccionar todos por defecto al abrir si no había selección activa
    if (SN_STATE.selectedIds.size === 0 && allNeg.length > 0) {
      allNeg.forEach((a) => SN_STATE.selectedIds.add(Number(a.id)));
    }
    renderStockNegativoTable();
  };

  // Listeners de filtros y acciones del módulo Stock Negativo
  document.getElementById('sn-search-input')?.addEventListener('input', () => renderStockNegativoTable());
  document.getElementById('sn-filter-rubro')?.addEventListener('change', () => renderStockNegativoTable());
  document.getElementById('sn-filter-marca')?.addEventListener('change', () => renderStockNegativoTable());
  document.getElementById('sn-filter-proveedor')?.addEventListener('change', () => renderStockNegativoTable());
  document.getElementById('sn-sort-select')?.addEventListener('change', () => renderStockNegativoTable());

  document.getElementById('btn-sn-refresh')?.addEventListener('click', async () => {
    await loadCatalogDatabase(true);
    window.initOrRefreshStockNegativoSection();
    showStockNegativoFeedback('✅ Listado de Stock Negativo actualizado.');
  });

  document.getElementById('sn-check-header')?.addEventListener('change', (e) => {
    const checked = Boolean(e.target.checked);
    SN_STATE.filteredRows.forEach((a) => {
      const aid = Number(a.id);
      if (checked) SN_STATE.selectedIds.add(aid);
      else SN_STATE.selectedIds.delete(aid);
    });
    renderStockNegativoTable();
  });

  document.getElementById('btn-sn-select-all')?.addEventListener('click', () => {
    SN_STATE.filteredRows.forEach((a) => SN_STATE.selectedIds.add(Number(a.id)));
    renderStockNegativoTable();
  });

  document.getElementById('btn-sn-select-none')?.addEventListener('click', () => {
    SN_STATE.filteredRows.forEach((a) => SN_STATE.selectedIds.delete(Number(a.id)));
    renderStockNegativoTable();
  });

  document.getElementById('btn-sn-apply-target-all')?.addEventListener('click', () => {
    const rawTarget = Number(document.getElementById('sn-bulk-target-stock')?.value ?? 0);
    const cleanTarget = Number.isFinite(rawTarget) ? round2(rawTarget) : 0;
    const targetRows = SN_STATE.filteredRows.filter((a) => SN_STATE.selectedIds.has(Number(a.id)));
    const rowsToApply = targetRows.length > 0 ? targetRows : SN_STATE.filteredRows;
    if (rowsToApply.length === 0) return;
    rowsToApply.forEach((a) => {
      SN_STATE.draftStockById[Number(a.id)] = cleanTarget;
    });
    renderStockNegativoTable();
    showStockNegativoFeedback(`✍️ Se pre-cargó el valor ${cleanTarget} en ${rowsToApply.length} artículo${rowsToApply.length === 1 ? '' : 's'}. Presioná "Guardar Todos los Nuevos Stocks" para confirmar.`);
  });

  document.getElementById('btn-sn-fix-all-zero')?.addEventListener('click', async () => {
    const selectedVisible = SN_STATE.filteredRows.filter((a) => SN_STATE.selectedIds.has(Number(a.id)));
    const targetList = selectedVisible.length > 0 ? selectedVisible : SN_STATE.filteredRows;
    if (targetList.length === 0) {
      showStockNegativoFeedback('⚠️ No hay artículos con stock negativo para corregir.', true);
      return;
    }
    const scopeText = selectedVisible.length > 0
      ? `${selectedVisible.length} artículo(s) seleccionado(s)`
      : `los ${targetList.length} artículo(s) listados`;
    if (!(await showBrandConfirmDialog(`¿Confirmás llevar a Stock 0 de forma general a ${scopeText}?`))) {
      return;
    }
    const batch = targetList.map((a) => ({ id: Number(a.id), sf: 0 }));
    applyStockNegativoCorrectionBatch(batch, `✅ ¡Corrección General completada! Se llevaron ${batch.length} artículo(s) a Stock 0.`);
  });

  document.getElementById('btn-sn-save-all-rows')?.addEventListener('click', async () => {
    const selectedVisible = SN_STATE.filteredRows.filter((a) => SN_STATE.selectedIds.has(Number(a.id)));
    const targetList = selectedVisible.length > 0 ? selectedVisible : SN_STATE.filteredRows;
    if (targetList.length === 0) {
      showStockNegativoFeedback('⚠️ No hay artículos en la lista para guardar.', true);
      return;
    }
    const batch = targetList.map((a) => {
      const aid = Number(a.id);
      const val = Object.prototype.hasOwnProperty.call(SN_STATE.draftStockById, aid)
        ? Number(SN_STATE.draftStockById[aid])
        : 0;
      return { id: aid, sf: Number.isFinite(val) ? round2(val) : 0 };
    });
    if (!(await showBrandConfirmDialog(`¿Confirmás guardar el nuevo stock asignado para ${batch.length} artículo(s)?`))) {
      return;
    }
    applyStockNegativoCorrectionBatch(batch, `✅ Se actualizaron los stocks de ${batch.length} artículo(s) correctamente.`);
  });

  document.getElementById('sn-tbody')?.addEventListener('input', (e) => {
    const inp = e.target.closest('.sn-row-stock-input');
    if (!inp) return;
    const aid = Number(inp.getAttribute('data-art-id'));
    if (aid > 0) {
      const art = STATE.articulos.find((a) => Number(a.id) === aid);
      stripDecimalInputIfNotFrac(inp, doesArticleAllowFraction(art));
      SN_STATE.draftStockById[aid] = inp.value;
    }
  });

  document.getElementById('sn-tbody')?.addEventListener('change', (e) => {
    const chk = e.target.closest('.sn-row-check');
    if (!chk) return;
    const aid = Number(chk.getAttribute('data-art-id'));
    if (aid > 0) {
      if (chk.checked) SN_STATE.selectedIds.add(aid);
      else SN_STATE.selectedIds.delete(aid);
      const { allNeg, filtered } = getNegativeStockArticlesList();
      updateStockNegativoKpis(allNeg, filtered);
    }
  });

  document.getElementById('sn-tbody')?.addEventListener('keydown', (e) => {
    const inp = e.target.closest('.sn-row-stock-input');
    if (inp) {
      const aid = Number(inp.getAttribute('data-art-id'));
      const art = aid > 0 ? STATE.articulos.find((a) => Number(a.id) === aid) : null;
      preventDecimalKeyIfNotFrac(e, doesArticleAllowFraction(art));
    }
    if (e.key === 'Enter') {
      if (!inp) return;
      e.preventDefault();
      const aid = Number(inp.getAttribute('data-art-id'));
      if (aid > 0) {
        const art = STATE.articulos.find((a) => Number(a.id) === aid);
        const allowFrac = doesArticleAllowFraction(art);
        const newSf = allowFrac ? round2(Number(inp.value) || 0) : Math.round(Number(inp.value) || 0);
        applyStockNegativoCorrectionBatch(
          [{ id: aid, sf: newSf }],
          `✅ Stock de #${art?.c || aid} (${art?.n || ''}) corregido a ${newSf} u.`
        );
      }
    }
  });

  document.getElementById('sn-tbody')?.addEventListener('click', (e) => {
    const btnZero = e.target.closest('.sn-btn-zero-one');
    if (btnZero) {
      const aid = Number(btnZero.getAttribute('data-art-id'));
      if (aid > 0) {
        const art = STATE.articulos.find((a) => Number(a.id) === aid);
        applyStockNegativoCorrectionBatch(
          [{ id: aid, sf: 0 }],
          `✅ Stock de #${art?.c || aid} (${art?.n || ''}) corregido a 0 u.`
        );
      }
      return;
    }

    const btnSaveOne = e.target.closest('.sn-btn-save-one');
    if (btnSaveOne) {
      const aid = Number(btnSaveOne.getAttribute('data-art-id'));
      if (aid > 0) {
        const rowInp = document.querySelector(`.sn-row-stock-input[data-art-id="${aid}"]`);
        const rawVal = rowInp ? Number(rowInp.value) : Number(SN_STATE.draftStockById[aid] ?? 0);
        const newSf = Number.isFinite(rawVal) ? round2(rawVal) : 0;
        const art = STATE.articulos.find((a) => Number(a.id) === aid);
        applyStockNegativoCorrectionBatch(
          [{ id: aid, sf: newSf }],
          `✅ Stock de #${art?.c || aid} (${art?.n || ''}) corregido a ${newSf} u.`
        );
      }
      return;
    }

    const btnEdit = e.target.closest('.sn-btn-edit-art');
    if (btnEdit) {
      const aid = Number(btnEdit.getAttribute('data-art-id'));
      const art = STATE.articulos.find((a) => Number(a.id) === aid);
      if (art) openArticleModal(art);
    }
  });

  document.getElementById('btn-sn-export-csv')?.addEventListener('click', () => {
    const rows = SN_STATE.filteredRows;
    if (!rows || rows.length === 0) {
      showStockNegativoFeedback('⚠️ No hay artículos en el listado para exportar.', true);
      return;
    }
    const rubMap = new Map((Array.isArray(STATE.rubros) ? STATE.rubros : []).map((r) => [Number(r.id), r.nombre || '']));
    const marMap = new Map((Array.isArray(STATE.marcas) ? STATE.marcas : []).map((m) => [Number(m.id), m.nombre || '']));
    const provMap = new Map((Array.isArray(STATE.proveedores) ? STATE.proveedores : []).map((p) => [Number(p.id), p.nombre || p.razonSocial || '']));

    const header = ['Codigo', 'EAN', 'Articulo', 'Rubro', 'Marca', 'Proveedor', 'Costo Final', 'Precio Publico', 'Stock Actual Negativo'];
    const csvLines = [header.join(';')];
    rows.forEach((a) => {
      const ean = Array.isArray(a.bc) && a.bc.length > 0 ? a.bc[0].c : '';
      const rub = rubMap.get(Number(a.r)) || '';
      const mar = marMap.get(Number(a.mk ?? a.m)) || '';
      const prov = provMap.get(Number(a.p)) || '';
      const costo = round2(Number(a.cfn ?? a.pcf ?? a.cn ?? a.pc) || 0).toString().replace('.', ',');
      const pub = round2(Number(a.p1f) || 0).toString().replace('.', ',');
      const sf = round2(Number(a.sf) || 0).toString().replace('.', ',');
      const clean = (s) => `"${String(s || '').replace(/"/g, '""')}"`;
      csvLines.push([clean(a.c), clean(ean), clean(a.n), clean(rub), clean(mar), clean(prov), costo, pub, sf].join(';'));
    });

    const blob = new Blob(['\uFEFF' + csvLines.join('\r\n')], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `stock_negativo_${new Date().toISOString().slice(0, 10)}.csv`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  });

  document.getElementById('btn-sn-print')?.addEventListener('click', () => {
    const rows = SN_STATE.filteredRows;
    if (!rows || rows.length === 0) {
      showStockNegativoFeedback('⚠️ No hay artículos en el listado para imprimir.', true);
      return;
    }
    const rubMap = new Map((Array.isArray(STATE.rubros) ? STATE.rubros : []).map((r) => [Number(r.id), r.nombre || '']));
    const marMap = new Map((Array.isArray(STATE.marcas) ? STATE.marcas : []).map((m) => [Number(m.id), m.nombre || '']));
    const trs = rows.map((a, idx) => {
      const ean = Array.isArray(a.bc) && a.bc.length > 0 ? a.bc[0].c : '';
      return `<tr>
        <td style="padding:5px 8px;border:1px solid #ccc;text-align:center;">${idx + 1}</td>
        <td style="padding:5px 8px;border:1px solid #ccc;font-family:monospace;">#${escapeHtml(a.c || '')}<br><small>${escapeHtml(ean)}</small></td>
        <td style="padding:5px 8px;border:1px solid #ccc;"><strong>${escapeHtml(a.n || '')}</strong></td>
        <td style="padding:5px 8px;border:1px solid #ccc;">${escapeHtml(rubMap.get(Number(a.r)) || '')} / ${escapeHtml(marMap.get(Number(a.mk ?? a.m)) || '')}</td>
        <td style="padding:5px 8px;border:1px solid #ccc;text-align:right;color:#b91c1c;font-weight:bold;">${round2(Number(a.sf) || 0)}</td>
        <td style="padding:5px 8px;border:1px solid #ccc;width:90px;"></td>
      </tr>`;
    }).join('');

    const w = window.open('', '_blank', 'width=960,height=720');
    if (!w) return;
    w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Listado de Stock Negativo</title>
      <style>body{font-family:Arial,sans-serif;font-size:12px;margin:20px;color:#111}table{width:100%;border-collapse:collapse;margin-top:12px}th{background:#f3f4f6;padding:6px 8px;border:1px solid #ccc;text-align:left}</style>
    </head><body>
      <h2 style="margin:0 0 4px;">📉 Listado General de Stock Negativo (${rows.length} artículos)</h2>
      <p style="margin:0 0 10px;color:#555;">Fecha: ${todayFormatted()} · Casa Nueva ERP</p>
      <table>
        <thead><tr><th>#</th><th>Cód. / EAN</th><th>Artículo</th><th>Rubro / Marca</th><th style="text-align:right;">Stock Actual</th><th>Conteo Físico</th></tr></thead>
        <tbody>${trs}</tbody>
      </table>
      <script>window.onload=function(){window.print();};<\/script>
    </body></html>`);
    w.document.close();
  });

  // =========================================================================
  // SUBMÓDULO: PRECIOS EN GÓNDOLA Y REPORTE DE ETIQUETAS A4 (3 × 9 = 27/HOJA)
  // =========================================================================
  const PG_PAGE_SIZE = 60;
  const PG_STATE = {
    selectedIds: new Set(),
    filteredRows: [],
    page: 1,
    manualCopiesMap: {}
  };

  window.PG_SELECT_NEW_ID = (artId) => {
    if (artId > 0) {
      PG_STATE.selectedIds.add(Number(artId));
    }
  };

  function getActivePgPriceList() {
    return 'MINORISTA';
  }

  function showPgFeedback(htmlMsg) {
    const banner = document.getElementById('pg-feedback-banner');
    if (!banner) return;
    if (!htmlMsg) {
      banner.hidden = true;
      return;
    }
    banner.innerHTML = htmlMsg;
    banner.hidden = false;
  }

  function formatLabelPriceA4(num) {
    const val = Number(num) || 0;
    return val.toFixed(2).replace('.', ',');
  }

  function parseArDateForSort(dateStr, fallbackIso = '') {
    if (fallbackIso) {
      const t = Date.parse(fallbackIso);
      if (!isNaN(t)) return t;
    }
    const parts = String(dateStr || '').trim().split('/');
    if (parts.length === 3) {
      const d = parseInt(parts[0], 10);
      const m = parseInt(parts[1], 10) - 1;
      const y = parseInt(parts[2], 10);
      const dt = new Date(y, m, d).getTime();
      if (!isNaN(dt)) return dt;
    }
    return 0;
  }

  function buildPgRowData(art, queueEntry, activeList) {
    const isMay = activeList === 'MAYORISTA';
    const actual = round2(isMay ? (art.p2f || 0) : (art.p1f || 0));
    const enGondola = queueEntry
      ? round2(isMay ? (queueEntry.enGondolaMay ?? actual) : (queueEntry.enGondolaMin ?? actual))
      : actual;
    const diff = round2(actual - enGondola);
    const pct = enGondola > 0 ? round2((diff / enGondola) * 100) : 0;
    const copias = queueEntry
      ? Math.max(1, Number(queueEntry.copias) || 1)
      : Math.max(1, Number(PG_STATE.manualCopiesMap[art.id]) || 1);
    const fechaAct = queueEntry?.fechaActualizacion || art.fup || todayFormatted();
    const updatedAtIso = queueEntry?.updatedAtIso || '';
    const origen = queueEntry?.origen || (art.fup ? 'Catálogo' : 'Padrón');
    const isVaried = Math.abs(diff) >= 0.01;
    const isManual = Boolean(queueEntry?.manual);

    return {
      art,
      queueEntry,
      enGondola,
      actual,
      diff,
      pct,
      copias,
      fechaAct,
      updatedAtIso,
      origen,
      isVaried,
      isManual
    };
  }

  function updatePgKpisAndSelectionSummary() {
    const activeList = getActivePgPriceList();
    const queueValues = Object.values(STATE.gondolaQueue || {});
    const totalPending = queueValues.length;

    let upCount = 0;
    let downCount = 0;
    queueValues.forEach((qe) => {
      const art = STATE.articulos.find((a) => Number(a.id) === Number(qe.artId));
      if (!art) return;
      const actual = activeList === 'MAYORISTA' ? round2(art.p2f || 0) : round2(art.p1f || 0);
      const prev = activeList === 'MAYORISTA' ? round2(qe.enGondolaMay ?? actual) : round2(qe.enGondolaMin ?? actual);
      const d = round2(actual - prev);
      if (d >= 0.01) upCount++;
      else if (d <= -0.01) downCount++;
    });

    const selectedRows = getRowsForPgPrinting(false);
    const selectedArticlesCount = selectedRows.length;
    const totalLabels = selectedRows.reduce((sum, r) => sum + Math.max(1, Number(r.copias) || 1), 0);
    const totalSheets = totalLabels > 0 ? Math.ceil(totalLabels / 27) : 0;

    const elPending = document.getElementById('kpi-pg-pending');
    const elPendingSub = document.getElementById('kpi-pg-pending-sub');
    const elSelected = document.getElementById('kpi-pg-selected');
    const elSheets = document.getElementById('kpi-pg-sheets');
    const elVariations = document.getElementById('kpi-pg-variations');
    const elActiveList = document.getElementById('kpi-pg-active-list');
    const thActual = document.getElementById('pg-th-lista-actual');

    if (elPending) elPending.textContent = totalPending.toLocaleString('es-AR');
    if (elPendingSub) {
      elPendingSub.textContent = totalPending === 1
        ? '1 producto con etiqueta pendiente de góndola'
        : `${totalPending.toLocaleString('es-AR')} productos pendientes de colocar en góndola`;
    }
    if (elSelected) elSelected.textContent = selectedArticlesCount.toLocaleString('es-AR');
    if (elSheets) {
      elSheets.textContent = `${totalLabels.toLocaleString('es-AR')} etiqueta${totalLabels === 1 ? '' : 's'} · ${totalSheets} hoja${totalSheets === 1 ? '' : 's'} A4 (27 por hoja)`;
    }
    if (elVariations) elVariations.textContent = `${upCount} ▲ / ${downCount} ▼`;
    if (elActiveList) elActiveList.textContent = 'Hoja A4 (3 × 9)';
    if (thActual) thActual.textContent = 'Actual';

    syncPgSelectButtonsState();
    updateGondolaMenuBadges();
  }

  function syncPgStickyTopOffset() {
    const topbar = document.querySelector('.erp-topbar');
    if (topbar && topbar.offsetHeight > 0) {
      document.documentElement.style.setProperty('--erp-topbar-h', `${topbar.offsetHeight}px`);
    }
  }

  function syncPgSelectButtonsState() {
    const btnAll = document.getElementById('btn-pg-select-all');
    const btnNone = document.getElementById('btn-pg-select-none');
    const chkAll = document.getElementById('pg-btn-chk-all');
    const chkNone = document.getElementById('pg-btn-chk-none');
    const lblAll = document.getElementById('pg-btn-lbl-all');

    const rows = Array.isArray(PG_STATE.filteredRows) ? PG_STATE.filteredRows : [];
    const totalVisible = rows.length;
    let selectedVisible = 0;
    for (let i = 0; i < totalVisible; i++) {
      if (PG_STATE.selectedIds.has(Number(rows[i]?.art?.id))) {
        selectedVisible++;
      }
    }

    const isAllSelected = totalVisible > 0 && selectedVisible === totalVisible;
    const isNoneSelected = totalVisible > 0 && selectedVisible === 0;

    if (chkAll) {
      chkAll.checked = isAllSelected;
      chkAll.indeterminate = false;
    }
    if (btnAll) {
      btnAll.classList.toggle('is-pg-sel-active', isAllSelected);
      btnAll.setAttribute('aria-pressed', isAllSelected ? 'true' : 'false');
    }
    if (lblAll) {
      if (totalVisible > 0 && selectedVisible > 0 && selectedVisible < totalVisible) {
        lblAll.textContent = `Todos (${selectedVisible}/${totalVisible})`;
      } else if (isAllSelected) {
        lblAll.textContent = `Todos (${totalVisible})`;
      } else {
        lblAll.textContent = 'Todos';
      }
    }

    if (chkNone) {
      chkNone.checked = isNoneSelected;
      chkNone.indeterminate = false;
    }
    if (btnNone) {
      btnNone.classList.toggle('is-pg-sel-active', isNoneSelected);
      btnNone.setAttribute('aria-pressed', isNoneSelected ? 'true' : 'false');
    }
  }

  function applyPreciosGondolaFilters(page = 1) {
    if (!STATE.loaded && STATE.articulos.length === 0) {
      loadCatalogDatabase().then(() => applyPreciosGondolaFilters(page));
      return;
    }

    const activeList = getActivePgPriceList();
    const q = normalizeStr(document.getElementById('pg-filter-q')?.value || '');
    const provId = Number(document.getElementById('pg-filter-proveedor')?.value) || 0;
    const rubroId = Number(document.getElementById('pg-filter-rubro')?.value) || 0;
    const cfgRaw = document.getElementById('pg-filter-config')?.value || '';
    const mostrar = document.getElementById('pg-filter-mostrar')?.value || 'pendientes';
    const orden = document.getElementById('pg-filter-orden')?.value || 'codigo';

    const tokens = q ? q.split(/\s+/).filter(Boolean) : [];
    const hasSearchOrFilter = tokens.length > 0 || provId > 0 || rubroId > 0 || cfgRaw !== '';
    const queueMap = STATE.gondolaQueue || {};
    const rows = [];

    for (const art of STATE.articulos) {
      if (Number(art.bl) === 1) continue;

      const qe = queueMap[String(art.id)] || null;
      if (mostrar === 'pendientes' && !qe && !hasSearchOrFilter) continue;
      if (mostrar === 'manuales' && (!qe || !qe.manual)) continue;
      if (mostrar === 'solo_variaron' && !qe) continue;

      if (provId > 0) {
        const matchProv =
          Number(art.p) === provId ||
          (Array.isArray(art.pr) && art.pr.some((s) => Number(s.p) === provId));
        if (!matchProv) continue;
      }
      if (rubroId > 0 && Number(art.r) !== rubroId) continue;
      if (cfgRaw === 'SIN_CONFIG') {
        if (art.ucp === 1 && Number(art.cp) > 0 && STATE.configPreciosMap.has(Number(art.cp))) continue;
      } else if (cfgRaw !== '') {
        if (!(art.ucp === 1 && Number(art.cp) === Number(cfgRaw))) continue;
      }

      if (tokens.length > 0) {
        const bcs = Array.isArray(art.bc) ? art.bc.map((b) => b.c).join(' ') : '';
        const marcaName = STATE.marcasMap.get(Number(art.mk))?.nombre || '';
        const rubroName = STATE.rubrosMap.get(Number(art.r))?.nombre || '';
        const hay = normalizeStr(
          `${art.c} ${parseInt(art.c, 10) || ''} ${art.n} ${bcs} ${art.cf || ''} ${marcaName} ${rubroName}`
        );
        if (!tokens.every((t) => hay.includes(t))) continue;
      }

      const rowObj = buildPgRowData(art, qe, activeList);
      if (mostrar === 'solo_variaron' && !rowObj.isVaried) continue;
      rows.push(rowObj);
    }

    rows.sort((a, b) => {
      if (mostrar === 'pendientes' && hasSearchOrFilter) {
        const qa = a.queueEntry ? 1 : 0;
        const qb = b.queueEntry ? 1 : 0;
        if (qb !== qa) return qb - qa;
      }
      if (orden === 'nombre') {
        return String(a.art.n || '').localeCompare(String(b.art.n || ''), 'es-AR');
      }
      if (orden === 'fecha') {
        const tb = parseArDateForSort(b.fechaAct, b.updatedAtIso);
        const ta = parseArDateForSort(a.fechaAct, a.updatedAtIso);
        if (tb !== ta) return tb - ta;
      }
      if (orden === 'rubro') {
        const ra = STATE.rubrosMap.get(Number(a.art.r))?.nombre || '';
        const rb = STATE.rubrosMap.get(Number(b.art.r))?.nombre || '';
        const cmp = ra.localeCompare(rb, 'es-AR');
        if (cmp !== 0) return cmp;
      }
      if (orden === 'porcentaje') {
        const diffAbs = Math.abs(b.pct) - Math.abs(a.pct);
        if (Math.abs(diffAbs) >= 0.01) return diffAbs;
      }
      return String(a.art.c || '').localeCompare(String(b.art.c || ''), 'es-AR', { numeric: true });
    });

    PG_STATE.filteredRows = rows;
    const totalPages = Math.max(1, Math.ceil(rows.length / PG_PAGE_SIZE));
    PG_STATE.page = Math.min(Math.max(1, page), totalPages);

    renderPreciosGondolaTable(totalPages);
    updatePgKpisAndSelectionSummary();
  }

  function renderPreciosGondolaTable(totalPages) {
    const tbody = document.getElementById('pg-items-tbody');
    const statusEl = document.getElementById('pg-status-msg');
    const pageInd = document.getElementById('pg-page-indicator');
    const btnPrev = document.getElementById('btn-pg-prev-page');
    const btnNext = document.getElementById('btn-pg-next-page');
    const chkHeader = document.getElementById('pg-chk-header-all');
    if (!tbody) return;

    const total = PG_STATE.filteredRows.length;
    const startIdx = (PG_STATE.page - 1) * PG_PAGE_SIZE;
    const slice = PG_STATE.filteredRows.slice(startIdx, startIdx + PG_PAGE_SIZE);

    if (statusEl) {
      statusEl.textContent = total === 0
        ? 'No hay artículos en la vista actual.'
        : `Mostrando ${slice.length} de ${total.toLocaleString('es-AR')} artículo(s)`;
    }
    syncUnifiedPaginationControls(pageInd, btnPrev, btnNext, PG_STATE.page, totalPages, (nextPage) => {
      applyPreciosGondolaFilters(nextPage);
    });

    if (chkHeader) {
      chkHeader.checked = slice.length > 0 && slice.every((r) => PG_STATE.selectedIds.has(Number(r.art.id)));
    }

    tbody.textContent = '';
    updatePgHistoryCountBadge();
    if (slice.length === 0) {
      const tr = document.createElement('tr');
      const td = document.createElement('td');
      td.colSpan = 10;
      td.className = 'table-loading-cell';
      const mostrar = document.getElementById('pg-filter-mostrar')?.value || 'pendientes';
      const msgText = mostrar === 'pendientes' || mostrar === 'solo_variaron'
        ? 'No hay artículos con cambio de precio pendiente de góndola. Al actualizar cualquier precio (manual, por Factura Proveedor o por Configuración de Precios) o usar Selección Manual, aparecerán automáticamente aquí.'
        : 'No se encontraron artículos con los filtros seleccionados.';

      const wrap = document.createElement('div');
      wrap.style.display = 'flex';
      wrap.style.flexDirection = 'column';
      wrap.style.alignItems = 'center';
      wrap.style.gap = '0.7rem';
      wrap.style.padding = '0.35rem 0';

      const pMsg = document.createElement('div');
      pMsg.textContent = msgText;
      wrap.appendChild(pMsg);

      const histList = Array.isArray(STATE.gondolaPrintHistory) ? STATE.gondolaPrintHistory : [];
      if (histList.length > 0 && (mostrar === 'pendientes' || mostrar === 'solo_variaron')) {
        const lastBatch = histList[0];
        const recBox = document.createElement('div');
        recBox.style.display = 'flex';
        recBox.style.flexWrap = 'wrap';
        recBox.style.alignItems = 'center';
        recBox.style.justifyContent = 'center';
        recBox.style.gap = '0.55rem';
        recBox.style.padding = '0.55rem 0.9rem';
        recBox.style.borderRadius = '8px';
        recBox.style.border = '1px solid var(--border-subtle)';
        recBox.style.background = 'var(--surface-subtle, rgba(212,169,42,0.06))';

        const lbl = document.createElement('span');
        lbl.style.fontSize = '0.82rem';
        lbl.innerHTML = `<strong>¿Falló la impresora?</strong> Última tanda: <strong>${escapeHtml(lastBatch.fechaHora || '')}</strong> (${Number(lastBatch.articlesCount || 0)} art. · ${Number(lastBatch.totalLabels || 0)} etiquetas):`;
        recBox.appendChild(lbl);

        const btnRestLast = document.createElement('button');
        btnRestLast.type = 'button';
        btnRestLast.className = 'btn-primary btn-sm';
        btnRestLast.style.width = 'auto';
        btnRestLast.textContent = '↩️ Recuperar a la Lista';
        btnRestLast.addEventListener('click', () => {
          restoreGondolaBatchToQueue(lastBatch);
        });
        recBox.appendChild(btnRestLast);

        const btnReprintLast = document.createElement('button');
        btnReprintLast.type = 'button';
        btnReprintLast.className = 'btn-secondary btn-sm';
        btnReprintLast.style.width = 'auto';
        btnReprintLast.textContent = '🖨️ Reimprimir A4 Directo';
        btnReprintLast.addEventListener('click', () => {
          reprintGondolaHistoryBatchA4(lastBatch, false);
        });
        recBox.appendChild(btnReprintLast);

        const btnOpenHist = document.createElement('button');
        btnOpenHist.type = 'button';
        btnOpenHist.className = 'btn-secondary btn-sm';
        btnOpenHist.style.width = 'auto';
        btnOpenHist.textContent = `🕘 Ver Historial (${histList.length})`;
        btnOpenHist.addEventListener('click', () => {
          openPgHistoryModal();
        });
        recBox.appendChild(btnOpenHist);

        wrap.appendChild(recBox);
      }

      td.appendChild(wrap);
      tr.appendChild(td);
      tbody.appendChild(tr);
      return;
    }

    const frag = document.createDocumentFragment();
    slice.forEach((row) => {
      const { art, queueEntry, enGondola, actual, diff, pct, copias, fechaAct, origen } = row;
      const artId = Number(art.id);
      const tr = document.createElement('tr');

      // 1. Checkbox Actualizar / Imprimir
      const tdChk = document.createElement('td');
      tdChk.style.textAlign = 'center';
      const chk = document.createElement('input');
      chk.type = 'checkbox';
      chk.checked = PG_STATE.selectedIds.has(artId);
      chk.setAttribute('aria-label', `Seleccionar ${art.n}`);
      chk.addEventListener('change', () => {
        if (chk.checked) PG_STATE.selectedIds.add(artId);
        else PG_STATE.selectedIds.delete(artId);
        if (chkHeader) {
          chkHeader.checked = slice.length > 0 && slice.every((r) => PG_STATE.selectedIds.has(Number(r.art.id)));
        }
        updatePgKpisAndSelectionSummary();
      });
      tdChk.appendChild(chk);
      tr.appendChild(tdChk);

      // 2. Código (Row header for sticky/responsive table)
      const thCode = document.createElement('th');
      thCode.scope = 'row';
      const mainBc = Array.isArray(art.bc) && art.bc.length > 0 ? art.bc[0].c : 'S/EAN';
      thCode.innerHTML = `<div class="price-cell-stack"><span class="art-code-pill">${escapeHtml(art.c)}</span><span class="price-neto-val">${escapeHtml(mainBc)}</span></div>`;
      tr.appendChild(thCode);

      // 3. Artículo + Rubro / Origen
      const tdName = document.createElement('td');
      const rubroName = STATE.rubrosMap.get(Number(art.r))?.nombre || 'SIN RUBRO';
      tdName.innerHTML = `<div class="price-cell-stack"><strong class="art-title-text">${escapeHtml(art.n)}</strong><span class="art-sub-meta">${escapeHtml(rubroName)} · ${escapeHtml(origen)}</span></div>`;
      tr.appendChild(tdName);

      // 4. Fecha de Actualización
      const tdFecha = document.createElement('td');
      tdFecha.innerHTML = `<span class="badge badge--gold" style="font-variant-numeric:tabular-nums;">📅 ${escapeHtml(fechaAct)}</span>`;
      tr.appendChild(tdFecha);

      // 5. Cant. de copias
      const tdCopias = document.createElement('td');
      tdCopias.style.textAlign = 'center';
      const inpCopias = document.createElement('input');
      inpCopias.type = 'number';
      inpCopias.min = '1';
      inpCopias.max = '999';
      inpCopias.className = 'form-input pg-copies-input';
      inpCopias.value = String(copias);
      inpCopias.setAttribute('aria-label', `Cantidad de copias para ${art.n}`);
      inpCopias.addEventListener('change', () => {
        const validCopies = Math.max(1, Math.min(999, parseInt(inpCopias.value, 10) || 1));
        inpCopias.value = String(validCopies);
        row.copias = validCopies;
        if (STATE.gondolaQueue && STATE.gondolaQueue[String(artId)]) {
          STATE.gondolaQueue[String(artId)].copias = validCopies;
          syncGondolaQueueToServer();
        } else {
          PG_STATE.manualCopiesMap[artId] = validCopies;
        }
        updatePgKpisAndSelectionSummary();
      });
      tdCopias.appendChild(inpCopias);
      tr.appendChild(tdCopias);

      // 6. En Góndola
      const tdEnGondola = document.createElement('td');
      tdEnGondola.className = 'num-col';
      tdEnGondola.textContent = formatArs(enGondola);
      tr.appendChild(tdEnGondola);

      // 7. Actual
      const tdActual = document.createElement('td');
      tdActual.className = 'num-col';
      tdActual.innerHTML = `<strong class="price-final-val">$ ${formatArs(actual)}</strong>`;
      tr.appendChild(tdActual);

      // 8. Diferencia
      const tdDiff = document.createElement('td');
      tdDiff.className = 'num-col';
      const diffCls = diff >= 0.01 ? 'pg-diff-up' : diff <= -0.01 ? 'pg-diff-down' : 'pg-diff-zero';
      const diffPrefix = diff > 0.009 ? '+' : '';
      tdDiff.innerHTML = `<span class="${diffCls}">${diffPrefix}${formatArs(diff)}</span>`;
      tr.appendChild(tdDiff);

      // 9. Porcentaje
      const tdPct = document.createElement('td');
      tdPct.className = 'num-col';
      const pctPrefix = pct > 0.009 ? '+' : '';
      tdPct.innerHTML = `<span class="${diffCls}">${pctPrefix}${formatArs(pct)}%</span>`;
      tr.appendChild(tdPct);

      // 10. Quitar de pendientes
      const tdRemove = document.createElement('td');
      tdRemove.style.textAlign = 'center';
      if (queueEntry) {
        const btnRem = document.createElement('button');
        btnRem.type = 'button';
        btnRem.className = 'btn-remove-row';
        btnRem.style.minWidth = '28px';
        btnRem.style.minHeight = '28px';
        btnRem.title = 'Descartar de la lista de góndola';
        btnRem.textContent = '✕';
        btnRem.addEventListener('click', () => {
          delete STATE.gondolaQueue[String(artId)];
          PG_STATE.selectedIds.delete(artId);
          syncGondolaQueueToServer();
          applyPreciosGondolaFilters(PG_STATE.page);
        });
        tdRemove.appendChild(btnRem);
      } else {
        const btnAddQuick = document.createElement('button');
        btnAddQuick.type = 'button';
        btnAddQuick.className = 'btn-secondary btn-sm';
        btnAddQuick.style.padding = '0.18rem 0.45rem';
        btnAddQuick.title = 'Agregar a cola de etiquetas de góndola';
        btnAddQuick.textContent = '+';
        btnAddQuick.addEventListener('click', () => {
          addManualArticleToGondolaQueue(art, row.copias);
        });
        tdRemove.appendChild(btnAddQuick);
      }
      tr.appendChild(tdRemove);

      frag.appendChild(tr);
    });

    tbody.appendChild(frag);
  }

  function addManualArticleToGondolaQueue(art, copies = 1) {
    if (!art || !art.id) return;
    if (!STATE.gondolaQueue || typeof STATE.gondolaQueue !== 'object') {
      STATE.gondolaQueue = {};
    }
    const key = String(art.id);
    const existing = STATE.gondolaQueue[key];
    const cleanCopies = Math.max(1, Math.min(999, parseInt(copies, 10) || 1));
    const fecha = art.fup || todayFormatted();

    if (existing) {
      existing.copias = cleanCopies;
      existing.manual = true;
    } else {
      STATE.gondolaQueue[key] = {
        artId: Number(art.id),
        enGondolaMin: round2(art.p1f || 0),
        enGondolaMay: round2(art.p2f || 0),
        copias: cleanCopies,
        fechaActualizacion: fecha,
        updatedAtIso: new Date().toISOString(),
        origen: 'Selección Manual',
        manual: true
      };
    }
    PG_STATE.selectedIds.add(Number(art.id));
    syncGondolaQueueToServer();
    applyPreciosGondolaFilters(PG_STATE.page);
  }

  function getRowsForPgPrinting(fallbackToFiltered = true) {
    const activeList = getActivePgPriceList();
    if (PG_STATE.selectedIds.size > 0) {
      const inFilter = PG_STATE.filteredRows.filter((r) => PG_STATE.selectedIds.has(Number(r.art.id)));
      if (inFilter.length > 0) return inFilter;

      const fromAll = [];
      PG_STATE.selectedIds.forEach((id) => {
        const art = STATE.articulos.find((a) => Number(a.id) === Number(id));
        if (art) {
          fromAll.push(buildPgRowData(art, STATE.gondolaQueue?.[String(art.id)] || null, activeList));
        }
      });
      return fromAll;
    }
    return fallbackToFiltered ? PG_STATE.filteredRows : [];
  }

  function buildGondolaA4SheetsHtml(rowsToPrint) {
    const labels = [];
    rowsToPrint.forEach((row) => {
      const count = Math.max(1, Math.min(999, Number(row.copias) || 1));
      const ean = Array.isArray(row.art.bc) && row.art.bc.length > 0 ? String(row.art.bc[0].c || '').trim() : '';
      const codeStr = String(row.art.c || '').trim();
      const priceStr = `$ ${formatLabelPriceA4(row.actual)}`;
      const dateStr = String(row.fechaAct || todayFormatted()).trim();
      const nameStr = String(row.art.n || '').trim();

      for (let i = 0; i < count; i++) {
        labels.push({
          name: nameStr,
          price: priceStr,
          code: codeStr,
          date: dateStr,
          ean
        });
      }
    });

    const sheetsHtml = [];
    for (let i = 0; i < labels.length; i += 27) {
      const chunk = labels.slice(i, i + 27);
      const cellsHtml = chunk
        .map(
          (lbl) => `
          <div class="pg-label-box">
            <div class="pg-label-name">${escapeHtml(lbl.name)}</div>
            <div class="pg-label-price">${escapeHtml(lbl.price)}</div>
            <div class="pg-label-footer">
              <span class="pg-label-code">${escapeHtml(lbl.code)}</span>
              <span class="pg-label-date">${escapeHtml(lbl.date)}</span>
              <span class="pg-label-ean">${escapeHtml(lbl.ean)}</span>
            </div>
          </div>`
        )
        .join('');
      sheetsHtml.push(`<section class="pg-a4-sheet">${cellsHtml}</section>`);
    }

    return {
      totalLabels: labels.length,
      totalSheets: sheetsHtml.length,
      html: sheetsHtml.join('')
    };
  }

  function openPgA4PreviewModal(customRows = null) {
    const rows = Array.isArray(customRows) && customRows.length > 0 ? customRows : getRowsForPgPrinting(true);
    if (rows.length === 0) {
      window.alert('No hay artículos seleccionados ni pendientes en la lista para generar etiquetas A4.');
      return false;
    }

    PG_STATE.previewCustomRows = Array.isArray(customRows) && customRows.length > 0 ? customRows : null;
    const { totalLabels, totalSheets, html } = buildGondolaA4SheetsHtml(rows);
    const stage = document.getElementById('pg-a4-preview-stage');
    const badge = document.getElementById('pg-preview-meta-badge');
    const dlg = document.getElementById('pg-a4-preview-dialog');

    if (stage) stage.innerHTML = html;
    if (badge) {
      badge.textContent = `REPORTE A4 · ${totalLabels} ETIQUETA${totalLabels === 1 ? '' : 'S'} EN ${totalSheets} HOJA${totalSheets === 1 ? '' : 'S'} A4 (3 × 9)`;
    }
    if (dlg && !dlg.open) {
      dlg.showModal();
    }
    return true;
  }

  function executePgPrintA4Document(markUpdatedAfter = true, customRows = null) {
    const rows = Array.isArray(customRows) && customRows.length > 0 ? customRows : getRowsForPgPrinting(true);
    if (rows.length === 0) {
      window.alert('No hay artículos seleccionados ni pendientes para imprimir.');
      return;
    }

    const { html } = buildGondolaA4SheetsHtml(rows);
    let printIframe = document.getElementById('pg-print-a4-iframe');
    if (!printIframe) {
      printIframe = document.createElement('iframe');
      printIframe.id = 'pg-print-a4-iframe';
      printIframe.title = 'Impresión A4 Precios en Góndola';
      printIframe.style.position = 'fixed';
      printIframe.style.right = '0';
      printIframe.style.bottom = '0';
      printIframe.style.width = '0';
      printIframe.style.height = '0';
      printIframe.style.border = '0';
      document.body.appendChild(printIframe);
    }

    const printDocHtml = `<!DOCTYPE html>
<html lang="es-AR">
<head>
  <meta charset="UTF-8">
  <title>Precios en Góndola - Reporte A4</title>
  <style>
    @page {
      size: A4 portrait;
      margin: 0;
    }
    html, body {
      margin: 0;
      padding: 0;
      background: #ffffff;
      color: #000000;
      font-family: Arial, Helvetica, sans-serif;
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
    .pg-a4-sheet {
      width: 210mm;
      height: 297mm;
      padding: 7.5mm 8mm;
      box-sizing: border-box;
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      grid-template-rows: repeat(9, 29.55mm);
      column-gap: 2mm;
      row-gap: 2mm;
      page-break-after: always;
      break-after: page;
    }
    .pg-a4-sheet:last-child {
      page-break-after: auto;
      break-after: auto;
    }
    .pg-label-box {
      border: 1px solid #222222;
      background: #ffffff;
      color: #000000;
      padding: 1.6mm 2.2mm 1.3mm;
      box-sizing: border-box;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      overflow: hidden;
      break-inside: avoid;
      page-break-inside: avoid;
    }
    .pg-label-name {
      font-size: 8.3pt;
      font-weight: 400;
      line-height: 1.12;
      text-align: center;
      color: #000000;
      max-height: 7.2mm;
      overflow: hidden;
    }
    .pg-label-price {
      font-size: 24.5pt;
      font-weight: 800;
      line-height: 1;
      text-align: center;
      color: #000000;
      letter-spacing: -0.02em;
      white-space: nowrap;
      margin-top: auto;
      margin-bottom: auto;
    }
    .pg-label-footer {
      display: grid;
      grid-template-columns: 1fr auto 1fr;
      align-items: baseline;
      gap: 1.2mm;
      font-size: 7.2pt;
      font-weight: 400;
      line-height: 1;
      color: #000000;
    }
    .pg-label-code {
      text-align: left;
      white-space: nowrap;
    }
    .pg-label-date {
      text-align: center;
      font-size: 6.7pt;
      color: #111111;
      white-space: nowrap;
    }
    .pg-label-ean {
      text-align: right;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
  </style>
</head>
<body>${html}</body>
</html>`;

    const win = printIframe.contentWindow;
    if (!win) return;
    win.document.open();
    win.document.write(printDocHtml);
    win.document.close();

    // Limpiar el listado pendiente inmediatamente al ordenar la impresión,
    // antes de que el diálogo nativo de impresión bloquee el hilo del navegador.
    if (markUpdatedAfter) {
      markRowsAsUpdatedOnGondola(rows, true);
      document.getElementById('pg-a4-preview-dialog')?.close();
    } else {
      document.getElementById('pg-a4-preview-dialog')?.close();
    }

    setTimeout(() => {
      try {
        win.focus();
        win.print();
      } catch {}
    }, 180);
  }

  function recordGondolaPrintHistoryBatch(targetRows, tipoOperacion = 'Impresión Reporte A4') {
    if (!Array.isArray(targetRows) || targetRows.length === 0) return null;
    if (!Array.isArray(STATE.gondolaPrintHistory)) {
      STATE.gondolaPrintHistory = [];
    }
    const now = new Date();
    const hh = String(now.getHours()).padStart(2, '0');
    const mm = String(now.getMinutes()).padStart(2, '0');
    const fechaHora = `${todayFormatted()} ${hh}:${mm}`;
    const usuario = STATE.currentUser?.name || STATE.currentUser?.username || 'Administrador';

    const items = [];
    let totalLabels = 0;
    targetRows.forEach((r) => {
      const art = r?.art || STATE.articulos.find((a) => Number(a.id) === Number(r?.artId || 0));
      if (!art) return;
      const copias = Math.max(1, Math.min(999, Number(r.copias || r.queueEntry?.copias || 1)));
      const ean = Array.isArray(art.bc) && art.bc.length > 0 ? String(art.bc[0].c || '').trim() : '';
      const actual = round2(r.actual ?? art.p1f ?? 0);
      const enGondolaMin = round2(r.enGondola ?? r.queueEntry?.enGondolaMin ?? actual);
      const enGondolaMay = round2(r.queueEntry?.enGondolaMay ?? art.p2f ?? 0);
      totalLabels += copias;
      items.push({
        artId: Number(art.id),
        c: String(art.c || ''),
        n: String(art.n || ''),
        ean,
        actual,
        enGondolaMin,
        enGondolaMay,
        copias,
        fechaAct: String(r.fechaAct || r.queueEntry?.fechaActualizacion || art.fup || todayFormatted()),
        origen: String(r.origen || r.queueEntry?.origen || 'Recuperado'),
        manual: Boolean(r.isManual || r.queueEntry?.manual)
      });
    });

    if (items.length === 0) return null;

    const batch = {
      id: `IMP-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
      fechaHora,
      tipo: tipoOperacion,
      usuario,
      articlesCount: items.length,
      totalLabels,
      totalSheets: Math.ceil(totalLabels / 27),
      items
    };

    STATE.gondolaPrintHistory.unshift(batch);
    if (STATE.gondolaPrintHistory.length > 30) {
      STATE.gondolaPrintHistory = STATE.gondolaPrintHistory.slice(0, 30);
    }
    saveLocalGondolaPrintHistory();
    return batch;
  }

  function buildRowsFromHistoryBatch(batch) {
    if (!batch || !Array.isArray(batch.items)) return [];
    const rows = [];
    batch.items.forEach((it) => {
      let art = STATE.articulos.find((a) => Number(a.id) === Number(it.artId));
      if (!art && it.c) {
        const c5 = String(it.c).trim().padStart(5, '0');
        art = STATE.articulos.find((a) => String(a.c || '').trim().padStart(5, '0') === c5);
      }
      const resolvedArt = art || {
        id: Number(it.artId) || 0,
        c: String(it.c || ''),
        n: String(it.n || ''),
        p1f: round2(it.actual || 0),
        p2f: round2(it.enGondolaMay || it.actual || 0),
        bc: it.ean ? [{ c: String(it.ean) }] : []
      };
      rows.push({
        art: resolvedArt,
        copias: Math.max(1, Number(it.copias) || 1),
        actual: round2(resolvedArt.p1f || it.actual || 0),
        enGondola: round2(it.enGondolaMin ?? resolvedArt.p1f ?? 0),
        fechaAct: String(it.fechaAct || todayFormatted()),
        origen: String(it.origen || 'Recuperado')
      });
    });
    return rows;
  }

  function restoreGondolaBatchToQueue(batch) {
    if (!batch || !Array.isArray(batch.items) || batch.items.length === 0) {
      window.alert('No hay artículos en esta tanda para recuperar.');
      return;
    }
    if (!STATE.gondolaQueue || typeof STATE.gondolaQueue !== 'object') {
      STATE.gondolaQueue = {};
    }
    let restoredCount = 0;
    batch.items.forEach((it) => {
      let art = STATE.articulos.find((a) => Number(a.id) === Number(it.artId));
      if (!art && it.c) {
        const c5 = String(it.c).trim().padStart(5, '0');
        art = STATE.articulos.find((a) => String(a.c || '').trim().padStart(5, '0') === c5);
      }
      if (!art) return;
      const artId = Number(art.id);
      const copias = Math.max(1, Math.min(999, Number(it.copias) || 1));
      STATE.gondolaQueue[String(artId)] = {
        artId,
        enGondolaMin: round2(it.enGondolaMin ?? art.p1f ?? 0),
        enGondolaMay: round2(it.enGondolaMay ?? art.p2f ?? 0),
        copias,
        fechaActualizacion: String(it.fechaAct || art.fup || todayFormatted()),
        updatedAtIso: new Date().toISOString(),
        origen: `Recuperado (${batch.fechaHora || 'Impresión'})`,
        manual: true
      };
      PG_STATE.selectedIds.add(artId);
      restoredCount++;
    });

    const mostrarSel = document.getElementById('pg-filter-mostrar');
    if (mostrarSel && mostrarSel.value !== 'pendientes') {
      mostrarSel.value = 'pendientes';
    }
    document.getElementById('pg-history-dialog')?.close();
    syncGondolaQueueToServer();
    applyPreciosGondolaFilters(1);
    showPgFeedback(
      `<strong>↩️ Impresión recuperada:</strong> Se restauraron <strong>${restoredCount} artículo(s)</strong> (${Number(batch.totalLabels || restoredCount)} etiqueta${Number(batch.totalLabels || restoredCount) === 1 ? '' : 's'}) de la tanda <strong>${escapeHtml(batch.fechaHora || '')}</strong> a la lista pendiente.`
    );
  }

  function reprintGondolaHistoryBatchA4(batch, previewOnly = false) {
    const rows = buildRowsFromHistoryBatch(batch);
    if (rows.length === 0) {
      window.alert('No se pudieron reconstruir las etiquetas de esta tanda.');
      return;
    }
    document.getElementById('pg-history-dialog')?.close();
    if (previewOnly) {
      openPgA4PreviewModal(rows);
    } else {
      executePgPrintA4Document(false, rows);
    }
  }

  function renderPgHistoryModal() {
    const tbody = document.getElementById('pg-history-tbody');
    if (!tbody) return;
    ensureSeededGondolaPrintHistory();
    const list = Array.isArray(STATE.gondolaPrintHistory) ? STATE.gondolaPrintHistory : [];
    tbody.textContent = '';

    if (list.length === 0) {
      const tr = document.createElement('tr');
      const td = document.createElement('td');
      td.colSpan = 4;
      td.className = 'table-loading-cell';
      td.textContent = 'No hay tandas de impresión guardadas en el historial.';
      tr.appendChild(td);
      tbody.appendChild(tr);
      return;
    }

    list.forEach((batch, idx) => {
      const tr = document.createElement('tr');

      const tdFecha = document.createElement('td');
      tdFecha.innerHTML = `<div class="price-cell-stack"><strong>${escapeHtml(batch.fechaHora || '—')}</strong>${idx === 0 ? '<span class="badge badge--gold" style="font-size:0.66rem; width:fit-content;">ÚLTIMA TANDA</span>' : ''}</div>`;
      tr.appendChild(tdFecha);

      const tdTipo = document.createElement('td');
      tdTipo.innerHTML = `<div class="price-cell-stack"><strong>${escapeHtml(batch.tipo || 'Impresión A4')}</strong><span class="art-sub-meta">👤 ${escapeHtml(batch.usuario || 'Administrador')}</span></div>`;
      tr.appendChild(tdTipo);

      const tdCnt = document.createElement('td');
      const artCnt = Number(batch.articlesCount || (batch.items ? batch.items.length : 0));
      const lblCnt = Number(batch.totalLabels || artCnt);
      const shtCnt = Number(batch.totalSheets || Math.ceil(lblCnt / 27));
      tdCnt.innerHTML = `<div class="price-cell-stack"><strong>${artCnt} artículo${artCnt === 1 ? '' : 's'}</strong><span class="art-sub-meta">${lblCnt} etiq. · ${shtCnt} hoja${shtCnt === 1 ? '' : 's'} A4</span></div>`;
      tr.appendChild(tdCnt);

      const tdAct = document.createElement('td');
      tdAct.style.textAlign = 'right';
      const btnWrap = document.createElement('div');
      btnWrap.style.display = 'flex';
      btnWrap.style.justifyContent = 'flex-end';
      btnWrap.style.alignItems = 'center';
      btnWrap.style.gap = '0.45rem';
      btnWrap.style.flexWrap = 'nowrap';

      const uniformBtnStyle =
        'width:152px !important; min-width:152px !important; max-width:152px !important; height:36px !important; min-height:36px !important; display:inline-flex !important; align-items:center !important; justify-content:center !important; font-size:0.8rem !important; font-weight:700 !important; padding:0 0.5rem !important; white-space:nowrap !important; box-sizing:border-box !important; margin:0 !important;';

      const btnRest = document.createElement('button');
      btnRest.type = 'button';
      btnRest.className = 'btn-secondary btn-sm';
      btnRest.style.cssText = uniformBtnStyle;
      btnRest.title = 'Vuelve a cargar todos los artículos de esta tanda en la lista pendiente';
      btnRest.textContent = '↩️ Restaurar a Lista';
      btnRest.addEventListener('click', () => {
        restoreGondolaBatchToQueue(batch);
      });
      btnWrap.appendChild(btnRest);

      const btnPrev = document.createElement('button');
      btnPrev.type = 'button';
      btnPrev.className = 'btn-secondary btn-sm';
      btnPrev.style.cssText = uniformBtnStyle;
      btnPrev.title = 'Ver vista previa A4 de esta tanda';
      btnPrev.textContent = '👁️ Ver A4';
      btnPrev.addEventListener('click', () => {
        reprintGondolaHistoryBatchA4(batch, true);
      });
      btnWrap.appendChild(btnPrev);

      const btnReprint = document.createElement('button');
      btnReprint.type = 'button';
      btnReprint.className = 'btn-secondary btn-sm';
      btnReprint.style.cssText = uniformBtnStyle;
      btnReprint.title = 'Enviar nuevamente a la impresora las hojas A4 de esta tanda';
      btnReprint.textContent = '🖨️ Reimprimir';
      btnReprint.addEventListener('click', () => {
        reprintGondolaHistoryBatchA4(batch, false);
      });
      btnWrap.appendChild(btnReprint);

      tdAct.appendChild(btnWrap);
      tr.appendChild(tdAct);
      tbody.appendChild(tr);
    });
  }

  function openPgHistoryModal() {
    renderPgHistoryModal();
    const dlg = document.getElementById('pg-history-dialog');
    if (dlg && !dlg.open) {
      dlg.showModal();
    }
  }

  function markRowsAsUpdatedOnGondola(targetRows, fromPrint = false) {
    if (!Array.isArray(targetRows) || targetRows.length === 0) return;
    if (!STATE.gondolaQueue || typeof STATE.gondolaQueue !== 'object') {
      STATE.gondolaQueue = {};
    }

    const savedBatch = recordGondolaPrintHistoryBatch(
      targetRows,
      fromPrint ? 'Impresión Reporte A4 (PDF)' : 'Actualización en Góndola'
    );

    const targetIdSet = new Set();
    targetRows.forEach((r) => {
      const idNum = Number(r?.art?.id || r?.artId || 0);
      if (idNum > 0) targetIdSet.add(idNum);
    });

    let count = 0;
    Object.keys(STATE.gondolaQueue).forEach((k) => {
      const entry = STATE.gondolaQueue[k];
      const entryId = Number(entry?.artId || k || 0);
      if (targetIdSet.has(entryId) || targetIdSet.has(Number(k))) {
        delete STATE.gondolaQueue[k];
        count++;
      }
    });

    targetIdSet.forEach((idNum) => {
      delete STATE.gondolaQueue[String(idNum)];
      PG_STATE.selectedIds.delete(idNum);
      delete PG_STATE.manualCopiesMap[idNum];
    });

    // Si se imprimió todo el listado visible, limpiar cualquier selección residual y volver a vista de pendientes limpia
    if (fromPrint) {
      if (Object.keys(STATE.gondolaQueue).length === 0) {
        PG_STATE.selectedIds.clear();
        PG_STATE.manualCopiesMap = {};
      }
      const mostrarSel = document.getElementById('pg-filter-mostrar');
      if (mostrarSel && mostrarSel.value === 'todos_catalogo') {
        mostrarSel.value = 'pendientes';
      }
    }

    const effectiveCount = Math.max(count, targetIdSet.size);
    syncGondolaQueueToServer();
    applyPreciosGondolaFilters(1);
    if (effectiveCount > 0) {
      showPgFeedback(
        fromPrint
          ? `<strong>🖨️ Etiquetas enviadas a imprimir:</strong> Se quitaron <strong>${effectiveCount} artículo(s)</strong> del listado pendiente. Si falló la impresora, usá el botón <strong>"↩️ Recuperar Última Impresión"</strong> o <strong>"🕘 Historial de Impresiones"</strong>.`
          : `<strong>✅ Góndola actualizada:</strong> Se marcaron <strong>${effectiveCount} artículo(s)</strong> como colocados en góndola (respaldados en Historial de Impresiones).`
      );
      if (savedBatch) {
        const banner = document.getElementById('pg-feedback-banner');
        if (banner && !banner.hidden) {
          const btnQuickRestore = document.createElement('button');
          btnQuickRestore.type = 'button';
          btnQuickRestore.className = 'btn-secondary btn-sm';
          btnQuickRestore.style.marginInlineStart = '0.65rem';
          btnQuickRestore.style.width = 'auto';
          btnQuickRestore.style.fontWeight = '700';
          btnQuickRestore.textContent = '↩️ Recuperar ahora esta tanda';
          btnQuickRestore.addEventListener('click', () => {
            restoreGondolaBatchToQueue(savedBatch);
          });
          banner.appendChild(btnQuickRestore);
        }
      }
    }
  }

  function renderPgManualSuggestions(rawQuery) {
    const suggBox = document.getElementById('pg-manual-suggestions');
    if (!suggBox) return;
    const cleaned = extractCodeFromBarcodeOrQrPayload(rawQuery);
    const q = normalizeStr(cleaned);
    if (!q || q.length < 2) {
      suggBox.hidden = true;
      suggBox.textContent = '';
      return;
    }

    const tokens = q.split(/\s+/).filter(Boolean);
    const matches = [];
    for (const art of STATE.articulos) {
      if (art.bl === 1) continue;
      const bcs = Array.isArray(art.bc) ? art.bc.map((b) => b.c).join(' ') : '';
      const hay = normalizeStr(`${art.c} ${parseInt(art.c, 10) || ''} ${art.n} ${bcs}`);
      if (tokens.every((t) => hay.includes(t))) {
        matches.push(art);
        if (matches.length >= 8) break;
      }
    }

    if (matches.length === 0) {
      suggBox.hidden = true;
      suggBox.textContent = '';
      return;
    }

    suggBox.textContent = '';
    const frag = document.createDocumentFragment();
    matches.forEach((art) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'verificador-suggestion-item';
      const ean = Array.isArray(art.bc) && art.bc.length > 0 ? art.bc[0].c : `CÓD. ${art.c}`;
      btn.innerHTML = `
        <div class="verificador-sugg-left">
          <span class="verificador-sugg-code">#${escapeHtml(art.c)} · ${escapeHtml(ean)}</span>
          <strong class="verificador-sugg-name">${escapeHtml(art.n)}</strong>
        </div>
        <div class="verificador-sugg-right">
          <span class="verificador-sugg-price">$ ${formatArs(art.p1f || 0)}</span>
        </div>
      `;
      btn.addEventListener('click', () => {
        const copiesInp = document.getElementById('pg-manual-copias');
        const copies = Math.max(1, parseInt(copiesInp?.value || '1', 10) || 1);
        addManualArticleToGondolaQueue(art, copies);
        const inp = document.getElementById('pg-manual-input');
        if (inp) {
          inp.value = '';
          inp.focus();
        }
        suggBox.hidden = true;
        showPgFeedback(`<strong>➕ Agregado a Precios en Góndola:</strong> #${escapeHtml(art.c)} — <strong>${escapeHtml(art.n)}</strong> (${copies} copia${copies === 1 ? '' : 's'}).`);
      });
      frag.appendChild(btn);
    });
    suggBox.appendChild(frag);
    suggBox.hidden = false;
  }

