  function handleOfSugKeyNav(e, suggBoxId, fallbackEnterFn = null) {
    const suggBox = document.getElementById(suggBoxId);
    if (!suggBox || suggBox.hidden) {
      if (e.key === 'Enter' && typeof fallbackEnterFn === 'function') {
        e.preventDefault();
        fallbackEnterFn();
      }
      return;
    }
    const items = Array.from(suggBox.querySelectorAll('.fact-sug-item'));
    if (e.key === 'ArrowDown' && items.length > 0) {
      e.preventDefault();
      let cur = items.findIndex((el) => el.classList.contains('is-highlighted'));
      cur = (cur + 1) % items.length;
      items.forEach((el, i) => el.classList.toggle('is-highlighted', i === cur));
      items[cur]?.scrollIntoView({ block: 'nearest' });
      return;
    }
    if (e.key === 'ArrowUp' && items.length > 0) {
      e.preventDefault();
      let cur = items.findIndex((el) => el.classList.contains('is-highlighted'));
      cur = (cur - 1 + items.length) % items.length;
      items.forEach((el, i) => el.classList.toggle('is-highlighted', i === cur));
      items[cur]?.scrollIntoView({ block: 'nearest' });
      return;
    }
    if (e.key === 'Enter') {
      e.preventDefault();
      const activeItem =
        suggBox.querySelector('.fact-sug-item.is-highlighted') || items[0];
      if (activeItem) {
        activeItem.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));
      } else if (typeof fallbackEnterFn === 'function') {
        fallbackEnterFn();
      }
      return;
    }
    if (e.key === 'Escape') {
      e.preventDefault();
      suggBox.hidden = true;
    }
  }

