  // =========================================================================
  // VENTANA EMERGENTE DE ACTUALIZACIÓN DE NUEVA VERSIÓN (ESTILO REIKI ONLINE)
  // =========================================================================
  const CLIENT_APP_VERSION = (() => {
    try {
      const scriptEl = document.querySelector('script[src*="assets/js/app.js"]');
      const src = scriptEl ? scriptEl.getAttribute('src') || '' : '';
      const m = src.match(/[?&]v=([^&]+)/);
      if (m && m[1]) return `casa-nueva-erp-v${m[1]}`;
    } catch {}
    return 'casa-nueva-erp-v126';
  })();
  const ACK_VERSION_STORAGE_KEY = 'cn_erp_ack_version_v1';
  const DISMISSED_VERSION_SESSION_KEY = 'cn_erp_dismissed_version_v1';
  let waitingServiceWorker = null;
  let userConfirmedSwUpdate = false;
  let detectedServerAppVersion = CLIENT_APP_VERSION;

  const pwaUpdateToast = document.getElementById('pwa-update-toast');
  const pwaApplyUpdateBtn = document.getElementById('btn-pwa-apply-update');
  const pwaDismissUpdateBtn = document.getElementById('btn-pwa-dismiss-update');

  // Al iniciar la versión actual en el navegador, registrarla como confirmada para no repetir el aviso en vano
  try {
    localStorage.setItem(ACK_VERSION_STORAGE_KEY, CLIENT_APP_VERSION);
    sessionStorage.setItem(DISMISSED_VERSION_SESSION_KEY, CLIENT_APP_VERSION);
  } catch {}

  function extractErpVersionNumber(ver) {
    const m = String(ver || '').match(/v(\d+)/i);
    return m ? parseInt(m[1], 10) : 0;
  }

  function isVersionAlreadyAcknowledged(ver) {
    if (!ver) return true;
    if (ver === CLIENT_APP_VERSION) return true;
    const clientNum = extractErpVersionNumber(CLIENT_APP_VERSION);
    const targetNum = extractErpVersionNumber(ver);
    if (clientNum > 0 && targetNum > 0 && targetNum <= clientNum) return true;
    try {
      const ackVer = localStorage.getItem(ACK_VERSION_STORAGE_KEY);
      if (ackVer === ver) return true;
      const ackNum = extractErpVersionNumber(ackVer);
      if (ackNum > 0 && targetNum > 0 && targetNum <= ackNum) return true;
      if (sessionStorage.getItem(DISMISSED_VERSION_SESSION_KEY) === ver) return true;
    } catch {}
    return false;
  }

  function markVersionAcknowledged(ver) {
    const v = ver || detectedServerAppVersion || CLIENT_APP_VERSION;
    try {
      localStorage.setItem(ACK_VERSION_STORAGE_KEY, v);
      sessionStorage.setItem(DISMISSED_VERSION_SESSION_KEY, v);
    } catch {}
  }

  function showPwaUpdateToast(targetVer) {
    if (!pwaUpdateToast) return;
    if (!targetVer || isVersionAlreadyAcknowledged(targetVer)) return;
    pwaUpdateToast.hidden = false;
  }

  window.__notifyServerAppVersion = function (srvVersion) {
    if (!srvVersion) return;
    detectedServerAppVersion = srvVersion;
    if (srvVersion !== CLIENT_APP_VERSION && !isVersionAlreadyAcknowledged(srvVersion)) {
      showPwaUpdateToast(srvVersion);
    }
  };

  if (pwaDismissUpdateBtn) {
    pwaDismissUpdateBtn.addEventListener('click', () => {
      const dismissVer =
        detectedServerAppVersion && detectedServerAppVersion !== CLIENT_APP_VERSION
          ? detectedServerAppVersion
          : CLIENT_APP_VERSION;
      markVersionAcknowledged(dismissVer);
      if (pwaUpdateToast) {
        pwaUpdateToast.hidden = true;
      }
    });
  }

  if (pwaApplyUpdateBtn) {
    pwaApplyUpdateBtn.addEventListener('click', async () => {
      const targetVersion =
        detectedServerAppVersion && detectedServerAppVersion !== CLIENT_APP_VERSION
          ? detectedServerAppVersion
          : CLIENT_APP_VERSION;
      userConfirmedSwUpdate = true;
      markVersionAcknowledged(targetVersion);
      if (pwaUpdateToast) {
        pwaUpdateToast.hidden = true;
      }

      // Persistir usuario activo y sección actual para que la actualización mantenga la pantalla abierta sin salir del login
      if (STATE.currentUser) {
        savePersistedAdminSession(STATE.currentUser);
      }
      const currentOpenSec = Array.from(document.querySelectorAll('.erp-section')).find((s) => !s.hidden);
      if (currentOpenSec && currentOpenSec.id) {
        savePersistedNavState(currentOpenSec.id, STATE.activeCajaId || 'caja1');
      }

      // Si hay artículos cargados en una venta en curso, actualizar bases en caliente sin recargar ni perder el carrito
      if (Array.isArray(STATE.factItems) && STATE.factItems.length > 0) {
        Promise.all([
          loadCatalogDatabase(true),
          loadClientesDatabase(true),
          loadVentasDatabase(true)
        ]).catch(() => {});
        return;
      }

      if (waitingServiceWorker) {
        try {
          waitingServiceWorker.postMessage({ type: 'SKIP_WAITING' });
        } catch {}
      }

      try {
        if ('caches' in window) {
          const keys = await caches.keys();
          await Promise.all(keys.map((k) => caches.delete(k)));
        }
      } catch {}

      const cleanUrl = `${window.location.pathname}?_v=${encodeURIComponent(targetVersion)}${window.location.hash || ''}`;
      window.location.replace(cleanUrl);
    });
  }

  // =========================================================================
  // MÓDULO FONDOS · CUENTAS BANCARIAS Y BILLETERAS VIRTUALES
  // (ABM Entidades, Cuenta Corriente Bancaria, Conciliación, E-Cheq y Pase Posnet)
  // =========================================================================
  function parseFondosMoney(val) {
    if (typeof val === 'number') return Number.isFinite(val) ? val : 0;
    const raw = String(val ?? '').trim().replace(/\$/g, '').replace(/\s+/g, '');
    if (!raw) return 0;
    if (raw.includes(',') && raw.includes('.')) {
      if (raw.lastIndexOf(',') > raw.lastIndexOf('.')) {
        return Number(raw.replace(/\./g, '').replace(',', '.')) || 0;
      }
      return Number(raw.replace(/,/g, '')) || 0;
    }
    if (raw.includes(',')) {
      return Number(raw.replace(',', '.')) || 0;
    }
    return Number(raw) || 0;
  }

  function roundMoney(val) {
    const n = parseFondosMoney(val);
    return Math.round((n + Number.EPSILON) * 100) / 100;
  }

  function isRemovedDemoBankAccount(c) {
    if (!c || typeof c !== 'object') return false;
    const cbu = String(c.cbu || c.nroCuenta || '').trim();
    const alias = String(c.alias || '').trim().toUpperCase();
    if (cbu === '0200314801000012458092' || alias === 'CASANUEVA.BANCOR.CTA') return true;
    if (cbu === '0110102320011402589441' || alias === 'CASANUEVA.NACION.ERP') return true;
    return false;
  }

