  function renderCajaTesoreriaSection() {
    const sec = document.getElementById('sec-caja-tesoreria');
    if (!sec) return;
    if (!FONDOS_STATE.initialized) {
      loadFondosLocalState();
    }
    syncCajaMovementsFromConfirmedPlanillas(false);

    const totals = computeCajaTesoreriaTotals();

    const elSaldo = document.getElementById('caja-tes-kpi-saldo');
    const elIng = document.getElementById('caja-tes-kpi-ingresos');
    const elIngSub = document.getElementById('caja-tes-kpi-ingresos-sub');
    const elEgr = document.getElementById('caja-tes-kpi-egresos');
    const elCtrl = document.getElementById('caja-tes-kpi-control');
    const elCtrlSub = document.getElementById('caja-tes-kpi-control-sub');

    if (elSaldo) {
      elSaldo.textContent = `$ ${formatArs(totals.saldoActual)}`;
      elSaldo.style.color = totals.saldoActual < 0 ? 'var(--red-danger)' : 'var(--text-primary)';
    }
    if (elIng) elIng.textContent = `+ $ ${formatArs(totals.totalIngresos)}`;
    if (elIngSub) elIngSub.textContent = `${totals.planillasCount} planilla(s) confirmada(s) + cobros`;
    if (elEgr) elEgr.textContent = `- $ ${formatArs(totals.totalEgresos)}`;

    const lastCtrl = Array.isArray(FONDOS_STATE.controlesCaja) && FONDOS_STATE.controlesCaja.length > 0
      ? FONDOS_STATE.controlesCaja[0]
      : null;
    if (elCtrl) {
      if (lastCtrl) {
        const dif = roundMoney(lastCtrl.diferencia || 0);
        elCtrl.textContent = `$ ${formatArs(lastCtrl.efectivoContado || 0)}`;
        elCtrl.style.color = Math.abs(dif) < 0.01 ? 'var(--green-ok)' : 'var(--red-danger)';
      } else {
        elCtrl.textContent = 'SIN ARQUEO';
        elCtrl.style.color = '';
      }
    }
    if (elCtrlSub) {
      if (lastCtrl) {
        const dif = roundMoney(lastCtrl.diferencia || 0);
        elCtrlSub.textContent = `${lastCtrl.fechaHora || ''} · Dif: $ ${formatArs(dif)}`;
      } else {
        elCtrlSub.textContent = 'Usá "Control de Caja" para contar billetes';
      }
    }

    // Filtrar tabla de movimientos de Caja
    const fDesde = String(document.getElementById('caja-tes-filter-desde')?.value || '');
    const fHasta = String(document.getElementById('caja-tes-filter-hasta')?.value || '');
    const fTipo = String(document.getElementById('caja-tes-filter-tipo')?.value || 'TODOS');
    const fQ = String(document.getElementById('caja-tes-filter-q')?.value || '').trim().toUpperCase();

    const filteredMovs = totals.movementsDesc.filter((m) => {
      if (fDesde && String(m.fechaIso || '') < fDesde) return false;
      if (fHasta && String(m.fechaIso || '') > fHasta) return false;
      if (fTipo !== 'TODOS') {
        if (fTipo === 'CLIENTE') {
          if (m.imputacion !== 'CLIENTE_PAGO' && m.imputacion !== 'CLIENTE_COBRO') return false;
        } else if (m.imputacion !== fTipo) {
          return false;
        }
      }
      if (fQ) {
        const hay = `${m.comprobante || ''} ${m.tipo || ''} ${m.destinatario || ''} ${m.concepto || ''} ${m.usuario || ''}`.toUpperCase();
        if (!hay.includes(fQ)) return false;
      }
      return true;
    });

    const movsTbody = document.getElementById('caja-tes-movs-tbody');
    if (movsTbody) {
      if (filteredMovs.length === 0) {
        movsTbody.innerHTML =
          '<tr><td colspan="9" class="table-loading-cell">No hay movimientos de Caja para el filtro seleccionado.</td></tr>';
      } else {
        movsTbody.innerHTML = filteredMovs
          .map((m) => {
            const badgeStyle =
              m.imputacion === 'RENDICION_PLANILLA'
                ? 'background:#dbeafe;color:#1e40af;'
                : m.imputacion === 'PROVEEDOR'
                  ? 'background:#fef3c7;color:#92400e;'
                  : m.imputacion === 'GASTO'
                    ? 'background:#ffedd5;color:#c2410c;'
                    : m.imputacion === 'DEPOSITO_BANCARIO'
                      ? 'background:#dcfce7;color:#166534;'
                      : m.imputacion === 'RETIRO_PERSONAL'
                        ? 'background:#fee2e2;color:#991b1b;'
                        : 'background:#f1f5f9;color:#334155;';

            return `<tr>
              <td>
                <div class="price-cell-stack">
                  <strong>${escapeHtml(m.fechaHora || m.fechaIso || '')}</strong>
                  <span class="price-neto-val">${escapeHtml(m.usuario || 'ADMIN')}</span>
                </div>
              </td>
              <td><span class="art-code-pill">${escapeHtml(m.comprobante || 'S/N')}</span></td>
              <td><span class="badge" style="${badgeStyle}">${escapeHtml(m.tipo || m.imputacion || 'MOVIMIENTO')}</span></td>
              <td><strong>${escapeHtml(m.destinatario || '—')}</strong></td>
              <td>${escapeHtml(m.concepto || '—')}</td>
              <td class="num-col" style="color:var(--green-ok); font-weight:800;">${m.ingreso > 0 ? `+ $ ${formatArs(m.ingreso)}` : '—'}</td>
              <td class="num-col" style="color:var(--red-danger); font-weight:800;">${m.egreso > 0 ? `- $ ${formatArs(m.egreso)}` : '—'}</td>
              <td class="num-col"><strong>$ ${formatArs(m.saldoAcumulado)}</strong></td>
              <td style="text-align:center;">
                <div style="display:flex; gap:0.35rem; justify-content:center; align-items:center; flex-wrap:nowrap;">
                  <button type="button" class="btn-secondary btn-sm" data-caja-tes-print="${escapeHtml(m.id)}" style="width:auto; white-space:nowrap;" title="Imprimir Recibo / Comprobante">🖨️ Recibo</button>
                  ${
                    m.imputacion !== 'RENDICION_PLANILLA'
                      ? `<button type="button" class="btn-secondary btn-sm" data-caja-tes-del="${escapeHtml(m.id)}" style="width:auto; color:var(--red-danger);" title="Eliminar movimiento">🗑️</button>`
                      : ''
                  }
                </div>
              </td>
            </tr>`;
          })
          .join('');
      }
    }

    // Tabla de Historial de Controles de Caja
    const ctrlTbody = document.getElementById('caja-tes-controles-tbody');
    if (ctrlTbody) {
      const ctrls = Array.isArray(FONDOS_STATE.controlesCaja) ? FONDOS_STATE.controlesCaja : [];
      if (ctrls.length === 0) {
        ctrlTbody.innerHTML =
          '<tr><td colspan="6" class="table-loading-cell">Aún no se han registrado controles de billetes en Caja.</td></tr>';
      } else {
        ctrlTbody.innerHTML = ctrls
          .slice(0, 40)
          .map((ctrl) => {
            const dif = roundMoney(ctrl.diferencia || 0);
            const difColor = Math.abs(dif) < 0.01 ? 'var(--green-ok)' : dif > 0 ? '#1e40af' : 'var(--red-danger)';
            const difPrefix = dif > 0.009 ? '+ ' : dif < -0.009 ? '- ' : '';
            const billetesResumen = BILLETES_DENOMINACIONES.map((d) => {
              const q = Math.max(0, Math.floor(Number(ctrl.billetes?.[d]) || 0));
              return q > 0 ? `${q}x$${d.toLocaleString('es-AR')}` : '';
            })
              .filter(Boolean)
              .join(' · ');

            return `<tr>
              <td>
                <div class="price-cell-stack">
                  <strong>${escapeHtml(ctrl.fechaHora || '')}</strong>
                  <span class="price-neto-val">${escapeHtml(ctrl.usuario || 'ADMIN')}</span>
                </div>
              </td>
              <td class="num-col"><strong>$ ${formatArs(ctrl.saldoEsperado || 0)}</strong></td>
              <td class="num-col" style="color:#1e40af;"><strong>$ ${formatArs(ctrl.efectivoContado || 0)}</strong></td>
              <td class="num-col" style="color:${difColor}; font-weight:800;">${difPrefix}$ ${formatArs(Math.abs(dif))}</td>
              <td>
                <div class="price-cell-stack">
                  <span>${escapeHtml(billetesResumen || 'Sin billetes detallados')}</span>
                  ${ctrl.observacion ? `<span class="price-neto-val">${escapeHtml(ctrl.observacion)}</span>` : ''}
                </div>
              </td>
              <td style="text-align:center;">
                <button type="button" class="btn-secondary btn-sm" data-caja-tes-print-ctrl="${escapeHtml(ctrl.id)}" style="width:auto;">🖨️ Acta</button>
              </td>
            </tr>`;
          })
          .join('');
      }
    }
  }

  function openCajaTesoreriaControlDialog() {
    const dlg = document.getElementById('caja-tesoreria-control-dialog');
    if (!dlg) return;

    const totals = computeCajaTesoreriaTotals();
    const saldoEsperado = roundMoney(totals.saldoActual);

    CAJA_TESORERIA_UI.controlBilletes = {};
    BILLETES_DENOMINACIONES.forEach((d) => {
      CAJA_TESORERIA_UI.controlBilletes[d] = 0;
    });

    const monInp = document.getElementById('caja-tes-control-monedas');
    const obsInp = document.getElementById('caja-tes-control-obs');
    const adjChk = document.getElementById('caja-tes-control-ajustar-saldo');
    if (monInp) monInp.value = '0';
    if (obsInp) obsInp.value = '';
    if (adjChk) adjChk.checked = false;

    const updateControlTotals = () => {
      const sumB = sumBilletesMap(CAJA_TESORERIA_UI.controlBilletes);
      const monedas = roundMoney(Math.max(0, Number(monInp?.value) || 0));
      const contado = roundMoney(sumB.total + monedas);
      const dif = roundMoney(contado - saldoEsperado);

      const elEsp = document.getElementById('caja-tes-ctrl-esperado');
      const elCont = document.getElementById('caja-tes-ctrl-contado');
      const elCnt = document.getElementById('caja-tes-ctrl-billetes-count');
      const elDif = document.getElementById('caja-tes-ctrl-diferencia');
      const elDifLbl = document.getElementById('caja-tes-ctrl-dif-label');
      const elTfoot = document.getElementById('caja-tes-control-total-tfoot');

      if (elEsp) elEsp.textContent = `$ ${formatArs(saldoEsperado)}`;
      if (elCont) elCont.textContent = `$ ${formatArs(contado)}`;
      if (elCnt) elCnt.textContent = `${sumB.totalCount} billete(s) contado(s)`;
      if (elTfoot) elTfoot.textContent = `$ ${formatArs(contado)}`;

      if (elDif) {
        const prefix = dif > 0.009 ? '+ ' : dif < -0.009 ? '- ' : '';
        elDif.textContent = `${prefix}$ ${formatArs(Math.abs(dif))}`;
        elDif.style.color = Math.abs(dif) < 0.01 ? 'var(--green-ok)' : dif > 0 ? '#1e40af' : 'var(--red-danger)';
      }
      if (elDifLbl) {
        if (Math.abs(dif) < 0.01) {
          elDifLbl.textContent = '✅ Arqueo Exacto (Sin diferencia)';
          elDifLbl.style.color = 'var(--green-ok)';
        } else if (dif > 0) {
          elDifLbl.textContent = 'Sobrante en Caja respecto al saldo contable';
          elDifLbl.style.color = '#1e40af';
        } else {
          elDifLbl.textContent = 'Faltante en Caja respecto al saldo contable';
          elDifLbl.style.color = 'var(--red-danger)';
        }
      }
    };

    const tbody = document.getElementById('caja-tes-control-billetes-tbody');
    const qtyInputs = [];
    if (tbody) {
      tbody.textContent = '';
      BILLETES_DENOMINACIONES.forEach((denom, idx) => {
        const tr = document.createElement('tr');

        const tdDen = document.createElement('td');
        tdDen.innerHTML = renderBilleteDenomCellHtml(denom);
        tr.appendChild(tdDen);

        const tdNom = document.createElement('td');
        tdNom.className = 'cierre-cell-readonly-num';
        tdNom.textContent = `$ ${formatArs(denom)}`;
        tr.appendChild(tdNom);

        const tdQty = document.createElement('td');
        tdQty.className = 'cierre-cell-input';
        const inp = document.createElement('input');
        inp.type = 'text';
        inp.inputMode = 'numeric';
        inp.className = 'cierre-billete-qty-input';
        inp.value = '0';
        inp.addEventListener('focus', () => inp.select());
        tdQty.appendChild(inp);
        tr.appendChild(tdQty);

        const tdSub = document.createElement('td');
        tdSub.className = 'cierre-cell-subtotal';
        tdSub.textContent = '$ 0,00';
        tr.appendChild(tdSub);

        inp.addEventListener('input', () => {
          const digits = String(inp.value || '').replace(/[^\d]/g, '');
          const qty = digits ? Math.max(0, parseInt(digits, 10)) : 0;
          CAJA_TESORERIA_UI.controlBilletes[denom] = qty;
          tdSub.textContent = `$ ${formatArs(denom * qty)}`;
          updateControlTotals();
        });

        inp.addEventListener('blur', () => {
          inp.value = String(CAJA_TESORERIA_UI.controlBilletes[denom] || 0);
        });

        inp.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === 'ArrowDown') {
            e.preventDefault();
            if (idx < qtyInputs.length - 1) {
              qtyInputs[idx + 1].focus();
            } else {
              document.getElementById('btn-save-caja-tes-control')?.focus();
            }
          } else if (e.key === 'ArrowUp' && idx > 0) {
            e.preventDefault();
            qtyInputs[idx - 1].focus();
          }
        });

        qtyInputs.push(inp);
        tbody.appendChild(tr);
      });
    }

    monInp?.addEventListener('input', updateControlTotals);
    updateControlTotals();

    if (!dlg.open) {
      dlg.showModal();
    }
    requestAnimationFrame(() => {
      if (qtyInputs[0]) {
        qtyInputs[0].focus();
        qtyInputs[0].select();
      }
    });
  }

  window.initOrRefreshCajaTesoreriaSection = function () {
    loadFondosLocalState();
    loadClientesDatabase().then(() => {
      populateCajaTesoreriaSelectors();
    });

    const todayIso = getTodayIsoLocal();
    const fechaInp = document.getElementById('caja-tes-fecha');
    const compInp = document.getElementById('caja-tes-comprobante');
    if (fechaInp && !fechaInp.value) fechaInp.value = todayIso;
    if (compInp && !compInp.value) compInp.value = getNextReciboCajaSuggestedNumber();

    populateCajaTesoreriaSelectors();
    renderCajaTesoreriaSection();

    if (!CAJA_TESORERIA_UI.bound) {
      CAJA_TESORERIA_UI.bound = true;

      document.getElementById('caja-tes-tipo-imputacion')?.addEventListener('change', () => {
        populateCajaTesoreriaSelectors();
      });

      const searchInp = document.getElementById('caja-tes-tercero-search');
      const dropEl = document.getElementById('caja-tes-tercero-dropdown');
      const selEl = document.getElementById('caja-tes-tercero-select');

      const selectCajaTercero = (ent) => {
        CAJA_TESORERIA_UI.selectedTercero = ent || null;
        if (dropEl) dropEl.hidden = true;
        if (!ent) {
          if (searchInp) searchInp.value = '';
          if (selEl) selEl.value = '';
          return;
        }
        if (searchInp) searchInp.value = String(ent.nombre || '').trim();
        if (selEl) selEl.value = String(ent.id);
      };

      searchInp?.addEventListener('input', () => {
        const q = String(searchInp.value || '').trim().toUpperCase();
        if (!dropEl) return;
        if (!q) {
          dropEl.hidden = true;
          return;
        }
        const tipoImp = String(document.getElementById('caja-tes-tipo-imputacion')?.value || 'PROVEEDOR');
        const isProvFilter = tipoImp === 'PROVEEDOR';
        const matches = (Array.isArray(STATE.clientes) ? STATE.clientes : [])
          .filter((c) => {
            if (!c || c.baja || isSystemConfigClient(c)) return false;
            if (isProvFilter && !c.esProveedor) return false;
            const hay = `${c.nombre || ''} ${c.nroDoc || ''} ${c.cuit || ''}`.toUpperCase();
            return hay.includes(q);
          })
          .sort((a, b) =>
            String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es', { sensitivity: 'base' })
          )
          .slice(0, 25);

        if (matches.length === 0) {
          dropEl.hidden = true;
          return;
        }
        dropEl.innerHTML = matches
          .map(
            (ent) =>
              `<div class="pos-autocomplete-item" data-caja-tes-ent-id="${escapeHtml(String(ent.id))}">
                <strong>${escapeHtml(ent.nombre)}</strong>
                <span style="font-size:0.76rem; color:var(--text-secondary);">${ent.esProveedor ? 'PROVEEDOR' : 'CLIENTE'} ${ent.nroDoc ? `· ${escapeHtml(ent.nroDoc)}` : ''}</span>
              </div>`
          )
          .join('');
        dropEl.hidden = false;
      });

      dropEl?.addEventListener('click', (e) => {
        const item = e.target.closest('[data-caja-tes-ent-id]');
        if (!item) return;
        const id = Number(item.getAttribute('data-caja-tes-ent-id'));
        const ent = (STATE.clientes || []).find((c) => Number(c.id) === id);
        if (ent) selectCajaTercero(ent);
      });

      selEl?.addEventListener('change', () => {
        const id = Number(selEl.value);
        const ent = (STATE.clientes || []).find((c) => Number(c.id) === id) || null;
        selectCajaTercero(ent);
      });

      // Submit de Movimiento / Recibo de Caja
      document.getElementById('caja-tesoreria-mov-form')?.addEventListener('submit', async (e) => {
        e.preventDefault();
        const tipoImp = String(document.getElementById('caja-tes-tipo-imputacion')?.value || 'PROVEEDOR');
        const fechaIso = String(document.getElementById('caja-tes-fecha')?.value || getTodayIsoLocal());
        const comprobante =
          String(document.getElementById('caja-tes-comprobante')?.value || '').trim().toUpperCase() ||
          getNextReciboCajaSuggestedNumber();
        const importe = roundMoney(document.getElementById('caja-tes-importe')?.value);
        const conceptoUser = String(document.getElementById('caja-tes-concepto')?.value || '').trim().toUpperCase();
        const autoPrint = Boolean(document.getElementById('caja-tes-auto-print')?.checked);
        const imputarCtaCte = Boolean(document.getElementById('caja-tes-imputar-ctacte')?.checked);

        if (!(importe > 0)) {
          alert('Ingresá un importe en efectivo mayor a $ 0,00.');
          document.getElementById('caja-tes-importe')?.focus();
          return;
        }
        if (!conceptoUser) {
          alert('Ingresá el concepto o detalle del recibo / movimiento de Caja.');
          document.getElementById('caja-tes-concepto')?.focus();
          return;
        }

        const fParts = fechaIso.split('-');
        const fechaAr = fParts.length === 3 ? `${fParts[2]}/${fParts[1]}/${fParts[0]}` : fechaIso;
        const now = new Date();
        const horaStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
        const fechaHora = `${fechaAr} ${horaStr}`;
        const nowIso = now.toISOString();
        const usuario = STATE.currentUser?.name || STATE.currentUser?.username || 'ADMINISTRADOR';

        let destinatario = '';
        let tipoLabel = '';
        let esIngreso = false;

        if (tipoImp === 'PROVEEDOR' || tipoImp === 'CLIENTE_PAGO' || tipoImp === 'CLIENTE_COBRO') {
          let ent = CAJA_TESORERIA_UI.selectedTercero;
          if (!ent) {
            const selId = Number(document.getElementById('caja-tes-tercero-select')?.value);
            if (selId) ent = (STATE.clientes || []).find((c) => Number(c.id) === selId) || null;
          }
          if (!ent) {
            alert('Seleccioná el Proveedor o Cliente destinatario del recibo.');
            document.getElementById('caja-tes-tercero-search')?.focus();
            return;
          }
          destinatario = String(ent.nombre || '').trim().toUpperCase();
          esIngreso = tipoImp === 'CLIENTE_COBRO';
          tipoLabel =
            tipoImp === 'PROVEEDOR'
              ? 'RECIBO DE PAGO A PROVEEDOR'
              : tipoImp === 'CLIENTE_PAGO'
                ? 'RECIBO DE PAGO A CLIENTE'
                : 'RECIBO DE COBRO DE CLIENTE';

          if (imputarCtaCte) {
            // En Cuenta Corriente: cobro de cliente resta saldo deudor (-1); pago a proveedor o reintegro suma/cancela saldo acreedor (+1)
            const dh = esIngreso ? -1 : 1;
            await imputarMovimientoEnCuentaCorrienteTercero({
              terceroObj: ent,
              fechaIso,
              tipoComp: tipoLabel,
              numeroComp: comprobante,
              dh,
              importe,
              obs: `CAJA FONDOS · ${conceptoUser}`
            });
          }
        } else if (tipoImp === 'RETIRO_PERSONAL') {
          const persona = String(document.getElementById('caja-tes-retiro-persona')?.value || '').trim().toUpperCase();
          if (!persona) {
            alert('Indicá el titular o destinatario del Retiro Personal.');
            document.getElementById('caja-tes-retiro-persona')?.focus();
            return;
          }
          destinatario = persona;
          tipoLabel = 'RETIRO PERSONAL';
          esIngreso = false;
        } else if (tipoImp === 'DEPOSITO_BANCARIO') {
          const cuentaId = String(document.getElementById('caja-tes-cuenta-banco')?.value || '');
          const cta = FONDOS_STATE.cuentasBancarias.find((c) => c && c.id === cuentaId);
          if (!cta) {
            alert('Seleccioná la Cuenta Bancaria habilitada donde se deposita el efectivo.');
            return;
          }
          destinatario = `${cta.banco} (${cta.denominacion})`;
          tipoLabel = 'DEPÓSITO EN CUENTA BANCARIA';
          esIngreso = false;

          // Acreditar automáticamente el depósito de efectivo en la Cuenta Bancaria seleccionada
          FONDOS_STATE.movimientosBancarios.unshift({
            id: `MOV-DEP-${Date.now()}`,
            cuentaId: cta.id,
            fechaIso,
            tipo: 'DEPÓSITO DE EFECTIVO',
            concepto: `DEPÓSITO EN EFECTIVO DESDE CAJA · ${conceptoUser}`,
            comprobante,
            tercero: 'SUBMÓDULO CAJA',
            debe: importe,
            haber: 0,
            conciliado: false,
            createdAt: nowIso
          });
        } else {
          destinatario = 'INGRESO / APORTE A CAJA';
          tipoLabel = 'INGRESO MANUAL DE EFECTIVO';
          esIngreso = true;
        }

        const newMov = {
          id: `CAJA-MOV-${Date.now()}`,
          fechaIso,
          fechaHora,
          tipo: tipoLabel,
          imputacion: tipoImp,
          comprobante,
          destinatario,
          concepto: conceptoUser,
          ingreso: esIngreso ? importe : 0,
          egreso: esIngreso ? 0 : importe,
          usuario,
          createdAt: nowIso
        };

        FONDOS_STATE.movimientosCaja.unshift(newMov);
        saveFondosState(true);

        const impEl = document.getElementById('caja-tes-importe');
        const concEl = document.getElementById('caja-tes-concepto');
        const compEl = document.getElementById('caja-tes-comprobante');
        if (impEl) impEl.value = '';
        if (concEl) concEl.value = '';
        if (compEl) compEl.value = getNextReciboCajaSuggestedNumber();

        renderCajaTesoreriaSection();
        if (FONDOS_STATE.initialized) {
          renderAllFondosPanels();
        }

        if (autoPrint) {
          printReciboMovimientoCaja(newMov);
        }
      });

      // Filtros de tabla de movimientos de Caja
      ['caja-tes-filter-desde', 'caja-tes-filter-hasta', 'caja-tes-filter-tipo'].forEach((id) => {
        document.getElementById(id)?.addEventListener('change', renderCajaTesoreriaSection);
      });
      document.getElementById('caja-tes-filter-q')?.addEventListener('input', renderCajaTesoreriaSection);

      // Acciones en fila de movimientos de Caja
      document.getElementById('caja-tes-movs-tbody')?.addEventListener('click', (e) => {
        const printBtn = e.target.closest('[data-caja-tes-print]');
        if (printBtn) {
          const id = printBtn.getAttribute('data-caja-tes-print');
          const mov = FONDOS_STATE.movimientosCaja.find((m) => m && m.id === id);
          if (mov) printReciboMovimientoCaja(mov);
          return;
        }
        const delBtn = e.target.closest('[data-caja-tes-del]');
        if (delBtn) {
          const id = delBtn.getAttribute('data-caja-tes-del');
          const idx = FONDOS_STATE.movimientosCaja.findIndex((m) => m && m.id === id);
          if (idx >= 0) {
            FONDOS_STATE.movimientosCaja.splice(idx, 1);
            saveFondosState(true);
            renderCajaTesoreriaSection();
          }
        }
      });

      // Imprimir listado A4 de Movimientos de Caja
      document.getElementById('btn-caja-tes-print-extracto')?.addEventListener('click', () => {
        const totals = computeCajaTesoreriaTotals();
        const rowsHtml = totals.movementsDesc
          .map(
            (m) => `<tr>
              <td>${escapeHtml(m.fechaHora || m.fechaIso || '')}</td>
              <td>${escapeHtml(m.comprobante || 'S/N')}</td>
              <td>${escapeHtml(m.tipo || m.imputacion || '')}</td>
              <td>${escapeHtml(m.destinatario || '')}</td>
              <td>${escapeHtml(m.concepto || '')}</td>
              <td style="text-align:right; color:#15803d;">${m.ingreso > 0 ? `$ ${formatArs(m.ingreso)}` : ''}</td>
              <td style="text-align:right; color:#b91c1c;">${m.egreso > 0 ? `$ ${formatArs(m.egreso)}` : ''}</td>
              <td style="text-align:right; font-weight:800;">$ ${formatArs(m.saldoAcumulado)}</td>
            </tr>`
          )
          .join('');

        const w = window.open('', '_blank', 'width=980,height=760');
        if (!w) return;
        w.document.open();
        w.document.write(`<!DOCTYPE html>
          <html lang="es-AR">
          <head>
            <meta charset="UTF-8">
            <title>Movimientos de Caja - Casa Nueva Supermercado</title>
            <style>
              @page { size: A4 portrait; margin: 12mm; }
              body { font-family: Arial, sans-serif; color: #0f172a; font-size: 9pt; margin: 0; }
              h1 { font-size: 14pt; margin: 0 0 6px; }
              .meta { padding: 8px 10px; background: #f8fafc; border: 1px solid #cbd5e1; margin-bottom: 10px; }
              table { width: 100%; border-collapse: collapse; }
              th, td { border: 1px solid #cbd5e1; padding: 5px 6px; text-align: left; font-size: 8.5pt; }
              th { background: #e2e8f0; }
            </style>
          </head>
          <body>
            <h1>CASA NUEVA SUPERMERCADO · FONDOS · MOVIMIENTOS DE CAJA</h1>
            <div class="meta">
              <strong>Total Ingresos (+):</strong> $ ${formatArs(totals.totalIngresos)} ·
              <strong>Total Egresos (-):</strong> $ ${formatArs(totals.totalEgresos)} ·
              <strong>Saldo Disponible en Caja:</strong> $ ${formatArs(totals.saldoActual)}
            </div>
            <table>
              <thead>
                <tr>
                  <th>Fecha / Hora</th>
                  <th>N° Comp.</th>
                  <th>Operación</th>
                  <th>Destinatario / Origen</th>
                  <th>Concepto</th>
                  <th style="text-align:right;">Ingreso (+)</th>
                  <th style="text-align:right;">Egreso (-)</th>
                  <th style="text-align:right;">Saldo Caja</th>
                </tr>
              </thead>
              <tbody>${rowsHtml || '<tr><td colspan="8">Sin movimientos registrados.</td></tr>'}</tbody>
            </table>
            <script>window.onload = function(){ setTimeout(function(){ window.print(); }, 200); };<\/script>
          </body>
          </html>`);
        w.document.close();
      });

      // Control de Caja (Conteo de Billetes)
      ['btn-open-caja-tesoreria-control', 'btn-open-caja-tesoreria-control-2'].forEach((id) => {
        document.getElementById(id)?.addEventListener('click', openCajaTesoreriaControlDialog);
      });

      document.getElementById('btn-clear-caja-tes-control-billetes')?.addEventListener('click', () => {
        openCajaTesoreriaControlDialog();
      });

      ['btn-close-caja-tes-control-top', 'btn-cancel-caja-tes-control'].forEach((id) => {
        document.getElementById(id)?.addEventListener('click', () => {
          document.getElementById('caja-tesoreria-control-dialog')?.close();
        });
      });

      document.getElementById('caja-tesoreria-control-form')?.addEventListener('submit', (e) => {
        e.preventDefault();
        const totals = computeCajaTesoreriaTotals();
        const saldoEsperado = roundMoney(totals.saldoActual);
        const sumB = sumBilletesMap(CAJA_TESORERIA_UI.controlBilletes);
        const monedas = roundMoney(Math.max(0, Number(document.getElementById('caja-tes-control-monedas')?.value) || 0));
        const efectivoContado = roundMoney(sumB.total + monedas);
        const diferencia = roundMoney(efectivoContado - saldoEsperado);
        const observacion = String(document.getElementById('caja-tes-control-obs')?.value || '').trim().toUpperCase();
        const ajustar = Boolean(document.getElementById('caja-tes-control-ajustar-saldo')?.checked);

        const now = new Date();
        const fechaIso = getTodayIsoLocal();
        const fechaHora = `${todayFormatted()} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
        const usuario = STATE.currentUser?.name || STATE.currentUser?.username || 'ADMINISTRADOR';

        const ctrlRecord = {
          id: `CTRL-CAJA-${Date.now()}`,
          fechaIso,
          fechaHora,
          usuario,
          saldoEsperado,
          efectivoContado,
          monedas,
          diferencia,
          billetes: { ...CAJA_TESORERIA_UI.controlBilletes },
          observacion,
          createdAt: now.toISOString()
        };

        FONDOS_STATE.controlesCaja.unshift(ctrlRecord);

        if (ajustar && Math.abs(diferencia) >= 0.01) {
          FONDOS_STATE.movimientosCaja.unshift({
            id: `CAJA-AJ-${Date.now()}`,
            fechaIso,
            fechaHora,
            tipo: 'AJUSTE POR CONTROL DE CAJA (BILLETES)',
            imputacion: 'AJUSTE',
            comprobante: `ARQ-${Date.now().toString().slice(-6)}`,
            destinatario: 'CONTROL DE CAJA',
            concepto: `AJUSTE DE ARQUEO DE BILLETES (CONTADO: $ ${formatArs(efectivoContado)} vs ESPERADO: $ ${formatArs(saldoEsperado)})${observacion ? ` · ${observacion}` : ''}`,
            ingreso: diferencia > 0 ? Math.abs(diferencia) : 0,
            egreso: diferencia < 0 ? Math.abs(diferencia) : 0,
            usuario,
            createdAt: now.toISOString()
          });
        }

        saveFondosState(true);
        document.getElementById('caja-tesoreria-control-dialog')?.close();
        renderCajaTesoreriaSection();
      });

      document.getElementById('caja-tes-controles-tbody')?.addEventListener('click', (e) => {
        const btn = e.target.closest('[data-caja-tes-print-ctrl]');
        if (!btn) return;
        const id = btn.getAttribute('data-caja-tes-print-ctrl');
        const ctrl = FONDOS_STATE.controlesCaja.find((c) => c && c.id === id);
        if (ctrl) printControlCajaActa(ctrl);
      });
    }
  };

