  const MESES_NOMBRES_OP = [
    'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
    'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
  ];

  function formatPeriodoImputadoLabel(periodoYm) {
    const parts = String(periodoYm || '').split('-');
    if (parts.length !== 2) return periodoYm || '—';
    const y = Number(parts[0]);
    const m = Number(parts[1]);
    if (!y || !(m >= 1 && m <= 12)) return periodoYm;
    return `${MESES_NOMBRES_OP[m - 1]} ${y}`;
  }

  function getNextOrdenPagoNumber() {
    let maxNum = 0;
    const ops = Array.isArray(FONDOS_STATE.ordenesPago) ? FONDOS_STATE.ordenesPago : [];
    ops.forEach((op) => {
      const m = String(op?.numero || '').match(/(\d+)$/);
      if (m) {
        const n = parseInt(m[1], 10);
        if (Number.isFinite(n) && n > maxNum) maxNum = n;
      }
    });
    return `OP 0099-${String(maxNum + 1).padStart(8, '0')}`;
  }

