  function applyOrdenPagoModeSwitch(newMode) {
    ORDEN_PAGO_UI.modo = newMode === 'GASTO' ? 'GASTO' : 'COMPRA_MERCADERIA';
    const isMercaderia = ORDEN_PAGO_UI.modo === 'COMPRA_MERCADERIA';

    const chkMerc = document.getElementById('op-chk-compra-mercaderia');
    const chkGasto = document.getElementById('op-chk-gastos');
    if (chkMerc) chkMerc.checked = isMercaderia;
    if (chkGasto) chkGasto.checked = !isMercaderia;

    const lblMerc = document.getElementById('op-lbl-compra-mercaderia');
    const lblGasto = document.getElementById('op-lbl-gastos');
    if (lblMerc) {
      lblMerc.style.borderColor = isMercaderia ? '#1d4ed8' : '#cbd5e1';
      lblMerc.style.background = isMercaderia ? 'linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%)' : '#ffffff';
    }
    if (lblGasto) {
      lblGasto.style.borderColor = !isMercaderia ? '#ea580c' : '#cbd5e1';
      lblGasto.style.background = !isMercaderia ? 'linear-gradient(135deg, #fff7ed 0%, #ffedd5 100%)' : '#ffffff';
    }

    const panelMerc = document.getElementById('op-panel-compra-mercaderia');
    const panelGasto = document.getElementById('op-panel-gastos');
    if (panelMerc) panelMerc.hidden = !isMercaderia;
    if (panelGasto) panelGasto.hidden = isMercaderia;

    if (!isMercaderia) {
      updateOrdenPagoGastoLiveKpis();
    }
  }

  function computeOpProviderPendingComprobantes(provId) {
    const stateMovs = Array.isArray(STATE.movimientosPorCliente?.[String(provId)])
      ? STATE.movimientosPorCliente[String(provId)]
      : [];
    const cachedMovs = ORDEN_PAGO_UI.provMovementsCache.get(Number(provId)) || [];
    const movs = stateMovs.length >= cachedMovs.length ? stateMovs : cachedMovs;

    const toSortableDate = (raw) => {
      const s = String(raw || '').trim();
      const mAr = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
      if (mAr) return `${mAr[3]}-${mAr[2]}-${mAr[1]}`;
      return s;
    };

    const sorted = [...movs].sort((a, b) => {
      const fa = toSortableDate(a.fi || a.fecha || a.f || '');
      const fb = toSortableDate(b.fi || b.fecha || b.f || '');
      if (fa !== fb) return fa.localeCompare(fb);
      return Number(a.id || 0) - Number(b.id || 0);
    });

    // En Cuenta Corriente COMPRA: dh === -1 es factura de compra (deuda con el proveedor), dh === 1 es pago realizado
    let totalPagos = 0;
    const cargos = [];
    sorted.forEach((m) => {
      if (!m || m.esCompensacion) return;
      const origUpper = String(m.origen || 'COMPRA').toUpperCase();
      if (origUpper !== 'COMPRA' && origUpper !== '') return;
      const imp = roundMoney(Math.abs(Number(m.importe ?? m.imp ?? Math.max(Number(m.debe || m.d || 0), Number(m.haber || m.h || 0))) || 0));
      if (!(imp > 0)) return;
      if (Number(m.dh) === -1) {
        const rawFecha = String(m.fi || m.fecha || m.f || '');
        const fAr = rawFecha.includes('/') ? rawFecha : formatIsoDateToAr(rawFecha);
        const tipoStr = String(m.tipoComp || m.tipo || m.tcn || 'FACTURA DE COMPRA').trim();
        const numStr = String(m.comprobante || m.numero || m.n || 'S/N').trim();
        cargos.push({
          id: String(m.id || `${rawFecha}-${numStr}`),
          fechaIso: toSortableDate(rawFecha),
          fechaAr: fAr,
          tipo: tipoStr,
          numero: numStr,
          obs: String(m.obs || '').trim(),
          importeOriginal: imp,
          pagadoPrevio: 0,
          saldoPendiente: imp
        });
      } else if (Number(m.dh) === 1) {
        totalPagos = roundMoney(totalPagos + imp);
      }
    });

    let remPagos = totalPagos;
    cargos.forEach((c) => {
      if (remPagos <= 0) return;
      const aplica = Math.min(c.saldoPendiente, remPagos);
      c.pagadoPrevio = roundMoney(aplica);
      c.saldoPendiente = roundMoney(c.saldoPendiente - aplica);
      remPagos = roundMoney(remPagos - aplica);
    });

    const pendientes = cargos.filter((c) => c.saldoPendiente >= 0.01);
    const totalDeudaComprobantes = roundMoney(pendientes.reduce((acc, c) => acc + c.saldoPendiente, 0));
    const saldoNetoProveedor = roundMoney(totalDeudaComprobantes - remPagos);

    return {
      pendientes,
      saldoNetoProveedor
    };
  }

  function renderOpProveedorState() {
    const prov = ORDEN_PAGO_UI.selectedProveedor;
    const kpisWrap = document.getElementById('op-prov-kpis');
    const actionBar = document.getElementById('op-mercaderia-action-bar');
    const clearBtn = document.getElementById('btn-op-clear-prov');
    const tbody = document.getElementById('op-prov-pendientes-tbody');
    const badgeCnt = document.getElementById('op-prov-pendientes-count-badge');
    const confirmBtn = document.getElementById('btn-op-confirmar-mercaderia');

    if (!prov) {
      if (kpisWrap) kpisWrap.hidden = true;
      if (actionBar) actionBar.hidden = true;
      if (clearBtn) clearBtn.hidden = true;
      if (badgeCnt) badgeCnt.textContent = '0 pendientes';
      if (confirmBtn) confirmBtn.disabled = true;
      if (tbody) {
        tbody.innerHTML = '<tr><td colspan="8" class="table-loading-cell">Seleccioná un proveedor arriba para listar sus facturas de compra pendientes de pago.</td></tr>';
      }
      return;
    }

    if (kpisWrap) kpisWrap.hidden = false;
    if (actionBar) actionBar.hidden = false;
    if (clearBtn) clearBtn.hidden = false;

    const { pendientes, saldoNetoProveedor } = computeOpProviderPendingComprobantes(prov.id);
    ORDEN_PAGO_UI.provPendingComprobantes = pendientes;

    const montoInp = document.getElementById('op-prov-monto-input');
    let montoAbonar = roundMoney(Math.max(0, Number(montoInp?.value) || 0));

    if (ORDEN_PAGO_UI.manualSelectionMode) {
      let sumChecked = 0;
      pendientes.forEach((c) => {
        if (ORDEN_PAGO_UI.selectedCompIds.has(c.id)) {
          sumChecked = roundMoney(sumChecked + c.saldoPendiente);
        }
      });
      montoAbonar = sumChecked;
      if (montoInp && document.activeElement !== montoInp) {
        montoInp.value = montoAbonar > 0 ? montoAbonar.toFixed(2) : '';
      }
    } else {
      ORDEN_PAGO_UI.selectedCompIds.clear();
      let rem = montoAbonar;
      pendientes.forEach((c) => {
        if (rem > 0.009) {
          ORDEN_PAGO_UI.selectedCompIds.add(c.id);
          rem = roundMoney(rem - c.saldoPendiente);
        }
      });
    }

    // Calcular distribución por comprobante
    let remDist = montoAbonar;
    const rowsCalc = pendientes.map((c) => {
      let aplica = 0;
      if (ORDEN_PAGO_UI.manualSelectionMode) {
        if (ORDEN_PAGO_UI.selectedCompIds.has(c.id) && remDist > 0) {
          aplica = roundMoney(Math.min(c.saldoPendiente, remDist));
          remDist = roundMoney(remDist - aplica);
        }
      } else if (remDist > 0) {
        aplica = roundMoney(Math.min(c.saldoPendiente, remDist));
        remDist = roundMoney(remDist - aplica);
      }
      const saldoPost = roundMoney(Math.max(0, c.saldoPendiente - aplica));
      return { ...c, aplica, saldoPost };
    });

    const elNom = document.getElementById('op-kpi-prov-nombre');
    const elMeta = document.getElementById('op-kpi-prov-meta');
    const elSaldo = document.getElementById('op-kpi-prov-saldo');
    const elSaldoSub = document.getElementById('op-kpi-prov-saldo-sub');
    const elAbonar = document.getElementById('op-kpi-prov-abonar');
    const elAbonarSub = document.getElementById('op-kpi-prov-abonar-sub');
    const elRest = document.getElementById('op-kpi-prov-restante');
    const elRestSub = document.getElementById('op-kpi-prov-restante-sub');

    if (elNom) elNom.textContent = prov.nombre || 'PROVEEDOR';
    if (elMeta) elMeta.textContent = `Cód. #${prov.codigo || prov.id} · CUIT/Doc: ${prov.nroDoc || prov.cuit || 'S/D'}`;
    if (elSaldo) elSaldo.textContent = `$ ${formatArs(saldoNetoProveedor)}`;
    if (elSaldoSub) elSaldoSub.textContent = `${pendientes.length} factura(s) de compra pendiente(s)`;
    if (elAbonar) elAbonar.textContent = `$ ${formatArs(montoAbonar)}`;
    const aplicadosCount = rowsCalc.filter((r) => r.aplica > 0.009).length;
    if (elAbonarSub) {
      elAbonarSub.textContent = aplicadosCount > 0
        ? `Cubre ${aplicadosCount} comprobante(s)`
        : montoAbonar > 0
          ? 'Pago a cuenta en Cta. Cte. Proveedor'
          : 'Ingresá monto o tildá facturas';
    }
    const restante = roundMoney(Math.max(0, saldoNetoProveedor - montoAbonar));
    if (elRest) elRest.textContent = `$ ${formatArs(restante)}`;
    if (elRestSub) elRestSub.textContent = restante <= 0.009 ? '✅ Deuda cancelada en su totalidad' : 'Saldo pendiente luego de esta OP';
    if (badgeCnt) badgeCnt.textContent = `${pendientes.length} pendiente(s)`;
    if (confirmBtn) confirmBtn.disabled = !(montoAbonar > 0);

    if (tbody) {
      if (rowsCalc.length === 0) {
        tbody.innerHTML = '<tr><td colspan="8" class="table-loading-cell">Este proveedor no registra facturas pendientes en Cuenta Corriente. Podés ingresar igualmente un Monto a Abonar para registrar una Orden de Pago por Compra de Mercadería.</td></tr>';
      } else {
        tbody.innerHTML = rowsCalc
          .map((r) => {
            const isChecked = r.aplica > 0.009 || ORDEN_PAGO_UI.selectedCompIds.has(r.id);
            let estBadge = '<span class="badge" style="background:#f1f5f9;color:#475569;">PENDIENTE</span>';
            if (r.aplica >= r.saldoPendiente - 0.01) {
              estBadge = '<span class="badge" style="background:#dcfce7;color:#166534;">SE CANCELA TOTAL</span>';
            } else if (r.aplica > 0.009) {
              estBadge = '<span class="badge" style="background:#fef3c7;color:#92400e;">PAGO PARCIAL</span>';
            }
            return `<tr style="${isChecked ? 'background:#eff6ff;' : ''}">
              <td style="text-align:center;">
                <input type="checkbox" data-op-comp-chk="${escapeHtml(r.id)}" ${isChecked ? 'checked' : ''} style="width:17px;height:17px;accent-color:#1d4ed8;cursor:pointer;">
              </td>
              <td><strong>${escapeHtml(r.fechaAr || r.fechaIso)}</strong></td>
              <td>
                <div class="price-cell-stack">
                  <strong>${escapeHtml(r.tipo)} ${escapeHtml(r.numero)}</strong>
                  ${r.obs ? `<span class="price-neto-val">${escapeHtml(r.obs)}</span>` : ''}
                </div>
              </td>
              <td class="num-col">$ ${formatArs(r.importeOriginal)}</td>
              <td class="num-col" style="color:var(--text-secondary);">$ ${formatArs(r.pagadoPrevio)}</td>
              <td class="num-col" style="font-weight:800; color:#dc2626;">$ ${formatArs(r.saldoPendiente)}</td>
              <td class="num-col" style="font-weight:800; color:#1d4ed8;">${r.aplica > 0 ? `$ ${formatArs(r.aplica)}` : '—'}</td>
              <td style="text-align:center;">${estBadge}</td>
            </tr>`;
          })
          .join('');
      }
    }
  }

  async function selectOpProveedor(prov) {
    ORDEN_PAGO_UI.selectedProveedor = prov || null;
    ORDEN_PAGO_UI.selectedCompIds.clear();
    ORDEN_PAGO_UI.manualSelectionMode = false;

    const searchInp = document.getElementById('op-prov-search');
    const sugEl = document.getElementById('op-prov-suggestions');
    const quickSel = document.getElementById('op-prov-quick-select');
    const montoInp = document.getElementById('op-prov-monto-input');

    if (sugEl) sugEl.hidden = true;
    if (!prov) {
      if (searchInp) searchInp.value = '';
      if (quickSel) quickSel.value = '';
      if (montoInp) montoInp.value = '';
      renderOpProveedorState();
      return;
    }

    if (searchInp) searchInp.value = String(prov.nombre || '').trim();
    if (quickSel) quickSel.value = String(prov.id);

    try {
      const res = await fetch(`api/clientes.php?action=movimientos&id=${encodeURIComponent(prov.id)}&origen=COMPRA&_t=${Date.now()}`, { cache: 'no-store' });
      if (res.ok) {
        const data = await res.json();
        ORDEN_PAGO_UI.provMovementsCache.set(Number(prov.id), Array.isArray(data.movimientos) ? data.movimientos : []);
      }
    } catch {}

    const { pendientes, saldoNetoProveedor } = computeOpProviderPendingComprobantes(prov.id);
    if (montoInp) {
      if (pendientes.length > 0) {
        ORDEN_PAGO_UI.manualSelectionMode = true;
        pendientes.forEach((c) => ORDEN_PAGO_UI.selectedCompIds.add(c.id));
        const totalSel = roundMoney(pendientes.reduce((acc, c) => acc + c.saldoPendiente, 0));
        montoInp.value = totalSel > 0 ? totalSel.toFixed(2) : '';
      } else if (saldoNetoProveedor > 0) {
        montoInp.value = saldoNetoProveedor.toFixed(2);
      } else {
        montoInp.value = '';
      }
    }

    renderOpProveedorState();
  }

  function updateOrdenPagoGastoLiveKpis() {
    const catId = String(document.getElementById('op-gasto-categoria-select')?.value || '');
    const catObj = (FONDOS_STATE.categoriasGastos || []).find((c) => c && c.id === catId) || null;
    const mesVal = String(document.getElementById('op-gasto-mes-select')?.value || '').padStart(2, '0');
    const anioVal = String(document.getElementById('op-gasto-anio-select')?.value || new Date().getFullYear());
    const periodoYm = `${anioVal}-${mesVal}`;
    const monto = roundMoney(Math.max(0, Number(document.getElementById('op-gasto-monto-input')?.value) || 0));
    const medio = String(document.getElementById('op-gasto-medio-pago')?.value || 'Efectivo');

    const elCat = document.getElementById('op-gasto-kpi-cat');
    const elCatSub = document.getElementById('op-gasto-kpi-cat-sub');
    const elPer = document.getElementById('op-gasto-kpi-periodo');
    const elMonto = document.getElementById('op-gasto-kpi-monto');
    const elMedio = document.getElementById('op-gasto-kpi-medio');
    const elAcum = document.getElementById('op-gasto-kpi-acum-mes');
    const elAcumSub = document.getElementById('op-gasto-kpi-acum-mes-sub');

    if (elCat) elCat.textContent = catObj ? catObj.nombre : 'SELECCIONÁ GASTO';
    if (elCatSub) elCatSub.textContent = catObj?.descripcion || 'Rubro operativo del egreso';
    if (elPer) elPer.textContent = formatPeriodoImputadoLabel(periodoYm).toUpperCase();
    if (elMonto) elMonto.textContent = `$ ${formatArs(monto)}`;
    if (elMedio) elMedio.textContent = `Descuenta de Caja Central (${medio})`;

    // Calcular total de gastos ya imputados a ese mes calendario
    let acumMes = 0;
    let countMes = 0;
    const ops = Array.isArray(FONDOS_STATE.ordenesPago) ? FONDOS_STATE.ordenesPago : [];
    ops.forEach((o) => {
      if (o && o.tipoOrden === 'GASTO' && String(o.periodoImputado || '') === periodoYm) {
        acumMes = roundMoney(acumMes + roundMoney(o.importe || 0));
        countMes += 1;
      }
    });
    if (elAcum) elAcum.textContent = `$ ${formatArs(acumMes)}`;
    if (elAcumSub) elAcumSub.textContent = `${countMes} gasto(s) imputado(s) a ${formatPeriodoImputadoLabel(periodoYm)}`;
  }

  function renderOrdenPagoHistorialTable() {
    const tbody = document.getElementById('op-historial-tbody');
    if (!tbody) return;

    const fTipo = String(document.getElementById('op-hist-filter-tipo')?.value || 'TODOS');
    const fPer = String(document.getElementById('op-hist-filter-periodo')?.value || '');
    const fQ = String(document.getElementById('op-hist-filter-q')?.value || '').trim().toUpperCase();

    const ops = Array.isArray(FONDOS_STATE.ordenesPago) ? FONDOS_STATE.ordenesPago : [];
    const filtered = ops.filter((op) => {
      if (!op) return false;
      if (fTipo !== 'TODOS' && op.tipoOrden !== fTipo) return false;
      if (fPer) {
        const opPer = op.tipoOrden === 'GASTO'
          ? String(op.periodoImputado || '')
          : String(op.fechaIso || '').slice(0, 7);
        if (opPer !== fPer) return false;
      }
      if (fQ) {
        const hay = `${op.numero || ''} ${op.proveedorNombre || ''} ${op.categoriaNombre || ''} ${op.beneficiario || ''} ${op.concepto || ''} ${op.observacion || ''}`.toUpperCase();
        if (!hay.includes(fQ)) return false;
      }
      return true;
    });

    if (filtered.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="table-loading-cell">No hay Órdenes de Pago registradas para el filtro seleccionado.</td></tr>';
      return;
    }

    tbody.innerHTML = filtered
      .slice(0, 120)
      .map((op) => {
        const isGasto = op.tipoOrden === 'GASTO';
        const badgeHtml = isGasto
          ? '<span class="badge" style="background:#ffedd5;color:#c2410c;">🧾 GASTO</span>'
          : '<span class="badge" style="background:#dbeafe;color:#1e40af;">📦 COMPRA MERCADERÍA</span>';
        const destTitle = isGasto ? (op.categoriaNombre || 'GASTO') : (op.proveedorNombre || 'PROVEEDOR');
        const destSub = isGasto ? (op.beneficiario || '') : (op.proveedorDoc ? `CUIT: ${op.proveedorDoc}` : '');
        const periodoStr = isGasto
          ? formatPeriodoImputadoLabel(op.periodoImputado)
          : formatPeriodoImputadoLabel(String(op.fechaIso || '').slice(0, 7));

        return `<tr>
          <td>
            <div class="price-cell-stack">
              <strong>${escapeHtml(op.fechaHora || op.fechaIso || '')}</strong>
              <span class="price-neto-val">${escapeHtml(op.usuario || 'ADMIN')}</span>
            </div>
          </td>
          <td><span class="art-code-pill">${escapeHtml(op.numero || 'S/N')}</span></td>
          <td>${badgeHtml}</td>
          <td>
            <div class="price-cell-stack">
              <strong>${escapeHtml(destTitle)}</strong>
              ${destSub ? `<span class="price-neto-val">${escapeHtml(destSub)}</span>` : ''}
            </div>
          </td>
          <td><span class="badge" style="background:#f1f5f9;color:#334155;font-weight:700;">${escapeHtml(periodoStr)}</span></td>
          <td>
            <div class="price-cell-stack">
              <span>${escapeHtml(op.concepto || op.observacion || '—')}</span>
              <span class="price-neto-val">Medio: ${escapeHtml(op.medioPago || 'Efectivo')}</span>
            </div>
          </td>
          <td class="num-col" style="color:var(--red-danger); font-weight:900;">- $ ${formatArs(op.importe || 0)}</td>
          <td style="text-align:center;">
            <div style="display:flex; gap:0.35rem; justify-content:center;">
              <button type="button" class="btn-secondary btn-sm" data-op-print="${escapeHtml(op.id)}" style="width:auto;">🖨️ OP</button>
              <button type="button" class="btn-secondary btn-sm" data-op-del="${escapeHtml(op.id)}" style="width:auto; color:var(--red-danger);" title="Eliminar Orden de Pago">🗑️</button>
            </div>
          </td>
        </tr>`;
      })
      .join('');
  }

  let _reconcilingOpsIntoCtaCte = false;
  async function reconcileLocalOrdenesPagoIntoCtaCte() {
    if (_reconcilingOpsIntoCtaCte) return;
    const ops = Array.isArray(FONDOS_STATE.ordenesPago) ? FONDOS_STATE.ordenesPago : [];
    const mercOps = ops.filter((o) => o && o.tipoOrden === 'COMPRA_MERCADERIA' && roundMoney(o.importe) > 0);
    if (mercOps.length === 0) return;

    _reconcilingOpsIntoCtaCte = true;
    try {
      await loadClientesDatabase();
      for (const op of [...mercOps].reverse()) {
        let prov = (STATE.clientes || []).find((c) => Number(c.id) === Number(op.proveedorId));
        if (!prov && op.proveedorNombre) {
          const targetNom = String(op.proveedorNombre).trim().toUpperCase();
          prov = (STATE.clientes || []).find((c) => c && String(c.nombre || '').trim().toUpperCase() === targetNom);
        }
        if (!prov) continue;

        const cleanNro = String(op.numero || '').replace(/^(OP|RE|RC)\s+X?\s*/i, '').trim().toUpperCase();
        if (!cleanNro) continue;

        const existingMovs = STATE.movimientosPorCliente?.[String(prov.id)] || [];
        const alreadyInCtaCte = existingMovs.some((m) => {
          if (!m) return false;
          const compStr = String(m.comprobante || m.n || '').toUpperCase();
          return compStr.includes(cleanNro) && Number(m.dh) === 1;
        });

        if (!alreadyInCtaCte) {
          const savedMov = await imputarMovimientoEnCuentaCorrienteTercero({
            terceroObj: prov,
            fechaIso: op.fechaIso || getTodayIsoLocal(),
            tipoComp: 'ORDEN DE PAGO (COMPRA MERCADERÍA)',
            numeroComp: op.numero || cleanNro,
            dh: 1,
            importe: roundMoney(op.importe),
            obs: `CAJA CENTRAL · ${op.concepto || op.observacion || 'COMPRA DE MERCADERÍA'}`,
            origen: 'COMPRA',
            imputaciones: op.imputacionesDetalle || []
          });
          if (savedMov && savedMov.id) {
            op.ctacteMovId = Number(savedMov.id);
          }
        }
      }
    } finally {
      _reconcilingOpsIntoCtaCte = false;
    }
  }

  window.initOrRefreshFondosOrdenPagoSection = function () {
    loadFondosLocalState();
    updateOrdenPagoHeaderStatus();
    populateGastosCategorySelectors();

    // Inicializar selectores de fecha y mes imputado por defecto
    const now = new Date();
    const curYear = String(now.getFullYear());
    const curMonth = String(now.getMonth() + 1).padStart(2, '0');
    const todayIso = getTodayIsoLocal();

    const mesSel = document.getElementById('op-gasto-mes-select');
    const anioSel = document.getElementById('op-gasto-anio-select');
    const fechaGastoInp = document.getElementById('op-gasto-fecha-pago');
    if (mesSel && !mesSel.dataset.initialized) {
      mesSel.value = curMonth;
      mesSel.dataset.initialized = '1';
    }
    if (anioSel && !anioSel.dataset.initialized) {
      anioSel.value = curYear;
      anioSel.dataset.initialized = '1';
    }
    if (fechaGastoInp && !fechaGastoInp.value) {
      fechaGastoInp.value = todayIso;
    }

    // Poblar selector rápido de proveedores y reconciliar OPs previas en Cta. Cte.
    loadClientesDatabase().then(async () => {
      await reconcileLocalOrdenesPagoIntoCtaCte();
      const quickSel = document.getElementById('op-prov-quick-select');
      if (quickSel) {
        const provs = (Array.isArray(STATE.clientes) ? STATE.clientes : [])
          .filter((c) => c && !c.baja && c.esProveedor && !isSystemConfigClient(c))
          .sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es', { sensitivity: 'base' }));
        const prev = quickSel.value;
        quickSel.innerHTML =
          '<option value="">— Seleccionar proveedor de la lista —</option>' +
          provs.map((p) => `<option value="${escapeHtml(String(p.id))}">${escapeHtml(p.nombre)} (${escapeHtml(p.nroDoc || p.cuit || 'S/D')})</option>`).join('');
        if (prev) quickSel.value = prev;
      }
      if (ORDEN_PAGO_UI.selectedProveedor) {
        renderOpProveedorState();
      }
    });

    // Poblar bancos de transferencia
    ['op-prov-banco-select', 'op-gasto-banco-select'].forEach((id) => {
      const el = document.getElementById(id);
      if (el) populateTransferenciaBankSelect(el, el.value);
    });

    applyOrdenPagoModeSwitch(ORDEN_PAGO_UI.modo || 'COMPRA_MERCADERIA');
    renderOpProveedorState();
    updateOrdenPagoGastoLiveKpis();
    renderOrdenPagoHistorialTable();

    if (!ORDEN_PAGO_UI.bound) {
      ORDEN_PAGO_UI.bound = true;

      // Toggle mutuamente excluyente: Compra de Mercadería vs Gastos
      const chkMerc = document.getElementById('op-chk-compra-mercaderia');
      const chkGasto = document.getElementById('op-chk-gastos');
      chkMerc?.addEventListener('change', () => {
        if (chkMerc.checked) {
          applyOrdenPagoModeSwitch('COMPRA_MERCADERIA');
        } else {
          applyOrdenPagoModeSwitch('GASTO');
        }
      });
      chkGasto?.addEventListener('change', () => {
        if (chkGasto.checked) {
          applyOrdenPagoModeSwitch('GASTO');
        } else {
          applyOrdenPagoModeSwitch('COMPRA_MERCADERIA');
        }
      });

      // Buscador predictivo de proveedores
      const provSearch = document.getElementById('op-prov-search');
      const provSug = document.getElementById('op-prov-suggestions');
      provSearch?.addEventListener('input', () => {
        const q = String(provSearch.value || '').trim().toUpperCase();
        if (!provSug) return;
        if (!q) {
          provSug.hidden = true;
          return;
        }
        const matches = (Array.isArray(STATE.clientes) ? STATE.clientes : [])
          .filter((c) => {
            if (!c || c.baja || !c.esProveedor || isSystemConfigClient(c)) return false;
            const hay = `${c.nombre || ''} ${c.codigo || ''} ${c.nroDoc || ''} ${c.cuit || ''}`.toUpperCase();
            return hay.includes(q);
          })
          .slice(0, 20);
        if (matches.length === 0) {
          provSug.hidden = true;
          return;
        }
        provSug.innerHTML = matches
          .map(
            (p) => `<div class="pos-autocomplete-item" data-op-prov-id="${escapeHtml(String(p.id))}">
              <strong>${escapeHtml(p.nombre)}</strong>
              <span style="font-size:0.76rem; color:var(--text-secondary);">Cód. #${escapeHtml(String(p.codigo || p.id))} · CUIT: ${escapeHtml(p.nroDoc || p.cuit || 'S/D')}</span>
            </div>`
          )
          .join('');
        provSug.hidden = false;
      });

      provSug?.addEventListener('click', (e) => {
        const item = e.target.closest('[data-op-prov-id]');
        if (!item) return;
        const id = Number(item.getAttribute('data-op-prov-id'));
        const prov = (STATE.clientes || []).find((c) => Number(c.id) === id);
        if (prov) selectOpProveedor(prov);
      });

      document.getElementById('op-prov-quick-select')?.addEventListener('change', (e) => {
        const id = Number(e.target.value);
        const prov = (STATE.clientes || []).find((c) => Number(c.id) === id) || null;
        selectOpProveedor(prov);
      });

      document.getElementById('btn-op-clear-prov')?.addEventListener('click', () => {
        selectOpProveedor(null);
      });

      // Checkboxes de comprobantes de compra e importe
      document.getElementById('op-prov-pendientes-tbody')?.addEventListener('change', (e) => {
        const chk = e.target.closest('[data-op-comp-chk]');
        if (!chk) return;
        const compId = chk.getAttribute('data-op-comp-chk');
        ORDEN_PAGO_UI.manualSelectionMode = true;
        if (chk.checked) {
          ORDEN_PAGO_UI.selectedCompIds.add(compId);
        } else {
          ORDEN_PAGO_UI.selectedCompIds.delete(compId);
        }
        renderOpProveedorState();
      });

      document.getElementById('btn-op-check-all')?.addEventListener('click', () => {
        ORDEN_PAGO_UI.manualSelectionMode = true;
        (ORDEN_PAGO_UI.provPendingComprobantes || []).forEach((c) => ORDEN_PAGO_UI.selectedCompIds.add(c.id));
        renderOpProveedorState();
      });

      document.getElementById('btn-op-uncheck-all')?.addEventListener('click', () => {
        ORDEN_PAGO_UI.manualSelectionMode = true;
        ORDEN_PAGO_UI.selectedCompIds.clear();
        const montoInp = document.getElementById('op-prov-monto-input');
        if (montoInp) montoInp.value = '';
        renderOpProveedorState();
      });

      document.getElementById('op-prov-monto-input')?.addEventListener('input', () => {
        ORDEN_PAGO_UI.manualSelectionMode = false;
        renderOpProveedorState();
      });

      // Medio de pago en Compra de Mercadería
      const provMedioSel = document.getElementById('op-prov-medio-pago');
      provMedioSel?.addEventListener('change', () => {
        const val = String(provMedioSel.value || 'Efectivo');
        const bancoWrap = document.getElementById('op-prov-banco-wrap');
        const combWrap = document.getElementById('op-prov-combinado-wrap');
        if (bancoWrap) bancoWrap.hidden = val !== 'Transferencia' && val !== 'Pago Combinado';
        if (combWrap) combWrap.hidden = val !== 'Pago Combinado';
      });

      // Confirmar Orden de Pago por Compra de Mercadería
      document.getElementById('btn-op-confirmar-mercaderia')?.addEventListener('click', async () => {
        if (ORDEN_PAGO_UI.isSubmitting) return;
        const prov = ORDEN_PAGO_UI.selectedProveedor;
        if (!prov) {
          alert('Seleccioná el Proveedor destinatario de la Orden de Pago.');
          return;
        }
        const montoTotal = roundMoney(Math.max(0, Number(document.getElementById('op-prov-monto-input')?.value) || 0));
        if (!(montoTotal > 0)) {
          alert('Ingresá un monto a abonar mayor a $ 0,00.');
          return;
        }

        const medioPago = String(document.getElementById('op-prov-medio-pago')?.value || 'Efectivo');
        const obsUser = String(document.getElementById('op-prov-obs-input')?.value || '').trim().toUpperCase();
        let impEfectivo = montoTotal;
        let impBanco = 0;

        if (medioPago === 'Transferencia') {
          impEfectivo = 0;
          impBanco = montoTotal;
        } else if (medioPago === 'Pago Combinado') {
          impEfectivo = roundMoney(Math.max(0, Number(document.getElementById('op-prov-comb-efectivo')?.value) || 0));
          impBanco = roundMoney(Math.max(0, Number(document.getElementById('op-prov-comb-transf')?.value) || 0));
          if (Math.abs(impEfectivo + impBanco - montoTotal) > 0.05) {
            alert(`En Pago Combinado, la suma de Efectivo ($ ${formatArs(impEfectivo)}) + Transferencia ($ ${formatArs(impBanco)}) debe coincidir con el Monto a Abonar ($ ${formatArs(montoTotal)}).`);
            return;
          }
        }

        const numeroOp = getNextOrdenPagoNumber();
        const fechaIso = getTodayIsoLocal();
        const now = new Date();
        const fechaHora = `${todayFormatted()} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
        const usuario = STATE.currentUser?.name || STATE.currentUser?.username || 'ADMINISTRADOR';

        // Detalle de facturas imputadas
        let rem = montoTotal;
        const imputacionesDetalle = [];
        (ORDEN_PAGO_UI.provPendingComprobantes || []).forEach((c) => {
          if (rem <= 0.009) return;
          if (ORDEN_PAGO_UI.manualSelectionMode && !ORDEN_PAGO_UI.selectedCompIds.has(c.id)) return;
          const aplica = roundMoney(Math.min(c.saldoPendiente, rem));
          if (aplica > 0) {
            imputacionesDetalle.push({
              comprobanteId: c.id,
              fecha: c.fechaAr || c.fechaIso,
              comprobante: `${c.tipo} ${c.numero}`,
              importeOriginal: c.importeOriginal,
              importeAplicado: aplica,
              saldoPosterior: roundMoney(Math.max(0, c.saldoPendiente - aplica))
            });
            rem = roundMoney(rem - aplica);
          }
        });

        const detalleCompsStr = imputacionesDetalle.length > 0
          ? `Cancela: ${imputacionesDetalle.map((d) => d.comprobante).join(', ')}`
          : 'Pago a cuenta de mercadería';
        const conceptoFinal = `COMPRA DE MERCADERÍA · ${detalleCompsStr}${obsUser ? ` · ${obsUser}` : ''}`;

        ORDEN_PAGO_UI.isSubmitting = true;
        try {
          // 1. Imputar en Cuenta Corriente del Proveedor (origen COMPRA, dh = +1)
          const savedCtaMov = await imputarMovimientoEnCuentaCorrienteTercero({
            terceroObj: prov,
            fechaIso,
            tipoComp: 'ORDEN DE PAGO (COMPRA MERCADERÍA)',
            numeroComp: numeroOp,
            dh: 1,
            importe: montoTotal,
            obs: `CAJA CENTRAL · ${conceptoFinal}`,
            origen: 'COMPRA',
            imputaciones: imputacionesDetalle
          });

          // 2. Descontar efectivo de Caja Central
          if (impEfectivo > 0) {
            FONDOS_STATE.movimientosCaja.unshift({
              id: `CAJA-OP-${Date.now()}`,
              fechaIso,
              fechaHora,
              tipo: 'ORDEN DE PAGO · COMPRA DE MERCADERÍA',
              imputacion: 'PROVEEDOR',
              comprobante: numeroOp,
              destinatario: String(prov.nombre || '').toUpperCase(),
              concepto: conceptoFinal,
              ingreso: 0,
              egreso: impEfectivo,
              usuario,
              createdAt: now.toISOString()
            });
          }

          // 3. Descontar transferencia de Cuenta Bancaria de Fondos si corresponde
          if (impBanco > 0) {
            const bancoId = String(document.getElementById('op-prov-banco-select')?.value || '');
            const cta = FONDOS_STATE.cuentasBancarias.find((b) => b && b.id === bancoId) || FONDOS_STATE.cuentasBancarias[0];
            if (cta) {
              FONDOS_STATE.movimientosBancarios.unshift({
                id: `MOV-OP-${Date.now()}`,
                cuentaId: cta.id,
                fechaIso,
                tipo: 'ORDEN DE PAGO A PROVEEDOR',
                concepto: `${numeroOp} · ${conceptoFinal}`,
                comprobante: numeroOp,
                tercero: String(prov.nombre || '').toUpperCase(),
                debe: 0,
                haber: impBanco,
                conciliado: false,
                createdAt: now.toISOString()
              });
            }
          }

          // 4. Guardar registro en FONDOS_STATE.ordenesPago
          const opRecord = {
            id: `OP-${Date.now()}`,
            ctacteMovId: savedCtaMov && savedCtaMov.id ? Number(savedCtaMov.id) : 0,
            numero: numeroOp,
            fechaIso,
            fechaHora,
            tipoOrden: 'COMPRA_MERCADERIA',
            proveedorId: prov.id,
            proveedorNombre: String(prov.nombre || '').toUpperCase(),
            proveedorDoc: String(prov.nroDoc || prov.cuit || ''),
            medioPago,
            importe: montoTotal,
            importeEfectivo: impEfectivo,
            importeBanco: impBanco,
            concepto: conceptoFinal,
            observacion: obsUser,
            imputacionesDetalle,
            usuario,
            createdAt: now.toISOString()
          };
          FONDOS_STATE.ordenesPago.unshift(opRecord);
          saveFondosState(true);

          const obsInp = document.getElementById('op-prov-obs-input');
          if (obsInp) obsInp.value = '';
          await selectOpProveedor(prov);
          updateOrdenPagoHeaderStatus();
          renderOrdenPagoHistorialTable();
          printOrdenPagoVoucher(opRecord);
        } finally {
          ORDEN_PAGO_UI.isSubmitting = false;
        }
      });

      // Eventos del panel de Gastos
      ['op-gasto-categoria-select', 'op-gasto-mes-select', 'op-gasto-anio-select', 'op-gasto-medio-pago'].forEach((id) => {
        document.getElementById(id)?.addEventListener('change', () => {
          if (id === 'op-gasto-medio-pago') {
            const medio = String(document.getElementById('op-gasto-medio-pago')?.value || 'Efectivo');
            const bWrap = document.getElementById('op-gasto-banco-wrap');
            if (bWrap) bWrap.hidden = medio !== 'Transferencia';
          }
          updateOrdenPagoGastoLiveKpis();
        });
      });
      document.getElementById('op-gasto-monto-input')?.addEventListener('input', updateOrdenPagoGastoLiveKpis);

      ['btn-open-abm-gastos', 'btn-open-abm-gastos-inline'].forEach((id) => {
        document.getElementById(id)?.addEventListener('click', () => window.openAbmGastosDialog());
      });

      // Confirmar Orden de Pago por Gasto Operativo
      document.getElementById('btn-op-confirmar-gasto')?.addEventListener('click', () => {
        const catId = String(document.getElementById('op-gasto-categoria-select')?.value || '');
        const catObj = (FONDOS_STATE.categoriasGastos || []).find((c) => c && c.id === catId);
        if (!catObj) {
          alert('Seleccioná la Categoría de Gasto (o creala desde el botón ABM de Gastos).');
          return;
        }
        const monto = roundMoney(Math.max(0, Number(document.getElementById('op-gasto-monto-input')?.value) || 0));
        if (!(monto > 0)) {
          alert('Ingresá un importe del gasto mayor a $ 0,00.');
          document.getElementById('op-gasto-monto-input')?.focus();
          return;
        }

        const mesVal = String(document.getElementById('op-gasto-mes-select')?.value || '').padStart(2, '0');
        const anioVal = String(document.getElementById('op-gasto-anio-select')?.value || new Date().getFullYear());
        const periodoImputado = `${anioVal}-${mesVal}`;
        const fechaIso = String(document.getElementById('op-gasto-fecha-pago')?.value || getTodayIsoLocal());
        const beneficiario = String(document.getElementById('op-gasto-beneficiario')?.value || '').trim().toUpperCase();
        const comprobanteRef = String(document.getElementById('op-gasto-comprobante-ref')?.value || '').trim().toUpperCase();
        const medioPago = String(document.getElementById('op-gasto-medio-pago')?.value || 'Efectivo');
        const obsUser = String(document.getElementById('op-gasto-obs-input')?.value || '').trim().toUpperCase();

        const numeroOp = getNextOrdenPagoNumber();
        const now = new Date();
        const fParts = fechaIso.split('-');
        const fechaAr = fParts.length === 3 ? `${fParts[2]}/${fParts[1]}/${fParts[0]}` : fechaIso;
        const fechaHora = `${fechaAr} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
        const usuario = STATE.currentUser?.name || STATE.currentUser?.username || 'ADMINISTRADOR';

        const periodoLabel = formatPeriodoImputadoLabel(periodoImputado).toUpperCase();
        const conceptoFinal = `GASTO: ${catObj.nombre} (IMPUTADO: ${periodoLabel})${comprobanteRef ? ` · REF: ${comprobanteRef}` : ''}${obsUser ? ` · ${obsUser}` : ''}`;
        const movCajaId = `CAJA-GASTO-${Date.now()}`;

        if (medioPago === 'Efectivo') {
          FONDOS_STATE.movimientosCaja.unshift({
            id: movCajaId,
            fechaIso,
            fechaHora,
            tipo: `ORDEN DE PAGO · GASTO (${catObj.nombre})`,
            imputacion: 'GASTO',
            categoriaGastoId: catObj.id,
            categoriaGastoNombre: catObj.nombre,
            periodoImputado,
            comprobante: numeroOp,
            destinatario: beneficiario || catObj.nombre,
            concepto: conceptoFinal,
            ingreso: 0,
            egreso: monto,
            usuario,
            createdAt: now.toISOString()
          });
        } else {
          const bancoId = String(document.getElementById('op-gasto-banco-select')?.value || '');
          const cta = FONDOS_STATE.cuentasBancarias.find((b) => b && b.id === bancoId) || FONDOS_STATE.cuentasBancarias[0];
          if (cta) {
            FONDOS_STATE.movimientosBancarios.unshift({
              id: `MOV-GASTO-${Date.now()}`,
              cuentaId: cta.id,
              fechaIso,
              tipo: `ORDEN DE PAGO · GASTO (${catObj.nombre})`,
              concepto: `${numeroOp} · ${conceptoFinal}`,
              comprobante: numeroOp,
              tercero: beneficiario || catObj.nombre,
              debe: 0,
              haber: monto,
              conciliado: false,
              createdAt: now.toISOString()
            });
          }
        }

        const opRecord = {
          id: `OP-GASTO-${Date.now()}`,
          movCajaId,
          numero: numeroOp,
          fechaIso,
          fechaHora,
          tipoOrden: 'GASTO',
          categoriaId: catObj.id,
          categoriaNombre: catObj.nombre,
          periodoImputado,
          beneficiario,
          comprobanteRef,
          medioPago,
          importe: monto,
          concepto: conceptoFinal,
          observacion: obsUser,
          usuario,
          createdAt: now.toISOString()
        };

        FONDOS_STATE.ordenesPago.unshift(opRecord);
        saveFondosState(true);

        // Limpiar importe y campos opcionales
        ['op-gasto-monto-input', 'op-gasto-beneficiario', 'op-gasto-comprobante-ref', 'op-gasto-obs-input'].forEach((id) => {
          const el = document.getElementById(id);
          if (el) el.value = '';
        });

        updateOrdenPagoHeaderStatus();
        updateOrdenPagoGastoLiveKpis();
        renderOrdenPagoHistorialTable();
        printOrdenPagoVoucher(opRecord);
      });

      // Filtros e interacciones del Historial de Órdenes de Pago
      ['op-hist-filter-tipo', 'op-hist-filter-periodo'].forEach((id) => {
        document.getElementById(id)?.addEventListener('change', renderOrdenPagoHistorialTable);
      });
      document.getElementById('op-hist-filter-q')?.addEventListener('input', renderOrdenPagoHistorialTable);

      document.getElementById('op-historial-tbody')?.addEventListener('click', (e) => {
        const printBtn = e.target.closest('[data-op-print]');
        if (printBtn) {
          const id = printBtn.getAttribute('data-op-print');
          const op = (FONDOS_STATE.ordenesPago || []).find((o) => o && o.id === id);
          if (op) printOrdenPagoVoucher(op);
          return;
        }
        const delBtn = e.target.closest('[data-op-del]');
        if (delBtn) {
          const id = delBtn.getAttribute('data-op-del');
          const idx = (FONDOS_STATE.ordenesPago || []).findIndex((o) => o && o.id === id);
          if (idx >= 0) {
            const op = FONDOS_STATE.ordenesPago[idx];
            if (!confirm(`¿Eliminar la Orden de Pago ${op.numero || ''} por $ ${formatArs(op.importe || 0)}?`)) return;
            FONDOS_STATE.ordenesPago.splice(idx, 1);
            // También quitar su movimiento de Caja Central y Bancos si estaba vinculado por comprobante
            const movIdx = (FONDOS_STATE.movimientosCaja || []).findIndex(
              (m) => m && (m.id === op.movCajaId || (m.comprobante && m.comprobante === op.numero))
            );
            if (movIdx >= 0) FONDOS_STATE.movimientosCaja.splice(movIdx, 1);
            const bMovIdx = (FONDOS_STATE.movimientosBancarios || []).findIndex(
              (m) => m && m.comprobante && m.comprobante === op.numero
            );
            if (bMovIdx >= 0) FONDOS_STATE.movimientosBancarios.splice(bMovIdx, 1);

            // Si era Orden de Pago de Compra de Mercadería, anular también el movimiento en Cuenta Corriente del Proveedor
            if (op.tipoOrden === 'COMPRA_MERCADERIA' && op.proveedorId) {
              const cid = Number(op.proveedorId);
              const cleanNro = String(op.numero || '').replace(/^(OP|RE|RC)\s+X?\s*/i, '').trim().toUpperCase();
              const movsList = STATE.movimientosPorCliente?.[String(cid)] || [];
              const targetMov = movsList.find((m) => {
                if (!m) return false;
                if (op.ctacteMovId && Number(m.id) === Number(op.ctacteMovId)) return true;
                return cleanNro && String(m.comprobante || m.n || '').toUpperCase().includes(cleanNro);
              });
              if (targetMov && targetMov.id) {
                fetch('api/clientes.php', {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({
                    action: 'annul_ctacte_movement',
                    movId: Number(targetMov.id),
                    cId: cid,
                    revertImputaciones: (op.imputacionesDetalle || []).map((it) => ({
                      movId: Number(it.comprobanteId || it.movId || 0),
                      amount: roundMoney(it.importeAplicado || 0)
                    }))
                  })
                })
                  .then((r) => (r.ok ? r.json() : null))
                  .then((res) => {
                    if (res && res.ok && res.client) {
                      const cli = (STATE.clientes || []).find((c) => Number(c.id) === cid);
                      if (cli) Object.assign(cli, normalizeClientRecord(res.client, STATE.clientesCatalogs));
                    }
                    if (Array.isArray(STATE.movimientosPorCliente?.[String(cid)])) {
                      STATE.movimientosPorCliente[String(cid)] = STATE.movimientosPorCliente[String(cid)].filter(
                        (m) => Number(m?.id) !== Number(targetMov.id)
                      );
                    }
                    updateClientesKpis();
                    applyClientesFilters(STATE.clientesPage || 1);
                    applyProveedoresFilters(STATE.proveedoresPage || 1);
                    renderCuentasCorrientesSection();
                    if (ORDEN_PAGO_UI.selectedProveedor && Number(ORDEN_PAGO_UI.selectedProveedor.id) === cid) {
                      renderOpProveedorState();
                    }
                  })
                  .catch(() => {});
              }
            }

            saveFondosState(true);
            updateOrdenPagoHeaderStatus();
            updateOrdenPagoGastoLiveKpis();
            renderOrdenPagoHistorialTable();
          }
        }
      });

      // Eventos del modal ABM de Gastos
      document.getElementById('btn-close-abm-gastos')?.addEventListener('click', () => {
        document.getElementById('abm-gastos-dialog')?.close();
      });

      document.getElementById('btn-abm-gasto-cancel-edit')?.addEventListener('click', () => {
        const editIdEl = document.getElementById('abm-gasto-edit-id');
        const nomEl = document.getElementById('abm-gasto-nombre');
        const descEl = document.getElementById('abm-gasto-desc');
        const cancelBtn = document.getElementById('btn-abm-gasto-cancel-edit');
        if (editIdEl) editIdEl.value = '';
        if (nomEl) nomEl.value = '';
        if (descEl) descEl.value = '';
        if (cancelBtn) cancelBtn.hidden = true;
      });

      document.getElementById('abm-gastos-form')?.addEventListener('submit', (e) => {
        e.preventDefault();
        const editIdEl = document.getElementById('abm-gasto-edit-id');
        const nomEl = document.getElementById('abm-gasto-nombre');
        const descEl = document.getElementById('abm-gasto-desc');
        const cancelBtn = document.getElementById('btn-abm-gasto-cancel-edit');

        const nombre = String(nomEl?.value || '').trim().toUpperCase();
        const descripcion = String(descEl?.value || '').trim();
        if (!nombre) {
          alert('Ingresá el nombre de la categoría de gasto.');
          nomEl?.focus();
          return;
        }

        const editId = String(editIdEl?.value || '').trim();
        if (editId) {
          const cat = (FONDOS_STATE.categoriasGastos || []).find((c) => c && c.id === editId);
          if (cat) {
            cat.nombre = nombre;
            cat.descripcion = descripcion;
          }
        } else {
          FONDOS_STATE.categoriasGastos.push({
            id: `GASTO-CAT-${Date.now()}`,
            nombre,
            descripcion,
            activa: true
          });
        }

        if (editIdEl) editIdEl.value = '';
        if (nomEl) nomEl.value = '';
        if (descEl) descEl.value = '';
        if (cancelBtn) cancelBtn.hidden = true;

        saveFondosState(true);
        populateGastosCategorySelectors();
        renderAbmGastosTable();
        updateOrdenPagoGastoLiveKpis();
      });

      document.getElementById('abm-gastos-tbody')?.addEventListener('click', (e) => {
        const editBtn = e.target.closest('[data-abm-gasto-edit]');
        if (editBtn) {
          const id = editBtn.getAttribute('data-abm-gasto-edit');
          const cat = (FONDOS_STATE.categoriasGastos || []).find((c) => c && c.id === id);
          if (!cat) return;
          const editIdEl = document.getElementById('abm-gasto-edit-id');
          const nomEl = document.getElementById('abm-gasto-nombre');
          const descEl = document.getElementById('abm-gasto-desc');
          const cancelBtn = document.getElementById('btn-abm-gasto-cancel-edit');
          if (editIdEl) editIdEl.value = cat.id;
          if (nomEl) nomEl.value = cat.nombre || '';
          if (descEl) descEl.value = cat.descripcion || '';
          if (cancelBtn) cancelBtn.hidden = false;
          nomEl?.focus();
          return;
        }
        const delBtn = e.target.closest('[data-abm-gasto-del]');
        if (delBtn) {
          const id = delBtn.getAttribute('data-abm-gasto-del');
          const idx = (FONDOS_STATE.categoriasGastos || []).findIndex((c) => c && c.id === id);
          if (idx >= 0) {
            const cat = FONDOS_STATE.categoriasGastos[idx];
            if (!confirm(`¿Eliminar la categoría de gasto "${cat.nombre}"?`)) return;
            FONDOS_STATE.categoriasGastos.splice(idx, 1);
            saveFondosState(true);
            populateGastosCategorySelectors();
            renderAbmGastosTable();
            updateOrdenPagoGastoLiveKpis();
          }
        }
      });
    }
  };

  function getNextCuentaBancariaCodigo() {
    let maxNum = 0;
    FONDOS_STATE.cuentasBancarias.forEach((c) => {
      const m = String(c.codigo || c.id || '').match(/(\d+)/);
      if (m) {
        const n = parseInt(m[1], 10);
        if (n > maxNum) maxNum = n;
      }
    });
    return `B${String(maxNum + 1).padStart(3, '0')}`;
  }

  function getNextEcheqSuggestedNumber() {
    let maxNum = 1000;
    FONDOS_STATE.echeqs.forEach((e) => {
      const m = String(e.numero || '').match(/(\d+)/g);
      if (m && m.length > 0) {
        const n = parseInt(m[m.length - 1], 10);
        if (Number.isFinite(n) && n > maxNum) maxNum = n;
      }
    });
    return `ECH-${String(maxNum + 1).padStart(8, '0')}`;
  }

  function computeCuentaBalances(cuentaId) {
    const cta = FONDOS_STATE.cuentasBancarias.find((c) => c.id === cuentaId);
    const saldoInicial = roundMoney(cta?.saldoInicial || 0);
    let ingresos = 0;
    let egresos = 0;
    let ingresosConc = 0;
    let egresosConc = 0;
    let pendientesCount = 0;
    let pendientesNeto = 0;

    FONDOS_STATE.movimientosBancarios.forEach((m) => {
      if (!m || m.cuentaId !== cuentaId) return;
      const debe = roundMoney(m.debe || 0);
      const haber = roundMoney(m.haber || 0);
      ingresos = roundMoney(ingresos + debe);
      egresos = roundMoney(egresos + haber);
      if (m.conciliado) {
        ingresosConc = roundMoney(ingresosConc + debe);
        egresosConc = roundMoney(egresosConc + haber);
      } else {
        pendientesCount++;
        pendientesNeto = roundMoney(pendientesNeto + (debe - haber));
      }
    });

    let echeqsPendientes = 0;
    let echeqsCount = 0;
    FONDOS_STATE.echeqs.forEach((e) => {
      if (!e || e.cuentaId !== cuentaId) return;
      if (e.estado === 'EMITIDO') {
        echeqsPendientes = roundMoney(echeqsPendientes + roundMoney(e.importe || 0));
        echeqsCount++;
      }
    });

    const saldoContable = roundMoney(saldoInicial + ingresos - egresos);
    const saldoConciliado = roundMoney(saldoInicial + ingresosConc - egresosConc);
    const descubierto = roundMoney(cta?.descubierto || 0);
    const disponibleNeto = roundMoney(saldoContable + descubierto - echeqsPendientes);

    return {
      saldoInicial,
      ingresos,
      egresos,
      saldoContable,
      saldoConciliado,
      pendientesCount,
      pendientesNeto,
      echeqsPendientes,
      echeqsCount,
      descubierto,
      disponibleNeto
    };
  }

  function renderFondosGlobalKpis() {
    let totalContable = 0;
    let totalConciliado = 0;
    let totalPendientesCount = 0;
    let totalEcheqsPend = 0;
    let totalEcheqsCount = 0;
    let totalDisponible = 0;
    let activasCount = 0;

    FONDOS_STATE.cuentasBancarias.forEach((c) => {
      if (!c || c.baja) return;
      activasCount++;
      const b = computeCuentaBalances(c.id);
      totalContable = roundMoney(totalContable + b.saldoContable);
      totalConciliado = roundMoney(totalConciliado + b.saldoConciliado);
      totalPendientesCount += b.pendientesCount;
      totalEcheqsPend = roundMoney(totalEcheqsPend + b.echeqsPendientes);
      totalEcheqsCount += b.echeqsCount;
      totalDisponible = roundMoney(totalDisponible + b.disponibleNeto);
    });

    const elCont = document.getElementById('fondos-kpi-saldo-contable');
    const elAct = document.getElementById('fondos-kpi-cuentas-activas');
    const elConc = document.getElementById('fondos-kpi-saldo-conciliado');
    const elPend = document.getElementById('fondos-kpi-pendientes-conciliar');
    const elEch = document.getElementById('fondos-kpi-echeq-pendientes');
    const elEchCnt = document.getElementById('fondos-kpi-echeq-count');
    const elDisp = document.getElementById('fondos-kpi-disponible-neto');

    if (elCont) elCont.textContent = `$ ${formatArs(totalContable)}`;
    if (elAct) elAct.textContent = `${activasCount} entidad(es) activa(s)`;
    if (elConc) elConc.textContent = `$ ${formatArs(totalConciliado)}`;
    if (elPend) elPend.textContent = `${totalPendientesCount} partida(s) sin conciliar`;
    if (elEch) elEch.textContent = `$ ${formatArs(totalEcheqsPend)}`;
    if (elEchCnt) elEchCnt.textContent = `${totalEcheqsCount} E-Cheq(s) emitido(s) pendiente(s)`;
    if (elDisp) elDisp.textContent = `$ ${formatArs(totalDisponible)}`;
  }

  function populateFondosAccountSelectors() {
    const activeAccounts = FONDOS_STATE.cuentasBancarias.filter((c) => c && !c.baja);
    const echeqAccounts = activeAccounts.filter((c) => c.habilitaEcheq !== false);

    const buildOpts = (list, includeAllLabel = '') => {
      let html = includeAllLabel ? `<option value="todas">${escapeHtml(includeAllLabel)}</option>` : '';
      list.forEach((c) => {
        const bal = computeCuentaBalances(c.id);
        html += `<option value="${escapeHtml(c.id)}">${escapeHtml(c.codigo)} · ${escapeHtml(c.banco)} (${escapeHtml(c.denominacion)}) — $ ${formatArs(bal.saldoContable)}</option>`;
      });
      return html;
    };

    const movCuentaSel = document.getElementById('fondos-mov-cuenta');
    const movDestSel = document.getElementById('fondos-mov-cuenta-destino');
    const ctacteFilterSel = document.getElementById('fondos-ctacte-filter-cuenta');
    const concCuentaSel = document.getElementById('fondos-conc-cuenta');
    const echeqCuentaSel = document.getElementById('fondos-echeq-cuenta');
    const echeqFilterSel = document.getElementById('fondos-echeq-filter-cuenta');

    const prevMov = movCuentaSel?.value || '';
    const prevDest = movDestSel?.value || '';
    const prevCtacte = ctacteFilterSel?.value || 'todas';
    const prevConc = concCuentaSel?.value || '';
    const prevEcheq = echeqCuentaSel?.value || '';
    const prevEcheqFilter = echeqFilterSel?.value || 'todas';

    if (movCuentaSel) {
      movCuentaSel.innerHTML = buildOpts(activeAccounts);
      if (prevMov && activeAccounts.some((c) => c.id === prevMov)) movCuentaSel.value = prevMov;
    }
    if (movDestSel) {
      movDestSel.innerHTML = buildOpts(activeAccounts);
      if (prevDest && activeAccounts.some((c) => c.id === prevDest)) movDestSel.value = prevDest;
    }
    if (ctacteFilterSel) {
      ctacteFilterSel.innerHTML = buildOpts(FONDOS_STATE.cuentasBancarias, '🏦 TODAS LAS ENTIDADES BANCARIAS Y BILLETERAS');
      ctacteFilterSel.value = prevCtacte;
    }
    if (concCuentaSel) {
      concCuentaSel.innerHTML = buildOpts(activeAccounts);
      if (prevConc && activeAccounts.some((c) => c.id === prevConc)) concCuentaSel.value = prevConc;
    }
    if (echeqCuentaSel) {
      const targetEcheqList = echeqAccounts.length > 0 ? echeqAccounts : activeAccounts;
      echeqCuentaSel.innerHTML = buildOpts(targetEcheqList);
      if (prevEcheq && targetEcheqList.some((c) => c.id === prevEcheq)) echeqCuentaSel.value = prevEcheq;
    }
    if (echeqFilterSel) {
      echeqFilterSel.innerHTML = buildOpts(FONDOS_STATE.cuentasBancarias, '🏦 TODOS LOS BANCOS EMISORES');
      echeqFilterSel.value = prevEcheqFilter;
    }

    // Datalist de Proveedores y Clientes para vincular pagos o E-Cheqs
    const dl = document.getElementById('fondos-terceros-datalist');
    if (dl && Array.isArray(STATE.clientes)) {
      const opts = [];
      STATE.clientes.slice(0, 600).forEach((p) => {
        if (!p || p.baja || isSystemConfigClient(p)) return;
        const rol = p.esProveedor ? 'PROVEEDOR' : 'CLIENTE';
        const cuitTxt = p.cuit ? ` · CUIT ${p.cuit}` : '';
        opts.push(`<option value="${escapeHtml(p.nombre)}">#${escapeHtml(String(p.codigo || p.id))} · ${rol}${escapeHtml(cuitTxt)}</option>`);
      });
      dl.innerHTML = opts.join('');
    }
  }

  function findTerceroInPadron(nombreTexto) {
    const clean = String(nombreTexto || '').trim().toUpperCase();
    if (!clean || !Array.isArray(STATE.clientes)) return null;
    return (
      STATE.clientes.find((c) => c && String(c.nombre || '').trim().toUpperCase() === clean) ||
      STATE.clientes.find((c) => c && String(c.nombre || '').trim().toUpperCase().includes(clean)) ||
      null
    );
  }

  async function imputarMovimientoEnCuentaCorrienteTercero({ terceroObj, fechaIso, tipoComp, numeroComp, dh, importe, obs, origen, imputaciones }) {
    if (!terceroObj || !(importe > 0)) return null;
    await loadClientesDatabase();
    const cid = Number(terceroObj.id);
    const cli = STATE.clientes.find((c) => Number(c.id) === cid);
    if (!cli) return null;

    const monto = roundMoney(importe);
    const dhVal = Number(dh) === 1 ? 1 : -1;
    const fechaParts = String(fechaIso || getTodayIsoLocal()).split('-');
    const fechaAr = fechaParts.length === 3 ? `${fechaParts[2]}/${fechaParts[1]}/${fechaParts[0]}` : fechaIso;
    const tipoStr = String(tipoComp || (dhVal === 1 ? 'ORDEN DE PAGO (COMPRA MERCADERÍA)' : 'RECIBO DE PAGO')).toUpperCase();
    const isOpOrProv = Boolean(
      origen === 'COMPRA' ||
      tipoStr.includes('ORDEN DE PAGO') ||
      tipoStr.includes('COMPRA') ||
      tipoStr.includes('PROVEEDOR') ||
      (cli.esProveedor && dhVal === 1)
    );
    const tcaVal = tipoStr.includes('ORDEN DE PAGO') ? 'OP' : 'RE';
    const cleanNro = String(numeroComp || 'S/N').replace(/^(OP|RE|RC)\s+X?\s*/i, '').trim() || String(numeroComp || 'S/N');
    const origenVal = isOpOrProv ? 'COMPRA' : 'VENTA';

    const imputacionesPayload = Array.isArray(imputaciones)
      ? imputaciones.map((it) => ({
          movId: Number(it.movId || it.comprobanteId || it.id || 0),
          amount: roundMoney(it.amount || it.importeAplicado || it.importe || 0)
        })).filter((it) => it.movId > 0 && it.amount > 0)
      : [];

    let savedMov = null;
    try {
      const res = await fetch('api/clientes.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'add_ctacte_movement',
          clienteId: cid,
          esProveedor: Boolean(cli.esProveedor),
          movement: {
            cId: cid,
            imp: monto,
            dh: dhVal,
            tc: isOpOrProv ? 11 : (dhVal === -1 ? 10 : 1),
            tcn: tipoStr,
            tca: tcaVal,
            l: 'X',
            n: cleanNro,
            f: fechaAr,
            fi: fechaIso,
            v: fechaAr,
            obs: obs || '',
            origen: origenVal,
            imputaciones: imputacionesPayload
          }
        })
      });
      const json = await res.json().catch(() => null);
      if (res.ok && json && json.ok) {
        if (json.client) {
          const normCli = normalizeClientRecord(json.client, STATE.clientesCatalogs);
          Object.assign(cli, normCli);
        }
        const cliKey = String(cid);
        if (Array.isArray(json.movimientos)) {
          STATE.movimientosPorCliente[cliKey] = json.movimientos.map(normalizeMovimientoRecord);
          ORDEN_PAGO_UI.provMovementsCache.set(cid, STATE.movimientosPorCliente[cliKey]);
        } else if (json.movement) {
          if (!Array.isArray(STATE.movimientosPorCliente[cliKey])) {
            STATE.movimientosPorCliente[cliKey] = [];
          }
          savedMov = normalizeMovimientoRecord(json.movement);
          STATE.movimientosPorCliente[cliKey].push(savedMov);
          ORDEN_PAGO_UI.provMovementsCache.set(cid, STATE.movimientosPorCliente[cliKey]);
        }
        if (json.movement) {
          savedMov = normalizeMovimientoRecord(json.movement);
        }
      }
    } catch {}

    // Fallback local si hubo corte momentáneo de red
    if (!savedMov) {
      const cliKey = String(cid);
      if (!Array.isArray(STATE.movimientosPorCliente[cliKey])) {
        STATE.movimientosPorCliente[cliKey] = [];
      }
      const debeVal = dhVal === 1 ? monto : 0;
      const haberVal = dhVal === -1 ? monto : 0;
      const nuevoSaldo = roundMoney((Number(cli.saldoActual) || 0) + debeVal - haberVal);
      cli.totalDebe = roundMoney((Number(cli.totalDebe) || 0) + debeVal);
      cli.totalHaber = roundMoney((Number(cli.totalHaber) || 0) + haberVal);
      cli.saldoActual = nuevoSaldo;
      cli.cantMovs = (Number(cli.cantMovs) || 0) + 1;
      cli.ultimoMovFecha = fechaAr;

      savedMov = {
        id: Date.now(),
        cId: cid,
        fecha: fechaAr,
        vencimiento: fechaAr,
        tipoComp: tipoStr,
        comprobante: `${tcaVal} X ${cleanNro}`,
        dh: dhVal,
        debe: debeVal,
        haber: haberVal,
        importe: monto,
        cancelado: 0,
        pendiente: monto,
        saldo: nuevoSaldo,
        obs: obs || '',
        origen: origenVal
      };
      STATE.movimientosPorCliente[cliKey].push(savedMov);
      ORDEN_PAGO_UI.provMovementsCache.set(cid, STATE.movimientosPorCliente[cliKey]);
    }

    syncProveedoresCatalogFromEntities();
    updateClientesKpis();
    applyClientesFilters(STATE.clientesPage || 1);
    applyProveedoresFilters(STATE.proveedoresPage || 1);
    renderCuentasCorrientesSection();

    return savedMov;
  }

