    const denomEl = document.getElementById('fondos-abm-denominacion');
    const monEl = document.getElementById('fondos-abm-moneda');
    const cbuEl = document.getElementById('fondos-abm-cbu');
    const cuitEl = document.getElementById('fondos-abm-cuit');
    const aliasEl = document.getElementById('fondos-abm-alias');
    const posnetEl = document.getElementById('fondos-abm-posnet');
    const saldoIniEl = document.getElementById('fondos-abm-saldo-inicial');
    const descEl = document.getElementById('fondos-abm-descubierto');
    const echeqEl = document.getElementById('fondos-abm-echeq');
    const bajaEl = document.getElementById('fondos-abm-baja');
    const badgeEl = document.getElementById('fondos-abm-mode-badge');
    const titleEl = document.getElementById('fondos-abm-form-title');

    if (idEl) idEl.value = '';
