  // -------------------------------------------------------------------------
  // PANEL 3: CONCILIACIÓN DE SALDOS BANCARIOS
  // -------------------------------------------------------------------------
  function renderFondosConciliacionPanel() {
    const cuentaId = String(document.getElementById('fondos-conc-cuenta')?.value || '');
    const bal = computeCuentaBalances(cuentaId);
    const rawExtracto = document.getElementById('fondos-conc-saldo-extracto')?.value;
    const hasExtracto = rawExtracto !== '' && rawExtracto !== null && rawExtracto !== undefined;
    const saldoExtracto = hasExtracto ? roundMoney(rawExtracto) : bal.saldoConciliado;
    const diferencia = roundMoney(saldoExtracto - bal.saldoConciliado);

    const elCont = document.getElementById('fondos-conc-kpi-contable');
    const elConc = document.getElementById('fondos-conc-kpi-conciliado');
    const elPend = document.getElementById('fondos-conc-kpi-pendientes');
    const elExt = document.getElementById('fondos-conc-kpi-extracto');
    const elDif = document.getElementById('fondos-conc-kpi-diferencia');
    const elEst = document.getElementById('fondos-conc-kpi-estado');

    if (elCont) elCont.textContent = `$ ${formatArs(bal.saldoContable)}`;
    if (elConc) elConc.textContent = `$ ${formatArs(bal.saldoConciliado)}`;
    if (elPend) elPend.textContent = `${bal.pendientesCount} partida(s) pendiente(s) ($ ${formatArs(bal.pendientesNeto)})`;
    if (elExt) elExt.textContent = `$ ${formatArs(saldoExtracto)}`;
    if (elDif) {
      elDif.textContent = `${diferencia > 0 ? '+' : ''}$ ${formatArs(diferencia)}`;
      elDif.style.color = Math.abs(diferencia) < 0.01 ? 'var(--green-ok)' : 'var(--red-danger)';
    }
    if (elEst) {
      elEst.textContent =
        Math.abs(diferencia) < 0.01
          ? '✅ Saldo Conciliado coincide exactamente con el Extracto Bancario'
          : '⚠️ Existe diferencia entre el Extracto Bancario y las partidas tildadas';
    }

    const movsTbody = document.getElementById('fondos-conc-movs-tbody');
    if (movsTbody) {
      const movs = FONDOS_STATE.movimientosBancarios.filter((m) => m && m.cuentaId === cuentaId);
      if (movs.length === 0) {
        movsTbody.innerHTML = '<tr><td colspan="5" class="table-loading-cell">Esta entidad aún no registra movimientos para conciliar.</td></tr>';
      } else {
        movsTbody.innerHTML = movs
          .map((m) => {
            const fParts = String(m.fechaIso || '').split('-');
            const fAr = fParts.length === 3 ? `${fParts[2]}/${fParts[1]}/${fParts[0]}` : m.fechaIso || '';
            return `<tr style="${m.conciliado ? 'background:rgba(22,163,74,0.06);' : ''}">
              <td style="text-align:center;">
                <input type="checkbox" data-fondos-conc-check="${escapeHtml(m.id)}" ${m.conciliado ? 'checked' : ''} style="width:18px; height:18px; cursor:pointer;">
              </td>
              <td><strong>${escapeHtml(fAr)}</strong></td>
              <td>
                <div class="price-cell-stack">
                  <strong>${escapeHtml(m.concepto || m.tipo)}</strong>
                  <span class="price-neto-val">${escapeHtml(m.comprobante || 'S/N')} ${m.tercero ? `· ${escapeHtml(m.tercero)}` : ''}</span>
                </div>
              </td>
              <td class="num-col" style="color:var(--green-ok); font-weight:700;">${m.debe > 0 ? `+ $ ${formatArs(m.debe)}` : '—'}</td>
              <td class="num-col" style="color:var(--red-danger); font-weight:700;">${m.haber > 0 ? `- $ ${formatArs(m.haber)}` : '—'}</td>
            </tr>`;
          })
          .join('');
      }
    }

    const histTbody = document.getElementById('fondos-conc-hist-tbody');
    if (histTbody) {
      if (FONDOS_STATE.conciliacionesBancarias.length === 0) {
        histTbody.innerHTML = '<tr><td colspan="5" class="table-loading-cell">Aún no se han guardado cierres de conciliación bancaria.</td></tr>';
      } else {
        histTbody.innerHTML = FONDOS_STATE.conciliacionesBancarias
          .slice(0, 40)
          .map((k) => {
            const cta = FONDOS_STATE.cuentasBancarias.find((c) => c.id === k.cuentaId);
            return `<tr>
              <td>
                <div class="price-cell-stack">
                  <strong>${escapeHtml(k.fechaAr || k.fechaIso)}</strong>
                  <span class="price-neto-val">${escapeHtml(cta ? cta.banco : k.cuentaId)}</span>
                </div>
              </td>
              <td class="num-col"><strong>$ ${formatArs(k.saldoConciliado || 0)}</strong></td>
              <td class="num-col"><strong>$ ${formatArs(k.saldoExtracto || 0)}</strong></td>
              <td class="num-col" style="color:${Math.abs(k.diferencia || 0) < 0.01 ? 'var(--green-ok)' : 'var(--red-danger)'}; font-weight:800;">
                $ ${formatArs(k.diferencia || 0)}
              </td>
              <td style="text-align:center;">
                <button type="button" class="btn-secondary btn-sm" data-fondos-print-conc="${escapeHtml(k.id)}">🖨️ Acta</button>
              </td>
            </tr>`;
          })
          .join('');
      }
    }
  }

  // -------------------------------------------------------------------------
  // PANEL 4: EMISIÓN Y CARTERA DE E-CHEQ / CHEQUES
  // -------------------------------------------------------------------------
  function renderFondosEcheqPanel() {
    const tbody = document.getElementById('fondos-echeq-tbody');
    if (!tbody) return;

    const filterCuenta = String(document.getElementById('fondos-echeq-filter-cuenta')?.value || 'todas');
    const filterEstado = String(document.getElementById('fondos-echeq-filter-estado')?.value || 'todos');
    const q = String(document.getElementById('fondos-echeq-filter-q')?.value || '').trim().toUpperCase();
    const todayIso = getTodayIsoLocal();

    const rows = FONDOS_STATE.echeqs.filter((e) => {
      if (!e) return false;
      if (filterCuenta !== 'todas' && e.cuentaId !== filterCuenta) return false;
      if (filterEstado !== 'todos' && e.estado !== filterEstado) return false;
      if (q) {
        const cta = FONDOS_STATE.cuentasBancarias.find((c) => c.id === e.cuentaId);
        const hay = `${e.numero} ${e.beneficiario} ${e.cuit} ${e.concepto} ${cta?.banco || ''}`.toUpperCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });

    if (rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="table-loading-cell">No hay E-Cheqs registrados para los filtros seleccionados.</td></tr>';
      return;
    }

    tbody.innerHTML = rows
      .map((e) => {
        const cta = FONDOS_STATE.cuentasBancarias.find((c) => c.id === e.cuentaId);
        const fEmiParts = String(e.fechaEmision || '').split('-');
        const fEmiAr = fEmiParts.length === 3 ? `${fEmiParts[2]}/${fEmiParts[1]}/${fEmiParts[0]}` : e.fechaEmision || '';
        const fVtoParts = String(e.fechaVencimiento || '').split('-');
        const fVtoAr = fVtoParts.length === 3 ? `${fVtoParts[2]}/${fVtoParts[1]}/${fVtoParts[0]}` : e.fechaVencimiento || '';

        const isDueOrPast = e.estado === 'EMITIDO' && e.fechaVencimiento && e.fechaVencimiento <= todayIso;
        const estadoBadge =
          e.estado === 'DEBITADO'
            ? '<span class="badge badge--green">✅ DEBITADO EN BANCO</span>'
            : e.estado === 'ANULADO'
              ? '<span class="badge" style="background:#fee2e2;color:#991b1b;">✕ ANULADO</span>'
              : isDueOrPast
                ? '<span class="badge badge--gold">⚠️ AL DÍA PARA DEBITAR</span>'
                : '<span class="badge badge--gold">⏳ EMITIDO / EN CIRCULACIÓN</span>';

        return `<tr style="${e.estado === 'ANULADO' ? 'opacity:0.55;' : ''}">
          <td>
            <div class="price-cell-stack">
              <span class="art-code-pill">${escapeHtml(e.numero)}</span>
              <span class="price-neto-val">${escapeHtml(e.modalidad || 'PAGO DIFERIDO (ECHEQ)')}</span>
            </div>
          </td>
          <td>
            <div class="price-cell-stack">
              <strong>${escapeHtml(cta ? cta.banco : e.cuentaId)}</strong>
              <span class="price-neto-val">${escapeHtml(cta ? cta.denominacion : '')}</span>
            </div>
          </td>
          <td>${escapeHtml(fEmiAr)}</td>
          <td>
            <div class="price-cell-stack">
              <strong style="color:${isDueOrPast ? '#d97706' : 'var(--text-primary)'};">${escapeHtml(fVtoAr)}</strong>
              <span class="price-neto-val">${isDueOrPast ? 'Fecha de pago cumplida' : 'Pago diferido'}</span>
            </div>
          </td>
          <td>
            <div class="price-cell-stack">
              <strong>${escapeHtml(e.beneficiario)}</strong>
              <span class="price-neto-val">${e.cuit ? `CUIT ${escapeHtml(e.cuit)}` : ''}</span>
            </div>
          </td>
          <td>${escapeHtml(e.concepto || '—')}</td>
          <td class="num-col"><strong style="font-size:0.95rem;">$ ${formatArs(e.importe || 0)}</strong></td>
          <td style="text-align:center;">${estadoBadge}</td>
          <td style="text-align:center;">
            <div style="display:flex; flex-wrap:wrap; gap:0.3rem; justify-content:center;">
              ${
                e.estado === 'EMITIDO'
                  ? `<button type="button" class="btn-primary btn-sm" style="width:auto;" data-fondos-echeq-debitar="${escapeHtml(e.id)}" title="Registrar el débito bancario del E-Cheq en la Cuenta Corriente del Banco">🏦 Debitar</button>`
                  : ''
              }
              <button type="button" class="btn-secondary btn-sm" data-fondos-echeq-print="${escapeHtml(e.id)}" title="Imprimir Comprobante / Orden de Pago E-Cheq A4">🖨️ A4</button>
              ${
                e.estado === 'EMITIDO'
                  ? `<button type="button" class="btn-secondary btn-sm" style="color:var(--red-danger);" data-fondos-echeq-anular="${escapeHtml(e.id)}" title="Anular E-Cheq">✕</button>`
                  : ''
              }
            </div>
          </td>
        </tr>`;
      })
      .join('');
  }

