        phoneNumberId: document.getElementById('wa-cfg-phone-id')?.value || '',
        mayoristaPhoneDisplay: document.getElementById('wa-cfg-may-phone')?.value || '+54 9 3584 36-7910',
        mayoristaBusinessName: document.getElementById('wa-cfg-may-biz-name')?.value || 'Casa Nueva Mayorista',
        mayoristaPhoneNumberId: document.getElementById('wa-cfg-may-phone-id')?.value || '',
